(2912, 364, '_form', '<div class=\"form-support\">\n  <p>\n    [text* your-name class:input-name placeholder \"Name\"]\n  </p>\n  <p>\n    [tel* your-phone class:input-phone placeholder \"Phone number\"]\n  </p>\n  <p>\n    [email* your-email class:input-email placeholder \"Email\"]\n  </p>\n  <p>\n    [textarea your-message class:input-text placeholder \"Text\"]\n  </p>\n  <p>\n    [submit class:submit-button \"Submit message\"]\n  </p>\n</div>'),
(2913, 364, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:40:\"[_site_title] <duythanh271102@gmail.com>\";s:9:\"recipient\";s:19:\"[_site_admin_email]\";s:4:\"body\";s:259:\"Gửi đến từ: [your-name] [your-email]\nTiêu đề: [your-subject]\n\nNội dung thông điệp:\n[your-message]\n\n-- \nĐây là thông báo cho biết một biểu mẫu liên hệ đã được gửi trên trang web của bạn ([_site_title] [_site_url]).\";s:18:\"additional_headers\";s:22:\"Reply-To: [your-email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
