(5752, 674, '_elementor_data', '[{\"id\":\"3246e86\",\"elType\":\"container\",\"settings\":{\"content_width\":\"full\",\"width\":{\"unit\":\"custom\",\"size\":\"1920px\"},\"width_tablet\":{\"unit\":\"custom\",\"size\":\"\",\"sizes\":[]},\"width_mobile\":{\"unit\":\"custom\",\"size\":488},\"background_background\":\"gradient\",\"background_color\":\"#1E00AE\",\"background_color_b\":\"#0C0048\",\"_flex_size\":\"none\",\"_element_width\":\"initial\",\"_element_width_mobile\":\"initial\"},\"elements\":[{\"id\":\"6947181\",\"elType\":\"container\",\"settings\":{\"boxed_width\":{\"unit\":\"px\",\"size\":1405,\"sizes\":[]},\"margin\":{\"unit\":\"px\",\"top\":\"50\",\"right\":\"0\",\"bottom\":\"0\",\"left\":\"0\",\"isLinked\":false}},\"elements\":[{\"id\":\"7272bed\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Join Our Newsletter\",\"align\":\"center\",\"title_color\":\"#FFFFFF\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Ford Antenna\",\"typography_font_size\":{\"unit\":\"px\",\"size\":30,\"sizes\":[]},\"typography_font_weight\":\"500\",\"typography_line_height\":{\"unit\":\"px\",\"size\":36,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"102058b\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"title\":\"Signup to be the first to hear about exclusive deals, special offers and upcoming collections\",\"align\":\"center\",\"title_color\":\"#FFFFFF\",\"typography_typography\":\"custom\",\"typography_font_family\":\"Ford Antenna\",\"typography_font_size\":{\"unit\":\"px\",\"size\":14,\"sizes\":[]},\"typography_font_weight\":\"300\",\"typography_line_height\":{\"unit\":\"px\",\"size\":24,\"sizes\":[]}},\"elements\":[],\"widgetType\":\"heading\"},{\"id\":\"b320aad\",\"elType\":\"widget\",\"settings\":{\"content_width\":\"full\",\"shortcode\":\"[contact-form-7 id=\\\"efbcd83\\\" title=\\\"send email\\\"]\",\"_flex_align_self\":\"center\",\"custom_css\":\".flex-container {\\r\\n    display: flex;\\r\\n    align-items: center; \\r\\n    gap: 5px;\\r\\n}\\r\\n\\r\\n.flex-container .email-input input[type=\\\"text\\\"] {\\r\\n    width: 650px;\\r\\n    padding: 18px 15px;\\r\\n    border: 1px solid #fff;\\r\\n    border-radius: 8px;\\r\\n    background-color: transparent;\\r\\n    color: #fff;\\r\\n    font-size: 14px;\\r\\n    outline: none;\\r\\n    max-width: 1;\\r\\n}\\r\\n\\r\\n.flex-container .email-input input[type=\\\"text\\\"]::placeholder {\\r\\n    color: #fff; \\r\\n    opacity: 0.7;\\r\\n}\\r\\n\\r\\n.flex-container .submit-button input[type=\\\"submit\\\"] {\\r\\n    padding: 18px 50px;\\r\\n    background-color: #007BFF;\\r\\n    border: none;\\r\\n    border-radius: 8px;\\r\\n    color: white;\\r\\n    font-size: 20px;\\r\\n    cursor: pointer;\\r\\n    display: inline-block;\\r\\n    font-family: Ford Antenna;\\r\\n    font-size: 16px;\\r\\n    font-weight: 500;\\r\\n    line-height: 24px;\\r\\n    \\/* text-align: center; *\\/\\r\\n}\\r\\n\\r\\n.flex-container .submit-button input[type=\\\"submit\\\"]:hover {\\r\\n    background-color: #0056b3; \\r\\n}\\r\\n.wpcf7-spinner {\\r\\n    display: none;\\r\\n}\\r\\n\\r\\n\\r\\n.wpcf7-not-valid-tip {\\r\\n    color: #dc3232; \\r\\n    font-size: 1em;\\r\\n    font-weight: normal;\\r\\n    display: block; \\r\\n    background-color: #e9e9e9;\\r\\n    padding: 10px;\\r\\n    border-radius: 3px;\\r\\n    margin-top: 5px;\\r\\n    position: relative;\\r\\n}\\r\\n.wpcf7-not-valid-tip::before {\\r\\n    content: \'\';\\r\\n    position: absolute;\\r\\n    top: -10px; \\r\\n    left: 10px;\\r\\n    border-width: 10px; \\r\\n    border-style: solid;\\r\\n    border-color: transparent transparent #e9e9e9 transparent;\\r\\n}\\r\\n\\r\\n.wpcf7-not-valid-tip::after {\\r\\n    content: \'\';\\r\\n    position: absolute;\\r\\n    top: -8px; \\r\\n    left: 10px; \\r\\n    border-width: 8px; \\r\\n    border-style: solid;\\r\\n    border-color: transparent transparent #dc3232 transparent;\\r\\n}\\r\\n\\r\\n.