(2677, 'PIP PNSMV059 Nickel and Nickel Alloy Other Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '', 5, '2407160916068', '', '', 'This Practice provides the mechanical design, fabrication, examination, inspection, and documentation requirements for pressure vessel process trays, tower structured packing, tower random packing, distributors, and related components welded to the pressure boundary.', '', 300.00, 0.00, '', '', '2024-07-16 21:31:19', '1970-01-01 00:00:00', 0, 0, 0, 0, 0, 0),
(2678, 'PIP PNSMV058 Nickel and Nickel Alloy Plug Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '', 14, '2407160916069', '', '', 'This Practice provides procedures for installing ceramic fiber refractory linings in fired heaters and other process equipment. Installation includes steel surface preparation and coating, ceramic fiber installation, and repair of ceramic fiber linings. Ceramic fiber refractories in this Practice include: a. Alkaline earth silicate fiber, b. Refractory ceramic fiber, and c. Polycrystalline wool. This Practice does not include installation procedures for mineral wool, fiberglass, or other non-refractory fiber insulation materials.', '', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '1970-01-01 00:00:00', 0, 0, 0, 0, 0, 0);
