(2679, 'PIP PNSMV054 Nickel and Nickel Alloy Globe Valve Descriptions', 'Process Industry Practices', '', '', '3/1/2024 12:00:00 AM', '', '', 30, '2407160916070', '', '', 'This Practice describes guidelines for selecting non-lubricated flexible couplings for general purpose applications for most types of rotating equipment. General purpose coupling applications include loads with steady, non-fluctuating torque characteristics within the power and speed ranges defined in this Practice.', '', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '1970-01-01 00:00:00', 0, 0, 0, 0, 0, 0),
(2691, 'PIP PN01SA0S01 Piping Material Specification 1SA0S01 Class 150, 304/304L Stainless Steel, Socket Weld, C.A.- None, Process', 'Process Industry Practices', '', '', '3/1/2023 12:00:00 AM', '', '', 6, '2407160916082', '', '', 'This Practice provides the detailed purchase descriptions for low and intermediate alloy steel gate valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for low and intermediate alloy steel gate valve tag numbers to applicable PIP Piping Material Specifications.', '', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '1970-01-01 00:00:00', 0, 0, 0, 0, 0, 0),
(2692, 'PIP PLSMV005 Carbon Steel Check Valve Descriptions', 'Process Industry Practices', '', '', '4/1/2023 12:00:00 AM', '', '', 23, '2407160916083', '', '', 'This Practice provides the detailed purchase descriptions for carbon steel globe valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for carbon steel globe valve tag numbers to applicable PIP PMSs.', '', 100.00, 0.00, '', '', '2024-07-16 21:31:19', '1970-01-01 00:00:00', 0, 0, 0, 0, 0, 0),
(2693, 'PIP PLE00012 Piping Examination and Leak Testing Guide - B31.8 Pipelines', 'Process Industry Practices', '', '', '4/1/2024 12:00:00 AM', '', '', 8, '2407160916084', '', '', 'This Practice provides the detailed purchase descriptions for carbon steel gate valve tag numbers included in PIP Piping Material Specifications (PMSs) and used along with PIP PNSM0110 for the procurement of valves. This Practice also provides a cross reference for carbon steel gate valve tag numbers to applicable PIP Piping Material Specifications.', '', 75.00, 0.00, '', '', '2024-07-16 21:31:19', '1970-01-01 00:00:00', 0, 0, 0, 0, 0, 0),
