INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4271, '3A - 3-A Sanitary Standards', '3A - 3-A Sanitary Standards', '3-A SSI develops and maintains a comprehensive inventory of Sanitary Standards and Accepted Practices for dairy and food processing equipment and systems. They are also instrumental in advancing state-of-art hygienic equipment design to meet the rapidly changing needs of the food, beverage and pharmaceutical industries.', '3-A SSI phát triển và duy trì một danh mục toàn diện về Tiêu chuẩn vệ sinh và Thực hành được chấp nhận cho các thiết bị và hệ thống chế biến sữa và thực phẩm. 3-A SSI cũng đóng vai trò quan trọng trong việc thúc đẩy thiết kế thiết bị vệ sinh hiện đại để đáp ứng nhu cầu thay đổi nhanh chóng của ngành thực phẩm, đồ uống và dược phẩm.', NULL, NULL, NULL, NULL, 'publisher/avatar/QJVL9K0E2FH428XLCOEL.jpg', 0),
(4272, '9000 - 9000 Store', '9000 - 9000 Store', 'The 9000 Store, part of the Standards Stores, provides tools and training to assist organizations in achieving and maintaining certification to international standards from ISO, SAE, BSI, and others.', '9000 Store, một phần của Standards Stores, cung cấp các công cụ và đào tạo để hỗ trợ các tổ chức đạt được và duy trì chứng nhận theo các tiêu chuẩn quốc tế từ ISO, SAE, BSI và các tổ chức khác.', 'Deprecated:  htmlspecialchars(): Passing null to parameter #1 ($string) of type string is deprecated in /var/www/vhosts/tecbook.vn/httpdocs/wp-includes/formatting.php on line 4720', '', '', '', 'publisher/avatar/62DYENFZXWMFQFEYH65W.jpg', 0),
(4273, 'AA - Aluminum Association', 'AA - Aluminum Association', 'Aluminum Association standards are used throughout all facets of aluminum commerce, as well as in other organizations\' codes and standards. Aluminum alloy and temper designations, chemical composition limits and registered properties in North America are developed under approval of ANSI Accredited Standards Committee H35 - Aluminum and Aluminum Alloys. Aluminum Association (AA) standards are promulgated by the Technical Committee on Product Standards (TCPS).', 'Tiêu chuẩn của Hiệp hội Nhôm được sử dụng trong mọi khía cạnh của hoạt động thương mại nhôm, cũng như trong các quy định và tiêu chuẩn của các tổ chức khác. Các ký hiệu quy ước về hợp kim và nhiệt độ nhôm, giới hạn thành phần hóa học và các đặc tính đã đăng ký ở Bắc Mỹ được xây dựng theo sự chấp thuận của Ủy ban Tiêu chuẩn được công nhận của ANSI H35 - Nhôm và Hợp kim nhôm. Các tiêu chuẩn của Hiệp hội Nhôm (AA) được ban hành bởi Ủy ban Kỹ thuật về Tiêu chuẩn Sản phẩm (TCPS).', NULL, NULL, NULL, NULL, 'publisher/avatar/JLTXU6EIZ4WMJELAWXUW.jpg', 0),
(4274, 'AAMI - Association for the Advancement of Medical Instrumentation', 'AAMI - Association for the Advancement of Medical Instrumentation', 'AAMI is the primary source of consensus standards, both national and international, for the medical device industry, as well as practical information, support, and guidance for healthcare technology and sterilization professionals.', 'AAMI (Association for the Advancement of Medical Instrumentation) là Hiệp hội Cải tiến Trang thiết bị Y tế. Đây là một tổ chức chuyên về tiêu chuẩn và công nghệ trong lĩnh vực trang thiết bị y tế.\r\n\r\nAAMI được thành lập vào năm 1967 và có trụ sở tại Hoa Kỳ. Nhiệm vụ chính của AAMI là nghiên cứu, phát triển và giới thiệu các tiêu chuẩn, hướng dẫn và gợi ý về trang thiết bị y tế, nhằm đảm bảo tính an toàn, hiệu suất và chất lượng của các thiết bị này.\r\n\r\nAAMI đóng vai trò quan trọng trong việc xác định các tiêu chuẩn kỹ thuật và quy trình cho các trang thiết bị y tế, bao gồm các thiết bị y tế điện tử, máy móc y tế, trang thiết bị y tế di động và hệ thống y tế thông minh. Các tiêu chuẩn AAMI đảm bảo rằng các thiết bị y tế đáp ứng các yêu cầu về an toàn, hiệu suất và tuân thủ quy định trong ngành y tế.\r\n\r\nNgoài ra, AAMI cũng cung cấp các khóa học, tài liệu và sự kiện liên quan đến công nghệ và quy chuẩn trong ngành y tế. Tổ chức này hợp tác với các cơ quan quốc tế và ngành công nghiệp y tế để thúc đẩy sự phát triển và sử dụng công nghệ tiên tiến trong y tế.', 'AAMI (Association for the Advancement of Medical Instrumentation) là Hiệp hội Cải tiến Trang thiết bị Y tế. Đây là một tổ chức chuyên về tiêu chuẩn và công nghệ trong lĩnh vực trang thiết bị y tế.', 'AAMI,ANSI/AAMI', 'AAMI, Hiệp hội Cải tiến Trang thiết bị Y tế , Association for the Advancement of Medical Instrumentation, Trang thiết bị Y tế, Tiêu chuẩn trang thiết bị y tế', NULL, 'publisher/avatar/XBZW4U67ZUAZWBG78JVD.jpg', 0),
(4275, 'AASHTO - American Association of State and Highway Transportation Officials', 'AASHTO - American Association of State Highway and Transportation Officials', 'AASHTO is a leading source of technical information on design, construction and maintenance of highways and other transportation facilities, including aviation, highways, public transit, rail, and water.', 'AASHTO (American Association of State Highway and Transportation Officials) là Hiệp hội Đường cao tốc và Giao thông Hoa Kỳ. Đây là một tổ chức quốc gia tập hợp các quan chức đại diện cho các cơ quan chính phủ tiểu bang và liên bang của Hoa Kỳ, có liên quan đến lĩnh vực đường cao tốc và giao thông.\n\nAASHTO được thành lập vào năm 1914 và có trụ sở tại Washington, D.C. Nhiệm vụ chính của AASHTO là xây dựng và thúc đẩy các tiêu chuẩn, quy định và hướng dẫn về xây dựng, bảo trì và vận hành hệ thống đường cao tốc và giao thông ở Hoa Kỳ.\n\nAASHTO cung cấp một nền tảng để các quan chức chính phủ tiểu bang và liên bang cùng nhau thảo luận, hợp tác và đưa ra các quyết định quan trọng liên quan đến lĩnh vực đường cao tốc và giao thông. Tổ chức này đóng vai trò quan trọng trong việc phát triển và duy trì hệ thống giao thông an toàn, hiệu quả và bền vững ở Hoa Kỳ.\n\nAASHTO cũng đóng góp vào việc nghiên cứu và phát triển các công nghệ, phương pháp và chính sách mới trong lĩnh vực giao thông. Tổ chức này cung cấp các khóa đào tạo và tài liệu hướng dẫn để nâng cao năng lực và kiến thức của các chuyên gia và nhân viên liên quan đến đường cao tốc và giao thông.\n\nAASHTO là một trong những tổ chức quan trọng nhất trong lĩnh vực đường cao tốc và giao thông ở Hoa Kỳ và có vai trò quan trọng trong việc định hình và phát triển hệ thống giao thông quốc gia.', 'AASHTO là Hiệp hội Đường cao tốc và Giao thông Hoa Kỳ, một tổ chức quốc gia tập hợp các quan chức đại diện cho các cơ quan chính phủ tiểu bang và liên bang của Hoa Kỳ, có liên quan đến lĩnh vực đường cao tốc và giao thông.', 'AASHTO,ANSI/AASHTO/AWS,AASHTO/AWS', 'AASHTO, Hiệp hội Đường cao tốc và Giao thông Hoa Kỳ (AASHTO), American Association of State Highway and Transportation Officials (AASHTO), Đường cao tốc và Giao thông, Tiêu chuẩn Đường cao tốc và Giao thông', NULL, 'publisher/avatar/AJPED8MNFAA24ILZYSSY.png', 0),
(4276, 'AATCC - American Association of Textile Chemists and Colorists', 'AATCC - American Association of Textile Chemists and Colorists', 'Founded as the American Association of Textile Chemists and Colorists (AATCC), the Association continues to evolve to meet the needs of those in the ever-changing textile and materials industries. AATCC is internationally recognized for its standard methods of testing fibers and fabrics to measure and evaluate such performance characteristics as colorfastness, appearance, soil release, dimensional change, and water resistance.', 'AATCC (American Association of Textile Chemists and Colorists) là Hiệp hội các Nhà Hóa chất Dệt và Nhuộm Hoa Kỳ. Đây là một tổ chức chuyên về nghiên cứu, phát triển và tiêu chuẩn hóa trong lĩnh vực hóa chất dệt và nhuộm.\n\nAATCC được thành lập vào năm 1921 và có trụ sở tại Hoa Kỳ. Nhiệm vụ chính của AATCC là thúc đẩy sự phát triển và chia sẻ kiến thức về công nghệ, kỹ thuật và quy trình liên quan đến hóa chất dệt và nhuộm.\n\nAATCC đóng vai trò quan trọng trong việc xác định các tiêu chuẩn và phương pháp kiểm tra cho các vật liệu dệt và sản phẩm nhuộm. Các tiêu chuẩn này đảm bảo tính đồng nhất, chất lượng và hiệu suất của các sản phẩm trong ngành công nghiệp dệt và nhuộm.\n\nTổ chức này cung cấp các tài liệu hướng dẫn, phương pháp thử nghiệm và chứng chỉ đào tạo về hóa chất dệt và nhuộm. AATCC cũng tổ chức hội thảo, hội nghị và sự kiện để thúc đẩy sự trao đổi thông tin và kết nối giữa các chuyên gia và nhà nghiên cứu trong ngành công nghiệp dệt và nhuộm.', 'AATCC (American Association of Textile Chemists and Colorists) là Hiệp hội các Nhà Hóa chất Dệt và Nhuộm Hoa Kỳ. Đây là một tổ chức chuyên về nghiên cứu, phát triển và tiêu chuẩn hóa trong lĩnh vực hóa chất dệt và nhuộm.', 'AATCC,ANSI/AATCC', 'AATCC, Hiệp hội các Nhà Hóa chất Dệt và Nhuộm Hoa Kỳ (AATCC), American Association of Textile Chemists and Colorists (AATCC), Hóa chất, Hóa chất Dệt và Nhuộm, Dệt và Nhuộm, Tiêu chuẩn hóa chất Dệt và Nhuộm', '59.020*59.060*59.080.59.100', 'publisher/avatar/ZZ9REBSB2IWA8I73M51V.png', 0),
(4277, 'ABCB - Australian Building Codes Board', 'ABCB - Australian Building Codes Board', 'ABCB - Australian Building Codes Board', 'The Australian Building Codes Board (ABCB) is a standards writing body responsible for the National Construction Code, WaterMark and CodeMark Certification Schemes, and regulatory reform in the construction industry. The ABCB is a joint initiative of the Commonwealth and state and territory governments, together with the building and plumbing industries.', 'Hội đồng Quy chuẩn Xây dựng Úc (ABCB) là cơ quan soạn thảo tiêu chuẩn chịu trách nhiệm về Quy chuẩn Xây dựng Quốc gia, WaterMark và Chương trình Chứng nhận CodeMark, và cải cách quy định trong ngành xây dựng. ABCB là sáng kiến ​​chung của chính quyền Khối thịnh vượng chung, tiểu bang và lãnh thổ, cùng với ngành xây dựng và hệ thống ống nước.', NULL, NULL, NULL, 'publisher/avatar/8S2DYTPLGR4C2XYR3NS0.jpg', 0),
(4278, 'ABMA - American Bearing Manufacturers Association', 'ABMA - American Bearing Manufacturers Association', 'ABMA\'s mission is to provide leadership, advocacy and education with a focus on membership value, industry outreach and issues impacting the global bearing industry. ABMA began in 1917 as an informal committee to aid production of bearings during World War I. The committee consisted of Andrew Company, New Departure, Nice, Federal, Fafnir, SKF, Norma, BCA, Marlin Rockwell and Atlas Ball. In 1933, articles of association were established for Anti-Friction Bearing Manufacturers Association (AFBMA).', 'Sứ mệnh của ABMA là cung cấp sự lãnh đạo, vận động và giáo dục tập trung vào giá trị thành viên, tiếp cận ngành và các vấn đề tác động đến ngành công nghiệp vòng bi toàn cầu. ABMA bắt đầu vào năm 1917 như một ủy ban không chính thức để hỗ trợ sản xuất vòng bi trong Thế chiến thứ nhất. Ủy ban bao gồm Andrew Company, New Departure, Nice, Federal, Fafnir, SKF, Norma, BCA, Marlin Rockwell và Atlas Ball. Năm 1933, các điều khoản hiệp hội được thành lập cho Hiệp hội các nhà sản xuất vòng bi chống ma sát (AFBMA).', NULL, NULL, NULL, NULL, 'publisher/avatar/DFGFM342XQOM7KNQB5V5.png', 0),
(4279, 'ABMA-Boiler - American Boiler Manufacturers Association', 'ABMA-Boiler - American Boiler Manufacturers Association', 'ABMA represents companies worldwide that design and build fuel combustion systems. Members include manufacturers of commercial/institutional, industrial and power-generating boilers, makers of related fuel-burning equipment, users of boiler and boiler-related equipment, and industry suppliers. ABMA leads the bearings industry as an expert resource through the publication and maintenance of a complete set of bearings standards that have been developed either by ABMA technical committee experts or by experts on Technical Committee 4 (TC 4) of the International Organization for Standardization (ISO).\nYou can help to shape tomorrow’s standards for the bearings industry by joining ABMA’s active Technical Committee. The standards are approved by Accredited Standards Committee B3, made up of bearing manufacturers and end users.  ASC B3 is accredited by the American National Standards Institute (ANSI). By signing up to be a part of ASC B3 committee, you and your team will have a seat at the table to network and mold the future of the industry with other bearing experts.', '\"ABMA đại diện cho các công ty trên toàn thế giới thiết kế và xây dựng hệ thống đốt nhiên liệu. Các thành viên bao gồm các nhà sản xuất nồi hơi thương mại/tổ chức, công nghiệp và phát điện, các nhà sản xuất thiết bị đốt nhiên liệu liên quan, người sử dụng nồi hơi và thiết bị liên quan đến nồi hơi và các nhà cung cấp trong ngành. ABMA dẫn đầu ngành công nghiệp vòng bi với tư cách là nguồn lực chuyên gia thông qua việc xuất bản và duy trì một bộ tiêu chuẩn vòng bi hoàn chỉnh đã được phát triển bởi các chuyên gia của ủy ban kỹ thuật ABMA hoặc bởi các chuyên gia trong Ủy ban kỹ thuật 4 (TC 4) của Tổ chức tiêu chuẩn hóa quốc tế (ISO).\nBạn có thể giúp định hình các tiêu chuẩn của tương lai cho ngành công nghiệp vòng bi bằng cách tham gia Ủy ban kỹ thuật tích cực của ABMA. Các tiêu chuẩn được Ủy ban tiêu chuẩn được công nhận B3, bao gồm các nhà sản xuất vòng bi và người dùng cuối, chấp thuận. ASC B3 được Viện tiêu chuẩn quốc gia Hoa Kỳ (ANSI) công nhận. Bằng cách đăng ký trở thành một phần của ủy ban ASC B3, bạn và nhóm của mình sẽ có một vị trí tại bàn để kết nối và định hình tương lai của ngành với các chuyên gia vòng bi khác.\n\"', 'ABMA dẫn đầu ngành công nghiệp vòng bi với tư cách là nguồn lực chuyên gia thông qua việc xuất bản và duy trì một bộ tiêu chuẩn vòng bi hoàn chỉnh đã được phát triển bởi các chuyên gia của ủy ban kỹ thuật ABMA hoặc các chuyên gia của Ủy ban kỹ thuật 4 (TC 4) của Tổ chức tiêu chuẩn hóa quốc tế (ISO).', NULL, NULL, NULL, 'publisher/avatar/3YDZYYEL60Z9EN4REIT3.png', 0),
(4280, 'ACC - American Chemistry CouncilThe American Chemistry Council', 'ACC - American Chemistry CouncilThe American Chemistry Council', 'America\'s oldest trade association of its kind, representing companies engaged in the business of chemistry-an innovative, $760 billion enterprise that is helping solve the biggest challenges facing our nation and the world. The American Chemistry Council (ACC) represents more than 190 companies engaged in the business of chemistry—an innovative, economic growth engine that is helping to solve the biggest challenges facing our country and the world. Our members are the leading companies engaged in all aspects of the business of chemistry, from the largest corporations to the smallest, and everything in between. They are the people and companies creating the groundbreaking products that are improving the world all around us by making it healthier, safer, more sustainable and more productive. \nMission:\nThe American Chemistry Council’s mission is to advocate for the people, policy, and products of chemistry that make the United States the global leader in innovation and manufacturing.\n\nTo achieve this, we:\n\nChampion science-based policy solutions across all levels of government;\nDrive continuous performance improvement to protect employees and communities through Responsible Care®;\nFoster the development of sustainability practices throughout ACC member companies; and\nCommunicate authentically with communities about challenges and solutions for a safer, healthier and more sustainable way of life.\nVision:\nOur vision is a world made better by chemistry, where people live happier, healthier, and more prosperous lives, safely and sustainably – for generations to come.\n\nWe believe that if America is to remain a country that innovates and competes globally, it must do so with a thriving American chemical industry. Protecting that unique role and promoting our industry’s interests drives everything we do.\n\nOur member-driven philosophy makes ACC the leading, collective voice of the business of chemistry, driving a pro-growth, common sense and science-based public policy agenda that brings forth innovation, creates jobs and economic expansion and enhances public and environmental health and safety.\n\nInitiatives & Programs\nEvery year, the chemistry industry invests tens of millions of dollars to ensure that the products making modern living possible are safe for you, our communities and the environment. In addition to research initiatives, ACC programs focus on anticipating and preventing accidents, as well as educating the public about how to use our products safely.\n\nChemistry makes it possible to satisfy a growing world population. Our products protect our food supply, air and water, ensure safe living conditions and provide access to efficient and affordable energy sources and lifesaving medical treatments in communities around the globe.\n\nTo enable these ongoing innovations, we advocate for public policies that support the creation of groundbreaking products to improve lives, protect our environment and enhance the economic vitality of communities.', '\"Hiệp hội thương mại lâu đời nhất của Hoa Kỳ, đại diện cho các công ty tham gia vào lĩnh vực hóa học - một doanh nghiệp sáng tạo trị giá 760 tỷ đô la đang giúp giải quyết những thách thức lớn nhất mà quốc gia chúng ta và thế giới đang phải đối mặt. Hội đồng Hóa học Hoa Kỳ (ACC) đại diện cho hơn 190 công ty tham gia vào lĩnh vực hóa học - một động lực tăng trưởng kinh tế sáng tạo đang giúp giải quyết những thách thức lớn nhất mà quốc gia chúng ta và thế giới đang phải đối mặt. Các thành viên của chúng tôi là những công ty hàng đầu tham gia vào mọi khía cạnh của lĩnh vực hóa học, từ các tập đoàn lớn nhất đến nhỏ nhất và mọi thứ ở giữa. Họ là những con người và công ty tạo ra các sản phẩm đột phá đang cải thiện thế giới xung quanh chúng ta bằng cách làm cho thế giới trở nên lành mạnh hơn, an toàn hơn, bền vững hơn và hiệu quả hơn.\nSứ mệnh:\nSứ mệnh của Hội đồng Hóa học Hoa Kỳ là ủng hộ con người, chính sách và các sản phẩm hóa học giúp Hoa Kỳ trở thành quốc gia dẫn đầu toàn cầu về đổi mới và sản xuất.\n\nĐể đạt được điều này, chúng tôi:\n\nĐưa ra các giải pháp chính sách dựa trên khoa học ở mọi cấp chính quyền;\nThúc đẩy cải tiến hiệu suất liên tục để bảo vệ nhân viên và cộng đồng thông qua Responsible Care®;\nThúc đẩy sự phát triển của các hoạt động thực hành bền vững trên khắp các công ty thành viên của ACC; và\nTrao đổi chân thực với cộng đồng về những thách thức và giải pháp cho một lối sống an toàn hơn, lành mạnh hơn và bền vững hơn.\nTầm nhìn:\nTầm nhìn của chúng tôi là một thế giới tốt đẹp hơn nhờ hóa học, nơi mọi người sống hạnh phúc hơn, khỏe mạnh hơn và thịnh vượng hơn, an toàn và bền vững - cho các thế hệ mai sau.\n\nChúng tôi tin rằng nếu Hoa Kỳ muốn tiếp tục là một quốc gia đổi mới và cạnh tranh trên toàn cầu, thì phải làm như vậy với một ngành công nghiệp hóa chất Hoa Kỳ đang phát triển mạnh. Bảo vệ vai trò độc đáo đó và thúc đẩy lợi ích của ngành công nghiệp của chúng tôi thúc đẩy mọi thứ chúng tôi làm.\n\nTriết lý do thành viên thúc đẩy của chúng tôi biến ACC trở thành tiếng nói tập thể hàng đầu của ngành hóa học, thúc đẩy chương trình nghị sự chính sách công dựa trên khoa học, có ý nghĩa chung và thúc đẩy tăng trưởng, mang lại sự đổi mới, tạo việc làm và mở rộng kinh tế, đồng thời tăng cường sức khỏe và an toàn của công chúng và môi trường.\n\nCác sáng kiến ​​& Chương trình\nHàng năm, ngành hóa học đầu tư hàng chục triệu đô la để đảm bảo rằng các sản phẩm giúp cuộc sống hiện đại trở nên an toàn cho bạn, cộng đồng của chúng tôi và môi trường. Ngoài các sáng kiến ​​nghiên cứu, các chương trình của ACC tập trung vào việc dự đoán và ngăn ngừa tai nạn, cũng như giáo dục công chúng về cách sử dụng sản phẩm của chúng tôi một cách an toàn.\n\nHóa học giúp thỏa mãn nhu cầu của dân số thế giới đang ngày càng tăng. Các sản phẩm của chúng tôi bảo vệ nguồn cung cấp thực phẩm, không khí và nước, đảm bảo điều kiện sống an toàn và cung cấp quyền tiếp cận các nguồn năng lượng hiệu quả và giá cả phải chăng cùng các phương pháp điều trị y tế cứu sống trong các cộng đồng trên toàn cầu.\n\nĐể tạo điều kiện cho những đổi mới liên tục này, chúng tôi ủng hộ các chính sách công hỗ trợ việc tạo ra các sản phẩm mang tính đột phá nhằm cải thiện cuộc sống, bảo vệ môi trường và tăng cường sức sống kinh tế của cộng đồng.\n\"', 'Hội đồng Hóa học Hoa Kỳ (ACC) đại diện cho hơn 190 công ty tham gia vào lĩnh vực hóa học - một động lực tăng trưởng kinh tế sáng tạo đang giúp giải quyết những thách thức lớn nhất mà quốc gia chúng ta và thế giới đang phải đối mặt.', NULL, NULL, NULL, 'publisher/avatar/GB4AMJEMQL87D64RE91V.jpg', 0),
(4281, 'ACGIH - American Conference of Governmental Industrial Hygienists', 'ACGIH - American Conference of Governmental Industrial Hygienists', 'ACGIH is a 501(c)(3) charitable scientific organization that advances occupational and environmental health. Examples of this include our annual editions of the TLVs and BEIs book and work practice guides in ACGIH’s Signature Publications.\r\n\r\nACGIH’s key mission is – To Protect Workers Around the World. ACGIH is fighting for you! We are here to protect you! ACGIH is growing stronger and passionately fighting for your health and safety as you face those hidden dangers in your workplace environments.\r\n\r\nACGIH works continuously to enhance the occupational, environmental, health, and safety fields. Our research provides you with the science and data you need to ensure the safety of your employees and community. Subscription support is crucial to the continued research and development of occupational science.\r\n \r\nFor over 80 years, ACGIH has been respected for its dedication to the industrial hygiene and occupational and environmental health and safety communities. We have grown and expanded without losing sight of its original goal - to encourage the interchange of experience among industrial hygiene workers and to collect and make accessible such information and data as might be of aid to them in the proper fulfillment of their duties.', 'ACGIH là tổ chức khoa học từ thiện 501(c)(3) thúc đẩy sức khỏe nghề nghiệp và môi trường. Ví dụ về điều này bao gồm các ấn bản hàng năm của chúng tôi về sách TLV và BEI và hướng dẫn thực hành công việc trong Ấn phẩm đặc biệt của ACGIH.\r\n\r\nSứ mệnh chính của ACGIH là – Bảo vệ người lao động trên toàn thế giới. ACGIH đang chiến đấu vì bạn! Chúng tôi ở đây để bảo vệ bạn! ACGIH đang ngày càng mạnh mẽ hơn và đấu tranh hết mình vì sức khỏe và sự an toàn của bạn khi bạn phải đối mặt với những mối nguy hiểm tiềm ẩn trong môi trường làm việc của mình.\r\n\r\nACGIH liên tục làm việc để nâng cao các lĩnh vực nghề nghiệp, môi trường, sức khỏe và an toàn. Nghiên cứu của chúng tôi cung cấp cho bạn khoa học và dữ liệu bạn cần để đảm bảo an toàn cho nhân viên và cộng đồng của bạn. Hỗ trợ đăng ký là rất quan trọng đối với việc tiếp tục nghiên cứu và phát triển khoa học nghề nghiệp.\r\n\r\nTrong hơn 80 năm qua, ACGIH đã được tôn trọng vì sự cống hiến của mình cho cộng đồng vệ sinh công nghiệp và sức khỏe và an toàn nghề nghiệp và môi trường. Chúng tôi đã phát triển và mở rộng mà không đánh mất mục tiêu ban đầu - khuyến khích trao đổi kinh nghiệm giữa những người lao động vệ sinh công nghiệp và thu thập cũng như cung cấp thông tin và dữ liệu có thể giúp họ hoàn thành tốt nhiệm vụ của mình.', 'ACGIH là tổ chức khoa học từ thiện 501(c)(3) thúc đẩy sức khỏe nghề nghiệp và môi trường. Ví dụ về điều này bao gồm các ấn bản hàng năm của chúng tôi về sách TLV và BEI và hướng dẫn thực hành công việc trong Ấn phẩm đặc biệt của ACGIH.', '', '', '', 'publisher/avatar/2LQ6A4PI8QFW2NWVD1JD.jpg', 1),
(4282, 'ACI - American Concrete Institute', 'ACI - American Concrete Institute', 'The American Concrete Institute is a leading global authority for the development, dissemination, and adoption of its consensus-based standards, technical resources, and educational, training, & certification programs. Founded in 1904, ACI is headquartered in Farmington Hills, Michigan, USA, with a regional office in Dubai, UAE, and resource centers in Southern California and Chicago/Midwest. ACI has over 94 chapters, 244 student chapters, and 35,000 members spanning over 120 countries.\nACI functions as a technical and educational society for sharing innovative ideas and promoting superior concrete technology. The Institute publishes more than 400 technical standards, reports and manuals on testing, inspection, cracking and failure, building code requirements, and related topics.\nThe history of any organization is a reflection of the ideals and activities of individuals or organized groups within it, and their influence on the accomplishment of the established objective or its revision to meet changing conditions. So it has been with ACI and its antecedent, the National Association of Cement Users. This brief account attempts to point out significant developments that have guided the Institute to its present position. Space does not permit naming all the \"greats\" who have contributed so generously of time and effort to ACI work and progress of the industry.\n\nThe history of ACI is, of course, closely tied to the history of developments in concrete technology. This development is recorded as it occurred in the pages of the Institute\'s publications.\nStandards\nACI technical committees disseminate information through consensus-based publications within the scope of a committee’s mission.\nStandardization is the most rigorous consensus process used by ACI. ACI standards are written in mandatory language. There are typically two types of ACI Standards – design codes and construction specifications.\nDesign Codes\nDesign codes are directed to the design professional, not the construction team. ACI design codes include, code requirements, code cases, acceptance criteria, and design specifications.\nConstruction Specifications\nACI construction specifications are written to direct the producers, testing agencies, and construction team, not the design professional. ACI specifications include both construction and material specifications.\nHandbooks and Manuals\nHandbooks and manuals are ACI documents that provide tools and guidance to the practitioner on applying design, construction, and inspection standards.\nHandbooks typically contain charts, tables, and examples to facilitate design of concrete structures, formwork, and reinforcement detailing. Examples are provided to illustrate the steps in designing or detailing. Manuals often include compendiums of relevant ACI documents referenced by ACI standards, which engineers, contractors, and/or inspectors find valuable to have readily accessible.', 'Viện Bê tông Hoa Kỳ là cơ quan toàn cầu hàng đầu về phát triển, phổ biến và áp dụng các tiêu chuẩn dựa trên sự đồng thuận, các nguồn lực kỹ thuật và các chương trình giáo dục, đào tạo và chứng nhận. Được thành lập vào năm 1904, ACI có trụ sở chính tại Farmington Hills, Michigan, Hoa Kỳ, với một văn phòng khu vực tại Dubai, UAE và các trung tâm nguồn lực tại Nam California và Chicago/Midwest. ACI có hơn 94 chi hội, 244 chi hội sinh viên và 35.000 thành viên trải dài trên 120 quốc gia.\nACI hoạt động như một hiệp hội kỹ thuật và giáo dục để chia sẻ những ý tưởng sáng tạo và thúc đẩy công nghệ bê tông vượt trội. Viện xuất bản hơn 400 tiêu chuẩn kỹ thuật, báo cáo và sổ tay hướng dẫn về thử nghiệm, kiểm tra, nứt và hỏng, yêu cầu về quy định xây dựng và các chủ đề liên quan.\nLịch sử của bất kỳ tổ chức nào đều phản ánh lý tưởng và hoạt động của các cá nhân hoặc nhóm có tổ chức trong tổ chức đó, cũng như ảnh hưởng của họ đối với việc hoàn thành mục tiêu đã đề ra hoặc sửa đổi mục tiêu để đáp ứng các điều kiện thay đổi. ACI và tổ chức tiền thân của nó, Hiệp hội Người sử dụng Xi măng Quốc gia cũng vậy. Bản tóm tắt này cố gắng chỉ ra những phát triển quan trọng đã đưa Viện đến vị thế hiện tại. Không đủ chỗ để nêu tên tất cả những \"người vĩ đại\" đã đóng góp rất nhiều thời gian và công sức cho công việc và sự tiến bộ của ngành ACI.\n\nLịch sử của ACI tất nhiên gắn liền chặt chẽ với lịch sử phát triển của công nghệ bê tông. Sự phát triển này được ghi lại khi nó diễn ra trên các trang ấn phẩm của Viện.\nTiêu chuẩn\nCác ủy ban kỹ thuật của ACI phổ biến thông tin thông qua các ấn phẩm dựa trên sự đồng thuận trong phạm vi nhiệm vụ của ủy ban.\nChuẩn hóa là quy trình đồng thuận nghiêm ngặt nhất mà ACI sử dụng. Các tiêu chuẩn của ACI được viết bằng ngôn ngữ bắt buộc. Thông thường có hai loại Tiêu chuẩn ACI – quy tắc thiết kế và thông số kỹ thuật xây dựng.\nQuy tắc thiết kế\nQuy tắc thiết kế hướng đến chuyên gia thiết kế, không phải nhóm xây dựng. Quy tắc thiết kế của ACI bao gồm các yêu cầu về quy tắc, trường hợp quy tắc, tiêu chí chấp nhận và thông số kỹ thuật thiết kế.\nThông số kỹ thuật xây dựng\nThông số kỹ thuật xây dựng của ACI được viết để hướng đến nhà sản xuất, cơ quan thử nghiệm và nhóm xây dựng, không phải chuyên gia thiết kế. Thông số kỹ thuật của ACI bao gồm cả thông số kỹ thuật về xây dựng và vật liệu.\nSổ tay và Hướng dẫn\nSổ tay và hướng dẫn là các tài liệu ACI cung cấp các công cụ và hướng dẫn cho người hành nghề về việc áp dụng các tiêu chuẩn thiết kế, xây dựng và kiểm tra.\nSổ tay thường chứa các biểu đồ, bảng và ví dụ để tạo điều kiện thuận lợi cho việc thiết kế các kết cấu bê tông, ván khuôn và chi tiết cốt thép. Các ví dụ được cung cấp để minh họa các bước trong thiết kế hoặc chi tiết. Sổ tay thường bao gồm các tập hợp các tài liệu ACI có liên quan được tham chiếu theo các tiêu chuẩn ACI, mà các kỹ sư, nhà thầu và/hoặc thanh tra viên thấy có giá trị khi dễ dàng truy cập.', 'Viện Bê tông Hoa Kỳ là cơ quan toàn cầu hàng đầu về phát triển, phổ biến và áp dụng các tiêu chuẩn dựa trên sự đồng thuận, các nguồn lực kỹ thuật và các chương trình giáo dục, đào tạo và chứng nhận.', NULL, NULL, NULL, 'publisher/avatar/3O3HL9X4ASL03OWPL9VB.jpg', 0),
(4283, 'ADA - American Dental Association', 'ADA - American Dental Association', 'The ADA’s mission is to help dentists succeed and support the advancement of the health of the public. We are guided by our core values, which include integrity, excellence, and a dedication to bring you evidence-based insights that empower you to provide quality oral care for all patients.\nWe advocate for public health by focusing on crucial issues such as access to care, the rules and regulations that surround the practice of dentistry and much more.\nThe ADA is your source for the latest research on oral health, along with helpful practice guidelines, data on industry trends and a host of practical programs that support your personal health and success.\nFounded in 1859, the American Dental Association is the oldest and largest national dental society in the world. Since then, the ADA has grown to become the leading source of oral health related information for dentists and their patients.\nTogether with our 159,000+ members, the ADA has been driving dentistry forward for more than 160 years.', 'Sứ mệnh của ADA là giúp các nha sĩ thành công và hỗ trợ sự tiến bộ của sức khỏe cộng đồng. Chúng tôi được hướng dẫn bởi các giá trị cốt lõi của mình, bao gồm tính chính trực, sự xuất sắc và sự tận tâm mang đến cho bạn những hiểu biết dựa trên bằng chứng giúp bạn có thể cung cấp dịch vụ chăm sóc răng miệng chất lượng cho tất cả bệnh nhân.\nChúng tôi ủng hộ sức khỏe cộng đồng bằng cách tập trung vào các vấn đề quan trọng như khả năng tiếp cận dịch vụ chăm sóc, các quy tắc và quy định liên quan đến hoạt động nha khoa và nhiều vấn đề khác.\nADA là nguồn thông tin nghiên cứu mới nhất về sức khỏe răng miệng, cùng với các hướng dẫn thực hành hữu ích, dữ liệu về xu hướng ngành và nhiều chương trình thực tế hỗ trợ sức khỏe và thành công cá nhân của bạn.\nĐược thành lập vào năm 1859, Hiệp hội Nha khoa Hoa Kỳ là hiệp hội nha khoa quốc gia lâu đời nhất và lớn nhất trên thế giới. Kể từ đó, ADA đã phát triển trở thành nguồn thông tin liên quan đến sức khỏe răng miệng hàng đầu cho các nha sĩ và bệnh nhân của họ.\nCùng với hơn 159.000 thành viên, ADA đã thúc đẩy ngành nha khoa phát triển trong hơn 160 năm.', 'Sứ mệnh của ADA là giúp các nha sĩ thành công và hỗ trợ sự tiến bộ của sức khỏe cộng đồng. Chúng tôi được hướng dẫn bởi các giá trị cốt lõi của mình, bao gồm tính chính trực, sự xuất sắc và sự tận tâm mang đến cho bạn những hiểu biết dựa trên bằng chứng giúp bạn có thể cung cấp dịch vụ chăm sóc răng miệng chất lượng cho tất cả bệnh nhân.', NULL, NULL, NULL, 'publisher/avatar/UEHATA1D82BGV9FSY9WU.jpg', 0),
(4284, 'ADS - SAE ITC TSC Aerospace Standards (Formerly ADS Group Limited)', 'ADS - SAE ITC TSC Aerospace Standards (Formerly ADS Group Limited)', 'SAE ITC TSC Aerospace Standards originate from the technical standards published by the UK\'s SBAC and ADS, SBAC\'s successor organization. They form a collection of some 4500 aerospace standards covering airframe and engine standard parts (AS, AGS & ESC), reference sheets (RS) and technical specifications (TS). The documents also complement the aerospace standards published by SAE International.', 'Tiêu chuẩn hàng không vũ trụ SAE ITC TSC có nguồn gốc từ các tiêu chuẩn kỹ thuật do SBAC và ADS của Anh, tổ chức kế nhiệm của SBAC, công bố. Chúng tạo thành một bộ sưu tập gồm khoảng 4500 tiêu chuẩn hàng không vũ trụ bao gồm các bộ phận tiêu chuẩn của khung máy bay và động cơ (AS, AGS & ESC), các bảng tham chiếu (RS) và thông số kỹ thuật (TS). Các tài liệu này cũng bổ sung cho các tiêu chuẩn hàng không vũ trụ do SAE International công bố.', 'Tiêu chuẩn hàng không vũ trụ SAE ITC TSC có nguồn gốc từ các tiêu chuẩn kỹ thuật do SBAC và ADS của Anh, tổ chức kế nhiệm của SBAC, công bố. Chúng tạo thành một bộ sưu tập gồm khoảng 4500 tiêu chuẩn hàng không vũ trụ bao gồm các bộ phận tiêu chuẩn của khung máy bay và động cơ (AS, AGS & ESC), các bảng tham chiếu (RS) và thông số kỹ thuật (TS). Các tài liệu này cũng bổ sung cho các tiêu chuẩn hàng không vũ trụ do SAE International công bố.', NULL, NULL, NULL, 'publisher/avatar/SQSU3PHCEKKF7BERCY07.jpg', 0),
(4285, 'AEIC - Association of Edison Illuminating Companies', 'AEIC - Association of Edison Illuminating Companies', 'AEIC is the electric utility industry’s longest-serving and preeminent association where leading operations experts work together to share knowledge and provide guidance to the industry essential to achieving operational excellence and grid modernization. Founded in 1885 by Thomas Edison, AEIC’s members rise to challenges and accelerate opportunities in all aspects of generation, transmission, distribution and storage of electric power for the benefit of its members, the industry at large and consumers, worldwide.\nFounded by Thomas Edison and his associates in 1885, AEIC is one of the oldest organizations in the electric energy industry. Founded to guide the growth of the proliferating Edison illuminating companies, the Association originally existed as mainly a company organization but, quickly grew to represent the entire electric power industry. The organizers of the Association determined to hold annual meetings at which company representatives would engage in an “interchange of opinions.” At the first Annual Meeting in 1885, it was announced that the Association sought, “through the interchange of views and experiences, and by comparison and consultation, [to make] the knowledge of one the knowledge of all, to the advantage of their common interests.”\n\nThe commitment to the exchange of ideas formed the core of the formal statement of purposes: the Association would continue to “elicit all of the information” needed for advancing the “mutual interests” of the member companies. This primary statement of purpose has guided the Association ever since.\n\nThrough this collaborative thinking, AEIC delivered the distilled wisdom of the industry on technical systems, financing (including accounting and rate-making), service, and marketing. Early discussions at annual meetings focused on the kinds of technical concerns that would later engage the AEIC. Members talked of street lighting, the relative merits of contract and meter systems for determining usage, engines and boilers, lamp breakage, fuels, and central station staff responsibilities.\n\nMember companies sent their chief executive officers and senior staff from engineering and operations to increase the benefits of membership to the company. The geographical representation of member companies pointed to the emergence of a national AEIC. Meeting minutes contained the collective thought of the industry’s leaders. In them were recorded the annual reports and discussions describing the state of the technical art and projecting future developments. “Printed but not published,” the title page of each volume proclaimed, since membership was required to receive the documents. The tradition of privacy was, as an AEIC president declared in the 1950s, a “sacred heritage.” At the dawn of the 20th Century, member companies were moving beyond supplying electricity for “lighting and incidental power” to providing power for surface and elevated railroads, interurban transportation lines, electrochemical processes, and heating. In response, the appointment of new committees was recommended to guide this expansive phase which the industry had entered, including a Committee on Electric Vehicles.\n\nDuring the early 1900’s, a string of specialized committees was in place. Rapid developments in apparatus, marketing practice, and operating problems led to the evolution of an Association committee structure to deal with them. This demonstrated the Association’s growing commitment both to aid the flow of technical information to the industry and to add to the store of technical knowledge.\n\nBy 1935, the AEIC committee system reflected a mature industry prepared, on the one hand, to capitalize on all possibilities for expanding production and extending distribution and, on the other hand, to respond to new market conditions and rising customer expectations. The Association’s program would, over the long haul, include power generation, power distribution, electric power apparatus, meters and service, and the twin areas of load-building and load research. By the time of the AEIC’s fiftieth anniversary, most of the modern committee structure had fallen into place and AEIC had taken full responsibility for coordinating load studies within the industry. Other means by which the AEIC transmitted information were the papers by engineers and managers on technical subjects at the annual meeting.\n\nToday, AEIC continues to hold a unique and important position in the electric industry as the only place where senior leaders and operational experts come together to share knowledge, collaborate, and provide guidance to the industry.\n\nMembers respond to challenges, accelerate change, and achieve excellence in all aspects of generation, transmission, distribution, and storage of electric power for the benefit of all members, the industry at large, and consumers.\n\nAEIC’s member companies represent a “who’s who” of utility industry leaders. Our members include large utilities, state and regional cooperatives, and municipalities. Through our Annual Achievement Awards program, we recognize and promote members who have clearly demonstrated significant contributions to advancing the operations of the electric energy industry. More than 500 employees from our member companies are actively and enthusiastically engaged in committee work focused on addressing key operational issues and challenges in the industry. These committees produce technical specifications, industry standards, best practices, and useful guidance that benefit the entire industry. In addition, AEIC offers virtual and in-person meetings, networking and collaboration opportunities throughout the year, including our association-wide Annual Meeting. Our members often refer to AEIC as a respected and trusted ‘safe harbor’ for open, honest dialogue and sharing of ideas, problem-solving and pragmatic guidance.\n\nAs the industry’s longest-serving and preeminent association, we’ve been leading the way since 1885.', 'AEIC là hiệp hội lâu đời nhất và nổi trội nhất trong ngành điện, nơi các chuyên gia vận hành hàng đầu cùng nhau chia sẻ kiến ​​thức và hướng dẫn ngành công nghiệp thiết yếu để đạt được sự xuất sắc trong vận hành và hiện đại hóa lưới điện. Được thành lập vào năm 1885 bởi Thomas Edison, các thành viên của AEIC vượt qua thử thách và đẩy nhanh cơ hội trong mọi khía cạnh của việc sản xuất, truyền tải, phân phối và lưu trữ điện năng vì lợi ích của các thành viên, ngành công nghiệp nói chung và người tiêu dùng trên toàn thế giới.\nĐược thành lập bởi Thomas Edison và các cộng sự vào năm 1885, AEIC là một trong những tổ chức lâu đời nhất trong ngành năng lượng điện. Được thành lập để hướng dẫn sự phát triển của các công ty chiếu sáng Edison đang phát triển mạnh mẽ, Hiệp hội ban đầu chủ yếu tồn tại như một tổ chức công ty nhưng nhanh chóng phát triển để đại diện cho toàn bộ ngành điện. Những người tổ chức Hiệp hội quyết định tổ chức các cuộc họp thường niên, tại đó các đại diện công ty sẽ tham gia vào \"trao đổi ý kiến\". Tại Cuộc họp thường niên đầu tiên vào năm 1885, Hiệp hội đã thông báo rằng Hiệp hội tìm cách \"thông qua việc trao đổi quan điểm và kinh nghiệm, và thông qua so sánh và tham vấn, [để biến] kiến ​​thức của một người thành kiến ​​thức của tất cả mọi người, vì lợi ích chung của họ\".\n\nCam kết trao đổi ý tưởng đã hình thành nên cốt lõi của tuyên bố chính thức về mục đích: Hiệp hội sẽ tiếp tục \"thu thập tất cả thông tin\" cần thiết để thúc đẩy \"lợi ích chung\" của các công ty thành viên. Tuyên bố mục đích chính này đã định hướng cho Hiệp hội kể từ đó.\n\nThông qua tư duy hợp tác này, AEIC đã truyền tải trí tuệ cô đọng của ngành về các hệ thống kỹ thuật, tài chính (bao gồm kế toán và định giá), dịch vụ và tiếp thị. Các cuộc thảo luận ban đầu tại các cuộc họp thường niên tập trung vào các loại mối quan tâm kỹ thuật mà sau này sẽ thu hút AEIC. Các thành viên đã nói về chiếu sáng đường phố, giá trị tương đối của hệ thống hợp đồng và đồng hồ đo để xác định mức sử dụng, động cơ và nồi hơi, đèn bị hỏng, nhiên liệu và trách nhiệm của nhân viên trạm trung tâm.\n\nCác công ty thành viên đã cử giám đốc điều hành và nhân viên cấp cao từ bộ phận kỹ thuật và vận hành đến để tăng lợi ích của tư cách thành viên cho công ty. Sự đại diện về mặt địa lý của các công ty thành viên chỉ ra sự xuất hiện của một AEIC quốc gia. Biên bản cuộc họp chứa đựng suy nghĩ chung của các nhà lãnh đạo trong ngành. Trong đó ghi lại các báo cáo và thảo luận hàng năm mô tả tình trạng nghệ thuật kỹ thuật và dự báo các phát triển trong tương lai. “Đã in nhưng không được xuất bản”, trang tiêu đề của mỗi tập sách tuyên bố, vì tư cách thành viên là bắt buộc để nhận được các tài liệu. Truyền thống bảo mật, như một chủ tịch AEIC đã tuyên bố vào những năm 1950, là một “di sản thiêng liêng”. Vào đầu thế kỷ 20, các công ty thành viên đã chuyển từ cung cấp điện cho “chiếu sáng và điện dự phòng” sang cung cấp điện cho đường sắt trên mặt đất và trên cao, tuyến giao thông liên đô thị, quy trình điện hóa và hệ thống sưởi ấm. Để ứng phó, việc bổ nhiệm các ủy ban mới đã được khuyến nghị để hướng dẫn giai đoạn mở rộng này mà ngành đã bước vào, bao gồm cả Ủy ban về Xe điện.\n\nVào đầu những năm 1900, một loạt các ủy ban chuyên ngành đã được thành lập. Sự phát triển nhanh chóng về thiết bị, hoạt động tiếp thị và các vấn đề vận hành đã dẫn đến sự phát triển của một cơ cấu ủy ban của Hiệp hội để giải quyết các vấn đề này. Điều này chứng minh cam kết ngày càng tăng của Hiệp hội trong việc hỗ trợ luồng thông tin kỹ thuật cho ngành và bổ sung vào kho kiến ​​thức kỹ thuật.\n\nĐến năm 1935, hệ thống ủy ban AEIC phản ánh một ngành công nghiệp trưởng thành, một mặt, sẵn sàng tận dụng mọi khả năng để mở rộng sản xuất và phân phối, mặt khác, đáp ứng các điều kiện thị trường mới và kỳ vọng ngày càng tăng của khách hàng. Về lâu dài, chương trình của Hiệp hội sẽ bao gồm phát điện, phân phối điện, thiết bị điện, đồng hồ đo và dịch vụ, và hai lĩnh vực song song là xây dựng phụ tải và nghiên cứu phụ tải. Đến thời điểm kỷ niệm 50 năm thành lập AEIC, hầu hết cấu trúc ủy ban hiện đại đã đi vào hoạt động và AEIC đã chịu toàn bộ trách nhiệm điều phối các nghiên cứu phụ tải trong ngành. Các phương tiện khác mà AEIC truyền tải thông tin là các bài báo của các kỹ sư và nhà quản lý về các chủ đề kỹ thuật tại cuộc họp thường niên.\n\nNgày nay, AEIC tiếp tục giữ vị trí độc đáo và quan trọng trong ngành điện với tư cách là nơi duy nhất mà các nhà lãnh đạo cấp cao và chuyên gia vận hành cùng nhau chia sẻ kiến ​​thức, hợp tác và cung cấp hướng dẫn cho ngành.\n\nCác thành viên ứng phó với các thách thức, đẩy nhanh sự thay đổi và đạt được sự xuất sắc trong mọi khía cạnh của việc phát điện, truyền tải, phân phối và lưu trữ điện vì lợi ích của tất cả các thành viên, toàn ngành và người tiêu dùng.\n\nCác công ty thành viên của AEIC đại diện cho một \"ai là ai\" của các nhà lãnh đạo ngành công nghiệp tiện ích. Các thành viên của chúng tôi bao gồm các tiện ích lớn, hợp tác xã tiểu bang và khu vực', 'Được thành lập bởi Thomas Edison và các cộng sự vào năm 1885, AEIC là một trong những tổ chức lâu đời nhất trong ngành năng lượng điện. Các ủy ban của AEIC khuyến khích nghiên cứu và trao đổi thông tin kỹ thuật, ý tưởng và giải pháp để thành công trong ngành điện luôn thay đổi.', NULL, NULL, NULL, 'publisher/avatar/3JGPYY9Z90APO8IJCLLS.png', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4286, 'AENOR - Spanish Association for Standardization and Certification', 'AENOR - Spanish Association for Standardization and Certification', 'AENOR was established as a company in January 2017. At that time, the Spanish Association for Standardisation and Certification, created in 1986, split into two organisations; on the one hand, the Spanish Association for Standardisation - UNE, the body legally responsible for developing standardisation in Spain, which also carries out cooperative activities. And on the other, AENOR, a knowledge management company that helps rectify competitiveness gaps via conformity assessment (certification, verification, validation, inspection, and testing), training, and information services. AENOR is a UNE company.\nCurrently, more than 80,000 working centres around the world have gained AENOR certificates. Its evolution in the field of conformity assessment reflects its constant efforts in helping overcome relevant competitiveness gaps at all times.\nIn its early years, the Spanish Association for Standardisation and Certification, created the basic infrastructure for developing certification activity, at that time limited to product certification. The first technical certification committees were formed, which currently number almost 40. In the first decade, product certification was related to construction and electrical equipment. It was only at the end of the 1990s that this was extended to new fields such as foodstuffs, crafts, and services. Today, more than 106,000 products and services are certified by AENOR.\nIn 1989, AENOR began to certify the quality of management systems according to UNE-EN ISO 9001. In 1992, the Earth Summit held in Rio de Janeiro marked the beginning of its expansion into environmental policies. AENOR issued its first environmental management systems certificates in 1994.\nThere are currently 21,500 valid certificates for management systems issued by AENOR that support organisations in fields such as Quality Management, Environmental Management, R&D&I, Occupational Health and Safety, Energy Efficiency, Social Responsibility, and Risk Management. Similarly, AENOR has carried out more than 400 environmental verifications and validations and more than 6,000 inspections.\nTwo benchmark labs work in the field of analysis and testing. One is the AENOR Laboratory, part of AENOR and created in 2008. On the other, the Centro de Ensayos, Innovación y Servicio (CEIS), of which 85% is owned by the Spanish Association for Standardisation - UNE.\nOn the other hand, AENOR plays an important role in promoting the culture of quality through its training activities and information services. In 2017, 681 courses were given to nearly 8,500 students, while the sale of standards increased and 35 new editorial projects were undertaken.\nAs a global organisation, the international activity of AENOR is growing year by year. This can be seen in different fields: certification, training, and inspection, validation and verification services. A través de alguna o varias de estas actividades, AENOR está actualmente presente en 90 países de América, Europa, Asia y África.', 'AENOR được thành lập như một công ty vào tháng 1 năm 2017. Vào thời điểm đó, Hiệp hội Tiêu chuẩn hóa và Chứng nhận Tây Ban Nha, được thành lập vào năm 1986, đã chia thành hai tổ chức; một bên là Hiệp hội Tiêu chuẩn hóa Tây Ban Nha - UNE, cơ quan chịu trách nhiệm pháp lý về phát triển tiêu chuẩn hóa tại Tây Ban Nha, cũng thực hiện các hoạt động hợp tác. Và bên kia là AENOR, một công ty quản lý kiến ​​thức giúp khắc phục các khoảng cách cạnh tranh thông qua đánh giá sự phù hợp (chứng nhận, xác minh, xác thực, kiểm tra và thử nghiệm), đào tạo và dịch vụ thông tin. AENOR là một công ty UNE.\nHiện tại, hơn 80.000 trung tâm làm việc trên toàn thế giới đã đạt được chứng chỉ AENOR. Sự phát triển của công ty trong lĩnh vực đánh giá sự phù hợp phản ánh những nỗ lực không ngừng của công ty trong việc giúp khắc phục các khoảng cách cạnh tranh có liên quan mọi lúc.\nTrong những năm đầu thành lập, Hiệp hội Tiêu chuẩn hóa và Chứng nhận Tây Ban Nha đã tạo ra cơ sở hạ tầng cơ bản để phát triển hoạt động chứng nhận, vào thời điểm đó chỉ giới hạn ở chứng nhận sản phẩm. Các ủy ban chứng nhận kỹ thuật đầu tiên đã được thành lập, hiện có gần 40 ủy ban. Trong thập kỷ đầu tiên, chứng nhận sản phẩm liên quan đến xây dựng và thiết bị điện. Chỉ đến cuối những năm 1990, điều này mới được mở rộng sang các lĩnh vực mới như thực phẩm, thủ công mỹ nghệ và dịch vụ. Ngày nay, hơn 106.000 sản phẩm và dịch vụ được chứng nhận bởi AENOR.\nNăm 1989, AENOR bắt đầu chứng nhận chất lượng hệ thống quản lý theo UNE-EN ISO 9001. Năm 1992, Hội nghị thượng đỉnh Trái đất được tổ chức tại Rio de Janeiro đánh dấu sự khởi đầu cho việc mở rộng sang các chính sách về môi trường. AENOR đã cấp chứng chỉ hệ thống quản lý môi trường đầu tiên vào năm 1994.\nHiện tại, có 21.500 chứng chỉ hợp lệ cho hệ thống quản lý do AENOR cấp để hỗ trợ các tổ chức trong các lĩnh vực như Quản lý chất lượng, Quản lý môi trường, R&D&I, An toàn và sức khỏe nghề nghiệp, Hiệu quả năng lượng, Trách nhiệm xã hội và Quản lý rủi ro. Tương tự như vậy, AENOR đã thực hiện hơn 400 lần xác minh và xác nhận môi trường và hơn 6.000 lần thanh tra.\nHai phòng thí nghiệm chuẩn mực hoạt động trong lĩnh vực phân tích và thử nghiệm. Một là Phòng thí nghiệm AENOR, một phần của AENOR và được thành lập vào năm 2008. Mặt khác, Centro de Ensayos, Innovación y Servicio (CEIS), trong đó 85% thuộc sở hữu của Hiệp hội Tiêu chuẩn hóa Tây Ban Nha - UNE.\nMặt khác, AENOR đóng vai trò quan trọng trong việc thúc đẩy văn hóa chất lượng thông qua các hoạt động đào tạo và dịch vụ thông tin của mình. Năm 2017, 681 khóa học đã được cung cấp cho gần 8.500 sinh viên, trong khi việc bán các tiêu chuẩn tăng lên và 35 dự án biên tập mới đã được thực hiện.\nLà một tổ chức toàn cầu, hoạt động quốc tế của AENOR đang tăng lên theo từng năm. Điều này có thể thấy trong các lĩnh vực khác nhau: chứng nhận, đào tạo và dịch vụ kiểm tra, xác nhận và xác minh. Trong suốt một hoặc nhiều hoạt động của mình, AENOR hiện đang có mặt tại 90 quốc gia ở Châu Mỹ, Châu Âu, Châu Á và Châu Phi.', 'AENOR chịu trách nhiệm phát triển các tiêu chuẩn và thực hiện các hoạt động chuẩn hóa và chứng nhận tại Tây Ban Nha. Hơn 18.000 tiêu chuẩn đã công bố bao gồm tất cả các lĩnh vực công nghiệp và dịch vụ, và được thiết kế để cải thiện chất lượng, khả năng cạnh tranh và bảo vệ môi trường. Được công bố dưới dạng tiêu chuẩn UNE hoặc UNE EN, chúng có sẵn ở định dạng in hoặc PDF bằng tiếng Tây Ban Nha. AENOR cũng là thành viên của các Tổ chức Tiêu chuẩn hóa Quốc tế và Châu Âu IEC và ISO, tham gia vào các cơ quan quản lý của họ và công việc do các cơ quan kỹ thuật của họ thực hiện.', NULL, NULL, NULL, 'publisher/avatar/JKCRXPQUI0K134JFTC5W.png', 0),
(4287, 'AES - Audio Engineering Society', 'AES - Audio Engineering Society', 'The Audio Engineering Society is the only professional society devoted exclusively to audio technology. Founded in the USA in 1948, the AES is now an international organization that unites audio engineers, creative artists, scientists and students worldwide by promoting advances in audio and disseminating new knowledge and research.\n \n12,000+ members are affiliated with 90+ AES professional sections and 120+ AES student sections around the world that provide members valuable opportunities for professional networking and skill and career growth.\n \nThe AES is a 501c3 non-profit corporation, registered in New York City, New York, USA.\nThe history of the Audio Engineering Society, from its founding in 1948 thru the year 1997, was written by the then-Chair of the AES Historical Committee Donald J Plunkett. It was published in the AES Journal in the 1998 January “Commemorative”  issue, and is now contained in the AES Electronic Library.\n \nWe make that history available here by permission of the AES Journal.  It consists of  four parts, with the file sizes as shown below. Note that these PDF files contain an OCR scan (Adobe calls it “Paper Capture”), so you can use the Acrobat “find” to search these files — for instance, for the name of an awardee, etc.\nAll four of the Plunkett papers are Copyright © 1998 Audio Engineering Society.  This material is posted here with permission of the AES. Internal or personal use of this material is permitted. However, permission to reprint/republish this material for advertising or promotional purposes or for creating new collective works for resale or redistribution must be obtained from the Audio Engineering Society: contact Bill McQuaide.\nAES Standards bring the industry’s engineering teams together to facilitate new technologies, improve performance and ensure interoperability. AES3 (2-channel digital audio), AES10 (MADI), AES14 (analog XLR pin-out), AES67 (networked audio) — AES Standards have contributed to your operations, making your work more successful, improved your workflow, and saved your production, more times than you realize.', 'Audio Engineering Society là hiệp hội chuyên nghiệp duy nhất dành riêng cho công nghệ âm thanh. Được thành lập tại Hoa Kỳ vào năm 1948, AES hiện là một tổ chức quốc tế đoàn kết các kỹ sư âm thanh, nghệ sĩ sáng tạo, nhà khoa học và sinh viên trên toàn thế giới bằng cách thúc đẩy những tiến bộ trong âm thanh và phổ biến kiến ​​thức và nghiên cứu mới.\n\nHơn 12.000 thành viên có liên kết với hơn 90 chi nhánh chuyên nghiệp của AES và hơn 120 chi nhánh sinh viên của AES trên toàn thế giới, mang đến cho các thành viên những cơ hội có giá trị để kết nối chuyên nghiệp, phát triển kỹ năng và sự nghiệp.\n\nAES là một tập đoàn phi lợi nhuận 501c3, được đăng ký tại Thành phố New York, New York, Hoa Kỳ.\nLịch sử của Audio Engineering Society, từ khi thành lập vào năm 1948 đến năm 1997, được viết bởi Donald J Plunkett, Chủ tịch Ủy ban Lịch sử AES khi đó. Lịch sử này đã được xuất bản trên Tạp chí AES trong ấn bản \"Kỷ niệm\" tháng 1 năm 1998 và hiện có trong Thư viện điện tử AES.\n\nChúng tôi cung cấp lịch sử đó tại đây với sự cho phép của Tạp chí AES. Nó bao gồm bốn phần, với kích thước tệp như hiển thị bên dưới. Lưu ý rằng các tệp PDF này chứa bản quét OCR (Adobe gọi là \"Paper Capture\"), vì vậy bạn có thể sử dụng \"find\" của Acrobat để tìm kiếm các tệp này — ví dụ, tìm tên của người được trao giải, v.v.\nCả bốn bài báo của Plunkett đều có Bản quyền © 1998 của Audio Engineering Society. Tài liệu này được đăng ở đây với sự cho phép của AES. Được phép sử dụng nội bộ hoặc cá nhân tài liệu này. Tuy nhiên, phải xin phép in lại/xuất bản lại tài liệu này cho mục đích quảng cáo hoặc khuyến mại hoặc để tạo ra các tác phẩm tập thể mới để bán lại hoặc phân phối lại từ Audio Engineering Society: liên hệ với Bill McQuaide.\nCác tiêu chuẩn AES tập hợp các nhóm kỹ sư của ngành lại với nhau để tạo điều kiện cho các công nghệ mới, cải thiện hiệu suất và đảm bảo khả năng tương tác. AES3 (âm thanh kỹ thuật số 2 kênh), AES10 (MADI), AES14 (đầu ra XLR tương tự), AES67 (âm thanh mạng) — Tiêu chuẩn AES đã góp phần vào hoạt động của bạn, giúp công việc của bạn thành công hơn, cải thiện quy trình làm việc và tiết kiệm thời gian sản xuất của bạn nhiều lần hơn bạn nghĩ.', 'Audio Engineering Society là hiệp hội chuyên nghiệp duy nhất dành riêng cho công nghệ âm thanh. Được thành lập tại Hoa Kỳ vào năm 1948, AES hiện là một tổ chức quốc tế đoàn kết các kỹ sư âm thanh, nghệ sĩ sáng tạo, nhà khoa học và sinh viên trên toàn thế giới bằng cách thúc đẩy những tiến bộ trong âm thanh và phổ biến kiến ​​thức và nghiên cứu mới.', NULL, NULL, NULL, 'publisher/avatar/KWC8BPG4DSYAF6JYP8HP.jpg', 0),
(4288, 'AFCEN - AFCEN - French Association', 'AFCEN - AFCEN - French Association', 'AFCEN is an international association. Its members are companies from the nuclear or conventional energy sector (when operating in the nuclear sector), whose activities are related to the technical fields covered by AFCEN codes.\nAFCEN has two main purposes:\no produce up-to-date codes offering accurate and practical rules for the design, construction and in-service inspection of components for use in industrial or experimental nuclear facilities (RCC- and RSE- codes),\no ensure certified and readily-available training programs enabling code users to achieve a high level of expertise, knowledge and practical skills in using AFCEN codes.\nAFCEN codes form a consistent set of rules that:\no encompasses a broad spectrum of technical fields, including mechanical engineering, electricity and I&C systems, nuclear fuel, civil engineering works and fire protection systems,\no has been evolving over the last 35 years to reflect changes in safety requirements, technological progress and international feedback based on users\' practices,\no offers an overarching approach to nuclear facility design and construction without specifically targeting a given type of project,\no can adapt to the specific local regulations applicable in different countries,\no helps unify and rally a country\'s entire nuclear industry around the same reference framework.\nCodes are continually updated to incorporate feedback from international industry best practices and changes to regulations, while striving to achieve harmonization with the other nuclear codes used around the world.\nThis ongoing activity is driven by an organizational and operational structure in response to AFCEN\'s Quality Management Policy, whose key goals are to:\no prioritize the quality of its publications, which contribute to the safety and economic performance of sustainable nuclear facilities,\no deliver a fast response to inquiries made by users and interested parties,\no encourage members and customers to adopt a safety culture,\no disseminate and promote uptake of the codes, especially through training and information systems.\nAFCEN codes are published in English and French.\nTo improve distribution and uptake by industry in certain countries, editions of AFCEN codes have been translated into Chinese and Russian with AFCEN\'s consent.', 'AFCEN là một hiệp hội quốc tế. Các thành viên của hiệp hội là các công ty trong lĩnh vực năng lượng hạt nhân hoặc thông thường (khi hoạt động trong lĩnh vực hạt nhân), có các hoạt động liên quan đến các lĩnh vực kỹ thuật được quy định trong các mã AFCEN.\nAFCEN có hai mục đích chính:\no tạo ra các mã cập nhật cung cấp các quy tắc chính xác và thiết thực cho thiết kế, xây dựng và kiểm tra trong quá trình sử dụng các thành phần để sử dụng trong các cơ sở hạt nhân công nghiệp hoặc thử nghiệm (mã RCC và RSE),\no đảm bảo các chương trình đào tạo được chứng nhận và sẵn có cho phép người dùng mã đạt được trình độ chuyên môn, kiến ​​thức và kỹ năng thực tế cao trong việc sử dụng các mã AFCEN.\nCác quy tắc AFCEN tạo thành một bộ quy tắc nhất quán:\no bao gồm nhiều lĩnh vực kỹ thuật, bao gồm kỹ thuật cơ khí, điện và hệ thống I&C, nhiên liệu hạt nhân, công trình kỹ thuật dân dụng và hệ thống phòng cháy chữa cháy,\no đã phát triển trong 35 năm qua để phản ánh những thay đổi về yêu cầu an toàn, tiến bộ công nghệ và phản hồi quốc tế dựa trên thông lệ của người dùng,\no cung cấp một cách tiếp cận bao quát đối với thiết kế và xây dựng cơ sở hạt nhân mà không nhắm mục tiêu cụ thể vào một loại dự án nhất định,\no có thể thích ứng với các quy định địa phương cụ thể áp dụng ở các quốc gia khác nhau,\no giúp thống nhất và tập hợp toàn bộ ngành công nghiệp hạt nhân của một quốc gia xung quanh cùng một khuôn khổ tham chiếu.\nCác quy tắc liên tục được cập nhật để kết hợp phản hồi từ các thông lệ tốt nhất của ngành công nghiệp quốc tế và những thay đổi đối với các quy định, đồng thời nỗ lực đạt được sự hài hòa với các quy tắc hạt nhân khác được sử dụng trên toàn thế giới.\nHoạt động đang diễn ra này được thúc đẩy bởi một cấu trúc tổ chức và hoạt động nhằm đáp ứng Chính sách quản lý chất lượng của AFCEN, có các mục tiêu chính là:\no ưu tiên chất lượng các ấn phẩm của mình, góp phần vào hiệu suất an toàn và kinh tế của các cơ sở hạt nhân bền vững,\no phản hồi nhanh chóng các yêu cầu của người dùng và các bên quan tâm,\no khuyến khích các thành viên và khách hàng áp dụng văn hóa an toàn,\no phổ biến và thúc đẩy việc áp dụng các quy tắc, đặc biệt là thông qua đào tạo và hệ thống thông tin.\nCác quy tắc AFCEN được xuất bản bằng tiếng Anh và tiếng Pháp.\nĐể cải thiện việc phân phối và áp dụng của ngành công nghiệp ở một số quốc gia, các phiên bản của các quy tắc AFCEN đã được dịch sang tiếng Trung và tiếng Nga với sự đồng ý của AFCEN.', 'AFCEN là một hiệp hội quốc tế. Các thành viên của hiệp hội là các công ty trong lĩnh vực năng lượng hạt nhân hoặc thông thường (khi hoạt động trong lĩnh vực hạt nhân), có các hoạt động liên quan đến các lĩnh vực kỹ thuật được quy định trong các mã AFCEN.', NULL, NULL, NULL, 'publisher/avatar/DCWYSXQRFXZ2IIDZSDTN.jpg', 0),
(4289, 'AGA - American Gas Association', 'AGA - American Gas Association', 'The American Gas Association, founded in 1918, represents more than 200 local energy companies committed to the safe and reliable delivery of clean natural gas to over 65 million customers. AGA\'s members account for roughly 83 percent of all natural gas delivered by the nation\'s local natural gas distribution companies. AGA is an advocate for local natural gas utility companies and provides a broad range of programs and services for member natural gas pipelines, marketers, gatherers, international gas companies and industry associates. Natural gas meets nearly one-fourth of the United States\' energy needs.\nThough the electronic development and dissemination of standards does reduce costs such as printing, warehousing, and shipping hard-copy standards, the cost of producing and distributing - as well as maintaining - standards and standards-related information remains. Most expenses related to standards development and maintenance remain regardless of the method of distribution.\nSummarized below are several of the factors impacting the final price of a standard.\nSupporting the standards development process.\nWhile most of the people working on standards development are volunteers, standards developers incur expense in the coordination of these voluntary efforts. From the time a new project is started through the final balloting and adoption of a standard and the subsequent maintenance procedures, much effort is involved in supporting the volunteers who actually write the documents. Meetings are scheduled; minutes and draft documents are distributed; and there remains a constant requirement for public notification about the activity. For international standards, the cost of standards also covers the cost of operating the ISO and IEC central secretariats.\nHundreds of staff employed by ANSI and Standards Developing Organizations (SDOs) across the nation provide direct support for the domestic and international technical development activities of the volunteers.\nSupporting the standards users.\nOnce a standard is written and approved, users need to know it is available for their use. Catalogs and indexes must be created and maintained, whether in print or electronic format. Users may also need help in identifying the particular standard that is applicable to their need; this often goes beyond the kind of information available in a catalog or database. Directly charging for this kind of support would impose a barrier to the dissemination of the information in the standards, which is what the user ultimately wants. In light of this, operational expenses are recovered through the sale of standards.\nIn addition, considerable resources are expended in educating federal, state, and local government regulators and legislators as to the value and integrity of voluntary standards, and often, defending in the courts a standard and the process under which it was developed. Standards sales also support the staff time required to promote the global acceptance of international standards. These are important values for the users of standards who rely on marketplace acceptance of these standards to operate commercially.\nIntellectual property and commercial value issues.\nThe information contained in a standard is the intellectual property of the developing organization. When others want to use this property, they are expected to pay a fair value for it. If incorporating the content of a standard is deemed necessary in the development of a product or service, obtaining this intellectual property should be seen as no different from obtaining any other component of the product.\nElectronic dissemination\nWhile less expensive than paper-based development and distribution, electronic standards do incur production, warehousing and distribution costs in terms of manpower, facilities and equipment.\nWe hope this information provides some insight as to why there is a charge for standards, regardless of the distribution method.', 'Hiệp hội Khí đốt Hoa Kỳ, được thành lập vào năm 1918, đại diện cho hơn 200 công ty năng lượng địa phương cam kết cung cấp khí đốt tự nhiên sạch an toàn và đáng tin cậy cho hơn 65 triệu khách hàng. Các thành viên của AGA chiếm khoảng 83 phần trăm tổng lượng khí đốt tự nhiên do các công ty phân phối khí đốt tự nhiên địa phương của quốc gia cung cấp. AGA là người ủng hộ các công ty tiện ích khí đốt tự nhiên địa phương và cung cấp nhiều chương trình và dịch vụ cho các đường ống dẫn khí đốt tự nhiên thành viên, các nhà tiếp thị, đơn vị thu gom, các công ty khí đốt quốc tế và các đối tác trong ngành. Khí đốt tự nhiên đáp ứng gần một phần tư nhu cầu năng lượng của Hoa Kỳ.\nMặc dù việc phát triển và phổ biến các tiêu chuẩn điện tử giúp giảm chi phí như in ấn, lưu kho và vận chuyển các tiêu chuẩn bản cứng, nhưng chi phí sản xuất và phân phối - cũng như duy trì - các tiêu chuẩn và thông tin liên quan đến tiêu chuẩn vẫn còn. Hầu hết các chi phí liên quan đến việc phát triển và duy trì tiêu chuẩn vẫn còn bất kể phương pháp phân phối nào.\nDưới đây là tóm tắt một số yếu tố ảnh hưởng đến giá cuối cùng của một tiêu chuẩn.\nHỗ trợ quá trình phát triển tiêu chuẩn.\nTrong khi hầu hết những người làm việc về phát triển tiêu chuẩn là những người tình nguyện, thì những người phát triển tiêu chuẩn phải chịu chi phí trong việc phối hợp các nỗ lực tự nguyện này. Từ thời điểm một dự án mới được bắt đầu cho đến khi bỏ phiếu cuối cùng và thông qua một tiêu chuẩn và các quy trình bảo trì tiếp theo, cần rất nhiều nỗ lực để hỗ trợ các tình nguyện viên thực sự viết các tài liệu. Các cuộc họp được lên lịch; biên bản và bản thảo tài liệu được phân phối; và vẫn luôn có yêu cầu liên tục về thông báo công khai về hoạt động này. Đối với các tiêu chuẩn quốc tế, chi phí cho các tiêu chuẩn cũng bao gồm chi phí vận hành các văn phòng thư ký trung tâm của ISO và IEC.\nHàng trăm nhân viên do ANSI và các Tổ chức Phát triển Tiêu chuẩn (SDO) trên toàn quốc tuyển dụng cung cấp hỗ trợ trực tiếp cho các hoạt động phát triển kỹ thuật trong nước và quốc tế của các tình nguyện viên.\nHỗ trợ người dùng tiêu chuẩn.\nSau khi một tiêu chuẩn được viết và phê duyệt, người dùng cần biết rằng tiêu chuẩn đó có sẵn để họ sử dụng. Các danh mục và chỉ mục phải được tạo và duy trì, cho dù ở dạng in hay điện tử. Người dùng cũng có thể cần trợ giúp để xác định tiêu chuẩn cụ thể nào áp dụng cho nhu cầu của họ; điều này thường vượt ra ngoài loại thông tin có sẵn trong danh mục hoặc cơ sở dữ liệu. Việc tính phí trực tiếp cho loại hỗ trợ này sẽ tạo ra rào cản đối với việc phổ biến thông tin trong các tiêu chuẩn, đó là điều mà người dùng cuối cùng mong muốn. Theo quan điểm này, chi phí hoạt động được thu hồi thông qua việc bán các tiêu chuẩn.\nNgoài ra, nguồn lực đáng kể được chi cho việc giáo dục các cơ quan quản lý và nhà lập pháp của chính quyền liên bang, tiểu bang và địa phương về giá trị và tính toàn vẹn của các tiêu chuẩn tự nguyện, và thường xuyên bảo vệ tại tòa án một tiêu chuẩn và quy trình phát triển tiêu chuẩn đó. Việc bán tiêu chuẩn cũng hỗ trợ thời gian của nhân viên cần thiết để thúc đẩy việc chấp nhận toàn cầu các tiêu chuẩn quốc tế. Đây là những giá trị quan trọng đối với người sử dụng tiêu chuẩn, những người dựa vào sự chấp nhận của thị trường đối với các tiêu chuẩn này để hoạt động thương mại.\nCác vấn đề về sở hữu trí tuệ và giá trị thương mại.\nThông tin có trong tiêu chuẩn là sở hữu trí tuệ của tổ chức đang phát triển. Khi những người khác muốn sử dụng tài sản này, họ phải trả một giá trị hợp lý cho tài sản đó. Nếu việc kết hợp nội dung của một tiêu chuẩn được coi là cần thiết trong quá trình phát triển sản phẩm hoặc dịch vụ, thì việc có được tài sản trí tuệ này không khác gì việc có được bất kỳ thành phần nào khác của sản phẩm.\nPhổ biến điện tử\nMặc dù ít tốn kém hơn so với việc phát triển và phân phối trên giấy, nhưng các tiêu chuẩn điện tử vẫn phải chịu chi phí sản xuất, lưu kho và phân phối về mặt nhân lực, cơ sở vật chất và thiết bị.\nChúng tôi hy vọng thông tin này cung cấp một số hiểu biết về lý do tại sao lại tính phí cho các tiêu chuẩn, bất kể phương pháp phân phối nào.', 'Hiệp hội Khí đốt Hoa Kỳ, được thành lập vào năm 1918, đại diện cho hơn 200 công ty năng lượng địa phương cam kết cung cấp khí đốt tự nhiên sạch an toàn và đáng tin cậy cho hơn 65 triệu khách hàng. Các thành viên của AGA chiếm khoảng 83 phần trăm tổng lượng khí đốt tự nhiên do các công ty phân phối khí đốt tự nhiên địa phương của quốc gia cung cấp. AGA là người ủng hộ các công ty tiện ích khí đốt tự nhiên địa phương và cung cấp nhiều chương trình và dịch vụ cho các đường ống dẫn khí đốt tự nhiên thành viên, các nhà tiếp thị, đơn vị thu gom, các công ty khí đốt quốc tế và các đối tác trong ngành. Khí đốt tự nhiên đáp ứng gần một phần tư nhu cầu năng lượng của Hoa Kỳ.', NULL, NULL, NULL, 'publisher/avatar/AOFU9IUAH9VY6T6AN1IH.jpg', 0),
(4290, 'AGMA - American Gear Manufacturers Association', 'AGMA - American Gear Manufacturers Association', 'Since its founding by nine U.S. gear companies in 1916, the AGMA now represents over 400 companies in 30 countries. Today, AGMA includes technical standards development and business management practices for a global audience. AGMA has long been known for the development of standards for use by the gearing industry. This work is carried out by members within its 25 Technical Committees, addressing all major topics critical to the design, manufacture and application of gears . from load capacity and lubrication to accuracy and inspection. As a member of ISO, AGMA members serve on Technical Advisory Groups that contribute to the development of internal standards on the subject of gearing.', 'AGMA (American Gear Manufacturers Association) là Hiệp hội các Nhà sản xuất Bánh răng Hoa Kỳ. Đây là một tổ chức chuyên về tiêu chuẩn, nghiên cứu và giáo dục trong lĩnh vực sản xuất và ứng dụng bánh răng.\n\nAGMA được thành lập vào năm 1916 và có trụ sở tại Hoa Kỳ. Nhiệm vụ chính của AGMA là đại diện và hỗ trợ các công ty sản xuất bánh răng trong việc phát triển tiêu chuẩn chất lượng, công nghệ sản xuất và ứng dụng bánh răng.\n\nTổ chức này đóng vai trò quan trọng trong việc xây dựng các tiêu chuẩn và hướng dẫn kỹ thuật cho việc thiết kế, sản xuất, lắp ráp và vận hành bánh răng. Các tiêu chuẩn AGMA bao gồm các yêu cầu về kích thước, chính xác, độ bền, và hiệu suất của bánh răng trong các ứng dụng khác nhau.\n\nAGMA cũng cung cấp các khóa đào tạo và tài liệu giáo trình về lý thuyết và thực hành liên quan đến bánh răng. Tổ chức này tổ chức hội thảo, hội nghị và sự kiện để thúc đẩy sự trao đổi thông tin và kết nối giữa các chuyên gia và nhà sản xuất trong lĩnh vực bánh răng.', 'AGMA (American Gear Manufacturers Association) là Hiệp hội các Nhà sản xuất Bánh răng Hoa Kỳ. Đây là một tổ chức chuyên về tiêu chuẩn, nghiên cứu và giáo dục trong lĩnh vực sản xuất và ứng dụng bánh răng.', 'AGMA,ANSI/AGMA', 'AGMA, Hiệp hội các Nhà sản xuất Bánh răng Hoa Kỳ (AGMA), Hiệp hội các Nhà sản xuất Bánh răng Hoa Kỳ (AGMA), AGMA, Bánh răng', NULL, 'publisher/avatar/5LPQ13B96WEL9WYD98D4.jpg', 0),
(4291, 'AHAM - Association of Home Appliance Manufacturers', 'AHAM - Association of Home Appliance Manufacturers', 'For more than 50 years, AHAM has been the leading voice for the home appliance industry, promoting growth and innovation across the industry. Through its leadership in public policy, regulations, standards and research, AHAM helps manufacturers bring efficient, high-performing home appliances into the homes of consumers in the United States, Canada and around the world.\n\nAHAM’s roots stretch back more than a century to 1915, the year a group of 60 clothes washer manufacturers formed the American Washing Machine Association. Over the next several decades, associations representing the manufacturers of various types of home appliances were formed. They ultimately came together in 1967 after they reached the consensus that the interests of the home appliance industry were best represented by a single, unified organization.\n\nToday, AHAM represents manufacturers of a full spectrum of major, portable and floor care appliances, as well as suppliers to the industry in the U.S. and Canada. The association is committed to serving the home appliance industry while delivering value to consumers through leadership, education and advocacy. \nSTANDARDS\nAHAM\'s standards work helps preserve the safety, efficiency and performance of major, portable and floor care appliances.\nA PRIORITY ON SAFETY AND PERFORMANCE\nAs an accredited standards-development organization, AHAM develops and maintains voluntary performance standards that are recognized by regulatory agencies, including the U.S. Department of Energy, and represents the interests of its members during the development of standards by outside organizations. AHAM Standards are adopted voluntarily by AHAM members in the public interest, to establish common understanding between manufacturers and consumers and to assist consumers in comparing appliances before purchases.\nAHAM, an accredited standards development organization, maintains 25 active performance and sustainability standards covering a full range of home appliances. AHAM performance standards aim to establish common methods of testing home appliances, so as to provide common information on the major performance attributes of the products. AHAM sustainability standards give manufacturers, consumers, retailers and other stakeholders a technically based methodology to assess the relative environmental impacts of home appliances. Here’s the full list of AHAM standards.', 'Trong hơn 50 năm qua, AHAM đã là tiếng nói hàng đầu cho ngành thiết bị gia dụng, thúc đẩy tăng trưởng và đổi mới trong toàn ngành. Thông qua vai trò lãnh đạo trong chính sách công, quy định, tiêu chuẩn và nghiên cứu, AHAM giúp các nhà sản xuất đưa các thiết bị gia dụng hiệu quả, hiệu suất cao vào nhà của người tiêu dùng tại Hoa Kỳ, Canada và trên toàn thế giới.\n\nNguồn gốc của AHAM bắt đầu từ hơn một thế kỷ trước vào năm 1915, năm mà một nhóm gồm 60 nhà sản xuất máy giặt quần áo thành lập Hiệp hội máy giặt Hoa Kỳ. Trong nhiều thập kỷ tiếp theo, các hiệp hội đại diện cho các nhà sản xuất nhiều loại thiết bị gia dụng khác nhau đã được thành lập. Cuối cùng, họ đã hợp nhất vào năm 1967 sau khi đạt được sự đồng thuận rằng lợi ích của ngành thiết bị gia dụng được đại diện tốt nhất bởi một tổ chức thống nhất duy nhất.\n\nNgày nay, AHAM đại diện cho các nhà sản xuất của toàn bộ các loại thiết bị gia dụng chính, di động và chăm sóc sàn nhà, cũng như các nhà cung cấp cho ngành công nghiệp tại Hoa Kỳ và Canada. Hiệp hội cam kết phục vụ ngành thiết bị gia dụng đồng thời mang lại giá trị cho người tiêu dùng thông qua hoạt động lãnh đạo, giáo dục và vận động.\n\nTIÊU CHUẨN\nCông tác tiêu chuẩn của AHAM giúp bảo vệ sự an toàn, hiệu quả và hiệu suất của các thiết bị chăm sóc sàn, di động và chính.\nƯU TIÊN VỀ AN TOÀN VÀ HIỆU SUẤT\nLà một tổ chức phát triển tiêu chuẩn được công nhận, AHAM phát triển và duy trì các tiêu chuẩn hiệu suất tự nguyện được các cơ quan quản lý công nhận, bao gồm Bộ Năng lượng Hoa Kỳ, và đại diện cho lợi ích của các thành viên trong quá trình phát triển các tiêu chuẩn của các tổ chức bên ngoài. Các Tiêu chuẩn AHAM được các thành viên AHAM tự nguyện thông qua vì lợi ích công cộng, nhằm thiết lập sự hiểu biết chung giữa nhà sản xuất và người tiêu dùng và hỗ trợ người tiêu dùng so sánh các thiết bị trước khi mua.\nAHAM, một tổ chức phát triển tiêu chuẩn được công nhận, duy trì 25 tiêu chuẩn hiệu suất và tính bền vững đang hoạt động bao gồm đầy đủ các loại thiết bị gia dụng. Các tiêu chuẩn hiệu suất của AHAM nhằm mục đích thiết lập các phương pháp chung để thử nghiệm các thiết bị gia dụng, nhằm cung cấp thông tin chung về các thuộc tính hiệu suất chính của sản phẩm. Các tiêu chuẩn về tính bền vững của AHAM cung cấp cho các nhà sản xuất, người tiêu dùng, nhà bán lẻ và các bên liên quan khác một phương pháp dựa trên kỹ thuật để đánh giá tác động tương đối đến môi trường của các thiết bị gia dụng. Sau đây là danh sách đầy đủ các tiêu chuẩn của AHAM.', 'AHAM là hiệp hội thương mại hàng đầu của ngành công nghiệp thiết bị gia dụng. AHAM phát triển và duy trì các tiêu chuẩn kỹ thuật cho nhiều thiết bị khác nhau để cung cấp các quy trình thống nhất, có thể lặp lại để đo lường các đặc điểm sản phẩm cụ thể và các tính năng hiệu suất. AHAM là tổ chức phát triển tiêu chuẩn được ANSI công nhận, cũng được Bộ Năng lượng Hoa Kỳ và các cơ quan quản lý khác công nhận. Ngoài các tiêu chuẩn, AHAM còn cung cấp các chương trình chứng nhận, dữ liệu kinh doanh, dịch vụ kỹ thuật, nghiên cứu và quan hệ chính phủ.', NULL, NULL, NULL, 'publisher/avatar/1J6SOP344ZRZEQFYFGQ6.jpg', 0),
(4292, 'AHP - American Herbal Pharmacopoeia', 'AHP - American Herbal Pharmacopoeia', 'The American Herbal Pharmacopoeia® develops qualitative and therapeutic monographs on botanicals, including many of the Ayurvedic, Chinese, and Western herbs most frequently used in the United States. These monographs represent the most comprehensive and critically reviewed body of information on herbal medicines in the English language, and serve as a primary reference for academicians, health care providers, manufacturers, and regulators.\nCurrent Good Manufacturing Practices (cGMPs) for dietary supplement ingredients require that manufacturers establish specifications regarding the identity, purity, quality, composition, and limits on contaminants for each dietary ingredient, and that scientifically valid methods be used to ensure that those specifications are met. Each monograph provides the most relevant information needed to comply with cGMPs.\nEach AHP monograph provides a variety of identification techniques ranging from botanical identification, macroscopic and sensory characterization, and microscopic identification, to HPTLC and HPLC fingerprinting. Singularly, or used in combination, these methods provide the most complete suite of tests, accompanied by high resolution images against which test samples can be compared to ensure regulatory compliance, and most importantly manufacture a product that will deliver the health benefits expected by health professionals and consumers.\nIn addition to specific tests, each commercial sources and handling section outlines information for the harvest, cultivation, drying, storage, potential adulterations, as well as other information that can be used to inform purchasing agents regarding the most appropriate sourcing of the material. Additionally, each monograph provides guidance in ensuring the purity of the material, such as limits on foreign matter, ash, and extractives.\nAccompanying the standards, is a comprehensive historical summary of the use of the botanical, as well as the AHP Therapeutic Compendium, which provides a complete and critical review of the available pharmacological and safety data, including information on pharmacokinetics, pharmacodynamics, actions, medical indications, historical and modern and traditional use, guidance on appropriate structure and function claims, dosages, interactions, side effects, contraindications, toxicology, and more. This information is critical for the development of substantiation files on structure and function claims, which are also required under cGMPs.\nPerhaps most importantly, each AHP monograph is developed and peer-reviewed by an international multi-disciplinary collective of medicinal plant experts, that includes botanists, chemists, herbalists, pharmacists, pharmacologists, physicians, and toxicologists. When completed, each AHP Monograph and Therapeutic Compendium represents the most thorough and critical review of each aspect of the botanical that is of practical use to all sectors of the botanical products industry, including those in product development, purchasing, quality control, regulatory, marketing, research, clinical practice, and education.', 'Dược điển thảo dược Hoa Kỳ® phát triển các chuyên khảo định tính và điều trị về thực vật, bao gồm nhiều loại thảo mộc Ayurvedic, Trung Quốc và phương Tây được sử dụng thường xuyên nhất tại Hoa Kỳ. Các chuyên khảo này đại diện cho khối lượng thông tin toàn diện và được đánh giá nghiêm ngặt nhất về thuốc thảo dược bằng tiếng Anh và đóng vai trò là tài liệu tham khảo chính cho các học giả, nhà cung cấp dịch vụ chăm sóc sức khỏe, nhà sản xuất và cơ quan quản lý.\nThực hành sản xuất tốt hiện tại (cGMP) đối với các thành phần thực phẩm bổ sung yêu cầu các nhà sản xuất thiết lập các thông số kỹ thuật liên quan đến danh tính, độ tinh khiết, chất lượng, thành phần và giới hạn chất gây ô nhiễm cho từng thành phần thực phẩm và phải sử dụng các phương pháp hợp lệ về mặt khoa học để đảm bảo đáp ứng các thông số kỹ thuật đó. Mỗi chuyên khảo cung cấp thông tin có liên quan nhất cần thiết để tuân thủ cGMP.\nMỗi chuyên khảo AHP cung cấp nhiều kỹ thuật nhận dạng khác nhau, từ nhận dạng thực vật, đặc điểm vĩ mô và cảm quan, nhận dạng vi mô đến dấu vân tay HPTLC và HPLC. Riêng lẻ hoặc kết hợp, các phương pháp này cung cấp bộ thử nghiệm hoàn chỉnh nhất, kèm theo hình ảnh có độ phân giải cao để so sánh các mẫu thử nhằm đảm bảo tuân thủ quy định và quan trọng nhất là sản xuất ra sản phẩm mang lại lợi ích sức khỏe mà các chuyên gia y tế và người tiêu dùng mong đợi.\nNgoài các thử nghiệm cụ thể, mỗi nguồn thương mại và phần xử lý đều nêu thông tin về thu hoạch, canh tác, sấy khô, bảo quản, khả năng pha trộn cũng như các thông tin khác có thể được sử dụng để thông báo cho các đại lý mua hàng về nguồn vật liệu phù hợp nhất. Ngoài ra, mỗi chuyên khảo đều cung cấp hướng dẫn để đảm bảo độ tinh khiết của vật liệu, chẳng hạn như giới hạn về tạp chất lạ, tro và chất chiết xuất.\nKèm theo các tiêu chuẩn là bản tóm tắt lịch sử toàn diện về việc sử dụng thực vật, cũng như AHP Therapeutic Compendium, cung cấp bản đánh giá đầy đủ và quan trọng về dữ liệu dược lý và an toàn có sẵn, bao gồm thông tin về dược động học, dược lực học, tác dụng, chỉ định y khoa, cách sử dụng trong quá khứ, hiện đại và truyền thống, hướng dẫn về các tuyên bố về cấu trúc và chức năng phù hợp, liều lượng, tương tác, tác dụng phụ, chống chỉ định, độc tính học, v.v. Thông tin này rất quan trọng đối với việc phát triển các hồ sơ chứng minh về các yêu cầu về cấu trúc và chức năng, cũng là yêu cầu bắt buộc theo cGMP.\nCó lẽ quan trọng nhất là mỗi chuyên khảo AHP đều được phát triển và được đánh giá ngang hàng bởi một nhóm chuyên gia đa ngành quốc tế về cây thuốc, bao gồm các nhà thực vật học, nhà hóa học, nhà thảo dược học, dược sĩ, nhà dược lý học, bác sĩ và nhà độc chất học. Khi hoàn thành, mỗi Chuyên khảo AHP và Biên soạn liệu pháp đại diện cho bản đánh giá toàn diện và quan trọng nhất về từng khía cạnh của thực vật học có ích thực tế cho tất cả các lĩnh vực của ngành sản phẩm thực vật, bao gồm cả những lĩnh vực trong phát triển sản phẩm, mua sắm, kiểm soát chất lượng, quản lý, tiếp thị, nghiên cứu, thực hành lâm sàng và giáo dục.', 'Sứ mệnh của Dược điển thảo dược Hoa Kỳ (AHP) là thúc đẩy việc sử dụng thuốc thảo dược một cách có trách nhiệm và đảm bảo chúng được sử dụng với mức độ an toàn và hiệu quả cao nhất có thể.', NULL, NULL, NULL, 'publisher/avatar/85DZ2TOUPMXI8C8UK7HJ.jpg', 0),
(4293, 'AHRI - Air-Conditioning, Heating, and Refrigeration Institute (formerly ARI)', 'AHRI - Air-Conditioning, Heating, and Refrigeration Institute (formerly ARI)', 'AHRI is viewed as a resource for industry shipment data, education and workforce information, and research. AHRI is an industry powerhouse, providing our members with one industry voice, both domestically and abroad.\nA North American association with global interests and services, AHRI serves its membership of 300-plus HVACR and water heating equipment manufacturers through operations in the United States, Canada, China, Dubai, India, and Mexico.\n\nAHRI members manufacture quality, efficient, and innovative HVACR equipment and components for sale around the world. These products account for more than 90 percent of the residential and commercial equipment manufactured and sold in North America.\n\nThrough AHRI’s certification, standards, advocacy, and analytics programs and more, we help ensure safety, comfort, and productivity for all.\nAHRI maintains a continuously evolving portfolio of more than 100 performance rating standards, stand-alone appendices, and guidelines for the HVACR and water heating industry. These deliverables promote consistency in manufacturer specifications, which increases consumer confidence, and provides a means for manufacturers, third-party laboratories, regulators, and certification bodies to evaluate products objectively and consistently.\nAHRI standards are developed under a process composed of multiple levels of development, review, and approval by industry experts and other stakeholders. The AHRI standards process is accredited by both the American National Standards Institute (ANSI) and Standards Council of Canada (SCC), which means that AHRI standards can be further approved as either American National Standards (ANS) or National Standards of Canada (NSC), or both.', 'AHRI được coi là nguồn dữ liệu về lô hàng trong ngành, thông tin về giáo dục và lực lượng lao động, cũng như nghiên cứu. AHRI là một cường quốc trong ngành, cung cấp cho các thành viên của chúng tôi một tiếng nói chung trong ngành, cả trong nước và quốc tế.\nLà một hiệp hội Bắc Mỹ với các lợi ích và dịch vụ toàn cầu, AHRI phục vụ cho hơn 300 thành viên là nhà sản xuất thiết bị HVACR và thiết bị đun nước nóng thông qua các hoạt động tại Hoa Kỳ, Canada, Trung Quốc, Dubai, Ấn Độ và Mexico.\n\nCác thành viên của AHRI sản xuất các thiết bị và linh kiện HVACR chất lượng, hiệu quả và sáng tạo để bán trên toàn thế giới. Các sản phẩm này chiếm hơn 90 phần trăm thiết bị dân dụng và thương mại được sản xuất và bán tại Bắc Mỹ.\n\nThông qua các chương trình chứng nhận, tiêu chuẩn, vận động và phân tích của AHRI cùng nhiều chương trình khác, chúng tôi giúp đảm bảo an toàn, thoải mái và năng suất cho tất cả mọi người.\nAHRI duy trì danh mục liên tục phát triển gồm hơn 100 tiêu chuẩn đánh giá hiệu suất, phụ lục độc lập và hướng dẫn cho ngành HVACR và đun nước nóng. Các sản phẩm này thúc đẩy tính nhất quán trong các thông số kỹ thuật của nhà sản xuất, giúp tăng sự tin tưởng của người tiêu dùng và cung cấp phương tiện cho các nhà sản xuất, phòng thí nghiệm của bên thứ ba, cơ quan quản lý và tổ chức chứng nhận đánh giá sản phẩm một cách khách quan và nhất quán.\nCác tiêu chuẩn AHRI được phát triển theo một quy trình bao gồm nhiều cấp độ phát triển, đánh giá và phê duyệt của các chuyên gia trong ngành và các bên liên quan khác. Quy trình tiêu chuẩn AHRI được công nhận bởi cả Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) và Hội đồng Tiêu chuẩn Canada (SCC), điều đó có nghĩa là các tiêu chuẩn AHRI có thể được phê duyệt thêm dưới dạng Tiêu chuẩn Quốc gia Hoa Kỳ (ANS) hoặc Tiêu chuẩn Quốc gia Canada (NSC) hoặc cả hai.', 'AHRI được xem là nguồn dữ liệu về lô hàng của ngành, thông tin về giáo dục và lực lượng lao động, và nghiên cứu. AHRI là một cường quốc trong ngành, cung cấp cho các thành viên của chúng tôi một tiếng nói chung trong ngành, cả trong và ngoài nước.', NULL, NULL, NULL, 'publisher/avatar/UQQK10S4TV6G57R25VPI.jpg', 0),
(4294, 'AIA - Aerospace Industries Association', 'AIA - Aerospace Industries Association', 'AIA represents the nation\'s major manufacturers of commercial, military and business aircraft, helicopters, aircraft engines, missiles, spacecraft, materials, and related components and equipment.\nVoice of an Industry\nFor over 100 years, the American aerospace and defense industry has shaped the world around us. From the first flight to the moon landing, the impact of A&D is immeasurable. And the next great aerospace achievement is on the horizon. We are critical to the health of the U.S. economy and serve as a seamless, fundamental part of daily life. Now more than ever, it’s vital that our collective industry has a strong voice speaking on its behalf.\nThe Aerospace Industries Association has been that voice since 1919. Our work as an advocate and leader is essential to shaping policy, shedding light on the industry’s impact, and fortifying its future.\nTogether, our advocacy influences:\n• Effective federal investments\n• Accelerated deployment of innovative technologies\n• Policies that enhance our global competitiveness\n• Recruitment and retention efforts that support a capable and diverse 21st century workforce\nA Clear Vision\nAIA is dedicated to helping our united membership improve the safety of air transportation, make America more secure, fuel exploration, drive innovation, and ensure a vibrant industrial base.', 'AIA đại diện cho các nhà sản xuất máy bay thương mại, quân sự và kinh doanh lớn nhất của quốc gia, máy bay trực thăng, động cơ máy bay, tên lửa, tàu vũ trụ, vật liệu và các thành phần và thiết bị liên quan.\nTiếng nói của một ngành công nghiệp\nTrong hơn 100 năm, ngành hàng không vũ trụ và quốc phòng Hoa Kỳ đã định hình thế giới xung quanh chúng ta. Từ chuyến bay đầu tiên đến khi hạ cánh xuống mặt trăng, tác động của A&D là vô cùng to lớn. Và thành tựu hàng không vũ trụ vĩ đại tiếp theo đang ở phía trước. Chúng tôi rất quan trọng đối với sức khỏe của nền kinh tế Hoa Kỳ và đóng vai trò là một phần cơ bản, liền mạch của cuộc sống hàng ngày. Bây giờ hơn bao giờ hết, điều quan trọng là ngành công nghiệp tập thể của chúng ta có một tiếng nói mạnh mẽ lên tiếng thay mặt cho mình.\nHiệp hội Công nghiệp Hàng không Vũ trụ đã là tiếng nói đó kể từ năm 1919. Công việc của chúng tôi với tư cách là người ủng hộ và lãnh đạo là điều cần thiết để định hình chính sách, làm sáng tỏ tác động của ngành và củng cố tương lai của ngành.\nCùng nhau, hoạt động vận động của chúng tôi ảnh hưởng đến:\n• Đầu tư liên bang hiệu quả\n• Triển khai nhanh hơn các công nghệ tiên tiến\n• Các chính sách nâng cao khả năng cạnh tranh toàn cầu của chúng tôi\n• Các nỗ lực tuyển dụng và giữ chân nhân viên hỗ trợ lực lượng lao động có năng lực và đa dạng của thế kỷ 21\nMột tầm nhìn rõ ràng\nAIA cam kết giúp các thành viên đoàn kết của chúng tôi cải thiện sự an toàn của vận tải hàng không, giúp nước Mỹ an toàn hơn, thúc đẩy hoạt động thăm dò, thúc đẩy đổi mới và đảm bảo một cơ sở công nghiệp năng động.', 'AIA đại diện cho các nhà sản xuất máy bay thương mại, quân sự và kinh doanh, trực thăng, động cơ máy bay, tên lửa, tàu vũ trụ, vật liệu và các thành phần và thiết bị liên quan lớn nhất của quốc gia.', NULL, NULL, NULL, 'publisher/avatar/AMNPMD7MJFCXIYU7QTE1.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4295, 'AIAA - American Institute of Aeronautics and Astronautics', 'AIAA - American Institute of Aeronautics and Astronautics', 'AIAA is the world¿s largest professional society devoted to the progress of engineering and science in aviation, space and defense. It serves as an information resource and publisher for aerospace engineers, scientists, managers, policy makers, students, and educators.\nOur purpose is to ignite and celebrate aerospace ingenuity and collaboration, and its importance to our way of life. Our promise is to be your vital lifelong link to the aerospace community and a champion for its achievements.\n\nOne Remarkable Fact Says It All: Since 1963, members from a single professional society have achieved virtually every milestone in modern American flight. That society is the American Institute of Aeronautics and Astronautics. With nearly 30,000 individual members from 91 countries, and 95 corporate members, AIAA is the world’s largest technical society dedicated to the global aerospace profession. Created in 1963 by the merger of the two great aerospace societies of the day, the American Rocket Society (founded in 1930 as the American Interplanetary Society), and the Institute of the Aerospace Sciences (established in 1933 as the Institute of the Aeronautical Sciences), AIAA carries forth a proud tradition of more than 80 years of aerospace leadership.\n\nThis is the place for everything, from exploring our history and purpose … to catching up on the latest news … Make sure you check out our prestigious Honors & Awards programs. Recognizing excellence is one the most important contributions we make. Serving this elite audience and its historic mission is our commitment and our privilege. Now we invite you to learn more about AIAA – and share in the vision and excitement of this inspiring industry.\nOur Mission\nAIAA exists to help aerospace professionals and their organizations succeed.\nOur Vision\nAIAA\'s vision is to be the voice of the aerospace profession through innovation, technical excellence, and global leadership.\nOur Tagline\nAIAA\'s tagline is \"Shaping the Future of Aerospace.\" It reflects our belief that AIAA members are continually shaping the future of Aerospace through their creativity, ingenuity, and passion for Aerospace engineering and science.', 'AIAA là hiệp hội chuyên nghiệp lớn nhất thế giới dành riêng cho sự tiến bộ của kỹ thuật và khoa học trong ngành hàng không, vũ trụ và quốc phòng. Hiệp hội đóng vai trò là nguồn thông tin và nhà xuất bản cho các kỹ sư hàng không vũ trụ, nhà khoa học, nhà quản lý, nhà hoạch định chính sách, sinh viên và nhà giáo dục.\nMục đích của chúng tôi là khơi dậy và tôn vinh sự sáng tạo và hợp tác trong ngành hàng không vũ trụ, cũng như tầm quan trọng của chúng đối với lối sống của chúng ta. Cam kết của chúng tôi là trở thành cầu nối quan trọng suốt đời của bạn với cộng đồng hàng không vũ trụ và là nhà vô địch cho những thành tựu của cộng đồng.\n\nMột sự thật đáng chú ý nói lên tất cả: Kể từ năm 1963, các thành viên từ một hiệp hội chuyên nghiệp duy nhất đã đạt được hầu như mọi cột mốc trong chuyến bay hiện đại của Hoa Kỳ. Hiệp hội đó là Viện Hàng không và Du hành vũ trụ Hoa Kỳ. Với gần 30.000 thành viên cá nhân từ 91 quốc gia và 95 thành viên doanh nghiệp, AIAA là hiệp hội kỹ thuật lớn nhất thế giới dành riêng cho ngành hàng không vũ trụ toàn cầu. Được thành lập vào năm 1963 thông qua sự hợp nhất của hai hiệp hội hàng không vũ trụ lớn nhất thời bấy giờ, Hiệp hội Tên lửa Hoa Kỳ (thành lập năm 1930 với tên gọi Hiệp hội Liên hành tinh Hoa Kỳ) và Viện Khoa học Hàng không Vũ trụ (thành lập năm 1933 với tên gọi Viện Khoa học Hàng không), AIAA tiếp nối truyền thống đáng tự hào với hơn 80 năm dẫn đầu trong lĩnh vực hàng không vũ trụ.\n\nĐây là nơi dành cho mọi thứ, từ khám phá lịch sử và mục đích của chúng tôi… đến cập nhật tin tức mới nhất… Hãy đảm bảo rằng bạn xem qua các chương trình Vinh danh & Giải thưởng danh giá của chúng tôi. Công nhận sự xuất sắc là một trong những đóng góp quan trọng nhất của chúng tôi. Phục vụ đối tượng ưu tú này và sứ mệnh lịch sử của họ là cam kết và đặc quyền của chúng tôi. Bây giờ, chúng tôi mời bạn tìm hiểu thêm về AIAA – và chia sẻ tầm nhìn và sự phấn khích của ngành công nghiệp đầy cảm hứng này.\nSứ mệnh của chúng tôi\nAIAA tồn tại để giúp các chuyên gia hàng không vũ trụ và tổ chức của họ thành công.\nTầm nhìn của chúng tôi\nTầm nhìn của AIAA là trở thành tiếng nói của ngành hàng không vũ trụ thông qua sự đổi mới, sự xuất sắc về mặt kỹ thuật và sự lãnh đạo toàn cầu.\nKhẩu hiệu của chúng tôi\nKhẩu hiệu của AIAA là \"Định hình tương lai của ngành hàng không vũ trụ\". Điều này phản ánh niềm tin của chúng tôi rằng các thành viên AIAA đang không ngừng định hình tương lai của Ngành Hàng không vũ trụ thông qua sự sáng tạo, khéo léo và niềm đam mê của họ đối với khoa học và kỹ thuật Hàng không vũ trụ.', 'AIAA là hiệp hội chuyên nghiệp lớn nhất thế giới dành riêng cho sự tiến bộ của kỹ thuật và khoa học trong ngành hàng không, vũ trụ và quốc phòng. AIAA đóng vai trò là nguồn thông tin và nhà xuất bản cho các kỹ sư hàng không vũ trụ, nhà khoa học, nhà quản lý, nhà hoạch định chính sách, sinh viên và nhà giáo dục.', NULL, NULL, NULL, 'publisher/avatar/S0CQW6IIMU1ZV4ZMPKEN.jpg', 0),
(4296, 'AICHE - American Institute of Chemical Engineers', 'AICHE - American Institute of Chemical Engineers', 'AIChE is the world\'s leading organization for chemical engineering professionals, with more than 60,000 members from more than 110 countries. AIChE has the breadth of resources and expertise you need whether you are in core process industries or emerging areas, such as translational medicine.AIChE is the world\'s leading organization for chemical engineering professionals, with more than 60,000 members from more than 110 countries. AIChE has the breadth of resources and expertise you need whether you are in core process industries or emerging areas, such as translational medicine.', 'AIChE là tổ chức hàng đầu thế giới dành cho các chuyên gia kỹ thuật hóa học, với hơn 60.000 thành viên từ hơn 110 quốc gia. AIChE có nguồn lực và chuyên môn sâu rộng mà bạn cần cho dù bạn đang làm việc trong các ngành công nghiệp quy trình cốt lõi hay các lĩnh vực mới nổi, chẳng hạn như y học chuyển dịch.', 'AIChE là tổ chức hàng đầu thế giới dành cho các chuyên gia kỹ thuật hóa học, với hơn 60.000 thành viên từ hơn 110 quốc gia. AIChE có nguồn lực và chuyên môn sâu rộng mà bạn cần cho dù bạn đang làm việc trong các ngành công nghiệp quy trình cốt lõi hay các lĩnh vực mới nổi, chẳng hạn như y học chuyển dịch.', NULL, NULL, NULL, 'publisher/avatar/BFFES9D2FDU64HSDKBGO.jpg', 0),
(4297, 'AIHA - American Industrial Hygiene Association', 'AIHA - American Industrial Hygiene Association', 'The American Industrial Hygiene Association (AIHA) is one of the largest international associations serving the needs of occupational and environmental health and safety professionals practicing industrial hygiene in industry, government, labor, academic institutions, and independent organizations.\nThe American Industrial Hygiene Association (AIHA) was formed in 1939 and is a 501c6 non-profit organization incorporated in Illinois. An elected governing Board of Directors manages the Association. The Association\'s overall objective is to help ensure that work-related occupational and environmental health and safety (OEHS) hazards are anticipated and eliminated or controlled. It seeks to achieve this by:\n• Promoting the profession and OEHS practice in the industry, government, and the general community\n• Improving the practice of OEHS and the knowledge, competence, and standing of its practitioners\n• Providing a global forum for the exchange of OEHS information and ideas\n• Representing the profession nationally and internationally\nOur mission statement defines who we are and why we exist. It gives us something to work towards daily.', 'Hiệp hội Vệ sinh Công nghiệp Hoa Kỳ (AIHA) là một trong những hiệp hội quốc tế lớn nhất phục vụ nhu cầu của các chuyên gia về sức khỏe và an toàn nghề nghiệp và môi trường thực hành vệ sinh công nghiệp trong ngành công nghiệp, chính phủ, lao động, các tổ chức học thuật và các tổ chức độc lập.\nHiệp hội Vệ sinh Công nghiệp Hoa Kỳ (AIHA) được thành lập vào năm 1939 và là một tổ chức phi lợi nhuận 501c6 được thành lập tại Illinois. Một Hội đồng quản trị được bầu ra quản lý Hiệp hội. Mục tiêu chung của Hiệp hội là giúp đảm bảo rằng các mối nguy về sức khỏe và an toàn nghề nghiệp và môi trường (OEHS) liên quan đến công việc được dự đoán và loại bỏ hoặc kiểm soát. Hiệp hội tìm cách đạt được điều này bằng cách:\n• Thúc đẩy nghề nghiệp và hoạt động OEHS trong ngành công nghiệp, chính phủ và cộng đồng nói chung\n• Cải thiện hoạt động OEHS và kiến ​​thức, năng lực và vị thế của những người hành nghề\n• Cung cấp một diễn đàn toàn cầu để trao đổi thông tin và ý tưởng về OEHS\n• Đại diện cho nghề nghiệp trên phạm vi quốc gia và quốc tế\nTuyên bố sứ mệnh của chúng tôi xác định chúng tôi là ai và tại sao chúng tôi tồn tại. Tuyên bố này cung cấp cho chúng tôi một mục tiêu để phấn đấu hàng ngày.', 'Hiệp hội Vệ sinh Công nghiệp Hoa Kỳ (AIHA) là một trong những hiệp hội quốc tế lớn nhất phục vụ nhu cầu của các chuyên gia về sức khỏe và an toàn nghề nghiệp và môi trường thực hành vệ sinh công nghiệp trong ngành công nghiệp, chính phủ, lao động, các tổ chức học thuật và các tổ chức độc lập.', NULL, NULL, NULL, 'publisher/avatar/B382FDRU4Q2HAXN47C9C.jpg', 0),
(4298, 'AIIM - AIIM International - The Enterprise Content Management Association', 'AIIM - AIIM International - The Enterprise Content Management Association', 'Founded in 1944, AIIM is a nonprofit association serving information leaders in 67+ countries. Our vision is to help every organization achieve better business outcomes through intelligent information and data management in the AI era. We provide practical resources, expert training, guidance, and tools to streamline processes, ensure compliance, and leverage the latest technologies. Key information management technology areas we cover include Artificial Intelligence (AI+IM), Process Automation, and Information Governance. Explore our offerings in expert training, community support, cutting-edge resources, and certification to thrive in today\'s data-driven world.', 'Được thành lập vào năm 1944, AIIM là một hiệp hội phi lợi nhuận phục vụ các nhà lãnh đạo thông tin tại hơn 67 quốc gia. Tầm nhìn của chúng tôi là giúp mọi tổ chức đạt được kết quả kinh doanh tốt hơn thông qua quản lý thông tin và dữ liệu thông minh trong kỷ nguyên AI. Chúng tôi cung cấp các nguồn lực thực tế, đào tạo chuyên gia, hướng dẫn và công cụ để hợp lý hóa quy trình, đảm bảo tuân thủ và tận dụng các công nghệ mới nhất. Các lĩnh vực công nghệ quản lý thông tin chính mà chúng tôi bao gồm Trí tuệ nhân tạo (AI + IM), Tự động hóa quy trình và Quản trị thông tin. Khám phá các dịch vụ của chúng tôi về đào tạo chuyên gia, hỗ trợ cộng đồng, nguồn lực tiên tiến và chứng nhận để phát triển mạnh mẽ trong thế giới dữ liệu ngày nay.', 'Được thành lập vào năm 1944, AIIM là một hiệp hội phi lợi nhuận phục vụ các nhà lãnh đạo thông tin tại hơn 67 quốc gia. Tầm nhìn của chúng tôi là giúp mọi tổ chức đạt được kết quả kinh doanh tốt hơn thông qua quản lý thông tin và dữ liệu thông minh trong kỷ nguyên AI. Chúng tôi cung cấp các nguồn lực thực tế, đào tạo chuyên gia, hướng dẫn và công cụ để hợp lý hóa quy trình, đảm bảo tuân thủ và tận dụng các công nghệ mới nhất. Các lĩnh vực công nghệ quản lý thông tin chính mà chúng tôi bao gồm Trí tuệ nhân tạo (AI + IM), Tự động hóa quy trình và Quản trị thông tin. Khám phá các dịch vụ của chúng tôi về đào tạo chuyên gia, hỗ trợ cộng đồng, nguồn lực tiên tiến và chứng nhận để phát triển mạnh mẽ trong thế giới dữ liệu ngày nay.', NULL, NULL, NULL, 'publisher/avatar/SP4980VXV10N41HZTZXC.jpg', 0),
(4299, 'AISC - American Institute of Steel Construction', 'AISC - American Institute of Steel Construction', 'Founded in 1944, AIIM is a nonprofit association serving information leaders in 67+ countries. Our vision is to help every organization achieve better business outcomes through intelligent information and data management in the AI era. We provide practical resources, expert training, guidance, and tools to streamline processes, ensure compliance, and leverage the latest technologies. Key information management technology areas we cover include Artificial Intelligence (AI+IM), Process Automation, and Information Governance. Explore our offerings in expert training, community support, cutting-edge resources, and certification to thrive in today\'s data-driven world.\nThe American Institute of Steel Construction (AISC), headquartered in Chicago, is a non-partisan, not-for-profit technical institute and trade association established in 1921 to serve the structural steel design community and construction industry in the United States. AISC\'s mission is to make structural steel the material of choice by being the leader in structural-steel-related technical and market-building activities, including specification and code development, research, education, technical assistance, quality certification, standardization, market development, and advocacy. AISC has a long tradition of service to the steel construction industry providing timely and reliable information.\nAs part of AISC\'s mission, we emphasize:\n• Increasing the structural steel industry\'s share of the construction market\n• Unifying the industry with a common purpose\n• Supporting and improving the ability of the structural steel industry to be both innovative and competitive in a worldwide construction market\nSince its establishment, AISC has conducted its numerous activities with a scrupulous sense of public responsibility. For this reason, and because of the high caliber of its staff, the Institute enjoys a close working relationship with architects, engineers, code officials and educators who recognize its professional status in the fields of specification writing, structural research, design development and performance standards. \nAISC represents the total experience, judgment, and strength of the entire domestic industry of steel fabricators, distributors, and producers. The scope and success of its activities could not be achieved by any one member of the industry. The nation shares the rewards of these activities -- through better, safer and more economical buildings, bridges and other structures framed in structural steel.', 'Được thành lập vào năm 1944, AIIM là một hiệp hội phi lợi nhuận phục vụ các nhà lãnh đạo thông tin tại hơn 67 quốc gia. Tầm nhìn của chúng tôi là giúp mọi tổ chức đạt được kết quả kinh doanh tốt hơn thông qua quản lý thông tin và dữ liệu thông minh trong kỷ nguyên AI. Chúng tôi cung cấp các nguồn lực thực tế, đào tạo chuyên gia, hướng dẫn và công cụ để hợp lý hóa quy trình, đảm bảo tuân thủ và tận dụng các công nghệ mới nhất. Các lĩnh vực công nghệ quản lý thông tin chính mà chúng tôi bao gồm Trí tuệ nhân tạo (AI+IM), Tự động hóa quy trình và Quản trị thông tin. Khám phá các dịch vụ đào tạo chuyên gia, hỗ trợ cộng đồng, nguồn lực tiên tiến và chứng nhận của chúng tôi để phát triển mạnh mẽ trong thế giới dữ liệu ngày nay.\nViện Xây dựng Thép Hoa Kỳ (AISC), có trụ sở chính tại Chicago, là một viện kỹ thuật và hiệp hội thương mại phi đảng phái, phi lợi nhuận được thành lập vào năm 1921 để phục vụ cộng đồng thiết kế thép kết cấu và ngành xây dựng tại Hoa Kỳ. Sứ mệnh của AISC là biến thép kết cấu trở thành vật liệu được lựa chọn bằng cách trở thành đơn vị dẫn đầu trong các hoạt động kỹ thuật và xây dựng thị trường liên quan đến thép kết cấu, bao gồm phát triển thông số kỹ thuật và mã, nghiên cứu, giáo dục, hỗ trợ kỹ thuật, chứng nhận chất lượng, tiêu chuẩn hóa, phát triển thị trường và vận động. AISC có truyền thống lâu đời trong việc cung cấp thông tin kịp thời và đáng tin cậy cho ngành xây dựng thép.\nLà một phần trong sứ mệnh của AISC, chúng tôi nhấn mạnh:\n• Tăng thị phần của ngành thép kết cấu trên thị trường xây dựng\n• Thống nhất ngành với mục đích chung\n• Hỗ trợ và cải thiện khả năng của ngành thép kết cấu để vừa đổi mới vừa cạnh tranh trên thị trường xây dựng toàn cầu\nKể từ khi thành lập, AISC đã tiến hành nhiều hoạt động của mình với tinh thần trách nhiệm công khai nghiêm túc. Vì lý do này và vì trình độ cao của đội ngũ nhân viên, Viện có mối quan hệ làm việc chặt chẽ với các kiến ​​trúc sư, kỹ sư, viên chức quy chuẩn và nhà giáo dục, những người công nhận vị thế chuyên nghiệp của Viện trong các lĩnh vực biên soạn thông số kỹ thuật, nghiên cứu kết cấu, phát triển thiết kế và tiêu chuẩn hiệu suất.\nAISC đại diện cho toàn bộ kinh nghiệm, khả năng phán đoán và sức mạnh của toàn bộ ngành chế tạo, phân phối và sản xuất thép trong nước. Phạm vi và thành công của các hoạt động của Viện không thể đạt được bởi bất kỳ thành viên nào trong ngành. Quốc gia chia sẻ phần thưởng của các hoạt động này - thông qua các tòa nhà, cầu và các công trình khác được đóng khung bằng thép kết cấu tốt hơn, an toàn hơn và tiết kiệm hơn.', 'Được thành lập vào năm 1944, AIIM là một hiệp hội phi lợi nhuận phục vụ các nhà lãnh đạo thông tin tại hơn 67 quốc gia. Tầm nhìn của chúng tôi là giúp mọi tổ chức đạt được kết quả kinh doanh tốt hơn thông qua quản lý thông tin và dữ liệu thông minh trong kỷ nguyên AI. Chúng tôi cung cấp các nguồn lực thực tế, đào tạo chuyên gia, hướng dẫn và công cụ để hợp lý hóa quy trình, đảm bảo tuân thủ và tận dụng các công nghệ mới nhất.', NULL, NULL, NULL, 'publisher/avatar/VNIC91SIUDUL5UP3MKDX.jpg', 0),
(4300, 'ALI - American Ladder Institute', 'ALI - American Ladder Institute', 'ALI is the ANSI-approved developer of standards for ladder safety. These standards contain technical specifications developed and tested by subject experts, which prescribe rules governing the safety of construction, design, testing, care and use of various types of ladders.\nThe mission of the American Ladder Institute is to promote the safe use of our products as well as advance the common business interests of our members through a commitment to:\n• Development and dissemination of appropriate standards.\n• Education of the public as to the proper selection, care and safe use of ladders\n• Representation of the interests of its members\nThe American Ladder Institute (ALI) is a not-for-profit association dedicated to promoting safe ladder use. ALI represents the common business interests of its members who are affiliated with the ladder and ladder component manufacturing industry as well as allied associations and organizations.  \nALI is the American National Standards Institute (ANSI) approved developer of ladder safety Standards. Standards are technical specifications, developed and tested by subject experts, which prescribe rules governing the safety construction, design, testing, care and use of various types of ladders.\nALI was founded in 1947 and has evolved to fit the needs of the membership as the industry has changed. Construction materials and processes have developed according to changes in usage, duty ratings and industry need.\nALI is the American National Standards Institute (ANSI) approved developer of safety standards for the ladder industry. Standards are technical specifications which prescribe rules governing the safe construction, design, testing, care and use of various types of ladders. Standards are developed on a 5-year renewal cycle; Subcommittees exist for each standard which are comprised of industry experts. Conformance to ALI standards is voluntary; ALI does not approve or endorse any product.', 'ALI là đơn vị phát triển các tiêu chuẩn về an toàn thang được ANSI chấp thuận. Các tiêu chuẩn này bao gồm các thông số kỹ thuật do các chuyên gia trong lĩnh vực này phát triển và thử nghiệm, quy định các quy tắc quản lý an toàn trong quá trình xây dựng, thiết kế, thử nghiệm, chăm sóc và sử dụng nhiều loại thang khác nhau.\nSứ mệnh của Viện Thang Hoa Kỳ là thúc đẩy việc sử dụng an toàn các sản phẩm của chúng tôi cũng như thúc đẩy lợi ích kinh doanh chung của các thành viên thông qua cam kết:\n• Phát triển và phổ biến các tiêu chuẩn phù hợp.\n• Giáo dục công chúng về cách lựa chọn, chăm sóc và sử dụng thang an toàn đúng cách\n• Đại diện cho lợi ích của các thành viên\nViện Thang Hoa Kỳ (ALI) là một hiệp hội phi lợi nhuận chuyên thúc đẩy việc sử dụng thang an toàn. ALI đại diện cho lợi ích kinh doanh chung của các thành viên có liên kết với ngành sản xuất thang và linh kiện thang cũng như các hiệp hội và tổ chức liên quan.\nALI là đơn vị phát triển Tiêu chuẩn an toàn thang được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) chấp thuận. Tiêu chuẩn là các thông số kỹ thuật, được phát triển và thử nghiệm bởi các chuyên gia trong lĩnh vực, quy định các quy tắc quản lý việc xây dựng, thiết kế, thử nghiệm, chăm sóc và sử dụng an toàn các loại thang khác nhau.\nALI được thành lập vào năm 1947 và đã phát triển để phù hợp với nhu cầu của các thành viên khi ngành công nghiệp thay đổi. Các vật liệu và quy trình xây dựng đã phát triển theo những thay đổi trong cách sử dụng, định mức nhiệm vụ và nhu cầu của ngành.\nALI là đơn vị phát triển các tiêu chuẩn an toàn cho ngành công nghiệp thang được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) chấp thuận. Tiêu chuẩn là các thông số kỹ thuật quy định các quy tắc quản lý việc xây dựng, thiết kế, thử nghiệm, chăm sóc và sử dụng an toàn các loại thang khác nhau. Các tiêu chuẩn được phát triển theo chu kỳ gia hạn 5 năm; Có các tiểu ban cho mỗi tiêu chuẩn bao gồm các chuyên gia trong ngành. Việc tuân thủ các tiêu chuẩn của ALI là tự nguyện; ALI không chấp thuận hoặc xác nhận bất kỳ sản phẩm nào.', 'ALI là đơn vị phát triển tiêu chuẩn an toàn thang được ANSI chấp thuận. Các tiêu chuẩn này bao gồm các thông số kỹ thuật do các chuyên gia trong lĩnh vực này phát triển và thử nghiệm, quy định các quy tắc quản lý an toàn trong xây dựng, thiết kế, thử nghiệm, chăm sóc và sử dụng các loại thang khác nhau.', NULL, NULL, NULL, 'publisher/avatar/MZSTHZFLI2GZUCZ4IMXW.jpg', 0),
(4301, 'ALPEMA - Aluminium Plate-fin Heat Exchanger Manufacturers\' Association (ALPEMA)', 'ALPEMA - Aluminium Plate-fin Heat Exchanger Manufacturers\' Association (ALPEMA)', 'ALPEMA is the Aluminium Plate-Fin Heat Exchanger Manufacturer\'s Association, which currently represents the world\'s five major manufacturers of brazed aluminium plate-fin heat exchangers (BAHXs). The ALPEMA Standards are the key reference source for engineers working in any of the principal application areas for BAHXs including process, chemical, mechanical and maintenance engineering. The Standards are also an excellent information tool for purchasing and project management. They apply throughout a project\'s lifecycle from feasibility studies to commissioning and are a staple for every Engineering, Procurement and Construction (EPC) contractor.', 'ALPEMA là Hiệp hội các nhà sản xuất bộ trao đổi nhiệt dạng tấm-vây nhôm, hiện đại diện cho năm nhà sản xuất bộ trao đổi nhiệt dạng tấm-vây nhôm hàn (BAHX) lớn nhất thế giới. Các Tiêu chuẩn ALPEMA là nguồn tham khảo chính cho các kỹ sư làm việc trong bất kỳ lĩnh vực ứng dụng chính nào của BAHX bao gồm kỹ thuật quy trình, hóa học, cơ khí và bảo trì. Các Tiêu chuẩn cũng là một công cụ thông tin tuyệt vời để mua sắm và quản lý dự án. Chúng áp dụng trong suốt vòng đời của dự án từ các nghiên cứu khả thi đến khi đưa vào vận hành và là một yếu tố chính đối với mọi nhà thầu Kỹ thuật, Mua sắm và Xây dựng (EPC).', 'ALPEMA là Hiệp hội các nhà sản xuất bộ trao đổi nhiệt dạng tấm-vây nhôm, hiện đại diện cho năm nhà sản xuất bộ trao đổi nhiệt dạng tấm-vây nhôm hàn (BAHX) lớn nhất thế giới. Các Tiêu chuẩn ALPEMA là nguồn tham khảo chính cho các kỹ sư làm việc trong bất kỳ lĩnh vực ứng dụng chính nào của BAHX bao gồm kỹ thuật quy trình, hóa học, cơ khí và bảo trì. Các Tiêu chuẩn cũng là một công cụ thông tin tuyệt vời để mua sắm và quản lý dự án. Chúng áp dụng trong suốt vòng đời của dự án từ các nghiên cứu khả thi đến khi đưa vào vận hành và là một yếu tố chính đối với mọi nhà thầu Kỹ thuật, Mua sắm và Xây dựng (EPC).', NULL, NULL, NULL, 'publisher/avatar/033KCDXUHV0KXPQ5TTCR.png', 0),
(4302, 'AMCA - Air Movement and Control Association', 'AMCA - Air Movement and Control Association', 'AMCA International serves the air movement and control industry with certification programs, application manuals, product-rating manuals, test methods and ANSI-approved standards for industrial, commercial, and residential air-handling equipment.\nThe Air Movement and Control Association (AMCA) International Inc. is a non-profit organization that provides its manufacturing members and affiliates with a wide range of resources, knowledge, and expertise related to the air systems industry. We advance the air system industry and its community through advocacy, certification ratings, international standards, laboratory accreditation, compliance verification, and education.\nAMCA International members and staff shall comply with the following Code of Ethics so that the business of the industry may be conducted in a straightforward, fair, and equitable manner to benefit designers, architects, engineers, contractors, purchasers, and AMCA International Members alike. The purposes of this Code of Ethics are to encourage the improvement of the quality of the products of the industry, the improvement of the business conduct of Members, and for the Members to abide by self-imposed rules of good business conduct of mutual benefit to the public and to themselves. All members must sign a pledge to follow this code and make every effort to ensure that:\n1. All representations made to a purchaser or user through advertising, catalogs, or other media are factual and properly descriptive of the performance of the products so advertised and sold.\n2. Any guarantees or warranties made in connection with such products are clearly presented and fair to the purchaser or user.\n3. When it is necessary to substitute products for those designated, the seller will accurately represent its products and take steps to ensure that there is no confusion between the products specified and the products delivered.\n4. Only those products that comply with established test specifications, standards, or codes in all respects can be identified or labeled as conforming thereto.\n5. No efforts will be made to knowingly induce or attempt to induce the breach of existing lawful contracts between competitors and their customers or their suppliers or to defame competitors by falsely impugning their conduct, ability to perform contracts, credit standing, or quality and performance of products.\n6. The hiring or offer of employment to employees of competitors is done in good faith and not for the purpose of injuring, destroying, or preventing competition.\n7. Participation and cooperation engaged in with other Members is for the good of the industry, that decisions are arrived at independently and not from any plan, common course of action, agreement, combination, or conspiracy to fix or maintain the pricing of products, allocation of markets, or restriction of competition or to otherwise violate the antitrust laws of any government.\n8. No representations made to a purchaser or user shall be obfuscated or hidden in order to conceal nonfactual or improper descriptions of the performance of products advertised or sold.\n9. No efforts are made to infringe upon, misuse or misappropriate any patent, trademark, copyright, trade secret, or other commercially proprietary information belonging to any other Member or CRP affiliate.\nThe Air Movement and Control Association International (AMCA International) provides members the lawful opportunity to meet together to transact AMCA International business and to further AMCA International’s legitimate goals. Such lawful activities include the development of performance standards that provide a benefit to the public, the running of certification programs, the petitioning of federal, state, local, or foreign governments on issues that have an impact on AMCA International’s members as a whole, the promotion of the industry, the conducting of educational programs, the provision of statistical reporting, and the conducting of pre-competitive research. Because participants in AMCA International’s meetings are companies with competing, and sometimes opposing economic interests, AMCA International’s actions are subject to close antitrust scrutiny.\noccupational and environmental health and safety (OEHS) in the workplace and community. Founded in 1939, we support our members with our expertise, networks, comprehensive education programs, and other products and services that help them maintain the highest professional and competency standards. More than half of AIHA\'s nearly 8,500 members are Certified Industrial Hygienists, and many hold other professional designations. AIHA serves as a resource for those employed across the public and private sectors and the communities in which they work.', 'AMCA International phục vụ ngành công nghiệp kiểm soát và lưu thông không khí bằng các chương trình chứng nhận, hướng dẫn ứng dụng, hướng dẫn đánh giá sản phẩm, phương pháp thử nghiệm và các tiêu chuẩn được ANSI chấp thuận cho thiết bị xử lý không khí công nghiệp, thương mại và dân dụng.\nHiệp hội Kiểm soát và Lưu thông Không khí (AMCA) International Inc. là một tổ chức phi lợi nhuận cung cấp cho các thành viên sản xuất và chi nhánh của mình nhiều nguồn lực, kiến ​​thức và chuyên môn liên quan đến ngành công nghiệp hệ thống không khí. Chúng tôi thúc đẩy ngành công nghiệp hệ thống không khí và cộng đồng của ngành thông qua hoạt động vận động, đánh giá chứng nhận, tiêu chuẩn quốc tế, công nhận phòng thí nghiệm, xác minh tuân thủ và giáo dục.\nCác thành viên và nhân viên của AMCA International phải tuân thủ Bộ quy tắc đạo đức sau đây để hoạt động kinh doanh của ngành có thể được tiến hành theo cách thẳng thắn, công bằng và bình đẳng, mang lại lợi ích cho các nhà thiết kế, kiến ​​trúc sư, kỹ sư, nhà thầu, người mua và các Thành viên của AMCA International. Mục đích của Bộ quy tắc đạo đức này là khuyến khích cải thiện chất lượng sản phẩm của ngành, cải thiện hành vi kinh doanh của các Thành viên và để các Thành viên tuân thủ các quy tắc tự áp đặt về hành vi kinh doanh tốt, có lợi cho cả công chúng và chính họ. Tất cả các thành viên phải ký cam kết tuân thủ quy tắc này và nỗ lực hết sức để đảm bảo rằng:\n1. Mọi tuyên bố đưa ra cho người mua hoặc người dùng thông qua quảng cáo, danh mục hoặc phương tiện truyền thông khác đều là sự thật và mô tả đúng về hiệu suất của các sản phẩm được quảng cáo và bán như vậy.\n2. Mọi bảo đảm hoặc bảo hành được đưa ra liên quan đến các sản phẩm đó đều được trình bày rõ ràng và công bằng với người mua hoặc người dùng.\n3. Khi cần thay thế các sản phẩm được chỉ định, người bán sẽ tuyên bố chính xác về sản phẩm của mình và thực hiện các bước để đảm bảo không có sự nhầm lẫn giữa các sản phẩm được chỉ định và các sản phẩm được giao.\n4. Chỉ những sản phẩm tuân thủ các thông số kỹ thuật, tiêu chuẩn hoặc quy tắc thử nghiệm đã thiết lập ở mọi khía cạnh mới có thể được xác định hoặc dán nhãn là tuân thủ.\n5. Không có nỗ lực nào được thực hiện để cố ý thúc đẩy hoặc cố gắng thúc đẩy vi phạm các hợp đồng hợp pháp hiện có giữa các đối thủ cạnh tranh và khách hàng hoặc nhà cung cấp của họ hoặc để bôi nhọ đối thủ cạnh tranh bằng cách vu khống hành vi, khả năng thực hiện hợp đồng, uy tín tín dụng hoặc chất lượng và hiệu suất của sản phẩm.\n\n6. Việc thuê hoặc cung cấp việc làm cho nhân viên của đối thủ cạnh tranh được thực hiện một cách thiện chí và không nhằm mục đích gây tổn hại, phá hủy hoặc ngăn cản sự cạnh tranh.\n7. Sự tham gia và hợp tác với các Thành viên khác là vì lợi ích của ngành, rằng các quyết định được đưa ra một cách độc lập và không phải từ bất kỳ kế hoạch, hành động chung, thỏa thuận, kết hợp hoặc âm mưu nào để ấn định hoặc duy trì giá sản phẩm, phân bổ thị trường hoặc hạn chế cạnh tranh hoặc vi phạm luật chống độc quyền của bất kỳ chính phủ nào.\n8. Không được che giấu hoặc làm lu mờ bất kỳ tuyên bố nào được đưa ra cho người mua hoặc người dùng để che giấu các mô tả không đúng sự thật hoặc không phù hợp về hiệu suất của các sản phẩm được quảng cáo hoặc bán.\n9. Không có nỗ lực nào được thực hiện để xâm phạm, sử dụng sai hoặc chiếm đoạt bất kỳ bằng sáng chế, nhãn hiệu, bản quyền, bí mật thương mại hoặc thông tin độc quyền thương mại nào khác thuộc về bất kỳ Thành viên hoặc chi nhánh CRP nào khác.\nHiệp hội Kiểm soát và Di chuyển Hàng không Quốc tế (AMCA International) cung cấp cho các thành viên cơ hội hợp pháp để gặp gỡ nhau để giao dịch kinh doanh của AMCA International và thúc đẩy các mục tiêu hợp pháp của AMCA International. Các hoạt động hợp pháp như vậy bao gồm việc xây dựng các tiêu chuẩn hiệu suất mang lại lợi ích cho công chúng, điều hành các chương trình chứng nhận, kiến ​​nghị lên chính quyền liên bang, tiểu bang, địa phương hoặc nước ngoài về các vấn đề có tác động đến toàn bộ các thành viên của AMCA International, thúc đẩy ngành, tiến hành các chương trình giáo dục, cung cấp báo cáo thống kê và tiến hành nghiên cứu trước khi cạnh tranh. Vì những người tham gia các cuộc họp của AMCA International là các công ty có lợi ích kinh tế cạnh tranh và đôi khi đối lập, nên các hành động của AMCA International phải chịu sự giám sát chặt chẽ của luật chống độc quyền.\nSức khỏe và an toàn nghề nghiệp và môi trường (OEHS) tại nơi làm việc và cộng đồng. Được thành lập vào năm 1939, chúng tôi hỗ trợ các thành viên của mình bằng chuyên môn, mạng lưới, chương trình giáo dục toàn diện và các sản phẩm và dịch vụ khác giúp họ duy trì các tiêu chuẩn chuyên môn và năng lực cao nhất. Hơn một nửa trong số gần 8.500 thành viên của AIHA là Chuyên gia vệ sinh công nghiệp được chứng nhận và nhiều người có các danh hiệu chuyên môn khác. AIHA đóng vai trò là nguồn lực cho những người làm việc trong các khu vực công và tư nhân cũng như cộng đồng nơi họ làm việc.', 'AMCA International phục vụ ngành kiểm soát và lưu thông không khí bằng các chương trình chứng nhận, hướng dẫn ứng dụng, hướng dẫn đánh giá sản phẩm, phương pháp thử nghiệm và các tiêu chuẩn được ANSI chấp thuận cho thiết bị xử lý không khí công nghiệp, thương mại và dân dụng.', NULL, NULL, NULL, 'publisher/avatar/WW0XWS16K527DF2C7M28.jpg', 0),
(4303, 'ANS - American Nuclear Society', 'ANS - American Nuclear Society', 'The American Nuclear Society (ANS) is the premier organization for those that embrace the nuclear sciences and technologies for their vital contributions to improving people’s lives and preserving the planet.\n\nANS membership is open to all and consists of individuals from all walks of life, including engineers, doctors, students, educators, scientists, soldiers, advocates, government employees, and others. Celebrating its 70th anniversary in 2024, ANS is committed to advancing, fostering, and promoting the development and application of nuclear sciences and technologies to benefit society.', 'Hiệp hội Hạt nhân Hoa Kỳ (ANS) là tổ chức hàng đầu dành cho những người ủng hộ khoa học và công nghệ hạt nhân vì những đóng góp quan trọng của chúng trong việc cải thiện cuộc sống của con người và bảo vệ hành tinh.\n\nTư cách thành viên ANS mở cho tất cả mọi người và bao gồm những cá nhân từ mọi tầng lớp xã hội, bao gồm kỹ sư, bác sĩ, sinh viên, nhà giáo dục, nhà khoa học, binh lính, người ủng hộ, nhân viên chính phủ và những người khác. Kỷ niệm 70 năm thành lập vào năm 2024, ANS cam kết thúc đẩy, bồi dưỡng và thúc đẩy sự phát triển và ứng dụng khoa học và công nghệ hạt nhân để mang lại lợi ích cho xã hội.', 'Hiệp hội Hạt nhân Hoa Kỳ (ANS) là tổ chức hàng đầu dành cho những người ủng hộ khoa học và công nghệ hạt nhân vì những đóng góp quan trọng của chúng trong việc cải thiện cuộc sống của con người và bảo vệ hành tinh.', NULL, NULL, '07*27*43.020*53*71', 'publisher/avatar/JIGQQPP8SIG43EU63C2F.png', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4305, 'ANSI/ANSLG - American National Standards Institute / American National Standard Lighting Group', 'ANSI/ANSLG - American National Standards Institute / American National Standard Lighting Group', 'ANSI/ANSLG xác định các yêu cầu và thông số kỹ thuật an toàn cho chiếu sáng chung, được Viện Tiêu chuẩn Quốc gia Hoa Kỳ chấp thuận.\nThe American Nuclear Society (ANS) is the premier organization for those that embrace the nuclear sciences and technologies for their vital contributions to improving people’s lives and preserving the planet.\nANS membership is open to all and consists of individuals from all walks of life, including engineers, doctors, students, educators, scientists, soldiers, advocates, government employees, and others. Celebrating its 70th anniversary in 2024, ANS is committed to advancing, fostering, and promoting the development and application of nuclear sciences and technologies to benefit society.\nThe American Nuclear Society was launched in the mid-1950s, a time of growing interest in employing peaceful applications of nuclear science and technology for bettering the lives of people in the United States and around the world. President Eisenhower had presented his dramatic 1953 \"Atoms for Peace\" speech to the United Nations, proposing international knowledge-sharing for development of civilian nuclear science and technology. While a number of associations already had nuclear divisions or groups, many people felt that a new organization was needed. Following its establishment in 1954 as a not-for-profit association of individual members, the Society quickly added breadth and depth to its activities, resulting in an organization that was both influenced by and had an influence on the burgeoning nuclear field.\nThe name of the organization generated considerable discussion back in 1954. Among the other names suggested were Society of Nuclear Engineering, American Society of Nuclear Technology, Institute of Nuclear Engineering, Association of Nuclear Engineers, Association of Nuclear Science and Technology, and Society of Nuclear Scientists and Engineers. Ultimately (in October 1954) the name American Nuclear Society won the day – and the decades.\nIn the mid-to-late 1950s, ANS was already putting in place many of the elements that still make up the organization. In June 1955 ANS held its first Annual Meeting and elected its first President, in March 1956 launched its first journal (Nuclear Science and Engineering), and in November 1956 formed its Standards Committee. By the end of the 1950s, ANS had three Professional Divisions, 14 Local Sections, and 11 Student Branches.\n\nDuring the 1960s ANS grew rapidly, driven in no small part by the construction of many nuclear plants in the United States and elsewhere for generating electricity, and also by the research in using the technology for a variety of other uses, from aerospace to merchant ships to medicine. By the end of the 1960s, ANS had 12 divisions, 28 local sections, 40 student branches, three periodicals (two journals and a magazine), and was running two national meetings and several topical meetings each year.\nEach succeeding decade has brought changes both to ANS and to nuclear science and technology. In the 1970s, ANS became even more international minded than it already was, and also took its first formal steps in outreach activities. The 1980s became a time of focus on operating the plants, since there were no new U.S. plant orders, and an increased emphasis on radioactive waste management; the U.S. federal government enacted major legislation about both low- and high-level wastes and ANS started its Fuel Cycle and Waste Management Division. In the 1990s, amid consolidation in the industrial area, ANS increased its visibility in Washington, D.C., carried out its first professionally directed strategic planning, and worked on shoring up the supply of qualified people for the nuclear field.\nWhile ANS is national and international in its scope, its headquarters is located in La Grange Park, Illinois (about 10 miles from downtown Chicago). It did not start there, however. As with many associations, ANS moved around some during its early years. ANS\'s first \"home\" was in space provided by the Oak Ridge Institute of Nuclear Studies in Tennessee. In 1958 the headquarters were moved to small offices in downtown Chicago, and in 1964 the headquarters were moved to larger offices spaces in Hinsdale, Illinois. Finally, in 1977 the Society moved to its own headquarters building (owned by ANS) in La Grange Park.\nANS has made, and continues to make, important contributions to the use of nuclear science and technology, and consequently to the larger society beyond ANS. It achieves this through its many products and services, including meetings, publications, standards, outreach, honors and awards, scholarships, teachers workshops, Organization Members, and representation in Washington, D.C.\nANS continues to be a professional organization of scientists, engineers, and other professionals devoted to the peaceful applications of nuclear science and technology. Its more than 10,000 members, from 50+ countries, come from diverse technical disciplines ranging from physics and nuclear safety to operations and power, and from across the full spectrum of the national and international enterprise, including government, academia, research laboratories, and private industry. Making it all succeed are a Board of Directors, 20 standing committees, 19 Professional Divisions, 41 Local Sections, 58 Student Sections, liaison agreements with more than 30 non-U.S. nuclear societies, and a headquarters staff of about 35 people.\nStandards\nFormed in 1957, the ANS Standards Committee has been active in the development of industry standards ever since. All ANS standards receive dual approval from the American National Standards Institute and are thus considered American National Standards. Industry standards are often started to establish safe practices. Once a standard is written and approved, it may influence regulatory guidance. Further, standards developed under voluntary consensus procedures, like those of ANS, often receive wide acceptance in their industry due to the broad representation of experts who worked to create the standard.\nANS standards, as well as the standards of many other organizations and industries, are documents that set forth requirements for the design, manufacture, or operation of a piece of equipment. They can also address computer firmware and software. A standard can address the necessary physical and functional features of equipment, its safe application, or some combination of these. These standards are applied on a voluntary basis. When a standard is adopted by a state or federal agency, then it becomes part of their mandatory code.\nSince its start, ANS has written and approved nearly 150 different standards, and numerous versions of many of those. At present ANS has more than 80 standards that are current American National Standards and many others that are considered historical standards. These technical documents are written, reviewed, and approved by the army of talented volunteers that support our program. ANS has close to 1000 volunteers who provide their experience and expertise to the various levels of standards committees to see that these important documents are written for the industry\'s needs.', 'ANSI/ANSLG xác định các yêu cầu và thông số kỹ thuật an toàn cho chiếu sáng chung, được Viện Tiêu chuẩn Quốc gia Hoa Kỳ chấp thuận.\nHiệp hội Hạt nhân Hoa Kỳ (ANS) là tổ chức hàng đầu dành cho những người ủng hộ khoa học và công nghệ hạt nhân vì những đóng góp quan trọng của chúng trong việc cải thiện cuộc sống của con người và bảo vệ hành tinh.\nTư cách thành viên của ANS mở cửa cho tất cả mọi người và bao gồm các cá nhân từ mọi tầng lớp xã hội, bao gồm kỹ sư, bác sĩ, sinh viên, nhà giáo dục, nhà khoa học, binh lính, người ủng hộ, nhân viên chính phủ và những người khác. Kỷ niệm 70 năm thành lập vào năm 2024, ANS cam kết thúc đẩy, bồi dưỡng và phát triển và ứng dụng khoa học và công nghệ hạt nhân để mang lại lợi ích cho xã hội.\nHiệp hội Hạt nhân Hoa Kỳ được thành lập vào giữa những năm 1950, thời điểm ngày càng quan tâm đến việc sử dụng các ứng dụng hòa bình của khoa học và công nghệ hạt nhân để cải thiện cuộc sống của người dân ở Hoa Kỳ và trên toàn thế giới. Tổng thống Eisenhower đã trình bày bài phát biểu đầy ấn tượng năm 1953 \"Nguyên tử vì hòa bình\" của mình trước Liên hợp quốc, đề xuất chia sẻ kiến thức quốc tế để phát triển khoa học và công nghệ hạt nhân dân sự. Trong khi một số hiệp hội đã có các bộ phận hoặc nhóm hạt nhân, nhiều người cảm thấy rằng cần có một tổ chức mới. Sau khi thành lập vào năm 1954 với tư cách là một hiệp hội phi lợi nhuận gồm các thành viên cá nhân, Hiệp hội đã nhanh chóng mở rộng và nâng cao chiều sâu cho các hoạt động của mình, tạo nên một tổ chức vừa chịu ảnh hưởng vừa có tác động đến lĩnh vực hạt nhân đang phát triển.\nTên của tổ chức đã tạo ra nhiều cuộc thảo luận đáng kể vào năm 1954. Trong số những cái tên khác được đề xuất là Hiệp hội Kỹ thuật Hạt nhân, Hiệp hội Công nghệ Hạt nhân Hoa Kỳ, Viện Kỹ thuật Hạt nhân, Hiệp hội Kỹ sư Hạt nhân, Hiệp hội Khoa học và Công nghệ Hạt nhân và Hiệp hội các Nhà khoa học và Kỹ sư Hạt nhân. Cuối cùng (vào tháng 10 năm 1954), cái tên Hiệp hội Hạt nhân Hoa Kỳ đã giành chiến thắng - và trong nhiều thập kỷ.\nVào giữa đến cuối những năm 1950, ANS đã đưa vào áp dụng nhiều yếu tố vẫn tạo nên tổ chức. Vào tháng 6 năm 1955, ANS đã tổ chức Cuộc họp thường niên đầu tiên và bầu ra Chủ tịch đầu tiên, vào tháng 3 năm 1956 đã ra mắt tạp chí đầu tiên (Khoa học và Kỹ thuật hạt nhân) và vào tháng 11 năm 1956 đã thành lập Ủy ban Tiêu chuẩn. Vào cuối những năm 1950, ANS đã có ba Ban chuyên môn, 14 Ban địa phương và 11 Chi nhánh sinh viên.Trong những năm 1960, ANS phát triển nhanh chóng, một phần không nhỏ là nhờ việc xây dựng nhiều nhà máy điện hạt nhân tại Hoa Kỳ và những nơi khác để sản xuất điện, và cũng nhờ vào việc nghiên cứu sử dụng công nghệ này cho nhiều mục đích sử dụng khác, từ hàng không vũ trụ đến tàu buôn và y học. Đến cuối những năm 1960, ANS đã có 12 bộ phận, 28 chi nhánh địa phương, 40 chi nhánh sinh viên, ba ấn phẩm định kỳ (hai tạp chí và một tạp chí chuyên ngành) và tổ chức hai cuộc họp toàn quốc và một số cuộc họp chuyên đề mỗi năm.\nMỗi thập kỷ tiếp theo đã mang lại những thay đổi cho cả ANS và khoa học và công nghệ hạt nhân. Vào những năm 1970, ANS trở nên có tư duy quốc tế hơn nữa và cũng đã thực hiện những bước đi chính thức đầu tiên trong các hoạt động tiếp cận cộng đồng. Những năm 1980 trở thành thời điểm tập trung vào việc vận hành các nhà máy, vì không có đơn đặt hàng nhà máy mới nào của Hoa Kỳ và ngày càng chú trọng hơn vào việc quản lý chất thải phóng xạ; chính phủ liên bang Hoa Kỳ đã ban hành luật quan trọng về cả chất thải cấp thấp và cấp cao và ANS đã thành lập Ban Quản lý Chất thải và Chu trình Nhiên liệu. Vào những năm 1990, trong bối cảnh hợp nhất trong lĩnh vực công nghiệp, ANS đã tăng cường sự hiện diện của mình tại Washington, D.C., thực hiện kế hoạch chiến lược do chuyên gia chỉ đạo đầu tiên và nỗ lực củng cố nguồn cung ứng nhân lực đủ tiêu chuẩn cho lĩnh vực hạt nhân.\nMặc dù ANS có phạm vi hoạt động trên phạm vi toàn quốc và quốc tế, trụ sở chính của tổ chức này được đặt tại La Grange Park, Illinois (cách trung tâm thành phố Chicago khoảng 10 dặm). Tuy nhiên, tổ chức này không bắt đầu tại đó. Giống như nhiều hiệp hội khác, ANS đã di chuyển một số nơi trong những năm đầu thành lập. \"Ngôi nhà\" đầu tiên của ANS là không gian do Viện Nghiên cứu Hạt nhân Oak Ridge ở Tennessee cung cấp. Năm 1958, trụ sở chính được chuyển đến các văn phòng nhỏ ở trung tâm thành phố Chicago và năm 1964, trụ sở chính được chuyển đến các không gian văn phòng lớn hơn ở Hinsdale, Illinois. Cuối cùng, vào năm 1977, Hiệp hội đã chuyển đến tòa nhà trụ sở riêng của mình (do ANS sở hữu) tại La Grange Park.\nANS đã và đang đóng góp quan trọng vào việc sử dụng khoa học và công nghệ hạt nhân, và do đó đóng góp vào xã hội rộng lớn hơn ngoài ANS. Tổ chức này đạt được điều này thông qua nhiều sản phẩm và dịch vụ của mình, bao gồm các cuộc họp, ấn phẩm, tiêu chuẩn, hoạt động tiếp cận, danh hiệu và giải thưởng, học bổng, hội thảo dành cho giáo viên, Thành viên Tổ chức và đại diện tại Washington, D.C.\nANS tiếp tục là một tổ chức chuyên nghiệp của các nhà khoa học, kỹ sư và các chuyên gia khác cống hiến cho các ứng dụng hòa bình của khoa học và công nghệ hạt nhân. Hơn 10.000 thành viên của tổ chức, đến từ hơn 50 quốc gia, đến từ nhiều ngành kỹ thuật khác nhau, từ vật lý và an toàn hạt nhân đến hoạt động và năng lượng, và từ khắp các lĩnh vực doanh nghiệp quốc gia và quốc tế, bao gồm chính phủ, học viện, phòng thí nghiệm nghiên cứu và ngành công nghiệp tư nhân. Làm cho tất cả thành công là Hội đồng quản trị, 20 ủy ban thường trực, 19 Ban chuyên môn, 41 Chi nhánh địa phương, 58 Chi nhánh sinh viên, các thỏa thuận liên lạc với hơn 30 hiệp hội hạt nhân không phải của Hoa Kỳ và đội ngũ nhân viên trụ sở chính gồm khoảng 35 người.\nTiêu chuẩn\nĐược thành lập vào năm 1957, Ủy ban Tiêu chuẩn ANS đã tích cực phát triển các tiêu chuẩn công nghiệp kể từ đó. Tất cả các tiêu chuẩn ANS đều nhận được sự chấp thuận kép từ Viện Tiêu chuẩn Quốc gia Hoa Kỳ và do đó được coi là Tiêu chuẩn Quốc gia Hoa Kỳ. Các tiêu chuẩn của ngành thường được đưa ra để thiết lập các hoạt động an toàn. Sau khi một tiêu chuẩn được viết và phê duyệt, nó có thể ảnh hưởng đến hướng dẫn về quy định. Hơn nữa, các tiêu chuẩn được xây dựng theo các thủ tục đồng thuận tự nguyện, như tiêu chuẩn của ANS, thường được chấp nhận rộng rãi trong ngành của họ do có sự đại diện rộng rãi của các chuyên gia đã làm việc để tạo ra tiêu chuẩn.\nCác tiêu chuẩn của ANS, cũng như các tiêu chuẩn của nhiều tổ chức và ngành khác, là các tài liệu nêu ra các yêu cầu về thiết kế, sản xuất hoặc vận hành một thiết bị. Chúng cũng có thể giải quyết phần mềm và chương trình cơ sở máy tính. Một tiêu chuẩn có thể giải quyết các tính năng vật lý và chức năng cần thiết của thiết bị, ứng dụng an toàn của thiết bị hoặc một số kết hợp của những tính năng này. Các tiêu chuẩn này được áp dụng trên cơ sở tự nguyện. Khi một tiêu chuẩn được một cơ quan tiểu bang hoặc liên bang thông qua, thì tiêu chuẩn đó sẽ trở thành một phần trong bộ quy tắc bắt buộc của họ.\nKể từ khi thành lập, ANS đã viết và phê duyệt gần 150 tiêu chuẩn khác nhau và nhiều phiên bản của nhiều tiêu chuẩn trong số đó. Hiện tại, ANS có hơn 80 tiêu chuẩn là Tiêu chuẩn Quốc gia Hoa Kỳ hiện hành và nhiều tiêu chuẩn khác được coi là tiêu chuẩn lịch sử. Các tài liệu kỹ thuật này được viết, xem xét và phê duyệt bởi đội ngũ tình nguyện viên tài năng hỗ trợ chương trình của chúng tôi. ANS có gần 1000 tình nguyện viên cung cấp kinh nghiệm và chuyên môn của họ cho các cấp ủy ban tiêu chuẩn khác nhau để đảm bảo rằng các tài liệu quan trọng này được viết cho nhu cầu của ngành.', 'ANSI/ANSLG xác định các yêu cầu và thông số kỹ thuật an toàn cho chiếu sáng chung, được Viện Tiêu chuẩn Quốc gia Hoa Kỳ chấp thuận.', NULL, NULL, NULL, 'publisher/avatar/S37GZKU88CX9V38LU8D4.jpg', 0),
(4306, 'ANSI/NEMA - American National Standards Institute / National Electrical Manufacturers Association', 'ANSI/NEMA - American National Standards Institute / National Electrical Manufacturers Association', 'ANSI/NEMA standards are NEMA publications that have the approval of the American National Standards Institute (ANSI).', 'Hiệp hội các nhà sản xuất điện quốc gia (NEMA) là một hiệp hội thương mại có trụ sở tại Hoa Kỳ đại diện cho lợi ích của các nhà sản xuất thiết bị điện và hình ảnh y tế. NEMA được thành lập vào năm 1926 và đóng vai trò là nền tảng cho sự hợp tác, vận động và tiêu chuẩn hóa trong ngành sản xuất điện.\n\nMục tiêu và hoạt động chính của Hiệp hội các nhà sản xuất điện quốc gia bao gồm:\nĐại diện ngành: NEMA đóng vai trò là tiếng nói của ngành sản xuất điện tại Hoa Kỳ. Hiệp hội đại diện cho lợi ích của các công ty thành viên, bao gồm các nhà sản xuất nhiều loại thiết bị, hệ thống và linh kiện điện. NEMA tham gia với các cơ quan chính phủ, cơ quan quản lý và các bên liên quan khác để ủng hộ các chính sách và quy định hỗ trợ sự tăng trưởng, đổi mới và khả năng cạnh tranh của ngành.\nTiêu chuẩn hóa: NEMA đóng vai trò quan trọng trong việc phát triển và duy trì các tiêu chuẩn cho hệ thống và thiết bị điện. Hiệp hội hợp tác với các chuyên gia trong ngành, cơ quan chính phủ và các tổ chức phát triển tiêu chuẩn khác để thiết lập các tiêu chuẩn kỹ thuật, hướng dẫn và khuyến nghị thực hành. Các tiêu chuẩn này bao gồm các khía cạnh khác nhau của thiết bị điện, bao gồm an toàn, hiệu suất, khả năng tương tác và hiệu quả năng lượng. Tiêu chuẩn NEMA giúp đảm bảo chất lượng sản phẩm, tạo điều kiện tiếp cận thị trường và thúc đẩy tiến bộ công nghệ trong ngành.\nNghiên cứu Thị trường và Phân tích Dữ liệu: NEMA tiến hành nghiên cứu thị trường và thu thập dữ liệu ngành để cung cấp những hiểu biết có giá trị về lĩnh vực sản xuất điện. Hiệp hội thu thập thông tin về xu hướng thị trường, lô hàng sản phẩm và các chỉ số kinh tế để hỗ trợ các công ty thành viên đưa ra quyết định kinh doanh sáng suốt. Dữ liệu và phân tích thị trường của NEMA giúp xác định các cơ hội mới nổi, đánh giá nhu cầu thị trường và hỗ trợ lập kế hoạch chiến lược trong ngành.\nVận động và Giáo dục: NEMA ủng hộ các chính sách và sáng kiến nhằm nâng cao lợi ích của ngành sản xuất điện. Hiệp hội tích cực tham gia với các nhà hoạch định chính sách, nhà quản lý và nhà lập pháp để thúc đẩy các vấn đề liên quan đến hiệu quả năng lượng, tính bền vững, an toàn sản phẩm và tiếp cận thị trường. NEMA cũng cung cấp các tài nguyên giáo dục, chương trình đào tạo và hội thảo để phổ biến kiến thức và phương pháp thực hành tốt nhất cho các chuyên gia trong ngành.\nKết nối và cộng tác: NEMA cung cấp nền tảng kết nối và cộng tác giữa các bên liên quan trong ngành. Hiệp hội tổ chức các hội nghị, cuộc họp và sự kiện để các nhà sản xuất, nhà cung cấp và chuyên gia trong ngành có thể kết nối, trao đổi ý tưởng và thúc đẩy quan hệ đối tác. Các thành viên NEMA có cơ hội hợp tác trong các dự án nghiên cứu, sáng kiến công nghiệp và hoạt động phát triển tiêu chuẩn.\n\nThông qua các hoạt động của mình, Hiệp hội các nhà sản xuất điện quốc gia (NEMA) hỗ trợ sự tăng trưởng, đổi mới và khả năng cạnh tranh của ngành sản xuất điện tại Hoa Kỳ. Hiệp hội đóng một vai trò quan trọng trong việc đại diện, tiêu chuẩn hóa, nghiên cứu thị trường, vận động và giáo dục trong lĩnh vực sản xuất điện.', 'NEMA là tổ chức thương mại lớn nhất của Hoa Kỳ đại diện cho các nhà SX các sản phẩm điện. Tiêu chuẩn của NEMA đã được chấp nhận thành Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) hoặc được chính phủ liên bang thông qua.', 'NEMA,ANSI/NEMA,NEMA/ISO,AWS/NEMA', 'NEMA, Hội các Nhà sản xuất Điện Quốc gia (NEMA), National Electrical Manufacturers Association (NEMA), Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', NULL, 'publisher/avatar/P27FUZ81IE0TLJOW98DZ.jpg', 0),
(4307, 'ANSI/TCNA - Tile Council of North America, Inc.', 'ANSI/TCNA - Tile Council of North America, Inc.', 'TCNA is a trade association representing manufacturers of ceramic tile, tile installation materials, tile equipment, raw materials, and other tile-related products.\nTCNA, Tile Council of North America, Inc., is a nonprofit organization that develops and publishes standards for the tiling industry. Headquartered in Anderson, United States, TCNA standards are used by its over 200 member companies, representing 90% of ceramic tile production in North America. TCNA also serves as the administrator for the U.S. TAG (United States Technical Advisory Group) to ISO/TC 189 (International Organization for Standardization/Technical Committee).', 'TCNA là một hiệp hội thương mại đại diện cho các nhà sản xuất gạch men, vật liệu lắp đặt gạch, thiết bị ốp lát, nguyên liệu thô và các sản phẩm liên quan đến gạch khác.\nTCNA, Tile Council of North America, Inc., là một tổ chức phi lợi nhuận phát triển và công bố các tiêu chuẩn cho ngành công nghiệp ốp lát. Có trụ sở chính tại Anderson, Hoa Kỳ, các tiêu chuẩn TCNA được hơn 200 công ty thành viên sử dụng, đại diện cho 90% sản lượng gạch men tại Bắc Mỹ. TCNA cũng đóng vai trò là đơn vị quản lý cho U.S. TAG (Nhóm tư vấn kỹ thuật Hoa Kỳ) theo ISO/TC 189 (Tổ chức tiêu chuẩn hóa/Ủy ban kỹ thuật quốc tế).', 'TCNA là một hiệp hội thương mại đại diện cho các nhà sản xuất gạch men, vật liệu lắp đặt gạch, thiết bị ốp lát, nguyên liệu thô và các sản phẩm liên quan đến gạch khác.', NULL, NULL, NULL, 'publisher/avatar/GMW86D6KZY3TO3GLCLHX.png', 0),
(4308, 'ANSI/UAMA - Unified Abrasives Manufacturers\' Association', 'ANSI/UAMA - Unified Abrasives Manufacturers\' Association', 'UAMA was established in 1999 as a non-profit business association that develops standards to support the design and production of abrasives. Technical experts from related industries and UAMA members create and maintain industry standards to ensure the quality of abrasive products.\nUAMA was established in 1999 as a non-profit business association that develops standards to support the design and production of abrasives. Technical experts from related industries and UAMA members create and maintain industry standards to ensure the quality of abrasive products.\nIt is also our mission to support the safe use of abrasive products. The UAMA website has resources such as a Safety Guide for Grinding Wheels and information on the Shelf Life of grinding wheels, abrasive discs, and abrasive belts. For more detailed safety information, please see publication B7.1-2017, American National Standard Safety Requirements for the Use, Care and Protection of Abrasive Wheels.', 'UAMA được thành lập vào năm 1999 với tư cách là một hiệp hội kinh doanh phi lợi nhuận phát triển các tiêu chuẩn để hỗ trợ thiết kế và sản xuất chất mài mòn. Các chuyên gia kỹ thuật từ các ngành liên quan và các thành viên của UAMA tạo ra và duy trì các tiêu chuẩn của ngành để đảm bảo chất lượng của các sản phẩm mài mòn.\nUAMA được thành lập vào năm 1999 với tư cách là một hiệp hội kinh doanh phi lợi nhuận phát triển các tiêu chuẩn để hỗ trợ thiết kế và sản xuất chất mài mòn. Các chuyên gia kỹ thuật từ các ngành liên quan và các thành viên của UAMA tạo ra và duy trì các tiêu chuẩn của ngành để đảm bảo chất lượng của các sản phẩm mài mòn.\nSứ mệnh của chúng tôi cũng là hỗ trợ việc sử dụng an toàn các sản phẩm mài mòn. Trang web của UAMA có các nguồn tài nguyên như Hướng dẫn an toàn cho bánh mài và thông tin về Thời hạn sử dụng của bánh mài, đĩa mài và đai mài mòn. Để biết thông tin an toàn chi tiết hơn, vui lòng xem ấn phẩm B7.1-2017, Yêu cầu an toàn theo Tiêu chuẩn quốc gia Hoa Kỳ về việc sử dụng, chăm sóc và bảo vệ bánh mài.', 'UAMA được thành lập vào năm 1999 với tư cách là một hiệp hội kinh doanh phi lợi nhuận phát triển các tiêu chuẩn để hỗ trợ thiết kế và sản xuất chất mài mòn. Các chuyên gia kỹ thuật từ các ngành liên quan và các thành viên của UAMA tạo ra và duy trì các tiêu chuẩn của ngành để đảm bảo chất lượng của các sản phẩm mài mòn.', NULL, NULL, NULL, 'publisher/avatar/03LSVLNXSDDN9IWFX4S8.jpg', 0),
(4309, 'API - American Petroleum Institute', 'API - American Petroleum Institute', 'API is a leader in the development of petroleum and petrochemical equipment and operating standards covering topics that range from drill bits to environmental protection. These embrace proven, sound engineering and operating practices and safe, interchangeable equipment and materials. Many have been incorporated into state and federal regulations and adopted by ISO for worldwide acceptance.', 'Viện Dầu khí Hoa Kỳ (American Petroleum Institute - API) là một tổ chức thương mại và ngành nghề trong ngành dầu khí. API được thành lập vào năm 1919 và có trụ sở chính tại Washington, D.C., Hoa Kỳ. Tổ chức này đại diện cho ngành công nghiệp dầu khí Hoa Kỳ và có vai trò quan trọng trong việc phát triển và thúc đẩy các tiêu chuẩn kỹ thuật, quy định và các quy trình liên quan đến ngành dầu khí.\n\nAPI được biết đến như một cơ quan tiêu chuẩn hàng đầu trong ngành dầu khí. Tổ chức này phát triển và công bố các tiêu chuẩn kỹ thuật và quy định để đảm bảo an toàn, bảo vệ môi trường và thúc đẩy sự hiệu quả trong các hoạt động như khai thác, sản xuất, vận chuyển và sử dụng các nguồn tài nguyên dầu mỏ và khí tự nhiên.\n\nAPI cũng đóng vai trò quan trọng trong việc đại diện cho ngành công nghiệp dầu khí Hoa Kỳ và bảo vệ lợi ích của các công ty thành viên trước các quy định và chính sách của chính phủ. Tổ chức này thường tham gia vào quá trình xây dựng luật pháp, tham gia vào các cuộc thảo luận và tiếp xúc với các cơ quan chính phủ và quốc tế liên quan đến ngành dầu khí.\n\nNgoài ra, API cung cấp các dịch vụ khác như đào tạo và giáo dục, nghiên cứu và phân tích, và công bố các báo cáo và thông tin thị trường liên quan đến ngành dầu khí.\n\nAPI có một số thành viên là các công ty trong ngành dầu khí, bao gồm các công ty sản xuất dầu mỏ và khí tự nhiên, các công ty khai thác và vận chuyển dầu mỏ và khí tự nhiên, các công ty dịch vụ dầu khí và các tổ chức liên quan khác.\n\nTóm lại, American Petroleum Institute (API) là một tổ chức quan trọng trong ngành dầu khí, đóng vai trò trong việc phát triển tiêu chuẩn kỹ thuật, quy định và quy trình, đại diện cho ngành công nghiệp dầu khí và cung cấp các dịch vụ và thông tin liên quan đến ngành này.', 'API đại diện cho ngành công nghiệp dầu khí Hoa Kỳ và có vai trò quan trọng trong việc phát triển và thúc đẩy các tiêu chuẩn kỹ thuật, quy định và các quy trình liên quan đến ngành dầu khí.', 'API,API/EI,API/IP,API/ANSI', 'API, Tiêu chuẩn của Viện Dầu khí Hoa Kỳ (API), American Petroleum Institute (API), Dầu khí, Tiêu chuẩn dầu khí', NULL, 'publisher/avatar/40OOVZY44SU48DB1CWU1.jpg', 0),
(4310, 'APWA - American Public Works Association', 'APWA - American Public Works Association', 'The American Public Works Association (APWA) serves professionals in all aspects of public works--a fact that sets it apart from other organizations and makes it an effective voice of public works throughout North America. With a worldwide membership more than 30,000 strong, APWA includes not only personnel from local, county, state/province, and federal agencies, but also private sector personnel who supply products and services to those professionals.\r\nAPWA serves professionals in all aspects of public works—a fact that sets it apart from other organizations and makes it an effective voice of public works throughout North America. With a worldwide membership of more than 32,000, APWA includes not only personnel from local, county, state/province, and federal agencies, but also private sector personnel who supply products and services to those professionals. Membership in APWA is open to any individual, agency, or corporation with an interest in public works and infrastructure issues.\r\nAPWA is a not-for-profit, 501(c)(3) organization that prides itself on its ability to provide varied educational and networking opportunities that help public works personnel grow in their professionalism and improve the quality of life in the communities they serve.', 'Hiệp hội Công trình Công cộng Hoa Kỳ (APWA) phục vụ các chuyên gia trong mọi khía cạnh của công trình công cộng - một thực tế khiến tổ chức này khác biệt so với các tổ chức khác và trở thành tiếng nói hiệu quả của công trình công cộng trên khắp Bắc Mỹ. Với hơn 30.000 thành viên trên toàn thế giới, APWA không chỉ bao gồm nhân sự từ các cơ quan địa phương, quận, tiểu bang/tỉnh và liên bang mà còn có cả nhân sự khu vực tư nhân cung cấp sản phẩm và dịch vụ cho những chuyên gia đó.\r\nAPWA phục vụ các chuyên gia trong mọi khía cạnh của công trình công cộng - một thực tế khiến tổ chức này khác biệt so với các tổ chức khác và trở thành tiếng nói hiệu quả của công trình công cộng trên khắp Bắc Mỹ. Với hơn 32.000 thành viên trên toàn thế giới, APWA không chỉ bao gồm nhân sự từ các cơ quan địa phương, quận, tiểu bang/tỉnh và liên bang mà còn có cả nhân sự khu vực tư nhân cung cấp sản phẩm và dịch vụ cho những chuyên gia đó. Tư cách thành viên của APWA mở cho bất kỳ cá nhân, cơ quan hoặc tập đoàn nào quan tâm đến các vấn đề về công trình công cộng và cơ sở hạ tầng.\r\nAPWA là một tổ chức phi lợi nhuận, 501(c)(3) tự hào về khả năng cung cấp nhiều cơ hội giáo dục và kết nối đa dạng giúp nhân viên công trình công cộng phát triển tính chuyên nghiệp và cải thiện chất lượng cuộc sống trong cộng đồng mà họ phục vụ.', 'Hiệp hội Công trình Công cộng Hoa Kỳ (APWA) phục vụ các chuyên gia trong mọi khía cạnh của công trình công cộng - một thực tế khiến tổ chức này khác biệt so với các tổ chức khác và trở thành tiếng nói hiệu quả của công trình công cộng trên khắp Bắc Mỹ. Với hơn 30.000 thành viên trên toàn thế giới, APWA không chỉ bao gồm nhân sự từ các cơ quan địa phương, quận, tiểu bang/tỉnh và liên bang mà còn có cả nhân sự khu vực tư nhân cung cấp sản phẩm và dịch vụ cho những chuyên gia đó.', '', '', '', 'publisher/avatar/V0GGMZ2FVAON9FIHXD1Y.png', 1),
(4311, 'AREMA - American Railway Engineering and Maintenance-of-Way Association', 'AREMA - American Railway Engineering and Maintenance-of-Way Association', 'AREMA standards including the Manual for Railway Engineering (Fixed Properties), and Trackwork Plans. These publications cover items such as: ballast, ties, timber, concrete and steel structures, railway crossings, yards and terminals, waterproofing and maintenance, and track layouts\nAREMA is a professional association for railway engineering personnel that offers numerous educational opportunities and produces and publishes the recommended practices for railway engineering infrastructure including track, structures and communications & signals. AREMA is comprised of approximately 5,500 members all working together to further the development and advancement of both technical and practical knowledge of the industry.\nMission\nThe development and advancement of both technical and practical knowledge and recommended practices pertaining to the design, construction and maintenance of railway infrastructure.\nJoining a Technical Committee is the starting point for involvement in the Association and an opportunity for lifelong growth in the industry. AREMA has 30 Technical Committees covering a broad spectrum of railway engineering specialties. Build your network of contacts, sharpen your leadership skills, learn from other members, and maximize your membership investment. Join a Technical Committee today!', 'Tiêu chuẩn AREMA bao gồm Sổ tay Kỹ thuật Đường sắt (Thuộc tính Cố định) và Kế hoạch Đường ray. Các ấn phẩm này bao gồm các mục như: đá dăm, tà vẹt, gỗ, kết cấu bê tông và thép, đường ngang đường sắt, sân ga và nhà ga, chống thấm và bảo trì, và bố trí đường ray\nAREMA là một hiệp hội chuyên nghiệp dành cho nhân viên kỹ thuật đường sắt, cung cấp nhiều cơ hội giáo dục và biên soạn cũng như xuất bản các thông lệ được khuyến nghị cho cơ sở hạ tầng kỹ thuật đường sắt bao gồm đường ray, kết cấu và thông tin liên lạc & tín hiệu. AREMA bao gồm khoảng 5.500 thành viên cùng nhau làm việc để thúc đẩy sự phát triển và nâng cao kiến ​​thức kỹ thuật và thực tiễn của ngành.\nSứ mệnh\nSự phát triển và nâng cao kiến ​​thức kỹ thuật và thực tiễn cũng như các thông lệ được khuyến nghị liên quan đến thiết kế, xây dựng và bảo trì cơ sở hạ tầng đường sắt.\nTham gia Ủy ban Kỹ thuật là điểm khởi đầu để tham gia Hiệp hội và là cơ hội để phát triển lâu dài trong ngành. AREMA có 30 Ủy ban Kỹ thuật bao gồm nhiều chuyên ngành kỹ thuật đường sắt. Xây dựng mạng lưới liên lạc của bạn, rèn luyện kỹ năng lãnh đạo, học hỏi từ các thành viên khác và tối đa hóa khoản đầu tư thành viên của bạn. Tham gia Ủy ban Kỹ thuật ngay hôm nay!', 'Tiêu chuẩn AREMA bao gồm Sổ tay Kỹ thuật Đường sắt (Thuộc tính Cố định) và Kế hoạch Đường ray. Các ấn phẩm này bao gồm các mục như: đá dăm, tà vẹt, gỗ, kết cấu bê tông và thép, đường ngang đường sắt, sân ga và nhà ga, chống thấm và bảo trì, và bố trí đường ray', NULL, NULL, NULL, 'publisher/avatar/Z7YMB57SIAKG2GIVECJO.jpg', 0),
(4312, 'ARINC - Aeronautical Radio Incorporated', 'ARINC - Aeronautical Radio Incorporated', 'Aeronautical Radio, Incorporated (ARINC), established in 1929, was a major provider of transport communications and systems engineering solutions for eight industries: aviation, airports, defense, government, healthcare, networks, security, and transportation. ARINC had installed computer data networks in police cars and railroad cars and also maintains the standards for line-replaceable units.\nARINC was formerly headquartered in Annapolis, Maryland, and had two regional headquarters in London, established in 1999 to serve the Europe, Middle East, and Africa region, and Singapore, established in 2003 for the Asia Pacific region. ARINC had more than 3,200 employees at over 120 locations worldwide.\nThe sale of the company by Carlyle Group to Rockwell Collins was completed on December 23, 2013, and from November 2018 onward operates as part of Collins Aerospace.\nARINC Standards (Aeronautical Radio Incorporated) are published by the US-based SAE Industry Technologies Consortia (SAE ITC®), an affiliate of SAE International®. SAE\'s membership is comprised of public and private organizations collaborating in a neutral forum with the aim of driving innovative solutions to key industry challenges.\n\"ARINC Industry Activities\", a program of SAE ITC, organizes the activities of the groups AEEC, AMC, and FSEMC to cooperatively establish consensus-based, voluntary aviation technical standards which no one organization could develop on its own. ARINC Standards describe avionics, cabin systems, protocols and interfaces for more than 10,000 types of aircraft used throughout the world.', 'Aeronautical Radio, Incorporated (ARINC), được thành lập vào năm 1929, là nhà cung cấp chính các giải pháp kỹ thuật hệ thống và truyền thông vận tải cho tám ngành: hàng không, sân bay, quốc phòng, chính phủ, chăm sóc sức khỏe, mạng lưới, an ninh và vận tải. ARINC đã lắp đặt mạng dữ liệu máy tính trong xe cảnh sát và toa tàu hỏa và cũng duy trì các tiêu chuẩn cho các đơn vị có thể thay thế đường dây.\nARINC trước đây có trụ sở chính tại Annapolis, Maryland và có hai trụ sở khu vực tại London, được thành lập vào năm 1999 để phục vụ khu vực Châu Âu, Trung Đông và Châu Phi, và Singapore, được thành lập vào năm 2003 cho khu vực Châu Á - Thái Bình Dương. ARINC có hơn 3.200 nhân viên tại hơn 120 địa điểm trên toàn thế giới.\nViệc bán công ty của Carlyle Group cho Rockwell Collins đã hoàn tất vào ngày 23 tháng 12 năm 2013 và từ tháng 11 năm 2018 trở đi hoạt động như một phần của Collins Aerospace.\nTiêu chuẩn ARINC (Aeronautical Radio Incorporated) được công bố bởi SAE Industry Technologies Consortia (SAE ITC®) có trụ sở tại Hoa Kỳ, một chi nhánh của SAE International®. Thành viên của SAE bao gồm các tổ chức công và tư hợp tác trong một diễn đàn trung lập với mục đích thúc đẩy các giải pháp sáng tạo cho những thách thức chính của ngành.\n\"ARINC Industry Activities\", một chương trình của SAE ITC, tổ chức các hoạt động của các nhóm AEEC, AMC và FSEMC để hợp tác thiết lập các tiêu chuẩn kỹ thuật hàng không tự nguyện dựa trên sự đồng thuận mà không một tổ chức nào có thể tự mình phát triển. Tiêu chuẩn ARINC mô tả hệ thống điện tử hàng không, hệ thống cabin, giao thức và giao diện cho hơn 10.000 loại máy bay được sử dụng trên toàn thế giới.', 'Aeronautical Radio, Incorporated (ARINC), được thành lập vào năm 1929, là nhà cung cấp chính các giải pháp kỹ thuật hệ thống và truyền thông vận tải cho tám ngành: hàng không, sân bay, quốc phòng, chính phủ, chăm sóc sức khỏe, mạng lưới, an ninh và vận tải. ARINC đã lắp đặt mạng dữ liệu máy tính trong xe cảnh sát và toa tàu hỏa và cũng duy trì các tiêu chuẩn cho các đơn vị có thể thay thế đường dây.', NULL, NULL, NULL, 'publisher/avatar/HETGI0EFPE9U2BH0FNHR.jpg', 0),
(4313, 'ARMY - United States Army Publication', 'ARMY - United States Army Publication', 'ARMY - United States Army Publication', NULL, NULL, NULL, NULL, NULL, 'publisher/avatar/31RAOZBSS5W73ULME9A8.jpg', 0),
(4314, 'AS - Standards Australia', 'AS - Standards Australia', 'Standards Australia is an independent, not-for-profit organization recognized by the Australian Government as the peak non-government Standards body in Australia. The organization develops internationally aligned Australian Standards that enhance the nation\'s economic efficiency, international competitiveness and contribution to community demand for a safe and sustainable environment. Standards Australia is the Australian member of ISO and IEC.', 'Tiêu chuẩn quốc gia Úc được quản lý bởi Cơ quan Tiêu chuẩn Quốc gia Úc (Standards Australia). Standards Australia là một cơ quan phi chính phủ có trách nhiệm phát triển và quản lý tiêu chuẩn quốc gia tại Úc.\n\nStandards Australia hoạt động như một tổ chức phi lợi nhuận và là thành viên của Tổ chức Tiêu chuẩn Quốc tế (ISO) và Liên minh Tiêu chuẩn Quốc gia (IANSA). Công việc của Standards Australia bao gồm phát triển, xem xét và công bố các tiêu chuẩn quốc gia mới, cũng như thực hiện quản lý và cập nhật các tiêu chuẩn hiện có.\n\nĐể tìm hiểu về tiêu chuẩn quốc gia Úc và các tiêu chuẩn cụ thể, bạn có thể truy cập trang web chính thức của Standards Australia tại địa chỉ: https://www.standards.org.au/. Trang web này cung cấp thông tin về các tiêu chuẩn hiện hành, quy trình đề xuất tiêu chuẩn mới, cơ quan chứng nhận và các dịch vụ khác liên quan đến tiêu chuẩn tại Úc.\n\nNgoài ra, bạn cũng có thể tìm hiểu về các tiêu chuẩn quốc gia Úc thông qua các tổ chức và cơ quan liên quan khác như các bộ ngành chính phủ, hiệp hội ngành công nghiệp hoặc các cơ quan chứng nhận độc lập.', 'AS (Australian Standard) là hệ thống tiêu chuẩn quốc gia của Úc. Được quản lý bởi Tiêu chuẩn Úc (Standards Australia), AS là một tập hợp các tiêu chuẩn kỹ thuật áp dụng cho nhiều lĩnh vực khác nhau', 'AS', 'Tiêu chuẩn Quốc gia Úc, Australian Standard, AS standard, AS', NULL, 'publisher/avatar/RRJOUGHPZF9P9P1TETT6.jpg', 0),
(4315, 'ASA - Acoustical Society of America Standards', 'ASA - Acoustical Society of America Standards', 'The Acoustical Society of America (ASA) is an international scientific society founded in 1929 dedicated to generating, disseminating and promoting the knowledge of acoustics and its practical applications. The Society is primarily a voluntary organization of about 7500 members and attracts the interest, commitment, and service of many professionals.\nIn the summer of 1928, Floyd R. Watson and Wallace Waterfall (1900–1974), a former doctoral student of Watson, were invited by UCLA\'s Vern Oliver Knudsen to an evening dinner at Knudsen\'s beach club[4] in Santa Monica.[3] The three physicists decided to form a society of acoustical engineers interested in architectural acoustics. In the early part of December 1928, Wallace Waterfall sent letters to sixteen people inquiring about the possibility of organizing such a society. Harvey Fletcher offered the use of the Bell Telephone Laboratories at 463 West Street in Manhattan as a meeting place for an organizational, initial meeting to be held on December 27, 1928. The meeting was attended by forty scientists and engineers who started the Acoustical Society of America (ASA). Temporary officers were elected: Harvey Fletcher as president, V. O. Knudsen as vice-president, Wallace Waterfall as secretary, and Charles Fuller Stoddard (1876–1958) as treasurer. A constitution and by-laws were drafted. The first issue of the Journal of the Acoustical Society of America was published in October 1929.\nThe Society has 13 technical committees that represent specialized interests in the field of acoustics. The committees organize technical sessions at conferences and are responsible for the representation of their sub-field in ASA publications. ]The committees include:\n• Acoustical oceanography\n• Animal bioacoustics\n• Architectural acoustics\n• Biomedical acoustics\n• Computational acoustics (Technical Specialty Group)\n• Acoustical engineering\n• Musical acoustics\n• Noise\n• Physical acoustics\n• Psychoacoustics\n• Signal processing in acoustics\n• Speech communication\n• Structural acoustics and vibration\n• Underwater acoustics', 'Hội Âm học Hoa Kỳ (ASA) là một hội khoa học quốc tế được thành lập vào năm 1929, chuyên tạo ra, phổ biến và thúc đẩy kiến ​​thức về âm học và các ứng dụng thực tế của nó. Hội chủ yếu là một tổ chức tự nguyện với khoảng 7500 thành viên và thu hút sự quan tâm, cam kết và dịch vụ của nhiều chuyên gia.\nVào mùa hè năm 1928, Floyd R. Watson và Wallace Waterfall (1900–1974), một cựu nghiên cứu sinh tiến sĩ của Watson, được Vern Oliver Knudsen của UCLA mời đến một bữa tối tại câu lạc bộ bãi biển của Knudsen[4] ở Santa Monica.[3] Ba nhà vật lý đã quyết định thành lập một hội các kỹ sư âm học quan tâm đến âm học kiến ​​trúc. Vào đầu tháng 12 năm 1928, Wallace Waterfall đã gửi thư cho mười sáu người để hỏi về khả năng tổ chức một hội như vậy. Harvey Fletcher đề nghị sử dụng Phòng thí nghiệm Điện thoại Bell tại số 463 West Street ở Manhattan làm nơi họp cho cuộc họp đầu tiên của tổ chức sẽ được tổ chức vào ngày 27 tháng 12 năm 1928. Cuộc họp có sự tham dự của bốn mươi nhà khoa học và kỹ sư, những người đã thành lập Hiệp hội Âm học Hoa Kỳ (ASA). Các viên chức tạm thời được bầu: Harvey Fletcher làm chủ tịch, V. O. Knudsen làm phó chủ tịch, Wallace Waterfall làm thư ký và Charles Fuller Stoddard (1876–1958) làm thủ quỹ. Một bản hiến chương và điều lệ đã được soạn thảo. Ấn bản đầu tiên của Tạp chí Hiệp hội Âm học Hoa Kỳ được xuất bản vào tháng 10 năm 1929.\nHiệp hội có 13 ủy ban kỹ thuật đại diện cho các lợi ích chuyên môn trong lĩnh vực âm học. Các ủy ban tổ chức các phiên họp kỹ thuật tại các hội nghị và chịu trách nhiệm đại diện cho lĩnh vực phụ của mình trong các ấn phẩm của ASA. ]Các ủy ban bao gồm:\n• Hải dương học âm học\n• Sinh học âm học động vật\n• Âm học kiến ​​trúc\n• Âm học y sinh\n• Âm học tính toán (Nhóm chuyên ngành kỹ thuật)\n• Kỹ thuật âm học\n• Âm học âm nhạc\n• Tiếng ồn\n• Âm học vật lý\n• Tâm lý âm học\n• Xử lý tín hiệu trong âm học\n• Giao tiếp bằng lời nói\n• Âm học cấu trúc và rung động\n• Âm học dưới nước', 'Hội Âm học Hoa Kỳ (ASA) là một hội khoa học quốc tế được thành lập vào năm 1929, chuyên tạo ra, phổ biến và thúc đẩy kiến ​​thức về âm học và các ứng dụng thực tế của nó. Hội chủ yếu là một tổ chức tự nguyện với khoảng 7500 thành viên và thu hút sự quan tâm, cam kết và dịch vụ của nhiều chuyên gia.', NULL, NULL, NULL, 'publisher/avatar/3P1OX7V9LA4WBHO1HMQD.png', 0),
(4316, 'ASAE/ASABE - The American Society of Agricultural and Biological Engineers', 'ASAE/ASABE - The American Society of Agricultural and Biological Engineers', 'The American Society of Agricultural and Biological Engineers (ASABE) is an international professional society devoted to agricultural and biological engineering. It was founded in December 1907 at the University of Wisconsin–Madison as the American Society of Agricultural Engineers (ASAE) and is now based in St. Joseph, Michigan. Today the organization has about 9,000 members in over 100 countries.[citation needed] ASABE serves many functions: it provides a forum for communication of research findings through conferences, scientific journals, and a magazine; it develops standards of practice; it provides opportunities for members to network. It cooperates with the Alpha Epsilon honor society.\nAfter years of debate, members of the organization voted in 2005 to modify the name to better reflect the changes in the profession.[citation needed] For many years, the discipline had broadened to include engineering for biological systems, and the name change simply reflected this reality. Most of the university departments of agricultural engineering had already changed their names. The increase in biological engineering led to a number of breakthroughs that greatly affected the global agriculture system of modern society. Genetically modified organisms for instance have led to massive overhauls in food production, logistics and trade.\nASABE is the lead society in ABET evaluation for agricultural and biological academic program evaluation in the United States. It is a cooperating society for bioengineering/biomedical, environmental engineering and healthcare engineering technology.\nASABE encourages engineering excellence through professional licensure. The society\'s committee on licensure maintains and enhances the professionalism of the members of ASABE by providing services related to the national Principles and Practices Examination (PE Exam) for agricultural and biological engineering.\nOrganization\nASABE comprises eight technical communities that advance the mission of the organization through publishing, continuing professional development, and standards development: Applied Science and Engineering Energy Systems Ergonomics, Safety, and Health Information Technology, Sensors, and Control Systems Machinery Systems Natural Resources and Environment Systems Plant, Animal and Facility Systems Processing Systems', 'Hiệp hội Kỹ sư Nông nghiệp và Sinh học Hoa Kỳ (ASABE) là một hiệp hội chuyên nghiệp quốc tế dành riêng cho kỹ thuật nông nghiệp và sinh học. Hiệp hội được thành lập vào tháng 12 năm 1907 tại Đại học Wisconsin–Madison với tên gọi là Hiệp hội Kỹ sư Nông nghiệp Hoa Kỳ (ASAE) và hiện có trụ sở tại St. Joseph, Michigan. Ngày nay, tổ chức này có khoảng 9.000 thành viên tại hơn 100 quốc gia.[cần dẫn nguồn] ASABE phục vụ nhiều chức năng: cung cấp diễn đàn để truyền đạt các phát hiện nghiên cứu thông qua các hội nghị, tạp chí khoa học và tạp chí; phát triển các tiêu chuẩn thực hành; tạo cơ hội cho các thành viên kết nối mạng. Hiệp hội hợp tác với hội danh dự Alpha Epsilon.\nSau nhiều năm tranh luận, các thành viên của tổ chức đã bỏ phiếu vào năm 2005 để sửa đổi tên nhằm phản ánh tốt hơn những thay đổi trong nghề.[cần dẫn nguồn] Trong nhiều năm, ngành này đã mở rộng để bao gồm cả kỹ thuật cho các hệ thống sinh học và việc đổi tên chỉ đơn giản phản ánh thực tế này. Hầu hết các khoa kỹ thuật nông nghiệp của trường đại học đã đổi tên. Sự gia tăng của kỹ thuật sinh học đã dẫn đến một số đột phá ảnh hưởng lớn đến hệ thống nông nghiệp toàn cầu của xã hội hiện đại. Ví dụ, các sinh vật biến đổi gen đã dẫn đến những thay đổi lớn trong sản xuất thực phẩm, hậu cần và thương mại.\nASABE là hiệp hội dẫn đầu trong đánh giá ABET về đánh giá chương trình học thuật về nông nghiệp và sinh học tại Hoa Kỳ. Đây là hiệp hội hợp tác về công nghệ kỹ thuật sinh học/y sinh, kỹ thuật môi trường và kỹ thuật chăm sóc sức khỏe.\nASABE khuyến khích sự xuất sắc về kỹ thuật thông qua cấp phép hành nghề. Ủy ban cấp phép của hiệp hội duy trì và nâng cao tính chuyên nghiệp của các thành viên ASABE bằng cách cung cấp các dịch vụ liên quan đến Kỳ thi Nguyên tắc và Thực hành quốc gia (Kỳ thi PE) về kỹ thuật nông nghiệp và sinh học.\nTổ chức\nASABE bao gồm tám cộng đồng kỹ thuật thúc đẩy sứ mệnh của tổ chức thông qua việc xuất bản, phát triển chuyên môn liên tục và phát triển tiêu chuẩn: Khoa học ứng dụng và Kỹ thuật Hệ thống năng lượng Công thái học, An toàn và Sức khỏe Công nghệ thông tin, Cảm biến và Hệ thống điều khiển Hệ thống máy móc Hệ thống tài nguyên thiên nhiên và môi trường Hệ thống thực vật, động vật và cơ sở Hệ thống xử lý', 'Hiệp hội Kỹ sư Nông nghiệp và Sinh học Hoa Kỳ (ASABE) là một hiệp hội chuyên nghiệp quốc tế dành riêng cho kỹ thuật nông nghiệp và sinh học. Hiệp hội được thành lập vào tháng 12 năm 1907 tại Đại học Wisconsin–Madison với tên gọi là Hiệp hội Kỹ sư Nông nghiệp Hoa Kỳ (ASAE) và hiện có trụ sở tại St. Joseph, Michigan. Ngày nay, tổ chức này có khoảng 9.000 thành viên tại hơn 100 quốc gia.[cần dẫn nguồn] ASABE phục vụ nhiều chức năng: cung cấp diễn đàn để truyền đạt các phát hiện nghiên cứu thông qua các hội nghị, tạp chí khoa học và tạp chí; phát triển các tiêu chuẩn thực hành; tạo cơ hội cho các thành viên kết nối mạng.', NULL, NULL, '01*01.140*01.108*13*13.020*13.030*13.040*13.060*13.080*13.110*13.140*19*19.020*19.100*19.120*27*27.160*27.190*31*31.240*65*65.040*65.060*65.100*67.020*67.040*67.050*67.060*67.080*67.100*77.140', 'publisher/avatar/I1YT9VVH11PEOB1BG8W0.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4317, 'ASCE - American Society of Civil Engineers', 'ASCE - American Society of Civil Engineers', 'ASCE represents more than 140,000 members of the civil engineering profession worldwide and is the world\'s largest publisher of civil engineering information, producing more than 55,000 pages of technical content each year. The Codes and Standards Program is accredited by the American National Standards Institute (ANSI) and develops consensus standards on a variety of topics for the civil engineering profession. The Society celebrated its 150th anniversary in 2002.\nThe American Society of Civil Engineers (ASCE) is a tax-exempt professional body founded in 1852 to represent members of the civil engineering profession worldwide. Headquartered in Reston, Virginia, it is the oldest national engineering society in the United States.[3] Its constitution was based on the older Boston Society of Civil Engineers from 1848. \nASCE is dedicated to the advancement of the science and profession of civil engineering and the enhancement of human welfare through the activities of society members.[1] It has more than 143,000 members in 177 countries. Its mission is to provide essential value to members, their careers, partners, and the public; facilitate the advancement of technology; encourage and provide the tools for lifelong learning; promote professionalism and the profession; develop and support civil engineers. \nThe first serious and documented attempts to organize civil engineers as a professional society in the newly created United States were in the early 19th century. In 1828, John Kilbourn of Ohio managed a short-lived \"Civil Engineering Journal,\" editorializing about the recent incorporation of the Institution of Civil Engineers in Great Britain that same year, Kilbourn suggested that the American corps of engineers could constitute an American society of civil engineers.[6][5] Later, in 1834, an American trade periodical, the \"American Railroad Journal,\" advocated for a similar national organization of civil engineers', 'ASCE đại diện cho hơn 140.000 thành viên của ngành kỹ thuật dân dụng trên toàn thế giới và là nhà xuất bản thông tin kỹ thuật dân dụng lớn nhất thế giới, xuất bản hơn 55.000 trang nội dung kỹ thuật mỗi năm. Chương trình Tiêu chuẩn và Quy tắc được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận và phát triển các tiêu chuẩn đồng thuận về nhiều chủ đề khác nhau cho ngành kỹ thuật dân dụng. Hội đã kỷ niệm 150 năm thành lập vào năm 2002.\nHội Kỹ sư Dân dụng Hoa Kỳ (ASCE) là một tổ chức chuyên nghiệp miễn thuế được thành lập vào năm 1852 để đại diện cho các thành viên của ngành kỹ thuật dân dụng trên toàn thế giới. Có trụ sở chính tại Reston, Virginia, đây là hội kỹ thuật quốc gia lâu đời nhất tại Hoa Kỳ.[3] Hiến pháp của hội dựa trên Hội Kỹ sư Dân dụng Boston cũ hơn từ năm 1848.\nASCE dành riêng cho sự tiến bộ của khoa học và nghề kỹ thuật dân dụng và nâng cao phúc lợi của con người thông qua các hoạt động của các thành viên hội.[1] Hội có hơn 143.000 thành viên tại 177 quốc gia. Sứ mệnh của tổ chức là cung cấp giá trị thiết yếu cho các thành viên, sự nghiệp, đối tác và công chúng; tạo điều kiện thuận lợi cho sự tiến bộ của công nghệ; khuyến khích và cung cấp các công cụ để học tập suốt đời; thúc đẩy tính chuyên nghiệp và nghề nghiệp; phát triển và hỗ trợ các kỹ sư xây dựng.\nNhững nỗ lực nghiêm túc và được ghi chép đầu tiên nhằm tổ chức các kỹ sư xây dựng thành một hiệp hội chuyên nghiệp tại Hoa Kỳ mới thành lập là vào đầu thế kỷ 19. Năm 1828, John Kilbourn của Ohio đã quản lý một \"Tạp chí Kỹ thuật Xây dựng\" tồn tại trong thời gian ngắn, biên tập về việc thành lập Viện Kỹ sư Xây dựng gần đây tại Vương quốc Anh cùng năm đó, Kilbourn đề xuất rằng quân đoàn kỹ sư Hoa Kỳ có thể thành lập một hiệp hội kỹ sư xây dựng Hoa Kỳ.[6][5] Sau đó, vào năm 1834, một tạp chí thương mại của Hoa Kỳ, \"Tạp chí Đường sắt Hoa Kỳ\", đã ủng hộ một tổ chức kỹ sư xây dựng quốc gia tương tự', 'ASCE đại diện cho hơn 140.000 thành viên của ngành kỹ thuật dân dụng trên toàn thế giới và là nhà xuất bản thông tin kỹ thuật dân dụng lớn nhất thế giới, xuất bản hơn 55.000 trang nội dung kỹ thuật mỗi năm. Chương trình Tiêu chuẩn và Quy tắc được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận và phát triển các tiêu chuẩn đồng thuận về nhiều chủ đề khác nhau cho ngành kỹ thuật dân dụng. Hội đã kỷ niệm 150 năm thành lập vào năm 2002.', NULL, NULL, NULL, 'publisher/avatar/74T3Y4BCFEFQQ2K2LWS0.jpg', 0),
(4318, 'ASD-STAN prEN - ASD-STAN Standardization', 'ASD-STAN prEN - ASD-STAN Standardization', 'ASD-STAN is an association which establishes, develops and maintains standards on behalf of that European aerospace industry. Over the years, ASD-STAN has established a lean and streamlined standardisation process for European aerospace standards in agreement with the European Committee for Standardization (CEN). It is well recognised as the European body for the development of global aerospace standards by the International Aerospace Quality Group (IAQG).', 'ASD-STAN là Hiệp hội Tiêu chuẩn hóa Ngành Công nghiệp Quốc phòng và Không gian Vũ trụ Châu Âu. Đây là một tổ chức chuyên về việc phát triển và quản lý tiêu chuẩn trong lĩnh vực công nghiệp quốc phòng và không gian vũ trụ.\n\nASD-STAN được thành lập vào năm 1979 và có trụ sở tại Brussels, Bỉ. Tổ chức này là thành viên của ASD (Aerospace and Defence Industries Association of Europe), một liên minh các hiệp hội công nghiệp hàng không và quốc phòng tại Châu Âu.\n\nASD-STAN có nhiệm vụ chủ yếu là phát triển và duy trì các tiêu chuẩn kỹ thuật trong ngành công nghiệp quốc phòng và không gian vũ trụ. Các tiêu chuẩn này bao gồm các yêu cầu kỹ thuật, quy trình và phương pháp thử nghiệm, đảm bảo rằng các sản phẩm và dịch vụ trong ngành này đáp ứng được các tiêu chí an toàn, hiệu suất và chất lượng.\n\nASD-STAN cũng thúc đẩy việc sử dụng tiêu chuẩn trong ngành công nghiệp quốc phòng và không gian vũ trụ, nhằm tạo điều kiện thuận lợi cho sự hợp tác, trao đổi thông tin và phát triển công nghệ giữa các công ty và tổ chức trong lĩnh vực này.\n\nTổ chức cũng tham gia vào quá trình tiêu chuẩn hóa quốc tế, hợp tác với các tổ chức tiêu chuẩn khác trên toàn thế giới, nhưng tập trung vào việc phát triển các tiêu chuẩn dành riêng cho ngành công nghiệp quốc phòng và không gian vũ trụ.\n\nVai trò của ASD-STAN là quan trọng trong việc đảm bảo tính tương thích, an toàn và hiệu suất của các sản phẩm và dịch vụ trong ngành công nghiệp quốc phòng và không gian vũ trụ. Các tiêu chuẩn mà tổ chức này đề xuất và duy trì đóng vai trò quan trọng trong việc định hình và phát triển ngành công nghiệp này.', 'ASD-STAN là Hiệp hội Tiêu chuẩn hóa Ngành Công nghiệp Quốc phòng và Không gian Vũ trụ Châu Âu. Đây là một tổ chức chuyên về việc phát triển và quản lý tiêu chuẩn trong lĩnh vực công nghiệp quốc phòng và không gian vũ trụ.', 'ASD-STAN,AECMA,ASD', 'ASD-STAN, Hiệp hội Tiêu chuẩn hóa Ngành Công nghiệp Quốc phòng và Không gian Vũ trụ Châu Âu, ASD-STAN AeroSpace and Defence Industrie Association of Europe - Standardization', NULL, 'publisher/avatar/X9JTMMCPBK1M2WVXY7K2.jpg', 0),
(4319, 'ASHE - American Society for Healthcare Engineering', 'ASHE - American Society for Healthcare Engineering', 'The American Society of Healthcare Engineering (ASHE), established in 1962, was one of the first to publicize the term healthcare engineering. ASHE, as well as its many local affiliate societies, is devoted to the health care physical environment, including design, building, maintenance, and operation of hospitals and other health care facilities, which represents only one sector of engineers\' activities in healthcare. The term healthcare engineers first appeared in the scientific literature in 1989, where the critical role of engineers in the healthcare delivery system was discussed. A number of academic programs have adopted the name healthcare engineering (e.g., Indiana University, Northwestern University, Purdue University, Texas Tech University, University of Illinois, University of Michigan, University of North Carolina, University of Southern California, University of Toronto), although the description or definition of the term by these programs varies, as each institution has designed its program based on its own distinctive interest, strength, and focus. The first scholarly journal dedicated to healthcare engineering, Journal of Healthcare Engineering, was launched in 2010 by Dr. Ming-Chien Chyu, focusing on engineering involved in all aspects of healthcare delivery processes and systems. In the meantime, a number of companies with various foci have adopted healthcare engineering in their names.\nHealthcare engineering was first defined in a white paper published in 2015 by Chyu and 40 co-authors who are active members of and contributors to the healthcare engineering community around the world. The white paper was reviewed by more than 280 reviewers, including members of US National Academy of Engineering, engineering deans of the world\'s top universities, administrators and faculty members of healthcare engineering academic programs, leaders of healthcare/medical and engineering professional societies and associations, leaders of healthcare industry and government, and healthcare engineering professionals from around the world. This white paper documents a clear, rigorous definition of healthcare engineering as an academic discipline, an area of research, a field of specialty, and a profession, and is expected to raise the status and visibility of the field, help students choose healthcare engineering-related fields as majors, help engineers and healthcare professionals choose healthcare engineering as a profession, define healthcare engineering as a specialty area for the research community, funding agencies, and conference or event organizers, help job-search databases properly categorize healthcare engineering jobs, help healthcare employers recruit from the right pool of expertise, bring academic administrators\' attention to healthcare engineering in considering new program initiations, help governments and institutions of different levels put healthcare engineering into perspective for policy making, budgeting, and other purposes, and help publishers and librarians categorize literature related to healthcare engineering. Based on this white paper, a global, non-profit professional organization, Healthcare Engineering Alliance Society (HEALS), was founded by Chyu in 2015, which focuses on improving and advancing all aspects of healthcare through engineering approaches. The white paper has been cited in numerous scientific papers.', 'Hiệp hội Kỹ thuật chăm sóc sức khỏe Hoa Kỳ (ASHE), được thành lập vào năm 1962, là một trong những hiệp hội đầu tiên công bố thuật ngữ kỹ thuật chăm sóc sức khỏe. ASHE, cũng như nhiều hiệp hội liên kết địa phương của mình, dành riêng cho môi trường vật lý chăm sóc sức khỏe, bao gồm thiết kế, xây dựng, bảo trì và vận hành bệnh viện và các cơ sở chăm sóc sức khỏe khác, chỉ đại diện cho một lĩnh vực hoạt động của kỹ sư trong chăm sóc sức khỏe. Thuật ngữ kỹ sư chăm sóc sức khỏe lần đầu tiên xuất hiện trong tài liệu khoa học vào năm 1989, trong đó vai trò quan trọng của kỹ sư trong hệ thống cung cấp dịch vụ chăm sóc sức khỏe đã được thảo luận. Một số chương trình học thuật đã áp dụng tên kỹ thuật chăm sóc sức khỏe (ví dụ: Đại học Indiana, Đại học Northwestern, Đại học Purdue, Đại học Texas Tech, Đại học Illinois, Đại học Michigan, Đại học North Carolina, Đại học Nam California, Đại học Toronto), mặc dù mô tả hoặc định nghĩa về thuật ngữ của các chương trình này khác nhau, vì mỗi tổ chức đã thiết kế chương trình của mình dựa trên sở thích, thế mạnh và trọng tâm riêng biệt của mình. Tạp chí khoa học đầu tiên dành riêng cho kỹ thuật chăm sóc sức khỏe, Tạp chí Kỹ thuật Chăm sóc Sức khỏe, được Tiến sĩ Ming-Chien Chyu ra mắt vào năm 2010, tập trung vào kỹ thuật liên quan đến mọi khía cạnh của quy trình và hệ thống cung cấp dịch vụ chăm sóc sức khỏe. Trong khi đó, một số công ty với nhiều trọng tâm khác nhau đã áp dụng kỹ thuật chăm sóc sức khỏe vào tên của họ.\nKỹ thuật chăm sóc sức khỏe lần đầu tiên được định nghĩa trong một sách trắng được xuất bản vào năm 2015 bởi Chyu và 40 đồng tác giả là những thành viên tích cực và là những người đóng góp cho cộng đồng kỹ thuật chăm sóc sức khỏe trên toàn thế giới. Sách trắng đã được hơn 280 người đánh giá, bao gồm các thành viên của Viện Hàn lâm Kỹ thuật Quốc gia Hoa Kỳ, các trưởng khoa kỹ thuật của các trường đại học hàng đầu thế giới, các nhà quản lý và giảng viên của các chương trình học thuật về kỹ thuật chăm sóc sức khỏe, các nhà lãnh đạo của các hiệp hội và hội chuyên gia chăm sóc sức khỏe/y tế và kỹ thuật, các nhà lãnh đạo của ngành chăm sóc sức khỏe và chính phủ, và các chuyên gia kỹ thuật chăm sóc sức khỏe từ khắp nơi trên thế giới. Sách trắng này ghi lại định nghĩa rõ ràng, chặt chẽ về kỹ thuật chăm sóc sức khỏe như một ngành học thuật, một lĩnh vực nghiên cứu, một lĩnh vực chuyên môn và một nghề nghiệp, và được kỳ vọng sẽ nâng cao vị thế và khả năng hiển thị của lĩnh vực này, giúp sinh viên lựa chọn các lĩnh vực liên quan đến kỹ thuật chăm sóc sức khỏe làm chuyên ngành chính, giúp các kỹ sư và chuyên gia chăm sóc sức khỏe lựa chọn kỹ thuật chăm sóc sức khỏe làm nghề nghiệp, định nghĩa kỹ thuật chăm sóc sức khỏe là lĩnh vực chuyên môn cho cộng đồng nghiên cứu, các cơ quan tài trợ và đơn vị tổ chức hội nghị hoặc sự kiện, giúp cơ sở dữ liệu tìm kiếm việc làm phân loại đúng các công việc kỹ thuật chăm sóc sức khỏe, giúp các nhà tuyển dụng chăm sóc sức khỏe tuyển dụng từ nhóm chuyên gia phù hợp, thu hút sự chú ý của các nhà quản lý học thuật vào kỹ thuật chăm sóc sức khỏe khi xem xét khởi xướng chương trình mới, giúp chính phủ và các tổ chức ở các cấp độ khác nhau đưa kỹ thuật chăm sóc sức khỏe vào đúng bối cảnh để hoạch định chính sách, lập ngân sách và các mục đích khác, và giúp các nhà xuất bản và thủ thư phân loại tài liệu liên quan đến kỹ thuật chăm sóc sức khỏe. Dựa trên sách trắng này, một tổ chức chuyên nghiệp phi lợi nhuận toàn cầu, Healthcare Engineering Alliance Society (HEALS), được Chyu thành lập vào năm 2015, tập trung vào việc cải thiện và thúc đẩy mọi khía cạnh của chăm sóc sức khỏe thông qua các phương pháp tiếp cận kỹ thuật. Sách trắng đã được trích dẫn trong nhiều bài báo khoa học.', 'Hiệp hội Kỹ thuật chăm sóc sức khỏe Hoa Kỳ (ASHE), được thành lập vào năm 1962, là một trong những hiệp hội đầu tiên công bố thuật ngữ kỹ thuật chăm sóc sức khỏe. ASHE, cũng như nhiều hiệp hội liên kết địa phương của mình, dành riêng cho môi trường vật lý chăm sóc sức khỏe, bao gồm thiết kế, xây dựng, bảo trì và vận hành bệnh viện và các cơ sở chăm sóc sức khỏe khác, chỉ đại diện cho một lĩnh vực hoạt động của kỹ sư trong chăm sóc sức khỏe.', NULL, NULL, NULL, 'publisher/avatar/GBNJCWR8GCFOHE7Z3SMA.png', 0),
(4320, 'ASHRAE - ASHRAE', 'ASHRAE - ASHRAE', 'ASHRAE standards establish consensus for test methods and performance criteria. These include voluntary consensus standards for Method of Measurement or Test, Standard Design and Standard Practice. Consensus standards define minimum values or acceptable performance. ASHRAE is accredited by the American National Standards Institute (ANSI) and follows ANSI\'s requirements for due process and standards development.', 'ASHRAE, được thành lập vào năm 1894, là một xã hội toàn cầu nâng cao phúc lợi con người thông qua công nghệ bền vững cho môi trường xây dựng. Hiệp hội và các thành viên tập trung vào hệ thống tòa nhà, hiệu quả sử dụng năng lượng, chất lượng không khí trong nhà, điện lạnh và tính bền vững trong ngành. Thông qua nghiên cứu, viết tiêu chuẩn, xuất bản và giáo dục thường xuyên, ASHRAE định hình môi trường xây dựng cho ngày mai ngay hôm nay. ASHRAE được thành lập với tên gọi Hiệp hội kỹ sư sưởi ấm, làm lạnh và điều hòa không khí Hoa Kỳ thông qua sự sáp nhập vào năm 1959 của Hiệp hội kỹ sư sưởi ấm và điều hòa không khí Hoa Kỳ (ASHAE) thành lập năm 1894 và Hiệp hội kỹ sư làm lạnh Hoa Kỳ (ASRE) thành lập năm 1904 .\nVào năm 2012, như một phần của việc đổi thương hiệu, ASHRAE bắt đầu kinh doanh với tên “ASHRAE” thay vì sử dụng tên pháp lý đầy đủ của Hiệp hội Kỹ sư Hệ thống sưởi, Điện lạnh và Điều hòa Không khí Hoa Kỳ. Việc sử dụng ASHRAE phản ánh tư cách thành viên trên toàn thế giới của Hiệp hội và các dịch vụ đó sẽ tiếp tục phát triển trên toàn cầu. \n\nSứ mệnh và tầm nhìn của ASHRAE\n\nNhiệm vụ:\nThúc đẩy nghệ thuật và khoa học về sưởi ấm, thông gió, điều hòa không khí và làm lạnh để phục vụ nhân loại và thúc đẩy một thế giới bền vững.\n\nTầm nhìn\nASHRAE sẽ là công ty dẫn đầu toàn cầu, nguồn thông tin giáo dục và kỹ thuật quan trọng nhất, đồng thời là nhà cung cấp cơ hội chính để phát triển nghề nghiệp trong nghệ thuật và khoa học về sưởi ấm, thông gió, điều hòa không khí và điện lạnh. \n\nGiá trị cốt lõi của ASHRAE\n\nXuất sắc\nGiáo dục, thông tin kỹ thuật của ASHRAE cũng như tất cả các hoạt động và sản phẩm khác sẽ luôn phản ánh những phương pháp thực hành tốt nhất dẫn đầu ngành của chúng ta. Chúng tôi nỗ lực cải tiến và đổi mới liên tục trong tất cả các hoạt động và sản phẩm của mình.\n\nSự cam kết\nASHRAE và các thành viên của mình đam mê phục vụ môi trường xây dựng, tạo ra giá trị và ghi nhận thành tích của người khác.\n\nChính trực\nASHRAE cam kết tuân thủ các tiêu chuẩn đạo đức cao nhất. Chúng tôi làm việc minh bạch, tuân thủ các yêu cầu thiết yếu về quy trình hợp lý và đánh giá ngang hàng để đảm bảo với các thành viên và các bên liên quan rằng chúng tôi làm những điều đúng đắn và đúng cách.\n\nSự hợp tác\nASHRAE tìm kiếm và thúc đẩy các nỗ lực hợp tác với các tổ chức, cơ quan và cá nhân có cùng cam kết với chúng tôi về môi trường xây dựng bền vững.\n\nTình nguyện\nCác thành viên lãnh đạo ASHRAE ở mọi cấp độ, phục vụ ASHRAE và giúp ASHRAE phục vụ xã hội.', 'Tiêu chuẩn ASHRAE thiết lập sự đồng thuận về phương pháp thử nghiệm và tiêu chí thực hiện. Chúng bao gồm các tiêu chuẩn đồng thuận tự nguyện về Phương pháp đo lường hoặc thử nghiệm, Thiết kế tiêu chuẩn và Thực hành tiêu chuẩn.', 'ASHRAE,ANSI/AHRI/ASHRAE/ISO,ANSI/ASHRAE,ANSI/ASHRAE/IESNA', 'ASHRAE, Hiệp hội các Kỹ sư Nhiệt, Điện lạnh và Điều hòa Nhiệt độ Hoa Kỳ (ASHRAE), American Society of Heating, Refrigerating and Air-Conditioning Engineers (ASHRAE), Điện lạnh, Điều hòa nhiệt độ, Tiêu chuẩn hiệp hội Hoa Kỳ', '13.040*23.120*27.080*27.160*27.200', 'publisher/avatar/L9D7CLO7Z1OWS3HZE311.png', 0),
(4321, 'ASHRAE/Outskirts - Outskirts Press', 'ASHRAE/Outskirts - Outskirts Press', 'ASHRAE/Outskirts - Outskirts Press', NULL, NULL, NULL, NULL, '13.040*23.120*27.080*27.160*27.200', 'publisher/avatar/S7AC8Q3BK3KT1TWCCLU3.png', 0),
(4322, 'ASIS - ASIS International', 'ASIS - ASIS International', 'ASIS International is the leading organization for security professionals worldwide. An ANSI-accredited Standards Developing Organization, ASIS works with national and international standards-setting organizations to advance security practices worldwide through the development of standards and guidelines.\nASIS International, headquartered in Alexandria, Virginia, is a professional organization for security professionals. It issues certifications, standards, and guidelines for the security profession.\nFounded in 1955 as the American Society for Industrial Security (ASIS), the organization officially changed its name in 2002 to ASIS International to reflect its international expansion, which currently includes 34,600 members in 155 countries and 240 local chapters in 89 countries worldwide, the Annual ASIS Fact Sheet contains additional information. The name \"American Society for Industrial Security\" no longer exists except in historical legal documents.\nAs of 2018, the annual educational and networking event hosted by ASIS is referred to as the \"Global Security Exchange (GSX). This event is centered on education sessions, networking opportunities and an exhibit hall showcasing over 450 security vendors.\nThe ASIS Foundation offers security professionals certification scholarships, practical research, member hardship grants, and more.', 'ASIS International là tổ chức hàng đầu dành cho các chuyên gia an ninh trên toàn thế giới. Là một Tổ chức Phát triển Tiêu chuẩn được ANSI công nhận, ASIS hợp tác với các tổ chức thiết lập tiêu chuẩn quốc gia và quốc tế để thúc đẩy các hoạt động an ninh trên toàn thế giới thông qua việc phát triển các tiêu chuẩn và hướng dẫn.\nASIS International, có trụ sở chính tại Alexandria, Virginia, là một tổ chức chuyên nghiệp dành cho các chuyên gia an ninh. Tổ chức này cấp chứng chỉ, tiêu chuẩn và hướng dẫn cho nghề an ninh.\nĐược thành lập vào năm 1955 với tên gọi là Hiệp hội An ninh Công nghiệp Hoa Kỳ (ASIS), tổ chức này chính thức đổi tên thành ASIS International vào năm 2002 để phản ánh sự mở rộng ra quốc tế của mình, hiện có 34.600 thành viên tại 155 quốc gia và 240 chi nhánh địa phương tại 89 quốc gia trên toàn thế giới, Bản thông tin hàng năm của ASIS có chứa thông tin bổ sung. Tên gọi \"Hiệp hội An ninh Công nghiệp Hoa Kỳ\" không còn tồn tại nữa ngoại trừ trong các văn bản pháp lý lịch sử.\nTính đến năm 2018, sự kiện giáo dục và kết nối thường niên do ASIS tổ chức được gọi là \"Global Security Exchange (GSX). Sự kiện này tập trung vào các buổi giáo dục, cơ hội kết nối và một hội trường triển lãm trưng bày hơn 450 nhà cung cấp bảo mật.\nQuỹ ASIS cung cấp học bổng chứng nhận chuyên gia bảo mật, nghiên cứu thực tế, trợ cấp khó khăn cho thành viên, v.v.', 'ASIS International là tổ chức hàng đầu dành cho các chuyên gia an ninh trên toàn thế giới. Là một Tổ chức Phát triển Tiêu chuẩn được ANSI công nhận, ASIS hợp tác với các tổ chức thiết lập tiêu chuẩn quốc gia và quốc tế để thúc đẩy các hoạt động an ninh trên toàn thế giới thông qua việc phát triển các tiêu chuẩn và hướng dẫn.', NULL, NULL, NULL, 'publisher/avatar/37IA4MDVF09HFSYKFQ2V.png', 0),
(4323, 'ASM - ASM International', 'ASM - ASM International', 'ASM International is the preeminent association for engaging and connecting materials professionals and their organizations to the resources necessary to solve problems, improve outcomes, and advance society. As the world\'s largest and most established materials information society, ASM engages and connects you to a global network of peers and provides access to trusted materials information through reference content and data, education courses, international events, and research.\nASM (previously known as ASM International N.V., originally standing for Advanced Semiconductor Materials) is a Dutch headquartered multinational corporation that specializes in the design, manufacturing, sales and service of semiconductor wafer processing equipment for the fabrication of semiconductor devices. ASM\'s products are used by semiconductor manufacturers in front-end wafer processing in their semiconductor fabrication plants. ASM\'s technologies include atomic layer deposition, epitaxy, chemical vapor deposition and diffusion. \nThe company was founded by Arthur del Prado (1931-2016) as \'Advanced Semiconductor Materials\' in 1964.[2] From 2008 until 2020, son of Arthur del Prado, Chuck del Prado was CEO. ASM pioneered important aspects of many established wafer-processing technologies used in industry, including lithography, deposition, ion implantation, single-wafer epitaxy, and in recent years atomic layer deposition. Semiconductor equipment companies ASML, ASM Pacific Technology (ASMPT) and Besi are former divisions of ASM. \nASM headquarters is located in Almere, the Netherlands. The company has R&D sites in Almere (the Netherlands), Helsinki (Finland), Leuven (Belgium, near IMEC), Phoenix (Arizona), Tama (Japan), and Dongtan (South Korea). Manufacturing primarily occurs in Singapore and Dongtan (South-Korea). ASM also has sales & service offices across the globe, including United States, South Korea, China, Taiwan, Japan, Singapore and Israel. As of 2021, it has 3,312 staff, located in 14 countries. \nThe shares of the company are listed on the Euronext Amsterdam. In March 2020, ASM was promoted to the AEX index.[4] ASM has a minority stake in ASM Pacific Technology, a Hong Kong-based company active in semiconductor assembly, packaging and surface-mount technology.', 'ASM International là hiệp hội hàng đầu trong việc thu hút và kết nối các chuyên gia vật liệu và tổ chức của họ với các nguồn lực cần thiết để giải quyết vấn đề, cải thiện kết quả và thúc đẩy xã hội. Là hiệp hội thông tin vật liệu lớn nhất và lâu đời nhất thế giới, ASM thu hút và kết nối bạn với mạng lưới đồng nghiệp toàn cầu và cung cấp quyền truy cập vào thông tin vật liệu đáng tin cậy thông qua nội dung và dữ liệu tham khảo, các khóa học giáo dục, sự kiện quốc tế và nghiên cứu.\nASM (trước đây được gọi là ASM International N.V., ban đầu là viết tắt của Advanced Semiconductor Materials) là một tập đoàn đa quốc gia có trụ sở chính tại Hà Lan chuyên thiết kế, sản xuất, bán và dịch vụ thiết bị xử lý wafer bán dẫn để chế tạo các thiết bị bán dẫn. Các sản phẩm của ASM được các nhà sản xuất chất bán dẫn sử dụng trong quá trình xử lý wafer đầu vào tại các nhà máy chế tạo chất bán dẫn của họ. Các công nghệ của ASM bao gồm lắng đọng lớp nguyên tử, epitaxy, lắng đọng hơi hóa học và khuếch tán.\nCông ty được Arthur del Prado (1931-2016) thành lập với tên gọi \'Advanced Semiconductor Materials\' vào năm 1964.[2] Từ năm 2008 đến năm 2020, con trai của Arthur del Prado, Chuck del Prado là Tổng giám đốc điều hành. ASM tiên phong trong các khía cạnh quan trọng của nhiều công nghệ xử lý wafer đã được sử dụng trong ngành công nghiệp, bao gồm quang khắc, lắng đọng, cấy ion, epitaxy wafer đơn và trong những năm gần đây là lắng đọng lớp nguyên tử. Các công ty thiết bị bán dẫn ASML, ASM Pacific Technology (ASMPT) và Besi là các bộ phận trước đây của ASM.\nTrụ sở chính của ASM đặt tại Almere, Hà Lan. Công ty có các cơ sở R&D tại Almere (Hà Lan), Helsinki (Phần Lan), Leuven (Bỉ, gần IMEC), Phoenix (Arizona), Tama (Nhật Bản) và Dongtan (Hàn Quốc). Hoạt động sản xuất chủ yếu diễn ra tại Singapore và Dongtan (Hàn Quốc). ASM cũng có các văn phòng bán hàng và dịch vụ trên toàn cầu, bao gồm Hoa Kỳ, Hàn Quốc, Trung Quốc, Đài Loan, Nhật Bản, Singapore và Israel. Tính đến năm 2021, công ty có 3.312 nhân viên, làm việc tại 14 quốc gia.\nCổ phiếu của công ty được niêm yết trên Euronext Amsterdam. Vào tháng 3 năm 2020, ASM được thăng hạng lên chỉ số AEX.[4] ASM có cổ phần thiểu số trong ASM Pacific Technology, một công ty có trụ sở tại Hồng Kông hoạt động trong lĩnh vực lắp ráp chất bán dẫn, đóng gói và công nghệ gắn bề mặt.', 'ASM International là hiệp hội hàng đầu trong việc thu hút và kết nối các chuyên gia vật liệu và tổ chức của họ với các nguồn lực cần thiết để giải quyết vấn đề, cải thiện kết quả và thúc đẩy xã hội. Là hiệp hội thông tin vật liệu lớn nhất và lâu đời nhất thế giới, ASM thu hút và kết nối bạn với mạng lưới đồng nghiệp toàn cầu và cung cấp quyền truy cập vào thông tin vật liệu đáng tin cậy thông qua nội dung và dữ liệu tham khảo, các khóa học giáo dục, sự kiện quốc tế và nghiên cứu.', NULL, NULL, NULL, 'publisher/avatar/MA76YSSY5LAXSFXKKMC0.jpg', 0),
(4324, 'ASME - ASME International', 'ASME - ASME International', 'ASME is a not-for-profit membership organization that enables collaboration, knowledge sharing, career enrichment, and skills development across all engineering disciplines, toward a goal of helping the global engineering community develop solutions to benefit lives and livelihoods. Founded in 1880 by a small group of leading industrialists, ASME has grown through the decades to include more than 130,000 members in 158 countries.', 'ASME (American Society of Mechanical Engineers) là một tổ chức chuyên về cơ khí tại Hoa Kỳ. ASME không chỉ là một tiêu chuẩn duy nhất, mà là một tổ chức chuyên nghiên cứu, tiêu chuẩn hóa, và giáo dục trong lĩnh vực cơ khí.\n\nASME được thành lập vào năm 1880 và đã trở thành một trong những tổ chức hàng đầu trong ngành cơ khí toàn cầu. Nhiệm vụ chính của ASME là thúc đẩy sự phát triển và ứng dụng các phương pháp cơ khí tiên tiến, nâng cao kiến thức và kỹ năng của các kỹ sư cơ khí, đảm bảo tính an toàn và hiệu suất trong các thiết bị và công trình cơ khí.\n\nASME công bố và duy trì nhiều tiêu chuẩn kỹ thuật quan trọng trong lĩnh vực cơ khí. Các tiêu chuẩn ASME bao gồm ASME Boiler and Pressure Vessel Code (mã tiêu chuẩn về lò hơi và thiết bị chịu áp lực), ASME B31 Code (mã tiêu chuẩn về ống dẫn và đường ống), và nhiều tiêu chuẩn khác liên quan đến thiết kế, vận hành và bảo trì các hệ thống cơ khí.\n\nCác tiêu chuẩn ASME được sử dụng rộng rãi trong ngành cơ khí, đặc biệt là trong việc thiết kế, xây dựng và vận hành các thiết bị và hệ thống chịu áp lực như lò hơi, bình áp lực, đường ống, và các ứng dụng công nghiệp khác.\n\nNgoài ra, ASME còn tổ chức các hội thảo, hội nghị, và khóa học về cơ khí, cung cấp cơ hội giao lưu và chia sẻ kiến thức giữa các chuyên gia và nhà nghiên cứu trong ngành cơ khí.', 'ASME (American Society of Mechanical Engineers) là một tổ chức chuyên về cơ khí tại Hoa Kỳ. ASME không chỉ là một tiêu chuẩn duy nhất, mà là một tổ chức chuyên nghiên cứu, tiêu chuẩn hóa, và giáo dục trong lĩnh vực cơ khí.', 'ASME,ANSI/ASME', 'ASME, Tiêu chuẩn Hội Cơ khí Hoa Kỳ (ASME), American Society of Mechanical Engineers (ASME), Cơ khí, Tiêu chuẩn cơ khí', '01*01.020*01.080*01.100*01.110*11*11.120*13*13.110*17*17.020*17.040*17.100*17.120*19*19.020*19.040*19.060**19.100*21*23*23.020*23.040*23.060*23.080*25*25.040*25.060*25.080*25.100*25.140*25.160*25.200*27*27.020*27.040*27.060>27.070*27.075*27.100*27.120*27.', 'publisher/avatar/IJ2K9IRS0A3GY0GDPUPR.png', 0),
(4325, 'ASNT - American Society for Nondestructive Testing', 'ASNT - American Society for Nondestructive Testing', 'The American Society for Nondestructive Testing, Inc. (ASNT) is the world\'s largest technical society for nondestructive testing (NDT) professionals. Through organization and membership, ASNT provides a forum for exchange of NDT technical information, NDT educational materials and programs, and standards and services for the qualification and certification of NDT personnel. ASNT promotes the discipline of NDT as a profession and facilitates NDT research and technology applications.\nASNT is a nonprofit organization, which is governed by the Board of Directors and the national officers. There are four councils within ASNT:\n1. Technical and Education\n2. Research\n3. Section Operations\n4. Certification\nASNT publishes and maintains an important standard, SNT-TC-1A, which, with the addition of Codes of Practice ANSI/ASNT CP-189 and ANSI/ASNT CP-105, covers all aspects of qualification and certification of NDT personnel. SNT-TC-1A specifies an employer based certification scheme for ASNT NDT Level I and ASNT NDT Level II Certification Program personnel, which is extensively used worldwide, in countries not enforcing ISO 9712 such as the European Union or Canada. The ASNT Central Certification Program (ACCP) is a fully accredited certification scheme that specifically complies with the ISO 9712 Standard.', 'Hiệp hội Kiểm tra Không phá hủy Hoa Kỳ (ASNT) là hiệp hội kỹ thuật lớn nhất thế giới dành cho các chuyên gia kiểm tra không phá hủy (NDT). Thông qua tổ chức và tư cách thành viên, ASNT cung cấp diễn đàn trao đổi thông tin kỹ thuật NDT, tài liệu và chương trình giáo dục NDT, các tiêu chuẩn và dịch vụ để cấp chứng chỉ và trình độ cho nhân viên NDT. ASNT thúc đẩy kỷ luật NDT như một nghề nghiệp và tạo điều kiện cho các ứng dụng công nghệ và nghiên cứu NDT.\nASNT là một tổ chức phi lợi nhuận, được quản lý bởi Hội đồng quản trị và các viên chức quốc gia. Có bốn hội đồng trong ASNT:\n1. Kỹ thuật và Giáo dục\n2. Nghiên cứu\n3. Hoạt động của Bộ phận\n4. Chứng nhận\nASNT xuất bản và duy trì một tiêu chuẩn quan trọng, SNT-TC-1A, cùng với việc bổ sung Bộ quy tắc thực hành ANSI/ASNT CP-189 và ANSI/ASNT CP-105, bao gồm tất cả các khía cạnh về trình độ và cấp chứng chỉ cho nhân viên NDT. SNT-TC-1A chỉ định một chương trình chứng nhận dựa trên nhà tuyển dụng cho nhân viên Chương trình chứng nhận ASNT NDT Cấp độ I và ASNT NDT Cấp độ II, được sử dụng rộng rãi trên toàn thế giới, tại các quốc gia không áp dụng ISO 9712 như Liên minh Châu Âu hoặc Canada. Chương trình chứng nhận trung tâm ASNT (ACCP) là một chương trình chứng nhận được công nhận đầy đủ, tuân thủ cụ thể theo Tiêu chuẩn ISO 9712.', 'Hiệp hội Kiểm tra Không phá hủy Hoa Kỳ (ASNT) là hiệp hội kỹ thuật lớn nhất thế giới dành cho các chuyên gia kiểm tra không phá hủy (NDT). Thông qua tổ chức và tư cách thành viên, ASNT cung cấp diễn đàn trao đổi thông tin kỹ thuật NDT, tài liệu và chương trình giáo dục NDT, các tiêu chuẩn và dịch vụ để cấp chứng chỉ và trình độ cho nhân viên NDT. ASNT thúc đẩy kỷ luật NDT như một nghề nghiệp và tạo điều kiện cho các ứng dụng công nghệ và nghiên cứu NDT.', NULL, NULL, NULL, 'publisher/avatar/GQC1FPNWJ3NBZRROB7R5.jpg', 0),
(4326, 'ASQ - American Society for Quality', 'ASQ - American Society for Quality', 'ASQ, the American Society for Quality, is the world\'s leading authority on quality. The principles of quality influence manufacturing and other industrial processes by focusing attention on how products and services define and meet technical specifications. Quality standards from ASQ advance learning, quality improvement, and knowledge exchange to improve business results, and to create better workplaces and communities worldwide.\nThe American Society for Quality (ASQ), formerly the American Society for Quality Control (ASQC), is a society of quality professionals, with more than 40,000 members.\nASQ is a global organization with members in more than 140 countries. ASQ operates regional centers in North Asia, South Asia, and Latin America, and has established strategic alliances with organizations through the World Partners® Program in countries like Japan, Canada, and the United Arab Emirates to promote ASQ products and training. \nASQC was established on 16 February 1946 by 253 members in Milwaukee, Wisconsin, with George D. Edwards as its first president. The organization was first created as a way for quality experts and manufacturers to sustain quality-improvement techniques used during World War II. \nIn 1948, ASQC\'s Code of Ethics establishes standards for members to conduct their activities and business. Business writer Armand V. Feigenbaum served as president of the society in 1961–63. \nIn 1997, the members of the organization voted to change its name from \"American Society for Quality Control\" to \"American Society for Quality\".', 'ASQ, Hiệp hội Chất lượng Hoa Kỳ, là cơ quan có thẩm quyền hàng đầu thế giới về chất lượng. Các nguyên tắc về chất lượng ảnh hưởng đến sản xuất và các quy trình công nghiệp khác bằng cách tập trung sự chú ý vào cách sản phẩm và dịch vụ xác định và đáp ứng các thông số kỹ thuật. Các tiêu chuẩn chất lượng từ ASQ thúc đẩy việc học tập, cải tiến chất lượng và trao đổi kiến ​​thức để cải thiện kết quả kinh doanh và tạo ra nơi làm việc và cộng đồng tốt hơn trên toàn thế giới.\nHiệp hội Chất lượng Hoa Kỳ (ASQ), trước đây là Hiệp hội Kiểm soát Chất lượng Hoa Kỳ (ASQC), là một hiệp hội của các chuyên gia về chất lượng, với hơn 40.000 thành viên.\nASQ là một tổ chức toàn cầu với các thành viên ở hơn 140 quốc gia. ASQ điều hành các trung tâm khu vực ở Bắc Á, Nam Á và Châu Mỹ Latinh, và đã thiết lập các liên minh chiến lược với các tổ chức thông qua Chương trình Đối tác Thế giới® tại các quốc gia như Nhật Bản, Canada và Các Tiểu vương quốc Ả Rập Thống nhất để quảng bá các sản phẩm và đào tạo của ASQ.\nASQC được thành lập vào ngày 16 tháng 2 năm 1946 bởi 253 thành viên tại Milwaukee, Wisconsin, với George D. Edwards là chủ tịch đầu tiên. Tổ chức này ban đầu được thành lập như một cách để các chuyên gia về chất lượng và nhà sản xuất duy trì các kỹ thuật cải tiến chất lượng được sử dụng trong Thế chiến II.\nNăm 1948, Bộ quy tắc đạo đức của ASQC thiết lập các tiêu chuẩn để các thành viên tiến hành các hoạt động và công việc kinh doanh của mình. Nhà văn kinh doanh Armand V. Feigenbaum đã giữ chức chủ tịch của hiệp hội trong giai đoạn 1961–63.\nNăm 1997, các thành viên của tổ chức đã bỏ phiếu đổi tên từ \"Hiệp hội kiểm soát chất lượng Hoa Kỳ\" thành \"Hiệp hội chất lượng Hoa Kỳ\".', 'ASQ, Hiệp hội Chất lượng Hoa Kỳ, là cơ quan có thẩm quyền hàng đầu thế giới về chất lượng. Các nguyên tắc về chất lượng ảnh hưởng đến sản xuất và các quy trình công nghiệp khác bằng cách tập trung sự chú ý vào cách sản phẩm và dịch vụ xác định và đáp ứng các thông số kỹ thuật. Các tiêu chuẩn chất lượng từ ASQ thúc đẩy việc học tập, cải tiến chất lượng và trao đổi kiến ​​thức để cải thiện kết quả kinh doanh và tạo ra nơi làm việc và cộng đồng tốt hơn trên toàn thế giới.', NULL, NULL, NULL, 'publisher/avatar/I70P6B0JNT7MQ2FFJB8B.png', 0),
(4327, 'ASSE (Plumbing) - American Society of Sanitary Engineering', 'ASSE (Plumbing) - American Society of Sanitary Engineering', 'ASSE International is an ANSI-accredited standards developer and product certification body composed of members representing all disciplines of the plumbing and mechanical industries. ASSE’s product performance standards, professional qualifications standards, professional certification, and product certification programs aim to improve the performance and safety of plumbing and mechanical systems.\nASSE International is a membership organization and leading product and personnel certification agency for companies and individuals representing all disciplines of the plumbing and mechanical industries. Our mission is to promote public awareness about the importance of safe and correct plumbing and mechanical systems, and improve the performance and safety of these systems. After 113 years of advocating for standardized plumbing practices, more than 50 years of certifying products, and more than 25 years of certifying qualified personnel, ASSE certifications are proudly earned by manufacturers and workers throughout North America.\nASSE International maintains nearly 50 product performance standards, ranging from double check and reduced pressure backflow preventers to dielectric pipe unions, with many more in the development stages. ASSE\'s product standards are minimum performance requirements for component parts of the plumbing system.\nFor more than 113 years, ASSE International has been bringing the industry together to improve the performance and reliability of products and professionals. By working together, we protect the health and safety of the public.\nASSE product and professional standards are developed and revised through true industry consensus under the ANSI-accredited standards development process. This means that experts from all segments of the plumbing and mechanical industries gather to determine the minimum performance requirements for products and professionals.\nASSE International is a third-party certifier for professionals in the plumbing and mechanical industries. ASSE professional certification in the specialized segments of backflow prevention, service plumbing, infection control, fire protection, rainwater harvesting, and hydronic heating and cooling, among others, expands skill sets, offers nationally recognized certifications to jurisdictions, and raises the employability of professionals.\nASSE International is an ANAB- and SCC-accredited product certification body with a strong focus on backflow prevention and thermostatic mixing. ASSE certified products are tested by qualified laboratories to strict performance requirements of product standards, and certified in a manner that is impartial, balanced, informed, and rigorous.\nASSE International is a 113-year-old membership organization composed of members representing all disciplines of the plumbing and mechanical industries. ASSE\'s diversity of members form a platform to receive, understand, and solve industry problems relating to standards, codes, contracting, engineering and business. Whether it’s through planning or participating in local chapter activities and meetings, writing an article for ASSE publications, mentoring young member, or volunteering on national ASSE committees, membership involvement is essential to ASSE International’s success.', 'ASSE International là một tổ chức phát triển tiêu chuẩn và chứng nhận sản phẩm được ANSI công nhận, bao gồm các thành viên đại diện cho tất cả các ngành công nghiệp ống nước và cơ khí. Các tiêu chuẩn hiệu suất sản phẩm, tiêu chuẩn trình độ chuyên môn, chứng nhận chuyên môn và chương trình chứng nhận sản phẩm của ASSE nhằm mục đích cải thiện hiệu suất và tính an toàn của hệ thống ống nước và cơ khí.\nASSE International là một tổ chức thành viên và là cơ quan chứng nhận sản phẩm và nhân sự hàng đầu dành cho các công ty và cá nhân đại diện cho tất cả các ngành công nghiệp ống nước và cơ khí. Sứ mệnh của chúng tôi là nâng cao nhận thức của công chúng về tầm quan trọng của hệ thống ống nước và cơ khí an toàn và chính xác, đồng thời cải thiện hiệu suất và tính an toàn của các hệ thống này. Sau 113 năm ủng hộ các hoạt động tiêu chuẩn hóa hệ thống ống nước, hơn 50 năm chứng nhận sản phẩm và hơn 25 năm chứng nhận nhân sự đủ tiêu chuẩn, các nhà sản xuất và công nhân trên khắp Bắc Mỹ tự hào đạt được chứng nhận ASSE.\nASSE International duy trì gần 50 tiêu chuẩn hiệu suất sản phẩm, từ kiểm tra kép và bộ chống dòng chảy ngược áp suất giảm đến các đầu nối ống điện môi, với nhiều tiêu chuẩn khác đang trong giai đoạn phát triển. Các tiêu chuẩn sản phẩm của ASSE là các yêu cầu hiệu suất tối thiểu đối với các bộ phận cấu thành của hệ thống ống nước.\nTrong hơn 113 năm qua, ASSE International đã tập hợp ngành công nghiệp lại với nhau để cải thiện hiệu suất và độ tin cậy của sản phẩm và chuyên gia. Bằng cách hợp tác, chúng tôi bảo vệ sức khỏe và sự an toàn của công chúng.\nCác tiêu chuẩn sản phẩm và chuyên gia của ASSE được phát triển và sửa đổi thông qua sự đồng thuận thực sự của ngành theo quy trình phát triển tiêu chuẩn được ANSI công nhận. Điều này có nghĩa là các chuyên gia từ mọi phân khúc của ngành công nghiệp ống nước và cơ khí sẽ tập hợp lại để xác định các yêu cầu hiệu suất tối thiểu cho sản phẩm và chuyên gia.\nASSE International là đơn vị chứng nhận bên thứ ba dành cho các chuyên gia trong ngành công nghiệp ống nước và cơ khí. Chứng nhận chuyên gia của ASSE trong các phân khúc chuyên biệt về phòng ngừa dòng chảy ngược, dịch vụ ống nước, kiểm soát nhiễm trùng, phòng cháy chữa cháy, thu gom nước mưa và hệ thống sưởi ấm và làm mát bằng nước, cùng nhiều lĩnh vực khác, mở rộng các kỹ năng, cung cấp các chứng nhận được công nhận trên toàn quốc cho các khu vực pháp lý và nâng cao khả năng tuyển dụng của các chuyên gia.\nASSE International là một tổ chức chứng nhận sản phẩm được ANAB và SCC công nhận, tập trung mạnh vào phòng ngừa dòng chảy ngược và trộn nhiệt. Các sản phẩm được ASSE chứng nhận được các phòng thí nghiệm đủ tiêu chuẩn kiểm tra theo các yêu cầu hiệu suất nghiêm ngặt của các tiêu chuẩn sản phẩm và được chứng nhận theo cách công bằng, cân bằng, có thông tin và nghiêm ngặt.\nASSE International là một tổ chức thành viên đã có 113 năm tuổi bao gồm các thành viên đại diện cho tất cả các ngành công nghiệp ống nước và cơ khí. Sự đa dạng của các thành viên ASSE tạo thành một nền tảng để tiếp nhận, hiểu và giải quyết các vấn đề của ngành liên quan đến tiêu chuẩn, quy tắc, hợp đồng, kỹ thuật và kinh doanh. Cho dù thông qua việc lập kế hoạch hay tham gia vào các hoạt động và cuộc họp của chi nhánh địa phương, viết bài cho các ấn phẩm của ASSE, cố vấn cho các thành viên trẻ hoặc làm tình nguyện viên trong các ủy ban ASSE quốc gia, thì sự tham gia của các thành viên là điều cần thiết cho sự thành công của ASSE International.', 'ASSE International là một tổ chức phát triển tiêu chuẩn và chứng nhận sản phẩm được ANSI công nhận, bao gồm các thành viên đại diện cho tất cả các ngành công nghiệp ống nước và cơ khí. Các tiêu chuẩn hiệu suất sản phẩm, tiêu chuẩn trình độ chuyên môn, chứng nhận chuyên môn và chương trình chứng nhận sản phẩm của ASSE nhằm mục đích cải thiện hiệu suất và tính an toàn của hệ thống ống nước và cơ khí.', NULL, NULL, NULL, 'publisher/avatar/QNCJ2K3CA9DVRWKH1MR9.png', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4328, 'ASSP - American Society of Safety Professionals (Formerly ASSE)', 'ASSP - American Society of Safety Professionals (Formerly ASSE)', 'Founded in 1911, the American Society of Safety Engineers (ASSE) is the world\'s oldest and largest professional safety organization committed to protecting people, property and the environment. ASSE is responsible for several American National Standards Institute (ANSI) committees and leads the way in setting standards for safety in construction, demolition, motor vehicle operations, hazardous energy, fall protection, mold remediation, training and certification.\nThe American Society of Safety Professionals (ASSP), formerly known as American Society of Safety Engineers (ASSE), is a global organization of occupational safety and health (OSH) professional members who manage, supervise, research and consult on work-related OSH concerns across all industries. Society members use risk-based approaches to prevent workplace fatalities, injuries and illnesses.\nThe organization was founded on 25 March 1911 in the wake of the Triangle Shirtwaist Factory fire, after lack of safety measures caused the death of 146 garment workers.\nASSP offers continuing education to OSH professionals, participates in developing industry standards, pursues initiatives that aim to build the reputation of the OSH profession, and provides access to various member communities. The organization has alliances with federal agencies such as Occupational Safety and Health Administration (OSHA) and National Institute for Occupational Safety and Health (NIOSH). ASSP also works with the Accreditation Board for Engineering & Technology (ABET) to develop accreditation standards for OSH-related degree programs and has worked with the International Network of Safety and Health Practitioner Organizations (INSHPO) to develop a professional capability framework for OSH professionals.\nThe American Society of Safety Professionals has 151 local chapters, 40 sections and 65 student sections located across 75 countries. Members live in regions including the Americas, Europe, the Middle East, Africa, Asia and Australia.\nThe ASSP has specialty communities that focus on particular industries or fields of professional practice, including academia, construction, consulting, engineering, environment, ergonomics, fire protection, healthcare, industrial hygiene, international, management, manufacturing, oil, gas, mining and minerals, public sector, risk management/insurance and transportation. The organization also has four common interest groups – Blacks in Safety Excellence (BISE), Hispanic Safety Professionals, Women in Safety Excellence (WISE) and Young Professionals in OSH.\nASSP is secretariat for several American National Standards Institute (ANSI) committees and administrator for the United States technical advisory groups (TAG) to the International Organization for Standardization (ISO) on fall protection, risk management and occupational health and safety management systems. Members represent the organization on a wide range of safety and health committees affiliated with standards-development organizations such as National Fire Protection Association (NFPA), International Safety Equipment Association (ISEA) and ASTM International.]\nThe committees develop and maintain the standards, ensure that the revision process is timely and in accordance with ANSI procedures, and publish the final product. ASSP is secretariat or administrator for the U.S. TAG for the following standards:]\n• Confined Spaces (Z117)\n• Construction and Demolition Operations (A10)\n• Fall Protection and Fall Restraint (Z359)\n• Fleet Safety (Z15)\n• Hydrogen Sulfide Training (Z390)\n• Lockout/Tagout and Alternative Methods (Z244)\n• Occupational Health and Safety Management Systems (Z10, ISO 45001)\n• OSH Training (Z490)\n• Prevention Through Design (Z590.3)\n• Risk Management (ISO 31000/ANSI/ASSP Z690)\n• Scope and Functions of the Professional Safety Position (Z590.2)\n• Ventilation Systems (Z9)\n• Walking/Working Surfaces (A1264)', 'Được thành lập vào năm 1911, Hiệp hội Kỹ sư An toàn Hoa Kỳ (ASSE) là tổ chức an toàn chuyên nghiệp lâu đời nhất và lớn nhất thế giới cam kết bảo vệ con người, tài sản và môi trường. ASSE chịu trách nhiệm cho một số ủy ban của Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) và đi đầu trong việc thiết lập các tiêu chuẩn về an toàn trong xây dựng, phá dỡ, vận hành xe cơ giới, năng lượng nguy hiểm, bảo vệ chống rơi, khắc phục nấm mốc, đào tạo và cấp chứng chỉ.\nHiệp hội Chuyên gia An toàn Hoa Kỳ (ASSP), trước đây được gọi là Hiệp hội Kỹ sư An toàn Hoa Kỳ (ASSE), là một tổ chức toàn cầu gồm các thành viên chuyên nghiệp về an toàn và sức khỏe nghề nghiệp (OSH) quản lý, giám sát, nghiên cứu và tư vấn về các mối quan tâm về OSH liên quan đến công việc trong tất cả các ngành. Các thành viên của hiệp hội sử dụng các phương pháp tiếp cận dựa trên rủi ro để ngăn ngừa tử vong, thương tích và bệnh tật tại nơi làm việc.\nTổ chức được thành lập vào ngày 25 tháng 3 năm 1911 sau vụ cháy Nhà máy Triangle Shirtwaist, sau khi thiếu các biện pháp an toàn khiến 146 công nhân may mặc tử vong.\nASSP cung cấp giáo dục liên tục cho các chuyên gia OSH, tham gia xây dựng các tiêu chuẩn của ngành, theo đuổi các sáng kiến ​​nhằm xây dựng danh tiếng của nghề OSH và cung cấp quyền truy cập cho nhiều cộng đồng thành viên khác nhau. Tổ chức này có liên minh với các cơ quan liên bang như Cơ quan Quản lý An toàn và Sức khỏe Nghề nghiệp (OSHA) và Viện Quốc gia về An toàn và Sức khỏe Nghề nghiệp (NIOSH). ASSP cũng hợp tác với Hội đồng Công nhận Kỹ thuật & Công nghệ (ABET) để xây dựng các tiêu chuẩn công nhận cho các chương trình cấp bằng liên quan đến OSH và đã hợp tác với Mạng lưới Quốc tế các Tổ chức Thực hành An toàn và Sức khỏe (INSHPO) để xây dựng khuôn khổ năng lực chuyên môn cho các chuyên gia OSH.\nHiệp hội Chuyên gia An toàn Hoa Kỳ có 151 chi hội địa phương, 40 bộ phận và 65 bộ phận sinh viên tại 75 quốc gia. Các thành viên sống ở các khu vực bao gồm Châu Mỹ, Châu Âu, Trung Đông, Châu Phi, Châu Á và Úc.\nASSP có các cộng đồng chuyên ngành tập trung vào các ngành công nghiệp hoặc lĩnh vực hành nghề chuyên môn cụ thể, bao gồm học thuật, xây dựng, tư vấn, kỹ thuật, môi trường, công thái học, phòng cháy chữa cháy, chăm sóc sức khỏe, vệ sinh công nghiệp, quốc tế, quản lý, sản xuất, dầu khí, khai thác mỏ và khoáng sản, khu vực công, quản lý rủi ro/bảo hiểm và vận tải. Tổ chức này cũng có bốn nhóm lợi ích chung – Người da đen trong sự xuất sắc về an toàn (BISE), Chuyên gia an toàn gốc Tây Ban Nha, Phụ nữ trong sự xuất sắc về an toàn (WISE) và Chuyên gia trẻ trong OSH.\nASSP là ban thư ký cho một số ủy ban của Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) và là quản trị viên cho các nhóm cố vấn kỹ thuật Hoa Kỳ (TAG) cho Tổ chức Tiêu chuẩn hóa Quốc tế (ISO) về bảo vệ chống rơi ngã, quản lý rủi ro và hệ thống quản lý an toàn và sức khỏe nghề nghiệp. Các thành viên đại diện cho tổ chức trong nhiều ủy ban an toàn và sức khỏe liên kết với các tổ chức phát triển tiêu chuẩn như Hiệp hội Phòng cháy chữa cháy Quốc gia (NFPA), Hiệp hội Thiết bị An toàn Quốc tế (ISEA) và ASTM International.]\nCác ủy ban phát triển và duy trì các tiêu chuẩn, đảm bảo rằng quá trình sửa đổi diễn ra kịp thời và tuân thủ các thủ tục của ANSI, đồng thời công bố sản phẩm cuối cùng. ASSP là ban thư ký hoặc quản trị viên của U.S. TAG cho các tiêu chuẩn sau:]\n• Không gian hạn chế (Z117)\n• Hoạt động xây dựng và phá dỡ (A10)\n• Bảo vệ chống rơi và hạn chế rơi (Z359)\n• An toàn đội xe (Z15)\n• Đào tạo về hydro sunfua (Z390)\n• Khóa/gắn thẻ và các phương pháp thay thế (Z244)\n• Hệ thống quản lý an toàn và sức khỏe nghề nghiệp (Z10, ISO 45001)\n• Đào tạo về OSH (Z490)\n• Phòng ngừa thông qua thiết kế (Z590.3)\n• Quản lý rủi ro (ISO 31000/ANSI/ASSP Z690)\n• Phạm vi và chức năng của vị trí an toàn chuyên nghiệp (Z590.2)\n• Hệ thống thông gió (Z9)\n• Bề mặt đi bộ/làm việc (A1264)', 'Được thành lập vào năm 1911, Hiệp hội Kỹ sư An toàn Hoa Kỳ (ASSE) là tổ chức an toàn chuyên nghiệp lâu đời nhất và lớn nhất thế giới cam kết bảo vệ con người, tài sản và môi trường. ASSE chịu trách nhiệm cho một số ủy ban của Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) và đi đầu trong việc thiết lập các tiêu chuẩn về an toàn trong xây dựng, phá dỡ, vận hành xe cơ giới, năng lượng nguy hiểm, bảo vệ chống rơi, khắc phục nấm mốc, đào tạo và cấp chứng chỉ.', NULL, NULL, NULL, 'publisher/avatar/LFE4PB1S6EV7B5SMWIGY.jpg', 0),
(4329, 'ASTM - ASTM International', 'ASTM - ASTM International', 'ASTM International, formerly known as the American Society for Testing and Materials (ASTM), is a globally recognized leader in the development and delivery of international voluntary consensus standards. Today, some 13,000 ASTM standards are used around the world to improve product quality, enhance safety, facilitate market access and trade, and build consumer confidence.', 'Tiêu chuẩn ASTM xây dựng trên cơ sở tham gia của hơn 30.000 thành viên ASTM. Các chuyên gia kỹ thuật này đại diện cho các nhà sản xuất, người sử dụng, người tiêu dùng, chính phủ và viện nghiên cứu từ hơn 120 quốc gia. Việc tham gia ASTM được mở cho tất cả các bên quan tâm, dù ở bất cứ nơi nào trên thế giới. \n\nGiới thiệu Hiệp hội Thử nghiệm và Vật liệu Hoa Kỳ (ASTM)  \n\nHiệp hội Thử nghiệm và Vật liệu Hoa Kỳ (ASTM) là một tổ chức tiêu chuẩn quốc tế tập trung phát triển các tiêu chuẩn kỹ thuật cho nhiều ứng dụng công nghiệp. Tổ chức này được thành lập vào năm 1898 bởi Charles Dudley, một nhà hóa học của Đường sắt Pennsylvania. Trong khi điều tra các vết nứt do gãy đường ray, ông lưu ý rằng có những khác biệt khác nhau về chất lượng thép và đã công bố nghiên cứu của mình về chủ đề này. Điều này sau đó dẫn đến việc soạn thảo các tiêu chuẩn ban đầu đã phát triển qua nhiều năm. ASTM được đổi tên thành ASTM International vào năm 2001 và ngày nay có trụ sở chính đặt tại West Conshohocken, Pennsylvania. ASTM International không chính thức xây dựng các tiêu chuẩn của mình, nhưng những thực hành này có thể được thực thi theo các quy định của liên bang, tiểu bang và thành phố. \n\nASTM là một trong những tổ chức xây dựng tiêu chuẩn tự nguyện lớn nhất thế giới về tiêu chuẩn kỹ thuật đối với nguyên liệu, sản phẩm, hệ thống và dịch vụ. Được biết đến về chất lượng kỹ thuật cao và bám sát thị trường, các tiêu chuẩn của ASTM có một vị trí quan trọng trong cơ sở hạ tầng thông tin giúp hướng dẫn thiết kế, sản xuất và kinh doanh trong nền kinh tế toàn cầu.  \n\nTin tức về Tiêu chuẩn hóa được công bố trên trang web của ASTM và bạn cũng có thể mua Quy định kỹ thuật tiêu chuẩn thông qua trang web của họ. Các tiêu chuẩn được công bố hàng năm cho các chủ đề chất lượng kỹ thuật như kim loại, nhựa, dầu mỏ, dệt may, sơn, xây dựng, năng lượng, môi trường, y tế, điện tử và Thiết bị bảo hộ cá nhân (PPE). Có hơn 30.000 thành viên tình nguyện ở hơn 140 quốc gia. Tôi đã làm việc với các tiêu chuẩn ASTM khác nhau cho cả đường ống thép và nhựa trong ngành dầu khí. Nhìn chung có sáu loại tính năng mà bạn sẽ thấy trong tiêu chuẩn ASTM, bao gồm: Phương pháp thử, Quy định kỹ thuật, Phân loại, Thực hành, Hướng dẫn và Thuật ngữ. Bạn cũng có thể xem các phần khác như Phạm vi, Tài liệu viện dẫn, Thuật ngữ, Ý nghĩa và cách sử dụng, Quy trình, Báo cáo và Từ khóa. Tài liệu có thể bao gồm dữ liệu được lập bảng, đồ thị, nghiên cứu địa điểm sơ bộ, an toàn, quy định, phương trình, đơn vị và đặc tính vật liệu.', 'ASTM Quốc tế (ASTM International), nguồn gốc là Hội Thử nghiệm và Nguyên liệu Hoa Kỳ (ASTM), được thành lập từ hơn một thế kỷ trước. ASTM là một trong những tổ chức xây dựng tiêu chuẩn tự nguyện lớn nhất thế giới về tiêu chuẩn kỹ thuật đối với nguyên liệu, sản phẩm, hệ thống và dịch vụ.', 'ASTM,ANSI/ASTM,ISO/ASTM,ASTM/ISO,ASTM/NACE,IEEE/ASTM', NULL, '01*11*11.040*13*13.040*13.060*23*23.040*25.220*59*59.080*71*71.040*71.100*75*75.100*75.160*77*77.140*83*83.080*83.140*87*87.040*87.060*91*91.100', 'publisher/avatar/YG8KN0W4JVET50EMNO6O.png', 0),
(4330, 'ATIS - The Alliance for Telecommunications Industry Solutions', 'ATIS - The Alliance for Telecommunications Industry Solutions', 'The Alliance for Telecommunications Industry Solutions (ATIS) is a standards organization that develops technical and operational standards and solutions for the ICT industry, headquartered in Washington, D.C. The organization is accredited by the American National Standards Institute (ANSI). It is the North American Organizational Partner for the 3rd Generation Partnership Project (3GPP), a founding Partner of the oneM2M global initiative, a member of and major U.S. contributor to the International Telecommunication Union (ITU), as well as a member of the Inter-American Telecommunication Commission (CITEL). \nATIS has 150 member companies, including various telecommunications service providers, equipment manufacturers, and vendors. The organization encompasses numerous industry committees and fora, which discuss, evaluate, and author guidelines concerning such topics as 5G, cybersecurity, network reliability, technological interoperability, emergency services, billing, M2M, the all IP transition, and network function virtualization. \n\n.', 'Liên minh Giải pháp Ngành Viễn thông (ATIS) là một tổ chức tiêu chuẩn phát triển các tiêu chuẩn và giải pháp kỹ thuật và vận hành cho ngành ICT, có trụ sở chính tại Washington, D.C. Tổ chức này được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận. Đây là Đối tác Tổ chức Bắc Mỹ cho Dự án Đối tác Thế hệ thứ 3 (3GPP), Đối tác sáng lập của sáng kiến ​​toàn cầu oneM2M, thành viên và là nhà đóng góp chính của Hoa Kỳ cho Liên minh Viễn thông Quốc tế (ITU), cũng như là thành viên của Ủy ban Viễn thông Liên Mỹ (CITEL).\nATIS có 150 công ty thành viên, bao gồm nhiều nhà cung cấp dịch vụ viễn thông, nhà sản xuất thiết bị và nhà cung cấp. Tổ chức này bao gồm nhiều ủy ban và diễn đàn trong ngành, thảo luận, đánh giá và biên soạn các hướng dẫn liên quan đến các chủ đề như 5G, an ninh mạng, độ tin cậy của mạng, khả năng tương tác công nghệ, dịch vụ khẩn cấp, thanh toán, M2M, quá trình chuyển đổi toàn bộ IP và ảo hóa chức năng mạng.', 'Liên minh Giải pháp Ngành Viễn thông (ATIS) là một tổ chức tiêu chuẩn phát triển các tiêu chuẩn và giải pháp kỹ thuật và vận hành cho ngành ICT, có trụ sở chính tại Washington, D.C. Tổ chức này được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận. Đây là Đối tác Tổ chức Bắc Mỹ cho Dự án Đối tác Thế hệ thứ 3 (3GPP), Đối tác sáng lập của sáng kiến ​​toàn cầu oneM2M, thành viên và là nhà đóng góp chính của Hoa Kỳ cho Liên minh Viễn thông Quốc tế (ITU), cũng như là thành viên của Ủy ban Viễn thông Liên Mỹ (CITEL).', NULL, NULL, '33*33.040*33.060*33.080*33.180*65.060', 'publisher/avatar/7K71LKV4D9IXGFBHJ9SJ.jpg', 0),
(4331, 'AVIXA - Audiovisual and Integrated Experience Association', 'AVIXA - Audiovisual and Integrated Experience Association', 'It all started in 1939, when eight AV dealers got together to form the National Association of Visual Education Dealers (NAVED) with the goal of increasing American government funding of education. In 1949, NAVED merged with the Allied Non-Theatrical Film Association to form the National Audio-Visual Association (NAVA). NAVA changed its name to the International Communications Industries Association (ICIA) in 1983, which became InfoComm International in 2005. InfoComm became the Audiovisual and Integrated Experience Association (AVIXA) in 2017, to reflect a more diverse membership and creative outcomes.\nAV is the intersection of content, technology, and space. The AV industry is the community of manufacturers and myriad professionals that provide the tools and expertise necessary to convey ideas and enhance communication in virtually every human arena. Audiovisual systems and technologies are the building blocks that create memorable experiences and connect us to our world in every way imaginable. It’s the tremendous sound you hear at a concert, the amazing digital displays you see at a museum, the videoconferencing system you use at your office, the projected images you see at your corporate gatherings, the cool stuff in the huddle space that connects your devices to the big display, the technical wizardry that’s used in theme parks to amaze and delight you. That is all part of the AV industry. Are you getting the picture?\nWhat is AVIXA?\nWe’re part association, part society; a mix of professionals from all over the globe who create those cool experiences you have in meetings, classes, and events in offices, airports, museums, sports arenas, theatres, concerts…\nAVIXA has more than 11,400 members\nWe share our love of technology, creative content, and communication with you at events around the world with trade shows, webinars, courses, networking, and other events.\nWe’re the industry leader when it comes to professional collaboration, information, and community, leading the world with all the necessary resources: AV standards, certification, training, market intelligence, and thought leadership.\nWe’re the place where creatives who use technology for integrated experiences can come to find the AV expertise they need.\nAVIXA members realize just how significantly audiovisual technology impacts the user experience. They use technology to change how people communicate and experience the world. Does that sound like you?\nAVIXA’s AV community is brimming with manufacturers, systems integrators, dealers and distributors, consultants, programmers, live events companies, technology managers, content producers, and multimedia professionals.\nWith membership around the world in more than 80 countries, AV professionals are getting together to share their expertise and ideas', 'Mọi chuyện bắt đầu vào năm 1939, khi tám đại lý AV hợp tác với nhau để thành lập Hiệp hội các đại lý giáo dục trực quan quốc gia (NAVED) với mục tiêu tăng nguồn tài trợ của chính phủ Hoa Kỳ cho giáo dục. Năm 1949, NAVED sáp nhập với Hiệp hội phim phi sân khấu đồng minh để thành lập Hiệp hội nghe nhìn quốc gia (NAVA). NAVA đổi tên thành Hiệp hội các ngành truyền thông quốc tế (ICIA) vào năm 1983, trở thành InfoComm International vào năm 2005. InfoComm trở thành Hiệp hội trải nghiệm nghe nhìn và tích hợp (AVIXA) vào năm 2017, để phản ánh thành viên đa dạng hơn và kết quả sáng tạo hơn.\nAV là giao điểm của nội dung, công nghệ và không gian. Ngành công nghiệp AV là cộng đồng các nhà sản xuất và vô số chuyên gia cung cấp các công cụ và chuyên môn cần thiết để truyền tải ý tưởng và nâng cao giao tiếp trong hầu hết mọi lĩnh vực của con người. Các hệ thống và công nghệ nghe nhìn là những khối xây dựng tạo ra những trải nghiệm đáng nhớ và kết nối chúng ta với thế giới theo mọi cách có thể tưởng tượng được. Đó là âm thanh tuyệt vời mà bạn nghe thấy tại một buổi hòa nhạc, màn hình kỹ thuật số tuyệt vời mà bạn thấy tại một bảo tàng, hệ thống hội nghị truyền hình mà bạn sử dụng tại văn phòng, hình ảnh chiếu mà bạn thấy tại các cuộc họp công ty, những thứ thú vị trong không gian họp mặt kết nối các thiết bị của bạn với màn hình lớn, phép thuật kỹ thuật được sử dụng trong các công viên giải trí để làm bạn kinh ngạc và thích thú. Tất cả đều là một phần của ngành công nghiệp AV. Bạn có hiểu không?\nAVIXA là gì?\nChúng tôi là một phần của hiệp hội, một phần của xã hội; sự kết hợp của các chuyên gia từ khắp nơi trên thế giới tạo ra những trải nghiệm thú vị mà bạn có trong các cuộc họp, lớp học và sự kiện tại các văn phòng, sân bay, bảo tàng, đấu trường thể thao, nhà hát, buổi hòa nhạc…\nAVIXA có hơn 11.400 thành viên\nChúng tôi chia sẻ tình yêu của mình đối với công nghệ, nội dung sáng tạo và giao tiếp với bạn tại các sự kiện trên khắp thế giới với các triển lãm thương mại, hội thảo trên web, khóa học, giao lưu và các sự kiện khác.\nChúng tôi là công ty dẫn đầu ngành khi nói đến sự hợp tác chuyên nghiệp, thông tin và cộng đồng, dẫn đầu thế giới với tất cả các nguồn lực cần thiết: tiêu chuẩn AV, chứng nhận, đào tạo, thông tin thị trường và tư duy lãnh đạo.\n\nChúng tôi là nơi những người sáng tạo sử dụng công nghệ cho trải nghiệm tích hợp có thể tìm đến để tìm chuyên môn AV mà họ cần.\nCác thành viên của AVIXA nhận ra công nghệ nghe nhìn tác động đáng kể đến trải nghiệm của người dùng như thế nào. Họ sử dụng công nghệ để thay đổi cách mọi người giao tiếp và trải nghiệm thế giới. Bạn có giống vậy không?\nCộng đồng AV của AVIXA tràn ngập các nhà sản xuất, nhà tích hợp hệ thống, đại lý và nhà phân phối, cố vấn, lập trình viên, công ty sự kiện trực tiếp, quản lý công nghệ, nhà sản xuất nội dung và chuyên gia đa phương tiện.\nVới tư cách thành viên trên toàn thế giới tại hơn 80 quốc gia, các chuyên gia AV đang tập hợp lại để chia sẻ chuyên môn và ý tưởng của họ', 'AVIXA là tổ chức dẫn đầu ngành khi nói đến sự hợp tác chuyên nghiệp, thông tin và cộng đồng, dẫn đầu thế giới với tất cả các nguồn lực cần thiết: tiêu chuẩn AV, chứng nhận, đào tạo, thông tin thị trường và tư duy lãnh đạo.', NULL, NULL, NULL, 'publisher/avatar/JBQQD1SQ2V0B4EEJTRI4.jpg', 0),
(4332, 'AWC - American Wood Council', 'AWC - American Wood Council', 'The American Wood Council (AWC) is a trade association that represents North American wood products manufacturers. \nAWC\'s mission is to increase the use of wood by assuring the broad regulatory acceptance of wood products, developing design tools and guidelines for wood construction and influencing the development of public policies affecting the use of wood products.The American Wood Council (AWC) provides an organizational structure for wood products companies and associations to work together on building codes and standards, green building policy issues, and a focused set of environmental guidelines.\nNorth American membership includes companies and industry associations; among them, Boise Cascade LLC, Canfor USA/New South, Georgia-Pacific LLC, Interfor Corporation, Kapstone, Louisiana Pacific, Masonite, Norbord Inc., Plum Creek Timber, Potlatch Corp., Sierra Pacific Industries, West Fraser, West Rock Company, Weyerhaeuser Company, and the Canadian Wood Council. \nAWC was re-chartered in June 2010, with a broader mandate than a former predecessor namesake. Up until 2010, the wood products industry was represented by the American Forest & Paper Association (AF&PA), which now represents pulp and paper manufacturers.', 'Hội đồng Gỗ Hoa Kỳ (AWC) là một hiệp hội thương mại đại diện cho các nhà sản xuất sản phẩm gỗ Bắc Mỹ.\nSứ mệnh của AWC là tăng cường sử dụng gỗ bằng cách đảm bảo sự chấp nhận rộng rãi của các quy định đối với các sản phẩm gỗ, phát triển các công cụ thiết kế và hướng dẫn cho việc xây dựng bằng gỗ và tác động đến việc phát triển các chính sách công ảnh hưởng đến việc sử dụng các sản phẩm gỗ. Hội đồng Gỗ Hoa Kỳ (AWC) cung cấp một cấu trúc tổ chức cho các công ty và hiệp hội sản phẩm gỗ để cùng nhau làm việc về các quy tắc và tiêu chuẩn xây dựng, các vấn đề chính sách xây dựng xanh và một bộ hướng dẫn tập trung về môi trường.\nThành viên Bắc Mỹ bao gồm các công ty và hiệp hội ngành; trong số đó có Boise Cascade LLC, Canfor USA/New South, Georgia-Pacific LLC, Interfor Corporation, Kapstone, Louisiana Pacific, Masonite, Norbord Inc., Plum Creek Timber, Potlatch Corp., Sierra Pacific Industries, West Fraser, West Rock Company, Weyerhaeuser Company và Hội đồng Gỗ Canada.\nAWC đã được cấp lại giấy phép vào tháng 6 năm 2010, với nhiệm vụ rộng hơn so với người tiền nhiệm trước đây cùng tên. Cho đến năm 2010, ngành sản phẩm gỗ được đại diện bởi Hiệp hội Giấy và Lâm nghiệp Hoa Kỳ (AF&PA), hiện đại diện cho các nhà sản xuất bột giấy và giấy.', 'Hội đồng Gỗ Hoa Kỳ (AWC) là một hiệp hội thương mại đại diện cho các nhà sản xuất sản phẩm gỗ Bắc Mỹ. AWC đã được cấp lại giấy phép vào tháng 6 năm 2010, với nhiệm vụ rộng hơn so với người tiền nhiệm trước đây cùng tên. Cho đến năm 2010, ngành sản phẩm gỗ được đại diện bởi Hiệp hội Giấy và Lâm nghiệp Hoa Kỳ (AF&PA), hiện đại diện cho các nhà sản xuất bột giấy và giấy.', NULL, NULL, '77.140*91.040*91.080*91.100*91.220*93.010', 'publisher/avatar/CL2HT1MP5F9EOM3L3S3A.png', 0),
(4333, 'AWI - Architectural Woodwork Institute', 'AWI - Architectural Woodwork Institute', 'The Architectural Woodwork Institute has been the voice of the woodworking industry for more than half a century. Part of AWI\'s Mission is to create, publish and continually improve the architectural woodwork industry standards.\nThe Architectural Woodwork Institute (AWI), founded in 1953, is an American professional trade association. Member companies are the fabricators of fine finished woodwork, millwork, and furniture. AWI has published a Standard of Care for woodworking since 1961, called the Quality Standards Illustrated.\nFor over 70 years, the Architectural Woodwork Institute (AWI) has championed innovation, quality, and craftsmanship in architectural woodworking. Founded in Chicago in 1954, we\'ve evolved from our modest roots to nationally set and maintain the industry standards for interior architectural woodworking.\nToday, AWI stands at the forefront of the woodworking industry, offering unmatched education, networking, and compliance resources. Our dedication goes beyond setting standards, empowering member companies with tools to grow and innovate. Whether you\'re deeply immersed in or just brushing the surface of interior architectural woodworking, joining AWI opens doors to unparalleled opportunities.\nJoin AWI today and be a part of shaping the future of architectural woodworking.\nAWI standards provide woodworking businesses with a framework for achieving and demonstrating high-quality architectural woodwork. This not only enhances your reputation but also helps you meet customer expectations, reduce costs, and remain competitive in the industry.', 'Viện Đồ gỗ Kiến trúc đã là tiếng nói của ngành công nghiệp chế biến gỗ trong hơn nửa thế kỷ. Một phần trong Sứ mệnh của AWI là tạo ra, công bố và liên tục cải thiện các tiêu chuẩn của ngành công nghiệp đồ gỗ kiến ​​trúc.\nViện Đồ gỗ Kiến trúc (AWI), được thành lập vào năm 1953, là một hiệp hội thương mại chuyên nghiệp của Hoa Kỳ. Các công ty thành viên là những nhà chế tạo đồ gỗ hoàn thiện cao cấp, đồ gỗ và đồ nội thất. AWI đã công bố Tiêu chuẩn Chăm sóc cho đồ gỗ từ năm 1961, được gọi là Tiêu chuẩn Chất lượng Minh họa.\nTrong hơn 70 năm, Viện Đồ gỗ Kiến trúc (AWI) đã ủng hộ sự đổi mới, chất lượng và tay nghề thủ công trong ngành công nghiệp đồ gỗ kiến ​​trúc. Được thành lập tại Chicago vào năm 1954, chúng tôi đã phát triển từ nguồn gốc khiêm tốn của mình để thiết lập và duy trì các tiêu chuẩn của ngành trên toàn quốc đối với đồ gỗ kiến ​​trúc nội thất.\nNgày nay, AWI đi đầu trong ngành công nghiệp đồ gỗ, cung cấp các nguồn lực giáo dục, kết nối mạng và tuân thủ vô song. Sự cống hiến của chúng tôi không chỉ dừng lại ở việc thiết lập các tiêu chuẩn, mà còn trao quyền cho các công ty thành viên các công cụ để phát triển và đổi mới. Cho dù bạn đang đắm chìm sâu sắc hay chỉ lướt qua bề mặt của nghề mộc kiến ​​trúc nội thất, việc tham gia AWI sẽ mở ra cánh cửa đến với những cơ hội vô song.\nHãy tham gia AWI ngay hôm nay và trở thành một phần trong việc định hình tương lai của nghề mộc kiến ​​trúc.\nCác tiêu chuẩn của AWI cung cấp cho các doanh nghiệp chế biến gỗ một khuôn khổ để đạt được và chứng minh nghề mộc kiến ​​trúc chất lượng cao. Điều này không chỉ nâng cao danh tiếng của bạn mà còn giúp bạn đáp ứng được kỳ vọng của khách hàng, giảm chi phí và duy trì khả năng cạnh tranh trong ngành.', 'Viện Đồ gỗ Kiến trúc đã là tiếng nói của ngành công nghiệp chế biến gỗ trong hơn nửa thế kỷ. Một phần trong Sứ mệnh của AWI là tạo ra, công bố và liên tục cải thiện các tiêu chuẩn của ngành công nghiệp đồ gỗ kiến ​​trúc.', NULL, NULL, NULL, 'publisher/avatar/43OJ9WEE9GN2KA4Q4L2A.png', 0),
(4334, 'AWPA - American Wood Protection Association', 'AWPA - American Wood Protection Association', 'The American Wood Protection Association (AWPA, formerly the American Wood Preservers\' Association) is a non-profit organization responsible for promulgating voluntary wood preservation standards. AWPA Standards are developed by its technical committees in an ANSI-accredited, consensus-based process that involves individuals from all facets of wood preservation: Producers of preservatives and preservative components; producers of treated and untreated wood products; end users of treated wood; engineers, architects and building code officials; government entities, academia, and other groups with a general interest in wood preservation. AWPA\'s Standards are universally specified for wood preservation in the USA, and are recognized worldwide.\nThe American Wood Protection Association is an international, non-profit, technical society founded in 1904 to provide a common forum for the exchange of technical information between industry, research and users of treated wood.\nAWPA is the principal Standards-writing body for methods, preservatives, and other technologies which protect wood and wood-based products.  Individuals with various areas of interest including consumers, end-users, government, academia, specifiers and producers meet on a regular basis to develop and maintain these Standards for preservatives and other protectants, treatments, testing methods, quality control and inspection procedures for treated wood products.  AWPA relies on the expertise of and information voluntarily developed by technically qualified members.\nAWPA Standards help enhance product quality and build the confidence of product end-users. These standards are recognized and used by most, if not all, specifiers of treated wood including electrical utility, marine, road and building construction as well as by local, state and federal governments through the use of the major model building codes.\nAWPA believes that an open, consensus process is necessary to ensure development of technically competent, credible standards.  Membership in the Association is open to all interested individuals.  The standards development meetings are open to all persons whether or not they are members of the Association.\nDISCLAIMER:  In the judgment of the membership of the American Wood Protection Association, AWPA Standards represent the preferred wood preservation specifications, processes, penetration, and retention in the present state of research and technical knowledge.  AWPA Standards are voluntary and are provided for informational purposes only.  AWPA has no control over the processes used to employ AWPA standards or possible variations in materials, application, and manner of use.  AWPA assumes no responsibility for results of use or performance of products represented as meeting or conforming to AWPA Standards.  AWPA is not responsible for, and expressly disclaims all liability for, damages of any kind arising out of use, reference to, reliance on, or performance of any information contained herein.\nIMPORTANT:  Various Federal, State, and Local regulations may govern the use of products or processes standardized by AWPA.  The existence of an AWPA Standard for a product or process does not imply that it is lawfully permitted for use in all potential applications.  AWPA Standards are not to be regarded as legal or other professional advice.\nTRADEMARKS AND COPYRIGHT:  The various AWPA logos are trademarks of the American Wood Protection Association, Inc., and shall not be used for any reason without prior written consent from AWPA.  The terms \"AWPA\" and \"American Wood Protection Association\", the identifiers of AWPA Standards (e.g., U1, T1, M4, etc.), and Use Category designations (e.g., UC1, UC3B, UC4A, etc.) are AWPA trademarks and the intellectual property of AWPA and its Technical Committees.  AWPA grants a royalty-free license to use these trademarks for the limited purpose of labeling treated wood products which fully meet AWPA Standards.  The AWPA Standards are copyrighted documents and subject to federal and international intellectual property laws, and may not be reproduced without prior written consent from AWPA.  Please contact us if additional information is required', 'Hiệp hội Bảo vệ Gỗ Hoa Kỳ (AWPA, trước đây là Hiệp hội Bảo quản Gỗ Hoa Kỳ) là một tổ chức phi lợi nhuận chịu trách nhiệm ban hành các tiêu chuẩn bảo quản gỗ tự nguyện. Các Tiêu chuẩn AWPA được các ủy ban kỹ thuật của tổ chức xây dựng theo quy trình dựa trên sự đồng thuận được ANSI công nhận, có sự tham gia của các cá nhân từ mọi khía cạnh của công tác bảo quản gỗ: Nhà sản xuất chất bảo quản và thành phần bảo quản; nhà sản xuất các sản phẩm gỗ đã qua xử lý và chưa qua xử lý; người dùng cuối cùng của gỗ đã qua xử lý; kỹ sư, kiến ​​trúc sư và viên chức quản lý quy định xây dựng; các cơ quan chính phủ, học viện và các nhóm khác có mối quan tâm chung đến công tác bảo quản gỗ. Các Tiêu chuẩn của AWPA được chỉ định chung cho công tác bảo quản gỗ tại Hoa Kỳ và được công nhận trên toàn thế giới.\nHiệp hội Bảo vệ Gỗ Hoa Kỳ là một hiệp hội kỹ thuật phi lợi nhuận quốc tế được thành lập vào năm 1904 để cung cấp một diễn đàn chung cho việc trao đổi thông tin kỹ thuật giữa ngành công nghiệp, nghiên cứu và người sử dụng gỗ đã qua xử lý.\nAWPA là cơ quan soạn thảo Tiêu chuẩn chính cho các phương pháp, chất bảo quản và các công nghệ khác bảo vệ gỗ và các sản phẩm từ gỗ. Các cá nhân có nhiều lĩnh vực quan tâm khác nhau bao gồm người tiêu dùng, người dùng cuối, chính phủ, học viện, người chỉ định và nhà sản xuất họp thường xuyên để phát triển và duy trì các Tiêu chuẩn này cho chất bảo quản và các chất bảo vệ khác, phương pháp xử lý, phương pháp thử nghiệm, quy trình kiểm soát chất lượng và kiểm tra đối với các sản phẩm gỗ đã qua xử lý. AWPA dựa vào chuyên môn và thông tin do các thành viên có trình độ kỹ thuật tự nguyện phát triển.\nCác Tiêu chuẩn AWPA giúp nâng cao chất lượng sản phẩm và xây dựng lòng tin của người dùng cuối sản phẩm. Các tiêu chuẩn này được hầu hết, nếu không muốn nói là tất cả, những người chỉ định về gỗ đã qua xử lý, bao gồm tiện ích điện, hàng hải, đường bộ và xây dựng cũng như chính quyền địa phương, tiểu bang và liên bang công nhận và sử dụng thông qua việc sử dụng các quy tắc xây dựng mẫu chính.\nAWPA tin rằng cần có một quy trình đồng thuận, cởi mở để đảm bảo phát triển các tiêu chuẩn đáng tin cậy, có năng lực kỹ thuật. Tư cách thành viên của Hiệp hội mở cho tất cả các cá nhân quan tâm. Các cuộc họp phát triển tiêu chuẩn mở cho tất cả mọi người bất kể họ có phải là thành viên của Hiệp hội hay không.\nTUYÊN BỐ MIỄN TRỪ TRÁCH NHIỆM: Theo đánh giá của các thành viên Hiệp hội Bảo vệ Gỗ Hoa Kỳ, Tiêu chuẩn AWPA đại diện cho các thông số kỹ thuật, quy trình, độ thấm và khả năng lưu giữ gỗ được ưa chuộng trong tình trạng nghiên cứu và kiến ​​thức kỹ thuật hiện tại. Tiêu chuẩn AWPA là tự nguyện và chỉ được cung cấp cho mục đích thông tin. AWPA không kiểm soát các quy trình được sử dụng để áp dụng các tiêu chuẩn AWPA hoặc các biến thể có thể có về vật liệu, ứng dụng và cách sử dụng. AWPA không chịu trách nhiệm về kết quả sử dụng hoặc hiệu suất của các sản phẩm được trình bày là đáp ứng hoặc tuân thủ Tiêu chuẩn AWPA. AWPA không chịu trách nhiệm và từ chối mọi trách nhiệm pháp lý đối với các thiệt hại dưới bất kỳ hình thức nào phát sinh do sử dụng, tham khảo, tin cậy hoặc thực hiện bất kỳ thông tin nào có trong tài liệu này.\nQUAN TRỌNG: Các quy định khác nhau của Liên bang, Tiểu bang và Địa phương có thể chi phối việc sử dụng các sản phẩm hoặc quy trình do AWPA chuẩn hóa. Sự tồn tại của Tiêu chuẩn AWPA đối với một sản phẩm hoặc quy trình không có nghĩa là sản phẩm hoặc quy trình đó được phép sử dụng hợp pháp trong mọi ứng dụng tiềm năng. Tiêu chuẩn AWPA không được coi là lời khuyên pháp lý hoặc lời khuyên chuyên môn khác.\nTHƯƠNG HIỆU VÀ BẢN QUYỀN: Các logo AWPA khác nhau là thương hiệu của American Wood Protection Association, Inc., và không được sử dụng vì bất kỳ lý do nào mà không có sự đồng ý trước bằng văn bản của AWPA. Các thuật ngữ \"AWPA\" và \"American Wood Protection Association\", các mã định danh của Tiêu chuẩn AWPA (ví dụ: U1, T1, M4, v.v.) và các ký hiệu Danh mục sử dụng (ví dụ: UC1, UC3B, UC4A, v.v.) là thương hiệu của AWPA và là tài sản trí tuệ của AWPA và các Ủy ban Kỹ thuật của AWPA. AWPA cấp giấy phép miễn phí bản quyền để sử dụng các thương hiệu này cho mục đích hạn chế là dán nhãn các sản phẩm gỗ đã qua xử lý đáp ứng đầy đủ Tiêu chuẩn AWPA. Tiêu chuẩn AWPA là các tài liệu có bản quyền và tuân theo luật sở hữu trí tuệ liên bang và quốc tế, và không được sao chép mà không có sự đồng ý trước bằng văn bản của AWPA. Vui lòng liên hệ với chúng tôi nếu cần thêm thông tin', 'Hiệp hội Bảo vệ Gỗ Hoa Kỳ (AWPA, trước đây là Hiệp hội Bảo quản Gỗ Hoa Kỳ) là một tổ chức phi lợi nhuận chịu trách nhiệm ban hành các tiêu chuẩn bảo quản gỗ tự nguyện. Các Tiêu chuẩn AWPA được các ủy ban kỹ thuật của tổ chức xây dựng theo quy trình dựa trên sự đồng thuận được ANSI công nhận, có sự tham gia của các cá nhân từ mọi khía cạnh của công tác bảo quản gỗ: Nhà sản xuất chất bảo quản và thành phần bảo quản; nhà sản xuất các sản phẩm gỗ đã qua xử lý và chưa qua xử lý; người dùng cuối cùng của gỗ đã qua xử lý; kỹ sư, kiến ​​trúc sư và viên chức quản lý quy định xây dựng; các cơ quan chính phủ, học viện và các nhóm khác có mối quan tâm chung đến công tác bảo quản gỗ. Các Tiêu chuẩn của AWPA được chỉ định chung cho công tác bảo quản gỗ tại Hoa Kỳ và được công nhận trên toàn thế giới.', NULL, NULL, NULL, 'publisher/avatar/L3JYD3FRO27XU5EVIP7B.png', 0),
(4335, 'AWS - American Welding Society', 'AWS - American Welding Society', 'AWS - American Welding Society', 'AWS (American Welding Society) không phải là một tiêu chuẩn, mà là một tổ chức chuyên về hàn và liên quan đến công nghệ hàn tại Hoa Kỳ.\n\nAWS, được thành lập vào năm 1919, là một tổ chức chuyên nghiên cứu, giáo dục và tiêu chuẩn hóa trong lĩnh vực hàn. Nhiệm vụ chính của AWS là thúc đẩy sự phát triển và sử dụng các phương pháp hàn tiên tiến, nâng cao kiến thức và kỹ năng của các nhà hàn, đảm bảo chất lượng và an toàn trong quá trình hàn, và thiết lập các tiêu chuẩn kỹ thuật liên quan đến hàn.\n\nAWS cung cấp một loạt các chứng chỉ và khóa học về hàn cho các chuyên gia và công nhân trong ngành công nghiệp hàn. Tổ chức này cũng công bố các quy trình, quy định và tiêu chuẩn kỹ thuật liên quan đến hàn, bao gồm quy tắc thiết kế hàn, phương pháp thử nghiệm và xác nhận chất lượng hàn, mã đánh giá kỹ thuật và hướng dẫn về an toàn trong quá trình hàn.\n\nCác tiêu chuẩn và quy tắc của AWS được sử dụng rộng rãi trong ngành công nghiệp hàn tại Hoa Kỳ và có thể cũng áp dụng trong một số quốc gia khác. Tuy nhiên, AWS không phải là một tiêu chuẩn quốc tế và không có tiếng trọng như các tổ chức tiêu chuẩn hóa quốc tế khác như ISO (Tổ chức Tiêu chuẩn Hóa Quốc tế).', 'AWS (American Welding Society) không phải là một tiêu chuẩn, mà là một tổ chức chuyên về hàn và liên quan đến công nghệ hàn tại Hoa Kỳ.', 'AWS,ANSI/AWS,ANSI/AASHTO/AWS', 'Tiêu chuẩn Hiệp hội Hàn Hoa Kỳ (AWS), American Welding Society (AWS), AWS, Hàn, Công nghệ hàn, Tiêu chuẩn hàn', '25.140*91.220', 'publisher/avatar/NVCP9XZ5BBVRBT73J33I.png', 0),
(4336, 'AWWA - American Water Works Association', 'AWWA - American Water Works Association', 'AWWA is the world\'s largest organization of water supply professionals, representing the entire industry spectrum of treatment plant operators and managers, scientists, environmentalists, manufacturers, academicians, regulators, and utilities. AWWA standards cover hundreds of products and procedures.', 'AWWA (American Water Works Association) là Hiệp hội Công trình Nước Hoa Kỳ, một tổ chức chuyên về nghiên cứu, giáo dục và tiêu chuẩn hóa trong lĩnh vực nguồn nước và công trình cấp nước tại Hoa Kỳ.\n\nAWWA được thành lập vào năm 1881 và hiện nay là một tổ chức hàng đầu trong ngành công trình cấp nước tại Hoa Kỳ. Nhiệm vụ chính của AWWA là nghiên cứu, phát triển và chia sẻ kiến thức về nguồn nước, quản lý và vận hành hệ thống cấp nước, công nghệ và tiêu chuẩn liên quan. AWWA cũng cung cấp các khóa học, tài liệu hướng dẫn và các dịch vụ tư vấn để hỗ trợ các chuyên gia và chuyên gia trong ngành nước.\n\nMột phần quan trọng của hoạt động của AWWA là việc phát triển và công bố các tiêu chuẩn kỹ thuật áp dụng cho công trình cấp nước. Các tiêu chuẩn này bao gồm các yêu cầu về chất lượng nước, thiết kế và xây dựng hệ thống cấp nước, quy trình điều hành và bảo trì, an toàn và bảo vệ môi trường. Các tiêu chuẩn AWWA đóng vai trò quan trọng trong việc đảm bảo tính an toàn, hiệu suất và bền vững của hệ thống cấp nước tại Hoa Kỳ.', 'AWWA (American Water Works Association) là Hiệp hội Công trình Nước Hoa Kỳ, một tổ chức chuyên về nghiên cứu, giáo dục và tiêu chuẩn hóa trong lĩnh vực nguồn nước và công trình cấp nước tại Hoa Kỳ.', 'AWWA,ANSI/AWWA,ANSI/ASME-ITI/AWWA', 'Hiệp hội Công trình Nước Hoa Kỳ (AWWA), American Water Works Association (AWWA), AWWA, Công trình nước, Tiêu chuẩn hiệp hội', '13.060*23.020*23.040*23.060*91.140.60', 'publisher/avatar/UPBT7MCHZJ37MK3712Z0.png', 0),
(4337, 'B11 - B11 Standards, Inc.', 'B11 - B11 Standards, Inc.', 'B11 Standards, Inc. is ANSI-accredited Standards Developing Organization that administers and develops the ANSI B11 series of American National Standards and Technical Report on machine/machine too/machinery safety. B11 Standards Inc. also participates in a very large number of both national and international standards development activities.\nThe ANSI B11 series of American National Standards and Technical Reports consists of nearly three dozen different documents that deal with machine / machinery / machine tool safety, and they specify requirements for both the manufacturers (suppliers) and users of the machines.\nThe American National Standards Institute (ANSI) accredits Standards Developing Organizations to develop voluntary consensus standards according to rigorous procedures and approves those resultant American National Standards.\nThese documents are used frequently both by federal OSHA and its state counterparts or related agencies with regard to employers and their responsibility to provide a safe and healthful workplace, and in interpreting the existing workplace safety and health requirements enforced by the agencies (such as OSHA\'s Lockout/Tagout and Machine Guarding Standards) and in initiating rulemakings to amend existing rules or adopt new rules governing the control of workplace hazards. \nThey are also frequently used by the legal community (both plaintiff and defense) in product liability cases regarding the machinery or equipment supplier.  Having a standard against which can be measured the relative risk of designs offers an objective method of review.', 'B11 Standards, Inc. là Tổ chức Phát triển Tiêu chuẩn được ANSI công nhận, quản lý và phát triển loạt Tiêu chuẩn Quốc gia Hoa Kỳ ANSI B11 và Báo cáo Kỹ thuật về an toàn máy móc/máy móc quá/máy móc. B11 Standards Inc. cũng tham gia vào rất nhiều hoạt động phát triển tiêu chuẩn quốc gia và quốc tế.\nLoạt Tiêu chuẩn Quốc gia Hoa Kỳ ANSI B11 và Báo cáo Kỹ thuật bao gồm gần ba chục tài liệu khác nhau liên quan đến an toàn máy móc/máy móc/máy công cụ và chúng chỉ định các yêu cầu cho cả nhà sản xuất (nhà cung cấp) và người sử dụng máy móc.\nViện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận các Tổ chức Phát triển Tiêu chuẩn để phát triển các tiêu chuẩn đồng thuận tự nguyện theo các quy trình nghiêm ngặt và phê duyệt các Tiêu chuẩn Quốc gia Hoa Kỳ kết quả đó.\nCác tài liệu này thường được sử dụng bởi cả OSHA liên bang và các cơ quan đối tác cấp tiểu bang hoặc các cơ quan liên quan liên quan đến người sử dụng lao động và trách nhiệm của họ trong việc cung cấp nơi làm việc an toàn và lành mạnh, và trong việc giải thích các yêu cầu về an toàn và sức khỏe tại nơi làm việc hiện hành do các cơ quan thực thi (chẳng hạn như Tiêu chuẩn Khóa/Gắn thẻ và Bảo vệ Máy móc của OSHA) và trong việc khởi xướng các quy định để sửa đổi các quy định hiện hành hoặc thông qua các quy định mới quản lý việc kiểm soát các mối nguy hiểm tại nơi làm việc.\nChúng cũng thường được cộng đồng pháp lý (cả nguyên đơn và bị đơn) sử dụng trong các vụ kiện về trách nhiệm sản phẩm liên quan đến nhà cung cấp máy móc hoặc thiết bị. Việc có một tiêu chuẩn để có thể đo lường rủi ro tương đối của các thiết kế mang lại một phương pháp đánh giá khách quan.', 'B11 Standards, Inc. là Tổ chức Phát triển Tiêu chuẩn được ANSI công nhận, quản lý và phát triển loạt Tiêu chuẩn Quốc gia Hoa Kỳ ANSI B11 và Báo cáo Kỹ thuật về an toàn máy móc/máy móc quá/máy móc. B11 Standards Inc. cũng tham gia vào rất nhiều hoạt động phát triển tiêu chuẩn quốc gia và quốc tế.', NULL, NULL, NULL, 'publisher/avatar/GQX6P5I5SITLE1ND9HJV.jpg', 0),
(4338, 'BHMA - Builders Hardware Manufacturers Association', 'BHMA - Builders Hardware Manufacturers Association', 'Representing manufacturers of hardware for the commercial building and construction industries, BHMA is the only U.S. organization accredited by the American National Standards Institute (ANSI) to develop and maintain performance standards for architectural hardware.\nThe Builders Hardware Manufacturers Association (BHMA®) is the trade association for North American manufacturers of commercial builders\' hardware. BHMA® is involved in standards, codes and life safety regulations and other activities that specifically impact builders’ hardware performance standards for locks, closers, exit devices and other builders’ hardware. It the only organization accredited by the American National Standards Institute (ANSI) to develop and maintain builders’ hardware performance standards.\nEnhancing public safety and the security of buildings through standards, code advocacy and a commitment to fostering innovations that lead to the continuous improvement of builders hardware', 'Đại diện cho các nhà sản xuất phần cứng cho ngành xây dựng và thương mại, BHMA là tổ chức duy nhất của Hoa Kỳ được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận để phát triển và duy trì các tiêu chuẩn hiệu suất cho phần cứng kiến ​​trúc.\nHiệp hội các nhà sản xuất phần cứng xây dựng (BHMA®) là hiệp hội thương mại dành cho các nhà sản xuất phần cứng xây dựng thương mại của Bắc Mỹ. BHMA® tham gia vào các tiêu chuẩn, quy định và quy tắc an toàn tính mạng và các hoạt động khác tác động cụ thể đến các tiêu chuẩn hiệu suất phần cứng của nhà xây dựng đối với khóa, thiết bị đóng, thiết bị thoát hiểm và các phần cứng khác của nhà xây dựng. Đây là tổ chức duy nhất được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận để phát triển và duy trì các tiêu chuẩn hiệu suất phần cứng của nhà xây dựng.\nNâng cao an toàn công cộng và an ninh của các tòa nhà thông qua các tiêu chuẩn, vận động quy tắc và cam kết thúc đẩy các sáng kiến ​​dẫn đến cải tiến liên tục phần cứng của nhà xây dựng', 'Đại diện cho các nhà sản xuất phần cứng cho ngành xây dựng và thương mại, BHMA là tổ chức duy nhất của Hoa Kỳ được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận để phát triển và duy trì các tiêu chuẩn hiệu suất cho phần cứng kiến ​​trúc.', NULL, NULL, NULL, 'publisher/avatar/APY3I7B6TAY20Y6LA1AN.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4339, 'BICSI - BICSI', 'BICSI - BICSI', 'A Telecommunications AssociationBICSI is the worldwide preeminent source of information, education and knowledge assessment for the constantly evolving information and communications technology (ICT) community. BICSI serves over 23,000 ICT professionals within the design, integration and installation of wired and wireless infrastructure that empower all facets of today?s and tomorrow?s voice, data, and automation networks.\nBICSI is a professional association supporting the advancement of the information and communications technology (ICT) profession and currently serves more than 26,000 members and credential holders. BICSI is the preeminent resource for the Connected World. Headquartered in Tampa, Florida, USA, BICSI membership spans nearly 100 countries.\n  We provide:\n• Education and Training\n• Conferences and Events\n• Credentials and Certification Programs\n• Standards and Best Practices\n• Reference Manuals\n• Community and Membership\n  What is ICT?\n• Voice/Data/Audio/Video Technologies\n• Electronic Safety & Security\n• Project Management (Telecommunications)\n• Design, Integration & Installation of Telecommunications Distributions\n• All Fiber- and Copper-Based Distribution Systems and Infrastructure\n• Commercial Transportation of Information and Data\n• Wireless Networks\n• Data Center Design\n• Outside Plant Cabling\nBICSI Vision Statement\nBICSI will be the preeminent ICT resource for the Connected World.\nBICSI Mission Statement\nAdvancing the information and communications technology (ICT) profession.\nBICSI Core Values\nIntegrity is defined as the quality of being honest and having strong moral principles and moral uprightness. Integrity defines who we are as a professional association. Some of the moral principles include traits such as courage, honesty, responsibility, accountability, openness, self-respect, and humility. Integrity is also defined as the state of being whole and undivided. BICSI staff, volunteers, members, credential holders, affiliates, and all other stakeholders must strive to do the right thing for the organization, even when no one is looking. Integrity is first because it is critical to BICSI’s success, “… just as strong beams are critical to a house. If the beams are not whole, sound, or complete, if rotten is mixed with good, if termites have eaten the insides, then individual beams will break under stress; beams will fail in their relationship to other beams; nails will pull out and the house will fall.”1\nService to the profession is important. However, BICSI takes it one step further by encouraging service before or above self because it reminds us that we are all part of something bigger than ourselves, and that is the BICSI mission. It defines what we do as a professional association. BICSI staff, volunteers, members, credential holders, affiliates, and all other stakeholders demonstrate the following attributes, among others:\n• Stewardship: We plan and manage the resources entrusted to us with great care and responsibility.\n• Self-discipline: We adhere to policies and procedures such as the BICSI Code of Ethics/Professional Obligations.\n• Self-control: We do not behave in a way that would discredit ourselves, our association, or the ICT profession.\n• Loyalty: We are faithful to our BICSI commitments and voluntary obligations.\n• Inclusion: We all help create an environment free of fear, discrimination, harassment, intimidation, or unfair treatment.\n\nExcellence defines how BICSI strives to do everything it does, from beginning to end and everywhere in between. BICSI staff, volunteers, members, credential holders, affiliates, and all other stakeholders all have a role in ensuring BICSI provides the highest quality training and education, maintains highly credible credentialing programs, provides highly valued membership programs that meet member needs, and provides responsive customer care that exceeds service expectations. No matter what role we have, we are all responsible for doing our personal best and providing a good example to others.2\n\nBICSI will make integrity a daily practice through service above self, underpinned by excellence in everything we do to advance the information and communications technology (ICT) profession.', 'Hiệp hội Viễn thông BICSI là nguồn thông tin, giáo dục và đánh giá kiến ​​thức hàng đầu thế giới dành cho cộng đồng công nghệ thông tin và truyền thông (ICT) không ngừng phát triển. BICSI phục vụ hơn 23.000 chuyên gia ICT trong lĩnh vực thiết kế, tích hợp và lắp đặt cơ sở hạ tầng có dây và không dây hỗ trợ mọi khía cạnh của mạng thoại, dữ liệu và tự động hóa ngày nay và tương lai.\nBICSI là hiệp hội chuyên nghiệp hỗ trợ sự tiến bộ của nghề công nghệ thông tin và truyền thông (ICT) và hiện đang phục vụ hơn 26.000 thành viên và người có chứng chỉ. BICSI là nguồn thông tin hàng đầu cho Thế giới kết nối. Có trụ sở chính tại Tampa, Florida, Hoa Kỳ, tư cách thành viên của BICSI trải dài gần 100 quốc gia.\nChúng tôi cung cấp:\n• Giáo dục và Đào tạo\n• Hội nghị và Sự kiện\n• Chương trình Chứng chỉ và Chứng nhận\n• Tiêu chuẩn và Thực hành Tốt nhất\n• Sổ tay Tham khảo\n• Cộng đồng và Thành viên\nICT là gì?\n• Công nghệ thoại/dữ liệu/âm thanh/video\n• An toàn và bảo mật điện tử\n• Quản lý dự án (Viễn thông)\n• Thiết kế, tích hợp và lắp đặt hệ thống phân phối viễn thông\n• Tất cả các hệ thống phân phối và cơ sở hạ tầng dựa trên cáp quang và đồng\n• Vận chuyển thông tin và dữ liệu thương mại\n• Mạng không dây\n• Thiết kế trung tâm dữ liệu\n• Cáp bên ngoài nhà máy\nTuyên bố tầm nhìn của BICSI\nBICSI sẽ là nguồn tài nguyên ICT hàng đầu cho Thế giới kết nối.\nTuyên bố sứ mệnh của BICSI\nThúc đẩy nghề công nghệ thông tin và truyền thông (ICT).\nCác giá trị cốt lõi của BICSI\nChính trực được định nghĩa là phẩm chất trung thực, có nguyên tắc đạo đức mạnh mẽ và sự ngay thẳng về mặt đạo đức. Chính trực định nghĩa chúng tôi là một hiệp hội chuyên nghiệp. Một số nguyên tắc đạo đức bao gồm các đặc điểm như lòng dũng cảm, sự trung thực, trách nhiệm, sự giải trình, sự cởi mở, lòng tự trọng và sự khiêm tốn. Chính trực cũng được định nghĩa là trạng thái toàn vẹn và không chia cắt. Nhân viên, tình nguyện viên, thành viên, người giữ chứng chỉ, chi nhánh và tất cả các bên liên quan khác của BICSI phải nỗ lực làm điều đúng đắn cho tổ chức, ngay cả khi không có ai nhìn thấy. Tính chính trực là trên hết vì nó rất quan trọng đối với thành công của BICSI, “… cũng giống như những thanh dầm chắc chắn rất quan trọng đối với một ngôi nhà. Nếu những thanh dầm không nguyên vẹn, chắc chắn hoặc hoàn chỉnh, nếu mục nát lẫn lộn với tốt, nếu mối mọt đã ăn hết phần bên trong, thì từng thanh dầm sẽ gãy khi chịu lực; các thanh dầm sẽ không còn liên quan đến các thanh dầm khác; đinh sẽ bật ra và ngôi nhà sẽ đổ sập.”1\nPhục vụ cho nghề là điều quan trọng. Tuy nhiên, BICSI còn tiến xa hơn nữa bằng cách khuyến khích phục vụ trước hoặc trên bản thân vì điều đó nhắc nhở chúng ta rằng tất cả chúng ta đều là một phần của một điều gì đó lớn lao hơn chính bản thân mình, và đó chính là sứ mệnh của BICSI. Sứ mệnh này định nghĩa những gì chúng tôi làm với tư cách là một hiệp hội chuyên nghiệp. Nhân viên, tình nguyện viên, thành viên, người giữ chứng chỉ, chi nhánh và tất cả các bên liên quan khác của BICSI thể hiện các thuộc tính sau đây, trong số những thuộc tính khác:\n• Quản lý: Chúng tôi lập kế hoạch và quản lý các nguồn lực được giao phó với sự cẩn thận và trách nhiệm cao.\n\n• Tự kỷ luật: Chúng tôi tuân thủ các chính sách và quy trình như Bộ quy tắc đạo đức/Nghĩa vụ nghề nghiệp của BICSI.\n• Tự chủ: Chúng tôi không hành xử theo cách làm mất uy tín của bản thân, hiệp hội hoặc nghề ICT.\n• Lòng trung thành: Chúng tôi trung thành với các cam kết và nghĩa vụ tự nguyện của BICSI.\n• Hòa nhập: Tất cả chúng tôi đều chung tay tạo ra một môi trường không có nỗi sợ hãi, phân biệt đối xử, quấy rối, đe dọa hoặc đối xử bất công.\n\nSự xuất sắc định nghĩa cách BICSI phấn đấu thực hiện mọi việc mình làm, từ đầu đến cuối và mọi nơi ở giữa. Nhân viên, tình nguyện viên, thành viên, người nắm giữ chứng chỉ, chi nhánh và tất cả các bên liên quan khác của BICSI đều có vai trò đảm bảo BICSI cung cấp chương trình đào tạo và giáo dục chất lượng cao nhất, duy trì các chương trình cấp chứng chỉ có uy tín cao, cung cấp các chương trình thành viên có giá trị cao đáp ứng nhu cầu của thành viên và cung cấp dịch vụ chăm sóc khách hàng đáp ứng vượt quá mong đợi về dịch vụ. Bất kể chúng ta có vai trò gì, tất cả chúng ta đều có trách nhiệm làm hết sức mình và làm gương cho người khác.2\n\nBICSI sẽ biến tính chính trực thành một hoạt động hàng ngày thông qua việc phục vụ trên cả bản thân, được củng cố bằng sự xuất sắc trong mọi việc chúng ta làm để thúc đẩy nghề công nghệ thông tin và truyền thông (ICT).', 'Hiệp hội Viễn thông BICSI là nguồn thông tin, giáo dục và đánh giá kiến ​​thức hàng đầu thế giới dành cho cộng đồng công nghệ thông tin và truyền thông (ICT) không ngừng phát triển. BICSI phục vụ hơn 23.000 chuyên gia ICT trong lĩnh vực thiết kế, tích hợp và lắp đặt cơ sở hạ tầng có dây và không dây hỗ trợ mọi khía cạnh của mạng thoại, dữ liệu và tự động hóa ngày nay và tương lai', NULL, NULL, NULL, 'publisher/avatar/N1DG5VQ789AEU12AJ0DG.jpg', 0),
(4340, 'BIFMA - Business and Institutional Furniture Manufacturers Association', 'BIFMA - Business and Institutional Furniture Manufacturers Association', 'BIFMA is the trade association for business and institutional furniture manufacturers. Since 1973, BIFMA has been the voice of the commercial furniture industry.\nBIFMA is the not‐for-profit trade association for business and institutional furniture manufacturers. Since 1973, BIFMA has been the voice of the commercial furniture industry.\nOur industry’s service to our customers – providing healthy, comfortable, and productive spaces – rests on an infrastructure of engineering and materials standards. These standards, founded on centuries of craft and enhanced by ever-advancing science, embody the best of our knowledge on safety, ergonomics, and sustainability.\nBIFMA sponsors the development and refinement of standards, educates on their importance and application, and translates their necessary complexity into more easily understood and implemented formats. We promote sustainability throughout the life cycle of furniture. We offer statistical and educational resources to our members and the public and reach out to regulators, consumers, and international partners to foster value and innovation.\nAs a user, you may take the comfort, safety, and durability of the furniture for granted in your places of work, learning, and healing. In large part, this confidence is because of the voluntary standards that have been adopted by the commercial furniture industry. Chairs that support securely, casters that roll smoothly year after year, drawers that retain their shape even when jam-packed–these are the expectations of safe and functional business and institutional environments. BIFMA sponsors the development and ongoing maintenance of the standards that form the basis of this user confidence.', 'BIFMA là hiệp hội thương mại dành cho các nhà sản xuất đồ nội thất doanh nghiệp và tổ chức. Từ năm 1973, BIFMA đã là tiếng nói của ngành công nghiệp đồ nội thất thương mại. BIFMA là hiệp hội thương mại phi lợi nhuận dành cho các nhà sản xuất đồ nội thất doanh nghiệp và tổ chức. Từ năm 1973, BIFMA đã là tiếng nói của ngành công nghiệp đồ nội thất thương mại.\nDịch vụ của ngành chúng tôi dành cho khách hàng – cung cấp không gian lành mạnh, thoải mái và hiệu quả – dựa trên cơ sở hạ tầng của các tiêu chuẩn về kỹ thuật và vật liệu. Các tiêu chuẩn này, được xây dựng dựa trên nhiều thế kỷ thủ công và được cải tiến bởi khoa học không ngừng phát triển, thể hiện kiến ​​thức tốt nhất của chúng tôi về an toàn, công thái học và tính bền vững.\nBIFMA tài trợ cho việc phát triển và tinh chỉnh các tiêu chuẩn, giáo dục về tầm quan trọng và ứng dụng của chúng, đồng thời chuyển đổi sự phức tạp cần thiết của chúng thành các định dạng dễ hiểu và dễ triển khai hơn. Chúng tôi thúc đẩy tính bền vững trong suốt vòng đời của đồ nội thất. Chúng tôi cung cấp các nguồn tài nguyên thống kê và giáo dục cho các thành viên và công chúng của mình và tiếp cận các cơ quan quản lý, người tiêu dùng và các đối tác quốc tế để thúc đẩy giá trị và sự đổi mới.\nLà người dùng, bạn có thể coi sự thoải mái, an toàn và độ bền của đồ nội thất là điều hiển nhiên tại nơi làm việc, học tập và chữa bệnh của mình. Phần lớn, sự tự tin này là do các tiêu chuẩn tự nguyện đã được ngành công nghiệp đồ nội thất thương mại áp dụng. Ghế hỗ trợ an toàn, bánh xe lăn trơn tru qua từng năm, ngăn kéo giữ nguyên hình dạng ngay cả khi bị nhồi nhét - đây là những kỳ vọng về môi trường kinh doanh và tổ chức an toàn và chức năng. BIFMA tài trợ cho việc phát triển và duy trì liên tục các tiêu chuẩn tạo thành cơ sở cho sự tự tin này của người dùng.', 'BIFMA là hiệp hội thương mại dành cho các nhà sản xuất đồ nội thất doanh nghiệp và tổ chức. Từ năm 1973, BIFMA đã là tiếng nói của ngành công nghiệp đồ nội thất thương mại. BIFMA là hiệp hội thương mại phi lợi nhuận dành cho các nhà sản xuất đồ nội thất doanh nghiệp và tổ chức. Từ năm 1973, BIFMA đã là tiếng nói của ngành công nghiệp đồ nội thất thương mại.', NULL, NULL, NULL, 'publisher/avatar/G6SB8J5O6MNAMYVAGG6D.png', 0),
(4341, 'BioWorld - Thomson Reuters BioWorld', 'BioWorld - Thomson Reuters BioWorld', 'BioWorld delivers actionable intelligence on the most innovative drug development science that drives the business, which funds the means to heal disease. With writers and editors stationed around the globe, BioWorld reports the breaking news - and provides key perspective - on hundreds of medicines in development, the companies behind those therapeutic candidates, the business development transactions that evolve the market, and the regulatory hurdles that both challenge and guard the process.\nBioWorld’s suite of news services delivers actionable intelligence on the most innovative therapeutics and medical technologies in development. With writers and editors stationed around the globe, BioWorld reports the breaking news – and provides key perspective on hundreds of therapeutics and devices in development, the companies behind those candidates, the business development transactions that evolve the markets, and the regulatory hurdles that both challenge and guard the processes.\nBioWorld has a long tradition of excellence in journalism. Collectively, the news services have been honored with 70 awards from the Specialized Information Publishing Association and Apex dating back to 1998.\nNews about BioWorld\nBioWorld remains committed to the core principles of ethical journalism, producing fact-based news and analysis via direct interviews with sources and intensive background research bolstered with invaluable data from BioWorld’s vast archives and other trusted data sources. We are constantly working to enhance our news products. Read about BioWorld’s latest efforts.\nBioWorld was launched as a magazine in 1990 by David Bunnell and Cynthia Robbins-Roth (a former scientist from Genentech). Bunnell was a pioneer of the personal computing industry who founded some of the most successful computer magazines, including PC Magazine, PC World and Macworld. He had the idea that biotechnology would become a big thing, and he was right! Early on, BioWorld was converted to a faxed publication, called BioWorld Today. Shortly after, BioWorld Financial Watch (a weekly look at financial trends) was launched along with a nascent data service that tracked the biopharmaceutical industry. BioWorld’s former owner, Thompson Media Group, acquired BioWorld in 1994. BioWorld dropped the faxed version and converted to digital delivery. BioWorld was acquired by Thomson Reuters in 2013. In 2016 Thomson Reuters spun off the Intellectual Property and Science division, which emerged as an independent company now known as Clarivate.', 'BioWorld cung cấp thông tin tình báo hữu ích về khoa học phát triển thuốc tiên tiến nhất thúc đẩy doanh nghiệp, nguồn tài trợ cho các phương tiện chữa bệnh. Với các biên tập viên và cây bút trên khắp thế giới, BioWorld đưa tin tức nóng hổi - và cung cấp góc nhìn chính - về hàng trăm loại thuốc đang được phát triển, các công ty đứng sau các ứng viên điều trị đó, các giao dịch phát triển kinh doanh thúc đẩy thị trường và các rào cản pháp lý vừa thách thức vừa bảo vệ quy trình.\nBộ dịch vụ tin tức của BioWorld cung cấp thông tin tình báo hữu ích về các liệu pháp và công nghệ y tế tiên tiến nhất đang được phát triển. Với các biên tập viên và cây bút trên khắp thế giới, BioWorld đưa tin tức nóng hổi - và cung cấp góc nhìn chính về hàng trăm liệu pháp và thiết bị đang được phát triển, các công ty đứng sau các ứng viên đó, các giao dịch phát triển kinh doanh thúc đẩy thị trường và các rào cản pháp lý vừa thách thức vừa bảo vệ quy trình.\nBioWorld có truyền thống lâu đời về sự xuất sắc trong báo chí. Tổng cộng, các dịch vụ tin tức đã được vinh danh với 70 giải thưởng từ Hiệp hội xuất bản thông tin chuyên ngành và Apex có từ năm 1998.\nTin tức về BioWorld\nBioWorld vẫn cam kết với các nguyên tắc cốt lõi của báo chí đạo đức, tạo ra tin tức và phân tích dựa trên sự kiện thông qua các cuộc phỏng vấn trực tiếp với các nguồn tin và nghiên cứu bối cảnh chuyên sâu được hỗ trợ bằng dữ liệu vô giá từ kho lưu trữ khổng lồ của BioWorld và các nguồn dữ liệu đáng tin cậy khác. Chúng tôi không ngừng nỗ lực để cải thiện các sản phẩm tin tức của mình. Đọc về những nỗ lực mới nhất của BioWorld.\nBioWorld được David Bunnell và Cynthia Robbins-Roth (một cựu nhà khoa học của Genentech) ra mắt dưới dạng tạp chí vào năm 1990. Bunnell là người tiên phong trong ngành máy tính cá nhân, người đã sáng lập một số tạp chí máy tính thành công nhất, bao gồm PC Magazine, PC World và Macworld. Ông đã có ý tưởng rằng công nghệ sinh học sẽ trở thành một thứ gì đó lớn lao, và ông đã đúng! Ngay từ đầu, BioWorld đã được chuyển đổi thành ấn phẩm fax, có tên là BioWorld Today. Ngay sau đó, BioWorld Financial Watch (bản tin hàng tuần về xu hướng tài chính) đã được ra mắt cùng với một dịch vụ dữ liệu mới ra đời theo dõi ngành dược phẩm sinh học. Chủ sở hữu trước đây của BioWorld, Thompson Media Group, đã mua lại BioWorld vào năm 1994. BioWorld đã bỏ phiên bản fax và chuyển sang giao hàng kỹ thuật số. BioWorld đã được Thomson Reuters mua lại vào năm 2013. Năm 2016, Thomson Reuters đã tách bộ phận Sở hữu trí tuệ và Khoa học, trở thành một công ty độc lập hiện được gọi là Clarivate.', 'BioWorld cung cấp thông tin tình báo hữu ích về khoa học phát triển thuốc tiên tiến nhất thúc đẩy doanh nghiệp, nguồn tài trợ cho các phương tiện chữa bệnh. Với các biên tập viên và cây bút trên khắp thế giới, BioWorld đưa tin tức nóng hổi - và cung cấp góc nhìn chính - về hàng trăm loại thuốc đang được phát triển, các công ty đứng sau các ứng viên điều trị đó, các giao dịch phát triển kinh doanh thúc đẩy thị trường và các rào cản pháp lý vừa thách thức vừa bảo vệ quy trình.', NULL, NULL, NULL, 'publisher/avatar/V1ZZYR6S5VGC6J9DSAGU.png', 0),
(4342, 'BMI - Metallic Materials Properties Development and Standardization', 'BMI - Metallic Materials Properties Development and Standardization', 'MMPDS is recognized throughout the world, and it represents the primary source of statistically based design allowables for metallic materials and fastened joints used in the design of aerospace vehicle structures in the United States.\nThe MMPDS (Metallic Materials Properties Development Standardization) Handbook is recognized throughout the world, and it represents the primary source of statistically based design allowables for metallic materials and fastened joints used in the design of aerospace vehicle structures in the United States (U.S.).\nThe MMPDS Handbook has evolved and expanded tremendously over the years. The Handbook was first published in 1937 as the Army-Navy-Commerce Handbook 5 (ANC-5). The United States Air Force (USAF) took over the primary responsibility of continuing development of the Handbook in 1954 and, subsequently, changed its name to MIL-HDBK-5 in 1956. Since 1956, the Handbook has been revised and re-issued (in whole or in part) over 50 times – to incorporate new methodologies, add new material properties, and update existing design properties.\nHistorical files were searched and the minutes of previous meetings and correspondence were reviewed in an effort to reconstruct previous events which led to the handbook as it is today. However, early records were not diligently maintained, resulting in meager information in the years prior to 1948. Fortunately, the files did contain most of the revisions of the MIL-HDBK-5 and its predecessor. These revisions were most helpful in arranging the sequence of events. Although the history, which follows, may not be complete, it is believed that this description conveys a fairly accurate impression of the history of this Handbook. It is hoped that this history will prove interesting, especially for the young participants who have just recently become involved with the MMPDS program.\nThe earliest predecessor to MMPDS was the ANC-5 Bulletin. This document was prepared by the ANC-5 Committee of the Army-Navy-Commerce Committee on Aircraft Requirements and issued by the latter. So far as could be determined, the initial issue of this Bulletin occurred in 1937. The 1938 version contained design information for columns, thin-walled sections, mechanical property design values for wood, steel alloys, aluminum alloys, as well as magnesium alloys, and design allowables for joints, fittings, and parts. Revisions of ANC-5 were published in October 1940, December 1942, and October 1943. After the 1943 revision, the activity of the ANC-5 Committee was discontinued because of World War II.\nApparently the next meeting of the ANC-5 Committee occurred on June 5, 1945, at the close of World War II. The function of the Army-Navy- Commerce Committee on Aircraft Design Criteria was amended on March 19, 1946, as follows: “To develop aircraft design criteria governing strength, detailed design, propulsion systems, equipment, flight characteristics, and performance of cargo, transport, and training aircraft and to recommend the adoption of these criteria by the three member branches of the Government”. The ANC-5 Committee attending the meeting on May 2, 1946, consisted of three members (two military and one civilian) from the Army (Air Material Command) and Navy Bureau of Aeronautics), two members from Civil Aeronautics Administration (CAA), and a recorder from the military (USMC).\nThe Chairman was Mr. E. I. Ryder, CAA. Five people from the Aluminum Company of America and Reynolds Metals also attended this meeting. The Chairman stated at this meeting that it would be desirable to have members of the aircraft industry present at the next meeting and to encourage industry participation in future revisions of ANC-5. It is interesting to note that the chapter on wood was deleted from ANC-5 in Amendment No. 2, August 8, 1946. Mr. William T. Shuler, CAA, succeeded Mr. Ryder as Chairman in 1947. People from various government agencies, the aircraft industry, material suppliers, and fastener suppliers attended the ANC-5 Committee Meeting held on October 7, 1947, swelling attendance to 37. The ANC-5 Committee meetings were held alternately in Washington, D.C., and at Wright-Patterson Air Force Base (Dayton), Ohio. Generally, these meetings were scheduled in the Spring and Fall of the year. On September 21, 1948, the supervisory body for the ANC-5 Committee was changed to the Munitions Board Aircraft Committee. However, the function, operation, and membership of the ANC-5 Committee remained essentially unchanged. In September 1953, Mr. J. E. Dougherty, Jr., CAA, became Chairman. The Munitions Board was abolished in 1954, but the ANC-5 Committee continued to function as usual.\nIn 1954, Battelle Memorial Institute (Battelle) was awarded a contract by the Materials Laboratory, Wright-Patterson Air Force Base, Ohio, to review the field of material-property-design criteria for metals used in aircraft and missiles, and to bring up-to-date a compilation of design information for the design of aircraft and missiles. Over the next several years, Battelle published seven Wright Air Development Center technical reports which contained design allowables and other pertinent information for incorporation into ANC-5. Since this initial contract, Battelle has continuously served as the Air Force contractor and later the FAA contractor to maintain and update ANC-5, MIL-HDBK-5, and MMPDS.\nIn August 1956, the Air Force was assigned the responsibility for maintaining ANC-5. Mr. M. J. Crane, Aeronautical Standards Group (Navy and Air Force), was named Secretariat for the ANC-5 Committee on February 13, 1957.\nIn 1958 it was decided to publish the next revision as a military handbook. Battelle prepared the initial draft. Military Standardization Handbook MIL-HDBK-5, which superseded ANC-5, was published in March 1959. This revision incorporated the initial design information for titanium alloys.\nSince the abolition of the Munitions Board in 1954, the ANC-5 and MIL-HDBK-5 Committees had been charterless. In 1959 an effort was initiated to establish a Joint Committee of the Department of Defense and the Federal Aviation Agency on Federal Aircraft Design Criteria. This Joint Committee would have been the governing body for the MIL-HDBK-5 Committee. However, the establishment of this Joint Committee was not promulgated. At the May 1959 MIL-HDBK-5 Committee Meeting, Mr. J. E. Dougherty, Jr., resigned and Mr. E. S. Newberger, FAA, was appointed Chairman. Mr. Newberger resigned in 1961 and Mr. D. A. Shinn, Aeronautical Systems Division (Air Force), became Acting Chairman for the November 1961 meeting.\nMr. Dean Lauver, FAA, assumed Chairmanship and presided at the MIL-HDBK-5 Committee Meeting held in May 1962. Mr. Lauver’s Chairmanship was short lived and Mr. D. A. Shinn, Air Force, became the new Chairman. He presided at the meeting held in November 1962. Battelle began preparing the revisions and change notices to MIL-HDBK-5 in 1964.\nMessrs. Donald P. Moon and Walter S. Hyler prepared a report, AFML-TR-66-386, “MIL-HDBK-5 Guidelines for the Presentation of Data”, dated February 1967. This report specified the analytical procedures and methods for presenting data for MIL-HDBK-5. Prior to that time, many different procedures had been used. Certain procedures had been adopted either formally or informally. In some instances, the techniques had been fairly well documented but were located variously in attachments to the minutes of previous MIL-HDBK-5 meetings, in statistical text and workbooks, in company reports, or in other miscellaneous publications. For this guideline report, procedures were written delineating these past practices. When necessary, analytical techniques were developed. These guidelines represented an important milestone in the utilization of standardized procedures for the analysis and presentation of data for MIL-HDBK-5. This report contained all of the required information for the analysis and presentation of data for MIL-HDBK-5 in one convenient source. All of the procedures contained in these guidelines had been previously approved by the MIL-HDBK-5 Committee. These guidelines were later incorporated into MIL-HDBK-5B, September 1971, as Chapter 9.\nBeginning with the 39th MIL-HDBK-5 Meeting, April 1970, Battelle prepared and distributed the agenda and minutes of the MIL-HDBK-5 meetings. After about 10 years of consideration and discussion, guidelines for the analysis and presentation of fracture toughness data were approved at the 39th Meeting. These guidelines were incorporated into MIL-HDBK-5B, September, 1971.\nMr. Paul E. Ruff took over the Battelle lead of the MIL-HDBK-5 coordination activities from Mr. Hyler in the Fall of 1971.\nAt the 46th MIL-HDBK-5 Meeting, held in October 1973, Mr. D. A. Shinn announced that he was retiring from the Air Force and that he was stepping down as Chairman. Mr. C. L. Harmsworth, AFML (Air Force), succeeded Mr. Shinn as Chairman and presided at the 46th Meeting.\nBattelle prepared a “soft” metric conversion of the first seven chapters of MIL-HDBK-5. This “soft” metric version of MIL-HDBK-5 was published in an Air Force technical report, AFWAL-TR-80-4110, “Metrication of MIL-HDBK-5C”, dated August 1980. Although this document was recognized to be limited in its usefulness, the primary benefit of this effort was the revelation of problems associated with the conversion to metric design values and the presentation of metric design data.\nBeginning with MIL-HDBK-5C, Change Notice 3, dated June 1981, the revisions of MIL-HDBK-5 were typeset at Battelle, rather than by the Naval Publications and Forms Center. This change was made to shorten the processing time required to publish MIL-HDBK-5 revisions. Design information for the first product developed and marketed by a foreign supplier was incorporated into MIL-HDBK-5D via Change Notice 1, dated January 1, 1984. Design allowables for 7010-T73651 and -T7651 plate were added to the Handbook. These products were produced by Alcan Plate Limited, Birmingham, England. The material was fabricated and tested using metric units of measure. The metric mechanical property data were converted to English units for analysis and inclusion in MIL-HDBK-5.\nMr. Richard C. Rice took over the Battelle lead of the MIL-HDBK-5 coordination activities from Mr. Ruff in the Spring of 1993.\nAt the 87th MIL-HDBK-5 Meeting, held in Las Vegas, Nevada, held in April 1994, Mr. Neal Ontko, AFRL, (Air Force), succeeded Mr. C. L. Harmsworth as Chairman. Mr. Steven Thompson, AFRL, also committed to support Mr. Ontko in his new role as Chairman.\nThe need for a change in government oversight of the Handbook first became evident in 1997, when the Air Force reported that their annual funding for MIL-HDBK-5 technical coordination had been dramatically reduced. To help offset declining government support for Handbook coordination, Battelle formed, in 1997, an Industrial Steering Group (ISG) paying membership, consisting of aircraft and aerospace metallic material suppliers and users. The original founding member companies were; Century Aluminum, Alcoa Aluminum, Boeing, Lockheed Martin, Northrop Grumman, and Textron. All members participated at the single level offered of $30,000 per year. The ISG membership has steadily grown to represent 31 companies in 2014 from 8 countries, participating in various membership levels. Since its inception, the ISG has held meetings prior to every Handbook coordination meeting and has coordinated its activities closely with the Government Steering Group (GSG).\nFurther changes in the government oversight of MIL-HDBK-5 became official in 2003, when the Federal Aviation Administration took over the government oversight role and changed the name of the document to the Metallic Materials Properties Development and Standardization (MMPDS) Handbook. The FAA, led by John Bakuckas (FAA Technical Center) subsequently set up a 5 year contract with Battelle to continue technical coordination of the MMPDS Handbook and has renewed the contract in 5 year increments through 2018.\nMMPDS-01 and MIL-HDBK-5J were produced as identical documents for the transition of MIL-HDBK-5 to MMPDS. MIL- HDBK-5J was classified as noncurrent in the Spring of 2004.\nWhen the FAA took over government oversight of the Handbook, they asked Battelle to develop an additional source of revenue for maintaining the Handbook through its commercialization. As a result, the Handbook was no longer available as a free copy beginning with MMPDS-02.\nSince that time the MMPDS Handbook has been sold as a paper and electronic document, as well as in the form of a database through various licensees.\nIn November of 2011, Richard C. Rice stepped down from the program management position at Battelle to retire in December and was succeeded by Jana L Rubadue as Battelle program manager. Mr. Rice continues to work on MMPDS in a part-time capacity.', 'Năm 1954, Viện Tưởng niệm Battelle (Battelle) đã được Phòng thí nghiệm Vật liệu, Căn cứ Không quân Wright-Patterson, Ohio trao hợp đồng để xem xét lĩnh vực tiêu chí thiết kế vật liệu-tính chất cho kim loại được sử dụng trong máy bay và tên lửa, và cập nhật biên soạn thông tin thiết kế cho thiết kế máy bay và tên lửa. Trong nhiều năm tiếp theo, Battelle đã công bố bảy báo cáo kỹ thuật của Trung tâm Phát triển Không quân Wright có chứa các thông tin thiết kế cho phép và các thông tin liên quan khác để đưa vào ANC-5. Kể từ hợp đồng ban đầu này, Battelle liên tục làm nhà thầu của Không quân và sau đó là nhà thầu của FAA để bảo trì và cập nhật ANC-5, MIL-HDBK-5 và MMPDS.\nVào tháng 8 năm 1956, Không quân được giao trách nhiệm bảo trì ANC-5. Ông M. J. Crane, Nhóm Tiêu chuẩn Hàng không (Hải quân và Không quân), được bổ nhiệm làm Ban thư ký của Ủy ban ANC-5 vào ngày 13 tháng 2 năm 1957.\nNăm 1958, người ta quyết định xuất bản bản sửa đổi tiếp theo dưới dạng sổ tay quân sự. Battelle đã chuẩn bị bản thảo đầu tiên. Sổ tay Tiêu chuẩn hóa Quân sự MIL-HDBK-5, thay thế ANC-5, được xuất bản vào tháng 3 năm 1959. Bản sửa đổi này kết hợp thông tin thiết kế ban đầu cho hợp kim titan.\nKể từ khi Ủy ban Quân nhu bị bãi bỏ vào năm 1954, các Ủy ban ANC-5 và MIL-HDBK-5 đã không có điều lệ. Năm 1959, một nỗ lực đã được khởi xướng để thành lập Ủy ban Liên hợp của Bộ Quốc phòng và Cơ quan Hàng không Liên bang về Tiêu chí Thiết kế Máy bay Liên bang. Ủy ban Liên hợp này sẽ là cơ quan quản lý của Ủy ban MIL-HDBK-5. Tuy nhiên, việc thành lập Ủy ban Liên hợp này đã không được công bố. Tại cuộc họp Ủy ban MIL-HDBK-5 tháng 5 năm 1959, ông J. E. Dougherty, Jr., đã từ chức và ông E. S. Newberger, FAA, được bổ nhiệm làm Chủ tịch. Ông Newberger đã từ chức vào năm 1961 và ông D. A. Shinn, Bộ phận Hệ thống Hàng không (Không quân), đã trở thành Quyền Chủ tịch cho cuộc họp tháng 11 năm 1961.\nÔng Dean Lauver, FAA, đã đảm nhận Chức vụ Chủ tịch và chủ trì Cuộc họp Ủy ban MIL-HDBK-5 được tổ chức vào tháng 5 năm 1962. Chức vụ Chủ tịch của ông Lauver không kéo dài lâu và ông D. A. Shinn, Không quân, đã trở thành Chủ tịch mới. Ông chủ trì cuộc họp được tổ chức vào tháng 11 năm 1962. Battelle bắt đầu chuẩn bị các thông báo sửa đổi và thay đổi đối với MIL-HDBK-5 vào năm 1964.\nCác ông Donald P. Moon và Walter S. Hyler đã chuẩn bị một báo cáo, AFML-TR-66-386, “Hướng dẫn MIL-HDBK-5 về Trình bày Dữ liệu”, có niên đại là tháng 2 năm 1967. Báo cáo này nêu rõ các quy trình và phương pháp phân tích để trình bày dữ liệu cho MIL-HDBK-5. Trước thời điểm đó, nhiều quy trình khác nhau đã được sử dụng. Một số quy trình nhất định đã được áp dụng chính thức hoặc không chính thức. Trong một số trường hợp, các kỹ thuật đã được ghi chép khá đầy đủ nhưng lại nằm ở nhiều nơi khác nhau trong các tệp đính kèm biên bản các cuộc họp MIL-HDBK-5 trước đó, trong văn bản thống kê và sổ làm việc, trong báo cáo của công ty hoặc trong các ấn phẩm khác nhau. Đối với báo cáo hướng dẫn này, các quy trình đã được viết ra để mô tả các hoạt động trong quá khứ này. Khi cần thiết, các kỹ thuật phân tích đã được phát triển. Các hướng dẫn này đại diện cho một cột mốc quan trọng trong việc sử dụng các quy trình chuẩn hóa để phân tích và trình bày dữ liệu cho MIL-HDBK-5. Báo cáo này chứa tất cả các thông tin cần thiết để phân tích và trình bày dữ liệu cho MIL-HDBK-5 trong một nguồn thuận tiện. Tất cả các quy trình có trong các hướng dẫn này đã được Ủy ban MIL-HDBK-5 chấp thuận trước đó. Các hướng dẫn này sau đó được đưa vào MIL-HDBK-5B, tháng 9 năm 1971, dưới dạng Chương 9.\nMMPDS được công nhận trên toàn thế giới và là nguồn chính cung cấp các giá trị thiết kế dựa trên thống kê cho các vật liệu kim loại và mối nối cố định được sử dụng trong thiết kế kết cấu phương tiện hàng không vũ trụ tại Hoa Kỳ.\nSổ tay MMPDS (Chuẩn hóa phát triển tính chất vật liệu kim loại) được công nhận trên toàn thế giới và là nguồn chính cung cấp các giá trị thiết kế dựa trên thống kê cho các vật liệu kim loại và mối nối cố định được sử dụng trong thiết kế kết cấu phương tiện hàng không vũ trụ tại Hoa Kỳ (U.S.).\nSổ tay MMPDS đã phát triển và mở rộng đáng kể trong những năm qua. Sổ tay này được xuất bản lần đầu tiên vào năm 1937 với tên gọi Sổ tay Quân đội-Hải quân-Thương mại 5 (ANC-5). Không quân Hoa Kỳ (USAF) đã tiếp quản trách nhiệm chính trong việc tiếp tục phát triển Sổ tay vào năm 1954 và sau đó đổi tên thành MIL-HDBK-5 vào năm 1956. Kể từ năm 1956, Sổ tay đã được sửa đổi và tái bản (toàn bộ hoặc một phần) hơn 50 lần - để kết hợp các phương pháp luận mới, thêm các đặc tính vật liệu mới và cập nhật các đặc tính thiết kế hiện có.\nCác hồ sơ lịch sử đã được tìm kiếm và biên bản các cuộc họp và thư từ trước đó đã được xem xét trong nỗ lực tái tạo các sự kiện trước đó dẫn đến sổ tay như ngày nay. Tuy nhiên, các hồ sơ ban đầu không được lưu giữ cẩn thận, dẫn đến thông tin ít ỏi trong những năm trước năm 1948. May mắn thay, các hồ sơ đã chứa hầu hết các bản sửa đổi của MIL-HDBK-5 và phiên bản tiền nhiệm của nó. Những bản sửa đổi này hữu ích nhất trong việc sắp xếp trình tự các sự kiện. Mặc dù lịch sử sau đây có thể không đầy đủ, nhưng người ta tin rằng mô tả này truyền tải ấn tượng khá chính xác về lịch sử của Sổ tay này. Hy vọng rằng lịch sử này sẽ chứng minh được sự thú vị, đặc biệt là đối với những người tham gia trẻ tuổi mới tham gia chương trình MMPDS.\nTiền thân sớm nhất của MMPDS là Bản tin ANC-5. Tài liệu này được Ủy ban ANC-5 của Ủy ban Thương mại-Hải quân-Quân đội về Yêu cầu Máy bay biên soạn và được ban hành sau này. Theo như có thể xác định, bản tin đầu tiên này được phát hành vào năm 1937. Phiên bản năm 1938 chứa thông tin thiết kế cho các cột, phần có thành mỏng, giá trị thiết kế đặc tính cơ học cho gỗ, hợp kim thép, hợp kim nhôm, cũng như hợp kim magiê và các giá trị thiết kế cho phép đối với các mối nối, phụ kiện và bộ phận. Các bản sửa đổi của ANC-5 đã được công bố vào tháng 10 năm 1940, tháng 12 năm 1942 và tháng 10 năm 1943. Sau bản sửa đổi năm 1943, hoạt động của Ủy ban ANC-5 đã bị ngừng lại vì Thế chiến II.\nRõ ràng là cuộc họp tiếp theo của Ủy ban ANC-5 đã diễn ra vào ngày 5 tháng 6 năm 1945, khi Thế chiến II kết thúc. Chức năng của Ủy ban Tiêu chuẩn Thiết kế Máy bay Lục quân-Hải quân-Thương mại đã được sửa đổi vào ngày 19 tháng 3 năm 1946 như sau: “Phát triển các tiêu chuẩn thiết kế máy bay chi phối sức mạnh, thiết kế chi tiết, hệ thống động cơ, thiết bị, đặc điểm bay và hiệu suất của máy bay chở hàng, vận tải và huấn luyện và khuyến nghị ba nhánh thành viên của Chính phủ áp dụng các tiêu chuẩn này”. Ủy ban ANC-5 tham dự cuộc họp vào ngày 2 tháng 5 năm 1946, bao gồm ba thành viên (hai quân nhân và một dân sự) từ Lục quân (Bộ tư lệnh Vật liệu Không quân) và Cục Hàng không Hải quân), hai thành viên từ Cục Hàng không Dân dụng (CAA) và một người ghi chép từ quân đội (USMC).\nChủ tịch là ông E. I. Ryder, CAA. Năm người từ Công ty Nhôm Hoa Kỳ và Reynolds Metals cũng tham dự cuộc họp này. Chủ tịch tuyên bố tại cuộc họp này rằng sẽ rất mong muốn có sự tham gia của các thành viên trong ngành công nghiệp máy bay tại cuộc họp tiếp theo và khuyến khích ngành công nghiệp tham gia vào các bản sửa đổi trong tương lai của ANC-5. Thật thú vị khi lưu ý rằng chương về gỗ đã bị xóa khỏi ANC-5 trong Tu chính án số 2, ngày 8 tháng 8 năm 1946. Ông William T. Shuler, CAA, đã kế nhiệm ông Ryder làm Chủ tịch vào năm 1947. Những người từ nhiều cơ quan chính phủ, ngành công nghiệp máy bay, nhà cung cấp vật liệu và nhà cung cấp ốc vít đã tham dự Cuộc họp Ủy ban ANC-5 được tổ chức vào ngày 7 tháng 10 năm 1947, làm tăng số người tham dự lên 37. Các cuộc họp của Ủy ban ANC-5 được tổ chức luân phiên tại Washington, D.C. và tại Căn cứ Không quân Wright-Patterson (Dayton), Ohio. Nhìn chung, các cuộc họp này được lên lịch vào mùa xuân và mùa thu trong năm. Vào ngày 21 tháng 9 năm 1948, cơ quan giám sát của Ủy ban ANC-5 đã được đổi thành Ủy ban Máy bay của Ban Đạn dược. Tuy nhiên, chức năng, hoạt động và thành viên của Ủy ban ANC-5 về cơ bản vẫn không thay đổi. Vào tháng 9 năm 1953, ông J. E. Dougherty, Jr., CAA, trở thành Chủ tịch. Ủy ban Quân nhu đã bị bãi bỏ vào năm 1954, nhưng Ủy ban ANC-5 vẫn tiếp tục hoạt động như thường lệ.\nNăm 1954, Viện Tưởng niệm Battelle (Battelle) đã được Phòng thí nghiệm Vật liệu, Căn cứ Không quân Wright-Patterson, Ohio trao hợp đồng để xem xét lĩnh vực tiêu chí thiết kế vật liệu-tính chất cho kim loại được sử dụng trong máy bay và tên lửa, và cập nhật biên soạn thông tin thiết kế cho thiết kế máy bay và tên lửa. Trong nhiều năm tiếp theo, Battelle đã công bố bảy báo cáo kỹ thuật của Trung tâm Phát triển Không quân Wright có chứa các thông tin thiết kế cho phép và các thông tin liên quan khác để đưa vào ANC-5. Kể từ hợp đồng ban đầu này, Battelle liên tục làm nhà thầu của Không quân và sau đó là nhà thầu của FAA để bảo trì và cập nhật ANC-5, MIL-HDBK-5 và MMPDS.\nVào tháng 8 năm 1956, Không quân được giao trách nhiệm bảo trì ANC-5. Ông M. J. Crane, Nhóm Tiêu chuẩn Hàng không (Hải quân và Không quân), được bổ nhiệm làm Ban thư ký của Ủy ban ANC-5 vào ngày 13 tháng 2 năm 1957.\nNăm 1958, người ta quyết định xuất bản bản sửa đổi tiếp theo dưới dạng sổ tay quân sự. Battelle đã chuẩn bị bản thảo đầu tiên. Sổ tay Tiêu chuẩn hóa Quân sự MIL-HDBK-5, thay thế ANC-5, được xuất bản vào tháng 3 năm 1959. Bản sửa đổi này kết hợp thông tin thiết kế ban đầu cho hợp kim titan.\nKể từ khi Ủy ban Quân nhu bị bãi bỏ vào năm 1954, các Ủy ban ANC-5 và MIL-HDBK-5 đã không có điều lệ. Năm 1959, một nỗ lực đã được khởi xướng để thành lập Ủy ban Liên hợp của Bộ Quốc phòng và Cơ quan Hàng không Liên bang về Tiêu chí Thiết kế Máy bay Liên bang. Ủy ban Liên hợp này sẽ là cơ quan quản lý của Ủy ban MIL-HDBK-5. Tuy nhiên, việc thành lập Ủy ban Liên hợp này đã không được công bố. Tại cuộc họp Ủy ban MIL-HDBK-5 tháng 5 năm 1959, ông J. E. Dougherty, Jr., đã từ chức và ông E. S. Newberger, FAA, được bổ nhiệm làm Chủ tịch. Ông Newberger đã từ chức vào năm 1961 và ông D. A. Shinn, Bộ phận Hệ thống Hàng không (Không quân), đã trở thành Quyền Chủ tịch cho cuộc họp tháng 11 năm 1961.\nÔng Dean Lauver, FAA, đã đảm nhận Chức vụ Chủ tịch và chủ trì Cuộc họp Ủy ban MIL-HDBK-5 được tổ chức vào tháng 5 năm 1962. Chức vụ Chủ tịch của ông Lauver không kéo dài lâu và ông D. A. Shinn, Không quân, đã trở thành Chủ tịch mới. Ông chủ trì cuộc họp được tổ chức vào tháng 11 năm 1962. Battelle bắt đầu chuẩn bị các thông báo sửa đổi và thay đổi đối với MIL-HDBK-5 vào năm 1964.\nCác ông Donald P. Moon và Walter S. Hyler đã chuẩn bị một báo cáo, AFML-TR-66-386, “Hướng dẫn MIL-HDBK-5 về Trình bày Dữ liệu”, có niên đại là tháng 2 năm 1967. Báo cáo này nêu rõ các quy trình và phương pháp phân tích để trình bày dữ liệu cho MIL-HDBK-5. Trước thời điểm đó, nhiều quy trình khác nhau đã được sử dụng. Một số quy trình nhất định đã được áp dụng chính thức hoặc không chính thức. Trong một số trường hợp, các kỹ thuật đã được ghi chép khá đầy đủ nhưng lại nằm ở nhiều nơi khác nhau trong các tệp đính kèm biên bản các cuộc họp MIL-HDBK-5 trước đó, trong văn bản thống kê và sổ làm việc, trong báo cáo của công ty hoặc trong các ấn phẩm khác nhau. Đối với báo cáo hướng dẫn này, các quy trình đã được viết ra để mô tả các hoạt động trong quá khứ này. Khi cần thiết, các kỹ thuật phân tích đã được phát triển. Các hướng dẫn này đại diện cho một cột mốc quan trọng trong việc sử dụng các quy trình chuẩn hóa để phân tích và trình bày dữ liệu cho MIL-HDBK-5. Báo cáo này chứa tất cả các thông tin cần thiết để phân tích và trình bày dữ liệu cho MIL-HDBK-5 trong một nguồn thuận tiện. Tất cả các quy trình có trong các hướng dẫn này đã được Ủy ban MIL-HDBK-5 chấp thuận trước đó. Các hướng dẫn này sau đó được đưa vào MIL-HDBK-5B, tháng 9 năm 1971, dưới dạng Chương 9.\nBắt đầu từ Cuộc họp MIL-HDBK-5 lần thứ 39, tháng 4 năm 1970, Battelle đã chuẩn bị và phân phối chương trình nghị sự và biên bản của các cuộc họp MIL-HDBK-5. Sau khoảng 10 năm xem xét và thảo luận, các hướng dẫn về phân tích và trình bày dữ liệu độ bền gãy đã được phê duyệt tại Cuộc họp lần thứ 39. Các hướng dẫn này đã được đưa vào MIL-HDBK-5B, tháng 9 năm 1971.\nÔng Paul E. Ruff đã tiếp quản vị trí lãnh đạo Battelle về các hoạt động phối hợp MIL-HDBK-5 từ ông Hyler vào mùa thu năm 1971.\nTại Cuộc họp MIL-HDBK-5 lần thứ 46, được tổ chức vào tháng 10 năm 1973, ông D. A. Shinn tuyên bố rằng ông sẽ nghỉ hưu khỏi Không quân và sẽ từ chức Chủ tịch. Ông C. L. Harmsworth, AFML (Không quân), đã kế nhiệm ông Shinn làm Chủ tịch và chủ trì Cuộc họp lần thứ 46.\nBattelle đã chuẩn bị một bản chuyển đổi hệ mét “mềm” của bảy chương đầu tiên của MIL-HDBK-5. Phiên bản hệ mét “mềm” này của MIL-HDBK-5 đã được công bố trong báo cáo kỹ thuật của Không quân, AFWAL-TR-80-4110, “Hệ mét của MIL-HDBK-5C”, có niên đại là tháng 8 năm 1980. Mặc dù tài liệu này được công nhận là có hạn chế về tính hữu ích, nhưng lợi ích chính của nỗ lực này là phát hiện ra các vấn đề liên quan đến việc chuyển đổi sang các giá trị thiết kế hệ mét và trình bày dữ liệu thiết kế hệ mét.\nBắt đầu từ MIL-HDBK-5C, Thông báo thay đổi 3, có niên đại là tháng 6 năm 1981, các bản sửa đổi của MIL-HDBK-5 đã được sắp chữ tại Battelle, thay vì Trung tâm xuất bản và biểu mẫu của Hải quân. Thay đổi này được thực hiện để rút ngắn thời gian xử lý cần thiết để xuất bản các bản sửa đổi MIL-HDBK-5. Thông tin thiết kế cho sản phẩm đầu tiên do nhà cung cấp nước ngoài phát triển và tiếp thị đã được đưa vào MIL-HDBK-5D thông qua Thông báo thay đổi 1, có ngày 1 tháng 1 năm 1984. Các thông số thiết kế cho phép đối với tấm 7010-T73651 và -T7651 đã được thêm vào Sổ tay hướng dẫn. Các sản phẩm này được sản xuất bởi Alcan Plate Limited, Birmingham, Anh. Vật liệu được chế tạo và thử nghiệm bằng các đơn vị đo lường hệ mét. Dữ liệu về đặc tính cơ học hệ mét đã được chuyển đổi sang các đơn vị đo lường hệ Anh để phân tích và đưa vào MIL-HDBK-5.\nÔng Richard C. Rice đã tiếp quản vị trí lãnh đạo Battelle phụ trách các hoạt động phối hợp MIL-HDBK-5 từ ông Ruff vào mùa xuân năm 1993.\nTại Cuộc họp MIL-HDBK-5 lần thứ 87, được tổ chức tại Las Vegas, Nevada, vào tháng 4 năm 1994, ông Neal Ontko, AFRL, (Không quân), đã kế nhiệm ông C. L. Harmsworth làm Chủ tịch. Ông Steven Thompson, AFRL, cũng cam kết hỗ trợ ông Ontko trong vai trò mới là Chủ tịch.\nNhu cầu thay đổi giám sát của chính phủ đối với Sổ tay lần đầu tiên trở nên rõ ràng vào năm 1997, khi Không quân báo cáo rằng nguồn tài trợ hàng năm của họ cho hoạt động phối hợp kỹ thuật MIL-HDBK-5 đã bị cắt giảm đáng kể. Để giúp bù đắp cho sự suy giảm hỗ trợ của chính phủ đối với hoạt động phối hợp Sổ tay, Battelle đã thành lập, vào năm 1997, một Nhóm chỉ đạo công nghiệp (ISG) trả phí thành viên, bao gồm các nhà cung cấp và người sử dụng vật liệu kim loại hàng không vũ trụ và máy bay. Các công ty thành viên sáng lập ban đầu là; Century Aluminum, Alcoa Aluminum, Boeing, Lockheed Martin, Northrop Grumman và Textron. Tất cả các thành viên đều tham gia ở cấp độ duy nhất được cung cấp là 30.000 đô la mỗi năm. Số lượng thành viên ISG đã tăng đều đặn để đại diện cho 31 công ty vào năm 2014 từ 8 quốc gia, tham gia ở nhiều cấp độ thành viên khác nhau. Kể từ khi thành lập, ISG đã tổ chức các cuộc họp trước mỗi cuộc họp phối hợp Sổ tay và đã phối hợp chặt chẽ các hoạt động của mình với Nhóm chỉ đạo của chính phủ (GSG).\n\nNhững thay đổi tiếp theo trong việc giám sát của chính phủ đối với MIL-HDBK-5 đã chính thức được công bố vào năm 2003, khi Cục Hàng không Liên bang tiếp quản vai trò giám sát của chính phủ và đổi tên tài liệu thành Sổ tay Phát triển và Chuẩn hóa Tính chất Vật liệu Kim loại (MMPDS). FAA, do John Bakuckas (Trung tâm Kỹ thuật FAA) đứng đầu, sau đó đã ký hợp đồng 5 năm với Battelle để tiếp tục phối hợp kỹ thuật cho Sổ tay MMPDS và đã gia hạn hợp đồng theo từng đợt 5 năm cho đến năm 2018.\nMMPDS-01 và MIL-HDBK-5J được lập thành các tài liệu giống hệt nhau để chuyển đổi MIL-HDBK-5 sang MMPDS. MIL-HDBK-5J được phân loại là không còn hiệu lực vào mùa xuân năm 2004.\nKhi FAA tiếp quản việc giám sát của chính phủ đối với Sổ tay, họ đã yêu cầu Battelle phát triển thêm một nguồn doanh thu để duy trì Sổ tay thông qua quá trình thương mại hóa. Do đó, Sổ tay không còn được cung cấp miễn phí nữa kể từ MMPDS-02.\nKể từ thời điểm đó, Sổ tay MMPDS đã được bán dưới dạng tài liệu giấy và điện tử, cũng như dưới dạng cơ sở dữ liệu thông qua nhiều bên được cấp phép khác nhau.\nVào tháng 11 năm 2011, Richard C. Rice đã từ chức khỏi vị trí quản lý chương trình tại Battelle để nghỉ hưu vào tháng 12 và được thay thế bởi Jana L Rubadue làm quản lý chương trình Battelle. Ông Rice vẫn tiếp tục làm việc tại MMPDS với tư cách là một nhân viên bán thời gian.', 'Năm 1954, Viện Tưởng niệm Battelle (Battelle) đã được Phòng thí nghiệm Vật liệu, Căn cứ Không quân Wright-Patterson, Ohio trao hợp đồng để xem xét lĩnh vực tiêu chí thiết kế vật liệu-tính chất cho kim loại được sử dụng trong máy bay và tên lửa, và cập nhật biên soạn thông tin thiết kế cho thiết kế máy bay và tên lửa.', NULL, NULL, NULL, 'publisher/avatar/CS04QLZLUTX89WDQ0OKS.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4343, 'BOMA - Building Owners and Managers Association International', 'BOMA - Building Owners and Managers Association International', 'BOMA International is a primary source of information on building management and operations, development, leasing, building operating costs, energy consumption patterns, local and national building codes, legislation, occupancy statistics, technological developments and other industry trends.\nFounded in 1907, the Building Owners and Managers Association (BOMA) International is a federation of U.S. local associations and global affiliates. The leading trade association for commercial real estate professionals for more than 100 years, it represents the owners, managers, service providers and other property professionals of all commercial building types, including office, industrial, medical, corporate and mixed-use. BOMA International is the partner individuals in the commercial real estate industry choose to maximize value for their careers, organizations and assets. Its mission is to advance a vibrant commercial real estate industry through advocacy, influence and knowledge.\nBOMA International\'s dynamic leadership is made up not only of 5 elected officers and an elected Executive Committee, but it also includes the voices of all Local BOMA Associations through a 119 member Board of Governors.\nBOMA delivers quality programs to meet members\' changing educational needs and through unprecedented legislative advocacy efforts BOMA protects member interests. BOMA\'s influence is expanding through a growing membership and its achievements are the result of a strong, stable financial base.', 'BOMA International là nguồn thông tin chính về quản lý và vận hành tòa nhà, phát triển, cho thuê, chi phí vận hành tòa nhà, mô hình tiêu thụ năng lượng, quy định xây dựng địa phương và quốc gia, luật pháp, số liệu thống kê về tình trạng cư trú, phát triển công nghệ và các xu hướng khác của ngành.\nĐược thành lập vào năm 1907, Hiệp hội chủ sở hữu và quản lý tòa nhà (BOMA) quốc tế là một liên đoàn gồm các hiệp hội địa phương của Hoa Kỳ và các chi nhánh toàn cầu. Là hiệp hội thương mại hàng đầu dành cho các chuyên gia bất động sản thương mại trong hơn 100 năm, hiệp hội này đại diện cho chủ sở hữu, người quản lý, nhà cung cấp dịch vụ và các chuyên gia bất động sản khác thuộc mọi loại tòa nhà thương mại, bao gồm văn phòng, công nghiệp, y tế, doanh nghiệp và sử dụng hỗn hợp. BOMA International là đối tác mà các cá nhân trong ngành bất động sản thương mại lựa chọn để tối đa hóa giá trị cho sự nghiệp, tổ chức và tài sản của họ. Sứ mệnh của hiệp hội là thúc đẩy một ngành bất động sản thương mại sôi động thông qua hoạt động vận động, ảnh hưởng và kiến ​​thức.\nBan lãnh đạo năng động của BOMA International không chỉ bao gồm 5 viên chức được bầu và một Ủy ban điều hành được bầu mà còn bao gồm tiếng nói của tất cả các Hiệp hội BOMA địa phương thông qua Hội đồng quản trị gồm 119 thành viên.\nBOMA cung cấp các chương trình chất lượng để đáp ứng nhu cầu giáo dục thay đổi của các thành viên và thông qua các nỗ lực vận động lập pháp chưa từng có, BOMA bảo vệ quyền lợi của các thành viên. Ảnh hưởng của BOMA đang mở rộng thông qua số lượng thành viên ngày càng tăng và những thành tựu của tổ chức là kết quả của nền tảng tài chính vững mạnh và ổn định.', 'BOMA International là nguồn thông tin chính về quản lý và vận hành tòa nhà, phát triển, cho thuê, chi phí vận hành tòa nhà, mô hình tiêu thụ năng lượng, quy định xây dựng địa phương và quốc gia, luật pháp, số liệu thống kê về tình trạng cư trú, phát triển công nghệ và các xu hướng khác của ngành.', NULL, NULL, NULL, 'publisher/avatar/TXEBFVBMU8V735LBMZUF.png', 0),
(4344, 'BS - BSI Group', 'BS - BSI Group', 'The BSI catalog contains over 50,000 standards in PDF format, of which 31,000 are current. It includes standards of UK origin, European standards from CEN/CENELEC and international standards from ISO and IEC which have been adopted in the UK. BSI standards cover building and civil engineering, materials and chemicals, electrotechnology, consumer products and services, healthcare, management systems and information technology.', 'Viện Tiêu chuẩn Anh được lấy làm tên tổ chức vào năm 1931. BSI có Biên bản ghi nhớ với Chính phủ Vương quốc Anh, xác lập vị trí của BSI là Cơ quan Tiêu chuẩn Quốc gia Vương quốc Anh được công nhận. Hoạt động như một phần không thể thiếu của BSI, Ủy ban Kỹ thuật Điện Anh (BEC) là ủy ban quốc gia của IEC tại Vương quốc Anh. BSI là một tổ chức phân phối phi lợi nhuận và cung cấp các dịch vụ toàn cầu trong các lĩnh vực liên quan đến tiêu chuẩn hóa, đánh giá hệ thống, chứng nhận sản phẩm, đào tạo và dịch vụ tư vấn.\n\nDanh mục BSI chứa hơn 50.000 tiêu chuẩn ở định dạng PDF, trong đó có 31.000 tiêu chuẩn hiện hành. Nó bao gồm các tiêu chuẩn có nguồn gốc từ Vương quốc Anh, các tiêu chuẩn Châu Âu từ CEN/CENELEC và các tiêu chuẩn quốc tế từ ISO và IEC đã được áp dụng ở Anh. Tiêu chuẩn BSI bao gồm xây dựng và kỹ thuật dân dụng, vật liệu và hóa chất, công nghệ điện, sản phẩm và dịch vụ tiêu dùng, chăm sóc sức khỏe, hệ thống quản lý và công nghệ thông tin.', 'Viện Tiêu chuẩn Anh được lấy làm tên tổ chức vào năm 1931. BSI có Biên bản ghi nhớ với Chính phủ Vương quốc Anh, xác lập vị trí của BSI là Cơ quan Tiêu chuẩn Quốc gia Vương quốc Anh được công nhận. Hoạt động như một phần không thể thiếu của BSI, Ủy ban Kỹ thuật Điện Anh (BEC) là ủy ban quốc gia của IEC tại Vương quốc Anh. BSI là một tổ chức phân phối phi lợi nhuận và cung cấp các dịch vụ toàn cầu trong các lĩnh vực liên quan đến tiêu chuẩn hóa, đánh giá hệ thống, chứng nhận sản phẩm, đào tạo và dịch vụ tư vấn.', 'BS,BIP,PAS,DISC,EP,QGN,QSP,TA,CP,DD,HR,KIT,OHSAS,PP,PD,SP,TH', 'Tiêu chuẩn Anh, tiêu chuẩn BS, BS standard', NULL, 'publisher/avatar/61YZ32WV30AUO31G6NTX.jpg', 0),
(4345, 'CAN/CGSB - Canadian General Standards Board', 'CAN/CGSB - Canadian General Standards Board', 'The Canadian General Standards Board (CGSB) is a federal government organization that offers client-centred, comprehensive standards development and conformity assessment services in support of the economic, regulatory, procurement, health, safety and environmental interests of our stakeholders - government, industry and consumers.', 'CSA (Canadian Standards Association): CSA là tổ chức tiêu chuẩn hóa của Canada. Nó phát triển và công bố các tiêu chuẩn kỹ thuật áp dụng cho nhiều lĩnh vực khác nhau, bao gồm điện, điện tử, an toàn công cộng, xây dựng và nhiều lĩnh vực khác. Tiêu chuẩn CSA thường được sử dụng để đảm bảo tính an toàn, hiệu suất và tương thích của các sản phẩm và quy trình trong các ngành công nghiệp Canada.', 'CSA (Canadian Standards Association): CSA là tổ chức tiêu chuẩn hóa của Canada. Nó phát triển và công bố các tiêu chuẩn kỹ thuật áp dụng cho nhiều lĩnh vực khác nhau, bao gồm điện, điện tử, an toàn công cộng, xây dựng và nhiều lĩnh vực khác.', 'CAN,CSA,CAN/CSA,BNQ,1-GP', 'The Standards Council of Canada (SCC), Canadian Standards Association (CSA), CSA standard, Tiêu chuẩn quốc gia, tiêu chuẩn nước ngoài', '11.040*13.160*19.020*19.040*21*21.140*23.020*23.040*23.060*23.080*23.120*25.180*25.220*27.040*27.060*27.070*27.075*27.080*27.200*29.120*29.140*43.060*53.040*53.080*55*55.040*55.100*55.120*55.140*55.200*55.220*55.230*67.020*67.050*67.250*67.260*70.100*75.0', 'publisher/avatar/UEBQGM0VCSORKNMD9WMH.png', 0),
(4346, 'CAN/ULC - Underwriters Laboratories of Canada', 'CAN/ULC - Underwriters Laboratories of Canada', 'ULC tests and certifies products for public safety. It publishes over 180 standards on fire safety and equipment, building materials, electrical products, fire protection equipment, fire resistance, burglar and fire alarm systems, heating and ventilation equipment, and flammable liquids and gases.', NULL, NULL, NULL, NULL, '11.040*13.160*19.020*19.040*21*21.140*23.020*23.040*23.060*23.080*23.120*25.180*25.220*27.040*27.060*27.070*27.075*27.080*27.200*29.120*29.140*43.060*53.040*53.080*55*55.040*55.100*55.120*55.140*55.200*55.220*55.230*67.020*67.050*67.250*67.260*70.100*75.0', 'publisher/avatar/C1QXT5NXFFWS8NHWBMG8.jpg', 0),
(4347, 'CEI - Comitato Elettrotecnico Italiano', 'CEI - Comitato Elettrotecnico Italiano', 'CEI – Comitato Elettrotecnico Italiano is a private non-profit Association, responsible at the national level for technical standardization in the field of electrical, electronic, and telecommunications, with direct participation - on mandate from the Italian State - in the corresponding European (CENELEC - Comité Européen de Normalisation Electrotechnique) and international (IEC - International Electrotechnical Commission) standardization organizations. Founded in 1909 and recognized by the Italian State and the European Union (European Regulation), the CEI proposes, develops, publishes, and disseminates technical Standards that constitute the reference for the presumption of conformity to the \"state of the art\" of electrical products, processes, systems, and installations. Italian Law No. 186 of March 1, 1968, indeed establishes that \"All materials, equipment, machinery, installations, electrical and electronic systems must be manufactured and built in accordance with the state of the art\" and that those \"manufactured according to the standards of the Italian Electrotechnical Committee are considered to be built according to the state of the art\".\nThe CEI –  Italian Electrotechnical Committee  is a private, non-profit association,  responsible at a national level for  technical standardization in the electrical, electronic and telecommunications fields , with direct participation – on behalf of the Italian State – in the corresponding European ( CENELEC  –  Comité Européen de Normalisation Electrotechnique ) and international ( IEC  –  International Electrotechnical Commission ) standardization organizations .\nFounded in 1909 and recognized by the Italian State and the European Union  (European Regulation) , the CEI proposes,  develops, publishes and disseminates Technical Standards  that constitute the reference for the presumption of conformity to the \"rules of the art\" of electrical products, processes, systems and plants.\nItalian Law no. 186 of 1 March 1968 establishes that  \"All materials, equipment, machinery, installations and electrical and electronic systems must be made and constructed according to the rules of the art\"  and that the same  \"made according to the rules of the Italian Electrotechnical Committee are considered to be constructed according to the rules of the art\" .\nIEC standards\nThe  CEI Standards , largely implementations of international normative documents, also constitute a  unique and well-codified tool  for satisfying the mandatory requirements set forth by national and European legislation.\nThe technical standardization process is based on the  principle of consensus , following the participation and collaboration of all interested parties. A standard project is born to respond to specific needs expressed by the market to have shared references at a national (European or international) level. The CEI Standard project is developed within the Technical Committees of reference in which over  3,000 national Experts work , designated by the Legal, Promoter and Effective Members and coming from Ministries, Public and Private Bodies, Universities, Research and Testing Centers, Certification Bodies, Industrial Companies, Professional Orders, Trade and Cultural Associations.', 'CEI – Comitato Elettrotecnico Italiano là một Hiệp hội tư nhân phi lợi nhuận, chịu trách nhiệm ở cấp quốc gia về tiêu chuẩn hóa kỹ thuật trong lĩnh vực điện, điện tử và viễn thông, với sự tham gia trực tiếp - theo ủy quyền của Nhà nước Ý - trong các tổ chức tiêu chuẩn hóa tương ứng của Châu Âu (CENELEC - Comité Européen de Normalisation Electrotechnique) và quốc tế (IEC - Ủy ban Kỹ thuật Điện Quốc tế). Được thành lập vào năm 1909 và được Nhà nước Ý và Liên minh Châu Âu công nhận (Quy định Châu Âu), CEI đề xuất, phát triển, xuất bản và phổ biến các Tiêu chuẩn kỹ thuật tạo thành tài liệu tham khảo cho giả định về sự phù hợp với \"trạng thái nghệ thuật\" của các sản phẩm, quy trình, hệ thống và lắp đặt điện. Luật số 186 của Ý ngày 1 tháng 3 năm 1968 thực sự quy định rằng \"Tất cả các vật liệu, thiết bị, máy móc, hệ thống lắp đặt, hệ thống điện và điện tử phải được sản xuất và xây dựng theo tiêu chuẩn hiện đại\" và những vật liệu \"được sản xuất theo tiêu chuẩn của Ủy ban Kỹ thuật Điện Ý được coi là được xây dựng theo tiêu chuẩn hiện đại\".\nCEI – Ủy ban Kỹ thuật Điện Ý là một hiệp hội tư nhân, phi lợi nhuận, chịu trách nhiệm ở cấp quốc gia về tiêu chuẩn hóa kỹ thuật trong các lĩnh vực điện, điện tử và viễn thông, với sự tham gia trực tiếp – thay mặt cho Nhà nước Ý – vào các tổ chức tiêu chuẩn hóa tương ứng của Châu Âu (CENELEC – Comité Européen de Normalisation Electrotechnique) và quốc tế (IEC – Ủy ban Kỹ thuật Điện Quốc tế).\nĐược thành lập vào năm 1909 và được Nhà nước Ý và Liên minh Châu Âu (Quy định Châu Âu) công nhận, CEI đề xuất, phát triển, xuất bản và phổ biến các Tiêu chuẩn Kỹ thuật tạo thành tài liệu tham khảo cho giả định về sự phù hợp với \"quy tắc nghệ thuật\" của các sản phẩm, quy trình, hệ thống và nhà máy điện.\nLuật số 186 của Ý ngày 1 tháng 3 năm 1968 quy định rằng \"Tất cả các vật liệu, thiết bị, máy móc, lắp đặt và hệ thống điện và điện tử phải được sản xuất và xây dựng theo các quy tắc của nghệ thuật\" và rằng \"những thứ được sản xuất theo các quy tắc của Ủy ban Kỹ thuật Điện Ý được coi là được xây dựng theo các quy tắc của nghệ thuật\".\nTiêu chuẩn IEC\nTiêu chuẩn CEI, phần lớn là các văn bản chuẩn mực quốc tế, cũng tạo thành một công cụ độc đáo và được mã hóa tốt để đáp ứng các yêu cầu bắt buộc do luật pháp quốc gia và châu Âu đặt ra.\nQuy trình chuẩn hóa kỹ thuật dựa trên nguyên tắc đồng thuận, sau sự tham gia và hợp tác của tất cả các bên quan tâm. Một dự án tiêu chuẩn ra đời để đáp ứng các nhu cầu cụ thể do thị trường nêu ra nhằm có các tài liệu tham khảo chung ở cấp quốc gia (châu Âu hoặc quốc tế). Dự án Tiêu chuẩn CEI được xây dựng trong các Ủy ban Kỹ thuật tham khảo, trong đó có hơn 3.000 Chuyên gia quốc gia làm việc, được chỉ định bởi các Thành viên Pháp lý, Thúc đẩy và Hiệu quả và đến từ các Bộ, Cơ quan Công và Tư, Trường đại học, Trung tâm Nghiên cứu và Kiểm tra, Cơ quan Chứng nhận, Công ty Công nghiệp, Đơn đặt hàng Chuyên nghiệp, Hiệp hội Thương mại và Văn hóa.', 'CEI – Comitato Elettrotecnico Italiano là một Hiệp hội tư nhân phi lợi nhuận, chịu trách nhiệm ở cấp quốc gia về tiêu chuẩn hóa kỹ thuật trong lĩnh vực điện, điện tử và viễn thông, với sự tham gia trực tiếp - theo ủy quyền của Nhà nước Ý - trong các tổ chức tiêu chuẩn hóa tương ứng của Châu Âu (CENELEC - Comité Européen de Normalisation Electrotechnique) và quốc tế (IEC - Ủy ban Kỹ thuật Điện Quốc tế). Được thành lập vào năm 1909 và được Nhà nước Ý và Liên minh Châu Âu công nhận (Quy định Châu Âu), CEI đề xuất, phát triển, xuất bản và phổ biến các Tiêu chuẩn kỹ thuật tạo thành tài liệu tham khảo cho giả định về sự phù hợp với \"trạng thái nghệ thuật\" của các sản phẩm, quy trình, hệ thống và lắp đặt điện. Luật số 186 của Ý ngày 1 tháng 3 năm 1968 thực sự quy định rằng \"Tất cả các vật liệu, thiết bị, máy móc, hệ thống lắp đặt, hệ thống điện và điện tử phải được sản xuất và xây dựng theo tiêu chuẩn hiện đại\" và những vật liệu \"được sản xuất theo tiêu chuẩn của Ủy ban Kỹ thuật Điện Ý được coi là được xây dựng theo tiêu chuẩn hiện đại\".', NULL, NULL, NULL, 'publisher/avatar/AVBIH24AYIHGSLJS93PA.png', 0),
(4348, 'CFR - Code of Federal Regulations', 'CFR - Code of Federal Regulations', 'The Code of Federal Regulations is the codification of the general and permanent rules and regulations published in the Federal Register by the executive departments and agencies of the federal government of the United States.\nThe Office of the Federal Register (OFR) of the National Archives and Records Administration (NARA), and the U.S. Government Publishing Office (GPO) jointly administer the FederalRegister.gov website. We developed this website to make it easier for citizens and communities to understand the regulatory process and to participate in Government decision-making.', 'Bộ luật Quy định Liên bang là sự mã hóa các quy tắc và quy định chung và vĩnh viễn được công bố trên Công báo Liên bang bởi các bộ và cơ quan hành pháp của chính phủ liên bang Hoa Kỳ.\nVăn phòng Công báo Liên bang (OFR) của Cục Lưu trữ và Hồ sơ Quốc gia (NARA) và Văn phòng Xuất bản Chính phủ Hoa Kỳ (GPO) cùng quản lý trang web FederalRegister.gov. Chúng tôi đã phát triển trang web này để giúp công dân và cộng đồng dễ hiểu hơn về quy trình quản lý và tham gia vào quá trình ra quyết định của Chính phủ.', 'Bộ luật Quy định Liên bang là sự mã hóa các quy tắc và quy định chung và vĩnh viễn được công bố trên Công báo Liên bang bởi các bộ và cơ quan hành pháp của chính phủ liên bang Hoa Kỳ.', NULL, NULL, NULL, 'publisher/avatar/3XD0FBWTDKQ0VGQQN1IT.jpg', 0),
(4349, 'CGA - Compressed Gas Association', 'CGA - Compressed Gas Association', 'CGA publications address a wide range of standards, technical information and recommendations for best practices in the manufacture, storage, transportation, distribution, and use of industrial gases, cryogenic liquids and other products, including gas-handling equipment.\nCGA’s mission is to promote ever-improving safe, secure, and environmentally responsible manufacture, transportation, storage, transfilling, and disposal of industrial, medical, and food gases and their containers.\nMore than 180 companies worldwide are members of the Compressed Gas Association, from multinational corporations to family-owned businesses. These companies represent all facets of the industry: manufacturers, distributors, suppliers, and transporters of gases, cryogenic liquids, and related products. Our sphere of influence encompasses industrial, medical, food, and specialty gases in compressed or liquefied form, as well as a range of gas handling equipment.\nCompressed gases provide the invisible ingredient in millions of products used in everyday life. Together, our members supply products to industries that account for nearly 30% of the U.S. gross domestic product. In fact, every job our industry creates generates 2.3 additional jobs elsewhere in the economy.\nFor more than 110 years, the Compressed Gas Association has been dedicated to the development and promotion of safety standards and safe practices for our industry. We use a committee system comprised of member volunteers to develop technical specifications, safety standards, and training and educational materials. We also work with government agencies to help formulate and promote compliance with responsible regulations and standards.\nAdditionally, CGA works in close cooperation with other industrial gas associations around the world to harmonize standards and advance safety for the industry worldwide.\nSince 1913, CGA standards have served as the foundation for all facets of the industrial and medical gases and equipment industry in the United States and Canada.\nOur primary mission is to develop and promote safety standards and practices for ever-improving safe, secure, and environmentally responsible manufacture, transportation, storage, transfilling, and disposal of industrial and medical gases and their containers.\nCGA is the recognized leader in the development of gas and equipment standards in North America and around the world, many of which are referenced by regulators at all levels of government. CGA members enjoy a number of services that benefit their businesses.\nCGA is an accredited standards developer (ASD) through the American National Standards Institute (ANSI).', 'Các ấn phẩm của CGA đề cập đến nhiều tiêu chuẩn, thông tin kỹ thuật và khuyến nghị về các biện pháp thực hành tốt nhất trong sản xuất, lưu trữ, vận chuyển, phân phối và sử dụng khí công nghiệp, chất lỏng đông lạnh và các sản phẩm khác, bao gồm thiết bị xử lý khí.\nSứ mệnh của CGA là thúc đẩy sản xuất, vận chuyển, lưu trữ, chiết rót và xử lý khí công nghiệp, y tế và thực phẩm cùng các bình chứa của chúng một cách an toàn, bảo mật và có trách nhiệm với môi trường.\nHơn 180 công ty trên toàn thế giới là thành viên của Hiệp hội khí nén, từ các tập đoàn đa quốc gia đến các doanh nghiệp gia đình. Các công ty này đại diện cho mọi khía cạnh của ngành: nhà sản xuất, nhà phân phối, nhà cung cấp và đơn vị vận chuyển khí, chất lỏng đông lạnh và các sản phẩm liên quan. Phạm vi ảnh hưởng của chúng tôi bao gồm khí công nghiệp, y tế, thực phẩm và khí đặc biệt ở dạng nén hoặc hóa lỏng, cũng như một loạt các thiết bị xử lý khí.\nKhí nén cung cấp thành phần vô hình trong hàng triệu sản phẩm được sử dụng trong cuộc sống hàng ngày. Cùng nhau, các thành viên của chúng tôi cung cấp sản phẩm cho các ngành công nghiệp chiếm gần 30% tổng sản phẩm quốc nội của Hoa Kỳ. Trên thực tế, mỗi công việc mà ngành của chúng tôi tạo ra sẽ tạo ra thêm 2,3 việc làm ở nơi khác trong nền kinh tế.\nTrong hơn 110 năm, Hiệp hội Khí nén đã tận tụy phát triển và thúc đẩy các tiêu chuẩn an toàn và các biện pháp an toàn cho ngành của chúng tôi. Chúng tôi sử dụng một hệ thống ủy ban bao gồm các thành viên tình nguyện để phát triển các thông số kỹ thuật, tiêu chuẩn an toàn và tài liệu đào tạo và giáo dục. Chúng tôi cũng làm việc với các cơ quan chính phủ để giúp xây dựng và thúc đẩy việc tuân thủ các quy định và tiêu chuẩn có trách nhiệm.\nNgoài ra, CGA hợp tác chặt chẽ với các hiệp hội khí công nghiệp khác trên toàn thế giới để điều hòa các tiêu chuẩn và thúc đẩy an toàn cho ngành trên toàn thế giới.\nKể từ năm 1913, các tiêu chuẩn của CGA đã trở thành nền tảng cho mọi khía cạnh của ngành công nghiệp khí và thiết bị y tế và công nghiệp tại Hoa Kỳ và Canada.\nSứ mệnh chính của chúng tôi là phát triển và thúc đẩy các tiêu chuẩn và biện pháp an toàn để cải thiện liên tục sản xuất, vận chuyển, lưu trữ, chiết rót và xử lý khí công nghiệp và y tế cùng các bình chứa của chúng một cách an toàn, bảo mật và có trách nhiệm với môi trường.\nCGA là đơn vị dẫn đầu được công nhận trong việc phát triển các tiêu chuẩn về khí và thiết bị ở Bắc Mỹ và trên toàn thế giới, nhiều tiêu chuẩn trong số đó được các cơ quan quản lý ở mọi cấp chính quyền tham khảo. Các thành viên CGA được hưởng một số dịch vụ có lợi cho doanh nghiệp của họ.\nCGA là đơn vị phát triển tiêu chuẩn được công nhận (ASD) thông qua Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI).', 'Các ấn phẩm của CGA đề cập đến nhiều tiêu chuẩn, thông tin kỹ thuật và khuyến nghị về các biện pháp thực hành tốt nhất trong sản xuất, lưu trữ, vận chuyển, phân phối và sử dụng khí công nghiệp, chất lỏng đông lạnh và các sản phẩm khác, bao gồm thiết bị xử lý khí.\nSứ mệnh của CGA là thúc đẩy sản xuất, vận chuyển, lưu trữ, chiết rót và xử lý khí công nghiệp, y tế và thực phẩm cùng các bình chứa của chúng một cách an toàn, bảo mật và có trách nhiệm với môi trường.', NULL, NULL, '71*71.100*71.120', 'publisher/avatar/MT12VOLP4ZIIVEO7QXBG.jpg', 0),
(4350, 'CGSB - Canadian General Standards Board', 'CGSB - Canadian General Standards Board', 'CGA’s mission is to promote ever-improving safe, secure, and environmentally responsible manufacture, transportation, storage, transfilling, and disposal of industrial, medical, and food gases and their containers.', 'CGSB công bố hơn 1.500 tiêu chuẩn được chính phủ Canada sử dụng và được các ngành công nghiệp trên toàn thế giới công nhận. Cơ quan này cũng chứng nhận và đăng ký các nhà cung cấp có thể chứng minh rằng sản phẩm và dịch vụ của họ đáp ứng các tiêu chuẩn về chất lượng và hiệu suất được công nhận trên toàn quốc.\nHội đồng Tiêu chuẩn Canada (SCC) định nghĩa tiêu chuẩn là một tài liệu, được thiết lập theo sự đồng thuận và được một cơ quan được công nhận chấp thuận, cung cấp các quy tắc, hướng dẫn hoặc đặc điểm chung và lặp lại cho các hoạt động hoặc kết quả của chúng, nhằm đạt được mức độ hoặc thứ tự tối ưu trong một bối cảnh nhất định.\nHội đồng Tiêu chuẩn Chung Canada (CGSB) hiện có khoảng 350 tiêu chuẩn bằng tiếng Anh và tiếng Pháp - bao gồm nhiều loại sản phẩm và dịch vụ.\nNhân viên của Ban Tiêu chuẩn quản lý quy trình phát triển tiêu chuẩn bằng cách sử dụng các ủy ban cân bằng để đưa ra các tiêu chuẩn đồng thuận tự nguyện.\nTiêu chuẩn Quốc gia Canada (NSC), tiêu chuẩn CGSB và Tiêu chuẩn của Chính phủ Canada (GC) được CGSB xây dựng. NSC là tiêu chuẩn do Tổ chức Phát triển Tiêu chuẩn Canada (SDO) được công nhận như CGSB soạn thảo hoặc xem xét và được SCC chấp thuận. Tiêu chuẩn CGSB là một tài liệu được lập theo các chính sách và thủ tục của CGSB và được CGSB chấp thuận. Tiêu chuẩn GC là một tiêu chuẩn được xây dựng để nêu rõ các yêu cầu cụ thể của chính phủ đối với một vật liệu, một sản phẩm hoặc một dịch vụ, có thể đáp ứng hoặc không đáp ứng các yêu cầu của tiêu chuẩn NSC hoặc CGSB.', 'CGSB công bố hơn 1.500 tiêu chuẩn được chính phủ Canada sử dụng và được các ngành công nghiệp trên toàn thế giới công nhận. Cơ quan này cũng chứng nhận và đăng ký các nhà cung cấp có thể chứng minh rằng sản phẩm và dịch vụ của họ đáp ứng các tiêu chuẩn về chất lượng và hiệu suất được công nhận trên toàn quốc.', NULL, NULL, NULL, 'publisher/avatar/9U791CYQXGJ49RY9ORJF.png', 0),
(4351, 'CIE - Commission Internationale de L\'Eclairage', 'CIE - Commission Internationale de L\'Eclairage', 'More than 180 companies worldwide are members of the Compressed Gas Association, from multinational corporations to family-owned businesses. These companies represent all facets of the industry: manufacturers, distributors, suppliers, and transporters of gases, cryogenic liquids, and related products. Our sphere of influence encompasses industrial, medical, food, and specialty gases in compressed or liquefied form, as well as a range of gas handling equipment.', 'CIE (Commission Internationale de l\'Eclairage) là một tổ chức quốc tế chuyên về nghiên cứu và tiêu chuẩn hóa trong lĩnh vực chiếu sáng và màu sắc. Tên gọi CIE còn được biết đến là \"International Commission on Illumination\" trong tiếng Anh.\n\nCIE đã được thành lập vào năm 1913 và là một trong những tổ chức kỹ thuật đầu tiên trên thế giới chuyên về nghiên cứu và tiêu chuẩn hóa trong lĩnh vực chiếu sáng và màu sắc. Mục tiêu chính của CIE là khuyến khích và phát triển kiến thức về chiếu sáng và màu sắc, cũng như đề xuất các tiêu chuẩn và quy tắc kỹ thuật cho các ứng dụng thực tế.\n\nCIE tập trung vào nhiều lĩnh vực liên quan đến chiếu sáng và màu sắc, bao gồm đo lường ánh sáng, tính toán và mô phỏng ánh sáng, hiệu suất và tiết kiệm năng lượng, tương thích màu sắc, cảm giác thị giác và các vấn đề liên quan khác.\n\nCIE đã đóng góp quan trọng vào việc phát triển các tiêu chuẩn quốc tế về chiếu sáng và màu sắc. Các tiêu chuẩn CIE cung cấp các hướng dẫn và quy tắc về đo lường, phân loại và mô phỏng ánh sáng, chuẩn mực màu sắc, đánh giá hiệu suất chiếu sáng và màu sắc của các nguồn sáng, và các khía cạnh khác liên quan đến ánh sáng và màu sắc.\n\nTiêu chuẩn CIE đóng vai trò quan trọng trong việc đảm bảo chất lượng và đồng nhất trong các ứng dụng chiếu sáng và màu sắc trên toàn cầu, đồng thời đảm bảo sự tương thích và hiệu quả trong việc sử dụng ánh sáng và màu sắc trong các lĩnh vực như kiến trúc, thiết kế ánh sáng, công nghiệp giải trí, y học và nhiều lĩnh vực khác.', 'CIE (Commission Internationale de l\'Eclairage) là một tổ chức quốc tế chuyên về nghiên cứu và tiêu chuẩn hóa trong lĩnh vực chiếu sáng và màu sắc. Tên gọi CIE còn được biết đến là \"International Commission on Illumination\" trong tiếng Anh.', 'CIE', 'The International Commission on Illumination, CIE, Chiếu sáng, Tiêu chuẩn chiếu sáng', NULL, 'publisher/avatar/CMV05X5TILF70E943OD8.jpg', 0),
(4352, 'CII - Construction Industry Institute', 'CII - Construction Industry Institute', 'Compressed gases provide the invisible ingredient in millions of products used in everyday life. Together, our members supply products to industries that account for nearly 30% of the U.S. gross domestic product. In fact, every job our industry creates generates 2.3 additional jobs elsewhere in the economy.\nCII is the premier research & development platform for the capital projects industry. Based at The University of Texas at Austin, CII brings global project industry leaders together to create and drive innovative tools and solutions through an academically based, disciplined approach.\nFor more than four decades, this impressive consortium of more than 120 leading owner companies, engineering-contractor firms, and service providers – from both the public and private sectors – has collaborated through CII to improve safety, technology, cost, and schedule predictability across the members’ project portfolios.\nCII research is a collaborative effort that brings together industry and academia to identify opportunities and conduct research projects that align with its mission. Here\'s why CII research stands out: \n• Member-Driven Process: CII research thrives on active member involvement. Members pinpoint research areas, participate in Research Teams, review outcomes, and share insights through presentations and various media. Member engagement is pivotal at every stage. \n• Tangible Project Improvements: With over 40 years of dedicated research, CII has developed 17 Best Practices and numerous tools. The resources, which are accessible to organizations, are designed to significantly enhance project delivery. \n• Collaborative Approach: CII values diverse perspectives and collaboration. The collaborative nature of our approach relies on invaluable input from industry members and academics with different backgrounds. This diversity enriches the knowledge generated. \n• Academic Rigor: Projects adhere to a rigorous scientific approach. By involving subject matter experts from member organizations and tapping into the expertise of academics, CII ensures a solid foundation for all research endeavors.', 'Khí nén cung cấp thành phần vô hình trong hàng triệu sản phẩm được sử dụng trong cuộc sống hàng ngày. Cùng nhau, các thành viên của chúng tôi cung cấp sản phẩm cho các ngành công nghiệp chiếm gần 30% tổng sản phẩm quốc nội của Hoa Kỳ. Trên thực tế, mỗi công việc mà ngành của chúng tôi tạo ra sẽ tạo ra thêm 2,3 việc làm ở nơi khác trong nền kinh tế.\nCII là nền tảng nghiên cứu và phát triển hàng đầu cho ngành dự án vốn. Có trụ sở tại Đại học Texas tại Austin, CII tập hợp các nhà lãnh đạo ngành dự án toàn cầu lại với nhau để tạo ra và thúc đẩy các công cụ và giải pháp sáng tạo thông qua phương pháp tiếp cận có kỷ luật và dựa trên học thuật.\nTrong hơn bốn thập kỷ, tập đoàn ấn tượng này gồm hơn 120 công ty chủ sở hữu, công ty kỹ thuật-nhà thầu và nhà cung cấp dịch vụ hàng đầu - từ cả khu vực công và tư nhân - đã hợp tác thông qua CII để cải thiện khả năng dự đoán về an toàn, công nghệ, chi phí và lịch trình trên toàn bộ danh mục dự án của các thành viên.\nNghiên cứu của CII là nỗ lực hợp tác tập hợp ngành công nghiệp và học viện để xác định các cơ hội và tiến hành các dự án nghiên cứu phù hợp với sứ mệnh của mình. Sau đây là lý do tại sao nghiên cứu của CII nổi bật:\n• Quy trình do thành viên thúc đẩy: Nghiên cứu của CII phát triển mạnh mẽ nhờ sự tham gia tích cực của thành viên. Các thành viên xác định các lĩnh vực nghiên cứu, tham gia vào các Nhóm nghiên cứu, xem xét kết quả và chia sẻ hiểu biết thông qua các bài thuyết trình và nhiều phương tiện truyền thông khác nhau. Sự tham gia của thành viên là then chốt ở mọi giai đoạn.\n• Cải tiến Dự án hữu hình: Với hơn 40 năm nghiên cứu chuyên sâu, CII đã phát triển 17 Phương pháp hay nhất và nhiều công cụ. Các nguồn lực, có thể truy cập được đối với các tổ chức, được thiết kế để nâng cao đáng kể việc triển khai dự án.\n• Phương pháp tiếp cận hợp tác: CII coi trọng các quan điểm và sự hợp tác đa dạng. Bản chất hợp tác trong phương pháp tiếp cận của chúng tôi dựa trên sự đóng góp vô giá từ các thành viên trong ngành và các học giả có nền tảng khác nhau. Sự đa dạng này làm phong phú thêm kiến ​​thức được tạo ra.\n• Sự nghiêm ngặt về mặt học thuật: Các dự án tuân thủ một phương pháp tiếp cận khoa học nghiêm ngặt. Bằng cách thu hút các chuyên gia về chủ đề từ các tổ chức thành viên và khai thác chuyên môn của các học giả, CII đảm bảo nền tảng vững chắc cho mọi nỗ lực nghiên cứu.', 'CII là nền tảng nghiên cứu và phát triển hàng đầu cho ngành dự án vốn. Có trụ sở tại Đại học Texas tại Austin, CII tập hợp các nhà lãnh đạo ngành dự án toàn cầu lại với nhau để tạo ra và thúc đẩy các công cụ và giải pháp sáng tạo thông qua phương pháp tiếp cận có kỷ luật và dựa trên học thuật.', NULL, NULL, NULL, 'publisher/avatar/A3V97D2HS7O6FSMH8PJ8.jpg', 0),
(4353, 'CIRS - Centre for Innovation in Regulatory Science', 'CIRS - Centre for Innovation in Regulatory Science', 'For more than 110 years, the Compressed Gas Association has been dedicated to the development and promotion of safety standards and safe practices for our industry. We use a committee system comprised of member volunteers to develop technical specifications, safety standards, and training and educational materials. We also work with government agencies to help formulate and promote compliance with responsible regulations and standards.\nThe Centre for Innovation in Regulatory Science (CIRS) is a neutral, scientific and independently run global forum for policy leaders from government regulators, health technology assessment (HTA) agencies, the pharmaceutical industry, and other stakeholders in healthcare, such as patient organisations and academia. We serve patients, agencies and medical developers by focusing on improvements in policies and processes for regulation and HTA. CIRS also supports the development of agency capacity, including in low- and middle-income countries.\nThe CIRS team works internationally and is headquartered in the UK. CIRS works collaboratively with stakeholders worldwide, runs research projects internationally and conducts meetings globally to feed into and build on this research. Organisationally, CIRS is a wholly owned and independently managed UK subsidiary of Clarivate, with our funding derived from membership dues, special projects and grants from non-profits and governments.\nWhat sets us apart is our ability to facilitate safe harbour discussions between multiple stakeholders involved in drug development and patient access to medicines. CIRS meetings are usually small, focused and build on discussions from previous meetings to enable continuous evolution of a topic. They also include breakout sessions, which are key to producing recommendations to help effect change.\nWe are also evidence-driven and transparent in our work. The data we collect are used to support our workshops and we endeavour to make these publicly available through peer-reviewed journals or our R&D Briefings.\nOur small but dedicated team strive to ensure that the needs and priorities of our stakeholders are at the heart of CIRS activities. Our door is always open to new ideas and suggestions that fit with our mission.', 'Trong hơn 110 năm qua, Hiệp hội Khí nén đã tận tụy phát triển và thúc đẩy các tiêu chuẩn an toàn và thực hành an toàn cho ngành của chúng tôi. Chúng tôi sử dụng một hệ thống ủy ban bao gồm các thành viên tình nguyện để phát triển các thông số kỹ thuật, tiêu chuẩn an toàn và tài liệu đào tạo và giáo dục. Chúng tôi cũng làm việc với các cơ quan chính phủ để giúp xây dựng và thúc đẩy việc tuân thủ các quy định và tiêu chuẩn có trách nhiệm.\nTrung tâm Đổi mới Khoa học Quy định (CIRS) là một diễn đàn toàn cầu trung lập, khoa học và độc lập dành cho các nhà lãnh đạo chính sách từ các cơ quan quản lý của chính phủ, các cơ quan đánh giá công nghệ y tế (HTA), ngành dược phẩm và các bên liên quan khác trong lĩnh vực chăm sóc sức khỏe, chẳng hạn như các tổ chức bệnh nhân và học viện. Chúng tôi phục vụ bệnh nhân, các cơ quan và nhà phát triển y tế bằng cách tập trung vào việc cải thiện các chính sách và quy trình để quản lý và HTA. CIRS cũng hỗ trợ phát triển năng lực của các cơ quan, bao gồm cả ở các quốc gia có thu nhập thấp và trung bình.\nNhóm CIRS làm việc quốc tế và có trụ sở chính tại Vương quốc Anh. CIRS hợp tác với các bên liên quan trên toàn thế giới, thực hiện các dự án nghiên cứu quốc tế và tổ chức các cuộc họp trên toàn cầu để đưa vào và xây dựng dựa trên nghiên cứu này. Về mặt tổ chức, CIRS là công ty con của Clarivate tại Vương quốc Anh do Clarivate sở hữu hoàn toàn và quản lý độc lập, với nguồn tài trợ của chúng tôi có được từ phí thành viên, các dự án đặc biệt và các khoản tài trợ từ các tổ chức phi lợi nhuận và chính phủ.\nĐiểm khác biệt của chúng tôi là khả năng tạo điều kiện cho các cuộc thảo luận an toàn giữa nhiều bên liên quan tham gia vào quá trình phát triển thuốc và tiếp cận thuốc của bệnh nhân. Các cuộc họp của CIRS thường có quy mô nhỏ, tập trung và dựa trên các cuộc thảo luận từ các cuộc họp trước để cho phép chủ đề liên tục phát triển. Chúng cũng bao gồm các phiên thảo luận nhóm, đóng vai trò quan trọng trong việc đưa ra các khuyến nghị giúp tạo ra sự thay đổi.\nChúng tôi cũng lấy bằng chứng làm động lực và minh bạch trong công việc. Dữ liệu chúng tôi thu thập được sử dụng để hỗ trợ các hội thảo của chúng tôi và chúng tôi nỗ lực công khai các hội thảo này thông qua các tạp chí được bình duyệt ngang hàng hoặc các Bản tóm tắt về R&D của chúng tôi.\nĐội ngũ nhỏ nhưng tận tụy của chúng tôi luôn nỗ lực đảm bảo rằng nhu cầu và ưu tiên của các bên liên quan là trọng tâm của các hoạt động của CIRS. Chúng tôi luôn chào đón những ý tưởng và đề xuất mới phù hợp với sứ mệnh của mình.', 'Trong hơn 110 năm qua, Hiệp hội Khí nén đã tận tụy phát triển và thúc đẩy các tiêu chuẩn an toàn và thực hành an toàn cho ngành của chúng tôi. Chúng tôi sử dụng một hệ thống ủy ban bao gồm các thành viên tình nguyện để phát triển các thông số kỹ thuật, tiêu chuẩn an toàn và tài liệu đào tạo và giáo dục. Chúng tôi cũng làm việc với các cơ quan chính phủ để giúp xây dựng và thúc đẩy việc tuân thủ các quy định và tiêu chuẩn có trách nhiệm.', NULL, NULL, NULL, 'publisher/avatar/8NKPAFUNAC33XWPVT68Z.jpg', 0),
(4354, 'CISPR - International Special Committee on Radio Interference', 'CISPR - International Special Committee on Radio Interference', 'Additionally, CGA works in close cooperation with other industrial gas associations around the world to harmonize standards and advance safety for the industry worldwide.', 'CISPR (Comité International Spécial des Perturbations Radioélectriques) là Tiêu chuẩn Quốc tế về Tương thích điện từ. CISPR là một tổ chức tiêu chuẩn hóa quốc tế chuyên về tương thích điện từ và nhiễu điện từ.\n\nCISPR được thành lập vào năm 1934 và là một trong những tổ chức con của IEC (International Electrotechnical Commission), tổ chức quốc tế chịu trách nhiệm về tiêu chuẩn hóa trong lĩnh vực điện và điện tử.\n\nNhiệm vụ chính của CISPR là phát triển các tiêu chuẩn và quy tắc kỹ thuật liên quan đến tương thích điện từ và kiểm soát nhiễu điện từ. Các tiêu chuẩn CISPR tập trung vào việc đánh giá, đo lường và kiểm tra nhiễu điện từ gây ra bởi các thiết bị điện tử, máy móc và hệ thống điện.\n\nCISPR cũng tham gia vào quá trình phát triển các tiêu chuẩn quốc tế khác liên quan đến tương thích điện từ, ví dụ như tiêu chuẩn quốc tế về an toàn điện (IEC 60335), tiêu chuẩn quốc tế về sản phẩm y tế điện tử (IEC 60601) và nhiều tiêu chuẩn khác.\n\nTiêu chuẩn CISPR đóng vai trò quan trọng trong việc đảm bảo tính tương thích điện từ và giảm nhiễu điện từ trong các hệ thống điện tử và môi trường điện tử. Điều này đảm bảo rằng các thiết bị và hệ thống có thể hoạt động một cách đúng đắn và không gây ra nhiễu điện từ gây ảnh hưởng đến các thiết bị và hệ thống khác.', 'CISPR (Comité International Spécial des Perturbations Radioélectriques) là Tiêu chuẩn Quốc tế về Tương thích điện từ. CISPR là một tổ chức tiêu chuẩn hóa quốc tế chuyên về tương thích điện từ và nhiễu điện từ.', 'CISPR,CISPR/TR,IEC/CISPR,PDCISPR/TR,CISPR/IEC', 'Tiêu chuẩn Quốc tế về Tương thích điện từ (CISPR), International Special  Committee on Radio Interference (CISPR), Tương thích điện từ, Tiêu chuẩn Tương thích điện từ', NULL, 'publisher/avatar/H99L1JL8F6T97681V5DB.jpg', 0),
(4355, 'CLSI - Clinical and Laboratory Standards Institute', 'CLSI - Clinical and Laboratory Standards Institute', 'The Clinical and Laboratory Standards Institute (CLSI) is a not-for-profit organization that develops laboratory standards worldwide. Our standards are recognized by laboratories, accreditors, and government agencies as the best way to improve medical laboratory testing.\nCLSI facilitates the creation of best practice standards, guidelines, and products for medical laboratories by using the expertise of our volunteers. Organizations use CLSI standards to improve their testing outcomes, maintain accreditation, bring products to market faster, and navigate regulatory hurdles.\nThe strength of CLSI’s consensus process for standards development begins with our volunteers, who bring a diversity of skill sets, depth of expertise, and vast knowledge of regulatory requirements to lead the development of globally applicable clinical laboratory standards.\nCLSI’s collaborative approach ensures balanced representation from the global laboratory community to yield unbiased consensus standards that can be confidently adopted by laboratories, clinicians, regulatory agencies, and industry throughout the world.\nCLSI’s unique consensus process brings together experts from industry, government, and health care professions to develop timely standards recognized by laboratories, industry, accreditors, and regulators as the way to improve testing.\nCLSI documents focus on a variety of specialty areas, from laboratory basics to quality management systems, verification and validation, and information management. We also develop interactive tools, companion products, and bench aids based on these documents. Maximize your voice in the global laboratory community as you work alongside colleagues from diverse sectors to develop CLSI’s consensus-based standards and guidelines.', 'Viện Tiêu chuẩn Lâm sàng và Phòng xét nghiệm (CLSI) là một tổ chức phi lợi nhuận phát triển các tiêu chuẩn phòng xét nghiệm trên toàn thế giới. Các tiêu chuẩn của chúng tôi được các phòng xét nghiệm, đơn vị công nhận và các cơ quan chính phủ công nhận là cách tốt nhất để cải thiện xét nghiệm y khoa.\nCLSI tạo điều kiện thuận lợi cho việc tạo ra các tiêu chuẩn, hướng dẫn và sản phẩm thực hành tốt nhất cho các phòng xét nghiệm y khoa bằng cách sử dụng chuyên môn của các tình nguyện viên. Các tổ chức sử dụng các tiêu chuẩn CLSI để cải thiện kết quả xét nghiệm, duy trì sự công nhận, đưa sản phẩm ra thị trường nhanh hơn và vượt qua các rào cản về mặt quy định.\nSức mạnh của quy trình đồng thuận của CLSI đối với việc phát triển các tiêu chuẩn bắt đầu từ các tình nguyện viên của chúng tôi, những người mang đến sự đa dạng về kỹ năng, chiều sâu chuyên môn và kiến ​​thức sâu rộng về các yêu cầu của quy định để dẫn đầu quá trình phát triển các tiêu chuẩn phòng xét nghiệm lâm sàng có thể áp dụng trên toàn cầu.\nPhương pháp tiếp cận hợp tác của CLSI đảm bảo sự đại diện cân bằng từ cộng đồng phòng xét nghiệm toàn cầu để đưa ra các tiêu chuẩn đồng thuận khách quan có thể được các phòng xét nghiệm, bác sĩ lâm sàng, cơ quan quản lý và ngành công nghiệp trên toàn thế giới áp dụng một cách tự tin.\nQuy trình đồng thuận độc đáo của CLSI tập hợp các chuyên gia từ ngành công nghiệp, chính phủ và các chuyên gia chăm sóc sức khỏe để phát triển các tiêu chuẩn kịp thời được các phòng xét nghiệm, ngành công nghiệp, đơn vị công nhận và đơn vị quản lý công nhận là cách để cải thiện xét nghiệm.\nCác tài liệu của CLSI tập trung vào nhiều lĩnh vực chuyên môn, từ kiến ​​thức cơ bản về phòng thí nghiệm đến hệ thống quản lý chất lượng, xác minh và xác nhận, và quản lý thông tin. Chúng tôi cũng phát triển các công cụ tương tác, sản phẩm đi kèm và thiết bị hỗ trợ dựa trên các tài liệu này. Phát huy tối đa tiếng nói của bạn trong cộng đồng phòng thí nghiệm toàn cầu khi bạn làm việc cùng các đồng nghiệp từ nhiều lĩnh vực khác nhau để phát triển các tiêu chuẩn và hướng dẫn dựa trên sự đồng thuận của CLSI.', 'Viện Tiêu chuẩn Lâm sàng và Phòng xét nghiệm (CLSI) là một tổ chức phi lợi nhuận phát triển các tiêu chuẩn phòng xét nghiệm trên toàn thế giới. Các tiêu chuẩn của chúng tôi được các phòng xét nghiệm, đơn vị công nhận và các cơ quan chính phủ công nhận là cách tốt nhất để cải thiện xét nghiệm y khoa.', NULL, NULL, NULL, 'publisher/avatar/JXVJCEMJFK9S0VMW9MKH.jpg', 0),
(4356, 'CMAA - Crane Manufacturers Association of America', 'CMAA - Crane Manufacturers Association of America', 'Our primary mission is to develop and promote safety standards and practices for ever-improving safe, secure, and environmentally responsible manufacture, transportation, storage, transfilling, and disposal of industrial and medical gases and their containers.\nThe Crane Manufacturers Association of America, Inc. (CMAA) is an independent trade association in the United States. It is affiliated with the United States Division of Material Handling Industry. The voluntary association was incorporated as the CMAA in 1955.\nMember companies represent industry leaders in the overhead crane market, serve the United States market from operations based in the United States, Canada, and Mexico. CMAA, formerly the Electric Overhead Crane Institute, is an incorporated organization of leading electric overhead traveling crane manufacturers in the United States and an affiliate of Material Handling Industry.\nLeading crane manufacturers founded the Electric Overhead Crane Institute, or EOCI, in 1927 to promote standardization of cranes in both quality and performance, which is the root of CMAA. After publishing specifications in 1949 and 1961 of EOCI 61, CMAA’s Engineering Committee continued to propose specifications of CMAA 70, CMAA 74, CMAA 78, the last of which are Standards and Guidelines for Professional Services Performed on Overhead and Travelling Cranes and Associated Hoisting Equipment. Re-released in 2003, CMAA engineering committee published the Crane Operators Manual, as well as the Operational Guide for Lifting Devices in 2006. Members meet twice a year to update and review its publications.', 'Sứ mệnh chính của chúng tôi là phát triển và thúc đẩy các tiêu chuẩn và thông lệ an toàn để cải thiện liên tục sản xuất, vận chuyển, lưu trữ, chuyển tải và xử lý khí công nghiệp và y tế cùng các bình chứa khí một cách an toàn, bảo mật và có trách nhiệm với môi trường.\nHiệp hội các nhà sản xuất cần cẩu của Hoa Kỳ (CMAA) là một hiệp hội thương mại độc lập tại Hoa Kỳ. Hiệp hội này trực thuộc Sở Công nghiệp Xử lý Vật liệu Hoa Kỳ. Hiệp hội tự nguyện này được thành lập với tên gọi CMAA vào năm 1955.\nCác công ty thành viên đại diện cho những người dẫn đầu ngành trong thị trường cần cẩu trên cao, phục vụ thị trường Hoa Kỳ từ các hoạt động có trụ sở tại Hoa Kỳ, Canada và Mexico. CMAA, trước đây là Viện Cần cẩu Điện, là một tổ chức hợp nhất của các nhà sản xuất cần cẩu trên cao chạy bằng điện hàng đầu tại Hoa Kỳ và là chi nhánh của Ngành Công nghiệp Xử lý Vật liệu.\nCác nhà sản xuất cần cẩu hàng đầu đã thành lập Viện Cần cẩu Điện, hay EOCI, vào năm 1927 để thúc đẩy tiêu chuẩn hóa cần cẩu về cả chất lượng và hiệu suất, đây chính là gốc rễ của CMAA. Sau khi công bố các thông số kỹ thuật vào năm 1949 và 1961 của EOCI 61, Ủy ban Kỹ thuật của CMAA tiếp tục đề xuất các thông số kỹ thuật của CMAA 70, CMAA 74, CMAA 78, trong đó tiêu chuẩn cuối cùng là Tiêu chuẩn và Hướng dẫn cho Dịch vụ Chuyên nghiệp Thực hiện trên Cần trục Trên cao và Cần trục Di động và Thiết bị Nâng liên quan. Được phát hành lại vào năm 2003, ủy ban kỹ thuật của CMAA đã công bố Sổ tay Người vận hành Cần trục cũng như Hướng dẫn Vận hành cho Thiết bị Nâng vào năm 2006. Các thành viên họp hai lần một năm để cập nhật và xem xét các ấn phẩm của mình.', 'Hiệp hội các nhà sản xuất cần cẩu của Hoa Kỳ (CMAA) là một hiệp hội thương mại độc lập tại Hoa Kỳ. Hiệp hội này trực thuộc Sở Công nghiệp Xử lý Vật liệu Hoa Kỳ. Hiệp hội tự nguyện này được thành lập với tên gọi CMAA vào năm 1955', NULL, NULL, NULL, 'publisher/avatar/9T6F5GK51JRMXF0S1L6B.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4357, 'CRSI - Concrete Reinforcing Steel Institute', 'CRSI - Concrete Reinforcing Steel Institute', 'Founded in 1924, the Concrete Reinforcing Steel Institute (CRSI) is a technical institute and Standards Developing Organization (SDO) that stands as the authoritative resource for information related to steel reinforced concrete construction. CRSI offers many industry-trusted technical publications, standards documents, design aids, reference materials, and educational opportunities.\nApproximately 8 million tons of reinforcing steel (rebar) is manufactured per year using scrap steel in efficient manufacturing operations. It is estimated that the industry impacts over 75,000 people in steel transportation and placement.\nCRSI members include manufacturers, fabricators, material suppliers, and placers of steel reinforcing bars and related products as well as professionals who are involved in the research, design, and construction of steel reinforced concrete. CRSI members employ approximately 15,000 people in steel production and rebar fabrication at over 450 locations in 47 states throughout North America.\nStay up to date on Institute activities and promotions including new publication and technical document releases.\nThe non-profit CRSI Foundation fosters the educational and research mission of the Institute through educational programs and scholarships for students majoring in civil engineering, architecture, and other related disciplines at universities and technical schools. The Foundation also supports research fellowships and projects, which will ultimately advance the reinforced concrete industry.\nCRSI is headquartered in Schaumburg, Illinois, with regional offices located across the United States.', 'Được thành lập vào năm 1924, Viện Thép gia cường bê tông (CRSI) là một viện kỹ thuật và Tổ chức Phát triển Tiêu chuẩn (SDO) là nguồn thông tin có thẩm quyền liên quan đến kết cấu bê tông cốt thép. CRSI cung cấp nhiều ấn phẩm kỹ thuật, tài liệu tiêu chuẩn, công cụ hỗ trợ thiết kế, tài liệu tham khảo và cơ hội giáo dục đáng tin cậy trong ngành.\nKhoảng 8 triệu tấn thép gia cường (thanh cốt thép) được sản xuất mỗi năm bằng cách sử dụng thép phế liệu trong các hoạt động sản xuất hiệu quả. Người ta ước tính rằng ngành này tác động đến hơn 75.000 người trong lĩnh vực vận chuyển và lắp đặt thép.\nCác thành viên của CRSI bao gồm các nhà sản xuất, nhà chế tạo, nhà cung cấp vật liệu và người lắp đặt thanh cốt thép và các sản phẩm liên quan cũng như các chuyên gia tham gia vào nghiên cứu, thiết kế và xây dựng bê tông cốt thép. Các thành viên của CRSI tuyển dụng khoảng 15.000 người trong lĩnh vực sản xuất thép và chế tạo thanh cốt thép tại hơn 450 địa điểm ở 47 tiểu bang trên khắp Bắc Mỹ.\nHãy cập nhật các hoạt động và chương trình khuyến mãi của Viện bao gồm các ấn phẩm mới và bản phát hành tài liệu kỹ thuật.\nQuỹ CRSI phi lợi nhuận thúc đẩy sứ mệnh giáo dục và nghiên cứu của Viện thông qua các chương trình giáo dục và học bổng cho sinh viên chuyên ngành kỹ thuật dân dụng, kiến ​​trúc và các ngành liên quan khác tại các trường đại học và trường kỹ thuật. Quỹ cũng hỗ trợ các học bổng và dự án nghiên cứu, cuối cùng sẽ thúc đẩy ngành bê tông cốt thép.\nCRSI có trụ sở chính tại Schaumburg, Illinois, với các văn phòng khu vực trên khắp Hoa Kỳ.', 'Được thành lập vào năm 1924, Viện Thép gia cường bê tông (CRSI) là một viện kỹ thuật và Tổ chức Phát triển Tiêu chuẩn (SDO) là nguồn thông tin có thẩm quyền liên quan đến kết cấu bê tông cốt thép. CRSI cung cấp nhiều ấn phẩm kỹ thuật, tài liệu tiêu chuẩn, công cụ hỗ trợ thiết kế, tài liệu tham khảo và cơ hội giáo dục đáng tin cậy trong ngành.', NULL, NULL, NULL, 'publisher/avatar/HDLYN6WIERKEVC0CDANK.jpg', 0),
(4358, 'CSA - CSA Group', 'CSA - CSA Group', 'CSA Group is a global organization dedicated to safety, social good and sustainability. We are a leader in North American Standards and in Testing, Inspection and Certification around the world.\nOur mandate is to hold the future to a higher standard.\nAt CSA Group, we excel in addressing emerging, complex issues and technologies. CSA Group is comprised of two organizations: Standards and Testing, Inspection, & Certification.\nStandards\nThe mission of CSA Group’s not-for-profit Standards organization is to enhance the lives of Canadians through the advancement of standards in the public and private sectors.  We are a leader in standards research, development, education, and advocacy. The technical and management standards developed with our more than 11,000 members improve safety, health, the environment, and economic efficiency in Canada and beyond.\nTesting, Inspection and Certification\nCSA Group’s global commercial subsidiaries provide expert testing, inspection, and certification services that enable manufacturers to demonstrate that their products are in compliance with applicable safety, environmental, and operating performance standards for markets around the world. We offer deep expertise and industry-leading service delivery across a wide range of current and emerging technologies.', 'CSA Group là một tổ chức toàn cầu chuyên về an toàn, lợi ích xã hội và tính bền vững. Chúng tôi là đơn vị dẫn đầu về Tiêu chuẩn Bắc Mỹ và trong lĩnh vực Kiểm tra, Kiểm định và Chứng nhận trên toàn thế giới.\nNhiệm vụ của chúng tôi là giữ cho tương lai đạt tiêu chuẩn cao hơn.\nTại CSA Group, chúng tôi xuất sắc trong việc giải quyết các vấn đề và công nghệ mới nổi, phức tạp. CSA Group bao gồm hai tổ chức: Tiêu chuẩn và Kiểm tra, Kiểm định và Chứng nhận.\nTiêu chuẩn\nSứ mệnh của tổ chức Tiêu chuẩn phi lợi nhuận của CSA Group là nâng cao cuộc sống của người dân Canada thông qua việc thúc đẩy các tiêu chuẩn trong khu vực công và tư nhân. Chúng tôi là đơn vị dẫn đầu trong nghiên cứu, phát triển, giáo dục và vận động tiêu chuẩn. Các tiêu chuẩn kỹ thuật và quản lý được phát triển với hơn 11.000 thành viên của chúng tôi giúp cải thiện an toàn, sức khỏe, môi trường và hiệu quả kinh tế tại Canada và nhiều nơi khác.\nKiểm tra, Kiểm định và Chứng nhận\nCác công ty con thương mại toàn cầu của CSA Group cung cấp các dịch vụ kiểm tra, kiểm định và chứng nhận chuyên môn, cho phép các nhà sản xuất chứng minh rằng sản phẩm của họ tuân thủ các tiêu chuẩn về an toàn, môi trường và hiệu suất hoạt động hiện hành cho các thị trường trên toàn thế giới. Chúng tôi cung cấp chuyên môn sâu rộng và dịch vụ hàng đầu trong ngành trên nhiều công nghệ hiện tại và mới nổi.', 'CSA Group là một tổ chức toàn cầu chuyên về an toàn, lợi ích xã hội và tính bền vững. Chúng tôi là đơn vị dẫn đầu về Tiêu chuẩn Bắc Mỹ và trong lĩnh vực Kiểm tra, Kiểm định và Chứng nhận trên toàn thế giới.', NULL, NULL, '11.040*13.160*19.020*19.040*21*21.140*23.020*23.040*23.060*23.080*23.120*25.180*25.220*27.040*27.060*27.070*27.075*27.080*27.200*29.120*29.140*43.060*53.040*53.080*55*55.040*55.100*55.120*55.140*55.200*55.220*55.230*67.020*67.050*67.250*67.260*70.100*75.0', 'publisher/avatar/FSRO9TWOD2362JGVQCEA.jpg', 0),
(4359, 'CTA - Consumer Technology Association (Formerly CEA)', 'CTA - Consumer Technology Association (Formerly CEA)', 'As an ANSI-accredited standards body, CTA provides essential industry standards that enable interoperability between new products and existing devices. CTA standards can help you navigate the critical trends between technological innovation, marketplace globalization and regulatory reform.\nTechnology is about changing people’s lives for the better.\nIt’s about ideas, large and small, that keep us connected, that help us move, that spark even bigger ideas. The Consumer Technology Association (CTA)® convenes companies of every size and specialty in the technology industry to move us all forward.\nCTA is the trade association representing the $505 billion U.S. consumer technology industry, which supports more than 18 million U.S. jobs.\nOn August 28, we\'re unveiling refreshed logos for CES and CTA. It’s for you — our members, CES attendees and exhibitors, the boundary-pushers, tomorrow’s innovators.  \nWhy now? This change comes at a pivotal moment—CTA\'s 100th anniversary and a time of unprecedented momentum for CTA, CES, and you, the industry we support and represent. As we look ahead to the next century, we will continue to vigorously support and empower the tech industry as it tackles some of the world\'s greatest challenges. \nCTA educates U.S. policymakers to ensure the innovation economy is protected from laws and regulations that delay, restrict or ban the development of technologies in all our sectors.\nWith constant advancements in technology, the demand for workers with high-tech skills has skyrocketed.\nMatching new business needs with skilled workers requires innovative solutions – CTA is leading a multi-pronged effort to create high-skilled employment opportunities for all Americans.', 'Là một tổ chức tiêu chuẩn được ANSI công nhận, CTA cung cấp các tiêu chuẩn công nghiệp thiết yếu cho phép khả năng tương tác giữa các sản phẩm mới và các thiết bị hiện có. Các tiêu chuẩn của CTA có thể giúp bạn điều hướng các xu hướng quan trọng giữa đổi mới công nghệ, toàn cầu hóa thị trường và cải cách quy định.\nCông nghệ là về việc thay đổi cuộc sống của mọi người theo hướng tốt đẹp hơn.\nĐó là về những ý tưởng, lớn và nhỏ, giúp chúng ta kết nối, giúp chúng ta di chuyển, khơi dậy những ý tưởng lớn hơn nữa. Hiệp hội Công nghệ Tiêu dùng (CTA)® triệu tập các công ty ở mọi quy mô và chuyên ngành trong ngành công nghệ để đưa tất cả chúng ta tiến về phía trước.\nCTA là hiệp hội thương mại đại diện cho ngành công nghệ tiêu dùng trị giá 505 tỷ đô la của Hoa Kỳ, hỗ trợ hơn 18 triệu việc làm tại Hoa Kỳ.\nVào ngày 28 tháng 8, chúng tôi sẽ công bố logo mới cho CES và CTA. Logo này dành cho các bạn — các thành viên, những người tham dự và triển lãm CES, những người thúc đẩy ranh giới, những nhà đổi mới của tương lai.\nTại sao lại là bây giờ? Sự thay đổi này diễn ra vào thời điểm then chốt—kỷ niệm 100 năm thành lập CTA và là thời điểm có động lực chưa từng có đối với CTA, CES và bạn, ngành mà chúng tôi hỗ trợ và đại diện. Khi hướng tới thế kỷ tiếp theo, chúng tôi sẽ tiếp tục hỗ trợ và trao quyền mạnh mẽ cho ngành công nghệ khi ngành này giải quyết một số thách thức lớn nhất thế giới.\nCTA đào tạo các nhà hoạch định chính sách của Hoa Kỳ để đảm bảo nền kinh tế đổi mới được bảo vệ khỏi các luật và quy định làm chậm trễ, hạn chế hoặc cấm phát triển công nghệ trong mọi lĩnh vực của chúng tôi.\nVới những tiến bộ không ngừng trong công nghệ, nhu cầu về lao động có kỹ năng công nghệ cao đã tăng vọt.\nViệc kết hợp các nhu cầu kinh doanh mới với lao động có tay nghề đòi hỏi các giải pháp sáng tạo – CTA đang dẫn đầu nỗ lực đa hướng để tạo ra các cơ hội việc làm có tay nghề cao cho tất cả người Mỹ.', 'Là một tổ chức tiêu chuẩn được ANSI công nhận, CTA cung cấp các tiêu chuẩn công nghiệp thiết yếu cho phép khả năng tương tác giữa các sản phẩm mới và các thiết bị hiện có. Các tiêu chuẩn của CTA có thể giúp bạn điều hướng các xu hướng quan trọng giữa đổi mới công nghệ, toàn cầu hóa thị trường và cải cách quy định.', NULL, NULL, NULL, 'publisher/avatar/0I87ZQBT0TLU3O85XI67.jpg', 0),
(4360, 'CTI - Cooling Technology Institute', 'CTI - Cooling Technology Institute', 'CTI, the Cooling Technology Institute, advocates and promotes the use of environmentally responsible Evaporative Heat Transfer Systems (EHTS) for the benefit of the public by encouraging education, research, standards development and verification, government relations and technical information exchange. CTI publications cover design, manufacture, testing, maintenance and repair of open and closed circuit wet, atmospheric cooling towers, providing cooled water for air-conditioning, manufacturing and electric power generation.\nThe Cooling Technology Institute is a broad-based industry association. Our mission is to advocate and promote, for the benefit of the public, the use of all environmentally responsible commercial cooling technologies such as wet cooling towers, air-cooled condensers, dry coolers, indirect cooling, and hybrid systems by encouraging education, the development of codes, standards, and guidelines, the use and oversight of independent performance verification and certification programs, research and development, information exchange, and dialog with government agencies and organizations with a shared interest in sustainable heat rejection equipment.\nThe forerunner of CTI was formed in mid-1939.  It was a trade association composed of seven companies that manufactured cooling towers.  The companies were Binks, C.H. Wheeler, Fluor Corp, Foster Wheeler, Lillie-Hoffmann, Marley, and Schubert Christy.  The organization was formed for the purpose of industry betterment and the establishment of design standards.  The organization lasted for less than two years.\nIn 1950, CTI was formed by seven charter members.  The organization was headquartered in Basking Ridge, NJ.  The members were Fluor Corp (Los Angeles, CA), Foster Wheeler Corp (NY, NY), Hudson Engineering Corp (Houston, TX), Lillie-Hoffman Cooling Towers (St. Louis, MO), The Marley Company (Kansas City, KS), J.F. Pritchard & Co (Kansas City, MO) and C.H. Wheeler Manufacturing Co (Philadelphia, PA).  CTI also began as a trade association for the purpose of industry betterment and the establishment of industry standards.\nCTI transitioned to an industry association, including owner-operators and suppliers during the early 1960s.  Some of the founding companies had left the trade association between 1959 and 1965, and with the gradual inclusion of owner-operators and suppliers, the organization evolved the need to reorganize.  In 1966, much of the current organization was reorganized into three interest groups around manufacturers, suppliers, and owner-operators, with a nine-person board of directors, three in each group that had staggered 3-year terms.  The organization remained as one based on corporate memberships.  Presidents were elected by the membership, rotating through the interest groups.\nLater, CTI has added individual memberships for owner-operators and students.  In 2000, the scope of CTI was broadened to include all heat rejection equipment, not only cooling towers.  The operating name of the organization was changed to the Cooling Technology Institute.', 'CTI, Viện Công nghệ Làm mát, ủng hộ và thúc đẩy việc sử dụng Hệ thống Truyền nhiệt Bốc hơi (EHTS) có trách nhiệm với môi trường vì lợi ích của công chúng bằng cách khuyến khích giáo dục, nghiên cứu, phát triển và xác minh tiêu chuẩn, quan hệ chính phủ và trao đổi thông tin kỹ thuật. Các ấn phẩm của CTI bao gồm thiết kế, sản xuất, thử nghiệm, bảo trì và sửa chữa các tháp giải nhiệt khí quyển ướt mạch hở và mạch kín, cung cấp nước làm mát cho hệ thống điều hòa không khí, sản xuất và phát điện.\nViện Công nghệ Làm mát là một hiệp hội công nghiệp rộng lớn. Sứ mệnh của chúng tôi là ủng hộ và thúc đẩy, vì lợi ích của công chúng, việc sử dụng tất cả các công nghệ làm mát thương mại có trách nhiệm với môi trường như tháp giải nhiệt ướt, bình ngưng tụ làm mát bằng không khí, máy làm mát khô, làm mát gián tiếp và hệ thống lai bằng cách khuyến khích giáo dục, phát triển các quy tắc, tiêu chuẩn và hướng dẫn, sử dụng và giám sát các chương trình chứng nhận và xác minh hiệu suất độc lập, nghiên cứu và phát triển, trao đổi thông tin và đối thoại với các cơ quan và tổ chức chính phủ có chung mối quan tâm đến thiết bị loại bỏ nhiệt bền vững.\nTiền thân của CTI được thành lập vào giữa năm 1939. Đây là một hiệp hội thương mại bao gồm bảy công ty sản xuất tháp giải nhiệt. Các công ty là Binks, C.H. Wheeler, Fluor Corp, Foster Wheeler, Lillie-Hoffmann, Marley và Schubert Christy. Tổ chức được thành lập với mục đích cải thiện ngành và thiết lập các tiêu chuẩn thiết kế. Tổ chức tồn tại chưa đầy hai năm.\nNăm 1950, CTI được thành lập bởi bảy thành viên sáng lập. Tổ chức có trụ sở chính tại Basking Ridge, NJ. Các thành viên là Fluor Corp (Los Angeles, CA), Foster Wheeler Corp (NY, NY), Hudson Engineering Corp (Houston, TX), Lillie-Hoffman Cooling Towers (St. Louis, MO), The Marley Company (Kansas City, KS), J.F. Pritchard & Co (Kansas City, MO) và C.H. Wheeler Manufacturing Co (Philadelphia, PA). CTI cũng bắt đầu là một hiệp hội thương mại với mục đích cải thiện ngành và thiết lập các tiêu chuẩn ngành.\nCTI chuyển đổi thành một hiệp hội ngành, bao gồm chủ sở hữu-người điều hành và nhà cung cấp vào đầu những năm 1960. Một số công ty sáng lập đã rời khỏi hiệp hội thương mại trong khoảng thời gian từ năm 1959 đến năm 1965, và với sự tham gia dần dần của chủ sở hữu-người điều hành và nhà cung cấp, tổ chức đã phát triển nhu cầu tái tổ chức. Năm 1966, phần lớn tổ chức hiện tại đã được tổ chức lại thành ba nhóm lợi ích xung quanh các nhà sản xuất, nhà cung cấp và chủ sở hữu-người điều hành, với một hội đồng quản trị gồm chín người, ba người trong mỗi nhóm có nhiệm kỳ 3 năm xen kẽ. Tổ chức vẫn là một tổ chức dựa trên các thành viên công ty. Các chủ tịch được bầu bởi các thành viên, luân phiên qua các nhóm lợi ích.\nSau đó, CTI đã bổ sung thêm các thành viên cá nhân cho chủ sở hữu-người điều hành và sinh viên. Năm 2000, phạm vi hoạt động của CTI đã được mở rộng để bao gồm tất cả các thiết bị loại bỏ nhiệt, không chỉ tháp giải nhiệt. Tên hoạt động của tổ chức đã được đổi thành Viện Công nghệ Làm mát.', 'CTI, Viện Công nghệ Làm mát, ủng hộ và thúc đẩy việc sử dụng Hệ thống Truyền nhiệt Bốc hơi (EHTS) có trách nhiệm với môi trường vì lợi ích của công chúng bằng cách khuyến khích giáo dục, nghiên cứu, phát triển và xác minh tiêu chuẩn, quan hệ chính phủ và trao đổi thông tin kỹ thuật. Các ấn phẩm của CTI bao gồm thiết kế, sản xuất, thử nghiệm, bảo trì và sửa chữa các tháp giải nhiệt khí quyển ướt mạch hở và mạch kín, cung cấp nước làm mát cho hệ thống điều hòa không khí, sản xuất và phát điện.', NULL, NULL, NULL, 'publisher/avatar/S1AFGFSTSN3C81JYOQMO.png', 0),
(4361, 'DID - Data Item Description', 'DID - Data Item Description', 'A Data Item Description is a completed document defining the data deliverables required of a United States Department of Defense contractor. A DID specifically defines the data content, format, and intended use of the data with a primary objective of achieving standardization objectives by the U.S. Department of Defense.\nA United States data item description (DID) is a completed document defining the data deliverables required of a United States Department of Defense contractor. A DID specifically defines the data content, format, and intended use of the data with a primary objective of achieving standardization objectives by the U.S. Department of Defense. The content and format requirements for DIDs are defined within MIL-STD-963C, Data Item Descriptions (2014) \nThe terminology of DIDs and the term contract data requirements list (CDRL) originated with US military procurements, and it is now often encountered in other large procurements that are modeled after the military procurement process.[3] Within a military solicitation or contract, each DID is uniquely numbered to identify the data deliverables in terms of specific information such as: purpose, description, preparation instructions including a table of contents and descriptions of each section, and references to the Contract Statement of work (SOW).\nPractices and terms where definition is given by MIL-STD-963:\n• Tailoring of data requirements. The deletion of the applicability of a portion of the data requirements from an approved DID that are unnecessary to meet the needs of a specific contract.\n• Format. The desired organization, structure, or arrangement of the content of the data product described by the DID. This term relates to the shape, size, makeup, style, physical organization, or arrangement of the data product described in the DID.\n• Content. The desired subject(s), topic(s), or element(s) which constitutes the data product described in the DID (for example, a string of defined data elements for entry into a Government database; a listing of paragraph titles or topics for inclusion in a data deliverable) under general topics; or subject matter which may be further defined into sub-topics. For a specific contract, the content of a deliverable shall contain information that fulfills the requirements identified in the CDRL and the description of the DID. Documents should have section numbers and titles matching to the subsections of the DID content description for easier application and use.\n• DID number: Each DID is assigned a unique three-part identifier by the DID approval authority. An example DID number for repetitive use is DI-SESS-80013B (DI- Data Item; SESS – four character code for the \"Systems Engineering\" Standardization Area [see \"SD-1, Standardization Directory\"[4] for descriptions]; 80013 assigned by ASSIST Automated Document Number Module, and B the sequential version). An example DID number for one-time use is OT-13-1000 (OT- One Time; 13 – fiscal year issued; 10000 – the first number assigned in FY13 by the Army).\nSince DID documents are what contract mechanics cause to be produced, the defined content guidelines and their terminologies are commonly referred to in United States Military Standards or other forms of procedural and administrative guidance of the United States Department of Defense.', 'Mô tả mục dữ liệu là một tài liệu hoàn chỉnh xác định các mục dữ liệu bắt buộc đối với nhà thầu của Bộ Quốc phòng Hoa Kỳ. DID xác định cụ thể nội dung dữ liệu, định dạng và mục đích sử dụng dữ liệu với mục tiêu chính là đạt được các mục tiêu chuẩn hóa của Bộ Quốc phòng Hoa Kỳ.\nMô tả mục dữ liệu (DID) của Hoa Kỳ là một tài liệu hoàn chỉnh xác định các mục dữ liệu bắt buộc đối với nhà thầu của Bộ Quốc phòng Hoa Kỳ. DID xác định cụ thể nội dung dữ liệu, định dạng và mục đích sử dụng dữ liệu với mục tiêu chính là đạt được các mục tiêu chuẩn hóa của Bộ Quốc phòng Hoa Kỳ. Các yêu cầu về nội dung và định dạng đối với DID được xác định trong MIL-STD-963C, Mô tả mục dữ liệu (2014)\nThuật ngữ DID và thuật ngữ danh sách yêu cầu dữ liệu theo hợp đồng (CDRL) có nguồn gốc từ các hoạt động mua sắm của quân đội Hoa Kỳ và hiện nay thường gặp trong các hoạt động mua sắm lớn khác được mô phỏng theo quy trình mua sắm của quân đội.[3] Trong một hợp đồng hoặc chào hàng quân sự, mỗi DID được đánh số duy nhất để xác định các dữ liệu có thể cung cấp theo thông tin cụ thể như: mục đích, mô tả, hướng dẫn chuẩn bị bao gồm mục lục và mô tả của từng phần và tham chiếu đến Tuyên bố hợp đồng về công việc (SOW).\nCác thông lệ và thuật ngữ mà định nghĩa được đưa ra bởi MIL-STD-963:\n• Điều chỉnh các yêu cầu về dữ liệu. Xóa bỏ khả năng áp dụng một phần các yêu cầu về dữ liệu khỏi DID đã được phê duyệt mà không cần thiết để đáp ứng nhu cầu của một hợp đồng cụ thể.\n• Định dạng. Tổ chức, cấu trúc hoặc sắp xếp mong muốn của nội dung sản phẩm dữ liệu được mô tả bởi DID. Thuật ngữ này liên quan đến hình dạng, kích thước, thành phần, kiểu dáng, tổ chức vật lý hoặc sắp xếp của sản phẩm dữ liệu được mô tả trong DID.\n• Nội dung. Chủ đề(các chủ đề), phần tử(các phần tử) mong muốn tạo nên sản phẩm dữ liệu được mô tả trong DID (ví dụ: chuỗi phần tử dữ liệu được xác định để nhập vào cơ sở dữ liệu của Chính phủ; danh sách tiêu đề đoạn văn hoặc chủ đề để đưa vào dữ liệu chuyển giao) theo chủ đề chung; hoặc chủ đề có thể được xác định thêm thành các chủ đề phụ. Đối với hợp đồng cụ thể, nội dung của dữ liệu chuyển giao phải chứa thông tin đáp ứng các yêu cầu được xác định trong CDRL và mô tả về DID. Tài liệu phải có số phần và tiêu đề khớp với các phần phụ của mô tả nội dung DID để dễ áp ​​dụng và sử dụng hơn. • Số DID: Mỗi DID được cơ quan phê duyệt DID chỉ định một mã định danh ba phần duy nhất. Một ví dụ về số DID để sử dụng nhiều lần là DI-SESS-80013B (DI- Mục dữ liệu; SESS – mã bốn ký tự cho Khu vực chuẩn hóa \"Kỹ thuật hệ thống\" [xem \"SD-1, Thư mục chuẩn hóa\"[4] để biết mô tả]; 80013 do Mô-đun số tài liệu tự động ASSIST chỉ định và B là phiên bản tuần tự). Một ví dụ về số DID dùng một lần là OT-13-1000 (OT- Một lần; 13 – năm tài chính được cấp; 10000 – số đầu tiên được Quân đội cấp trong năm tài chính 2013).\nVì các tài liệu DID là những gì các thợ máy hợp đồng tạo ra, nên các hướng dẫn về nội dung được xác định và các thuật ngữ của chúng thường được tham chiếu trong Tiêu chuẩn Quân sự Hoa Kỳ hoặc các hình thức hướng dẫn thủ tục và hành chính khác của Bộ Quốc phòng Hoa Kỳ.', 'Mô tả mục dữ liệu là một tài liệu hoàn chỉnh xác định các mục dữ liệu bắt buộc đối với nhà thầu của Bộ Quốc phòng Hoa Kỳ. DID xác định cụ thể nội dung dữ liệu, định dạng và mục đích sử dụng dữ liệu với mục tiêu chính là đạt được các mục tiêu chuẩn hóa của Bộ Quốc phòng Hoa Kỳ.', NULL, NULL, NULL, 'publisher/avatar/PO39B4QAHIPDVL0RXIYF.jpg', 0),
(4362, 'DIN - Deutsches Institut Fur Normung E.V. (German National Standard)', 'DIN - Deutsches Institut Fur Normung E.V. (German National Standard)', 'Through its standards and handbooks, DIN facilitates the international exchange of goods and services and encourages cooperation in the realms of intellectual, scientific, technological, and economic activity. More than 12,000 standards address a wide range of topics.', 'Cơ quan Tiêu chuẩn Quốc gia Đức (Deutsches Institut für Normung), được viết tắt là DIN, là tổ chức tiêu chuẩn hóa quốc gia của Đức. Được thành lập vào năm 1917, DIN đã đóng góp quan trọng vào việc phát triển và thúc đẩy sự tiêu chuẩn hóa trong nền kinh tế Đức và cả thế giới. Tiêu chuẩn DIN đã trở thành một mô hình tiêu chuẩn quốc gia và quốc tế, với sự công nhận và áp dụng rộng rãi trong nhiều ngành công nghiệp.\n\nCơ quan Tiêu chuẩn Quốc gia Đức (DIN) chịu trách nhiệm xác định và phát triển các tiêu chuẩn trong nhiều lĩnh vực khác nhau, bao gồm công nghiệp, kỹ thuật, môi trường, y tế và nhiều lĩnh vực khác. \n\nCác tiêu chuẩn DIN đã có ảnh hưởng lớn đến các ngành công nghiệp và cả xã hội. Nhờ vào sự thống nhất và phù hợp của các tiêu chuẩn này, các doanh nghiệp có thể đảm bảo chất lượng sản phẩm và dịch vụ của mình, nâng cao sự tin cậy và độ tin cậy đối với khách hàng.\n\nĐối với ngành công nghiệp, tiêu chuẩn DIN giúp tạo ra một môi trường cạnh tranh lành mạnh, khuyến khích sự đổi mới và phát triển công nghệ. Chúng cũng đóng vai trò quan trọng trong việc bảo vệ môi trường và đảm bảo an toàn cho người lao động và người tiêu dùng.\n\nNgoài ra, tiêu chuẩn DIN còn có ảnh hưởng rộng rãi đến thương mại quốc tế. Với sự tham gia vào việc phát triển các tiêu chuẩn quốc tế, DIN đóng vai trò quan trọng trong việc tạo ra một môi trường thương mại công bằng và đồng nhất, giúp thúc đẩy sự phát triển kinh tế và hợp tác quốc tế.\n\nCơ quan Tiêu chuẩn Quốc gia Đức (DIN) đóng vai trò quan trọng trong việc xác định và phát triển các tiêu chuẩn quốc gia và quốc tế. Nhờ vào sự thống nhất và chất lượng của các tiêu chuẩn DIN, người tiêu dùng có thể tin tưởng vào chất lượng và an toàn của các sản phẩm và dịch vụ. Đồng thời, các tiêu chuẩn này còn đóng vai trò quan trọng trong việc thúc đẩy sự đổi mới, bảo vệ môi trường và xây dựng một môi trường thương mại công bằng và đồng nhất trên thế giới.', 'Cơ quan Tiêu chuẩn Quốc gia Đức (Deutsches Institut für Normung), được viết tắt là DIN, là tổ chức tiêu chuẩn hóa quốc gia của Đức. Được thành lập vào năm 1917, DIN đã đóng góp quan trọng vào việc phát triển và thúc đẩy sự tiêu chuẩn hóa trong nền kinh tế Đức và cả thế giới. Tiêu chuẩn DIN đã trở thành một mô hình tiêu chuẩn quốc gia và quốc tế, với sự công nhận và áp dụng rộng rãi trong nhiều ngành công nghiệp.', 'DIN,VG,LN,FDBR', 'DIN, DIN standards, Tiêu chuẩn quốc gia Đức, Tiêu chuẩn nước ngoài', NULL, 'publisher/avatar/96AATMFSIHQK8V3S4B1I.png', 0),
(4363, 'DNV - DNV', 'DNV - DNV', 'DNV is an independent assurance and risk management provider, operating in more than 100 countries. Through its broad experience and deep expertise, DNV advances safety and sustainable performance, sets industry standards, and inspires and invents solutions. Whether assessing a new ship design, qualifying technology for a floating wind farm, analysing sensor data from a gas pipeline or certifying a food company’s supply chain, DNV enables its customers and their stakeholders to manage technological and regulatory complexity with confidence. Driven by its purpose, to safeguard life, property, and the environment, DNV helps its customers seize opportunities and tackle the risks arising from global transformations. DNV is a trusted voice for many of the world’s most successful and forward-thinking companies. dnv.com\nDNV is the independent expert in assurance and risk management. Driven by our purpose, to safeguard life, property, and the environment, we empower our customers and their stakeholders with facts and reliable insights so that critical decisions can be made with confidence. As a trusted voice for many of the world’s most successful organizations, we use our knowledge to advance safety and performance, set industry benchmarks, and inspire and invent solutions to tackle global transformations.\n \nWe are the world’s leading classification society and a recognized advisor for the maritime industry. We deliver world-renowned testing, certification and technical advisory services to the energy value chain including renewables, oil and gas, and energy management. We are one of the world’s leading certification bodies, helping businesses assure the performance of their organizations, products, people, facilities and supply chains. \n \nWe are also a world-leading provider of digital solutions for managing risk and improving safety and asset performance for ships, pipelines, processing plants, offshore structures, electric grids, smart cities and more. Our open industry assurance platform Veracity, cyber security and software solutions support business-critical activities across many industries, including maritime, energy and healthcare.', 'DNV là nhà cung cấp dịch vụ quản lý rủi ro và đảm bảo độc lập, hoạt động tại hơn 100 quốc gia. Với kinh nghiệm rộng lớn và chuyên môn sâu, DNV thúc đẩy an toàn và hiệu suất bền vững, đặt ra các tiêu chuẩn trong ngành, đồng thời truyền cảm hứng và phát minh ra các giải pháp. Cho dù đánh giá thiết kế tàu mới, công nghệ đủ điều kiện cho trang trại điện gió nổi, phân tích dữ liệu cảm biến từ đường ống dẫn khí hay chứng nhận chuỗi cung ứng của công ty thực phẩm, DNV đều giúp khách hàng và các bên liên quan quản lý sự phức tạp về công nghệ và quy định một cách tự tin. Được thúc đẩy bởi mục đích bảo vệ tính mạng, tài sản và môi trường, DNV giúp khách hàng nắm bắt cơ hội và giải quyết các rủi ro phát sinh từ quá trình chuyển đổi toàn cầu. DNV là tiếng nói đáng tin cậy của nhiều công ty thành công và có tư duy tiến bộ nhất trên thế giới. dnv.com\nDNV là chuyên gia độc lập về quản lý rủi ro và đảm bảo. Được thúc đẩy bởi mục đích bảo vệ tính mạng, tài sản và môi trường, chúng tôi trao quyền cho khách hàng và các bên liên quan của họ bằng các sự kiện và hiểu biết đáng tin cậy để có thể đưa ra các quyết định quan trọng một cách tự tin. Là tiếng nói đáng tin cậy của nhiều tổ chức thành công nhất thế giới, chúng tôi sử dụng kiến ​​thức của mình để thúc đẩy an toàn và hiệu suất, thiết lập các chuẩn mực của ngành và truyền cảm hứng cũng như sáng tạo ra các giải pháp để giải quyết các chuyển đổi toàn cầu.\n\nChúng tôi là hiệp hội phân loại hàng đầu thế giới và là cố vấn được công nhận cho ngành hàng hải. Chúng tôi cung cấp các dịch vụ thử nghiệm, chứng nhận và tư vấn kỹ thuật nổi tiếng thế giới cho chuỗi giá trị năng lượng bao gồm năng lượng tái tạo, dầu khí và quản lý năng lượng. Chúng tôi là một trong những tổ chức chứng nhận hàng đầu thế giới, giúp các doanh nghiệp đảm bảo hiệu suất của tổ chức, sản phẩm, con người, cơ sở và chuỗi cung ứng của họ.\n\nChúng tôi cũng là nhà cung cấp hàng đầu thế giới về các giải pháp kỹ thuật số để quản lý rủi ro và cải thiện an toàn và hiệu suất tài sản cho tàu, đường ống, nhà máy chế biến, công trình ngoài khơi, lưới điện, thành phố thông minh, v.v. Nền tảng đảm bảo ngành mở Veracity, an ninh mạng và các giải pháp phần mềm của chúng tôi hỗ trợ các hoạt động quan trọng đối với doanh nghiệp trong nhiều ngành, bao gồm hàng hải, năng lượng và chăm sóc sức khỏe.', 'DNV là nhà cung cấp dịch vụ quản lý rủi ro và đảm bảo độc lập, hoạt động tại hơn 100 quốc gia. Với kinh nghiệm rộng lớn và chuyên môn sâu, DNV thúc đẩy an toàn và hiệu suất bền vững, đặt ra các tiêu chuẩn trong ngành, đồng thời truyền cảm hứng và phát minh ra các giải pháp.', NULL, NULL, NULL, 'publisher/avatar/35OI90AGRN4W5ON78JP9.jpg', 0),
(4364, 'DOD - Department of Defense', 'DOD - Department of Defense', 'Standardization documents are developed by the DOD and used for products, materials, and processes that have multiple applications to promote commonality and interoperability among the Military Departments and the Defense Agencies and between the United States and its allies, and to limit the variety of items in the military supply system.\nThe Department of Defense is America\'s largest government agency. With our military tracing its roots back to pre-Revolutionary times, the department has grown and evolved with our nation. Our mission is to provide the military forces needed to deter war and ensure our nation\'s security.', 'Các tài liệu chuẩn hóa được Bộ Quốc phòng phát triển và sử dụng cho các sản phẩm, vật liệu và quy trình có nhiều ứng dụng để thúc đẩy tính chung và khả năng tương tác giữa các Bộ Quân sự và các Cơ quan Quốc phòng và giữa Hoa Kỳ và các đồng minh, đồng thời hạn chế sự đa dạng của các mặt hàng trong hệ thống cung cấp quân sự.\nBộ Quốc phòng là cơ quan chính phủ lớn nhất của Hoa Kỳ. Với quân đội của chúng tôi có nguồn gốc từ thời tiền Cách mạng, bộ này đã phát triển và tiến hóa cùng với quốc gia của chúng tôi. Sứ mệnh của chúng tôi là cung cấp lực lượng quân sự cần thiết để ngăn chặn chiến tranh và đảm bảo an ninh quốc gia.', 'Các tài liệu chuẩn hóa được Bộ Quốc phòng phát triển và sử dụng cho các sản phẩm, vật liệu và quy trình có nhiều ứng dụng để thúc đẩy tính chung và khả năng tương tác giữa các Bộ Quân sự và các Cơ quan Quốc phòng và giữa Hoa Kỳ và các đồng minh, đồng thời hạn chế sự đa dạng của các mặt hàng trong hệ thống cung cấp quân sự.', NULL, NULL, NULL, 'publisher/avatar/O34C197FDN9GF2YVGYYZ.jpg', 0),
(4365, 'DOXPUB - Doxpub, Inc.', 'DOXPUB - Doxpub, Inc.', 'Doxpub creates document templates modeled after those of successful regulated companies to help businesses reduce the record-keeping costs of FDA compliance. In addition to saving time, money and effort, Doxpub customers have the advantage of learning how peer organizations manage fundamental industry issues.', 'Doxpub tạo ra các mẫu tài liệu theo mô hình của các công ty được quản lý thành công để giúp các doanh nghiệp giảm chi phí lưu giữ hồ sơ tuân thủ FDA. Ngoài việc tiết kiệm thời gian, tiền bạc và công sức, khách hàng của Doxpub còn có lợi thế là tìm hiểu cách các tổ chức ngang hàng quản lý các vấn đề cơ bản của ngành.', 'Doxpub creates document templates modeled after those of successful regulated companies to help businesses reduce the record-keeping costs of FDA compliance. In addition to saving time, money and effort, Doxpub customers have the advantage of learning how peer organizations manage fundamental industry issues.', NULL, NULL, NULL, 'publisher/avatar/7NJITEQFNYZDOFECW8C2.png', 0),
(4366, 'DVS - DEUTSCHER VERBAND FÜR SCHWEISSEN UND VERWANDTE VERFAHREN E.V.', 'DVS - DEUTSCHER VERBAND FÜR SCHWEISSEN UND VERWANDTE VERFAHREN E.V.', 'Partnership-based relationships with strong societies, interdisciplinary cooperation on a professional level and a competent team from the associated companies of the DVS Group – this is what has characterised DVS as a technical-scientific, non-profit society for years.\n\nTogether, we are committed to a high-performance industry in joining, cutting and coating technology. Together, we ensure qualification and certification in vocational training as well as recognised technical rules and standards. Together, we push forward innovations for joining technology.\n\nOur affiliated companies research, check and develop new ideas for the industry. They provide on-site training, give testing and laboratory situations a space or ensure a comprehensive range of technical and teaching media on the market.', 'Mối quan hệ đối tác với các cộng đồng vững mạnh, hợp tác liên ngành ở cấp độ chuyên nghiệp và một đội ngũ có năng lực từ các công ty liên kết của DVS Group – đây là những gì đã làm nên đặc điểm của DVS như một cộng đồng khoa học kỹ thuật, phi lợi nhuận trong nhiều năm.\n\nCùng nhau, chúng tôi cam kết xây dựng một ngành công nghiệp hiệu suất cao trong công nghệ ghép, cắt và phủ. Cùng nhau, chúng tôi đảm bảo trình độ và chứng chỉ trong đào tạo nghề cũng như các quy tắc và tiêu chuẩn kỹ thuật được công nhận. Cùng nhau, chúng tôi thúc đẩy các sáng kiến ​​về công nghệ ghép.\n\nCác công ty liên kết của chúng tôi nghiên cứu, kiểm tra và phát triển các ý tưởng mới cho ngành. Họ cung cấp đào tạo tại chỗ, tạo không gian cho các tình huống thử nghiệm và phòng thí nghiệm hoặc đảm bảo một loạt các phương tiện kỹ thuật và giảng dạy toàn diện trên thị trường.', 'Mối quan hệ đối tác với các cộng đồng vững mạnh, hợp tác liên ngành ở cấp độ chuyên nghiệp và một đội ngũ có năng lực từ các công ty liên kết của DVS Group – đây là những gì đã làm nên đặc điểm của DVS như một cộng đồng khoa học kỹ thuật, phi lợi nhuận trong nhiều năm.', NULL, NULL, NULL, 'publisher/avatar/7LW8BGU8V78UVNRT8NEH.jpg', 0),
(4367, 'ECIA - Electronic Components Industry Association', 'ECIA - Electronic Components Industry Association', 'The Electronic Components Industry Association (ECIA) is made up of the leading electronic component manufacturers, their manufacturer representatives and authorized distributors. ECIA members share a common goal of promoting and improving the business environment for the authorized sale of electronic components\nECIA provides resources and opportunities for members to improve their business performance while enhancing the industry’s overall capacity for growth and profitability. From driving critical conversations and process optimization to product authentication and industry advocacy, ECIA is your trusted source for support, insight and action.\nBringing together the talent and experience of a broad array of industry leaders and professionals representing all facets of the electronics components supply chain, ECIA is uniquely positioned to enable individual connection as well as industry-wide collaboration. As the supply chain becomes increasingly more complex, ECIA serves as a vital nexus for refinement and progress.\nExpansion and uncertainty seem to be the only true constants in the electronics industry today. In this dynamically shifting environment, reliable market intelligence is at a premium. Because ECIA’s members are the marketplace, we provide a level of visibility into the supply chain otherwise unavailable. From individual anecdotes gleaned from conversations at an ECIA event, to our exclusive market reports, we help keep you in the know.\nAs an organization made up of the leading electronic component manufacturers, their manufacturer representatives and authorized distributors, ECIA members share a common goal of promoting and improving the business environment for the authorized sale of electronic components to the end customer.\n To promote and improve the business environment for the authorized sale of electronic components by manufacturers, their distributors and independent sales representatives.\nElectronic components are industrial devices used to build electrical circuits, integral to the functioning of equipment such as computers, cell phones, automotive electronics, networking gear, and countless other products.  Virtually anything that plugs into the wall, runs on a battery or uses solar power is likely made up of electronic components.\nThe Electronic Components Industry is a global industry experiencing rapid growth due to the increased reliance on electronics in our lives and constant development of technology.\nOur industry is a nearly half trillion-dollar market employing over one million people.  Component manufacturers sell to equipment manufacturers either directly or through industrial distributors, and their sales forces are frequently augmented by independent manufacturer representatives.  Because of the sensitivity of many electronic applications and the value of the components, this industry has come under threat of counterfeit devices. The best guard against counterfeit components is for customers to buy only from trusted sources, meaning authorized distributors.\nThe Electronic Component Industry Association (ECIA) promotes the authorized supply chain for electronic components.\nThe infographics below were developed to provide an overview of the industry, the scope of careers and how ECIA connects its members.  Please feel free to use them in your efforts to promote the industry and attract potential employees!', 'Hiệp hội Công nghiệp Linh kiện Điện tử (ECIA) bao gồm các nhà sản xuất linh kiện điện tử hàng đầu, đại diện nhà sản xuất và nhà phân phối được ủy quyền. Các thành viên ECIA chia sẻ mục tiêu chung là thúc đẩy và cải thiện môi trường kinh doanh cho hoạt động bán linh kiện điện tử được ủy quyền\nECIA cung cấp các nguồn lực và cơ hội cho các thành viên để cải thiện hiệu suất kinh doanh của họ đồng thời nâng cao năng lực tăng trưởng và lợi nhuận chung của ngành. Từ việc thúc đẩy các cuộc trò chuyện quan trọng và tối ưu hóa quy trình đến xác thực sản phẩm và ủng hộ ngành, ECIA là nguồn hỗ trợ, hiểu biết và hành động đáng tin cậy của bạn.\nTập hợp tài năng và kinh nghiệm của nhiều nhà lãnh đạo và chuyên gia trong ngành đại diện cho mọi khía cạnh của chuỗi cung ứng linh kiện điện tử, ECIA có vị thế độc đáo để tạo điều kiện cho sự kết nối cá nhân cũng như sự hợp tác trên toàn ngành. Khi chuỗi cung ứng ngày càng trở nên phức tạp hơn, ECIA đóng vai trò là cầu nối quan trọng để tinh chỉnh và tiến bộ.\nSự mở rộng và sự không chắc chắn dường như là hằng số thực sự duy nhất trong ngành điện tử ngày nay. Trong môi trường thay đổi năng động này, thông tin thị trường đáng tin cậy là vô cùng quan trọng. Vì các thành viên của ECIA chính là thị trường, chúng tôi cung cấp mức độ hiển thị vào chuỗi cung ứng mà nếu không có thì không có. Từ những giai thoại cá nhân được thu thập từ các cuộc trò chuyện tại sự kiện ECIA, cho đến các báo cáo thị trường độc quyền của chúng tôi, chúng tôi giúp bạn luôn cập nhật thông tin.\nLà một tổ chức bao gồm các nhà sản xuất linh kiện điện tử hàng đầu, đại diện nhà sản xuất và nhà phân phối được ủy quyền của họ, các thành viên ECIA chia sẻ mục tiêu chung là thúc đẩy và cải thiện môi trường kinh doanh để bán linh kiện điện tử được ủy quyền cho khách hàng cuối.\nThúc đẩy và cải thiện môi trường kinh doanh để bán linh kiện điện tử được ủy quyền của các nhà sản xuất, nhà phân phối và đại diện bán hàng độc lập.\nLinh kiện điện tử là thiết bị công nghiệp được sử dụng để chế tạo mạch điện, là một phần không thể thiếu trong hoạt động của các thiết bị như máy tính, điện thoại di động, thiết bị điện tử ô tô, thiết bị mạng và vô số sản phẩm khác. Hầu như bất kỳ thứ gì cắm vào tường, chạy bằng pin hoặc sử dụng năng lượng mặt trời đều có khả năng được tạo thành từ các linh kiện điện tử.\nNgành công nghiệp linh kiện điện tử là một ngành công nghiệp toàn cầu đang có tốc độ tăng trưởng nhanh chóng do sự phụ thuộc ngày càng tăng vào thiết bị điện tử trong cuộc sống của chúng ta và sự phát triển không ngừng của công nghệ.\nNgành công nghiệp của chúng tôi là một thị trường trị giá gần nửa nghìn tỷ đô la, sử dụng hơn một triệu người. Các nhà sản xuất linh kiện bán cho các nhà sản xuất thiết bị trực tiếp hoặc thông qua các nhà phân phối công nghiệp và lực lượng bán hàng của họ thường được tăng cường bởi các đại diện nhà sản xuất độc lập. Do tính nhạy cảm của nhiều ứng dụng điện tử và giá trị của các thành phần, ngành công nghiệp này đã bị đe dọa bởi các thiết bị giả mạo. Biện pháp bảo vệ tốt nhất chống lại các thành phần giả mạo là khách hàng chỉ mua từ các nguồn đáng tin cậy, nghĩa là các nhà phân phối được ủy quyền.\nHiệp hội Công nghiệp Linh kiện Điện tử (ECIA) thúc đẩy chuỗi cung ứng được ủy quyền cho các linh kiện điện tử.\nCác thông tin đồ họa dưới đây được phát triển để cung cấp tổng quan về ngành công nghiệp, phạm vi nghề nghiệp và cách ECIA kết nối các thành viên của mình. Vui lòng sử dụng chúng trong nỗ lực thúc đẩy ngành công nghiệp và thu hút nhân viên tiềm năng của bạn!', 'Hiệp hội Công nghiệp Linh kiện Điện tử (ECIA) bao gồm các nhà sản xuất linh kiện điện tử hàng đầu, đại diện nhà sản xuất và nhà phân phối được ủy quyền. Các thành viên ECIA chia sẻ mục tiêu chung là thúc đẩy và cải thiện môi trường kinh doanh cho hoạt động bán linh kiện điện tử được ủy quyền', NULL, NULL, NULL, 'publisher/avatar/IZBC5HKA43BQMKV35UR7.jpg', 0),
(4368, 'EEC - European Union Directives', 'EEC - European Union Directives', 'The EU is one of the largest publishers of online information in the world and the hunt for information can seem complex. Every day a huge range of information goes online, including legislation, statistics, press releases, policy reports and more.\nA directive is a legal act of the European Union that requires member states to achieve particular goals without dictating how the member states achieve those goals. A directive\'s goals have to be made the goals of one or more new or changed national laws by the member states before this legislation applies to individuals residing in the member states. Directives normally leave member states with a certain amount of leeway as to the exact rules to be adopted. Directives can be adopted by means of a variety of legislative procedures depending on their subject matter.\nThe text of a draft directive (if subject to the co-decision process, as contentious matters usually are) is prepared by the Commission after consultation with its own and national experts. The draft is presented to the Parliament and the Council—composed of relevant ministers of member governments, initially for evaluation and comment and then subsequently for approval or rejection.\nThere are justifications for using a directive rather than a regulation: (i) it complies with the EU\'s desire for \"subsidiarity\"; (ii) it acknowledges that different member States have different legal systems, legal traditions and legal processes; and (iii) each Member State has leeway to choose its own statutory wording, rather than accepting the Brussels\' official \"Eurospeak\" terminology.\nFor example, while EU Directive 2009/20/EC (which simply requires all vessels visiting EU ports to have P&I cover) could have been a regulation (without requiring member states to implement the directive), the desire for subsidiarity was paramount, so a directive was the chosen vehicle.', 'EU là một trong những đơn vị xuất bản thông tin trực tuyến lớn nhất thế giới và việc tìm kiếm thông tin có vẻ phức tạp. Mỗi ngày, một lượng lớn thông tin được đưa lên mạng, bao gồm luật pháp, số liệu thống kê, thông cáo báo chí, báo cáo chính sách, v.v.\nChỉ thị là một đạo luật của Liên minh châu Âu yêu cầu các quốc gia thành viên đạt được các mục tiêu cụ thể mà không chỉ định cách thức các quốc gia thành viên đạt được các mục tiêu đó. Các mục tiêu của chỉ thị phải được thực hiện theo mục tiêu của một hoặc nhiều luật quốc gia mới hoặc đã thay đổi do các quốc gia thành viên ban hành trước khi luật này áp dụng cho các cá nhân cư trú tại các quốc gia thành viên. Các chỉ thị thường để lại cho các quốc gia thành viên một lượng tự do nhất định về các quy tắc chính xác cần thông qua. Các chỉ thị có thể được thông qua thông qua nhiều thủ tục lập pháp khác nhau tùy thuộc vào nội dung của chúng.\nVăn bản của dự thảo chỉ thị (nếu phải tuân theo quy trình đồng quyết định, vì các vấn đề gây tranh cãi thường diễn ra) được Ủy ban chuẩn bị sau khi tham khảo ý kiến ​​của các chuyên gia của Ủy ban và quốc gia. Dự thảo được trình lên Nghị viện và Hội đồng, bao gồm các bộ trưởng có liên quan của các chính phủ thành viên, ban đầu để đánh giá và bình luận, sau đó là để phê duyệt hoặc bác bỏ.\nCó những lý do chính đáng để sử dụng chỉ thị thay vì quy định: (i) nó tuân thủ mong muốn của EU về \"tính bổ trợ\"; (ii) nó thừa nhận rằng các quốc gia thành viên khác nhau có hệ thống pháp lý, truyền thống pháp lý và quy trình pháp lý khác nhau; và (iii) mỗi quốc gia thành viên có quyền tự do lựa chọn cách diễn đạt theo luật định của riêng mình, thay vì chấp nhận thuật ngữ \"Eurospeak\" chính thức của Brussels.\nVí dụ, trong khi Chỉ thị EU 2009/20/EC (chỉ yêu cầu tất cả các tàu cập cảng EU phải có bảo hiểm P&I) có thể là một quy định (mà không yêu cầu các quốc gia thành viên phải thực hiện chỉ thị), thì mong muốn về tính bổ trợ là tối quan trọng, vì vậy chỉ thị là phương tiện được lựa chọn.', 'Chỉ thị là một đạo luật của Liên minh châu Âu yêu cầu các quốc gia thành viên đạt được các mục tiêu cụ thể mà không chỉ định cách thức các quốc gia thành viên đạt được các mục tiêu đó. Các mục tiêu của chỉ thị phải được thực hiện theo mục tiêu của một hoặc nhiều luật quốc gia mới hoặc đã thay đổi do các quốc gia thành viên ban hành trước khi luật này áp dụng cho các cá nhân cư trú tại các quốc gia thành viên. Các chỉ thị thường để lại cho các quốc gia thành viên một lượng tự do nhất định về các quy tắc chính xác cần thông qua. Các chỉ thị có thể được thông qua thông qua nhiều thủ tục lập pháp khác nhau tùy thuộc vào nội dung của chúng.', NULL, NULL, NULL, 'publisher/avatar/W5PA2QEM2ZW8T8XACHRV.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4369, 'EEMUA - Engineering Equipment and Materials Users Association', 'EEMUA - Engineering Equipment and Materials Users Association', 'The Engineering Equipment & Materials Users Association is a non-profit international membership organisation that exists to serve its member companies. EEMUA aims to improve the safety, environmental and operating performance of industrial facilities in the most cost-effective way, pursuing and promoting leadership in industrial asset management by sharing engineering experiences and expertise, and by the active, enlightened promotion of the distinct interests of users of engineering products.\nEEMUA was founded in 1949 by major industrial players, with a vision of working together to establish standards in areas such as equipment and materials selection and specification, and engineering plant construction, and so drive good practice wider into industry.\nEEMUA membership now spans many sectors including companies that manage process and power plants, utilities, offshore platforms, storage terminals and other industrial facilities throughout the world. The Association\'s technical activities cover the full scope of industrial asset management as an internationally recognised source of expertise and information for the engineering industry. \n EEMUA plays a pivotal role in ensuring members’ physical assets and user requirements are in the best shape to contribute significantly to their companies. As a result, EEMUA focusses its efforts on the most critical issues.\nEEMUA\'s aims meet a wide range of needs for the owners and operators of industrial assets across a range of sectors. From helping ensure a competent workforce to influencing standards and regulations abroad, the association focuses closely on maximising value for members.\nMember companies own or operate many upper-tier COMAH (Control of Major Accident Hazards) and/or SEVESO establishments. Through knowledge sharing, EEMUA helps its members meet legal compliance requirements and challenge unreasonable expectations.', 'Hiệp hội Người sử dụng Thiết bị & Vật liệu Kỹ thuật là một tổ chức thành viên quốc tế phi lợi nhuận, tồn tại để phục vụ các công ty thành viên. EEMUA hướng đến mục tiêu cải thiện hiệu suất an toàn, môi trường và hoạt động của các cơ sở công nghiệp theo cách tiết kiệm chi phí nhất, theo đuổi và thúc đẩy vai trò lãnh đạo trong quản lý tài sản công nghiệp bằng cách chia sẻ kinh nghiệm và chuyên môn kỹ thuật, và bằng cách thúc đẩy tích cực, sáng suốt các lợi ích riêng biệt của người sử dụng các sản phẩm kỹ thuật.\nEEMUA được thành lập vào năm 1949 bởi các công ty công nghiệp lớn, với tầm nhìn hợp tác để thiết lập các tiêu chuẩn trong các lĩnh vực như lựa chọn và chỉ định thiết bị và vật liệu, và xây dựng nhà máy kỹ thuật, và do đó thúc đẩy thực hành tốt rộng rãi hơn vào ngành.\nHiện nay, tư cách thành viên của EEMUA trải rộng trên nhiều lĩnh vực bao gồm các công ty quản lý nhà máy điện và quy trình, tiện ích, giàn khoan ngoài khơi, nhà ga lưu trữ và các cơ sở công nghiệp khác trên toàn thế giới. Các hoạt động kỹ thuật của Hiệp hội bao gồm toàn bộ phạm vi quản lý tài sản công nghiệp như một nguồn thông tin và chuyên môn được công nhận trên toàn thế giới cho ngành kỹ thuật.\nEEMUA đóng vai trò quan trọng trong việc đảm bảo tài sản vật chất và yêu cầu của người dùng của các thành viên ở trạng thái tốt nhất để đóng góp đáng kể cho công ty của họ. Do đó, EEMUA tập trung nỗ lực vào các vấn đề quan trọng nhất.\nMục tiêu của EEMUA đáp ứng nhiều nhu cầu khác nhau của chủ sở hữu và người vận hành tài sản công nghiệp trên nhiều lĩnh vực. Từ việc giúp đảm bảo lực lượng lao động có năng lực đến việc tác động đến các tiêu chuẩn và quy định ở nước ngoài, hiệp hội tập trung chặt chẽ vào việc tối đa hóa giá trị cho các thành viên.\nCác công ty thành viên sở hữu hoặc vận hành nhiều cơ sở COMAH (Kiểm soát các mối nguy tai nạn lớn) và/hoặc SEVESO cấp cao. Thông qua việc chia sẻ kiến ​​thức, EEMUA giúp các thành viên của mình đáp ứng các yêu cầu tuân thủ pháp luật và thách thức những kỳ vọng vô lý.', 'Hiệp hội Người sử dụng Thiết bị & Vật liệu Kỹ thuật là một tổ chức thành viên quốc tế phi lợi nhuận, tồn tại để phục vụ các công ty thành viên. EEMUA hướng đến mục tiêu cải thiện hiệu suất an toàn, môi trường và hoạt động của các cơ sở công nghiệp theo cách tiết kiệm chi phí nhất, theo đuổi và thúc đẩy vai trò lãnh đạo trong quản lý tài sản công nghiệp bằng cách chia sẻ kinh nghiệm và chuyên môn kỹ thuật, và bằng cách thúc đẩy tích cực, sáng suốt các lợi ích riêng biệt của người sử dụng các sản phẩm kỹ thuật.', NULL, NULL, NULL, 'publisher/avatar/HKZBKTOBYVR1NSLC8GRS.jpg', 0),
(4370, 'ESD - EOS/ESD Association, Inc.', 'ESD - EOS/ESD Association, Inc.', 'Founded in 1982, EOS/ESD Association, Inc. is a professional voluntary association dedicated to advancing the theory and practice of electrostatic discharge (ESD) avoidance. From fewer than 100 members, EOS/ESD Association has grown to more than 2,000 members throughout the world. From an initial emphasis of ESD on electronic components, EOS/ESD Association has broadened its horizons to include areas such as textiles, plastics, web processing, cleanrooms, and graphic arts. To meet the needs of a continually changing environment, EOS/ESD Association is chartered to expand ESD awareness through standards, development, education programs, local chapters, publications, tutorials, certification and symposia.\nEOS/ESD Association, Inc. began with fewer than 100 members, and has now grown to over 15,869 members and volunteers throughout the world. Initially focusing on ESD on electronic components, the Association has broadened its horizons to include areas such as textiles, plastics, web processing, cleanrooms, and graphic arts. To meet the needs of a continually changing environment, EOS/ESD Association, Inc. is chartered to expand ESD awareness through standards, development, education programs, local chapters, publications, tutorials, certification, and symposia. It is the only organization accredited by the American National Standards Institute (ANSI) to write and produce standards on electrostatics.\nEOS/ESD Association, Inc. is the only organization accredited by ANSI to write and produce standards on electrostatics. Our organization has published over seventy documents covering electrical overstress and electrostatic discharge in the electronics environment. These include standards, ESD standard test methods, ESD standard practices, technical reports, and informational advisory documents.', 'Được thành lập vào năm 1982, Hiệp hội EOS/ESD, Inc. là một hiệp hội tình nguyện chuyên nghiệp dành riêng cho việc thúc đẩy lý thuyết và thực hành về tránh phóng tĩnh điện (ESD). Từ số lượng thành viên ít hơn 100, Hiệp hội EOS/ESD đã phát triển lên hơn 2.000 thành viên trên toàn thế giới. Từ việc ban đầu tập trung vào ESD trên các linh kiện điện tử, Hiệp hội EOS/ESD đã mở rộng phạm vi hoạt động của mình để bao gồm các lĩnh vực như dệt may, nhựa, xử lý web, phòng sạch và đồ họa. Để đáp ứng nhu cầu của một môi trường liên tục thay đổi, Hiệp hội EOS/ESD được cấp phép để mở rộng nhận thức về ESD thông qua các tiêu chuẩn, phát triển, chương trình giáo dục, chi nhánh địa phương, ấn phẩm, hướng dẫn, chứng nhận và hội thảo chuyên đề.\nHiệp hội EOS/ESD, Inc. bắt đầu với số lượng thành viên ít hơn 100 và hiện đã phát triển lên hơn 15.869 thành viên và tình nguyện viên trên toàn thế giới. Ban đầu tập trung vào ESD trên các linh kiện điện tử, Hiệp hội đã mở rộng phạm vi hoạt động của mình để bao gồm các lĩnh vực như dệt may, nhựa, xử lý web, phòng sạch và đồ họa. Để đáp ứng nhu cầu của một môi trường liên tục thay đổi, EOS/ESD Association, Inc. được cấp phép để mở rộng nhận thức về ESD thông qua các tiêu chuẩn, phát triển, chương trình giáo dục, chi nhánh địa phương, ấn phẩm, hướng dẫn, chứng nhận và hội thảo. Đây là tổ chức duy nhất được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận để biên soạn và ban hành các tiêu chuẩn về tĩnh điện.\nEOS/ESD Association, Inc. là tổ chức duy nhất được ANSI công nhận để biên soạn và ban hành các tiêu chuẩn về tĩnh điện. Tổ chức của chúng tôi đã công bố hơn bảy mươi tài liệu về ứng suất điện quá mức và phóng tĩnh điện trong môi trường điện tử. Các tài liệu này bao gồm các tiêu chuẩn, phương pháp thử nghiệm tiêu chuẩn ESD, thông lệ tiêu chuẩn ESD, báo cáo kỹ thuật và tài liệu tư vấn thông tin.', 'Được thành lập vào năm 1982, Hiệp hội EOS/ESD, Inc. là một hiệp hội tình nguyện chuyên nghiệp dành riêng cho việc thúc đẩy lý thuyết và thực hành về tránh phóng tĩnh điện (ESD).', NULL, NULL, NULL, 'publisher/avatar/9JULJI4LLN0G61ZPDW3U.jpg', 0),
(4371, 'ETSI - European Telecommunications Standards Institute', 'ETSI - European Telecommunications Standards Institute', 'Representing members from 54 countries, ETSI promotes worldwide standardization in telecommunications, broadcasting and information technology. The work of ETSI is closely aligned with the market needs of network operators, manufacturers, service providers, research institutions, and end users.', 'ETSI (European Telecommunications Standards Institute) là tổ chức tiêu chuẩn viễn thông Châu Âu. ETSI được thành lập vào năm 1988 và có trụ sở tại Sophia Antipolis, Pháp. Nhiệm vụ chính của ETSI là phát triển và quản lý các tiêu chuẩn kỹ thuật cho ngành viễn thông và công nghệ thông tin.\n\nETSI chịu trách nhiệm xây dựng và phát triển các tiêu chuẩn kỹ thuật cho các công nghệ viễn thông khác nhau, bao gồm mạng di động, mạng cố định, mạng không dây, truyền dẫn, giao thức mạng, bảo mật thông tin, chuẩn hóa hình thức và giao diện người dùng. Các tiêu chuẩn của ETSI đảm bảo sự tương thích và tính tương đồng giữa các thiết bị và hệ thống viễn thông khác nhau, cho phép các công nghệ và dịch vụ được phát triển và triển khai một cách hiệu quả trên toàn cầu.\n\nETSI cũng đóng vai trò quan trọng trong việc hình thành chính sách và quy định viễn thông ở Châu Âu thông qua việc hợp tác với các tổ chức và cơ quan khác như Liên minh Châu Âu về Viễn thông (EUROCAE), Liên minh Châu Âu về Tiêu chuẩn Hàng không (EUROCAE), và Viện Tiêu chuẩn Hàng không Quốc tế (RTCA).', 'ETSI là tổ chức tiêu chuẩn viễn thông Châu Âu. ETSI được thành lập vào năm 1988 và có trụ sở tại Sophia Antipolis, Pháp. Nhiệm vụ chính của ETSI là phát triển và quản lý các tiêu chuẩn kỹ thuật cho ngành viễn thông và công nghệ thông tin.', 'ETSI,CEN/CLC/ETSI/TR,ETSITS,ETSITR,ETSIEG,ETSIES,ETSISR,ETSIGS', 'ETSI, Tiêu chuẩn Viễn thông Châu Âu ETSI, European Telecommunications Standards Institute ETSI, Viễn thông', NULL, 'publisher/avatar/TVONHLDBL69AYTPUQSAI.jpg', 0),
(4372, 'FCI - Fluid Controls Institute', 'FCI - Fluid Controls Institute', 'FCI is an association of manufacturers of equipment for fluid (liquid or gas) control and conditioning. The institute is organized into product-specific sections that address issues relevant to particular products and/or technologies. These include regulators, secondary pressure drainers, control valves, pipeline strainers, solenoid valves, instruments, steam traps, and safety and relief valves.\nThe Fluid Controls Institute (FCI) is a trade association of manufacturers of fluid control and conditioning equipment. FCI focuses on technical issues and provides standards and educational documents that assist manufacturers and users of scope products.\nFCI is governed by a Board of Directors. Many of FCI’s activities are carried out in its separate sections, which are categorized by product scope. Individual member companies may affiliate with one or more of these sections, depending upon their product lines.', 'FCI là hiệp hội các nhà sản xuất thiết bị kiểm soát và điều hòa chất lỏng (chất lỏng hoặc khí). Viện được tổ chức thành các bộ phận sản phẩm cụ thể giải quyết các vấn đề liên quan đến các sản phẩm và/hoặc công nghệ cụ thể. Bao gồm bộ điều chỉnh, bộ xả áp suất thứ cấp, van điều khiển, bộ lọc đường ống, van điện từ, dụng cụ, bẫy hơi và van an toàn và van xả.\nViện Kiểm soát Chất lỏng (FCI) là hiệp hội thương mại của các nhà sản xuất thiết bị kiểm soát và điều hòa chất lỏng. FCI tập trung vào các vấn đề kỹ thuật và cung cấp các tiêu chuẩn và tài liệu giáo dục hỗ trợ các nhà sản xuất và người dùng các sản phẩm trong phạm vi.\nFCI được quản lý bởi Hội đồng quản trị. Nhiều hoạt động của FCI được thực hiện trong các bộ phận riêng biệt, được phân loại theo phạm vi sản phẩm. Các công ty thành viên riêng lẻ có thể liên kết với một hoặc nhiều bộ phận này, tùy thuộc vào dòng sản phẩm của họ.', 'FCI là hiệp hội các nhà sản xuất thiết bị kiểm soát và điều hòa chất lỏng (chất lỏng hoặc khí). Viện được tổ chức thành các bộ phận sản phẩm cụ thể giải quyết các vấn đề liên quan đến các sản phẩm và/hoặc công nghệ cụ thể. Bao gồm bộ điều chỉnh, bộ xả áp suất thứ cấp, van điều khiển, bộ lọc đường ống, van điện từ, dụng cụ, bẫy hơi và van an toàn và van xả.', NULL, NULL, NULL, 'publisher/avatar/ZJAK5N7158002XB97Z9R.jpg', 0),
(4373, 'FED - Federal Specifications and Standards', 'FED - Federal Specifications and Standards', 'Cut hours of search time down to minutes when you order Mil Specs at Techstreet. Get easy checkout, immediate download and free email alerts when changes and reactivations are issued. Online orders even earn Techpoint Rewards! For enterprise access, a web-based subscription serves end-users with automatic updates and desktop tools that help organize and track documents. Get just the sections you need or the entire Mil database. Our Web 2.0 interface is fast and easy to use. Perfect for every department . from research and design to purchasing, bidding and logistics.', 'Giảm hàng giờ tìm kiếm xuống còn vài phút khi bạn đặt hàng Mil Specs tại Techstreet. Nhận thanh toán dễ dàng, tải xuống ngay lập tức và cảnh báo qua email miễn phí khi có thay đổi và kích hoạt lại. Đơn hàng trực tuyến thậm chí còn kiếm được Techpoint Rewards! Đối với quyền truy cập doanh nghiệp, đăng ký dựa trên web phục vụ người dùng cuối với các bản cập nhật tự động và các công cụ trên máy tính để bàn giúp sắp xếp và theo dõi tài liệu. Chỉ nhận các phần bạn cần hoặc toàn bộ cơ sở dữ liệu Mil. Giao diện Web 2.0 của chúng tôi nhanh chóng và dễ sử dụng. Hoàn hảo cho mọi bộ phận . từ nghiên cứu và thiết kế đến mua sắm, đấu thầu và hậu cần.', 'Giảm hàng giờ tìm kiếm xuống còn vài phút khi bạn đặt hàng Mil Specs tại Techstreet. Nhận thanh toán dễ dàng, tải xuống ngay lập tức và cảnh báo qua email miễn phí khi có thay đổi và kích hoạt lại. Đơn hàng trực tuyến thậm chí còn kiếm được Techpoint Rewards! Đối với quyền truy cập doanh nghiệp, đăng ký dựa trên web phục vụ người dùng cuối với các bản cập nhật tự động và các công cụ trên máy tính để bàn giúp sắp xếp và theo dõi tài liệu. Chỉ nhận các phần bạn cần hoặc toàn bộ cơ sở dữ liệu Mil. Giao diện Web 2.0 của chúng tôi nhanh chóng và dễ sử dụng. Hoàn hảo cho mọi bộ phận . từ nghiên cứu và thiết kế đến mua sắm, đấu thầu và hậu cần.', NULL, NULL, NULL, 'publisher/avatar/E3K7WPUM6BA09XNNC57P.jpg', 0),
(4374, 'FM Approvals - FM Approvals', 'FM Approvals - FM Approvals', 'The Fiberglass Institute is a non-profit risk mitigation organization providing education, certification, service and membership programs along with supporting publications for industry. These resources help people like you eliminate premature fiberglass chemical process equipment failure risks resulting in longer equipment life, reduced cost and hardship prevention. Since 2003, FRPI programs have filled voids and become acclaimed as best practices by many.\nFM Approvals continues to test and certify key products related to property loss prevention. Our dedication to innovation over the years has resulted in numerous technical advancements, including low smoke generation wall panels, clean room materials, suppression mode sprinkler protection and water mist systems.', 'Viện Sợi thủy tinh là một tổ chức giảm thiểu rủi ro phi lợi nhuận cung cấp các chương trình giáo dục, chứng nhận, dịch vụ và thành viên cùng với các ấn phẩm hỗ trợ cho ngành. Các nguồn lực này giúp những người như bạn loại bỏ các rủi ro hỏng hóc thiết bị xử lý hóa chất sợi thủy tinh sớm dẫn đến tuổi thọ thiết bị dài hơn, giảm chi phí và ngăn ngừa khó khăn. Kể từ năm 2003, các chương trình FRPI đã lấp đầy khoảng trống và được nhiều người ca ngợi là phương pháp hay nhất.\nFM Approvals tiếp tục thử nghiệm và chứng nhận các sản phẩm chính liên quan đến phòng ngừa mất mát tài sản. Sự tận tâm của chúng tôi đối với sự đổi mới trong nhiều năm đã mang lại nhiều tiến bộ kỹ thuật, bao gồm các tấm tường tạo ra ít khói, vật liệu phòng sạch, chế độ bảo vệ phun nước và hệ thống phun sương.', 'Viện Sợi thủy tinh là một tổ chức giảm thiểu rủi ro phi lợi nhuận cung cấp các chương trình giáo dục, chứng nhận, dịch vụ và thành viên cùng với các ấn phẩm hỗ trợ cho ngành. Các nguồn lực này giúp những người như bạn loại bỏ các rủi ro hỏng hóc thiết bị xử lý hóa chất sợi thủy tinh sớm dẫn đến tuổi thọ thiết bị dài hơn, giảm chi phí và ngăn ngừa khó khăn. Kể từ năm 2003, các chương trình FRPI đã lấp đầy khoảng trống và được nhiều người ca ngợi là phương pháp hay nhất.', NULL, NULL, '13.220*13.320*29.260*91.060*91.100', 'publisher/avatar/4R5MHOD8BX7434YPMN2S.jpg', 0),
(4375, 'FRPI - Fiberglass Reinforced Plastics Institute, Inc.', 'FRPI - Fiberglass Reinforced Plastics Institute, Inc.', 'The Fiberglass Institute is a non-profit risk mitigation organization providing education, certification, service and membership programs along with supporting publications for industry. These resources help people like you eliminate premature fiberglass chemical process equipment failure risks resulting in longer equipment life, reduced cost and hardship prevention. Since 2003, FRPI programs have filled voids and become acclaimed as best practices by many.', 'Viện Sợi thủy tinh là một tổ chức phi lợi nhuận giảm thiểu rủi ro cung cấp các chương trình giáo dục, chứng nhận, dịch vụ và thành viên cùng với các ấn phẩm hỗ trợ cho ngành công nghiệp. Các nguồn lực này giúp những người như bạn loại bỏ các rủi ro hỏng hóc thiết bị quy trình hóa học sợi thủy tinh sớm dẫn đến tuổi thọ thiết bị dài hơn, giảm chi phí và ngăn ngừa khó khăn. Từ năm 2003, các chương trình FRPI đã lấp đầy khoảng trống và được nhiều người ca ngợi là các thông lệ tốt nhất.', 'Viện Sợi thủy tinh là một tổ chức phi lợi nhuận giảm thiểu rủi ro cung cấp các chương trình giáo dục, chứng nhận, dịch vụ và thành viên cùng với các ấn phẩm hỗ trợ cho ngành công nghiệp. Các nguồn lực này giúp những người như bạn loại bỏ các rủi ro hỏng hóc thiết bị quy trình hóa học sợi thủy tinh sớm dẫn đến tuổi thọ thiết bị dài hơn, giảm chi phí và ngăn ngừa khó khăn. Từ năm 2003, các chương trình FRPI đã lấp đầy khoảng trống và được nhiều người ca ngợi là các thông lệ tốt nhất.', NULL, NULL, NULL, 'publisher/avatar/9IN8U4132TC7OE4FMKF2.jpg', 0),
(4376, 'GMW - General Motors Worldwide', 'GMW - General Motors Worldwide', 'GMW is an abbreviation for General Motors worldwide (General Motors Worldwide). General Motors (GM) is a leading company in the automotive industry worldwide, producing cars and trucks with brands such as Buick, Cadillac, Chevrolet and GMC.', 'GMW là viết tắt của General Motors trên toàn thế giới (General Motors Worldwide). General Motors (GM) là một công ty hàng đầu trong ngành công nghiệp ô tô trên toàn thế giới, sản xuất ô tô và xe tải với các thương hiệu như Buick, Cadillac, Chevrolet và GMC.', 'GMW là viết tắt của General Motors trên toàn thế giới (General Motors Worldwide). General Motors (GM) là một công ty hàng đầu trong ngành công nghiệp ô tô trên toàn thế giới, sản xuất ô tô và xe tải với các thương hiệu như Buick, Cadillac, Chevrolet và GMC.', NULL, NULL, NULL, NULL, 0),
(4377, 'GPA - GPA Midstream Association', 'GPA - GPA Midstream Association', 'Formerly the Gas Processor\'s Association, GPA serves the midstream energy industry by providing local, regional and global forums for standards development, industry research, education and improvements in operational safety. Publications include standards and methods for analysis, measurement and sampling of natural gas liquids.\nShaping the U.S. midstream energy sector since 1921, GPA Midstream sets standards for natural gas liquids; develops simple and reproducible test methods to define the industry’s raw materials and products; manages a worldwide cooperative research program; provides a voice for our industry on Capitol Hill; and is the go-to resource for technical reports and publications. The annual GPA Midstream Convention is the premiere meeting place for midstream professionals from around the globe.\nGPA Midstream Association’s mission is to responsibly serve and represent the midstream energy industry through collaborative expertise, safety and advocacy from its member companies and staff, focused on sustainability, to the benefit of all.\nGPA Midstream is managed by staff  located at our headquarters in Tulsa, Okla., as well as in Washington, D.C. and Houston. Our board of directors is responsible for the association\'s deliverables to the industry. The board consists of member company representatives from the industry’s top natural gas liquids producers, along with representatives from small- and medium-sized midstream companies.\nMore than a thousand volunteers from member companies worldwide are engaged in GPA Midstream efforts. The volunteer support shows the industry\'s commitment to the organization and to safety, efficiency and continuous improvement.', 'Trước đây là Hiệp hội chế biến khí, GPA phục vụ ngành năng lượng trung gian bằng cách cung cấp các diễn đàn địa phương, khu vực và toàn cầu để phát triển tiêu chuẩn, nghiên cứu ngành, giáo dục và cải thiện an toàn vận hành. Các ấn phẩm bao gồm các tiêu chuẩn và phương pháp phân tích, đo lường và lấy mẫu chất lỏng khí tự nhiên.\nĐịnh hình ngành năng lượng trung gian của Hoa Kỳ kể từ năm 1921, GPA Midstream đặt ra các tiêu chuẩn cho chất lỏng khí tự nhiên; phát triển các phương pháp thử nghiệm đơn giản và có thể tái tạo để xác định nguyên liệu thô và sản phẩm của ngành; quản lý chương trình nghiên cứu hợp tác trên toàn thế giới; đưa ra tiếng nói cho ngành của chúng tôi tại Đồi Capitol; và là nguồn thông tin đáng tin cậy cho các báo cáo kỹ thuật và ấn phẩm. Hội nghị GPA Midstream hàng năm là nơi gặp gỡ hàng đầu cho các chuyên gia trung gian từ khắp nơi trên thế giới.\nSứ mệnh của Hiệp hội GPA Midstream là phục vụ và đại diện có trách nhiệm cho ngành năng lượng trung gian thông qua chuyên môn hợp tác, an toàn và vận động từ các công ty thành viên và nhân viên, tập trung vào tính bền vững, vì lợi ích của tất cả mọi người.\nGPA Midstream được quản lý bởi đội ngũ nhân viên tại trụ sở chính của chúng tôi ở Tulsa, Okla., cũng như tại Washington, D.C. và Houston. Hội đồng quản trị của chúng tôi chịu trách nhiệm về các mục tiêu của hiệp hội đối với ngành. Hội đồng bao gồm các đại diện công ty thành viên từ các nhà sản xuất chất lỏng khí tự nhiên hàng đầu của ngành, cùng với các đại diện từ các công ty trung gian vừa và nhỏ.\nHơn một nghìn tình nguyện viên từ các công ty thành viên trên toàn thế giới đang tham gia vào các nỗ lực của GPA Midstream. Sự hỗ trợ của tình nguyện viên cho thấy cam kết của ngành đối với tổ chức và đối với sự an toàn, hiệu quả và cải tiến liên tục.', 'Trước đây là Hiệp hội chế biến khí, GPA phục vụ ngành năng lượng trung gian bằng cách cung cấp các diễn đàn địa phương, khu vực và toàn cầu để phát triển tiêu chuẩn, nghiên cứu ngành, giáo dục và cải thiện an toàn vận hành. Các ấn phẩm bao gồm các tiêu chuẩn và phương pháp phân tích, đo lường và lấy mẫu chất lỏng khí tự nhiên.', NULL, NULL, NULL, 'publisher/avatar/SYS2BJR53ZOOLMLHPZCI.jpg', 0),
(4378, 'HEI - Heat Exchange Institute', 'HEI - Heat Exchange Institute', 'The Heat Exchange Institute (HEI) is a non-profit trade association committed to the technical advancement, promotion, and understanding of a broad range of utility and industrial-scale heat exchange and vacuum apparatus.\n\nHEI concentrates its efforts on the manufacturing and engineering aspects of air cooled condensers, steam surface condensers, closed feedwater heaters, shell and tube heat exchangers, plate heat exchangers, liquid ring vacuum pumps, steam jet ejectors and deaerators.\n\nThe primary purpose of HEI is to develop and publish standards which advance the technology, increase the efficiency, and promote the use of heat exchange and vacuum apparatus.\n\nThis objective is accomplished through technology-specific committees operating under the authority of the Institute\'s seven Sections:\n\nAir Cooled Condenser\nSteam Surface Condenser\nClosed Feedwater Heater\nShell & Tube Heat Exchangers\nPlate Heat Exchangers\nVacuum Technology\nDeaerator\nEach of these sections sponsors a technical committee which is charged with developing and revising standards specific to its range of products. \n\nEach technical committee meets at least twice a year, with each section member designating an engineer as its representative on the Technical Committee; ongoing communication among committee members assures that the standards are based on the latest available technology.\n\nSince its founding over 79 years ago, the Institute has earned international recognition as the leading authority on the technologies for heat exchange and vacuum apparatus. Institute standards are used throughout the world for the design, manufacture and operation of heat exchange and vacuum equipment.\n\nHEI has expanded its efforts to share the latest technology by sponsoring workshops and publishing articles for users of heat exchange and vacuum equipment.', 'Viện Trao đổi Nhiệt (HEI) là một hiệp hội thương mại phi lợi nhuận cam kết thúc đẩy, quảng bá và hiểu biết về kỹ thuật trong nhiều loại thiết bị trao đổi nhiệt và chân không quy mô công nghiệp và tiện ích.\n\nHEI tập trung nỗ lực vào các khía cạnh sản xuất và kỹ thuật của bộ ngưng tụ làm mát bằng không khí, bộ ngưng tụ bề mặt hơi nước, bộ gia nhiệt nước cấp kín, bộ trao đổi nhiệt vỏ và ống, bộ trao đổi nhiệt tấm, bơm chân không vòng chất lỏng, bộ phun hơi nước và bộ khử khí.\n\nMục đích chính của HEI là phát triển và công bố các tiêu chuẩn thúc đẩy công nghệ, tăng hiệu quả và thúc đẩy việc sử dụng bộ trao đổi nhiệt và chân không.\n\nMục tiêu này được thực hiện thông qua các ủy ban công nghệ cụ thể hoạt động theo thẩm quyền của bảy Ban của Viện:\n\nBộ ngưng tụ làm mát bằng không khí\nBộ ngưng tụ bề mặt hơi nước\nBộ gia nhiệt nước cấp kín\nBộ trao đổi nhiệt vỏ và ống\nBộ trao đổi nhiệt tấm\nCông nghệ chân không\nBộ khử khí\nMỗi ban này tài trợ cho một ủy ban kỹ thuật có nhiệm vụ phát triển và sửa đổi các tiêu chuẩn cụ thể cho phạm vi sản phẩm của mình.\n\nMỗi ủy ban kỹ thuật họp ít nhất hai lần một năm, với mỗi thành viên của bộ phận chỉ định một kỹ sư làm đại diện của mình trong Ủy ban kỹ thuật; việc trao đổi liên tục giữa các thành viên ủy ban đảm bảo rằng các tiêu chuẩn dựa trên công nghệ mới nhất hiện có.\n\nKể từ khi thành lập cách đây hơn 79 năm, Viện đã giành được sự công nhận quốc tế là cơ quan có thẩm quyền hàng đầu về công nghệ trao đổi nhiệt và thiết bị chân không. Các tiêu chuẩn của Viện được sử dụng trên toàn thế giới để thiết kế, sản xuất và vận hành thiết bị trao đổi nhiệt và chân không.\n\nHEI đã mở rộng nỗ lực chia sẻ công nghệ mới nhất bằng cách tài trợ cho các hội thảo và xuất bản các bài viết cho người dùng thiết bị trao đổi nhiệt và chân không.', 'Viện Trao đổi Nhiệt (HEI) là một hiệp hội thương mại phi lợi nhuận cam kết thúc đẩy, quảng bá và hiểu biết về kỹ thuật trong nhiều loại thiết bị trao đổi nhiệt và chân không quy mô công nghiệp và tiện ích.', NULL, NULL, NULL, 'publisher/avatar/99KW2RHSH4H9HHUJ10V6.jpg', 0),
(4379, 'HFES - Human Factors and Ergonomics Society', 'HFES - Human Factors and Ergonomics Society', 'The Human Factors and Ergonomics Society, founded in 1957, is the world\'s largest scientific association for human factors/ergonomics professionals. HFES serves the needs of members and the public by promoting and advancing the discovery and exchange of knowledge concerning the characteristics of human beings that are applicable to the design of systems, products, tools, and environments of all kinds.\nThe Human Factors and Ergonomics Society, founded in 1957, is the world’s largest scientific association for human factors/ergonomics professionals.\nHFES provides education, builds connections, and advocates on behalf of human factors/ergonomics field—from students to researchers, and industry practitioners—and fosters collaboration across the spectrum of professionals to drive forward advances in human factors and ergonomics because HFES believes that the seamless connection between humans and systems, and the connection between research and application, is vital to keeping all human beings safe. \nThe Society’s 3,500 members work in educational institutions, companies, government and military research centers, and independent consultancies in 58 countries. About 15% of members are students.  \nMission\nThe mission of HFES is to advance the science and practice of designing for people in systems through knowledge exchange, collaboration, and advocacy.\nVision \nA world that works for humans by design grounded in science.\nDiversity, Equity, Inclusion, and Belonging in HFES and in the HF/E Profession\nHFES strongly values its vision of \"a future in which the reach, relevance, and quality of human factors/ergonomics (HF/E) are greatly expanded by enriching the science and enhancing its impact on solving societal problems,\" including systemic racism. In support of this vision, we value and celebrate the diversity of students, practitioners, educators, researchers, and other individuals who engage in the profession of HF/E and the stakeholders who benefit from their practice.', 'Hiệp hội các yếu tố con người và công thái học, được thành lập năm 1957, là hiệp hội khoa học lớn nhất thế giới dành cho các chuyên gia về yếu tố con người/công thái học. HFES phục vụ nhu cầu của các thành viên và công chúng bằng cách thúc đẩy và phát triển việc khám phá và trao đổi kiến ​​thức liên quan đến các đặc điểm của con người có thể áp dụng cho việc thiết kế các hệ thống, sản phẩm, công cụ và môi trường các loại.\nHiệp hội các yếu tố con người và công thái học, được thành lập năm 1957, là hiệp hội khoa học lớn nhất thế giới dành cho các chuyên gia về yếu tố con người/công thái học.\nHFES cung cấp giáo dục, xây dựng các mối quan hệ và ủng hộ thay mặt cho lĩnh vực yếu tố con người/công thái học—từ sinh viên đến các nhà nghiên cứu và các học viên trong ngành—và thúc đẩy sự hợp tác trên toàn bộ các chuyên gia để thúc đẩy những tiến bộ trong yếu tố con người và công thái học vì HFES tin rằng mối liên hệ liền mạch giữa con người và hệ thống, cũng như mối liên hệ giữa nghiên cứu và ứng dụng, là rất quan trọng để giữ an toàn cho tất cả con người.\n3.500 thành viên của Hiệp hội làm việc tại các tổ chức giáo dục, công ty, trung tâm nghiên cứu của chính phủ và quân đội, và các công ty tư vấn độc lập tại 58 quốc gia. Khoảng 15% thành viên là sinh viên.\nSứ mệnh\nSứ mệnh của HFES là thúc đẩy khoa học và thực hành thiết kế cho con người trong các hệ thống thông qua trao đổi kiến ​​thức, hợp tác và vận động.\nTầm nhìn\nMột thế giới hoạt động vì con người theo thiết kế dựa trên khoa học.\nĐa dạng, Công bằng, Hòa nhập và Thuộc về trong HFES và trong Nghề HF/E\nHFES coi trọng tầm nhìn của mình về \"một tương lai trong đó phạm vi, sự liên quan và chất lượng của các yếu tố con người/công thái học (HF/E) được mở rộng đáng kể bằng cách làm phong phú khoa học và tăng cường tác động của nó trong việc giải quyết các vấn đề xã hội\", bao gồm cả chủ nghĩa phân biệt chủng tộc có hệ thống. Để ủng hộ tầm nhìn này, chúng tôi coi trọng và tôn vinh sự đa dạng của sinh viên, học viên, nhà giáo dục, nhà nghiên cứu và những cá nhân khác tham gia vào nghề HF/E và các bên liên quan được hưởng lợi từ hoạt động của họ.', 'Hiệp hội các yếu tố con người và công thái học, được thành lập năm 1957, là hiệp hội khoa học lớn nhất thế giới dành cho các chuyên gia về yếu tố con người/công thái học. HFES phục vụ nhu cầu của các thành viên và công chúng bằng cách thúc đẩy và phát triển việc khám phá và trao đổi kiến ​​thức liên quan đến các đặc điểm của con người có thể áp dụng cho việc thiết kế các hệ thống, sản phẩm, công cụ và môi trường các loại.', NULL, NULL, NULL, 'publisher/avatar/BAKDEODG36DWKB0G0CUN.jpg', 0),
(4380, 'HI - Hydraulic Institute', 'HI - Hydraulic Institute', 'Dedicated to excellence in the engineering, manufacturing and application of pumping equipment, HI standards are intended to eliminate misunderstandings between manufacturers, purchasers and customers. HI Pump Standards are widely used by consultants, contractors, engineering construction firms, manufacturers, libraries and universities, and pump users.\nFor more than a century the Hydraulic Institute (HI) has been centering the pump industry around developing standards and technical resources, advancing solutions for pump system performance and efficiency, educating the global marketplace and advocating for the industry.\nIndustry experts collaborate to advance the industry by volunteering their time, talent, and expertise. The Institute offers a variety of programs designed to meet the needs of member and partner organizations, including participation in and access to statistics programs, standards, training and resources for workforce development and participation in industry initiatives.\nStandards\nHI is an approved Standards Development Organization by the American National Standards Institute (ANSI), publishing more than 30 National Standards (ANSI/HI) covering pump and system nomenclature, definitions, design, application, installation, operation, maintenance and testing. HI Standards cover positive displacement pumps of Reciprocating, Controlled-Volume Metering, Air-Operated Diaphragm, and Rotary type and Rotodynamic pumps of centrifugal, mixed and axial flow type.', 'Dành riêng cho sự xuất sắc trong kỹ thuật, sản xuất và ứng dụng thiết bị bơm, các tiêu chuẩn HI nhằm mục đích loại bỏ sự hiểu lầm giữa nhà sản xuất, người mua và khách hàng. Tiêu chuẩn bơm HI được sử dụng rộng rãi bởi các nhà tư vấn, nhà thầu, công ty xây dựng kỹ thuật, nhà sản xuất, thư viện và trường đại học và người dùng bơm.\nTrong hơn một thế kỷ, Viện Thủy lực (HI) đã tập trung ngành bơm vào việc phát triển các tiêu chuẩn và nguồn lực kỹ thuật, thúc đẩy các giải pháp cho hiệu suất và hiệu quả của hệ thống bơm, giáo dục thị trường toàn cầu và ủng hộ ngành.\nCác chuyên gia trong ngành hợp tác để thúc đẩy ngành bằng cách tình nguyện dành thời gian, tài năng và chuyên môn của họ. Viện cung cấp nhiều chương trình được thiết kế để đáp ứng nhu cầu của các tổ chức thành viên và đối tác, bao gồm tham gia và tiếp cận các chương trình thống kê, tiêu chuẩn, đào tạo và nguồn lực để phát triển lực lượng lao động và tham gia vào các sáng kiến ​​của ngành.\nTiêu chuẩn\nHI là Tổ chức Phát triển Tiêu chuẩn được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) chấp thuận, xuất bản hơn 30 Tiêu chuẩn Quốc gia (ANSI/HI) bao gồm danh pháp, định nghĩa, thiết kế, ứng dụng, lắp đặt, vận hành, bảo trì và thử nghiệm của máy bơm và hệ thống. Tiêu chuẩn HI bao gồm các loại bơm dịch chuyển tích cực kiểu pittông, kiểu đo thể tích có kiểm soát, kiểu màng hoạt động bằng khí nén và kiểu quay và bơm quay động lực học kiểu ly tâm, kiểu hỗn hợp và kiểu dòng chảy hướng trục.', 'Dành riêng cho sự xuất sắc trong kỹ thuật, sản xuất và ứng dụng thiết bị bơm, các tiêu chuẩn HI nhằm mục đích loại bỏ sự hiểu lầm giữa nhà sản xuất, người mua và khách hàng. Tiêu chuẩn bơm HI được sử dụng rộng rãi bởi các nhà tư vấn, nhà thầu, công ty xây dựng kỹ thuật, nhà sản xuất, thư viện và trường đại học và người dùng bơm.', NULL, NULL, NULL, 'publisher/avatar/E0XNFB2WNURCK0C1TRP7.png', 0),
(4381, 'HIR - H.I.R. Technical Services', 'HIR - H.I.R. Technical Services', 'H.I.R. Technical Services specializes in providing guidance and council for the safe design, fabrication, construction, and inspection of above ground storage tanks of all types.', 'H.I.R. Technical Services chuyên cung cấp hướng dẫn và tư vấn về thiết kế, chế tạo, xây dựng và kiểm tra an toàn các loại bể chứa trên mặt đất.', 'H.I.R. Technical Services chuyên cung cấp hướng dẫn và tư vấn về thiết kế, chế tạo, xây dựng và kiểm tra an toàn các loại bể chứa trên mặt đất.', NULL, NULL, NULL, 'publisher/avatar/SKMO8KO9RKUC9RB29FTX.jpg', 0),
(4382, 'HPS - Health Physics Society', 'HPS - Health Physics Society', 'The Health Physics Society (HPS), formed in 1956, is a scientific organization of professionals who specialize in radiation safety. Its mission is to support its members in the practice of their profession and to promote excellence in the science and practice of radiation safety.\n\nToday its members represent all scientific and technical areas related to radiation safety, including academia, government, medicine, research and development, analytical services, consulting, and industry in all 50 states and the District of Columbia. The Society is chartered in the United States as an independent nonprofit scientific organization and, as such, is not affiliated with any government or industrial organization or private entity.\n\nThe Society also promotes:\n\nPublic information preparation and dissemination.\nEducation and training opportunities.\nScientific information exchange through meetings and conferences.\nPosting current news items.\nClick to see the Society Leadership, the HPS Code of Connduct, and the HPS Strategic Plan.\n\nClick here to see the Statement on Diversity and Inclusion.\n\nThe Society\'s Prospectus summarizes the activities, describes the various types of membership, and lists the publications of the Society.', 'Health Physics Society (HPS), được thành lập vào năm 1956, là một tổ chức khoa học gồm các chuyên gia chuyên về an toàn bức xạ. Sứ mệnh của tổ chức là hỗ trợ các thành viên trong việc hành nghề và thúc đẩy sự xuất sắc trong khoa học và thực hành an toàn bức xạ.\n\nNgày nay, các thành viên của tổ chức đại diện cho tất cả các lĩnh vực khoa học và kỹ thuật liên quan đến an toàn bức xạ, bao gồm học viện, chính phủ, y học, nghiên cứu và phát triển, dịch vụ phân tích, tư vấn và công nghiệp tại tất cả 50 tiểu bang và Quận Columbia. Tổ chức được cấp giấy phép tại Hoa Kỳ với tư cách là một tổ chức khoa học phi lợi nhuận độc lập và do đó không liên kết với bất kỳ tổ chức chính phủ, công nghiệp hoặc tổ chức tư nhân nào.\n\nTổ chức cũng thúc đẩy:\n\nChuẩn bị và phổ biến thông tin công khai.\n\nCơ hội giáo dục và đào tạo.\nTrao đổi thông tin khoa học thông qua các cuộc họp và hội nghị.\nĐăng các mục tin tức hiện tại.\nNhấp để xem Lãnh đạo của Tổ chức, Quy tắc ứng xử của HPS và Kế hoạch chiến lược của HPS.\n\nNhấp vào đây để xem Tuyên bố về Đa dạng và Hòa nhập.\n\nBản cáo bạch của Hội tóm tắt các hoạt động, mô tả các loại thành viên khác nhau và liệt kê các ấn phẩm của Hội.', 'Health Physics Society (HPS), được thành lập vào năm 1956, là một tổ chức khoa học gồm các chuyên gia chuyên về an toàn bức xạ. Sứ mệnh của tổ chức là hỗ trợ các thành viên trong việc hành nghề và thúc đẩy sự xuất sắc trong khoa học và thực hành an toàn bức xạ.', NULL, NULL, NULL, 'publisher/avatar/NU0K13Q28L7V73ADAGUF.jpg', 0),
(4383, 'I3A - International Imaging Industry AssociationI', 'I3A - International Imaging Industry AssociationI', '3A is the central international forum for the development and advancement of open standards and innovations for the worldwide imaging ecosystem. I3A\'s vision is to enable the use of imaging to simplify and enrich people\'s lives through visual experiences that connect generations, communities, information and services. I3A brings members together to collaborate on initiatives that generate standards, tools and metrics, drive adoption, foster growth, and open pathways to new markets. I3A is organized into six focused Interest Groups. I3A Interest Group Initiatives enable the rapid development of consortium standards, delivering quick and unique solutions to the market that are unavailable through other processes.\nThe International Imaging Industry Association (I3A) was a trade association created by the merger of the Photographic and Imaging Manufacturers Association (PIMA) and the Digital Imaging Group (DIG) in 2001. It served the photographic industry, which included tracking the market size.\nFrom 2001 through 2010, I3A also served as the sponsor for ANSI and ISO standards for photography, including the Picture Transfer Protocol (ISO 15740) as well as consortia standards such as the Internet Imaging Protocol.\nI3A transferred the sponsorship of ANSI and ISO photographic standards to the Society for Imaging Science and Technology in January 2011, and had been disbanded as of October 2013.', '3A là diễn đàn quốc tế trung tâm cho sự phát triển và thúc đẩy các tiêu chuẩn mở và đổi mới cho hệ sinh thái hình ảnh toàn cầu. Tầm nhìn của I3A là cho phép sử dụng hình ảnh để đơn giản hóa và làm phong phú thêm cuộc sống của mọi người thông qua các trải nghiệm trực quan kết nối các thế hệ, cộng đồng, thông tin và dịch vụ. I3A tập hợp các thành viên lại với nhau để hợp tác trong các sáng kiến ​​tạo ra các tiêu chuẩn, công cụ và số liệu, thúc đẩy việc áp dụng, thúc đẩy tăng trưởng và mở ra các con đường đến các thị trường mới. I3A được tổ chức thành sáu Nhóm quan tâm tập trung. Các Sáng kiến ​​Nhóm quan tâm của I3A cho phép phát triển nhanh chóng các tiêu chuẩn của liên minh, cung cấp các giải pháp nhanh chóng và độc đáo cho thị trường mà không có sẵn thông qua các quy trình khác.\nHiệp hội Công nghiệp Hình ảnh Quốc tế (I3A) là một hiệp hội thương mại được thành lập thông qua sự hợp nhất của Hiệp hội các nhà sản xuất hình ảnh và nhiếp ảnh (PIMA) và Nhóm Hình ảnh Kỹ thuật số (DIG) vào năm 2001. Hiệp hội phục vụ cho ngành công nghiệp nhiếp ảnh, bao gồm theo dõi quy mô thị trường.\nTừ năm 2001 đến năm 2010, I3A cũng là nhà tài trợ cho các tiêu chuẩn ANSI và ISO dành cho nhiếp ảnh, bao gồm Giao thức truyền ảnh (ISO 15740) cũng như các tiêu chuẩn của các tập đoàn như Giao thức hình ảnh Internet.\nI3A đã chuyển giao quyền tài trợ cho các tiêu chuẩn nhiếp ảnh ANSI và ISO cho Hiệp hội Khoa học và Công nghệ hình ảnh vào tháng 1 năm 2011 và đã bị giải thể vào tháng 10 năm 2013.', 'Hiệp hội Công nghiệp Hình ảnh Quốc tế (I3A) là một hiệp hội thương mại được thành lập thông qua sự hợp nhất của Hiệp hội các nhà sản xuất hình ảnh và nhiếp ảnh (PIMA) và Nhóm Hình ảnh Kỹ thuật số (DIG) vào năm 2001.', NULL, NULL, NULL, 'publisher/avatar/0B8KT0YJSHLHP2L257JC.jpg', 0),
(4384, 'IADC - International Association of Drilling Contractors', 'IADC - International Association of Drilling Contractors', 'Since 1940, IADC has exclusively represented the worldwide oil and gas drilling industry. IADC\'s mission is to catalyze improved performance for the drilling industry by enhancing operational integrity and championing better regulation to facilitate safer, cleaner and more efficient drilling operations worldwide.\nIADC is dedicated to promoting innovative technology and safe drilling practices that bring oil and gas to the world’s consumers.\nIADC is focused on core industry issues, like health and safety, training and accreditation, attracting the next generation to work alongside us, and serving as a strong advocate for oil and gas activities.\nFor 80 years, IADC has championed the drilling industry through training programs, guidelines, publications, committees, conferences, and advocacy for the global drilling industry.\nIADC welcomes companies that share a commitment to improving safety, advancing drilling technology and enhancing personnel competence.\nIADC brings the collective knowledge and experience of the global drilling industry into the hands of each member through a vast set of tried-and-true resources.', 'Kể từ năm 1940, IADC đã đại diện độc quyền cho ngành khoan dầu khí trên toàn thế giới. Sứ mệnh của IADC là thúc đẩy hiệu suất được cải thiện cho ngành khoan bằng cách tăng cường tính toàn vẹn hoạt động và ủng hộ các quy định tốt hơn để tạo điều kiện cho các hoạt động khoan an toàn hơn, sạch hơn và hiệu quả hơn trên toàn thế giới.\nIADC cam kết thúc đẩy công nghệ tiên tiến và các hoạt động khoan an toàn mang dầu khí đến với người tiêu dùng trên toàn thế giới.\nIADC tập trung vào các vấn đề cốt lõi của ngành, như sức khỏe và an toàn, đào tạo và công nhận, thu hút thế hệ tiếp theo làm việc cùng chúng tôi và đóng vai trò là người ủng hộ mạnh mẽ cho các hoạt động dầu khí.\nTrong 80 năm, IADC đã ủng hộ ngành khoan thông qua các chương trình đào tạo, hướng dẫn, ấn phẩm, ủy ban, hội nghị và hoạt động ủng hộ cho ngành khoan toàn cầu.\nIADC hoan nghênh các công ty chia sẻ cam kết cải thiện an toàn, phát triển công nghệ khoan và nâng cao năng lực của nhân viên.\nIADC mang kiến ​​thức và kinh nghiệm chung của ngành khoan toàn cầu vào tay từng thành viên thông qua một bộ nguồn lực rộng lớn đã được thử nghiệm và chứng minh.', 'Kể từ năm 1940, IADC đã đại diện độc quyền cho ngành khoan dầu khí trên toàn thế giới. Sứ mệnh của IADC là thúc đẩy hiệu suất được cải thiện cho ngành khoan bằng cách tăng cường tính toàn vẹn hoạt động và ủng hộ các quy định tốt hơn để tạo điều kiện cho các hoạt động khoan an toàn hơn, sạch hơn và hiệu quả hơn trên toàn thế giới.', NULL, NULL, NULL, 'publisher/avatar/EXNOQ0EG148C4YLTDCPW.jpg', 0),
(4385, 'IAPMO - International Association of Plumbing and Mechanical Officials', 'IAPMO - International Association of Plumbing and Mechanical Officials', 'The International Association of Plumbing and Mechanical Officials is an ANSI-accredited and ISO-certified standards body, with over 200 codes and standards covering plumbing, mechanical, swimming pools, backflow, solar and green energy systems. IAPMO codes help regulate the design, construction and maintenance of the built environment, protecting the health, safety and general welfare of a building\'s users.\nThe International Association of Plumbing & Mechanical Officials community of plumbing experts plays a vital public health role in assuring access to clean water and sanitation.\n \nWe like to say we live by the code. A code that says that water is safe, that plumbing systems are strong and that our association is even stronger.\n \nThe strength of our association brings all sectors of the plumbing industry together -- contractors, engineers, manufacturers and researchers -- rooted in a common belief that access to clean water is a fundamental right.\n \nOur consensus-based model code development process opens ourselves up to the genius of the entire community--and to the sunlight of the communities we serve through our open and transparent process.', 'Hiệp hội các quan chức cơ khí và ống nước quốc tế là một tổ chức tiêu chuẩn được ANSI công nhận và chứng nhận ISO, với hơn 200 quy tắc và tiêu chuẩn bao gồm hệ thống ống nước, cơ khí, hồ bơi, dòng chảy ngược, năng lượng mặt trời và năng lượng xanh. Các quy tắc của IAPMO giúp điều chỉnh thiết kế, xây dựng và bảo trì môi trường xây dựng, bảo vệ sức khỏe, sự an toàn và phúc lợi chung của người sử dụng tòa nhà.\nCộng đồng các chuyên gia về ống nước của Hiệp hội các quan chức cơ khí và ống nước quốc tế đóng vai trò quan trọng đối với sức khỏe cộng đồng trong việc đảm bảo quyền tiếp cận nước sạch và vệ sinh.\n\nChúng tôi muốn nói rằng chúng tôi sống theo quy tắc. Một quy tắc nói rằng nước an toàn, hệ thống ống nước mạnh mẽ và hiệp hội của chúng tôi thậm chí còn mạnh mẽ hơn.\n\nSức mạnh của hiệp hội chúng tôi tập hợp tất cả các lĩnh vực của ngành công nghiệp ống nước lại với nhau -- nhà thầu, kỹ sư, nhà sản xuất và nhà nghiên cứu -- bắt nguồn từ niềm tin chung rằng quyền tiếp cận nước sạch là quyền cơ bản.\n\nQuy trình phát triển quy tắc mô hình dựa trên sự đồng thuận của chúng tôi mở ra cho chúng tôi thiên tài của toàn bộ cộng đồng -- và ánh sáng mặt trời của các cộng đồng mà chúng tôi phục vụ thông qua quy trình công khai và minh bạch của mình.', 'Hiệp hội các quan chức cơ khí và ống nước quốc tế là một tổ chức tiêu chuẩn được ANSI công nhận và chứng nhận ISO, với hơn 200 quy tắc và tiêu chuẩn bao gồm hệ thống ống nước, cơ khí, hồ bơi, dòng chảy ngược, năng lượng mặt trời và năng lượng xanh. Các quy tắc của IAPMO giúp điều chỉnh thiết kế, xây dựng và bảo trì môi trường xây dựng, bảo vệ sức khỏe, sự an toàn và phúc lợi chung của người sử dụng tòa nhà.', NULL, NULL, '13*23*27*43.150*55*67*83*91*91.140*93', 'publisher/avatar/UH0I3DZEAK9X16G0G57F.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4386, 'IATA - International Air Transport Association', 'IATA - International Air Transport Association', 'The International Air Transport Association (IATA) is the trade association for the world\'s airlines, representing some 290 airlines or 82% of total air traffic. They support many areas of aviation activity and help formulate industry policy on critical aviation issues.\nThe International Air Transport Association (IATA) is the trade association for the world’s airlines, representing some 330 airlines over 80% of global air traffic. We support many areas of aviation activity and help formulate industry policy on critical aviation issues.', 'Hiệp hội Vận tải Hàng không Quốc tế (IATA) là hiệp hội thương mại của các hãng hàng không trên thế giới, đại diện cho khoảng 290 hãng hàng không hoặc 82% tổng lưu lượng hàng không. Họ hỗ trợ nhiều lĩnh vực hoạt động hàng không và giúp xây dựng chính sách của ngành về các vấn đề hàng không quan trọng.\nHiệp hội Vận tải Hàng không Quốc tế (IATA) là hiệp hội thương mại của các hãng hàng không trên thế giới, đại diện cho khoảng 330 hãng hàng không trên 80% lưu lượng hàng không toàn cầu. Chúng tôi hỗ trợ nhiều lĩnh vực hoạt động hàng không và giúp xây dựng chính sách của ngành về các vấn đề hàng không quan trọng.', 'Hiệp hội Vận tải Hàng không Quốc tế (IATA) là hiệp hội thương mại của các hãng hàng không trên thế giới, đại diện cho khoảng 290 hãng hàng không hoặc 82% tổng lưu lượng hàng không. Họ hỗ trợ nhiều lĩnh vực hoạt động hàng không và giúp xây dựng chính sách của ngành về các vấn đề hàng không quan trọng.', NULL, NULL, NULL, 'publisher/avatar/RM2ILTUS5WMXNEI6FZ8C.jpg', 0),
(4387, 'ICAO - International Civil Aviation Organization', 'ICAO - International Civil Aviation Organization', 'A specialized agency of the United Nations, the International Civil Aviation Organization (ICAO) was created in 1944 to promote the safe and orderly development of international civil aviation throughout the world. It sets standards and regulations necessary for aviation safety, security, efficiency and regularity, as well as for aviation environmental protection. The Organization serves as the forum for cooperation in all fields of civil aviation among its 191 Member States.', 'ICAO (International Civil Aviation Organization) là một tổ chức quốc tế chịu trách nhiệm quản lý và định hình các tiêu chuẩn và quy định hàng không dân dụng toàn cầu. ICAO được thành lập vào ngày 7 tháng 12 năm 1944, là một cơ quan thuộc Liên Hiệp Quốc có trụ sở tại Montreal, Canada.\n\nNhiệm vụ chính của ICAO là đảm bảo an toàn, hiệu quả và bền vững trong hàng không dân dụng quốc tế. Tổ chức này phát triển và thúc đẩy tiêu chuẩn, quy định và phương pháp hoạt động chung cho các hoạt động hàng không, bao gồm an toàn bay, an ninh hàng không, quản lý không lưu, văn bằng, phục vụ khách hàng và vận tải hàng hóa.\n\nICAO cung cấp một nền tảng để các quốc gia thành viên hợp tác và điều phối các hoạt động hàng không quốc tế. Tổ chức này tạo ra các tiêu chuẩn và quy định bằng cách phát triển các hiệp định và tiêu chuẩn phù hợp để đảm bảo sự nhất quán và tương thích trong ngành hàng không toàn cầu.\n\nICAO cũng đóng vai trò quan trọng trong việc cung cấp hỗ trợ kỹ thuật, đào tạo và chuyển giao công nghệ cho các quốc gia thành viên. Tổ chức này tổ chức các buổi hội thảo, khóa đào tạo và cung cấp tài liệu hướng dẫn để nâng cao năng lực và hiệu quả của các quốc gia trong việc thực thi các tiêu chuẩn hàng không quốc tế.\n\nVới 193 quốc gia thành viên, ICAO đóng vai trò quan trọng trong việc thúc đẩy sự phát triển bền vững và an toàn của ngành hàng không dân dụng toàn cầu.', 'ICAO (International Civil Aviation Organization) là một tổ chức quốc tế chịu trách nhiệm quản lý và định hình các tiêu chuẩn và quy định hàng không dân dụng toàn cầu.', 'ICAO', 'ICAO, Tổ chức Hàng không Dân dụng Thế giới (ICAO), International Civil Aviation Organisation (ICAO), Hàng không', NULL, 'publisher/avatar/JVPKI4UP4VL6W0EMDBNF.jpg', 0),
(4388, 'ICC - International Code Council', 'ICC - International Code Council', 'ICC founders include BOCA, ICBO and SBCCI. ICC works to develop a single, comprehensive, fully coordinated set of national model construction codes. Current ICC standards address a wide range of topics, including codes for international building, plumbing, mechanical systems, and energy conservation.\nThe International Code Council is the leading global source of model codes and standards and building safety solutions that include product evaluation, accreditation, technology, training, and certification. The Code Council\'s codes, standards, and solutions are used to ensure safe, affordable, and sustainable communities and buildings worldwide.\nThe International Code Council (ICC) family of solutions includes the ICC Evaluation Service (ICC ES), S. K. Ghosh Associates, the International Accreditation Service (IAS), General Code, ICC NTA, ICC Community Development Solutions, Alliance for National & Community Resilience (ANCR), and American Legal Publishing, which are dedicated to the construction of safe, sustainable, affordable and resilient structures. Find out more about each of our individual family of solutions here.\nFor more information about the Code Council, view our overview video, read our annual report, our overview brochure, and our 2025 strategic plan.\nThe International Codes, or I-Codes, are the most trusted source of model codes and standards. Decades of knowledge and experience guide our code development process to create safe, sustainable and affordable communities and a level playing field for builders, developers and manufacturers. As industry experts, we provide the codes and standards that our members turn to, building safety professionals rely on and manufacturers trust.', 'Những người sáng lập ICC bao gồm BOCA, ICBO và SBCCI. ICC nỗ lực xây dựng một bộ quy tắc xây dựng mẫu quốc gia toàn diện, thống nhất và được phối hợp đầy đủ. Các tiêu chuẩn ICC hiện tại giải quyết nhiều chủ đề, bao gồm các quy tắc về xây dựng quốc tế, hệ thống ống nước, hệ thống cơ khí và tiết kiệm năng lượng.\nHội đồng Quy tắc Quốc tế là nguồn cung cấp quy tắc và tiêu chuẩn mẫu toàn cầu hàng đầu và các giải pháp an toàn xây dựng bao gồm đánh giá sản phẩm, công nhận, công nghệ, đào tạo và chứng nhận. Các quy tắc, tiêu chuẩn và giải pháp của Hội đồng Quy tắc được sử dụng để đảm bảo các cộng đồng và tòa nhà an toàn, giá cả phải chăng và bền vững trên toàn thế giới.\nNhóm giải pháp của Hội đồng Quy tắc Quốc tế (ICC) bao gồm Dịch vụ Đánh giá ICC (ICC ES), S. K. Ghosh Associates, Dịch vụ Công nhận Quốc tế (IAS), Quy tắc Chung, ICC NTA, Giải pháp Phát triển Cộng đồng ICC, Liên minh vì Khả năng phục hồi Quốc gia và Cộng đồng (ANCR) và American Legal Publishing, những đơn vị chuyên xây dựng các công trình an toàn, bền vững, giá cả phải chăng và có khả năng phục hồi. Tìm hiểu thêm về từng nhóm giải pháp riêng lẻ của chúng tôi tại đây.\nĐể biết thêm thông tin về Hội đồng Bộ luật, hãy xem video tổng quan của chúng tôi, đọc báo cáo thường niên, tờ rơi tổng quan và kế hoạch chiến lược năm 2025 của chúng tôi.\nBộ luật quốc tế, hay I-Codes, là nguồn đáng tin cậy nhất về các bộ luật và tiêu chuẩn mẫu. Nhiều thập kỷ kiến ​​thức và kinh nghiệm hướng dẫn quy trình phát triển bộ luật của chúng tôi để tạo ra các cộng đồng an toàn, bền vững và giá cả phải chăng cũng như một sân chơi bình đẳng cho các nhà xây dựng, nhà phát triển và nhà sản xuất. Là những chuyên gia trong ngành, chúng tôi cung cấp các bộ luật và tiêu chuẩn mà các thành viên của chúng tôi hướng đến, các chuyên gia an toàn xây dựng tin tưởng và các nhà sản xuất tin tưởng.', 'Những người sáng lập ICC bao gồm BOCA, ICBO và SBCCI. ICC nỗ lực xây dựng một bộ quy tắc xây dựng mẫu quốc gia toàn diện, thống nhất và được phối hợp đầy đủ. Các tiêu chuẩn ICC hiện tại giải quyết nhiều chủ đề, bao gồm các quy tắc về xây dựng quốc tế, hệ thống ống nước, hệ thống cơ khí và tiết kiệm năng lượng.', NULL, NULL, NULL, 'publisher/avatar/RC5ZKE1ZSA3XST4P27MU.jpg', 0),
(4389, 'ICEA - Insulated Cable Engineers Association', 'ICEA - Insulated Cable Engineers Association', 'The Insulated Cable Engineers Association (ICEA) is a professional organization dedicated to developing cable standards for the electric power, control, and telecommunications industries. Since 1925, the objective has been to ensure safe, economical, and efficient cable systems utilizing proven state-of-the-art materials and concepts.\nThe Insulated Cable Engineers Association (ICEA) is a professional organization dedicated to developing cable standards for electric power, control, and telecommunications industries. \n \nSince 1925, our objective has been to ensure safe, economical, and efficient cable systems utilizing proven state-of-the-art materials and concepts. Now with the proliferation of new materials and cable designs, our mission has gained significant importance. ICEA documents are of interest to industry participants worldwide, i.e. cable manufacturers, architects, engineers, utilities and manufacturing plant personnel, consultants, and Original Equipment Manufacturers (OEM\'s).\n \nICEA is a \"Not-For-Profit\" association whose members are sponsored by American and European leading cable manufacturers. The technical development work is performed in four semi-autonomous Sections;  Power, Control & Instrumentation, Portable, and Communications Cable. In addition, there is a Technical Advisory Committee (TAC) called the Utility Power Cable Standards (UPCS).\n \nMany ICEA standards are approved by the American National Standards Institute (ANSI).   Currently, the National Electrical Manufacturers Association (NEMA) is seeking new ANSI Members—specifically in the “user” and “general interest” categories—with a direct and material interest in the C8 committee on Insulated Wire and Cables, Excluding Magnet Wire and its subcommittees.', 'Hiệp hội Kỹ sư Cáp cách điện (ICEA) là một tổ chức chuyên nghiệp chuyên phát triển các tiêu chuẩn cáp cho ngành điện, điều khiển và viễn thông. Từ năm 1925, mục tiêu của tổ chức là đảm bảo các hệ thống cáp an toàn, tiết kiệm và hiệu quả bằng cách sử dụng các vật liệu và khái niệm tiên tiến đã được chứng minh.\nHiệp hội Kỹ sư Cáp cách điện (ICEA) là một tổ chức chuyên nghiệp chuyên phát triển các tiêu chuẩn cáp cho ngành điện, điều khiển và viễn thông.\n\nTừ năm 1925, mục tiêu của chúng tôi là đảm bảo các hệ thống cáp an toàn, tiết kiệm và hiệu quả bằng cách sử dụng các vật liệu và khái niệm tiên tiến đã được chứng minh. Hiện nay, với sự phát triển của các vật liệu và thiết kế cáp mới, sứ mệnh của chúng tôi đã trở nên quan trọng đáng kể. Các tài liệu của ICEA được các bên tham gia trong ngành trên toàn thế giới quan tâm, tức là các nhà sản xuất cáp, kiến ​​trúc sư, kỹ sư, nhân viên nhà máy sản xuất và tiện ích, cố vấn và Nhà sản xuất thiết bị gốc (OEM).\n\nICEA là một hiệp hội \"phi lợi nhuận\" có các thành viên được tài trợ bởi các nhà sản xuất cáp hàng đầu của Mỹ và châu Âu. Công tác phát triển kỹ thuật được thực hiện tại bốn Ban bán tự chủ; Cáp điện, điều khiển & đo lường, di động và truyền thông. Ngoài ra, còn có một Ủy ban cố vấn kỹ thuật (TAC) được gọi là Tiêu chuẩn cáp điện tiện ích (UPCS).\n\nNhiều tiêu chuẩn ICEA được Viện tiêu chuẩn quốc gia Hoa Kỳ (ANSI) chấp thuận. Hiện tại, Hiệp hội các nhà sản xuất điện quốc gia (NEMA) đang tìm kiếm các thành viên ANSI mới—cụ thể là trong các danh mục “người dùng” và “lợi ích chung”—có lợi ích trực tiếp và vật chất trong ủy ban C8 về dây và cáp cách điện, không bao gồm dây điện từ và các tiểu ban của ủy ban này.', 'Hiệp hội Kỹ sư Cáp cách điện (ICEA) là một tổ chức chuyên nghiệp chuyên phát triển các tiêu chuẩn cáp cho ngành điện, điều khiển và viễn thông. Từ năm 1925, mục tiêu của tổ chức là đảm bảo các hệ thống cáp an toàn, tiết kiệm và hiệu quả bằng cách sử dụng các vật liệu và khái niệm tiên tiến đã được chứng minh.\nHiệp hội Kỹ sư Cáp cách điện (ICEA) là một tổ chức chuyên nghiệp chuyên phát triển các tiêu chuẩn cáp cho ngành điện, điều khiển và viễn thông.', NULL, NULL, NULL, 'publisher/avatar/3RXKHJNR16WX718QR4Q6.jpg', 0),
(4390, 'ICML - International Council for Machinery Lubrication', 'ICML - International Council for Machinery Lubrication', 'The International Council for Machinery Lubrication (ICML) is a vendor-neutral, not-for-profit organization founded to serve global industry as the world-class authority on machinery lubrication that advances the optimization of asset reliability, utilization and costs.\nICML is a global non-profit organization dedicated to helping lubrication practitioners succeed in their professional careers. ICML certification exams are administered in accordance with ISO 18436 and are available worldwide in multiple languages and in both paper and online formats. We coordinate our exam schedule with a network of independent training partners.\nThe International Council for Machinery Lubrication (ICML) is a vendor-neutral, not-for-profit organization founded to serve global industry as the world-class authority on machinery lubrication that advances the optimization of asset reliability, utilization and costs.\nICML was originally established to be a vehicle for the exchange of ideas and best practices, to assure the skills of those who work in our field, to recognize excellence and accomplishments, and to invite new participants to join our industry. \nToday we support individuals and organizations through programs that strengthen machinery lubrication and oil analysis as technical fields of endeavor. We are a certification body, a standards body, a membership body, and an awards body.', 'Hội đồng bôi trơn máy móc quốc tế (ICML) là một tổ chức phi lợi nhuận, trung lập với nhà cung cấp được thành lập để phục vụ ngành công nghiệp toàn cầu với tư cách là cơ quan có thẩm quyền đẳng cấp thế giới về bôi trơn máy móc, thúc đẩy việc tối ưu hóa độ tin cậy, sử dụng và chi phí của tài sản.\nICML là một tổ chức phi lợi nhuận toàn cầu chuyên giúp các học viên bôi trơn thành công trong sự nghiệp chuyên môn của họ. Các kỳ thi chứng chỉ ICML được quản lý theo tiêu chuẩn ISO 18436 và có sẵn trên toàn thế giới bằng nhiều ngôn ngữ và ở cả định dạng giấy và trực tuyến. Chúng tôi phối hợp lịch thi của mình với một mạng lưới các đối tác đào tạo độc lập.\nHội đồng bôi trơn máy móc quốc tế (ICML) là một tổ chức phi lợi nhuận, trung lập với nhà cung cấp được thành lập để phục vụ ngành công nghiệp toàn cầu với tư cách là cơ quan có thẩm quyền đẳng cấp thế giới về bôi trơn máy móc, thúc đẩy việc tối ưu hóa độ tin cậy, sử dụng và chi phí của tài sản.\nICML ban đầu được thành lập để trở thành phương tiện trao đổi ý tưởng và phương pháp hay nhất, đảm bảo kỹ năng của những người làm việc trong lĩnh vực của chúng tôi, ghi nhận sự xuất sắc và thành tích, và mời những người tham gia mới tham gia ngành của chúng tôi.\nNgày nay, chúng tôi hỗ trợ các cá nhân và tổ chức thông qua các chương trình tăng cường bôi trơn máy móc và phân tích dầu như các lĩnh vực kỹ thuật của nỗ lực. Chúng tôi là một tổ chức chứng nhận, một tổ chức tiêu chuẩn, một tổ chức thành viên và một tổ chức trao giải thưởng.', 'Hội đồng bôi trơn máy móc quốc tế (ICML) là một tổ chức phi lợi nhuận, trung lập với nhà cung cấp được thành lập để phục vụ ngành công nghiệp toàn cầu với tư cách là cơ quan có thẩm quyền đẳng cấp thế giới về bôi trơn máy móc, thúc đẩy việc tối ưu hóa độ tin cậy, sử dụng và chi phí của tài sản.', NULL, NULL, NULL, 'publisher/avatar/VSHGNJ3ZIH0EFI4HR0DT.jpg', 0),
(4391, 'IEC - International Electrotechnical Commission', 'IEC - International Electrotechnical Commission', 'IEC\'s activities, collectively known as electrotechnology, cover all electrical, electronic and associated technologies in the areas of power generation, transmission and distribution, medical equipment, semiconductors, fibre optics, nanotechnology and renewable energies. In addition to providing an excellent framework for improving safety and optimizing energy, IEC standards support trade between countries by providing a reference for the functioning of the World Trade Organization (WTO) Agreement on Technical Barriers to Trade.', 'Uỷ ban Kỹ thuật Điện Quốc tế (International Electrotechnical Commission - IEC)\n\nHàng triệu thiết bị điện tử, sử dụng hoặc sản xuất điện, dựa vào các tiêu chuẩn quốc tế IEC và Hệ thống đánh giá sự phù hợp trong hoạt động, lắp đặt và vận hành an toàn.\n\nĐược thành lập vào năm 1906, Ủy ban Kỹ thuật Điện Quốc tế IEC là tổ chức hàng đầu thế giới chịu trách nhiệm xây dựng và công bố tiêu chuẩn quốc tế cho tất cả công nghệ điện, điện tử và các công nghệ liên quan, được gọi chung là “kỹ thuật điện”. IEC phục vụ thị trường và xã hội thế giới thông qua công tác tiêu chuẩn hóa và đánh giá sự phù hợp, cung cấp nền tảng cho các công ty, ngành công nghiệp và chính phủ có thể gặp gỡ, thảo luận và xây dựng các tiêu chuẩn quốc tế mà họ cần, thúc đẩy thương mại và tăng trưởng kinh tế thế giới, khuyến khích phát triển các sản phẩm, hệ thống, dịch vụ an toàn, hiệu quả và thân thiện với môi trường.\n\nTất cả các Tiêu chuẩn Quốc tế IEC đều dựa trên sự đồng thuận và đại diện cho nhu cầu của các bên liên quan chính của mọi quốc gia tham gia IEC. Mỗi quốc gia thành viên, dù lớn hay nhỏ, đều có một phiếu bầu và tiếng nói trong quá trình xây dựng Tiêu chuẩn Quốc tế IEC.\n\nThành viên của IEC đến từ khắp nơi trên thế giới. Mặc dù từng thành viên khác nhau nhưng đều có một điểm chung: họ đại diện cho toàn bộ mối quan tâm về kỹ thuật điện tại quốc gia, công ty và doanh nghiệp, hiệp hội ngành nghề, các cơ quan giáo dục, các cơ quan chính phủ và các cơ quan quản lý. Tất cả các bên liên quan được tập hợp lại thông qua Ban kỹ thuật quốc gia của các quốc gia thành viên. IEC cũng hướng tới các nước công nghiệp hóa mới thông qua Chương trình Quốc gia Liên kết (có 87 quốc gia tham gia Chương trình) và, cùng với 83 quốc gia thành viên, đã lan tỏa phạm vi của gia đình IEC trên hơn 97% dân số thế giới. IEC cũng hợp tác với một số đối tác quốc tế, khu vực và quốc gia nhằm tạo ra các ấn bản chung, giúp quảng bá tầm quan trọng của tiêu chuẩn hóa trên toàn thế giới và điều phối các mối liên hệ tiềm năng trong công việc.\n\nCơ cấu tổ chức của IEC bao gồm:\n\n-  Hội đồng IEC (IEC Council): Thiết lập chính sách, các mục tiêu chiến lược dài hạn và tài chính của IEC. Hội đồng IEC giao cho Ủy ban Hội đồng (Council Board) quản lý công việc của IEC, với trách nhiệm quản lý cụ thể trong các lĩnh vực tiêu chuẩn, đánh giá sự phù hợp và chiến lược thị trường lần lượt do các ban SMB (Ban quản lý tiêu chuẩn hóa), CAB (Ban đánh giá sự phù hợp) và MSB (Ban chiến lược thị trường) đảm trách.\n\nMỗi năm Hội đồng IEC họp ít nhất một lần tại Đại hội đồng IEC (IEC General Assembly);\n\n-  Ủy ban Hội đồng IEC (IEC Council Board): gồm 15 thành viên do Hội đồng IEC bầu ra và các cán bộ của IEC. Ủy ban Hội đồng đưa ra những khuyến nghị về chính sách của IEC cho Hội đồng, quyết định các hoạt động (trừ các vấn đề về tài chính) và thực hiện các chính sách của hội đồng. Là đơn vị tiếp nhận và xem xét các báo cáo của SMB, CAB và MSB. Khi cần thiết Ủy ban Hội đồng sẽ lập ra các đơn vị tư vấn hoặc nhóm công tác đặc biệt cho các vấn đề cụ thể, chỉ định chủ tịch và các thành viên của những đơn vị này. Ủy ban hội đồng họp ít nhất hai lần mỗi năm;\n\n-  Ban Điều hành (Executive Committee): Chịu trách nhiệm triển khai các quyết định của Hội đồng và Ủy ban Hội đồng, giám sát hoạt động của Văn phòng Trung tâm và trao đổi thông tin với các Ủy ban IEC quốc gia. Ban điều hành chuẩn bị chương trình và tài liệu cho Ủy ban Hội đồng. Ban điều hành họp ít nhất là bốn lần mỗi năm.\n\n- Các ban chức năng gồm\n\n- Ban quản lý tiêu chuẩn hóa (Standardization Management Board)\n\n- Ban chính sách thị trường (Market Strategy Board)\n\n- Ban đánh giá sự phù hợp (Comformity Assessment Board);\n\n- Văn phòng Trung tâm: do Tổng Thư ký điều hành, có trụ sở tại Giơ-ne-vơ, Thụy Sỹ.\n\n- Các cơ quan kỹ thuật: IEC hiện có 104 Ban kỹ thuật và 90 Tiểu ban kỹ thuật, 559 nhóm công tác, 268 nhóm dự án, 607 nhóm duy trì, 4 hệ thống đánh giá sự phù hợp toàn cầu. \n\nCó hai hình thức tham gia IEC: Thành viên đầy đủ và thành viên liên kết. Tính đến nay IEC có 83 quốc gia thành viên (trong đó: 60 thành viên đầy đủ và 23 thành viên liên kết). Thành viên đầy đủ có quyền tham gia vào tất cả các hoạt động của IEC với quyền biểu quyết bằng lá phiếu có trọng lượng ngang nhau, trong khi đó thành viên liên kết chỉ được tham gia một cách hạn chế vào các hoạt động của IEC và không có quyền biểu quyết. Sự khác nhau giữa hai loại thành viên này còn được thể hiện ở kinh phí đóng góp. Ngoài ra, còn có quy chế \"Thành viên tiền liên kết\" với mục đích khuyến khích và thúc đẩy các nước thành viên thuộc loại này trở thành thành viên liên kết trong vòng 5 năm.\n\nTháng 4/2002, Việt Nam đã tham gia IEC với tư cách Thành viên liên kết. Việt Nam là thành viên P (thành viên tham gia) của ba Ban kỹ thuật IEC.\n\nHoạt động chính của IEC là xây dựng và ban hành các tiêu chuẩn quốc tế IEC và các báo cáo kỹ thuật. Các tiêu chuẩn IEC hiện được áp dụng rộng rãi ở nhiều nước trên thế giới, được các nước chấp nhận thành tiêu chuẩn quốc gia, được viện dẫn khi soạn thảo các hồ sơ dự thầu và hợp đồng thương mại. Các ấn phẩm của IEC được xuất bản chính thức bằng hai ngôn ngữ (tiếng Anh và tiếng Pháp). Uỷ ban Kỹ thuật điện Quốc gia của Liên bang Nga chịu trách nhiệm xuất bản phiên bản tiếng Nga. Một số ấn phẩm đã được dịch sang tiếng Tây Ban Nha.\n\nNgoài việc xây dựng và ban hành tiêu chuẩn quốc tế IEC, IEC còn duy trì các hệ thống đánh giá sự phù hợp với tiêu chuẩn IEC, đó là:\n\n- IECEE: Hệ thống thử nghiệm và chứng nhận sự phù hợp toàn cầu cho các thiết bị và linh kiện kỹ thuật điện, gồm 54 tổ chức quốc gia thành viên với 77 tổ chức chứng nhận quốc gia, 497 phòng thử nghiệm. Đến nay đã có 96.954 giấy chứng nhận IECEE được cấp.\n\n- IECQ: Hệ thống đánh giá chất lượng linh kiện điện, gồm 14 tổ chức quốc gia thành viên với 21 tổ chức chứng nhận, 50 chi nhánh tổ chức chứng nhận đã đăng ký IECQ và 14 tổ chức đào tạo được IECQ thông qua. Đến nay đã có 7.047 giấy chứng nhận IECQ được cấp.\n\n- IECEx: Hệ thống chứng nhận với tiêu chuẩn liên quan đến thiết bị điện dùng trong môi trường dễ cháy nổ, gồm 33 tổ chức quốc gia thành viên với 83 tổ chức chứng nhận được thừa nhận và 59 phòng thử nghiệm. Đến nay có hơn 6.500 giấy chứng nhận và báo cáo được cấp.\n\n- IECRE: Hệ thống chứng nhận cho tiêu chuẩn liên quan đến thiết bị sử dụng trong việc ứng dụng năng lượng tái tạo, gồm 15 quốc gia thành viên, 3 cơ quan chứng nhận, 3 phòng thử nghiệm và 2 chứng chỉ được cấp.\n\nTổng số tài liệu phát hành của IEC là 6.327 tiêu chuẩn quốc tế, 288 quy định kỹ thuật, 481 báo cáo kỹ thuật và 42 IEC-PAS. Trong năm 2016, IEC đã công bố 476 tiêu chuẩn quốc tế, 56 quy định kỹ thuật, 52 báo cáo kỹ thuật và 8 IEC-PAS.\n\nĐịa chỉ website của IEC: www.iec.ch', 'Ủy ban Kỹ thuật Điện Quốc tế IEC là tổ chức hàng đầu thế giới chịu trách nhiệm xây dựng và công bố tiêu chuẩn quốc tế cho tất cả công nghệ điện, điện tử và các công nghệ liên quan, được gọi chung là “kỹ thuật điện”. IEC phục vụ thị trường và xã hội thế giới thông qua công tác tiêu chuẩn hóa và đánh giá sự phù hợp, cung cấp nền tảng cho các công ty, ngành công nghiệp và chính phủ có thể gặp gỡ, thảo luận và xây dựng các tiêu chuẩn quốc tế mà họ cần, thúc đẩy thương mại và tăng trưởng kinh tế thế giới, khuyến khích phát triển các sản phẩm, hệ thống, dịch vụ an toàn, hiệu quả và thân thiện với môi trường.', 'IEC,ISO/IEC,CEI,IEC/TS,IEC/PAS,IEC/TR,CISPR', 'IEC, Tiêu chuẩn Quốc tế về Điện - Điện tử IEC, International Electrotechnical Commission IEC, IEC Standards, Ủy ban Kỹ thuật Điện Quốc tế IEC, International Electrotechnical Commission - IEC, Tiêu chuẩn quốc tế, Điện điện tử, Kỹ thuật điện', NULL, 'publisher/avatar/5J8RFBYRH1E29BTPQYWN.jpg', 0),
(4392, 'IEEE - IEEE', 'IEEE - IEEE', 'IEEE is the world\'s largest technical professional society, serving members in computing, electrical engineering and electronics. Comprised of 37 societies and councils, IEEE publishes technical journals, magazines, proceedings, and more than 800 standards.', 'IEEE (Institute of Electrical and Electronics Engineers) là một tổ chức quốc tế hàng đầu trong lĩnh vực kỹ thuật điện và điện tử. Được thành lập vào năm 1963, IEEE có trụ sở tại New York, Hoa Kỳ, và là một tổ chức chuyên nghiệp phi lợi nhuận.\n\nIEEE tập hợp các nhà kỹ sư, nhà nghiên cứu và chuyên gia trong lĩnh vực kỹ thuật điện và điện tử từ khắp nơi trên thế giới. Với hơn 400.000 thành viên ở hơn 160 quốc gia, IEEE là một cộng đồng toàn cầu gắn kết bởi sự quan tâm chung đến phát triển công nghệ và tiến bộ trong lĩnh vực này.\n\nIEEE đóng vai trò quan trọng trong việc khuyến khích và phát triển các lĩnh vực như điện, điện tử, viễn thông, công nghệ máy tính, khoa học thông tin, robot và tự động hóa, năng lượng và các lĩnh vực kỹ thuật liên quan khác. Tổ chức này cung cấp một nền tảng cho việc trao đổi kiến thức, hợp tác nghiên cứu và phát triển công nghệ thông qua việc tổ chức hội thảo, hội nghị, xuất bản tạp chí và tiêu chuẩn kỹ thuật.\n\nIEEE cũng chịu trách nhiệm đề xuất và thiết lập các tiêu chuẩn kỹ thuật quan trọng trong ngành điện và điện tử. Các tiêu chuẩn này đảm bảo tính tương thích, an toàn và hiệu quả của các công nghệ và sản phẩm trong lĩnh vực này.\n\nVới tầm ảnh hưởng toàn cầu, IEEE đóng góp đáng kể vào sự phát triển và tiến bộ của ngành kỹ thuật điện và điện tử, và có vai trò quan trọng trong việc định hình tương lai công nghệ.', 'IEEE (Institute of Electrical and Electronics Engineers) là một tổ chức quốc tế hàng đầu trong lĩnh vực kỹ thuật điện và điện tử. Được thành lập vào năm 1963, IEEE có trụ sở tại New York, Hoa Kỳ, và là một tổ chức chuyên nghiệp phi lợi nhuận.', 'IEEE,ISO/IEEE,ISO/IEC/IEEE,ANSI/ASHRAE/IEEE,ANSI/IEEE,IEEE/ANSI,IEEE/EIA', 'IEEE, IEEE standard, Viện Các Nhà Kỹ sư Điện - Điện tử (IEEE), Institute of Electrical and Electronics Engineers (IEEE), điện điện tử, Kỹ thuật điện, Tiêu chuẩn quốc tế', NULL, 'publisher/avatar/E7N3B6HTCV9HOGOJBVAP.png', 0),
(4393, 'IEEE/UL - IEEE/UL', 'IEEE/UL - IEEE/UL', 'IEEE/UL - IEEE/UL', NULL, NULL, NULL, NULL, NULL, 'publisher/avatar/XYTCBQ7G60QTCA78ODKE.png', 0),
(4394, 'IES - Illuminating Engineering Society', 'IES - Illuminating Engineering Society', 'For over a century, IES (formerly IESNA) has provided services, programs and publications for the lighting community and its consumers. In addition to approximately 100 design guides, technical memoranda and documents, IES develops standards in conjunction with other related organizations.\nEstablished in 1906, the Illuminating Engineering Society is the recognized technical and educational authority on illumination. Our mission is to improve the lighted environment by bringing together those with lighting knowledge and by translating that knowledge into actions that benefit the public. We provide a variety of professional development, publications, networking and educational opportunities to our membership of engineers, architects, designers, educators, students, contractors, distributors, utility personnel, manufacturers and scientists in nearly 60 countries. Through our American National Standards Institute (ANSI) accredited process, we publish and maintain the Lighting Library®, with over 100 standards written by subject matter experts in our technical committees.', 'Trong hơn một thế kỷ, IES (trước đây là IESNA) đã cung cấp các dịch vụ, chương trình và ấn phẩm cho cộng đồng chiếu sáng và người tiêu dùng. Ngoài khoảng 100 hướng dẫn thiết kế, biên bản ghi nhớ và tài liệu kỹ thuật, IES còn phát triển các tiêu chuẩn kết hợp với các tổ chức liên quan khác.\nĐược thành lập vào năm 1906, Illuminating Engineering Society là cơ quan giáo dục và kỹ thuật được công nhận về chiếu sáng. Sứ mệnh của chúng tôi là cải thiện môi trường được chiếu sáng bằng cách tập hợp những người có kiến ​​thức về chiếu sáng và chuyển kiến ​​thức đó thành các hành động có lợi cho công chúng. Chúng tôi cung cấp nhiều cơ hội phát triển chuyên môn, ấn phẩm, mạng lưới và giáo dục cho các thành viên là kỹ sư, kiến ​​trúc sư, nhà thiết kế, nhà giáo dục, sinh viên, nhà thầu, nhà phân phối, nhân viên tiện ích, nhà sản xuất và nhà khoa học tại gần 60 quốc gia. Thông qua quy trình được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận, chúng tôi xuất bản và duy trì Lighting Library®, với hơn 100 tiêu chuẩn do các chuyên gia về chủ đề này trong các ủy ban kỹ thuật của chúng tôi biên soạn.', 'Trong hơn một thế kỷ, IES (trước đây là IESNA) đã cung cấp các dịch vụ, chương trình và ấn phẩm cho cộng đồng chiếu sáng và người tiêu dùng. Ngoài khoảng 100 hướng dẫn thiết kế, biên bản ghi nhớ và tài liệu kỹ thuật, IES còn phát triển các tiêu chuẩn kết hợp với các tổ chức liên quan khác.', '43.040.20', NULL, NULL, 'publisher/avatar/N3Z4RFRAUCXVH2VYS1XU.jpg', 0),
(4395, 'IEST - Institute of Environmental Sciences and Technology', 'IEST - Institute of Environmental Sciences and Technology', 'The Institute of Environment Sciences and Technology (IEST) is the preeminent, non-profit, technical association for professionals in the field of Contamination Control/Cleanrooms, Environmental Testing, or Nanotechnology Facilities.\nIEST is the leading technical, nonprofit membership association that connects professionals who impact controlled environments. We give you technical guidance through International Standards, Recommended Practices, and education programs developed by experts in the fields of contamination control, environmental test and reliability, and nanotechnology facilities. \nFounded in 1953, IEST is a multidisciplinary, international society with members who are internationally recognized for their contributions to the environmental sciences in the areas of contamination control/cleanrooms, environmental test and reliability, or nanotechnology facilities.  Our 501(c)(3) not-for-profit technical society is an ANSI-accredited standards-developing organization; Secretariat of ISO/TC 209 Cleanrooms and associated controlled environments; Administrator of the ANSI-accredited US TAG to ISO/TC 209; and a founding member of the ANSI-accredited US TAG to ISO/TC 229 Nanotechnologies.  \nIEST publishes standards and Recommended Practices (RPs), sharing up-to-date, reliable technical information in these fields: contamination control; design, test and evaluation; product reliability, and nanotechnology facilities. IEST Working Groups create standardized procedures based upon peer-approved applications of environmental technology. \nWorking Group members determine, through cooperative effort, what issues will be addressed and what procedures to include in each of these consensus documents, and what procedures will be included. \n \nIEST has revised U.S. Federal Standards such as FED-STD-209, MIL-STD-781, MIL-STD-810, and MIL-STD-1246 (now IEST-STD-1246E). The IEST Standards and Practices program administers WG-DTE043: MIL-STD-810G, the Working Group that provides expert support to this constantly evolving standard.', 'Viện Khoa học và Công nghệ Môi trường (IEST) là hiệp hội kỹ thuật phi lợi nhuận hàng đầu dành cho các chuyên gia trong lĩnh vực Kiểm soát ô nhiễm/Phòng sạch, Kiểm tra môi trường hoặc Cơ sở công nghệ nano.\nIEST là hiệp hội thành viên kỹ thuật phi lợi nhuận hàng đầu kết nối các chuyên gia có tác động đến môi trường được kiểm soát. Chúng tôi cung cấp cho bạn hướng dẫn kỹ thuật thông qua các Tiêu chuẩn quốc tế, Thực hành được khuyến nghị và các chương trình giáo dục do các chuyên gia trong lĩnh vực kiểm soát ô nhiễm, thử nghiệm và độ tin cậy môi trường và cơ sở công nghệ nano phát triển.\nĐược thành lập vào năm 1953, IEST là một hiệp hội quốc tế đa ngành với các thành viên được công nhận trên toàn thế giới về những đóng góp của họ cho khoa học môi trường trong các lĩnh vực kiểm soát ô nhiễm/phòng sạch, thử nghiệm và độ tin cậy môi trường hoặc cơ sở công nghệ nano. Hiệp hội kỹ thuật phi lợi nhuận 501(c)(3) của chúng tôi là một tổ chức phát triển tiêu chuẩn được ANSI công nhận; Ban thư ký ISO/TC 209 Phòng sạch và các môi trường được kiểm soát liên quan; Quản trị viên của TAG Hoa Kỳ được ANSI công nhận theo ISO/TC 209; và là thành viên sáng lập của US TAG được ANSI công nhận theo ISO/TC 229 Công nghệ nano.\nIEST công bố các tiêu chuẩn và Thực hành được khuyến nghị (RP), chia sẻ thông tin kỹ thuật đáng tin cậy, cập nhật trong các lĩnh vực này: kiểm soát ô nhiễm; thiết kế, thử nghiệm và đánh giá; độ tin cậy của sản phẩm và cơ sở công nghệ nano. Các Nhóm công tác IEST tạo ra các quy trình chuẩn hóa dựa trên các ứng dụng công nghệ môi trường được đồng nghiệp chấp thuận.\nCác thành viên của Nhóm công tác xác định, thông qua nỗ lực hợp tác, những vấn đề nào sẽ được giải quyết và những quy trình nào sẽ được đưa vào từng tài liệu đồng thuận này, và những quy trình nào sẽ được đưa vào.\n\nIEST đã sửa đổi các Tiêu chuẩn Liên bang Hoa Kỳ như FED-STD-209, MIL-STD-781, MIL-STD-810 và MIL-STD-1246 (hiện là IEST-STD-1246E). Chương trình Tiêu chuẩn và Thực hành của IEST quản lý WG-DTE043: MIL-STD-810G, Nhóm công tác cung cấp hỗ trợ chuyên môn cho tiêu chuẩn không ngừng phát triển này.', 'Viện Khoa học và Công nghệ Môi trường (IEST) là hiệp hội kỹ thuật phi lợi nhuận hàng đầu dành cho các chuyên gia trong lĩnh vực Kiểm soát ô nhiễm/Phòng sạch, Kiểm tra môi trường hoặc Cơ sở công nghệ nano.', NULL, NULL, NULL, 'publisher/avatar/EYMANPW5SHS1STEV4IU2.png', 0),
(4396, 'IFI - Industrial Fasteners Institute', 'IFI - Industrial Fasteners Institute', 'The Industrial Fasteners Institute\'s mission is to represent the North American fastener manufacturers to its suppliers, customers, the government, and the public at large to advance the competitiveness, products, and innovative technology of the IFI Member Companies in a global marketplace. The IFI technical staff are active in all national and international fastener standards developers and provide those organizations insights into fastener manufacturing to keep standards practical and purposeful.', 'Viện Ốc vít Công nghiệp (Industrial Fasteners Institute - IFI) là một tổ chức quốc tế chuyên về nghiên cứu, tiêu chuẩn hóa và đào tạo về ốc vít và công nghệ kết nối liên quan. IFI được thành lập vào năm 1931 và có trụ sở tại thành phố Cleveland, tiểu bang Ohio, Hoa Kỳ.\n\nIFI tập trung vào việc phát triển và quản lý tiêu chuẩn về ốc vít và sản phẩm kết nối trong ngành công nghiệp. Các tiêu chuẩn của IFI bao gồm các yêu cầu về kích thước, vật liệu, cấu trúc và các yêu cầu khác đối với các loại ốc vít và phụ kiện đi kèm.\n\nNgoài ra, IFI cũng đóng vai trò quan trọng trong việc nghiên cứu và phát triển công nghệ mới trong lĩnh vực ốc vít và kết nối. Tổ chức này cung cấp các tài liệu học tập và đào tạo để giúp các chuyên gia và kỹ sư hiểu rõ hơn về các khía cạnh kỹ thuật và ứng dụng của các sản phẩm liên quan đến ốc vít.\n\nIFI có một số thành viên từ các công ty sản xuất ốc vít và các tổ chức liên quan trong ngành công nghiệp, và họ thường tham gia vào quá trình phát triển tiêu chuẩn và hoạt động của IFI.\n\nVới vai trò của mình, IFI đóng góp quan trọng vào việc đảm bảo chất lượng và hiệu suất của các sản phẩm ốc vít và kết nối, đồng thời tạo ra một môi trường cạnh tranh và đáng tin cậy cho ngành công nghiệp toàn cầu.', 'Viện Ốc vít Công nghiệp (Industrial Fasteners Institute - IFI) là một tổ chức quốc tế chuyên về nghiên cứu, tiêu chuẩn hóa và đào tạo về ốc vít và công nghệ kết nối liên quan', 'IFI', 'IFI, Viện Ốc vít Công nghiệp (IFI), Industrial Fasteners Institute (IFI), ốc vít, Tiêu chuẩn IFI', NULL, 'publisher/avatar/3OO9AC2V1H5IY03YUXOQ.jpg', 0),
(4397, 'IICRC - The Institute of Inspection, Cleaning, and Restoration Certification', 'IICRC - The Institute of Inspection, Cleaning, and Restoration Certification', 'The IICRC is a certification and Standards Developing Organization (SDO) non-profit organization for the inspection, cleaning and restoration industries. In partnership with regional and international trade associates, the IICRC serves more than 25 countries with offices in the United States, Canada, United Kingdom, Australia, New Zealand and Japan.\nThe IICRC is the Institute of Inspection Cleaning and Restoration Certification, a non-profit organization for the Inspection, Cleaning, and Restoration Industries. The IICRC, originally named the International Institute of Carpet and Upholstery Cleaning Inc. (IICUC), was founded in 1972 by Ed York. Since starting in 1972, the IICRC has evolved into a global organization with more than 49,000 active Certified Technicians and more than 6,500 Certified Firms around the world.\nThe IICRC is managed by its Board of Directors, which is comprised of 15 industry leaders elected by the IICRC’s Shareholders. The Board of Directors’ function is to represent the various interests of the applicants while leading the direction of the organization. The Board of Directors meets four times per year and is tasked with the responsibility of helping shape future policies of the organization and uphold the standards that help shape the industry.\nThe IICRC Standards serve to develop common, industry-accepted language and terminology that enables us to more universally discuss concepts and procedures regarding cleaning, inspection, and restoration. The IICRC is an American National Standards Institute (ANSI) member and accredited standards developer. ANSI coordinates standards, conformity assessment, and related activities in the United States of America. ANSI is responsible for overseeing the development of national consensus standards and verifying that the requirements for due process, consensus, and other criteria for approval have been met by the standard’s developer. An American National Standard (ANS) is a Voluntary Consensus Standard, and unless mandated by law, compliance is voluntary. However, some have been adopted as code or regulation by local, state, or federal authorities.', 'IICRC là tổ chức phi lợi nhuận về chứng nhận và Tổ chức Phát triển Tiêu chuẩn (SDO) dành cho các ngành công nghiệp kiểm tra, vệ sinh và phục hồi. Hợp tác với các đối tác thương mại khu vực và quốc tế, IICRC phục vụ hơn 25 quốc gia với các văn phòng tại Hoa Kỳ, Canada, Vương quốc Anh, Úc, New Zealand và Nhật Bản.\nIICRC là Viện Chứng nhận Kiểm tra, Vệ sinh và Phục hồi, một tổ chức phi lợi nhuận dành cho các ngành công nghiệp Kiểm tra, Vệ sinh và Phục hồi. IICRC, ban đầu có tên là Viện Quốc tế về Vệ sinh Thảm và Đồ nội thất (IICUC), được thành lập vào năm 1972 bởi Ed York. Kể từ khi thành lập vào năm 1972, IICRC đã phát triển thành một tổ chức toàn cầu với hơn 49.000 Kỹ thuật viên được Chứng nhận đang hoạt động và hơn 6.500 Công ty được Chứng nhận trên toàn thế giới.\nIICRC được quản lý bởi Hội đồng quản trị, bao gồm 15 nhà lãnh đạo ngành do các Cổ đông của IICRC bầu ra. Chức năng của Hội đồng quản trị là đại diện cho các lợi ích khác nhau của người nộp đơn trong khi lãnh đạo định hướng của tổ chức. Hội đồng quản trị họp bốn lần một năm và được giao nhiệm vụ giúp định hình các chính sách tương lai của tổ chức và duy trì các tiêu chuẩn giúp định hình ngành.\nCác tiêu chuẩn IICRC phục vụ cho mục đích phát triển ngôn ngữ và thuật ngữ chung, được ngành chấp nhận, cho phép chúng ta thảo luận rộng rãi hơn về các khái niệm và quy trình liên quan đến vệ sinh, kiểm tra và phục hồi. IICRC là thành viên của Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) và là nhà phát triển tiêu chuẩn được công nhận. ANSI điều phối các tiêu chuẩn, đánh giá sự phù hợp và các hoạt động liên quan tại Hoa Kỳ. ANSI chịu trách nhiệm giám sát việc phát triển các tiêu chuẩn đồng thuận quốc gia và xác minh rằng các yêu cầu về quy trình hợp lệ, sự đồng thuận và các tiêu chí khác để phê duyệt đã được nhà phát triển tiêu chuẩn đáp ứng. Tiêu chuẩn Quốc gia Hoa Kỳ (ANS) là Tiêu chuẩn Đồng thuận Tự nguyện và việc tuân thủ là tự nguyện, trừ khi được luật pháp yêu cầu. Tuy nhiên, một số đã được các cơ quan chức năng địa phương, tiểu bang hoặc liên bang thông qua dưới dạng mã hoặc quy định.', 'IICRC là tổ chức phi lợi nhuận về chứng nhận và Tổ chức Phát triển Tiêu chuẩn (SDO) dành cho các ngành công nghiệp kiểm tra, vệ sinh và phục hồi. Hợp tác với các đối tác thương mại khu vực và quốc tế, IICRC phục vụ hơn 25 quốc gia với các văn phòng tại Hoa Kỳ, Canada, Vương quốc Anh, Úc, New Zealand và Nhật Bản.', NULL, NULL, '13*53', 'publisher/avatar/IDTALDC3S581MJUFRKJE.jpg', 0),
(4398, 'INCITS - InterNational Committee for Information Technology Standards (formerly NCITS)', 'INCITS - InterNational Committee for Information Technology Standards (formerly NCITS)', 'The InterNational Committee for Information Technology Standards (INCITS) is the forum of choice for information technology developers, producers and users for the creation and maintenance of formal de jure IT standards. INCITS is accredited by, and operates under rules approved by, the American National Standards Institute (ANSI). These rules are designed to ensure that voluntary standards are developed by the consensus of directly and materially affected interests. INCITS is sponsored by the Information Technology Industry Council (ITI), a trade association representing the leading U.S. providers of information technology products and services. ITI members employ more than one million people in the United States and in 2000, their revenues exceeded $668 billion worldwide.\nINCITS relies on the expertise of thousands of engineers, entrepreneurs, developers, and other top-notch professionals to create consensus-driven, market-relevant standards that are at the heart of the tech industry.  Through participation in INCITS, industry leaders and users alike have the opportunity, through standards, to open new markets, dismantle trade barriers, and create the foundation for the future information technology structure.\nA Leader at Home and Around the World\nAs the tech-standards leader at home and around the world, INCITS is the guiding force for global and U.S. information and communications technology standards.  Domestically, we create new American National Standards and, globally, we serve as the U.S. representative to the Joint Technical Committee 1 -- a premier international tech standards-setting organization.  This leadership role gives our members direct entry into the U.S. and global standards arena, and provides us with a strong platform to design the foundation for globally accepted, highly interoperable products.\nWe Match the Pace of Innovation\nINCITS members are information technology developers, producers, and users of cutting-edge technologies -- all sharing a material stake in the development of a standard.  That’s why we work to match the pace of innovation, constantly developing approaches for new technologies and updating standards for older products that are evolving through innovation.  We work with to develop standards before a product goes to market so it is broadly accepted and a success in the global marketplace.', 'Ủy ban Tiêu chuẩn Công nghệ Thông tin Quốc tế (INCITS) là diễn đàn được các nhà phát triển, nhà sản xuất và người dùng công nghệ thông tin lựa chọn để tạo ra và duy trì các tiêu chuẩn CNTT chính thức de jure. INCITS được công nhận và hoạt động theo các quy tắc được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) chấp thuận. Các quy tắc này được thiết kế để đảm bảo rằng các tiêu chuẩn tự nguyện được phát triển theo sự đồng thuận của các bên có lợi ích bị ảnh hưởng trực tiếp và đáng kể. INCITS được tài trợ bởi Hội đồng Công nghiệp Công nghệ Thông tin (ITI), một hiệp hội thương mại đại diện cho các nhà cung cấp sản phẩm và dịch vụ công nghệ thông tin hàng đầu của Hoa Kỳ. Các thành viên của ITI tuyển dụng hơn một triệu người tại Hoa Kỳ và vào năm 2000, doanh thu của họ đã vượt quá 668 tỷ đô la trên toàn thế giới.\nINCITS dựa vào chuyên môn của hàng nghìn kỹ sư, doanh nhân, nhà phát triển và các chuyên gia hàng đầu khác để tạo ra các tiêu chuẩn có liên quan đến thị trường, dựa trên sự đồng thuận, là trọng tâm của ngành công nghệ. Thông qua việc tham gia INCITS, các nhà lãnh đạo ngành và người dùng đều có cơ hội, thông qua các tiêu chuẩn, để mở ra thị trường mới, phá bỏ rào cản thương mại và tạo nền tảng cho cấu trúc công nghệ thông tin trong tương lai.\nMột nhà lãnh đạo trong nước và trên toàn thế giới\nLà nhà lãnh đạo về tiêu chuẩn công nghệ trong nước và trên toàn thế giới, INCITS là lực lượng chỉ đạo cho các tiêu chuẩn công nghệ thông tin và truyền thông toàn cầu và Hoa Kỳ. Trong nước, chúng tôi tạo ra các Tiêu chuẩn quốc gia Hoa Kỳ mới và trên toàn cầu, chúng tôi đóng vai trò là đại diện của Hoa Kỳ cho Ủy ban kỹ thuật chung 1 -- một tổ chức thiết lập tiêu chuẩn công nghệ quốc tế hàng đầu. Vai trò lãnh đạo này giúp các thành viên của chúng tôi có thể trực tiếp tham gia vào đấu trường tiêu chuẩn của Hoa Kỳ và toàn cầu, đồng thời cung cấp cho chúng tôi một nền tảng vững chắc để thiết kế nền tảng cho các sản phẩm có khả năng tương tác cao và được chấp nhận trên toàn cầu.\nChúng tôi bắt kịp tốc độ đổi mới\nCác thành viên của INCITS là những nhà phát triển, nhà sản xuất và người dùng công nghệ thông tin tiên tiến -- tất cả đều chia sẻ lợi ích vật chất trong quá trình phát triển một tiêu chuẩn. Đó là lý do tại sao chúng tôi nỗ lực bắt kịp tốc độ đổi mới, liên tục phát triển các phương pháp tiếp cận cho các công nghệ mới và cập nhật các tiêu chuẩn cho các sản phẩm cũ đang phát triển thông qua đổi mới. Chúng tôi hợp tác để phát triển các tiêu chuẩn trước khi một sản phẩm được đưa ra thị trường để sản phẩm được chấp nhận rộng rãi và thành công trên thị trường toàn cầu.', 'Ủy ban Tiêu chuẩn Công nghệ Thông tin Quốc tế (INCITS) là diễn đàn được các nhà phát triển, nhà sản xuất và người dùng công nghệ thông tin lựa chọn để tạo ra và duy trì các tiêu chuẩn CNTT chính thức de jure. INCITS được công nhận và hoạt động theo các quy tắc được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) chấp thuận.', NULL, NULL, '01*03.100*11*33*35*37', 'publisher/avatar/J8XA98UKJFH7HTE624XL.jpg', 0),
(4399, 'IPC - Association Connecting Electronics Industries', 'IPC - Association Connecting Electronics Industries', 'IPC serves more than 2,300 member companies worldwide involved in designing, manufacturing, specifying and/or using printed circuit boards. Approximately 200 standards, guidelines and technical reports cover topics ranging from design and printed circuit board manufacturing to electronics assembly and testing.', 'IPC (Association Connecting Electronics Industries) là một tổ chức quốc tế chuyên về các tiêu chuẩn và khảo nghiệm trong lĩnh vực công nghiệp điện tử. IPC được thành lập vào năm 1957 và có trụ sở tại Bannockburn, Illinois, Hoa Kỳ.\n\nIPC tập trung vào việc xây dựng và định hình các tiêu chuẩn và quy định trong ngành công nghiệp điện tử. Tổ chức này cung cấp hướng dẫn và quy định về thiết kế, sản xuất và kiểm tra các thành phần điện tử, bảng mạch in (PCB), kết nối và quy trình sản xuất điện tử.\n\nIPC cũng cung cấp các khóa đào tạo và chứng chỉ cho các chuyên gia và kỹ sư trong ngành công nghiệp điện tử. Các khóa đào tạo của IPC giúp cung cấp kiến thức và kỹ năng cần thiết về thiết kế, chế tạo, kiểm tra và quản lý chất lượng trong lĩnh vực công nghiệp điện tử.\n\nTổ chức này cũng đóng vai trò quan trọng trong việc tạo ra một mạng lưới kết nối các thành viên trong ngành công nghiệp điện tử. IPC tổ chức các hội thảo, triển lãm và sự kiện để tạo cơ hội giao lưu, chia sẻ kiến thức và thúc đẩy sự phát triển và hợp tác trong ngành công nghiệp điện tử.', 'IPC (Association Connecting Electronics Industries) là một tổ chức quốc tế chuyên về các tiêu chuẩn và khảo nghiệm trong lĩnh vực công nghiệp điện tử. IPC được thành lập vào năm 1957 và có trụ sở tại Bannockburn, Illinois, Hoa Kỳ.', 'IPC,ANSI/IPC', 'IPC, IPC standard, Hiệp hội Kết nối các Nhà Công nghiệp Điện tử Hoa Kỳ (IPC), Association Connecting Electronics Industries (IPC), Tiêu chuẩn hiệp hội', '65.060*31', 'publisher/avatar/4ZECCPGFJR4Y2OGY0Q8E.png', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4400, 'ISA - The International Society of Automation', 'ISA - The International Society of Automation', 'Founded in 1945, The International Society of Automation is a leading, global, nonprofit organization that is setting the standard for automation by helping over 30,000 worldwide members and other professionals solve difficult technical problems, while enhancing their leadership and personal career capabilities. Based in Research Triangle Park, North Carolina, ISA develops standards; certifies industry professionals; provides education and training; publishes books and technical articles; and hosts the largest conference and exhibition for automation professionals in the Western Hemisphere. ISA is the founding sponsor of The Automation Federation (www.automationfederation.org).', 'ISA (International Society of Automation) là một tổ chức quốc tế chuyên về công nghệ tự động hóa, hệ thống và công cụ. ISA được thành lập vào năm 1945 và có trụ sở tại Research Triangle Park, North Carolina, Hoa Kỳ.\n\nISA tập trung vào việc phát triển và thúc đẩy các tiêu chuẩn, hướng dẫn và chia sẻ kiến thức trong lĩnh vực tự động hóa, hệ thống và công cụ. Tổ chức này liên quan đến nhiều lĩnh vực công nghiệp, bao gồm tự động hóa quy trình, hệ thống điều khiển, công nghệ đo lường và kiểm soát, an toàn tự động hóa, và nhiều lĩnh vực khác.\n\nISA cung cấp các khóa đào tạo, chứng chỉ và tài liệu hướng dẫn để nâng cao kiến thức và kỹ năng của các chuyên gia và kỹ sư trong lĩnh vực tự động hóa và hệ thống. Tổ chức này tổ chức các hội thảo, hội nghị và sự kiện để tạo cơ hội trao đổi thông tin, thảo luận và hợp tác giữa các chuyên gia, nhà nghiên cứu và người làm việc trong ngành.\n\nISA cũng chịu trách nhiệm xác định và phát triển các tiêu chuẩn kỹ thuật trong lĩnh vực tự động hóa và hệ thống. Các tiêu chuẩn này đảm bảo tính tương thích, an toàn và hiệu quả của các công nghệ và thiết bị tự động hóa và hệ thống.\n\nVới sự tham gia của các chuyên gia, doanh nghiệp và cá nhân trong lĩnh vực tự động hóa và hệ thống, ISA đóng vai trò quan trọng trong việc thúc đẩy sự phát triển và tiến bộ công nghệ, cũng như tạo cơ hội hợp tác và trao đổi thông tin trong ngành tự động hóa toàn cầu.', 'ISA (International Society of Automation) là một tổ chức quốc tế chuyên về công nghệ tự động hóa, hệ thống và công cụ. ISA được thành lập vào năm 1945 và có trụ sở tại Research Triangle Park, North Carolina, Hoa Kỳ.', 'ISA,ANSI/ISA', 'ISA, ISA standard, Hiệp hội Công cụ, Hệ thống và Tự động Hoa Kỳ (ISA), Instrumentation, Systems, and Automation Society (ISA), Tự động hóa, Công cụ, Tiêu chuẩn hiệp hội', '23*23.060*25*25.040*29*29.060*33*33.060', 'publisher/avatar/JARHB7MKRB4IEGLJVSL6.jpg', 0),
(4401, 'ISEA - International Safety Equipment Association', 'ISEA - International Safety Equipment Association', 'ISEA, the International Safety Equipment Association, is an ANSI-accredited standards developing organization whose member companies are world leaders in the design and manufacturer of protective clothing and equipment used in factories, construction sites, hospitals and clinics, farms, schools, laboratories, emergency response and in the home. ISEA is represented on technical committees at ANSI, NFPA, ASTM, CSA and ISO, and they provide counsel to regulatory bodies, including NIOSH, MSHA and OSHA.\nThe International Safety Equipment Association (ISEA) is a trade association of manufacturers of personal protective equipment and other safety equipment, with its offices in Arlington, Virginia. More than 100 companies are members. The ISEA is the secretariat organization for several American National Standards Institute technical standards for products such as high visibility clothing, eye protection, hard hats, chemical and dust protection, hand protection, and others; formerly this role was filled by the American Society of Safety Engineers.\nThe organization was founded in 1933 as the Industrial Safety Equipment Association. It adopted its current name in 2000.[1] Since 2002 it has had a Web site accessible to the public and member organizations.[2] In addition to technical standards development and market research, the organization also provides representation of the safety products industry to the American government.\nISEA standards help protect over 125 million workers in the U.S., in product categories such as high visibility apparel, protective headwear, hand protection, emergency eyewash and shower equipment, and more. These standards are widely used for construction safety, in industrial settings, hospitals, laboratories, and factories.  \n \nOur standards are developed by safety equipment professionals and approved by the American National Standards Institute (ANSI).', 'ISEA, Hiệp hội Thiết bị An toàn Quốc tế, là một tổ chức phát triển tiêu chuẩn được ANSI công nhận, các công ty thành viên của tổ chức này là những công ty hàng đầu thế giới về thiết kế và sản xuất quần áo và thiết bị bảo hộ được sử dụng trong các nhà máy, công trường xây dựng, bệnh viện và phòng khám, trang trại, trường học, phòng thí nghiệm, ứng phó khẩn cấp và tại nhà. ISEA được đại diện trong các ủy ban kỹ thuật tại ANSI, NFPA, ASTM, CSA và ISO, và họ cung cấp tư vấn cho các cơ quan quản lý, bao gồm NIOSH, MSHA và OSHA.\nHiệp hội Thiết bị An toàn Quốc tế (ISEA) là một hiệp hội thương mại của các nhà sản xuất thiết bị bảo vệ cá nhân và các thiết bị an toàn khác, có văn phòng tại Arlington, Virginia. Hơn 100 công ty là thành viên. ISEA là tổ chức thư ký cho một số tiêu chuẩn kỹ thuật của Viện Tiêu chuẩn Quốc gia Hoa Kỳ đối với các sản phẩm như quần áo phản quang, bảo vệ mắt, mũ cứng, bảo vệ hóa chất và bụi, bảo vệ tay và các sản phẩm khác; trước đây vai trò này do Hiệp hội Kỹ sư An toàn Hoa Kỳ đảm nhiệm.\nTổ chức này được thành lập vào năm 1933 với tên gọi là Hiệp hội Thiết bị An toàn Công nghiệp. Tổ chức này đã đổi tên hiện tại vào năm 2000.[1] Từ năm 2002, tổ chức đã có một trang web mà công chúng và các tổ chức thành viên có thể truy cập.[2] Ngoài việc phát triển các tiêu chuẩn kỹ thuật và nghiên cứu thị trường, tổ chức này còn đại diện cho ngành sản phẩm an toàn cho chính phủ Hoa Kỳ.\nCác tiêu chuẩn ISEA giúp bảo vệ hơn 125 triệu công nhân tại Hoa Kỳ, trong các danh mục sản phẩm như trang phục phản quang, mũ bảo hộ, bảo vệ tay, thiết bị rửa mắt và tắm khẩn cấp, v.v. Các tiêu chuẩn này được sử dụng rộng rãi cho an toàn xây dựng, trong các môi trường công nghiệp, bệnh viện, phòng thí nghiệm và nhà máy.\n\nCác tiêu chuẩn của chúng tôi được phát triển bởi các chuyên gia về thiết bị an toàn và được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) chấp thuận.', 'ISEA, Hiệp hội Thiết bị An toàn Quốc tế, là một tổ chức phát triển tiêu chuẩn được ANSI công nhận, các công ty thành viên của tổ chức này là những công ty hàng đầu thế giới về thiết kế và sản xuất quần áo và thiết bị bảo hộ được sử dụng trong các nhà máy, công trường xây dựng, bệnh viện và phòng khám, trang trại, trường học, phòng thí nghiệm, ứng phó khẩn cấp và tại nhà.', NULL, NULL, NULL, 'publisher/avatar/W7MUK396E7925G87XPJW.jpg', 0),
(4402, 'ISO - International Organization for Standardization', 'ISO - International Organization for Standardization', 'ISO is a global federation of national standards bodies from approximately 100 countries. Today, ISO standards are accepted worldwide as the method by which manufacturers and service providers can achieve maximum convenience and efficiency in the exchange of goods and services.', 'Tổ chức Tiêu chuẩn hóa Quốc tế ISO (International Organization for Standardization ISO) là một tổ chức quốc tế độc lập, phi chính phủ gồm 163 thành viên là các cơ quan tiêu chuẩn quốc gia. Thông qua các thành viên, ISO tập hợp các chuyên gia để cùng chia sẻ kiến thức và xây dựng tiêu chuẩn quốc tế tự nguyện, dựa trên sự đồng thuận và thích hợp với thị trường, hỗ trợ đổi mới và cung cấp giải pháp đối với các thách thức toàn cầu.\n\nTiêu chuẩn quốc tế đưa ra quy định kỹ thuật cấp thế giới cho sản phẩm, dịch vụ và hệ thống để đảm bảo chất lượng, an toàn và hiệu quả. Các tiêu chuẩn là công cụ tạo thuận lợi thương mại quốc tế. Hiện nay, ISO đã công bố hơn 21.478 tiêu chuẩn quốc tế và các tài liệu liên quan, bao trùm gần như tất cả các ngành công nghiệp, từ công nghệ tới an toàn thực phẩm, nông nghiệp và chăm sóc sức khỏe. Tiêu chuẩn quốc tế ISO tác động tới mọi người, mọi nơi.\n\nISO được thành lập năm 1946 khi đoàn đại biểu từ 25 quốc gia gặp mặt tại Hiệp hội kỹ sư xây dựng ở Luân Đôn và quyết định thành lập một tổ chức quốc tế “để tạo thuận lợi cho hợp tác và thống nhất quốc tế các tiêu chuẩn công nghiệp”. Vào ngày 23/2/1947, tổ chức mới, ISO, chính thức bắt đầu hoạt động. Cơ cấu tổ chức của ISO bao gồm:\n\n-  Đại Hội đồng (General Assembly): là cơ quan có thẩm quyền cao nhất đối với tất cả các công việc của ISO. Đại hội đồng họp toàn thể mỗi năm một lần, gồm tất cả các nước thành viên và quan chức của ISO;\n\n-  Hội đồng ISO (ISO Council): chịu trách nhiệm về hầu hết các vấn đề quản lý. Hội đồng họp một năm hai lần gồm 20 thành viên được Đại Hội đồng ISO bầu ra, các cán bộ của ISO và Chủ tịch Uỷ ban Phát triển chính sách (CASCO, COPOLCO, DEVCO). Dưới Hội đồng là một số cơ quan cung cấp các hướng dẫn và quản lý về các vấn đề cụ thể:\n\nỦy ban Chủ tịch - tư vấn cho Hội đồng và giám sát việc thực hiện các quyết định của Hội đồng và Đại hội đồng.\nCASCO - cung cấp hướng dẫn về đánh giá sự phù hợp\nCOPOLCO - cung cấp hướng dẫn các vấn đề về người tiêu dùng\nDEVCO - cung cấp hướng dẫn về các vấn đề liên quan đến các quốc gia đang phát triển\nỦy ban Thường vụ Hội đồng - tư vấn về các vấn đề tài chính và chiến lược\nỦy ban đặc biệt - có thể được thành lập để thúc đẩy các mục tiêu và mục tiêu chiến lược của tổ chức\n-  Ban Quản lý Kỹ thuật (Technical Management Board - TMB): quản lý các hoạt động kỹ thuật. Cơ quan này cũng chịu trách nhiệm về các Ban kỹ thuật tiêu chuẩn và ban cố vấn chiến lược;\n\n-  Ban Thư ký Trung tâm (Central Secretariat): do Tổng Thư ký điều hành;\n\n-  Các Ban Kỹ thuật/Tiểu ban kỹ thuật (Technical Committees/Sub-Committees - ISO/TCs/SCs): tiến hành nghiên cứu, xây dựng các tiêu chuẩn và tài liệu dạng tiêu chuẩn của ISO.\n\nCác thành viên của ISO là các tổ chức tiêu chuẩn hàng đầu các nước và mỗi quốc gia chỉ có một thành viên đại diện. Mỗi thành viên đại diện cho ISO trong nước của mình. Các cá nhân hoặc công ty không thể giữ vai trò thành viên ISO.\n\nISO có ba loại hình thành viên. Mỗi loại đều có một mức độ tiếp cận và ảnh hưởng khác nhau đối với hệ thống ISO. Trong số 163 thành viên của ISO, có 119 thành viên đầy đủ, 40 thành viên thông tấn và 4 thành viên đăng ký. Điều này giúp ISO tính đến cũng như  nhận diện các nhu cầu và năng lực khác nhau của mỗi cơ quan tiêu chuẩn quốc gia.\n\nThành viên đầy đủ ảnh hưởng đến chiến lược và việc xây dựng tiêu chuẩn ISO bằng cách tham gia và bỏ phiếu trong các cuộc họp về chính sách và kỹ thuật của ISO. Thành viên đầy đủ có quyền bán và chấp nhận tiêu chuẩn quốc tế ISO tại quốc gia mình.\n\nThành viên thông tấn tham gia việc xây dựng tiêu chuẩn và chiến lược của ISO bằng cách tham dự các cuộc họp về chính sách và kỹ thuật ISO với tư cách quan sát viên. Các thành viên thông tấn có thể bán và chấp nhận tiêu chuẩn quốc tế ISO tại quốc gia.\n\nThành viên đăng ký duy trì việc cập nhật về công việc của ISO nhưng không thể tham gia. Họ không được bán hoặc chấp nhận tiêu chuẩn quốc tế ISO tại quốc gia.\n\nNgoài ra còn có 711 tổ chức quốc tế có quan hệ với các Ban Kỹ thuật và Tiểu ban kỹ thuật của ISO.\n\nHoạt động kỹ thuật của ISO được triển khai bởi 3.555 đơn vị kỹ thuật, trong đó có 247 ban kỹ thuật (TC), 508 tiểu ban kỹ thuật, 2.674 nhóm công tác và 126 nhóm đặc biệt. Tính đến ngày 31 tháng 12 năm 2016, ISO đã xây dựng được 21.478 tiêu chuẩn quốc tế và các tài liệu dạng tiêu chuẩn, trong đó có 27,3% về công nghệ kỹ thuật; 21,8% về công nghệ vật liệu; 17,7% về điện tử, công nghệ thông tin và viễn thông; 10,7% về giao thông vận tải và phân phối hàng hóa; 9,3% về các lĩnh vực chung, cơ sở hạ tầng, khoa học và dịch vụ; 5,6% về nông nghiệp và công nghệ thực phẩm; 4,1% về y tế, sức khỏe và môi trường; 2,5 % về xây dựng và 1,0% về công nghệ đặc biệt. Trong năm 2016, ISO đã tổ chức 1.509 cuộc họp kỹ thuật tại 45 quốc gia, xử lý 4.997 hạng mục công việc với 1.648 hạng mục công việc trong giai đoạn chuẩn bị + 754 dự thảo ban kỹ thuật + 2595 dự thảo tiêu chuẩn quốc tế (DIS) và dự thảo cuối tiêu chuẩn quốc tế (FDIS). công bố 1.381 tiêu chuẩn quốc tế và tài liệu dạng tiêu chuẩn.\n\nĐịa chỉ website của ISO: www.iso.org\n\nViệt Nam (đại diện là Tổng cục Tiêu chuẩn Đo lường Chất lượng) tham gia ISO từ năm 1977 và đã có những đóng góp nhất định cho tổ chức này. Việt Nam đã tham gia Hội đồng ISO trong 3 nhiệm kỳ: 1997 - 1998, 2001 - 2002 và 2004 - 2005; hiện tham gia với tư cách thành viên P (Thành viên chính thức) trong 17 Ban kỹ thuật và Tiểu ban Kỹ thuật của ISO; tham gia với tư cách thành viên O (Thành viên quan sát) trong 70 Ban kỹ thuật và Tiểu ban Kỹ thuật của ISO; là thành viên P của 2 ban phát triển chính sách của ISO: DEVCO (Ban về những vấn đề của các nước đang phát triển), CASCO (Ban Tiêu chuẩn và đánh giá sự phù hợp); thành viên O của Ban Chính sách người tiêu dùng COPOLCO và Ban Mẫu chuẩn (REMCO).', 'Tổ chức Tiêu chuẩn hóa Quốc tế ISO (International Organization for Standardization ISO) là một tổ chức quốc tế độc lập, phi chính phủ gồm 163 thành viên là các cơ quan tiêu chuẩn quốc gia.', 'ISO,IWA,ISO/ASTM,ISO/PAS,ISO/TS,ISO/TR,ISO/IEC', 'ISO, ISO standard, Tiêu chuẩn ISO, Tổ chức Tiêu chuẩn hóa Quốc tế ISO, International Organization for Standardization ISO, Tiêu chuẩn Quốc tế ISO', NULL, 'publisher/avatar/2OKEHO8EO5YI8V2CQPFQ.jpg', 0),
(4403, 'ISPE - International Society for Pharmaceutical Engineering', 'ISPE - International Society for Pharmaceutical Engineering', 'ISPE provides education, training, forums, and technical documents for professionals in pharmaceutical manufacturing. The Society publishes best-practice guides on a wide array of topics, including bulk pharmaceutical chemicals, sterile manufacturing facilities, commissioning and qualification, biopharmaceutical manufacturing facilities, and technology transfer.\nThe International Society for Pharmaceutical Engineering (ISPE) is a nonprofit association serving its members by leading scientific, technical, and regulatory advancement throughout the entire pharmaceutical lifecycle.\nMission Statement\nISPE is the global industry leader in connecting pharmaceutical knowledge to deliver manufacturing and supply chain innovation, operational excellence, and regulatory insights to enhance industry efforts to develop, manufacture and reliably deliver quality medicines to patients.\nVision Statement\nProvide solutions to complex pharmaceutical industry challenges through manufacturing innovation, member and workforce development, technical, regulatory, and compliance collaboration.\nWho We Are\nIn a world where the pursuit of excellence knows no boundaries, ISPE is shaping the future of the pharmaceutical industry. We are committed to the advancement of the educational and technical efficiency of our members.\nISPE was founded in 1980 by a handful of people who believed the pharmaceutical industry needed an organization that would deal with practical applications of science and technology for technical professionals. The much-needed forum provided by ISPE began with a membership of engineers in North America. We recognize and thank each of our Founding Members for their forethought and inspirational ideas, which led to ISPE’s establishment and have helped continued to impact who we are today.\nToday, our membership base has expanded far beyond engineering to include a broad representation of more than 21,000 pharmaceutical professionals, representing 120 countries. We also have ISPE Communities of Practice (CoPs), which serve as technical engines uniting professionals worldwide to generate meaningful content in our gold standard documents, training programs, and conference programs. ISPE CoPs cover 20 unique technical areas in the pharmaceutical industry, including GAMP® which celebrated its 30th anniversary in 2021. Professional communities include Affiliates/Chapters, Women in Pharma®, and Emerging Leaders. ISPE’s networking platform ISPE Engage continues to facilitate an open forum for all members and each community of practice to virtually connect and collaborate.\nTogether, we lead and facilitate the development of next-generation process technologies and innovative technical solutions. Our forums and events enable the exchange of ideas and practical experience. We also collaborate and provide support for groups such as the Global Pharmaceutical Manufacturing Leadership Forum (GPMLF).\nOn matters of regulation, our focus is on those requirements that impact — or will impact — the licensing of facilities, manufacturing processes and operations, and the sustainability of the supply chain over the product lifecycle. We are proud to have more than 2,600+ ISPE members from regulatory authorities representing 73 countries. We provide a neutral environment where members and experts can engage in open dialogue on issues that will ultimately benefit patients around the world.', 'ISPE cung cấp giáo dục, đào tạo, diễn đàn và tài liệu kỹ thuật cho các chuyên gia trong lĩnh vực sản xuất dược phẩm. Hiệp hội xuất bản các hướng dẫn thực hành tốt nhất về nhiều chủ đề, bao gồm hóa chất dược phẩm số lượng lớn, cơ sở sản xuất vô trùng, đưa vào vận hành và đủ điều kiện, cơ sở sản xuất dược phẩm sinh học và chuyển giao công nghệ.\nHiệp hội Kỹ thuật Dược phẩm Quốc tế (ISPE) là một hiệp hội phi lợi nhuận phục vụ các thành viên của mình bằng cách dẫn đầu sự tiến bộ về khoa học, kỹ thuật và quy định trong toàn bộ vòng đời dược phẩm.\nTuyên bố Sứ mệnh\nISPE là công ty hàng đầu toàn cầu trong ngành kết nối kiến ​​thức dược phẩm để mang lại sự đổi mới trong sản xuất và chuỗi cung ứng, sự xuất sắc trong hoạt động và hiểu biết về quy định để nâng cao nỗ lực của ngành nhằm phát triển, sản xuất và cung cấp thuốc chất lượng cho bệnh nhân một cách đáng tin cậy.\nTuyên bố Tầm nhìn\nCung cấp các giải pháp cho những thách thức phức tạp của ngành dược phẩm thông qua đổi mới sản xuất, phát triển thành viên và lực lượng lao động, hợp tác về kỹ thuật, quy định và tuân thủ.\nChúng tôi là ai\nTrong một thế giới mà việc theo đuổi sự xuất sắc không có ranh giới, ISPE đang định hình tương lai của ngành dược phẩm. Chúng tôi cam kết nâng cao hiệu quả giáo dục và kỹ thuật của các thành viên.\nISPE được thành lập vào năm 1980 bởi một nhóm nhỏ những người tin rằng ngành dược phẩm cần một tổ chức có thể giải quyết các ứng dụng thực tế của khoa học và công nghệ cho các chuyên gia kỹ thuật. Diễn đàn rất cần thiết do ISPE cung cấp bắt đầu với tư cách là thành viên của các kỹ sư ở Bắc Mỹ. Chúng tôi ghi nhận và cảm ơn từng Thành viên sáng lập vì những ý tưởng sáng suốt và đầy cảm hứng của họ, dẫn đến việc thành lập ISPE và tiếp tục tác động đến chúng tôi ngày nay.\nNgày nay, cơ sở thành viên của chúng tôi đã mở rộng vượt xa lĩnh vực kỹ thuật để bao gồm hơn 21.000 chuyên gia dược phẩm, đại diện cho 120 quốc gia. Chúng tôi cũng có Cộng đồng thực hành (CoP) của ISPE, đóng vai trò là động lực kỹ thuật đoàn kết các chuyên gia trên toàn thế giới để tạo ra nội dung có ý nghĩa trong các tài liệu tiêu chuẩn vàng, chương trình đào tạo và chương trình hội nghị của chúng tôi. ISPE CoP bao gồm 20 lĩnh vực kỹ thuật độc đáo trong ngành dược phẩm, bao gồm GAMP® đã kỷ niệm 30 năm thành lập vào năm 2021. Các cộng đồng chuyên nghiệp bao gồm Chi nhánh/Chi hội, Phụ nữ trong ngành Dược® và Lãnh đạo mới nổi. Nền tảng mạng ISPE Engage của ISPE tiếp tục tạo điều kiện cho một diễn đàn mở cho tất cả các thành viên và mỗi cộng đồng thực hành để kết nối và cộng tác ảo.\nChúng tôi cùng nhau lãnh đạo và tạo điều kiện cho sự phát triển của các công nghệ quy trình thế hệ tiếp theo và các giải pháp kỹ thuật sáng tạo. Các diễn đàn và sự kiện của chúng tôi cho phép trao đổi ý tưởng và kinh nghiệm thực tế. Chúng tôi cũng hợp tác và hỗ trợ cho các nhóm như Diễn đàn lãnh đạo sản xuất dược phẩm toàn cầu (GPMLF).\nVề các vấn đề quy định, chúng tôi tập trung vào các yêu cầu có tác động — hoặc sẽ tác động — đến việc cấp phép cho các cơ sở, quy trình và hoạt động sản xuất, cũng như tính bền vững của chuỗi cung ứng trong suốt vòng đời sản phẩm. Chúng tôi tự hào có hơn 2.600 thành viên ISPE từ các cơ quan quản lý đại diện cho 73 quốc gia. Chúng tôi cung cấp một môi trường trung lập, nơi các thành viên và chuyên gia có thể tham gia vào cuộc đối thoại cởi mở về các vấn đề cuối cùng sẽ mang lại lợi ích cho bệnh nhân trên toàn thế giới.', 'ISPE cung cấp giáo dục, đào tạo, diễn đàn và tài liệu kỹ thuật cho các chuyên gia trong lĩnh vực sản xuất dược phẩm. Hiệp hội xuất bản các hướng dẫn thực hành tốt nhất về nhiều chủ đề, bao gồm hóa chất dược phẩm số lượng lớn, cơ sở sản xuất vô trùng, đưa vào vận hành và đủ điều kiện, cơ sở sản xuất dược phẩm sinh học và chuyển giao công nghệ.', NULL, NULL, NULL, 'publisher/avatar/9JT3UJTNHA193YINHBZX.jpg', 0),
(4404, 'ISTA - International Safe Transit Association', 'ISTA - International Safe Transit Association', 'The International Safe Transit Association (ISTA) is an organization focused on the specific concerns of transport packaging and our mission is to develop and deliver standards, educational programs and tools for the economic, social and environmental optimization of packaging systems. ISTA pioneered the concept of package performance testing and certification over 60 years ago and today our test procedures, standards and certification programs are at the forefront of Responsible Transport Packaging.\nOur Mission\nTo empower organizations and their people to minimize product damage throughout distribution and optimize resource usage through effective package design.\nOur Vision\nTo be the leading inspiration and resource for improving our world through transport packaging globally.', 'Hiệp hội Vận tải An toàn Quốc tế (ISTA) là một tổ chức tập trung vào các mối quan tâm cụ thể về bao bì vận chuyển và sứ mệnh của chúng tôi là phát triển và cung cấp các tiêu chuẩn, chương trình giáo dục và công cụ để tối ưu hóa kinh tế, xã hội và môi trường của các hệ thống bao bì. ISTA đã tiên phong trong khái niệm thử nghiệm và chứng nhận hiệu suất bao bì hơn 60 năm trước và ngày nay các quy trình thử nghiệm, tiêu chuẩn và chương trình chứng nhận của chúng tôi đang đi đầu trong Bao bì Vận chuyển Có trách nhiệm.\nSứ mệnh của chúng tôi\nTrao quyền cho các tổ chức và nhân viên của họ để giảm thiểu thiệt hại sản phẩm trong suốt quá trình phân phối và tối ưu hóa việc sử dụng tài nguyên thông qua thiết kế bao bì hiệu quả.\nTầm nhìn của chúng tôi\nTrở thành nguồn cảm hứng và nguồn lực hàng đầu để cải thiện thế giới của chúng ta thông qua bao bì vận chuyển trên toàn cầu.', 'Hiệp hội Vận tải An toàn Quốc tế (ISTA) là một tổ chức tập trung vào các mối quan tâm cụ thể về bao bì vận chuyển và sứ mệnh của chúng tôi là phát triển và cung cấp các tiêu chuẩn, chương trình giáo dục và công cụ để tối ưu hóa kinh tế, xã hội và môi trường của các hệ thống bao bì.', NULL, NULL, NULL, 'publisher/avatar/T6NOWFFB2LB1XH0OI6WA.jpg', 0),
(4405, 'ISUZU - Isuzu Motors Ltd.Moving the World - for You', 'ISUZU - Isuzu Motors Ltd.Moving the World - for You', 'ISUZU - Isuzu Motors Ltd.Moving the World - for You', NULL, NULL, NULL, NULL, NULL, 'publisher/avatar/WFK3BR3JRRVPH5JW652M.png', 0),
(4406, 'JEDEC - JEDEC Solid State Technology Association', 'JEDEC - JEDEC Solid State Technology Association', 'JEDEC is the global leader in developing open standards for the microelectronics industry. With over 4,000 volunteers representing nearly 300 member companies. JEDEC brings manufacturers and suppliers together on 50 different committees, creating standards to meet the diverse technical and developmental needs of the industry. These collaborations ensure product interoperability, benefiting the industry and ultimately consumers by decreasing time-to-market and reducing product development costs.\nJEDEC is the global leader in developing open standards for the microelectronics industry, with more than 3,000 volunteers representing over 350 member companies.\nJEDEC members have valuable access to pre-publication materials and proposals that put them ahead of the competition. Join JEDEC today and discover how membership will benefit your company.\nJEDEC brings manufacturers and suppliers together to participate in more than 50 committees and subcommittees, with the mission to create standards to meet the diverse technical and developmental needs of the industry.\nJEDEC’s collaborative efforts ensure product interoperability, benefiting the industry and ultimately consumers by decreasing time-to-market and reducing product development costs.\nJEDEC publications and standards are adopted worldwide.  JEDEC is accredited by ANSI and maintains liaisons with numerous standards bodies throughout the world.\nBest Practices in Setting Standards\nSince 1958, JEDEC has earned a reputation for upholding a fair, efficient and economical process for setting standards.\nMember companies choose from over 50 committees and subcommittees in which to participate. Gathering several times a year in locations worldwide, these committees address the varied needs of the industry, including discrete solid state devices, integrated circuits, electronic modules, various manufacturing support functions and much more.\nAdhering to JEDEC\'s \"one company, one vote\" rule, members vote on proposals electronically using JEDEC’s online voting system prior to committee meetings. Voting results are then reported at meetings and modifications to the proposals are made in response to voter-submitted comments.\nUpon committee approval, finalized standards proposals are submitted to the Board of Directors for approval — with published standards made available on the JEDEC website.\nEducational Forums\nJEDEC conducts workshops and conferences throughout the year in various locations worldwide. Visit our meetings and events calendar for the most up-to-date information on educational opportunities.', 'JEDEC là đơn vị dẫn đầu toàn cầu trong việc phát triển các tiêu chuẩn mở cho ngành vi điện tử. Với hơn 4.000 tình nguyện viên đại diện cho gần 300 công ty thành viên. JEDEC tập hợp các nhà sản xuất và nhà cung cấp lại với nhau trong 50 ủy ban khác nhau, tạo ra các tiêu chuẩn để đáp ứng các nhu cầu phát triển và kỹ thuật đa dạng của ngành. Những sự hợp tác này đảm bảo khả năng tương tác của sản phẩm, mang lại lợi ích cho ngành và cuối cùng là người tiêu dùng bằng cách giảm thời gian đưa sản phẩm ra thị trường và giảm chi phí phát triển sản phẩm.\nJEDEC là đơn vị dẫn đầu toàn cầu trong việc phát triển các tiêu chuẩn mở cho ngành vi điện tử, với hơn 3.000 tình nguyện viên đại diện cho hơn 350 công ty thành viên.\nCác thành viên của JEDEC có quyền truy cập có giá trị vào các tài liệu và đề xuất trước khi xuất bản giúp họ vượt lên trước đối thủ cạnh tranh. Hãy tham gia JEDEC ngay hôm nay và khám phá cách tư cách thành viên sẽ mang lại lợi ích cho công ty của bạn.\nJEDEC tập hợp các nhà sản xuất và nhà cung cấp lại với nhau để tham gia vào hơn 50 ủy ban và tiểu ban, với sứ mệnh tạo ra các tiêu chuẩn để đáp ứng các nhu cầu phát triển và kỹ thuật đa dạng của ngành.\nNhững nỗ lực hợp tác của JEDEC đảm bảo khả năng tương tác của sản phẩm, mang lại lợi ích cho ngành và cuối cùng là người tiêu dùng bằng cách giảm thời gian đưa sản phẩm ra thị trường và giảm chi phí phát triển sản phẩm.\nCác ấn phẩm và tiêu chuẩn của JEDEC được áp dụng trên toàn thế giới. JEDEC được ANSI công nhận và duy trì mối quan hệ với nhiều tổ chức tiêu chuẩn trên toàn thế giới.\nCác thông lệ tốt nhất trong việc thiết lập tiêu chuẩn\nKể từ năm 1958, JEDEC đã tạo dựng được danh tiếng về việc duy trì quy trình công bằng, hiệu quả và tiết kiệm để thiết lập tiêu chuẩn.\nCác công ty thành viên lựa chọn từ hơn 50 ủy ban và tiểu ban để tham gia. Các ủy ban này họp nhiều lần trong năm tại các địa điểm trên toàn thế giới, giải quyết các nhu cầu đa dạng của ngành, bao gồm các thiết bị bán dẫn rời rạc, mạch tích hợp, mô-đun điện tử, nhiều chức năng hỗ trợ sản xuất khác nhau và nhiều hơn nữa.\nTuân thủ quy tắc \"một công ty, một phiếu bầu\" của JEDEC, các thành viên bỏ phiếu cho các đề xuất bằng phương thức điện tử bằng hệ thống bỏ phiếu trực tuyến của JEDEC trước các cuộc họp của ủy ban. Sau đó, kết quả bỏ phiếu được báo cáo tại các cuộc họp và các sửa đổi đối với các đề xuất được thực hiện để phản hồi các ý kiến ​​do cử tri gửi đến.\nSau khi ủy ban chấp thuận, các đề xuất tiêu chuẩn cuối cùng sẽ được đệ trình lên Hội đồng quản trị để phê duyệt — với các tiêu chuẩn đã công bố được cung cấp trên trang web của JEDEC.\nDiễn đàn giáo dục\nJEDEC tổ chức các hội thảo và hội nghị trong suốt cả năm tại nhiều địa điểm khác nhau trên toàn thế giới. Truy cập lịch họp và sự kiện của chúng tôi để biết thông tin mới nhất về các cơ hội giáo dục.', 'JEDEC là đơn vị dẫn đầu toàn cầu trong việc phát triển các tiêu chuẩn mở cho ngành vi điện tử. Với hơn 4.000 tình nguyện viên đại diện cho gần 300 công ty thành viên. JEDEC tập hợp các nhà sản xuất và nhà cung cấp lại với nhau trong 50 ủy ban khác nhau, tạo ra các tiêu chuẩn để đáp ứng các nhu cầu phát triển và kỹ thuật đa dạng của ngành. Những sự hợp tác này đảm bảo khả năng tương tác của sản phẩm, mang lại lợi ích cho ngành và cuối cùng là người tiêu dùng bằng cách giảm thời gian đưa sản phẩm ra thị trường và giảm chi phí phát triển sản phẩm.', NULL, NULL, NULL, 'publisher/avatar/KA5XY6GBQFD5G620JYDZ.jpg', 0),
(4408, 'LIA - Laser Institute of AmericaLaser Institute of America', 'LIA - Laser Institute of AmericaLaser Institute of America', 'founded in 1968, is the professional society for laser applications and safety. Our mission is to foster lasers, laser applications, and laser safety worldwide. LIA cultivates innovation, ingenuity and inspiration to promote the continued growth and safe use of laser applications.\nThe Laser Institute (LIA), a 501(c)(3) nonprofit organization, is not only your guide in the manufacturing world of laser technology, but we\'re also the publisher of the Z136 series laser safety standards and the Journal of Laser Applications. As an unbiased authority with decades of history in the field, we are committed to elevating your understanding and application of laser technology, ensuring you remain at the cutting edge of manufacturing innovation.\nOur support extends through a focused range of offerings, including comprehensive laser safety training, specialized workshops, and industry conferences. These platforms provide invaluable opportunities for networking and learning from top experts and peers in the field. By engaging with LIA, you gain access to essential resources and a professional community, all dedicated to excellence in laser applications and laser safety.', 'Được thành lập vào năm 1968, LIA là hiệp hội chuyên nghiệp về ứng dụng và an toàn laser. Sứ mệnh của chúng tôi là thúc đẩy laser, ứng dụng laser và an toàn laser trên toàn thế giới. LIA nuôi dưỡng sự đổi mới, sáng tạo và cảm hứng để thúc đẩy sự phát triển liên tục và sử dụng an toàn các ứng dụng laser.\nViện Laser (LIA), một tổ chức phi lợi nhuận 501(c)(3), không chỉ là người hướng dẫn bạn trong thế giới sản xuất công nghệ laser mà chúng tôi còn là nhà xuất bản các tiêu chuẩn an toàn laser dòng Z136 và Tạp chí Ứng dụng Laser. Là một cơ quan có thẩm quyền công bằng với nhiều thập kỷ lịch sử trong lĩnh vực này, chúng tôi cam kết nâng cao hiểu biết và ứng dụng của bạn về công nghệ laser, đảm bảo bạn luôn đi đầu trong đổi mới sản xuất.\nSự hỗ trợ của chúng tôi mở rộng thông qua một loạt các dịch vụ tập trung, bao gồm đào tạo an toàn laser toàn diện, hội thảo chuyên ngành và hội nghị ngành. Các nền tảng này cung cấp các cơ hội vô giá để kết nối và học hỏi từ các chuyên gia và đồng nghiệp hàng đầu trong lĩnh vực này. Bằng cách tham gia với LIA, bạn có quyền truy cập vào các nguồn lực thiết yếu và một cộng đồng chuyên nghiệp, tất cả đều dành riêng cho sự xuất sắc trong các ứng dụng laser và an toàn laser.', 'Được thành lập vào năm 1968, LIA là hiệp hội chuyên nghiệp về ứng dụng và an toàn laser. Sứ mệnh của chúng tôi là thúc đẩy laser, ứng dụng laser và an toàn laser trên toàn thế giới. LIA nuôi dưỡng sự đổi mới, sáng tạo và cảm hứng để thúc đẩy sự phát triển liên tục và sử dụng an toàn các ứng dụng laser.', NULL, NULL, NULL, 'publisher/avatar/8WSKA26XE6GC4GAIUCJN.jpg', 0),
(4409, 'MBMA - Metal Building Manufacturers Association', 'MBMA - Metal Building Manufacturers Association', 'MBMA provides leadership, research, and education that increase the prominence and usage of metal building systems as the premier solution for performance, aesthetics, and sustainability in building construction.\nFor over 60 years the MBMA and its manufacturing members have worked together as partners to further its mission: to conduct research, to help advance building codes and standards, and to educate the construction community. Our passion is to support a strong, sustainable metal building systems industry that meets the needs of owners and the overall society..\nMetal building systems are far more sophisticated today than they were a decade ago; and due to MBMA’s leading edge research programs, further evolution is not far down the road. MBMA has invested heavily in engineering technology, fabrication concepts, structural improvements, and building quality. As a result, buildings today are far better in terms of cost, strength, function, and aesthetics. Through these innovations, we are moving the industry to a higher level and helping to position the industry for long-term growth and greater acceptance. Metal is the solution for most low-rise buildings.\nIf you’d like immediate information, give us a call. If you would like to become a member of MBMA\nBy becoming a member of MBMA, you can participate directly in MBMA\'s research and code activities, energy and sustainability projects, and insurance and safety programs. This work is achieved through nine committees that are comprised of companies just like yours that want to make a difference in our industry. This is a membership driven association, so be prepared to take an active role.\nApplications for membership are provided below. If you would like to speak to someone directly about the benefits of membership in MBMA, feel free to call (216) 241-7333 to speak to a representative.\nStandards\nThe International Building Code (IBC) developed the framework for code compliance. It references nationally recognized standards for determining design loads (wind, snow, seismic, etc.) and for the design of most materials such as wood, concrete, and steel. A design begins by determining the environmental loads the building will be subjected to. These are found in ASCE 7, published by the American Society of Civil Engineers.\nThe steel references in the IBC point designers to the American Institute of Steel Construction (AISC) for hot-rolled and built-up plate beams and columns and the American Iron and Steel Institute (AISI) for cold-formed steel members, such as Z and C roof purlins and wall girts. Metal building system designs are required to comply with both the AISC and the AISI specifications.', 'MBMA cung cấp sự lãnh đạo, nghiên cứu và giáo dục giúp tăng cường sự nổi bật và việc sử dụng các hệ thống tòa nhà kim loại như giải pháp hàng đầu về hiệu suất, tính thẩm mỹ và tính bền vững trong xây dựng công trình.\nTrong hơn 60 năm, MBMA và các thành viên sản xuất đã hợp tác với nhau như những đối tác để thúc đẩy sứ mệnh của mình: tiến hành nghiên cứu, giúp thúc đẩy các quy định và tiêu chuẩn xây dựng và giáo dục cộng đồng xây dựng. Niềm đam mê của chúng tôi là hỗ trợ một ngành công nghiệp hệ thống tòa nhà kim loại bền vững, mạnh mẽ đáp ứng nhu cầu của chủ sở hữu và toàn xã hội.\nCác hệ thống tòa nhà kim loại ngày nay tinh vi hơn nhiều so với một thập kỷ trước; và nhờ các chương trình nghiên cứu tiên tiến của MBMA, sự phát triển hơn nữa sẽ không còn xa nữa. MBMA đã đầu tư mạnh vào công nghệ kỹ thuật, khái niệm chế tạo, cải tiến kết cấu và chất lượng tòa nhà. Do đó, các tòa nhà ngày nay tốt hơn nhiều về mặt chi phí, độ bền, chức năng và tính thẩm mỹ. Thông qua những đổi mới này, chúng tôi đang đưa ngành công nghiệp lên một tầm cao mới và giúp định vị ngành công nghiệp để tăng trưởng dài hạn và được chấp nhận rộng rãi hơn. Kim loại là giải pháp cho hầu hết các tòa nhà thấp tầng.\nNếu bạn muốn có thông tin ngay lập tức, hãy gọi cho chúng tôi. Nếu bạn muốn trở thành thành viên của MBMA\nBằng cách trở thành thành viên của MBMA, bạn có thể tham gia trực tiếp vào các hoạt động nghiên cứu và mã của MBMA, các dự án năng lượng và phát triển bền vững, các chương trình bảo hiểm và an toàn. Công việc này được thực hiện thông qua chín ủy ban bao gồm các công ty giống như công ty của bạn muốn tạo ra sự khác biệt trong ngành của chúng tôi. Đây là một hiệp hội do thành viên điều hành, vì vậy hãy chuẩn bị để đảm nhận vai trò tích cực.\nCác đơn đăng ký thành viên được cung cấp bên dưới. Nếu bạn muốn trao đổi trực tiếp với ai đó về các lợi ích của tư cách thành viên MBMA, vui lòng gọi đến số (216) 241-7333 để trao đổi với đại diện.\nTiêu chuẩn\nBộ luật xây dựng quốc tế (IBC) đã phát triển khuôn khổ để tuân thủ bộ luật. Bộ luật này tham chiếu các tiêu chuẩn được công nhận trên toàn quốc để xác định tải trọng thiết kế (gió, tuyết, động đất, v.v.) và để thiết kế hầu hết các vật liệu như gỗ, bê tông và thép. Thiết kế bắt đầu bằng cách xác định tải trọng môi trường mà tòa nhà sẽ phải chịu. Những tải trọng này có trong ASCE 7, do Hiệp hội Kỹ sư xây dựng Hoa Kỳ xuất bản.\nCác tham chiếu về thép trong IBC hướng các nhà thiết kế đến Viện Xây dựng Thép Hoa Kỳ (AISC) đối với dầm và cột tấm cán nóng và lắp ghép và Viện Sắt và Thép Hoa Kỳ (AISI) đối với các thành phần thép cán nguội, chẳng hạn như xà gồ mái Z và C và dầm tường. Các thiết kế hệ thống tòa nhà bằng kim loại phải tuân thủ cả thông số kỹ thuật của AISC và AISI.', 'MBMA cung cấp sự lãnh đạo, nghiên cứu và giáo dục giúp tăng cường sự nổi bật và việc sử dụng các hệ thống tòa nhà kim loại như giải pháp hàng đầu về hiệu suất, tính thẩm mỹ và tính bền vững trong xây dựng công trình.', NULL, NULL, NULL, 'publisher/avatar/8DQY3VC4ZS60S6AFVCMO.jpg', 0),
(4410, 'MCGRAW-HILL - McGraw-Hill Publishing Company', 'MCGRAW-HILL - McGraw-Hill Publishing Company', 'Learn how we\'re working to expand the possibilities of content and technology to support learning in a connected world.\nOur vision is to unlock the potential of each learner at every stage of life. At McGraw Hill, we believe that your diverse experiences enrich the way you learn, teach, and grow. We know that no two journeys are the same, and support your path wherever it may take you – helping you achieve success on your own terms.\nAs a leading global education company, our mission is to partner with educators, learners, and professionals to help them access all the value that education can offer, no matter where their starting points may be.  Through high-quality, trusted content developed with world-class authors – and flexible tools to meet the needs of different teaching and learning styles – our digital platforms adapt to help meet learners where they are, and advance with them as they progress toward their goals.\n \nFor over 130 years, we have never stopped innovating to meet the ever-changing needs of educators and learners around the world – and will continue to support and celebrate their efforts every step of the way.\nAt McGraw Hill, we believe the learning journey never ends. We are driven by our passion to create the highest quality, most accessible and affordable solutions for learners and educators around the world, from PreK through higher education, into professional and beyond.', 'Tìm hiểu cách chúng tôi đang nỗ lực mở rộng khả năng của nội dung và công nghệ để hỗ trợ việc học trong một thế giới kết nối.\nTầm nhìn của chúng tôi là khai mở tiềm năng của mỗi người học ở mọi giai đoạn của cuộc sống. Tại McGraw Hill, chúng tôi tin rằng những trải nghiệm đa dạng của bạn sẽ làm phong phú thêm cách bạn học, giảng dạy và phát triển. MCGRAW-HILL biết rằng không có hai hành trình nào giống nhau và sẽ hỗ trợ con đường của bạn bất kể nó đưa bạn đến đâu - giúp bạn đạt được thành công theo cách của riêng mình.\nLà một công ty giáo dục toàn cầu hàng đầu, sứ mệnh của MCGRAW-HILL là hợp tác với các nhà giáo dục, người học và chuyên gia để giúp họ tiếp cận mọi giá trị mà giáo dục có thể mang lại, bất kể điểm xuất phát của họ có thể ở đâu. Thông qua nội dung đáng tin cậy, chất lượng cao được phát triển với các tác giả đẳng cấp thế giới - và các công cụ linh hoạt để đáp ứng nhu cầu của các phong cách giảng dạy và học tập khác nhau - các nền tảng kỹ thuật số của chúng tôi thích ứng để giúp đáp ứng người học ở bất cứ nơi nào họ đang ở và tiến lên cùng họ khi họ tiến tới mục tiêu của mình.\n\nTrong hơn 130 năm, MCGRAW-HILL chưa bao giờ ngừng đổi mới để đáp ứng nhu cầu luôn thay đổi của các nhà giáo dục và người học trên toàn thế giới - và sẽ tiếp tục hỗ trợ và tôn vinh những nỗ lực của họ trong từng bước đi.\nTại McGraw Hill, chúng tôi tin rằng hành trình học tập không bao giờ kết thúc. MCGRAW-HILL được thúc đẩy bởi niềm đam mê tạo ra các giải pháp chất lượng cao nhất, dễ tiếp cận nhất và giá cả phải chăng nhất cho người học và nhà giáo dục trên toàn thế giới, từ bậc mẫu giáo đến giáo dục đại học, đến chuyên nghiệp và hơn thế nữa.', 'Là một công ty giáo dục toàn cầu hàng đầu, sứ mệnh của MCGRAW-HILL là hợp tác với các nhà giáo dục, người học và chuyên gia để giúp họ tiếp cận mọi giá trị mà giáo dục có thể mang lại, bất kể điểm xuất phát của họ có thể ở đâu. Thông qua nội dung đáng tin cậy, chất lượng cao được phát triển với các tác giả đẳng cấp thế giới - và các công cụ linh hoạt để đáp ứng nhu cầu của các phong cách giảng dạy và học tập khác nhau - các nền tảng kỹ thuật số của chúng tôi thích ứng để giúp đáp ứng người học ở bất cứ nơi nào họ đang ở và tiến lên cùng họ khi họ tiến tới mục tiêu của mình.', NULL, NULL, NULL, 'publisher/avatar/YCG8IFUIMMZSS9OLAR6A.jpg', 0),
(4411, 'MIL - Military Specifications and Standards', 'MIL - Military Specifications and Standards', 'Cut hours of search time down to minutes when you order Mil Specs at Techstreet. Get easy checkout, immediate download and free email alerts when changes and reactivations are issued. Online orders even earn Techpoint Rewards! For enterprise access, a web-based subscription serves end-users with automatic updates and desktop tools that help organize and track documents. Get just the sections you need or the entire Mil database. Our Web 2.0 interface is fast and easy to use. Perfect for every department: from research and design to purchasing, bidding and logistics.', 'MIL (Military Specifications and Standards) là hệ thống quy chuẩn kỹ thuật quốc phòng của Hoa Kỳ. MIL được sử dụng để xác định các yêu cầu kỹ thuật và tiêu chuẩn chất lượng cho các sản phẩm và dịch vụ được sử dụng trong lĩnh vực quốc phòng.\n\nHệ thống quy chuẩn MIL bao gồm các quy chuẩn (specifications) và tiêu chuẩn (standards) được phát triển bởi Bộ Quốc phòng Hoa Kỳ (Department of Defense - DoD) hoặc các cơ quan liên quan khác. Các tiêu chuẩn MIL thường được sử dụng trong việc đặt hàng, thiết kế, chế tạo và kiểm tra các sản phẩm và dịch vụ quốc phòng.\n\nQuy chuẩn MIL bao gồm nhiều lĩnh vực khác nhau, bao gồm điện tử, cơ khí, vật liệu, hóa chất, quản lý chất lượng, kiểm tra và đo lường, bảo vệ môi trường, và nhiều lĩnh vực khác. Mỗi quy chuẩn MIL có các yêu cầu cụ thể về thiết kế, vật liệu, hiệu suất, thử nghiệm và xác nhận tuân thủ.\n\nTuy nhiên, từ năm 1994, hệ thống quy chuẩn MIL đã chuyển dần sang hệ thống quy chuẩn kỹ thuật quốc phòng mới gọi là hệ thống quy chuẩn Công nghiệp Quốc phòng Hoa Kỳ (United States Department of Defense - DoD - Defense Standardization Program - DSP). DSP cung cấp các tiêu chuẩn kỹ thuật và quy định chất lượng tương tự như MIL trước đây.\n\nLưu ý rằng thông tin này dựa trên kiến thức của tôi đến năm 2021, và có thể có sự thay đổi hoặc cập nhật về hệ thống quy chuẩn quốc phòng của Hoa Kỳ sau này.', 'MIL (Military Specifications and Standards) là hệ thống quy chuẩn kỹ thuật quốc phòng của Hoa Kỳ. MIL được sử dụng để xác định các yêu cầu kỹ thuật và tiêu chuẩn chất lượng cho các sản phẩm và dịch vụ được sử dụng trong lĩnh vực quốc phòng.', 'MIL,ANSI/MIL', 'MIL, Quy chuẩn Kỹ thuật Quốc phòng Hoa Kỳ (MIL), Quy chuẩn Kỹ thuật Quốc phòng Hoa Kỳ (MIL), Military Specifications (MIL), Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', NULL, 'publisher/avatar/4HSXN33X91ENR4WPAVJ4.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4412, 'MPIF - Metal Powder Industries Federation', 'MPIF - Metal Powder Industries Federation', 'The Metal Powder Industries Federation is a federation of six trade associations representing various aspects of powder metallurgy (PM), metal powders, and particulate materials. MPIF\'s mission is to advance the interests of the metal powder producing and consuming industries.\nThe Metal Powder Industries Federation (MPIF) is a \"not-for-profit association\" formed by the powder metallurgy industry to advance the interests of the metal powder producing and consuming industries.\nThe Federation is composed of six trade associations that are concerned with some aspect of powder metallurgy, metal powders, or particulate materials.\nThroughout its long history, MPIF has been a champion of this innovative technology, providing our member companies with a long list of services that help advance the art and science of powder metallurgy while promoting its benefits to prospective end users.\nHistory of the Metal Powder Industries Federation\nMPIF traces its roots to the closing days of World War II when a group of entrepreneurs engaged in the still-fledgling industry involved in making parts from metal powder were faced with a looming crisis.\nWith the close of the war, the industry—which until then had consisted primarily of self-lubricating bearings—would be saddled with a severe surplus production capacity that had been geared up for the war effort. That is, unless the industry could expand its existing markets and develop new ones in what was sure to be a period of economic boom as GIs came home to resume life as consumers.\nTo promote the technology to a then-skeptical engineering community, to develop the essential standards and testing methods customers would demand, and to obtain crucial and reliable statistical data about the vitality of the industry and its future prospects, the industry would need to set aside differences and speak with single voice. So these pioneers arrived at a momentous decision: they would form a trade association.\nWhat began as a single association embracing all the diverse players involved in the industry eventually evolved into a federation serving as an umbrella over six different associations, each representing a distinct segment of the industry:\n• Powder Metallurgy Parts Association\n• Metal Powder Producers Association\n• Powder Metallurgy Equipment Association\n• Metal Injection Molding Association\n• Refractory Metals Association\n• Association for Metal Additive Manufacturing\nThe Federation\'s growth has paralleled the growth of the industry it serves. In 1973 the Federation moved its headquarters from New York City to Princeton, N.J., where it is currently located and where its staff of dedicated professionals strives to help the organization achieve its mission: to be the international trade association serving the global interests of the North American PM and contiguous industries.\nStandards\nThe Metal Powder Industries Federation issues standards to provide the design and materials engineer with the information necessary for specifying powder metallurgy materials which have been developed by the powder metallurgy and metal injection molding parts, powder, and equipment producers. MPIF standards are intended to present and clarify powder metallurgy technology so as to aid in the conduct of business. PM materials specifications and test standards relate to those activities that concern designers and users of PM parts as well as the manufacturer.\nThe standards fall into three basic classifications:\n• Materials Specifications for components\n• Methods of test (for powders and components)\n• Powder Metallurgy Press Safety standards (developed in cooperation with the American National Standards Institute)', 'Liên đoàn Công nghiệp Bột kim loại là liên đoàn gồm sáu hiệp hội thương mại đại diện cho nhiều khía cạnh khác nhau của ngành luyện kim bột (PM), bột kim loại và vật liệu dạng hạt. Sứ mệnh của MPIF là thúc đẩy lợi ích của các ngành sản xuất và tiêu thụ bột kim loại.\nLiên đoàn Công nghiệp Bột kim loại (MPIF) là một \"hiệp hội phi lợi nhuận\" do ngành luyện kim bột thành lập nhằm thúc đẩy lợi ích của các ngành sản xuất và tiêu thụ bột kim loại.\nLiên đoàn bao gồm sáu hiệp hội thương mại quan tâm đến một số khía cạnh của ngành luyện kim bột, bột kim loại hoặc vật liệu dạng hạt.\nTrong suốt lịch sử lâu dài của mình, MPIF luôn là đơn vị tiên phong trong công nghệ tiên tiến này, cung cấp cho các công ty thành viên danh sách dài các dịch vụ giúp thúc đẩy nghệ thuật và khoa học luyện kim bột đồng thời quảng bá lợi ích của ngành này đến người dùng cuối tiềm năng.\nLịch sử của Liên đoàn Công nghiệp Bột kim loại\nMPIF bắt nguồn từ những ngày cuối của Thế chiến thứ II khi một nhóm doanh nhân tham gia vào ngành công nghiệp còn non trẻ này chuyên sản xuất các bộ phận từ bột kim loại phải đối mặt với một cuộc khủng hoảng đang rình rập.\nKhi chiến tranh kết thúc, ngành công nghiệp—cho đến lúc đó chủ yếu bao gồm các ổ trục tự bôi trơn—sẽ phải gánh chịu một công suất sản xuất dư thừa nghiêm trọng đã được chuẩn bị cho nỗ lực chiến tranh. Nghĩa là, trừ khi ngành công nghiệp có thể mở rộng thị trường hiện tại và phát triển các thị trường mới trong giai đoạn chắc chắn sẽ là thời kỳ bùng nổ kinh tế khi các GI trở về nhà để tiếp tục cuộc sống như người tiêu dùng.\nĐể quảng bá công nghệ cho cộng đồng kỹ thuật khi đó còn hoài nghi, để phát triển các tiêu chuẩn và phương pháp thử nghiệm thiết yếu mà khách hàng sẽ yêu cầu, và để có được dữ liệu thống kê quan trọng và đáng tin cậy về sức sống của ngành công nghiệp và triển vọng tương lai của ngành, ngành công nghiệp sẽ cần gạt bỏ những khác biệt và lên tiếng bằng một giọng nói duy nhất. Vì vậy, những người tiên phong này đã đi đến một quyết định quan trọng: họ sẽ thành lập một hiệp hội thương mại.\nNhững gì bắt đầu như một hiệp hội duy nhất bao gồm tất cả những người chơi đa dạng tham gia vào ngành công nghiệp cuối cùng đã phát triển thành một liên đoàn đóng vai trò là tổ chức bao trùm cho sáu hiệp hội khác nhau, mỗi hiệp hội đại diện cho một phân khúc riêng biệt của ngành:\n• Hiệp hội phụ tùng luyện kim bột\n• Hiệp hội sản xuất bột kim loại\n• Hiệp hội thiết bị luyện kim bột\n• Hiệp hội đúc phun kim loại\n• Hiệp hội kim loại chịu lửa\n• Hiệp hội sản xuất phụ gia kim loại\nSự phát triển của Liên đoàn song song với sự phát triển của ngành công nghiệp mà nó phục vụ. Năm 1973, Liên đoàn đã chuyển trụ sở chính từ Thành phố New York đến Princeton, N.J., nơi hiện đang tọa lạc và nơi đội ngũ chuyên gia tận tụy của liên đoàn nỗ lực giúp tổ chức đạt được sứ mệnh của mình: trở thành hiệp hội thương mại quốc tế phục vụ lợi ích toàn cầu của PM Bắc Mỹ và các ngành công nghiệp lân cận.\nTiêu chuẩn\nLiên đoàn công nghiệp bột kim loại ban hành các tiêu chuẩn để cung cấp cho kỹ sư thiết kế và vật liệu thông tin cần thiết để chỉ định các vật liệu luyện kim bột đã được phát triển bởi các nhà sản xuất phụ tùng, bột và thiết bị luyện kim bột và đúc phun kim loại. Tiêu chuẩn MPIF có mục đích trình bày và làm rõ công nghệ luyện kim bột để hỗ trợ cho việc tiến hành kinh doanh. Các thông số kỹ thuật vật liệu PM và tiêu chuẩn thử nghiệm liên quan đến các hoạt động liên quan đến nhà thiết kế và người sử dụng các bộ phận PM cũng như nhà sản xuất.\nCác tiêu chuẩn được chia thành ba loại cơ bản:\n• Thông số kỹ thuật vật liệu cho các thành phần\n• Phương pháp thử nghiệm (cho bột và thành phần)\n• Tiêu chuẩn an toàn máy ép luyện kim bột (được phát triển với sự hợp tác của Viện Tiêu chuẩn Quốc gia Hoa Kỳ)', 'Liên đoàn Công nghiệp Bột kim loại là liên đoàn gồm sáu hiệp hội thương mại đại diện cho nhiều khía cạnh khác nhau của ngành luyện kim bột (PM), bột kim loại và vật liệu dạng hạt. Sứ mệnh của MPIF là thúc đẩy lợi ích của các ngành sản xuất và tiêu thụ bột kim loại.', NULL, NULL, NULL, 'publisher/avatar/3B5Z2FWJ95L2W1JQM54N.jpg', 0),
(4413, 'MSS - Manufacturers Standardization Society of the Valve and Fittings Industry (MSS)', 'MSS - Manufacturers Standardization Society of the Valve and Fittings Industry (MSS)', 'MSS is the only organization in the world dedicated exclusively to the technical needs of the valve and fittings industry. Standards and codes are written and revised by 25 technical committees and address topics such as valves, valve actuators, pipe fittings, flanges, and pipe hangers.', 'MSS là viết tắt của \"Manufacturers Standardization Society\" trong tiếng Anh, có nghĩa là \"Hiệp hội các Nhà sản xuất Van và Phụ kiện\" trong tiếng Việt. MSS là một tổ chức không vụ lợi được thành lập vào năm 1924 tại Hoa Kỳ.\n\nMSS tập trung vào việc phát triển và xuất bản các tiêu chuẩn kỹ thuật và hướng dẫn liên quan đến van, phụ kiện và các thành phần liên quan trong ngành công nghiệp van và đường ống. Các tiêu chuẩn được phát triển bởi MSS đảm bảo tính đồng nhất, tương thích và an toàn trong thiết kế, sản xuất, lắp đặt và vận hành của các sản phẩm và hệ thống liên quan.\n\nMSS công bố các tiêu chuẩn về van, bộ lọc, bộ nối, phụ kiện đường ống, phụ kiện hàn, bộ phận đóng mở và nhiều khía cạnh khác liên quan đến quy trình và thiết bị trong ngành công nghiệp này. Tiêu chuẩn MSS thường được áp dụng rộng rãi trong ngành công nghiệp dầu khí, hóa chất, năng lượng, nước và các ngành công nghiệp khác.\n\nMSS cũng tham gia vào quá trình phát triển và xem xét các tiêu chuẩn quốc tế thông qua việc hợp tác với các tổ chức tiêu chuẩn khác như ISO (International Organization for Standardization) và ASTM International (American Society for Testing and Materials).', 'MSS là viết tắt của \"Manufacturers Standardization Society\" trong tiếng Anh, có nghĩa là \"Hiệp hội các Nhà sản xuất Van và Phụ kiện\" trong tiếng Việt. MSS là một tổ chức không vụ lợi được thành lập vào năm 1924 tại Hoa Kỳ.', 'MSS,ANSI/MSS', 'MSS, Manufacturers Standardization Society, Hiệp hội các Nhà sản xuất Van và Phụ kiện Hoa Kỳ (MSS), Tiêu chuẩn về van và phụ kiện, Van, Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', NULL, 'publisher/avatar/I1JHSRK4D14AGIXAG0FT.jpg', 0),
(4414, 'NAAMM - National Association of Architectural Metal Manufacturers', 'NAAMM - National Association of Architectural Metal Manufacturers', 'Since 1938, the National Association of Architectural Metal Manufacturers (NAAMM) has represented a wide variety of architectural metal products for building construction. NAAMM currently has six operating divisions, which promote the use of their specific products through the development and distribution of technical standards.\nNAAMM currently has six operating divisions, which promote the use of their specific products through the development and distribution of technical standards.\nThrough NAAMM, the six divisions receive symbiotic benefits. For example, the Metal Finishes Manual provides information on finishing which is applicable to all Divisions. Issues related to topics of mutual interest to manufacturers, such as workman\'s compensation, employee relationships, right-to-know, insurance issues, EPA and OSHA are addressed among NAAMM members.\nMission Statement\nThe mission of NAAMM and each of its divisions is:\n1. Developing, maintaining, publishing, and distributing technical information on metal products for building construction. This includes specifications, manuals, and other information for building design professionals.\n2. Promoting the use of NAAMM technical resources, NAAMM member firms and their products.\n3. Providing a forum for the exchange of management and technical information among the members.\nFor additional information about NAAMM Divisions and their products, click on the division links located on the home page and in the footer section.', 'Kể từ năm 1938, Hiệp hội các nhà sản xuất kim loại kiến ​​trúc quốc gia (NAAMM) đã đại diện cho nhiều loại sản phẩm kim loại kiến ​​trúc khác nhau cho xây dựng công trình. NAAMM hiện có sáu bộ phận hoạt động, thúc đẩy việc sử dụng các sản phẩm cụ thể của họ thông qua việc phát triển và phân phối các tiêu chuẩn kỹ thuật.\nNAAMM hiện có sáu bộ phận hoạt động, thúc đẩy việc sử dụng các sản phẩm cụ thể của họ thông qua việc phát triển và phân phối các tiêu chuẩn kỹ thuật.\nThông qua NAAMM, sáu bộ phận nhận được các lợi ích cộng sinh. Ví dụ, Sổ tay hoàn thiện kim loại cung cấp thông tin về hoàn thiện áp dụng cho tất cả các Bộ phận. Các vấn đề liên quan đến các chủ đề mà các nhà sản xuất cùng quan tâm, chẳng hạn như bồi thường cho người lao động, mối quan hệ giữa nhân viên, quyền được biết, các vấn đề về bảo hiểm, EPA và OSHA được giải quyết giữa các thành viên NAAMM.\nTuyên bố sứ mệnh\nSứ mệnh của NAAMM và từng bộ phận của nó là:\n1. Phát triển, duy trì, xuất bản và phân phối thông tin kỹ thuật về các sản phẩm kim loại cho xây dựng công trình. Điều này bao gồm các thông số kỹ thuật, sổ tay hướng dẫn và thông tin khác cho các chuyên gia thiết kế xây dựng.\n2. Thúc đẩy việc sử dụng các nguồn lực kỹ thuật của NAAMM, các công ty thành viên NAAMM và các sản phẩm của họ.\n\n3. Cung cấp diễn đàn để trao đổi thông tin quản lý và kỹ thuật giữa các thành viên.\nĐể biết thêm thông tin về các Phân ban của NAAMM và các sản phẩm của họ, hãy nhấp vào các liên kết phân ban nằm trên trang chủ và trong phần chân trang.', 'Kể từ năm 1938, Hiệp hội các nhà sản xuất kim loại kiến ​​trúc quốc gia (NAAMM) đã đại diện cho nhiều loại sản phẩm kim loại kiến ​​trúc khác nhau cho xây dựng công trình. NAAMM hiện có sáu bộ phận hoạt động, thúc đẩy việc sử dụng các sản phẩm cụ thể của họ thông qua việc phát triển và phân phối các tiêu chuẩn kỹ thuật.', NULL, NULL, NULL, 'publisher/avatar/6J1U6KKD35DXUL7TXA84.jpg', 0),
(4415, 'NACE - National Association of Corrosion Engineers', 'NACE - National Association of Corrosion Engineers', 'Formerly the National Association of Corrosion Engineers, NACE International represents members from 92 countries and is the largest organization in the world dedicated to the study of corrosion. NACE works to protect people, infrastructure, the environment, and the economy from the effects of corrosion by promoting engineering and research. Approximately 100 standards cover subjects such as laboratory corrosion testing, corrosion prevention and blast cleaning.', 'NACE International (trước đây được gọi là National Association of Corrosion Engineers) là một tổ chức chuyên về ăn mòn và bảo vệ chống ăn mòn. NACE có trụ sở tại Houston, Texas, Hoa Kỳ.\n\nNACE International được thành lập vào năm 1943 và là một tổ chức phi lợi nhuận. NACE tập trung vào việc nghiên cứu, phát triển và chia sẻ kiến thức về ăn mòn và các vấn đề liên quan đến bảo vệ chống ăn mòn trong các ngành công nghiệp.\n\nCác hoạt động chính của NACE bao gồm:\n\nTiêu chuẩn và hướng dẫn: NACE phát triển và công bố các tiêu chuẩn kỹ thuật, hướng dẫn và phương pháp thử nghiệm liên quan đến ăn mòn và bảo vệ chống ăn mòn. Những tiêu chuẩn này giúp đảm bảo tính an toàn và độ bền của các cấu trúc, thiết bị và vật liệu trong môi trường ăn mòn.\n\nĐào tạo và chứng chỉ: NACE cung cấp các khóa đào tạo và chứng chỉ về ăn mòn và bảo vệ chống ăn mòn. Điều này giúp nâng cao kiến thức và kỹ năng của các kỹ sư, kỹ thuật viên và chuyên gia trong lĩnh vực này.\n\nHội thảo và sự kiện: NACE tổ chức các hội thảo, hội nghị và sự kiện để tạo cơ hội trao đổi thông tin, kỹ năng và kinh nghiệm giữa các chuyên gia và nhà nghiên cứu trong lĩnh vực ăn mòn và bảo vệ chống ăn mòn.\n\nXuất bản: NACE phát hành các tạp chí, sách và tài liệu về ăn mòn và bảo vệ chống ăn mòn, giúp lan truyền kiến thức và thông tin mới nhất trong ngành.\n\nNACE International đóng vai trò quan trọng trong việc nâng cao hiểu biết về ăn mòn, bảo vệ chống ăn mòn và quản lý rủi ro liên quan đến ăn mòn trong các ngành công nghiệp, bảo vệ tài sản và đảm bảo an toàn trong môi trường làm việc.', 'NACE International (trước đây được gọi là National Association of Corrosion Engineers) là một tổ chức chuyên về ăn mòn và bảo vệ chống ăn mòn. NACE có trụ sở tại Houston, Texas, Hoa Kỳ.', 'NACE,ANSI/NACE,ASTM/NACE', 'NACE, Hiệp hội Quốc gia các Kỹ sư về Ăn mòn Hoa Kỳ (NACE), Ăn mòn, National Association of Corrosion Engineers (NACE), Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', NULL, 'publisher/avatar/06DZD1U8YFJJVR87SFSE.jpg', 0),
(4416, 'NADCA - National Air Duct Cleaners Association', 'NADCA - National Air Duct Cleaners Association', 'NADCA: The HVAC Inspection, Maintenance and Restoration Association, otherwise known as the National Air Duct Cleaners Association (NADCA) was formed in 1989 as a non-profit association of companies engaged in the cleaning of HVAC systems. NADCA\'s mission has expanded to include representation of qualified companies engaged in the inspection, cleaning and restoration of HVAC systems. NADCA standards and certification are specified on a regular basis to ensure HVAC systems are assessed, cleaned, and restored in a safe and efficient manner.\nNADCA: The HVAC Inspection, Cleaning and Restoration Association, otherwise known as the National Air Duct Cleaners Association (NADCA), was formed in 1989 as a nonprofit association of companies engaged in the cleaning of HVAC systems. Its original mission was to promote source removal as the only acceptable method of cleaning and to establish industry standards for the association.\nNADCA’s mission has expanded to include qualified companies engaged in the inspection, cleaning and restoration of HVAC systems. NADCA supports members\' success with standards, education, certification, marketing, and advocacy to promote ethics and the highest quality services. The goal of the association is for its members to be the number one resource for consumers and other entities seeking air duct cleaning and HVAC inspection, cleaning and restoration.\nNADCA’s membership continues to grow each year, along with its training, education and certification opportunities for air systems cleaning specialists, mold remediators, HVAC inspectors and others. NADCA has also published industry standards, educational materials and other useful information for consumers and members alike.\nNADCA is the global trade association representing the HVAC inspection, cleaning and restoration industry. We support members\' success with standards, education, certification, marketing and advocacy to promote the highest quality and ethical services.', 'NADCA: Hiệp hội Kiểm tra, Bảo trì và Phục hồi HVAC, hay còn gọi là Hiệp hội Vệ sinh Ống gió Quốc gia (NADCA), được thành lập vào năm 1989 với tư cách là một hiệp hội phi lợi nhuận của các công ty tham gia vào việc vệ sinh hệ thống HVAC. Sứ mệnh của NADCA đã mở rộng để bao gồm đại diện cho các công ty đủ điều kiện tham gia vào việc kiểm tra, vệ sinh và phục hồi hệ thống HVAC. Các tiêu chuẩn và chứng nhận của NADCA được chỉ định thường xuyên để đảm bảo các hệ thống HVAC được đánh giá, vệ sinh và phục hồi theo cách an toàn và hiệu quả.\nNADCA: Hiệp hội Kiểm tra, Vệ sinh và Phục hồi HVAC, hay còn gọi là Hiệp hội Vệ sinh Ống gió Quốc gia (NADCA), được thành lập vào năm 1989 với tư cách là một hiệp hội phi lợi nhuận của các công ty tham gia vào việc vệ sinh hệ thống HVAC. Sứ mệnh ban đầu của hiệp hội là thúc đẩy việc loại bỏ nguồn gây ô nhiễm như là phương pháp vệ sinh duy nhất được chấp nhận và thiết lập các tiêu chuẩn của ngành cho hiệp hội.\nSứ mệnh của NADCA đã mở rộng để bao gồm các công ty đủ điều kiện tham gia vào việc kiểm tra, vệ sinh và phục hồi hệ thống HVAC. NADCA hỗ trợ thành công của các thành viên bằng các tiêu chuẩn, giáo dục, chứng nhận, tiếp thị và vận động để thúc đẩy đạo đức và các dịch vụ chất lượng cao nhất. Mục tiêu của hiệp hội là để các thành viên trở thành nguồn lực số một cho người tiêu dùng và các tổ chức khác đang tìm kiếm dịch vụ vệ sinh ống gió và kiểm tra, vệ sinh và phục hồi HVAC.\nSố lượng thành viên của NADCA tiếp tục tăng lên mỗi năm, cùng với các cơ hội đào tạo, giáo dục và cấp chứng chỉ cho các chuyên gia vệ sinh hệ thống không khí, người khắc phục nấm mốc, thanh tra HVAC và những người khác. NADCA cũng đã công bố các tiêu chuẩn công nghiệp, tài liệu giáo dục và các thông tin hữu ích khác cho người tiêu dùng và các thành viên.\nNADCA là hiệp hội thương mại toàn cầu đại diện cho ngành kiểm tra, vệ sinh và phục hồi HVAC. Chúng tôi hỗ trợ thành công của các thành viên bằng các tiêu chuẩn, giáo dục, chứng nhận, tiếp thị và vận động để thúc đẩy các dịch vụ chất lượng cao nhất và có đạo đức.', 'NADCA: Hiệp hội Kiểm tra, Bảo trì và Phục hồi HVAC, hay còn gọi là Hiệp hội Vệ sinh Ống gió Quốc gia (NADCA), được thành lập vào năm 1989 với tư cách là một hiệp hội phi lợi nhuận của các công ty tham gia vào việc vệ sinh hệ thống HVAC. Sứ mệnh của NADCA đã mở rộng để bao gồm đại diện cho các công ty đủ điều kiện tham gia vào việc kiểm tra, vệ sinh và phục hồi hệ thống HVAC. Các tiêu chuẩn và chứng nhận của NADCA được chỉ định thường xuyên để đảm bảo các hệ thống HVAC được đánh giá, vệ sinh và phục hồi theo cách an toàn và hiệu quả.', NULL, NULL, NULL, 'publisher/avatar/L2JGFVLD8AW0QMDY6C1D.jpg', 0),
(4417, 'NAS - Aerospace Industries Association - National Aerospace Standard', 'NAS - Aerospace Industries Association - National Aerospace Standard', 'The National Aerospace Standards (NAS) are voluntary standards developed by the aerospace industry. Subject matter experts from AIA member companies participate in committees and working groups to develop and maintain the NAS library. The NAS parts are most well-known for state-of-the-art, high strength, precision fasteners, electrical connectors, splices and terminations, rod end bearings, and many other types of hardware and components.\nNational Aerospace Standards (NAS) are U.S. industry standards for the aerospace industry. They are created and maintaned by the Aerospace Industries Association (AIA).[1] The Federal Aviation Administration recognises National Aerospace Standards as \"traditional standards\" for the purposes of parts approval.[2]\nThe primary AIA committee responsible for developing standards is the National Aerospace Standards Cornmittee (NASC). Since 1938, the NASC has developed more than 2,600 standards for airframe fasteners and other mechanical parts. Personnel from the defense services, Defense Industrial Supply Center and Defense Electronics Supply Center participate actively in the preparation of NAS standards, and liaison is maintained with the FAA, NASA, AIA Canada and the airlines. NAS standards are developed on the basis of user requirements, although coordination is accomplished with suppliers and other materially affected interests.\nAIA’s National Aerospace Standards (NAS) are voluntary standards developed by the aerospace industry since 1941. Subject matter experts from AIA member companies participate in committees and working groups to develop and maintain the NAS library, which currently contains over 1400 active standards. All standards development is conducted in accordance with TOC-1, Development Procedures for National Aerospace Standards. AIA is an accredited standards developer (ASD) through the American National Standards Institute (ANSI).\nAIA’s standards cover a wide variety of subject areas including:\n• NAS parts (bolts, rivets, washers, screws, nut plates, pins, knobs, etc.)\n• Nondestructive Test Personnel certification (NAS410)\n• Hazardous materials management (NAS411)\n• Foreign Object Debris (FOD) prevention (NAS412)\n• Remote Verification (NAS413)\n• Cutting tools (drills, reamers, end mills)\n• Airport Operations (NAS3306)\n• Long Term Archival and Retrieval of Data (NAS9300 series)\n• Trade Compliance Standards (NAS9400 series)\n• Safety Management Systems (NAS9927)\n• Cyber Security (NAS9933)\nOrganization Designation Authorization – an American National Standard (NAS9947) – in development The NAS parts are most well-known for state-of-the-art, high strength, precision fasteners, electrical connectors, splices and terminations, rod end bearings, and many other types of hardware and components. Most of the NAS parts are available as 3D CAD models (see below for more information). In addition to the NAS standards, AIA supports standardization work at the International Organization for Standardization (ISO). AIA holds the secretariat for ISO/TC 20, Aircraft and Space Vehicles, and its subcommittee SC 16, Unmanned Aircraft Systems.\n\nThe NASC is responsible for the creation and maintenance of part standards for aerospace parts and components within AIA’s National Aerospace Standards (NAS) library. These part standards are recognized for meeting the high strength, close tolerance, and rigorous acceptance testing requirements of the aerospace industry. Subject matter experts from AIA member companies and the aerospace industry participate in the NASC to uphold its reputation for providing cost management and production streamlining value, along with the reliability that only industry standard parts can provide. In addition to the creation and maintenance of 2D drawings, specifications, and digital 3D models, the NASC is responsible for the review of and commenting on similar government specifications and standards. Committee members should be involved in the use, manufacturing, distribution, and/or testing of NAS parts, or use of NAS parts in product design and manufacturing.', 'Tiêu chuẩn Hàng không Vũ trụ Quốc gia (NAS) là các tiêu chuẩn tự nguyện do ngành hàng không vũ trụ phát triển. Các chuyên gia về chủ đề này từ các công ty thành viên AIA tham gia vào các ủy ban và nhóm làm việc để phát triển và duy trì thư viện NAS. Các bộ phận NAS nổi tiếng nhất với các ốc vít, đầu nối điện, mối nối và đầu nối, ổ trục đầu thanh và nhiều loại phần cứng và linh kiện khác hiện đại, có độ bền cao.\nTiêu chuẩn Hàng không Vũ trụ Quốc gia (NAS) là các tiêu chuẩn của ngành công nghiệp Hoa Kỳ dành cho ngành hàng không vũ trụ. Chúng được Hiệp hội Công nghiệp Hàng không Vũ trụ (AIA) tạo ra và duy trì.[1] Cục Hàng không Liên bang công nhận Tiêu chuẩn Hàng không Vũ trụ Quốc gia là \"tiêu chuẩn truyền thống\" cho mục đích phê duyệt các bộ phận.[2]\nỦy ban AIA chính chịu trách nhiệm phát triển các tiêu chuẩn là Ủy ban Tiêu chuẩn Hàng không Vũ trụ Quốc gia (NASC). Kể từ năm 1938, NASC đã phát triển hơn 2.600 tiêu chuẩn cho ốc vít khung máy bay và các bộ phận cơ khí khác. Nhân sự từ các dịch vụ quốc phòng, Trung tâm cung ứng công nghiệp quốc phòng và Trung tâm cung ứng điện tử quốc phòng tham gia tích cực vào việc chuẩn bị các tiêu chuẩn NAS và duy trì liên lạc với FAA, NASA, AIA Canada và các hãng hàng không. Các tiêu chuẩn NAS được phát triển dựa trên yêu cầu của người dùng, mặc dù có sự phối hợp với các nhà cung cấp và các bên liên quan khác bị ảnh hưởng đáng kể.\nCác tiêu chuẩn hàng không vũ trụ quốc gia (NAS) của AIA là các tiêu chuẩn tự nguyện do ngành hàng không vũ trụ phát triển từ năm 1941. Các chuyên gia về chủ đề từ các công ty thành viên AIA tham gia vào các ủy ban và nhóm làm việc để phát triển và duy trì thư viện NAS, hiện có hơn 1400 tiêu chuẩn đang hoạt động. Tất cả các tiêu chuẩn phát triển đều được tiến hành theo TOC-1, Quy trình phát triển cho các tiêu chuẩn hàng không vũ trụ quốc gia. AIA là nhà phát triển tiêu chuẩn được công nhận (ASD) thông qua Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI).\nTiêu chuẩn của AIA bao gồm nhiều lĩnh vực chủ đề khác nhau, bao gồm:\n• Các bộ phận NAS (bu lông, đinh tán, vòng đệm, vít, tấm đai ốc, chốt, núm, v.v.)\n• Chứng nhận Nhân viên kiểm tra không phá hủy (NAS410)\n• Quản lý vật liệu nguy hiểm (NAS411)\n• Phòng ngừa mảnh vỡ vật lạ (FOD) (NAS412)\n• Xác minh từ xa (NAS413)\n• Dụng cụ cắt (mũi khoan, máy doa, máy phay đầu)\n• Hoạt động sân bay (NAS3306)\n• Lưu trữ và truy xuất dữ liệu dài hạn (loạt NAS9300)\n• Tiêu chuẩn tuân thủ thương mại (loạt NAS9400)\n• Hệ thống quản lý an toàn (NAS9927)\n• An ninh mạng (NAS9933)\nỦy quyền chỉ định tổ chức – Tiêu chuẩn quốc gia Hoa Kỳ (NAS9947) – đang được phát triển NAS các bộ phận được biết đến nhiều nhất vì các ốc vít, đầu nối điện, mối nối và đầu nối, ổ trục đầu thanh và nhiều loại phần cứng và linh kiện khác hiện đại, có độ bền cao, chính xác. Hầu hết các bộ phận NAS đều có sẵn dưới dạng mô hình CAD 3D (xem bên dưới để biết thêm thông tin). Ngoài các tiêu chuẩn NAS, AIA còn hỗ trợ công tác chuẩn hóa tại Tổ chức Tiêu chuẩn hóa Quốc tế (ISO). AIA nắm giữ ban thư ký cho ISO/TC 20, Máy bay và Phương tiện Không gian, và tiểu ban SC 16, Hệ thống Máy bay Không người lái.\n\nNASC chịu trách nhiệm tạo ra và duy trì các tiêu chuẩn bộ phận cho các bộ phận và linh kiện hàng không vũ trụ trong thư viện Tiêu chuẩn Hàng không Vũ trụ Quốc gia (NAS) của AIA. Các tiêu chuẩn bộ phận này được công nhận là đáp ứng các yêu cầu về độ bền cao, dung sai chặt chẽ và thử nghiệm chấp nhận nghiêm ngặt của ngành hàng không vũ trụ. Các chuyên gia về chủ đề này từ các công ty thành viên AIA và ngành hàng không vũ trụ tham gia NASC để duy trì danh tiếng của mình trong việc cung cấp giá trị quản lý chi phí và hợp lý hóa sản xuất, cùng với độ tin cậy mà chỉ các bộ phận tiêu chuẩn trong ngành mới có thể cung cấp. Ngoài việc tạo và duy trì các bản vẽ 2D, thông số kỹ thuật và mô hình 3D kỹ thuật số, NASC còn chịu trách nhiệm xem xét và đưa ra nhận xét về các thông số kỹ thuật và tiêu chuẩn tương tự của chính phủ. Các thành viên ủy ban phải tham gia vào việc sử dụng, sản xuất, phân phối và/hoặc thử nghiệm các bộ phận NAS hoặc sử dụng các bộ phận NAS trong thiết kế và sản xuất sản phẩm.', 'Tiêu chuẩn Hàng không Vũ trụ Quốc gia (NAS) là các tiêu chuẩn tự nguyện do ngành hàng không vũ trụ phát triển. Các chuyên gia về chủ đề này từ các công ty thành viên AIA tham gia vào các ủy ban và nhóm làm việc để phát triển và duy trì thư viện NAS. Các bộ phận NAS nổi tiếng nhất với các ốc vít, đầu nối điện, mối nối và đầu nối, ổ trục đầu thanh và nhiều loại phần cứng và linh kiện khác hiện đại, có độ bền cao.', NULL, NULL, NULL, 'publisher/avatar/IITBLNQTGC97GK3J7B4Y.jpg', 0),
(4418, 'NASA - National Aeronautics and Space Administration', 'NASA - National Aeronautics and Space Administration', 'NASA - National Aeronautics and Space Administration. NASA explores the unknown in air and space, innovates for the benefit of humanity, and inspires the world through discovery. For more than 65 years, NASA has made the seemingly impossible, possible. At its 20 centers and facilities across the country and with U.S. commercial companies and international partners, NASA leads studying Earth science, including climate, our Sun, solar system, and the larger universe. We conduct cutting-edge research to advance technology and aeronautics. We operate the world’s leading space laboratory, the International Space Station, and will establish a sustainable and strong exploration presence on the Moon this decade through the Artemis campaign.', 'NASA khám phá những điều chưa biết trong không khí và không gian, đổi mới vì lợi ích của nhân loại và truyền cảm hứng cho thế giới thông qua khám phá. Trong hơn 65 năm, NASA đã biến điều tưởng chừng như không thể thành có thể. Tại 20 trung tâm và cơ sở trên khắp đất nước và với các công ty thương mại Hoa Kỳ và các đối tác quốc tế, NASA dẫn đầu nghiên cứu khoa học Trái đất, bao gồm khí hậu, Mặt trời, hệ mặt trời và vũ trụ rộng lớn hơn. Chúng tôi tiến hành nghiên cứu tiên tiến để thúc đẩy công nghệ và hàng không. Chúng tôi vận hành phòng thí nghiệm không gian hàng đầu thế giới, Trạm vũ trụ quốc tế, và sẽ thiết lập sự hiện diện thăm dò bền vững và mạnh mẽ trên Mặt trăng trong thập kỷ này thông qua chiến dịch Artemis.', 'NASA khám phá những điều chưa biết trong không khí và không gian, đổi mới vì lợi ích của nhân loại và truyền cảm hứng cho thế giới thông qua khám phá. Trong hơn 65 năm, NASA đã biến điều tưởng chừng như không thể thành có thể. Tại 20 trung tâm và cơ sở trên khắp đất nước và với các công ty thương mại Hoa Kỳ và các đối tác quốc tế, NASA dẫn đầu nghiên cứu khoa học Trái đất, bao gồm khí hậu, Mặt trời, hệ mặt trời và vũ trụ rộng lớn hơn. Chúng tôi tiến hành nghiên cứu tiên tiến để thúc đẩy công nghệ và hàng không. Chúng tôi vận hành phòng thí nghiệm không gian hàng đầu thế giới, Trạm vũ trụ quốc tế, và sẽ thiết lập sự hiện diện thăm dò bền vững và mạnh mẽ trên Mặt trăng trong thập kỷ này thông qua chiến dịch Artemis.', NULL, NULL, NULL, 'publisher/avatar/RCCOKS2XZA6NWZ4MSA6I.jpg', 0),
(4419, 'NBBI - National Board of Boiler and Pressure Vessel Inspectors', 'NBBI - National Board of Boiler and Pressure Vessel Inspectors', 'The National Board of Boiler and Pressure Vessel Inspectors was founded in 1919 to promote greater safety to life and property through uniformity in the construction, installation, repair, maintenance, and inspection of pressure equipment. Publisher of the National Board Inspection Code (NBIC), this American National Standard has been adopted by most states and cities, all Canadian provinces, and federal regulatory agencies including the US Department of Transportation. It is the only standard recognized worldwide for in-service inspection repairs and alterations of boilers and pressure vessels.\nThe National Board of Boiler and Pressure Vessel Inspectors is the worldwide leader in pressure equipment safety.\nIt was established in 1919 to promote greater safety to life and property through uniformity in the construction, installation, repair, maintenance, and inspection of pressure equipment.\nThe National Board membership oversees adherence to laws, rules, and regulations relating to boilers and pressure vessels. The National Board members are the chief boiler inspectors representing most U.S. states and provinces/territories of Canada, as well as many major cities in the United States.', 'Hội đồng Thanh tra Nồi hơi và Bình chịu áp suất Quốc gia được thành lập vào năm 1919 để thúc đẩy sự an toàn hơn cho tính mạng và tài sản thông qua sự thống nhất trong việc xây dựng, lắp đặt, sửa chữa, bảo trì và kiểm tra thiết bị chịu áp suất. Là đơn vị xuất bản Bộ luật Thanh tra của Hội đồng Quốc gia (NBIC), Tiêu chuẩn Quốc gia Hoa Kỳ này đã được hầu hết các tiểu bang và thành phố, tất cả các tỉnh của Canada và các cơ quan quản lý liên bang bao gồm Bộ Giao thông Vận tải Hoa Kỳ áp dụng. Đây là tiêu chuẩn duy nhất được công nhận trên toàn thế giới đối với việc sửa chữa và thay đổi kiểm tra đang hoạt động của nồi hơi và bình chịu áp suất.\nHội đồng Thanh tra Nồi hơi và Bình chịu áp suất Quốc gia là đơn vị dẫn đầu toàn cầu về an toàn thiết bị chịu áp suất.\nHội đồng được thành lập vào năm 1919 để thúc đẩy sự an toàn hơn cho tính mạng và tài sản thông qua sự thống nhất trong việc xây dựng, lắp đặt, sửa chữa, bảo trì và kiểm tra thiết bị chịu áp suất.\nCác thành viên của Hội đồng Quốc gia giám sát việc tuân thủ luật pháp, quy tắc và quy định liên quan đến nồi hơi và bình chịu áp suất. Các thành viên của Hội đồng Quốc gia là những thanh tra viên nồi hơi chính đại diện cho hầu hết các tiểu bang và tỉnh/lãnh thổ của Hoa Kỳ tại Canada, cũng như nhiều thành phố lớn tại Hoa Kỳ.', 'Hội đồng Thanh tra Nồi hơi và Bình chịu áp suất Quốc gia được thành lập vào năm 1919 để thúc đẩy sự an toàn hơn cho tính mạng và tài sản thông qua sự thống nhất trong việc xây dựng, lắp đặt, sửa chữa, bảo trì và kiểm tra thiết bị chịu áp suất. Là đơn vị xuất bản Bộ luật Thanh tra của Hội đồng Quốc gia (NBIC),', NULL, NULL, NULL, 'publisher/avatar/64Q7BCRJHFCLN8VNKT51.jpg', 0),
(4420, 'NCSL - National Conference of Standards Laboratories International', 'NCSL - National Conference of Standards Laboratories International', 'NCSL International is a member based and volunteer driven Professional Trade Organization. NCSL International provides the best opportunities for the world\'s measurement science professionals to network and exchange information, to promote measurement education and skill development and to develop a means to resolve measurement challenges. NCSL International membership is open to any organization or individual with an interest in the science of measurement and its application in research, development, education, or commerce.\n\nNCSL International (NCSLI) (from the founding name \"National Conference of Standards Laboratories\") is a global, non-profit organization whose membership is open to any organization with an interest in metrology (the science of measurement) and its application in research, development, education, and commerce.\nOn June 22, 1960, at the National Bureau of Standards (NBS) in Boulder, Colorado, Harvey Lance presented a paper titled \"The Nation\'s Electronic Standards Program: Where Do We Stand?\" suggesting the need for an organization of standards laboratories to promote cooperative efforts for solving the common problems faced by measurement and testing laboratories. The next morning a committee was formed to \"investigate the possible organization, scope, and objectives appropriate for an organization of standards laboratories\". September 15, 1961, the National Conference of Standards Laboratories (NCSL) was formally established with NBS as its sponsor. Primarily due to the growth and acquired ability of NCSL to run its own affairs, NBS (currently known as the National Institute of Standards and Technology or NIST) ended its sponsorship role in July 1986. The two agencies maintain a close and collaborative relationship. \nDuring the 1960s and early 1970s the Cold War climate caused a dilemma for NCSL which included many US aerospace and military facilities amongst its membership. There was concern over complying with US State Department regulations relating to technology transfer and discussion while allowing non-US entities to participate. NCSL considered national security a serious enough issue to warrant US-only membership. In 1974, however, the board of directors decided the substantial advantages of an open international membership outweighed the security considerations and NCSL enrollment was opened to non-US organizations. In 1975, Graham Cameron from the Canadian Department of National Defence became the first non-US delegate to serve on the board. In 1976 the first International Region was established. By 1996 non-US organizations comprised roughly 15% of the total membership. In the year 2000, NCSL began the process of formally changing its name to NCSL International to better represent its membership.', 'NCSL International là một Tổ chức Thương mại Chuyên nghiệp dựa trên thành viên và do các tình nguyện viên điều hành. NCSL International cung cấp những cơ hội tốt nhất cho các chuyên gia khoa học đo lường trên thế giới để kết nối và trao đổi thông tin, thúc đẩy giáo dục đo lường và phát triển kỹ năng cũng như phát triển phương tiện để giải quyết các thách thức về đo lường. Thành viên NCSL International mở cửa cho bất kỳ tổ chức hoặc cá nhân nào quan tâm đến khoa học đo lường và ứng dụng của nó trong nghiên cứu, phát triển, giáo dục hoặc thương mại.\n\nNCSL International (NCSLI) (từ tên sáng lập \"Hội nghị Quốc gia về Phòng thí nghiệm Tiêu chuẩn\") là một tổ chức phi lợi nhuận toàn cầu, có tư cách thành viên mở cửa cho bất kỳ tổ chức nào quan tâm đến phép đo (khoa học đo lường) và ứng dụng của nó trong nghiên cứu, phát triển, giáo dục và thương mại.\nVào ngày 22 tháng 6 năm 1960, tại Cục Tiêu chuẩn Quốc gia (NBS) ở Boulder, Colorado, Harvey Lance đã trình bày một bài báo có tựa đề \"Chương trình Tiêu chuẩn Điện tử của Quốc gia: Chúng ta đang ở đâu?\", đề xuất nhu cầu thành lập một tổ chức các phòng thí nghiệm tiêu chuẩn để thúc đẩy các nỗ lực hợp tác nhằm giải quyết các vấn đề chung mà các phòng thí nghiệm đo lường và thử nghiệm phải đối mặt. Sáng hôm sau, một ủy ban được thành lập để \"điều tra khả năng tổ chức, phạm vi và mục tiêu phù hợp cho một tổ chức phòng thí nghiệm tiêu chuẩn\". Ngày 15 tháng 9 năm 1961, Hội nghị quốc gia về các phòng thí nghiệm tiêu chuẩn (NCSL) chính thức được thành lập với NBS là nhà tài trợ. Chủ yếu là do sự phát triển và khả năng tự điều hành công việc của NCSL, NBS (hiện được gọi là Viện Tiêu chuẩn và Công nghệ Quốc gia hay NIST) đã chấm dứt vai trò tài trợ của mình vào tháng 7 năm 1986. Hai cơ quan này duy trì mối quan hệ chặt chẽ và hợp tác.\nTrong những năm 1960 và đầu những năm 1970, bầu không khí Chiến tranh Lạnh đã gây ra tình thế tiến thoái lưỡng nan cho NCSL, bao gồm nhiều cơ sở hàng không vũ trụ và quân sự của Hoa Kỳ trong số các thành viên của mình. Có lo ngại về việc tuân thủ các quy định của Bộ Ngoại giao Hoa Kỳ liên quan đến chuyển giao và thảo luận công nghệ trong khi vẫn cho phép các thực thể không phải của Hoa Kỳ tham gia. NCSL coi an ninh quốc gia là một vấn đề đủ nghiêm trọng để đảm bảo tư cách thành viên chỉ dành cho Hoa Kỳ. Tuy nhiên, vào năm 1974, hội đồng quản trị đã quyết định rằng những lợi thế đáng kể của tư cách thành viên quốc tế mở rộng hơn các cân nhắc về an ninh và việc đăng ký NCSL đã mở cho các tổ chức không phải của Hoa Kỳ. Năm 1975, Graham Cameron từ Bộ Quốc phòng Canada đã trở thành đại biểu đầu tiên không phải người Mỹ phục vụ trong ban quản trị. Năm 1976, Khu vực quốc tế đầu tiên được thành lập. Đến năm 1996, các tổ chức không phải người Mỹ chiếm khoảng 15% tổng số thành viên. Năm 2000, NCSL bắt đầu quá trình đổi tên chính thức thành NCSL International để đại diện tốt hơn cho các thành viên của mình.', 'NCSL International là một Tổ chức Thương mại Chuyên nghiệp dựa trên thành viên và do các tình nguyện viên điều hành. NCSL International cung cấp những cơ hội tốt nhất cho các chuyên gia khoa học đo lường trên thế giới để kết nối và trao đổi thông tin, thúc đẩy giáo dục đo lường và phát triển kỹ năng cũng như phát triển phương tiện để giải quyết các thách thức về đo lường. Thành viên NCSL International mở cửa cho bất kỳ tổ chức hoặc cá nhân nào quan tâm đến khoa học đo lường và ứng dụng của nó trong nghiên cứu, phát triển, giáo dục hoặc thương mại.', NULL, NULL, NULL, 'publisher/avatar/MG53CL9ZB1DH9KMGCVH3.jpg', 0),
(4421, 'NECA - National Electrical Contractors Association', 'NECA - National Electrical Contractors Association', 'The National Electrical Contractors Association (NECA) is the voice of the electrical construction industry. A trade organization founded in 1901, NECA contractors set industry standards for traditional and integrated electrical systems and leads the industry in the practical application of new technologies. NECA aims to protect the public while making electrical innovation possible.\nNECA is the voice of the $225 billion electrical construction industry that brings power, light, and communication technology to buildings and communities across the U.S.\nNECA contractors are the technical professionals responsible for the most innovative and safest electrical construction in the U.S.\nNECA traces its origins to the birth of modern electricity. In 1901, a group of electrical contractors met at the Pan-American Exposition in Buffalo, NY, where a major display of electric power had been installed. These contractors joined together to foster trade and reform abuses within their fledgling industry.\nToday, NECA continues to build on a legacy of protecting the public and making innovation possible. NECA contractors strive to be solution-providers for their customers, and their industry expertise benefits everyone working on an electrical construction project.', 'Hiệp hội Nhà thầu Điện Quốc gia (NECA) là tiếng nói của ngành xây dựng điện. Là một tổ chức thương mại được thành lập vào năm 1901, các nhà thầu NECA đặt ra các tiêu chuẩn của ngành cho các hệ thống điện truyền thống và tích hợp và dẫn đầu ngành trong việc ứng dụng thực tế các công nghệ mới. NECA hướng đến mục tiêu bảo vệ công chúng trong khi hiện thực hóa đổi mới điện.\nNECA là tiếng nói của ngành xây dựng điện trị giá 225 tỷ đô la, mang điện, ánh sáng và công nghệ truyền thông đến các tòa nhà và cộng đồng trên khắp Hoa Kỳ.\nCác nhà thầu NECA là các chuyên gia kỹ thuật chịu trách nhiệm về công trình điện sáng tạo và an toàn nhất tại Hoa Kỳ.\nNECA bắt nguồn từ sự ra đời của điện hiện đại. Năm 1901, một nhóm các nhà thầu điện đã họp tại Triển lãm Liên Mỹ ở Buffalo, New York, nơi đã lắp đặt một màn trình diễn điện lớn. Những nhà thầu này đã cùng nhau thúc đẩy thương mại và cải cách các hành vi lạm dụng trong ngành còn non trẻ của họ.\nNgày nay, NECA tiếp tục xây dựng trên di sản bảo vệ công chúng và hiện thực hóa đổi mới. Các nhà thầu của NECA luôn nỗ lực trở thành nhà cung cấp giải pháp cho khách hàng và chuyên môn trong ngành của họ mang lại lợi ích cho tất cả mọi người làm việc trong dự án xây dựng điện.', 'Hiệp hội Nhà thầu Điện Quốc gia (NECA) là tiếng nói của ngành xây dựng điện. Là một tổ chức thương mại được thành lập vào năm 1901, các nhà thầu NECA đặt ra các tiêu chuẩn của ngành cho các hệ thống điện truyền thống và tích hợp và dẫn đầu ngành trong việc ứng dụng thực tế các công nghệ mới. NECA hướng đến mục tiêu bảo vệ công chúng trong khi hiện thực hóa đổi mới điện.', NULL, NULL, NULL, 'publisher/avatar/15R980JNEKDRRPO7GEPC.jpg', 0),
(4422, 'NEMA - National Electrical Manufacturers Association', 'NEMA - National Electrical Manufacturers Association', 'NEMA is the largest U.S. trade organization representing manufacturers of products used in the generation, transmission, distribution, control, and end-use of electricity. Many of NEMA\'s 350+ standards have been approved as American National Standards or adopted by the federal government.', 'Hiệp hội các nhà sản xuất điện quốc gia (NEMA) là một hiệp hội thương mại có trụ sở tại Hoa Kỳ đại diện cho lợi ích của các nhà sản xuất thiết bị điện và hình ảnh y tế. NEMA được thành lập vào năm 1926 và đóng vai trò là nền tảng cho sự hợp tác, vận động và tiêu chuẩn hóa trong ngành sản xuất điện.\n\nMục tiêu và hoạt động chính của Hiệp hội các nhà sản xuất điện quốc gia bao gồm:\nĐại diện ngành: NEMA đóng vai trò là tiếng nói của ngành sản xuất điện tại Hoa Kỳ. Hiệp hội đại diện cho lợi ích của các công ty thành viên, bao gồm các nhà sản xuất nhiều loại thiết bị, hệ thống và linh kiện điện. NEMA tham gia với các cơ quan chính phủ, cơ quan quản lý và các bên liên quan khác để ủng hộ các chính sách và quy định hỗ trợ sự tăng trưởng, đổi mới và khả năng cạnh tranh của ngành.\nTiêu chuẩn hóa: NEMA đóng vai trò quan trọng trong việc phát triển và duy trì các tiêu chuẩn cho hệ thống và thiết bị điện. Hiệp hội hợp tác với các chuyên gia trong ngành, cơ quan chính phủ và các tổ chức phát triển tiêu chuẩn khác để thiết lập các tiêu chuẩn kỹ thuật, hướng dẫn và khuyến nghị thực hành. Các tiêu chuẩn này bao gồm các khía cạnh khác nhau của thiết bị điện, bao gồm an toàn, hiệu suất, khả năng tương tác và hiệu quả năng lượng. Tiêu chuẩn NEMA giúp đảm bảo chất lượng sản phẩm, tạo điều kiện tiếp cận thị trường và thúc đẩy tiến bộ công nghệ trong ngành.\nNghiên cứu Thị trường và Phân tích Dữ liệu: NEMA tiến hành nghiên cứu thị trường và thu thập dữ liệu ngành để cung cấp những hiểu biết có giá trị về lĩnh vực sản xuất điện. Hiệp hội thu thập thông tin về xu hướng thị trường, lô hàng sản phẩm và các chỉ số kinh tế để hỗ trợ các công ty thành viên đưa ra quyết định kinh doanh sáng suốt. Dữ liệu và phân tích thị trường của NEMA giúp xác định các cơ hội mới nổi, đánh giá nhu cầu thị trường và hỗ trợ lập kế hoạch chiến lược trong ngành.\nVận động và Giáo dục: NEMA ủng hộ các chính sách và sáng kiến nhằm nâng cao lợi ích của ngành sản xuất điện. Hiệp hội tích cực tham gia với các nhà hoạch định chính sách, nhà quản lý và nhà lập pháp để thúc đẩy các vấn đề liên quan đến hiệu quả năng lượng, tính bền vững, an toàn sản phẩm và tiếp cận thị trường. NEMA cũng cung cấp các tài nguyên giáo dục, chương trình đào tạo và hội thảo để phổ biến kiến thức và phương pháp thực hành tốt nhất cho các chuyên gia trong ngành.\nKết nối và cộng tác: NEMA cung cấp nền tảng kết nối và cộng tác giữa các bên liên quan trong ngành. Hiệp hội tổ chức các hội nghị, cuộc họp và sự kiện để các nhà sản xuất, nhà cung cấp và chuyên gia trong ngành có thể kết nối, trao đổi ý tưởng và thúc đẩy quan hệ đối tác. Các thành viên NEMA có cơ hội hợp tác trong các dự án nghiên cứu, sáng kiến công nghiệp và hoạt động phát triển tiêu chuẩn.\n\nThông qua các hoạt động của mình, Hiệp hội các nhà sản xuất điện quốc gia (NEMA) hỗ trợ sự tăng trưởng, đổi mới và khả năng cạnh tranh của ngành sản xuất điện tại Hoa Kỳ. Hiệp hội đóng một vai trò quan trọng trong việc đại diện, tiêu chuẩn hóa, nghiên cứu thị trường, vận động và giáo dục trong lĩnh vực sản xuất điện.', 'NEMA là tổ chức thương mại lớn nhất của Hoa Kỳ đại diện cho các nhà SX các sản phẩm điện. Tiêu chuẩn của NEMA đã được chấp nhận thành Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) hoặc được chính phủ liên bang thông qua.', 'NEMA,ANSI/NEMA,NEMA/ISO,AWS/NEMA', 'NEMA, Hội các Nhà sản xuất Điện Quốc gia (NEMA), National Electrical Manufacturers Association (NEMA), Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', '11*11.040*13*13.220*13.320*25*25.040*25.160*29*29.035*29.060*29.120*29.130*29.140*29.160*29.180*29.220*29.240*29.260*33*33.080*33.100*33.120*91*91.120*91.140*91.160*', 'publisher/avatar/EMFJBUE2HG5RXV3ZYHQJ.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4423, 'NETA - International Electrical Testing Association', 'NETA - International Electrical Testing Association', 'The InterNational Electrical Testing Association (NETA) is an organization that serves the electrical testing industry by offering accreditation of third-party electrical testing firms, certifying electrical testing technicians, and producing American National Standards.\nThe International Electrical Testing Association (NETA), formerly the National Electrical Testing Association, is a trade association dedicated to improving electrical testing standards in the United States and sharing those standards internationally. NETA is accredited by the American National Standards Institute (ANSI) as a standards developing entity. It is guided by an active Board of Directors consisting of professionals within the electrical testing industry. The Board meets quarterly for official meetings. Board members also participate on various NETA committees, such as the Standards Review Council, Certification Exam, Membership, Finance, Association Development and Strategy, Promotions and Marketing, Nominations and Mission Based Programs.\nNETA\'s stated mission is \"...to serve the electrical testing industry by establishing standards; publishing specifications; accrediting independent, third-party testing companies; certifying test technicians; and promoting the professional services of its members. The Association also collects and disseminates information and data of value to the electrical industry and educates the public and end user about the merits of electrical acceptance and maintenance testing.\"\nIn the 1960s, the electrical industry was booming thanks to lower prices and the huge increase in the number and reach of power lines, making electricity more in demand than ever before. By 1972, it was widely recognized that this rapid growth demanded some oversight to promote safety, system reliability, and quality testing. Nine companies came together and channeled this need into the creation of NETA, the National Electrical Testing Association. That same year, NETA released its first standard, Acceptance Testing Specifications for Electrical Power Equipment and Systems. NETA then turned its attention to improving the work of electrical technicians. To that end, the NETA Electrical Testing Technician Certification program was established in 1975. In recognition that the association had reached beyond United States borders, the name was changed to the InterNational Electrical Testing Association in 1983. In its ever-increasing desire to keep ahead of the changing industry, the NETA Accredited Company (NAC) program was instituted in 1991. Shortly thereafter, a program was developed for individual professionals in the electrical power industry to join NETA as alliance partners. NETA became ANSI Accredited in 1996, and by 2000 had released the first ANSI Accredited Standard, the ANSI/NETA Standard for Certification of Electrical Testing Technicians. A version of the ANSI/NETA Standard for Maintenance Testing Specifications was first published in 1975, with the most recent edition released in 2015. In 2013, the latest version of NETA\'s very first publication, the ANSI/NETA Standard for Acceptance Testing Specifications for Electrical Power Equipment and Systems, was verified as an American National Standard. The association actively furthers their mission to serve the electrical industry by continuing to develop standards, most recently in 2015 with the publication of the ANSI/NETA Standard for Electrical Commissioning Specifications. NETA celebrated 45 years of continual improvement of the electrical testing industry in 2017. The organization is managed by a private company which is not responsible to the public or NETA Members.', 'Hiệp hội Kiểm tra Điện Quốc tế (NETA) là một tổ chức phục vụ ngành kiểm tra điện bằng cách cung cấp chứng nhận cho các công ty kiểm tra điện của bên thứ ba, chứng nhận kỹ thuật viên kiểm tra điện và xây dựng Tiêu chuẩn Quốc gia Hoa Kỳ.\nHiệp hội Kiểm tra Điện Quốc tế (NETA), trước đây là Hiệp hội Kiểm tra Điện Quốc gia, là một hiệp hội thương mại chuyên cải thiện các tiêu chuẩn kiểm tra điện tại Hoa Kỳ và chia sẻ các tiêu chuẩn đó trên toàn thế giới. NETA được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận là một tổ chức phát triển tiêu chuẩn. NETA được chỉ đạo bởi một Hội đồng Quản trị tích cực bao gồm các chuyên gia trong ngành kiểm tra điện. Hội đồng họp hàng quý để họp chính thức. Các thành viên hội đồng cũng tham gia vào nhiều ủy ban của NETA, chẳng hạn như Hội đồng Đánh giá Tiêu chuẩn, Kỳ thi Chứng nhận, Thành viên, Tài chính, Phát triển và Chiến lược Hiệp hội, Quảng cáo và Tiếp thị, Đề cử và Chương trình Dựa trên Sứ mệnh.\nSứ mệnh đã nêu của NETA là \"... phục vụ ngành thử nghiệm điện bằng cách thiết lập các tiêu chuẩn; công bố thông số kỹ thuật; công nhận các công ty thử nghiệm độc lập của bên thứ ba; chứng nhận các kỹ thuật viên thử nghiệm; và thúc đẩy các dịch vụ chuyên nghiệp của các thành viên. Hiệp hội cũng thu thập và phổ biến thông tin và dữ liệu có giá trị cho ngành điện và giáo dục công chúng và người dùng cuối về các ưu điểm của thử nghiệm chấp nhận và bảo trì điện.\"\nVào những năm 1960, ngành điện bùng nổ nhờ giá thấp hơn và số lượng và phạm vi của đường dây điện tăng mạnh, khiến nhu cầu về điện trở nên cao hơn bao giờ hết. Đến năm 1972, người ta đã công nhận rộng rãi rằng sự tăng trưởng nhanh chóng này đòi hỏi một số giám sát để thúc đẩy tính an toàn, độ tin cậy của hệ thống và thử nghiệm chất lượng. Chín công ty đã hợp tác và chuyển nhu cầu này thành việc thành lập NETA, Hiệp hội thử nghiệm điện quốc gia. Cùng năm đó, NETA đã công bố tiêu chuẩn đầu tiên của mình, Thông số kỹ thuật thử nghiệm chấp nhận cho thiết bị và hệ thống điện. Sau đó, NETA chuyển sự chú ý của mình sang việc cải thiện công việc của các kỹ thuật viên điện. Để đạt được mục đích đó, chương trình Chứng nhận Kỹ thuật viên Kiểm tra Điện NETA đã được thành lập vào năm 1975. Nhận thấy rằng hiệp hội đã vươn ra ngoài biên giới Hoa Kỳ, tên của hiệp hội đã được đổi thành Hiệp hội Kiểm tra Điện Quốc tế vào năm 1983. Với mong muốn ngày càng tăng là luôn đi đầu trong ngành công nghiệp đang thay đổi, chương trình Công ty được NETA công nhận (NAC) đã được thành lập vào năm 1991. Ngay sau đó, một chương trình đã được phát triển cho các chuyên gia cá nhân trong ngành điện để tham gia NETA với tư cách là đối tác liên minh. NETA đã được ANSI công nhận vào năm 1996 và đến năm 2000 đã phát hành Tiêu chuẩn được ANSI công nhận đầu tiên, Tiêu chuẩn ANSI/NETA để Chứng nhận Kỹ thuật viên Kiểm tra Điện. Phiên bản Tiêu chuẩn ANSI/NETA về Thông số kỹ thuật Kiểm tra Bảo trì lần đầu tiên được công bố vào năm 1975, với phiên bản gần đây nhất được phát hành vào năm 2015. Vào năm 2013, phiên bản mới nhất của ấn phẩm đầu tiên của NETA, Tiêu chuẩn ANSI/NETA về Thông số kỹ thuật Kiểm tra Chấp nhận cho Thiết bị và Hệ thống Điện, đã được xác minh là Tiêu chuẩn Quốc gia Hoa Kỳ. Hiệp hội tích cực thúc đẩy sứ mệnh phục vụ ngành điện bằng cách tiếp tục phát triển các tiêu chuẩn, gần đây nhất là vào năm 2015 với việc công bố Tiêu chuẩn ANSI/NETA về Thông số kỹ thuật vận hành điện. NETA đã kỷ niệm 45 năm cải tiến liên tục của ngành thử nghiệm điện vào năm 2017. Tổ chức này được quản lý bởi một công ty tư nhân không chịu trách nhiệm với công chúng hoặc các Thành viên NETA.', 'Hiệp hội Kiểm tra Điện Quốc tế (NETA) là một tổ chức phục vụ ngành kiểm tra điện bằng cách cung cấp chứng nhận cho các công ty kiểm tra điện của bên thứ ba, chứng nhận kỹ thuật viên kiểm tra điện và xây dựng Tiêu chuẩn Quốc gia Hoa Kỳ.', NULL, NULL, NULL, 'publisher/avatar/OLKZCR46UAFPF7WFOBQ1.jpg', 0),
(4424, 'NFPA (Fire) - National Fire Protection Association', 'NFPA (Fire) - National Fire Protection Association', 'As the world\'s largest and most influential fire safety organization, NFPA publishes approximately 300 codes and standards intended to prevent the loss of life and property. Members include more than 66,000 fire safety professionals.', 'NFPA (National Fire Protection Association) - Hội Phòng cháy Quốc gia Hoa Kỳ. NFPA là một tổ chức phi lợi nhuận có trụ sở tại Hoa Kỳ và chuyên về lĩnh vực phòng cháy và an toàn cháy.\n\nNFPA được thành lập vào năm 1896 và đã trở thành một trong những tổ chức dẫn đầu trong việc thiết lập các tiêu chuẩn và quy định về phòng cháy và an toàn cháy. Mục tiêu chính của NFPA là đảm bảo an toàn và bảo vệ cuộc sống, tài sản và môi trường khỏi nguy cơ cháy và các tác động của nó.\n\nNFPA phát triển và xuất bản hàng loạt các tiêu chuẩn, mã luật và hướng dẫn kỹ thuật liên quan đến phòng cháy, hệ thống cứu hỏa, thiết bị báo cháy, phương pháp xử lý cháy, an toàn điện, an toàn cháy trong các tòa nhà và nhiều lĩnh vực khác. Các tiêu chuẩn và quy định của NFPA thường được áp dụng rộng rãi trong ngành công nghiệp, xây dựng, cơ quan chính phủ và cộng đồng chuyên ngành liên quan đến phòng cháy.\n\nNFPA cũng cung cấp các khóa đào tạo, chương trình chứng chỉ và tài liệu giáo dục để nâng cao nhận thức và khả năng về phòng cháy và an toàn cháy cho các chuyên gia và công chúng. Tổ chức này cũng thực hiện nhiều hoạt động nghiên cứu và tư vấn để đưa ra các phương pháp và giải pháp tiên tiến cho phòng cháy và an toàn cháy.', 'NFPA (National Fire Protection Association) - Hội Phòng cháy Quốc gia Hoa Kỳ. NFPA là một tổ chức phi lợi nhuận có trụ sở tại Hoa Kỳ và chuyên về lĩnh vực phòng cháy và an toàn cháy.', 'NFPA,ANSI/(NFPA),ANSI/NFPA,NFPA/T', 'NFPA, National Fire Protection Association, Hội Phòng cháy Quốc gia Hoa Kỳ, Tiêu chuẩn phòng cháy và an toàn cháy, PCCC, An toàn cháy, Phòng cháy chữa cháy, Fire protection, Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', NULL, 'publisher/avatar/HG1T0L2QJZ7H8KONHWV3.png', 0),
(4425, 'NFPA (Fluid) - National Fluid Power Association', 'NFPA (Fluid) - National Fluid Power Association', 'NFPA helps to increase the number of technically trained people capable of integrating and applying fluid power. The focus of NFPA\'s standards programs is on developing International Standards for the global marketplace, especially in the areas of design for interchangeability, testing, rating methods, safety, communications and calibration.\nFounded in 1953, the National Fluid Power Association (NFPA) is the only trade Association focused exclusively on fluid power technology with members representing the entire fluid power supply chain.  \n\nBeginning with 35 fluid power companies at the inaugural meeting on May 1, 1953, NFPA has grown to over 340 member companies with an ever-growing impact towards ensuring fluid power is the customer’s technology of choice.  \n\nHeadquartered in Milwaukee, WI, NFPA continues to add value for its members and is working towards the continued success of the fluid power industry.', 'NFPA giúp tăng số lượng người được đào tạo về kỹ thuật có khả năng tích hợp và áp dụng năng lượng chất lỏng. Trọng tâm của các chương trình tiêu chuẩn của NFPA là phát triển các Tiêu chuẩn quốc tế cho thị trường toàn cầu, đặc biệt là trong các lĩnh vực thiết kế để có thể hoán đổi, thử nghiệm, phương pháp đánh giá, an toàn, truyền thông và hiệu chuẩn.\nĐược thành lập vào năm 1953, Hiệp hội năng lượng chất lỏng quốc gia (NFPA) là Hiệp hội thương mại duy nhất tập trung hoàn toàn vào công nghệ năng lượng chất lỏng với các thành viên đại diện cho toàn bộ chuỗi cung cấp năng lượng chất lỏng.\n\nBắt đầu với 35 công ty năng lượng chất lỏng tại cuộc họp khai mạc vào ngày 1 tháng 5 năm 1953, NFPA đã phát triển lên hơn 340 công ty thành viên với tác động ngày càng tăng hướng tới việc đảm bảo năng lượng chất lỏng là công nghệ được khách hàng lựa chọn.\n\nCó trụ sở chính tại Milwaukee, WI, NFPA tiếp tục gia tăng giá trị cho các thành viên của mình và đang nỗ lực hướng tới sự thành công liên tục của ngành năng lượng chất lỏng.', 'Được thành lập vào năm 1953, Hiệp hội năng lượng chất lỏng quốc gia (NFPA) là Hiệp hội thương mại duy nhất tập trung hoàn toàn vào công nghệ năng lượng chất lỏng với các thành viên đại diện cho toàn bộ chuỗi cung cấp năng lượng chất lỏng', NULL, NULL, NULL, 'publisher/avatar/4BL6ZUX7IGQE1CSUS8E0.png', 0),
(4426, 'NFSI - National Floor Safety Institute', 'NFSI - National Floor Safety Institute', 'Founded in 1997 the National Floor Safety Institute (NFSI) is a 501(c)(3) non-for-profit organization whose mission is: “to aid in the prevention of slips, trips, and falls through education, research and standards development.”\nThe NFSI provides a wide range of services including independent product testing and certification, educational training, and standards development. Since 2006, the NFSI authored safety standards for slip, trip and fall prevention through the B101 committee on slip, trip and fall prevention. In 2014 the NFSI became the provider and issuer of the Walkway Auditor Certificate Holder (WACH) designation.\nStandards\nThe NFSI is proud to be a member of The Society for Standards Professionals (SES).\nIn 2001, the NFSI began authoring standards aimed at preventing slips and falls. The NFSI 101 A-D standards were the first slip and fall prevention standards published in the U.S. In 2005 the NFSI Board of Directors established the NFSI B101 committee on slip, trip and fall prevention which it continues to oversee. From 2006 to 2019, the NFSI was an ANSI accredited Standards Developing Organization (SDO) and functioned under a rigorous set of operating procedures which remain intact today and serve as the basis of the standards developing process. In 2020, the NFSI terminated its relationship with ANSI and became an independent SDO and was awarded organizational membership in the Society for Standards Professionals (SES) (ses-standards.org), joining other peer SDO’s including the ASTM and ANSI.', 'Được thành lập vào năm 1997, Viện An toàn Sàn Quốc gia (NFSI) là một tổ chức phi lợi nhuận 501(c)(3) có sứ mệnh là: “hỗ trợ phòng ngừa trượt ngã thông qua giáo dục, nghiên cứu và phát triển tiêu chuẩn”.\nNFSI cung cấp nhiều dịch vụ bao gồm thử nghiệm và chứng nhận sản phẩm độc lập, đào tạo giáo dục và phát triển tiêu chuẩn. Từ năm 2006, NFSI đã biên soạn các tiêu chuẩn an toàn để phòng ngừa trượt ngã thông qua ủy ban B101 về phòng ngừa trượt ngã. Năm 2014, NFSI đã trở thành nhà cung cấp và cấp chứng chỉ Người giữ chứng chỉ Kiểm toán viên Lối đi (WACH).\nTiêu chuẩn\nNFSI tự hào là thành viên của Hiệp hội các Chuyên gia Tiêu chuẩn (SES).\nNăm 2001, NFSI bắt đầu biên soạn các tiêu chuẩn nhằm mục đích phòng ngừa trượt ngã. Tiêu chuẩn NFSI 101 A-D là tiêu chuẩn phòng ngừa trượt ngã đầu tiên được công bố tại Hoa Kỳ. Năm 2005, Hội đồng quản trị NFSI đã thành lập ủy ban NFSI B101 về phòng ngừa trượt ngã và vấp ngã mà ủy ban này vẫn tiếp tục giám sát. Từ năm 2006 đến năm 2019, NFSI là Tổ chức phát triển tiêu chuẩn (SDO) được ANSI công nhận và hoạt động theo một bộ quy trình vận hành nghiêm ngặt vẫn còn nguyên vẹn cho đến ngày nay và đóng vai trò là cơ sở của quá trình phát triển tiêu chuẩn. Năm 2020, NFSI chấm dứt mối quan hệ với ANSI và trở thành SDO độc lập và được trao tư cách thành viên tổ chức trong Hiệp hội các chuyên gia tiêu chuẩn (SES) (ses-standards.org), gia nhập các SDO ngang hàng khác bao gồm ASTM và ANSI.', 'Được thành lập vào năm 1997, Viện An toàn Sàn Quốc gia (NFSI) là một tổ chức phi lợi nhuận 501(c)(3) có sứ mệnh là: “hỗ trợ phòng ngừa trượt ngã thông qua giáo dục, nghiên cứu và phát triển tiêu chuẩn”.', NULL, NULL, NULL, 'publisher/avatar/FQT4O7MZGJME9BCIQUVN.jpg', 0),
(4427, 'NGA - National Glass Association', 'NGA - National Glass Association', 'NGA was founded in 1948. In 2018, the association combined with the Glass Association of North America (GANA) to create the largest trade association serving our industry. Our 1,700 member companies include glazing contractors, full-service glass companies, glass and metal fabricators, primary glass manufacturers and glass building product suppliers.\nThe NGA member community is 1,800+ companies strong and represents all aspects of the glazing and glass building products industry.\n• We are contract glaziers.\n• We are full-service glass companies.\n• We are fabricators, manufacturers and suppliers.\nNGA takes pride in building community for our members—within our industry and with\nrelated stakeholders. \nNGA was founded in 1948. In 2018, we combined with the Glass Association of North America (GANA) to create the largest trade association serving our industry. \nThe NGA Board of Directors and other industry volunteers and stakeholders have identified the Association’s Purpose and Vision and set our Goals for the next few years.\nNGA is the authority and resource for its members and the industry to grow successful businesses and to champion the benefits of glazing and glass building products.', 'NGA được thành lập vào năm 1948. Năm 2018, hiệp hội đã kết hợp với Hiệp hội Kính Bắc Mỹ (GANA) để tạo ra hiệp hội thương mại lớn nhất phục vụ ngành của chúng tôi. 1.700 công ty thành viên của chúng tôi bao gồm các nhà thầu lắp kính, các công ty cung cấp dịch vụ kính trọn gói, các nhà chế tạo kính và kim loại, các nhà sản xuất kính chính và các nhà cung cấp sản phẩm xây dựng bằng kính.\nCộng đồng thành viên NGA có hơn 1.800 công ty và đại diện cho mọi khía cạnh của ngành lắp kính và sản phẩm xây dựng bằng kính.\n• Chúng tôi là thợ lắp kính theo hợp đồng.\n• Chúng tôi là các công ty cung cấp dịch vụ kính trọn gói.\n• Chúng tôi là các nhà chế tạo, nhà sản xuất và nhà cung cấp.\nNGA tự hào xây dựng cộng đồng cho các thành viên của mình—trong ngành của chúng tôi và với\ncác bên liên quan.\nNGA được thành lập vào năm 1948. Năm 2018, chúng tôi đã kết hợp với Hiệp hội Kính Bắc Mỹ (GANA) để tạo ra hiệp hội thương mại lớn nhất phục vụ ngành của chúng tôi.\nHội đồng quản trị NGA và các tình nguyện viên và bên liên quan khác trong ngành đã xác định Mục đích và Tầm nhìn của Hiệp hội và đặt ra Mục tiêu của chúng tôi trong vài năm tới.\nNGA là cơ quan có thẩm quyền và nguồn lực cho các thành viên và ngành công nghiệp phát triển các doanh nghiệp thành công và ủng hộ các lợi ích của các sản phẩm kính và xây dựng bằng kính.', 'NGA được thành lập vào năm 1948. Năm 2018, hiệp hội đã kết hợp với Hiệp hội Kính Bắc Mỹ (GANA) để tạo ra hiệp hội thương mại lớn nhất phục vụ ngành của chúng tôi. 1.700 công ty thành viên của chúng tôi bao gồm các nhà thầu lắp kính, các công ty cung cấp dịch vụ kính trọn gói, các nhà chế tạo kính và kim loại, các nhà sản xuất kính chính và các nhà cung cấp sản phẩm xây dựng bằng kính.', NULL, NULL, NULL, 'publisher/avatar/KY3I7ZH9RG1A7AQDG872.jpg', 0),
(4428, 'NISO - National Information Standards Organization', 'NISO - National Information Standards Organization', 'NISO is where content publishers, libraries, and software developers turn for information industry standards that allow them to work together. Through NISO, all of these communities are able to collaborate on mutually accepted standards - solutions that enhance their operations today and form a foundation for the future.\nNISO is where content publishers, libraries, and software developers turn for information industry standards that allow them to work together. Through NISO, all of these communities are able to collaborate on mutually accepted standards—solutions that enable them to better serve their customers, enhancing their operations today and forming a foundation for the future.\nNISO, the National Information Standards Organization, is a non-profit association accredited by the American National Standards Institute (ANSI). We identify, develop, maintain, and publish technical standards and recommended practices to manage information in today\'s continually changing digital environment. NISO standards apply to both traditional and new technologies and to information across its whole lifecycle, from creation through documentation, use, repurposing, storage, metadata, and preservation.\nFounded in 1939, incorporated as a not-for-profit education association in 1983, and assuming its current name the following year, NISO draws its support from the communities we serve. The leaders of more than 100 organizations in the fields of publishing, libraries, IT, and media serve as our Voting Members. Over 500 experts and practitioners from across the information community serve on NISO working groups, committees, and as officers of the association.\nThroughout the year we offer a cutting-edge educational program of webinars, virtual conferences, and training series focused on timely issues affecting all our stakeholder groups—libraries, publishers, and the vendors that serve them. Our annual NISO Plus conference brings together information professionals from around the world for conversations that become outcomes to be developed as projects, yielding solutions that benefit all. \nNISO recognizes that our standards must reflect global needs and that our community is increasingly interconnected and international. Designated by ANSI to represent U.S. interests as the Technical Advisory Group (TAG) to the International Organization for Standardization\'s (ISO) Technical Committee 46 on Information and Documentation (TC46), NISO also serves as the Secretariat for Subcommittee 9 on Identification and Description (SC9) with our Executive Director, Todd Carpenter, serving as the SC9 Secretary. We are well-positioned to bring together all interested parties, wherever they are based.', 'NISO là nơi các nhà xuất bản nội dung, thư viện và nhà phát triển phần mềm tìm đến để có các tiêu chuẩn của ngành thông tin cho phép họ làm việc cùng nhau. Thông qua NISO, tất cả các cộng đồng này có thể hợp tác về các tiêu chuẩn được chấp nhận chung - các giải pháp nâng cao hoạt động của họ hiện nay và tạo thành nền tảng cho tương lai.\nNISO là nơi các nhà xuất bản nội dung, thư viện và nhà phát triển phần mềm tìm đến để có các tiêu chuẩn của ngành thông tin cho phép họ làm việc cùng nhau. Thông qua NISO, tất cả các cộng đồng này có thể hợp tác về các tiêu chuẩn được chấp nhận chung - các giải pháp cho phép họ phục vụ khách hàng tốt hơn, nâng cao hoạt động của họ hiện nay và tạo thành nền tảng cho tương lai.\nNISO, Tổ chức Tiêu chuẩn Thông tin Quốc gia, là một hiệp hội phi lợi nhuận được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận. Chúng tôi xác định, phát triển, duy trì và công bố các tiêu chuẩn kỹ thuật và các thông lệ được khuyến nghị để quản lý thông tin trong môi trường kỹ thuật số liên tục thay đổi ngày nay. Các tiêu chuẩn của NISO áp dụng cho cả công nghệ truyền thống và công nghệ mới và cho thông tin trong toàn bộ vòng đời của thông tin, từ khi tạo thông qua tài liệu, sử dụng, tái sử dụng, lưu trữ, siêu dữ liệu và bảo quản.\nĐược thành lập vào năm 1939, hợp nhất thành một hiệp hội giáo dục phi lợi nhuận vào năm 1983 và đổi tên thành tên hiện tại vào năm sau, NISO nhận được sự hỗ trợ từ các cộng đồng mà chúng tôi phục vụ. Các nhà lãnh đạo của hơn 100 tổ chức trong lĩnh vực xuất bản, thư viện, CNTT và phương tiện truyền thông là Thành viên bỏ phiếu của chúng tôi. Hơn 500 chuyên gia và học viên từ khắp cộng đồng thông tin phục vụ trong các nhóm làm việc, ủy ban của NISO và với tư cách là cán bộ của hiệp hội.\nTrong suốt cả năm, chúng tôi cung cấp chương trình giáo dục tiên tiến gồm các hội thảo trên web, hội nghị trực tuyến và chuỗi đào tạo tập trung vào các vấn đề kịp thời ảnh hưởng đến tất cả các nhóm bên liên quan của chúng tôi—thư viện, nhà xuất bản và các nhà cung cấp phục vụ họ. Hội nghị NISO Plus thường niên của chúng tôi quy tụ các chuyên gia thông tin từ khắp nơi trên thế giới để thảo luận, các cuộc thảo luận sẽ trở thành kết quả để phát triển thành các dự án, đưa ra các giải pháp có lợi cho tất cả mọi người.\nNISO nhận ra rằng các tiêu chuẩn của chúng tôi phải phản ánh nhu cầu toàn cầu và cộng đồng của chúng tôi ngày càng kết nối và quốc tế hóa. Được ANSI chỉ định đại diện cho lợi ích của Hoa Kỳ với tư cách là Nhóm cố vấn kỹ thuật (TAG) cho Ủy ban kỹ thuật 46 về thông tin và tài liệu (TC46) của Tổ chức tiêu chuẩn hóa quốc tế (ISO), NISO cũng đóng vai trò là Ban thư ký của Tiểu ban 9 về nhận dạng và mô tả (SC9) với Giám đốc điều hành của chúng tôi, Todd Carpenter, đóng vai trò là Thư ký SC9. Chúng tôi có vị thế tốt để tập hợp tất cả các bên quan tâm, bất kể họ ở đâu.', 'NISO là nơi các nhà xuất bản nội dung, thư viện và nhà phát triển phần mềm tìm đến để có các tiêu chuẩn của ngành thông tin cho phép họ làm việc cùng nhau. Thông qua NISO, tất cả các cộng đồng này có thể hợp tác về các tiêu chuẩn được chấp nhận chung - các giải pháp nâng cao hoạt động của họ hiện nay và tạo thành nền tảng cho tương lai.', NULL, NULL, NULL, 'publisher/avatar/LKAOG7H4NHBAAA2LCPG2.jpg', 0),
(4429, 'NORSOK - NORSOK', 'NORSOK - NORSOK', 'The NORSOK standards are developed by the Norwegian petroleum industry to ensure adequate safety, value adding and cost effectiveness for petroleum industry developments and operations. Furthermore, NORSOK standards are as far as possible intended to replace oil company specifications and serve as references in the authorities regulations.\nThe private, independent foundation NORSØK is a national centre for the development of organic agriculture through interdisciplinary research and outreach. NORSØK also manages an organic farm. Our work is based on the four principles of organic agriculture: health, ecology, fairness and care. NORSØK and the farm are located in Tingvoll in Møre og Romsdal county.\nNORSØK contributes knowledge for increasing the sustainability of agriculture and society. Our staff covers a wide range of expertise, and provides a broad range of research, consulting and outreach services. NORSØK’s main areas of expertise are organic agriculture and food production, environmental science, sustainability and renewable energy.\nNORSØK currently has a staff of 27 employees. The managing director is Ms. Turid Strøm.\nStandards Norway is responsible for the development and publication of NORSOK. For users of the standards, it is therefore hugely beneficial to purchase standards and other additional products from us - straight from the source.\nWe offer a great selection of options and services reated to NORSOK standards, such as subscriptions with different service levels, several formats, requirements filtering, and more.\nSeveral major international companies emphasize in particular our flexible solutions when delivering NORSOK - we give you access to the standards you need.', 'Tiêu chuẩn NORSOK do ngành công nghiệp dầu mỏ Na Uy xây dựng nhằm đảm bảo an toàn, giá trị gia tăng và hiệu quả về chi phí cho các hoạt động và phát triển của ngành công nghiệp dầu mỏ. Hơn nữa, tiêu chuẩn NORSOK được thiết kế để thay thế các thông số kỹ thuật của công ty dầu mỏ và đóng vai trò là tài liệu tham khảo trong các quy định của chính quyền.\nTổ chức tư nhân, độc lập NORSØK là trung tâm quốc gia về phát triển nông nghiệp hữu cơ thông qua nghiên cứu và tiếp cận liên ngành. NORSØK cũng quản lý một trang trại hữu cơ. Công việc của chúng tôi dựa trên bốn nguyên tắc của nông nghiệp hữu cơ: sức khỏe, sinh thái, công bằng và chăm sóc. NORSØK và trang trại nằm ở Tingvoll thuộc hạt Møre og Romsdal.\nNORSØK đóng góp kiến ​​thức để tăng tính bền vững của nông nghiệp và xã hội. Đội ngũ nhân viên của chúng tôi bao gồm nhiều chuyên môn khác nhau và cung cấp nhiều dịch vụ nghiên cứu, tư vấn và tiếp cận. Các lĩnh vực chuyên môn chính của NORSØK là nông nghiệp hữu cơ và sản xuất thực phẩm, khoa học môi trường, tính bền vững và năng lượng tái tạo.\nNORSØK hiện có 27 nhân viên. Tổng giám đốc điều hành là bà Turid Strøm.\nStandards Norway chịu trách nhiệm phát triển và xuất bản NORSOK. Do đó, đối với người dùng các tiêu chuẩn, việc mua các tiêu chuẩn và các sản phẩm bổ sung khác từ chúng tôi - trực tiếp từ nguồn là vô cùng có lợi.\nChúng tôi cung cấp nhiều lựa chọn và dịch vụ liên quan đến các tiêu chuẩn NORSOK, chẳng hạn như đăng ký với các mức dịch vụ khác nhau, nhiều định dạng, lọc yêu cầu, v.v.\nMột số công ty quốc tế lớn đặc biệt nhấn mạnh đến các giải pháp linh hoạt của chúng tôi khi cung cấp NORSOK - chúng tôi cung cấp cho bạn quyền truy cập vào các tiêu chuẩn bạn cần.', 'Tổ chức tư nhân, độc lập NORSØK là trung tâm quốc gia về phát triển nông nghiệp hữu cơ thông qua nghiên cứu và tiếp cận liên ngành. NORSØK cũng quản lý một trang trại hữu cơ. Công việc của chúng tôi dựa trên bốn nguyên tắc của nông nghiệp hữu cơ: sức khỏe, sinh thái, công bằng và chăm sóc. NORSØK và trang trại nằm ở Tingvoll thuộc hạt Møre og Romsdal.', NULL, NULL, NULL, 'publisher/avatar/2ME2O8LFGVJIDVRBFYUW.jpg', 0),
(4430, 'NRC - National Research Council Canada', 'NRC - National Research Council Canada', 'The National Research Council of Canada (NRC) is the Government of Canada\'s premier research and technology organization. NRC works with clients and partners to provide innovation support, strategic research and scientific and technical services.\nThe NRC partners with Canadian industry to take research impacts from the lab to the marketplace, where people can experience the benefits. This market-driven focus delivers innovation faster, enhances people\'s lives and addresses some of the world\'s most pressing problems. We are responsive, creative and uniquely placed to partner with Canadian industry, to invest in strategic R&D programming that will address critical issues for our future.\nEach year our scientists, engineers and business experts work closely with thousands of Canadian firms, helping them bring new technologies to market. We have the people, expertise, services, licensing opportunities, national facilities and global networks to support Canadian businesses.\nIn this section, you will find more information about how the NRC is organized and governed, where we are located across Canada, and links to our corporate publications and financial statements.', 'Hội đồng Nghiên cứu Quốc gia Canada (NRC) là tổ chức nghiên cứu và công nghệ hàng đầu của Chính phủ Canada. NRC hợp tác với khách hàng và đối tác để cung cấp hỗ trợ đổi mới, nghiên cứu chiến lược và các dịch vụ khoa học và kỹ thuật.\nNRC hợp tác với ngành công nghiệp Canada để đưa tác động nghiên cứu từ phòng thí nghiệm ra thị trường, nơi mọi người có thể trải nghiệm những lợi ích. Trọng tâm hướng đến thị trường này mang lại sự đổi mới nhanh hơn, cải thiện cuộc sống của mọi người và giải quyết một số vấn đề cấp bách nhất trên thế giới. Chúng tôi phản ứng nhanh, sáng tạo và có vị thế độc đáo để hợp tác với ngành công nghiệp Canada, đầu tư vào chương trình R&D chiến lược sẽ giải quyết các vấn đề quan trọng cho tương lai của chúng tôi.\nHàng năm, các nhà khoa học, kỹ sư và chuyên gia kinh doanh của chúng tôi làm việc chặt chẽ với hàng nghìn công ty Canada, giúp họ đưa các công nghệ mới ra thị trường. Chúng tôi có con người, chuyên môn, dịch vụ, cơ hội cấp phép, cơ sở quốc gia và mạng lưới toàn cầu để hỗ trợ các doanh nghiệp Canada.\nTrong phần này, bạn sẽ tìm thấy thêm thông tin về cách thức tổ chức và quản lý NRC, nơi chúng tôi đặt trụ sở trên khắp Canada và các liên kết đến các ấn phẩm và báo cáo tài chính của công ty chúng tôi.', 'Hội đồng Nghiên cứu Quốc gia Canada (NRC) là tổ chức nghiên cứu và công nghệ hàng đầu của Chính phủ Canada. NRC hợp tác với khách hàng và đối tác để cung cấp hỗ trợ đổi mới, nghiên cứu chiến lược và các dịch vụ khoa học và kỹ thuật.', NULL, NULL, NULL, 'publisher/avatar/8NGHDBCCW64QMWN01TXN.jpg', 0),
(4431, 'NSC - Natural Stone Council', 'NSC - Natural Stone Council', 'The Natural Stone Council is a collaboration of businesses and trade associations that have joined forces to promote the use of natural stone in commercial, residential, government, institutional, educational and all types of applications interior and exterior.\nThe Natural Stone Institute is a trade association representing every aspect of the natural stone industry. The current membership exceeds 2,000 members in over 50 countries. The association offers a wide array of technical and training resources, professional development opportunities, regulatory advocacy, and networking events. Two prominent publications—the Dimension Stone Design Manual and Building Stone Magazine—raise awareness within the natural stone industry and in the design community for best practices and uses of natural stone.\nThe association serves as the authoritative source for safety and technical standards and information regarding the use of natural stone. It operates an industry accreditation program and two prestigious awards programs, as well as a continuing education program for architects and designers.\nThe Natural Stone Institute was formed in 2018 as a merger of the Marble Institute of America and the Building Stone Institute.  The Building Stone Institute was formed in 1894 as the International Cut Stone Contractors and Quarrymen’s Association; the name was changed to the Building Stone Institute in 1955. Established in 1903 as the National Association of Marble Dealers, the Marble Institute of America officially formed in 1944, when the association merged with the National Association of Marble Producers. In 1962, the National Association of Marble Builders merged with MIA. In 2021, the National Building Granite Quarriers Association (NBGQA) merged with the Natural Stone Institute. The NBGQA was founded in 1916.', 'Hội đồng Đá tự nhiên là sự hợp tác của các doanh nghiệp và hiệp hội thương mại đã hợp tác để thúc đẩy việc sử dụng đá tự nhiên trong thương mại, dân dụng, chính phủ, tổ chức, giáo dục và tất cả các loại ứng dụng nội thất và ngoại thất.\nViện Đá tự nhiên là một hiệp hội thương mại đại diện cho mọi khía cạnh của ngành đá tự nhiên. Số lượng thành viên hiện tại vượt quá 2.000 thành viên tại hơn 50 quốc gia. Hiệp hội cung cấp nhiều nguồn lực kỹ thuật và đào tạo, cơ hội phát triển chuyên môn, vận động pháp lý và các sự kiện giao lưu. Hai ấn phẩm nổi bật—Sổ tay thiết kế đá Dimension và Tạp chí đá xây dựng—nâng cao nhận thức trong ngành đá tự nhiên và trong cộng đồng thiết kế về các thông lệ và cách sử dụng đá tự nhiên tốt nhất.\nHiệp hội đóng vai trò là nguồn thông tin có thẩm quyền về các tiêu chuẩn an toàn và kỹ thuật cũng như thông tin liên quan đến việc sử dụng đá tự nhiên. Hiệp hội điều hành một chương trình công nhận ngành và hai chương trình giải thưởng danh giá, cũng như một chương trình giáo dục liên tục cho các kiến ​​trúc sư và nhà thiết kế.\nViện Đá tự nhiên được thành lập vào năm 2018 thông qua việc sáp nhập Viện Đá cẩm thạch Hoa Kỳ và Viện Đá xây dựng. Viện Đá xây dựng được thành lập vào năm 1894 với tên gọi là Hiệp hội Nhà thầu đá cắt và Khai thác đá quốc tế; tên được đổi thành Viện Đá Xây Dựng vào năm 1955. Được thành lập vào năm 1903 với tên gọi là Hiệp hội Đại lý Đá cẩm thạch Quốc gia, Viện Đá cẩm thạch Hoa Kỳ chính thức thành lập vào năm 1944, khi hiệp hội này sáp nhập với Hiệp hội Sản xuất Đá cẩm thạch Quốc gia. Năm 1962, Hiệp hội Xây dựng Đá cẩm thạch Quốc gia sáp nhập với MIA. Năm 2021, Hiệp hội Khai thác Đá granit Xây dựng Quốc gia (NBGQA) sáp nhập với Viện Đá tự nhiên. NBGQA được thành lập vào năm 1916.', 'Hội đồng Đá tự nhiên là sự hợp tác của các doanh nghiệp và hiệp hội thương mại đã hợp tác để thúc đẩy việc sử dụng đá tự nhiên trong thương mại, dân dụng, chính phủ, tổ chức, giáo dục và tất cả các loại ứng dụng nội thất và ngoại thất.\nViện Đá tự nhiên là một hiệp hội thương mại đại diện cho mọi khía cạnh của ngành đá tự nhiên.', NULL, NULL, NULL, 'publisher/avatar/4IWNGA2KJ2VZYRIIS0XJ.jpg', 0),
(4432, 'NSF - NSF', 'NSF - NSF', 'Dedicated to research, education, testing, certification, and service, NSF International (formerly the National Sanitation Foundation), develops standards and criteria for health-related equipment, products and services worldwide. The organization also assists companies preparing for ISO 9000 and 14000 registration.', 'Dành riêng cho nghiên cứu, giáo dục, thử nghiệm, chứng nhận và dịch vụ, NSF International (trước đây là National Sanitation Foundation), phát triển các tiêu chuẩn và tiêu chí cho thiết bị, sản phẩm và dịch vụ liên quan đến sức khỏe trên toàn thế giới. Tổ chức này cũng hỗ trợ các công ty chuẩn bị đăng ký ISO 9000 và 14000.', 'Dành riêng cho nghiên cứu, giáo dục, thử nghiệm, chứng nhận và dịch vụ, NSF International (trước đây là National Sanitation Foundation), phát triển các tiêu chuẩn và tiêu chí cho thiết bị, sản phẩm và dịch vụ liên quan đến sức khỏe trên toàn thế giới. Tổ chức này cũng hỗ trợ các công ty chuẩn bị đăng ký ISO 9000 và 14000.', NULL, NULL, '13*13.020*13.060*23*23.040*65*83*83.140*91*91.140*97*97.040*97.220', 'publisher/avatar/VIK0ECT0HZ33RZA1SNND.png', 0),
(4433, 'NZS - Standards New Zealand', 'NZS - Standards New Zealand', 'Standards New Zealand is New Zealand\'s leading developer of standards and standards-based solutions and national standards body. Our role includes:\n\nStandards development. We work with stakeholders from a variety of sectors to develop new standards, update existing standards, or adopt overseas standards for New Zealand industries. Most of our standards are developed in partnership with Standards Australia.\nInternational participation. We are the internationally recognised and statutorily independent national standards body for New Zealand. We coordinate international review group membership so that New Zealanders can participate in the development of international standards. This ensures New Zealand has a voice in the international standards community.\nAccess to standards. We publish, sell and facilitate access to New Zealand, joint Australian/New Zealand, and international standards.\nOur services and history date back to 1932, when following the devastating 1931 Hawkes Bay earthquake it became clear New Zealand needed building standards that were appropriate to its unique environment.\n\nHistory of Standards New Zealand\n\nOur extensive experience means that our products and services carry a reputation for being trusted, authoritative, accurate and credible. Over the years, we have forged and maintained strong working relationships with a wide range of government organisations, industry groups and the business sector.\n\nAlthough we develop and provide access to standards, we are not subject matter or technical experts in their content. We do not enforce or ensure compliance with standards, and we are not a certification body that determines whether products or practices comply with standards.\n\nWe are a business unit within the Ministry of Business, Innovation and Employment (MBIE). However, we do not receive direct government funding, and operate on a cost recovery basis.\n\nAs a part of MBIE, Standards New Zealand is well-placed to engage with a wide range of government agencies. This produces new opportunities for standards to be adopted as a means for supporting existing and planned government regulations and regulatory reforms.', 'Standards New Zealand là đơn vị phát triển tiêu chuẩn và giải pháp dựa trên tiêu chuẩn hàng đầu của New Zealand và là cơ quan tiêu chuẩn quốc gia. Vai trò của chúng tôi bao gồm:\n\nPhát triển tiêu chuẩn. Chúng tôi làm việc với các bên liên quan từ nhiều lĩnh vực khác nhau để phát triển các tiêu chuẩn mới, cập nhật các tiêu chuẩn hiện có hoặc áp dụng các tiêu chuẩn nước ngoài cho các ngành công nghiệp của New Zealand. Hầu hết các tiêu chuẩn của chúng tôi được phát triển thông qua quan hệ đối tác với Standards Australia.\nTham gia quốc tế. Chúng tôi là cơ quan tiêu chuẩn quốc gia được công nhận trên toàn thế giới và độc lập theo luật định của New Zealand. Chúng tôi điều phối tư cách thành viên nhóm đánh giá quốc tế để người dân New Zealand có thể tham gia vào quá trình phát triển các tiêu chuẩn quốc tế. Điều này đảm bảo New Zealand có tiếng nói trong cộng đồng tiêu chuẩn quốc tế.\nTiếp cận các tiêu chuẩn. Chúng tôi xuất bản, bán và tạo điều kiện tiếp cận các tiêu chuẩn của New Zealand, tiêu chuẩn chung của Úc/New Zealand và tiêu chuẩn quốc tế.\nCác dịch vụ và lịch sử của chúng tôi có từ năm 1932, khi sau trận động đất Hawkes Bay năm 1931 tàn khốc, New Zealand nhận thấy rõ ràng rằng cần có các tiêu chuẩn xây dựng phù hợp với môi trường độc đáo của mình.\n\nLịch sử của Standards New Zealand\n\nKinh nghiệm sâu rộng của chúng tôi có nghĩa là các sản phẩm và dịch vụ của chúng tôi có uy tín là đáng tin cậy, có thẩm quyền, chính xác và đáng tin cậy. Trong nhiều năm qua, chúng tôi đã xây dựng và duy trì mối quan hệ làm việc chặt chẽ với nhiều tổ chức chính phủ, nhóm ngành và khu vực kinh doanh.\n\nMặc dù chúng tôi phát triển và cung cấp quyền truy cập vào các tiêu chuẩn, nhưng chúng tôi không phải là chuyên gia về chủ đề hoặc kỹ thuật trong nội dung của chúng. Chúng tôi không thực thi hoặc đảm bảo tuân thủ các tiêu chuẩn và chúng tôi không phải là tổ chức chứng nhận xác định xem sản phẩm hoặc hoạt động có tuân thủ các tiêu chuẩn hay không.\n\nChúng tôi là một đơn vị kinh doanh thuộc Bộ Kinh doanh, Đổi mới và Việc làm (MBIE). Tuy nhiên, chúng tôi không nhận được tài trợ trực tiếp từ chính phủ và hoạt động trên cơ sở thu hồi chi phí.\n\nLà một phần của MBIE, Standards New Zealand có vị thế tốt để hợp tác với nhiều cơ quan chính phủ. Điều này tạo ra những cơ hội mới để áp dụng các tiêu chuẩn như một phương tiện hỗ trợ các quy định hiện hành và theo kế hoạch của chính phủ cũng như các cải cách quy định.', 'Standards New Zealand là đơn vị phát triển tiêu chuẩn và giải pháp dựa trên tiêu chuẩn hàng đầu của New Zealand và là cơ quan tiêu chuẩn quốc gia.', NULL, NULL, NULL, 'publisher/avatar/GSQLSARD722T9ZJLWQYO.jpg', 0),
(4434, 'OPEI - Outdoor Power Equipment Institute', 'OPEI - Outdoor Power Equipment Institute', 'The Outdoor Power Equipment Institute (OPEI) is an international trade association representing more than 100 small engine, utility vehicle and outdoor power equipment manufacturers and suppliers. OPEI is a recognized Standards Development Organization for the American National Standards Institute (ANSI) and active internationally through the International Standards Organization (ISO) in the development of safety and performance standards for outdoor power equipment.\nThe Outdoor Power Equipment Institute (OPEI) represents the interests of power equipment, small engine, battery power systems, and UTV, golf car, and personal transport vehicle manufacturers and suppliers. We also develop industry standards both in the U.S. and internationally.\nThe OPEI mission is, and has always been, to serve and protect the interests of the outdoor power equipment industry. Our aim is to expertly and humbly guide our members through the issues that we’re faced with so that the good that our equipment does – real, tangible good you can enjoy outdoors every day – can leave a lasting impact on the world.\nOPEI committees are established to develop new standards for their respective product sector, if deemed necessary by the membership, and are responsible for the continued maintenance of their respective American National Standards (ANS). Standards are subject to a five-year review process when they are either reaffirmed, revised, or withdrawn.\nOPEI technical committees are responsible for the drafting of all standards, and revision to existing standards, before a draft is circulated through the OPEI canvass and ANSI public review process. These methods are used to assure that all standards are open to review and revision by a diverse panel of stakeholders, including consumers, academia, and government. Complete details of OPEI procedures can be found in the OPEI Standards Development Procedures. These same procedures are the basis for OPEI’s accreditation as an ANSI Standard Development Organization (SDO). OPEI procedures are also subject to regular ANSI audit to assure compliance and continuous improvement.', 'Viện Thiết bị Điện Ngoài trời (OPEI) là một hiệp hội thương mại quốc tế đại diện cho hơn 100 nhà sản xuất và cung cấp động cơ nhỏ, xe tiện ích và thiết bị điện ngoài trời. OPEI là Tổ chức Phát triển Tiêu chuẩn được công nhận của Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) và hoạt động quốc tế thông qua Tổ chức Tiêu chuẩn Quốc tế (ISO) trong việc phát triển các tiêu chuẩn về an toàn và hiệu suất cho thiết bị điện ngoài trời.\nViện Thiết bị Điện Ngoài trời (OPEI) đại diện cho lợi ích của các nhà sản xuất và cung cấp thiết bị điện, động cơ nhỏ, hệ thống điện bằng pin và UTV, xe golf và phương tiện vận chuyển cá nhân. Chúng tôi cũng phát triển các tiêu chuẩn công nghiệp tại Hoa Kỳ và quốc tế.\nSứ mệnh của OPEI là và luôn là phục vụ và bảo vệ lợi ích của ngành thiết bị điện ngoài trời. Mục tiêu của chúng tôi là hướng dẫn các thành viên của mình một cách chuyên nghiệp và khiêm tốn thông qua các vấn đề mà chúng tôi phải đối mặt để những điều tốt đẹp mà thiết bị của chúng tôi mang lại - những điều tốt đẹp thực sự, hữu hình mà bạn có thể tận hưởng ngoài trời mỗi ngày - có thể để lại tác động lâu dài đến thế giới.\nCác ủy ban OPEI được thành lập để phát triển các tiêu chuẩn mới cho lĩnh vực sản phẩm tương ứng của họ, nếu các thành viên cho là cần thiết, và chịu trách nhiệm duy trì liên tục các Tiêu chuẩn quốc gia Hoa Kỳ (ANS) tương ứng của họ. Các tiêu chuẩn phải trải qua quá trình xem xét trong năm năm khi chúng được tái khẳng định, sửa đổi hoặc thu hồi.\nCác ủy ban kỹ thuật OPEI chịu trách nhiệm soạn thảo tất cả các tiêu chuẩn và sửa đổi các tiêu chuẩn hiện có trước khi bản dự thảo được lưu hành thông qua quá trình rà soát của OPEI và quá trình đánh giá công khai của ANSI. Các phương pháp này được sử dụng để đảm bảo rằng tất cả các tiêu chuẩn đều có thể được nhiều bên liên quan khác nhau, bao gồm người tiêu dùng, học viện và chính phủ, xem xét và sửa đổi. Có thể tìm thấy thông tin chi tiết đầy đủ về các thủ tục của OPEI trong Quy trình phát triển tiêu chuẩn của OPEI. Các thủ tục tương tự này là cơ sở để OPEI được công nhận là Tổ chức phát triển tiêu chuẩn ANSI (SDO). Các thủ tục của OPEI cũng phải chịu sự kiểm toán thường xuyên của ANSI để đảm bảo tuân thủ và cải tiến liên tục.', 'Viện Thiết bị Điện Ngoài trời (OPEI) là một hiệp hội thương mại quốc tế đại diện cho hơn 100 nhà sản xuất và cung cấp động cơ nhỏ, xe tiện ích và thiết bị điện ngoài trời. OPEI là Tổ chức Phát triển Tiêu chuẩn được công nhận của Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) và hoạt động quốc tế thông qua Tổ chức Tiêu chuẩn Quốc tế (ISO) trong việc phát triển các tiêu chuẩn về an toàn và hiệu suất cho thiết bị điện ngoài trời.', NULL, NULL, NULL, 'publisher/avatar/WLFIOFS8KE6YAN1JHT9S.png', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4435, 'PCI - Precast/Prestressed Concrete Institute', 'PCI - Precast/Prestressed Concrete Institute', 'Founded in 1954, the Precast/Prestressed Concrete Institute (PCI) is the technical institute and trade association for the precast/prestressed concrete structures industry. As a technical institute, PCI develops, maintains, and disseminates the Body of Knowledge for the design, fabrication, and erection of precast concrete structures and systems.\nPCI is the premier member association dedicated to precast concrete professionals and organizations.\nPCI members include businesses and individuals, offering a unique opportunity to access the entirety of the precast concrete business landscape.\nMembership with PCI continues to provide value within the precast concrete industry as demonstrated in our growth and retention rates. It’s an excellent time to be a PCI member with access to a myriad of tools and benefits to grow your business.\nAs the prestressed industry grew in the early 1950s, it became apparent that a central organization was essential to provide a unity of purpose in the industry. PCI was legally chartered as the Prestressed Concrete Institute on June 18, 1954, in Tampa, Fla.\nOriginally, six companies formed the institute, Cone Brother, R.H. Wright & Co., Dura-Stress, West Coast Shell Corporation, Lakeland Engineering Associates and Lakeland Concrete. Douglas P. Cone served as the first president of PCI.\nFrom the beginning, PCI recognized the importance of developing a body of knowledge as a technical institute. PCI published its first specification, “Specification for Pre-Tensioned Bonded Prestressed Concrete,” in October 1954. This publication was developed by Harry Edwards.\nAdditionally, the first issue of the PCI Journal was published shortly after PCI’s inception. The issue debuted at PCI’s second annual conference in May 1956. In September of 1957, PCI’s Technical Activities Council (TAC) was formed. TAC continues to oversee the technical work of the institute.\nIn December 1959, PCI moved its headquarters from Florida to Chicago, where it is based today.', 'Được thành lập vào năm 1954, Viện Bê tông đúc sẵn/Ứng suất trước (PCI) là viện kỹ thuật và hiệp hội thương mại cho ngành công nghiệp kết cấu bê tông đúc sẵn/Ứng suất trước. Là một viện kỹ thuật, PCI phát triển, duy trì và phổ biến Cơ sở kiến ​​thức về thiết kế, chế tạo và lắp dựng các hệ thống và kết cấu bê tông đúc sẵn.\nPCI là hiệp hội thành viên hàng đầu dành riêng cho các tổ chức và chuyên gia bê tông đúc sẵn.\nCác thành viên PCI bao gồm các doanh nghiệp và cá nhân, mang đến cơ hội độc đáo để tiếp cận toàn bộ bối cảnh kinh doanh bê tông đúc sẵn.\nViệc trở thành thành viên của PCI tiếp tục mang lại giá trị trong ngành bê tông đúc sẵn như đã chứng minh trong tỷ lệ tăng trưởng và duy trì của chúng tôi. Đây là thời điểm tuyệt vời để trở thành thành viên PCI với quyền truy cập vào vô số công cụ và lợi ích để phát triển doanh nghiệp của bạn.\nKhi ngành công nghiệp ứng suất trước phát triển vào đầu những năm 1950, rõ ràng là một tổ chức trung tâm là điều cần thiết để cung cấp sự thống nhất về mục đích trong ngành. PCI được cấp giấy phép hợp pháp là Viện Bê tông ứng suất trước vào ngày 18 tháng 6 năm 1954 tại Tampa, Florida.\nBan đầu, sáu công ty đã thành lập viện, Cone Brother, R.H. Wright & Co., Dura-Stress, West Coast Shell Corporation, Lakeland Engineering Associates và Lakeland Concrete. Douglas P. Cone là chủ tịch đầu tiên của PCI.\nNgay từ đầu, PCI đã nhận ra tầm quan trọng của việc phát triển khối kiến ​​thức như một viện kỹ thuật. PCI đã công bố thông số kỹ thuật đầu tiên của mình, \"Thông số kỹ thuật cho Bê tông ứng suất trước liên kết căng trước\" vào tháng 10 năm 1954. Ấn phẩm này được phát triển bởi Harry Edwards.\nNgoài ra, ấn bản đầu tiên của Tạp chí PCI đã được xuất bản ngay sau khi PCI thành lập. Ấn bản này ra mắt tại hội nghị thường niên lần thứ hai của PCI vào tháng 5 năm 1956. Vào tháng 9 năm 1957, Hội đồng hoạt động kỹ thuật (TAC) của PCI được thành lập. TAC tiếp tục giám sát công việc kỹ thuật của viện.\nVào tháng 12 năm 1959, PCI chuyển trụ sở chính từ Florida đến Chicago, nơi đặt trụ sở hiện nay.', 'Được thành lập vào năm 1954, Viện Bê tông đúc sẵn/Ứng suất trước (PCI) là viện kỹ thuật và hiệp hội thương mại cho ngành công nghiệp kết cấu bê tông đúc sẵn/Ứng suất trước. Là một viện kỹ thuật, PCI phát triển, duy trì và phổ biến Cơ sở kiến ​​thức về thiết kế, chế tạo và lắp dựng các hệ thống và kết cấu bê tông đúc sẵn.', NULL, NULL, NULL, 'publisher/avatar/SZVKKMDJ2BSUYRRM42II.jpg', 0),
(4436, 'PDA - Parenteral Drug Association', 'PDA - Parenteral Drug Association', 'The Parenteral Drug Association (PDA) is the leading global provider of science, technology and regulatory information and education for the pharmaceutical and biopharmaceutical community.\nThe Parenteral Drug Association (PDA) is the leading global provider of science, technology, and regulatory information.  PDA creates awareness and understanding of important issues facing the pharmaceutical and biopharmaceutical community and delivers high-quality, relevant education to the industry. Since its founding in 1946 as a nonprofit organization, PDA has been committed to developing scientifically sound, practical technical information and expertise to advance pharmaceutical/biopharmaceutical manufacturing science and regulation, so members can better serve patients.\nPDA was founded in 1946 as the Parenteral Drug Association by a small group of pharmaceutical manufacturers who recognized the need for an organization to disseminate technical information within the industry. Today, coordinated through its headquarters and manufacturing training facility in Bethesda, Maryland, and Europe office in Berlin, Germany, PDA volunteers worldwide carry out its mission of promoting the exchange of rapidly evolving information on the latest technology and regulations concerning high-quality pharmaceutical production.\nPDA is the recognized authoritative voice and leading technical organization in the field of parenteral science and technology. Through the development of Technical Reports and other documents and responses to regulatory initiatives, PDA and its members influence the future course of pharmaceutical products technology.\nWith more than 10,500 individual members worldwide, PDA draws its strength from the technical expertise of its membership. Conferences, meetings, and courses bring together pharmaceutical manufacturers, suppliers, users, academics, and regulatory officials to discuss and boost issues of mutual interest. These exchanges of technical knowledge, expertise, and best practices assist the advancement of pharmaceutical science and technology in the interest of public health.', 'Hiệp hội Thuốc tiêm (PDA) là nhà cung cấp thông tin khoa học, công nghệ và quy định và giáo dục hàng đầu toàn cầu cho cộng đồng dược phẩm và dược phẩm sinh học.\nHiệp hội Thuốc tiêm (PDA) là nhà cung cấp thông tin khoa học, công nghệ và quy định hàng đầu toàn cầu. PDA nâng cao nhận thức và hiểu biết về các vấn đề quan trọng mà cộng đồng dược phẩm và dược phẩm sinh học phải đối mặt và cung cấp giáo dục chất lượng cao, có liên quan cho ngành. Kể từ khi thành lập vào năm 1946 với tư cách là một tổ chức phi lợi nhuận, PDA đã cam kết phát triển thông tin kỹ thuật thực tế, có cơ sở khoa học và chuyên môn để thúc đẩy khoa học và quy định sản xuất dược phẩm/dược phẩm sinh học, để các thành viên có thể phục vụ bệnh nhân tốt hơn.\nPDA được thành lập vào năm 1946 với tên gọi Hiệp hội Thuốc tiêm bởi một nhóm nhỏ các nhà sản xuất dược phẩm nhận ra nhu cầu về một tổ chức để phổ biến thông tin kỹ thuật trong ngành. Ngày nay, thông qua trụ sở chính và cơ sở đào tạo sản xuất tại Bethesda, Maryland và văn phòng Châu Âu tại Berlin, Đức, các tình nguyện viên PDA trên toàn thế giới thực hiện sứ mệnh thúc đẩy trao đổi thông tin phát triển nhanh chóng về công nghệ và quy định mới nhất liên quan đến sản xuất dược phẩm chất lượng cao.\nPDA là tiếng nói có thẩm quyền được công nhận và là tổ chức kỹ thuật hàng đầu trong lĩnh vực khoa học và công nghệ tiêm truyền. Thông qua việc phát triển Báo cáo kỹ thuật và các tài liệu khác cũng như phản hồi đối với các sáng kiến ​​quản lý, PDA và các thành viên của mình tác động đến tiến trình tương lai của công nghệ sản phẩm dược phẩm.\nVới hơn 10.500 thành viên cá nhân trên toàn thế giới, PDA tận dụng sức mạnh của mình từ chuyên môn kỹ thuật của các thành viên. Các hội nghị, cuộc họp và khóa học quy tụ các nhà sản xuất dược phẩm, nhà cung cấp, người dùng, học giả và viên chức quản lý để thảo luận và thúc đẩy các vấn đề cùng quan tâm. Những trao đổi về kiến ​​thức kỹ thuật, chuyên môn và thông lệ tốt nhất này hỗ trợ sự tiến bộ của khoa học và công nghệ dược phẩm vì lợi ích của sức khỏe cộng đồng.', 'Hiệp hội Thuốc tiêm (PDA) là nhà cung cấp thông tin khoa học, công nghệ và quy định và giáo dục hàng đầu toàn cầu cho cộng đồng dược phẩm và dược phẩm sinh học.', NULL, NULL, NULL, 'publisher/avatar/CJNNBO6BV3P01UM8NLZD.png', 0),
(4437, 'PEI - Petroleum Equipment Institute', 'PEI - Petroleum Equipment Institute', 'The Petroleum Equipment Institute is a trade association whose members manufacture, distribute and service petroleum marketing and liquid-handling equipment. Founded in 1951, PEI represents more than 1,600 member companies located in all 50 states and more than 80 countries. Members include manufacturers, sellers and installers of equipment used in service stations, terminals, bulk plants, fuel, oil and gasoline delivery, and similar petroleum marketing operations.', 'Viện Thiết bị Dầu khí là một hiệp hội thương mại có các thành viên sản xuất, phân phối và bảo dưỡng thiết bị tiếp thị dầu khí và xử lý chất lỏng. Được thành lập vào năm 1951, PEI đại diện cho hơn 1.600 công ty thành viên có trụ sở tại tất cả 50 tiểu bang và hơn 80 quốc gia. Các thành viên bao gồm các nhà sản xuất, người bán và người lắp đặt thiết bị được sử dụng trong các trạm dịch vụ, nhà ga, nhà máy số lượng lớn, giao nhiên liệu, dầu và xăng, và các hoạt động tiếp thị dầu khí tương tự.', 'Viện Thiết bị Dầu khí là một hiệp hội thương mại có các thành viên sản xuất, phân phối và bảo dưỡng thiết bị tiếp thị dầu khí và xử lý chất lỏng. Được thành lập vào năm 1951, PEI đại diện cho hơn 1.600 công ty thành viên có trụ sở tại tất cả 50 tiểu bang và hơn 80 quốc gia. Các thành viên bao gồm các nhà sản xuất, người bán và người lắp đặt thiết bị được sử dụng trong các trạm dịch vụ, nhà ga, nhà máy số lượng lớn, giao nhiên liệu, dầu và xăng, và các hoạt động tiếp thị dầu khí tương tự.', NULL, NULL, NULL, 'publisher/avatar/Q2MCY3L4WXM212XXN270.png', 0),
(4438, 'PIA - Parachute Industry Association', 'PIA - Parachute Industry Association', 'PIA’s mission is to advance and support the growth, development, training and safety of parachuting activities and engage and serve participants in the parachuting industry.\nAs evidenced by what we have accomplished over the last four decades, the Parachute Industry Association is committed to advancing the growth, development, training and safety of parachuting. At the foundation of our industry is a close-knit community of civilian and military skydivers worldwide … which is why at PIA we have always done this important work in tandem with – rather than on behalf of – our members.', 'Sứ mệnh của PIA là thúc đẩy và hỗ trợ sự tăng trưởng, phát triển, đào tạo và an toàn của các hoạt động nhảy dù và thu hút và phục vụ những người tham gia vào ngành công nghiệp nhảy dù.\nNhư bằng chứng là những gì chúng tôi đã đạt được trong bốn thập kỷ qua, Hiệp hội Công nghiệp Nhảy dù cam kết thúc đẩy sự tăng trưởng, phát triển, đào tạo và an toàn của hoạt động nhảy dù. Nền tảng của ngành công nghiệp của chúng tôi là một cộng đồng gắn bó chặt chẽ của những người nhảy dù dân sự và quân sự trên toàn thế giới ... đó là lý do tại sao tại PIA, chúng tôi luôn thực hiện công việc quan trọng này cùng với - chứ không phải thay mặt cho - các thành viên của chúng tôi.', 'Sứ mệnh của PIA là thúc đẩy và hỗ trợ sự tăng trưởng, phát triển, đào tạo và an toàn của các hoạt động nhảy dù và thu hút và phục vụ những người tham gia vào ngành công nghiệp nhảy dù.\nNhư bằng chứng là những gì chúng tôi đã đạt được trong bốn thập kỷ qua, Hiệp hội Công nghiệp Nhảy dù cam kết thúc đẩy sự tăng trưởng, phát triển, đào tạo và an toàn của hoạt động nhảy dù. Nền tảng của ngành công nghiệp của chúng tôi là một cộng đồng gắn bó chặt chẽ của những người nhảy dù dân sự và quân sự trên toàn thế giới ... đó là lý do tại sao tại PIA, chúng tôi luôn thực hiện công việc quan trọng này cùng với - chứ không phải thay mặt cho - các thành viên của chúng tôi.', NULL, NULL, NULL, 'publisher/avatar/8ZCWSHS4V1H2RFCIOF1S.jpg', 0),
(4439, 'PIP - Process Industry Practices', 'PIP - Process Industry Practices', 'Process Industry Practices from PIP help increase the value of the engineering/ procurement/ construction process for the U.S. process industry and enhance compliance with safety, health and environmental objectives. PIP practices harmonize standards across the following engineering disciplines: Civil/Structural/Architectural, Coatings/Insulation/Refractory, Machinery, Electrical, P&ID, Piping, Process Control/Analyzers, and Vessels.\nPIP is dedicated to harmonizing internal company standards and practices around design, procurement, construction, and maintenance.\nPIP members are dedicated to harmonizing internal company standards and practices around design, procurement, construction, and maintenance. Our members are process industry owners and engineering construction contractors focused on minimizing total cost of ownership, reducing plant operating and installation costs, and standardizing non-proprietary processes. The organization works under the auspices of the Construction Industry Institute (CII), an organized research unit controlled by The University of Texas and operating within the Cockrell School of Engineering.\nPIP empowers economic progress and capital efficiency by translating applied research into industry best practices. Our mission centers around collaboration, producing a library of engineering practices encompassing globally relevant guidance and technical criteria within a program that provides opportunity for professional education and leadership development.', 'Các hoạt động thực hành của ngành công nghiệp quy trình từ PIP giúp tăng giá trị của quy trình kỹ thuật/mua sắm/xây dựng cho ngành công nghiệp quy trình của Hoa Kỳ và tăng cường tuân thủ các mục tiêu về an toàn, sức khỏe và môi trường. Các hoạt động của PIP hài hòa các tiêu chuẩn trong các lĩnh vực kỹ thuật sau: Xây dựng/Kết cấu/Kiến trúc, Sơn phủ/Cách nhiệt/Chịu nhiệt, Máy móc, Điện, P&ID, Đường ống, Kiểm soát quy trình/Máy phân tích và Tàu.\nPIP cam kết hài hòa các tiêu chuẩn và hoạt động thực hành nội bộ của công ty xung quanh thiết kế, mua sắm, xây dựng và bảo trì.\nCác thành viên của PIP cam kết hài hòa các tiêu chuẩn và hoạt động thực hành nội bộ của công ty xung quanh thiết kế, mua sắm, xây dựng và bảo trì. Các thành viên của chúng tôi là chủ sở hữu ngành công nghiệp quy trình và nhà thầu xây dựng kỹ thuật tập trung vào việc giảm thiểu tổng chi phí sở hữu, giảm chi phí vận hành và lắp đặt nhà máy và chuẩn hóa các quy trình không độc quyền. Tổ chức này hoạt động dưới sự bảo trợ của Viện Công nghiệp Xây dựng (CII), một đơn vị nghiên cứu có tổ chức do Đại học Texas kiểm soát và hoạt động trong Trường Kỹ thuật Cockrell.\nPIP thúc đẩy tiến bộ kinh tế và hiệu quả vốn bằng cách chuyển đổi nghiên cứu ứng dụng thành các hoạt động thực hành tốt nhất của ngành. Sứ mệnh của chúng tôi tập trung vào sự hợp tác, tạo ra một thư viện các hoạt động kỹ thuật bao gồm hướng dẫn có liên quan toàn cầu và các tiêu chí kỹ thuật trong một chương trình cung cấp cơ hội cho giáo dục chuyên nghiệp và phát triển khả năng lãnh đạo.', 'Các hoạt động thực hành của ngành công nghiệp quy trình từ PIP giúp tăng giá trị của quy trình kỹ thuật/mua sắm/xây dựng cho ngành công nghiệp quy trình của Hoa Kỳ và tăng cường tuân thủ các mục tiêu về an toàn, sức khỏe và môi trường. Các hoạt động của PIP hài hòa các tiêu chuẩn trong các lĩnh vực kỹ thuật sau: Xây dựng/Kết cấu/Kiến trúc, Sơn phủ/Cách nhiệt/Chịu nhiệt, Máy móc, Điện, P&ID, Đường ống, Kiểm soát quy trình/Máy phân tích và Tàu.', NULL, NULL, NULL, 'publisher/avatar/EY8O3XRROBATSVQJBPLH.jpg', 0),
(4440, 'PPI - Plastics Pipe Institute', 'PPI - Plastics Pipe Institute', 'The Plastics Pipe Institute Inc. (PPI) is the major trade association representing all segments of the plastics piping industry. PPI members share a common interest in broadening awareness and creating opportunities that expand market share and extend the use of plastics pipe in all its many applications. As an association, PPI focuses collaborative efforts to accumulate data, concentrate facts and target resources toward advancements in applications and increases in widespread usage.', 'Plastics Pipe Institute Inc. (PPI) là hiệp hội thương mại lớn đại diện cho tất cả các phân khúc của ngành ống nhựa. Các thành viên PPI chia sẻ mối quan tâm chung trong việc mở rộng nhận thức và tạo ra các cơ hội mở rộng thị phần và mở rộng việc sử dụng ống nhựa trong tất cả các ứng dụng của nó. Là một hiệp hội, PPI tập trung các nỗ lực hợp tác để tích lũy dữ liệu, tập trung các sự kiện và hướng các nguồn lực vào những tiến bộ trong các ứng dụng và tăng cường sử dụng rộng rãi.', 'Plastics Pipe Institute Inc. (PPI) là hiệp hội thương mại lớn đại diện cho tất cả các phân khúc của ngành ống nhựa. Các thành viên PPI chia sẻ mối quan tâm chung trong việc mở rộng nhận thức và tạo ra các cơ hội mở rộng thị phần và mở rộng việc sử dụng ống nhựa trong tất cả các ứng dụng của nó. Là một hiệp hội, PPI tập trung các nỗ lực hợp tác để tích lũy dữ liệu, tập trung các sự kiện và hướng các nguồn lực vào những tiến bộ trong các ứng dụng và tăng cường sử dụng rộng rãi.', NULL, NULL, NULL, 'publisher/avatar/QW681PG9EFAOO1JWXRZA.jpg', 0),
(4441, 'RIA-A3 - A3, Association For Advancing Automation', 'RIA-A3 - A3, Association For Advancing Automation', 'A3 is North America\'s largest automation trade association representing more than 1,100 organizations involved in robotics, artificial intelligence, machine vision & imaging, motion control & motors and related automation technologies.\nThe Association for Advancing Automation (A3) is an international trade group that serves the robotics industry. It was founded in 1974 and is headquartered in Ann Arbor, Michigan. The organization is involved in safety standards for robots,[1] and sponsors robotics conferences. On April 14, 2021 the Robotic Industries Association, AIA-Advancing Vision + Imaging (AIA), the Motion Control and Motors Association (MCMA), and A3 Mexico merged into A3, which had long acted as a long acted as an umbrella organisation for the individual trade organizations. \nA3 hosts the International Robot Safety Conference (IRSC). A3 also hosts an annual Workforce Development Day for students ages 12 and up with industry instructors to lean about technologies and careers related to automation and robotics across industries.', 'A3 là hiệp hội thương mại tự động hóa lớn nhất Bắc Mỹ đại diện cho hơn 1.100 tổ chức tham gia vào lĩnh vực robot, trí tuệ nhân tạo, thị giác máy và hình ảnh, điều khiển chuyển động và động cơ và các công nghệ tự động hóa liên quan.\nHiệp hội thúc đẩy tự động hóa (A3) là một nhóm thương mại quốc tế phục vụ cho ngành công nghiệp robot. Hiệp hội được thành lập vào năm 1974 và có trụ sở chính tại Ann Arbor, Michigan. Tổ chức này tham gia vào các tiêu chuẩn an toàn cho robot[1] và tài trợ cho các hội nghị về robot. Vào ngày 14 tháng 4 năm 2021, Hiệp hội công nghiệp robot, AIA-Advancing Vision + Imaging (AIA), Hiệp hội điều khiển chuyển động và động cơ (MCMA) và A3 Mexico đã sáp nhập thành A3, vốn từ lâu đã hoạt động như một tổ chức chung cho các tổ chức thương mại riêng lẻ.\nA3 tổ chức Hội nghị an toàn robot quốc tế (IRSC). A3 cũng tổ chức Ngày phát triển lực lượng lao động hàng năm cho học sinh từ 12 tuổi trở lên với các giảng viên trong ngành để tìm hiểu về các công nghệ và nghề nghiệp liên quan đến tự động hóa và robot trong các ngành.', 'A3 là hiệp hội thương mại tự động hóa lớn nhất Bắc Mỹ đại diện cho hơn 1.100 tổ chức tham gia vào lĩnh vực robot, trí tuệ nhân tạo, thị giác máy và hình ảnh, điều khiển chuyển động và động cơ và các công nghệ tự động hóa liên quan.', NULL, NULL, NULL, 'publisher/avatar/T45RF51HZKWEFCYSOXDP.png', 0),
(4442, 'RTCA - Radio Technical Commission for Aeronautics', 'RTCA - Radio Technical Commission for Aeronautics', 'RTCA works with the Federal Aviation Administration (FAA) to develop comprehensive, industry-vetted and endorsed standards that can be used as means of compliance with FAA regulations.', 'Ủy ban Kỹ thuật Vô tuyến Hàng không, Inc. (RTCA) là một tổ chức phi lợi nhuận có trụ sở tại Hoa Kỳ chuyên phát triển các tiêu chuẩn và hướng dẫn dựa trên sự đồng thuận cho ngành hàng không. Tổ chức này thường được biết đến với loạt tài liệu có tên \"DO\" (DO-xxx), viết tắt của \"Tài liệu của RTCA\".\nRTCA được thành lập vào năm 1935 và kể từ đó đã đóng một vai trò quan trọng trong việc định hình sự phát triển của các tiêu chuẩn và quy định hàng không. Nó tập hợp các bên liên quan trong ngành, bao gồm các cơ quan chính phủ, nhà sản xuất máy bay, hãng hàng không và nhà cung cấp công nghệ, để hợp tác giải quyết các thách thức kỹ thuật và vận hành trong ngành hàng không.\nCác tài liệu DO do RTCA tạo ra bao gồm nhiều chủ đề, bao gồm thông tin liên lạc, dẫn đường, giám sát, hệ thống máy bay và quản lý không lưu. Những tài liệu này làm cơ sở cho các yêu cầu chứng nhận, các phương pháp thực hành tốt nhất trong ngành và tuân thủ quy định trong lĩnh vực hàng không.\nViệc phát triển các tài liệu RTCA DO bao gồm một quy trình dựa trên sự đồng thuận, trong đó các nhóm làm việc bao gồm các chuyên gia trong ngành và các bên liên quan cộng tác để soạn thảo và xem xét các tiêu chuẩn. Những tài liệu này trải qua quá trình kiểm tra, phân tích và xác nhận nghiêm ngặt trước khi được xuất bản dưới dạng hướng dẫn của ngành.\nCác cơ quan quản lý, chẳng hạn như Cục Hàng không Liên bang (FAA) tại Hoa Kỳ, thường tham khảo các tài liệu RTCA DO trong quá trình xây dựng các quy định và yêu cầu chứng nhận. Các tiêu chuẩn và hướng dẫn do RTCA thiết lập được công nhận và áp dụng rộng rãi không chỉ ở Hoa Kỳ mà còn trên toàn thế giới.\nTóm lại, Ủy ban Kỹ thuật Vô tuyến Hàng không, Inc. (RTCA) là một tổ chức phát triển các tiêu chuẩn và hướng dẫn dựa trên sự đồng thuận cho ngành hàng không, với các tài liệu DO của tổ chức này được sử dụng rộng rãi làm tài liệu tham khảo cho việc tuân thủ quy định và các phương pháp hay nhất trong ngành.', 'Ủy ban Kỹ thuật Vô tuyến Hàng không, Inc. (RTCA) là một tổ chức phi lợi nhuận có trụ sở tại Hoa Kỳ chuyên phát triển các tiêu chuẩn và hướng dẫn dựa trên sự đồng thuận cho ngành hàng không.', 'RTCA', 'RTCA, Ủy ban Kỹ thuật Vô tuyến Hàng không (RTCA DO), Radio Technical Commission for Aeronautics, Inc. (RTCA DO), Tiêu chuẩn hiệp hội, Vô tuyến, hàng không', NULL, 'publisher/avatar/2V92V4C9GN0609HDH2DT.jpg', 0),
(4443, 'SAE - SAE International', 'SAE - SAE International', 'SAE standards are internationally recognized for their role in helping ensure the safety, quality, and effectiveness of products and services across the mobility engineering industry. They contain detailed production and interoperability guidelines; clarify legal and regulatory grey areas; condense product development cycles; ensure consistency and high quality in manufacturing; and lead the way to maximum performance.', 'Hiệp hội Tiêu chuẩn Ô tô (Society of Automotive Engineers - SAE) là một tổ chức quốc tế chuyên về tiêu chuẩn và nghiên cứu trong lĩnh vực công nghiệp ô tô và động cơ. SAE được thành lập vào năm 1905 tại Hoa Kỳ và có trụ sở chính tại Warrendale, Pennsylvania.\n\nSAE đóng vai trò quan trọng trong việc phát triển và công bố các tiêu chuẩn kỹ thuật, hướng dẫn và quy định cho ngành công nghiệp ô tô và các ngành công nghiệp liên quan. Các tiêu chuẩn SAE bao gồm các khía cạnh kỹ thuật như động cơ, hộp số, hệ thống điện, hệ thống treo, hệ thống phanh, hệ thống khung gầm và nhiều lĩnh vực khác.\n\nTiêu chuẩn SAE thường được sử dụng rộng rãi trong ngành ô tô trên toàn cầu và được công nhận bởi nhiều nhà sản xuất, nhà nghiên cứu, và các tổ chức liên quan. Các tiêu chuẩn SAE này giúp đảm bảo tính tương thích, an toàn, hiệu suất và chất lượng của các sản phẩm và công nghệ trong ngành công nghiệp ô tô.\n\nNgoài ra, SAE cũng tổ chức các hội thảo, hội nghị và hoạt động nghiên cứu để thúc đẩy sự giao lưu và chia sẻ kiến thức giữa các chuyên gia, kỹ sư và cán bộ công nghệ trong lĩnh vực ô tô.', 'Hiệp hội Tiêu chuẩn Ô tô (Society of Automotive Engineers - SAE) là một tổ chức quốc tế chuyên về tiêu chuẩn và nghiên cứu trong lĩnh vực công nghiệp ô tô và động cơ. SAE được thành lập vào năm 1905 tại Hoa Kỳ', 'SAE,ANSI/SAE,ANSI/AWS/SAE,SAE/USCAR', 'Hiệp hội Tiêu chuẩn Ô tô, Society of Automotive Engineers - SAE, Tiêu chuẩn ô tô, Tiêu chuẩn động cơ, Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', '01*19*43*49', 'publisher/avatar/K1Z92SCXBVVGDVLHAJ0T.jpg', 0),
(4444, 'SAIA - Scaffold and Access Industry Association', 'SAIA - Scaffold and Access Industry Association', 'SIA is the ANSI-approved developer of standards for the scaffold and access industry. SIA standards contain technical specifications developed and tested by scaffold experts, which prescribe rules governing the safety, construction, design, testing, care and use of various types of scaffolds.', 'SIA là đơn vị phát triển tiêu chuẩn được ANSI chấp thuận cho ngành giàn giáo và tiếp cận. Các tiêu chuẩn của SIA bao gồm các thông số kỹ thuật được các chuyên gia về giàn giáo phát triển và thử nghiệm, quy định các quy tắc quản lý an toàn, xây dựng, thiết kế, thử nghiệm, chăm sóc và sử dụng các loại giàn giáo khác nhau.', 'SIA là đơn vị phát triển tiêu chuẩn được ANSI chấp thuận cho ngành giàn giáo và tiếp cận. Các tiêu chuẩn của SIA bao gồm các thông số kỹ thuật được các chuyên gia về giàn giáo phát triển và thử nghiệm, quy định các quy tắc quản lý an toàn, xây dựng, thiết kế, thử nghiệm, chăm sóc và sử dụng các loại giàn giáo khác nhau.', NULL, NULL, NULL, 'publisher/avatar/V9GO1QBOKKPSG2PM42FQ.jpg', 0),
(4445, 'SCTE - Society of Cable Telecommunication Engineers', 'SCTE - Society of Cable Telecommunication Engineers', 'SCTE standards cover a wide range of industry needs --- from F connectors to protocols for high-speed data access over cable. SCTE is accredited by the American National Standards Institute (ANSI), recognized by the International Telecommunication Union (ITU), and works in cooperation with the European Telecommunications Standards Institute (ETSI).\nAs a not-for-profit member organization, SCTE moves member companies forward through continuous training for the workforce of tomorrow, and by putting leaders into the conversations that matter.\nSCTE is envisioning the future of connectivity, today. Through technological leadership and innovation, SCTE has served as the applied science leader for the cable telecommunication industry for more than five decades. As a not for profit, member organization, SCTE moves member companies forward through continuous training for the workforce of tomorrow and by putting leaders into the conversations that matter.\nSCTE is a professional association for the advancement of technology, standards and workforce education related to cable telecommunications engineering. Founded in 1969 as The Society of Cable Television Engineers, SCTE has a current membership of more than 19,000 individuals.\nProfit Through Interoperability. The SCTE Standards program is the only ANSI-accredited platform for developing technical specifications supporting cable telecommunications.\n\nAlready a member of SCTE Standards? Click below to access standards resources.', 'Tiêu chuẩn SCTE bao gồm nhiều nhu cầu của ngành --- từ đầu nối F đến các giao thức truy cập dữ liệu tốc độ cao qua cáp. SCTE được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận, được Liên minh Viễn thông Quốc tế (ITU) công nhận và hợp tác với Viện Tiêu chuẩn Viễn thông Châu Âu (ETSI).\nLà một tổ chức thành viên phi lợi nhuận, SCTE thúc đẩy các công ty thành viên tiến lên thông qua đào tạo liên tục cho lực lượng lao động của tương lai và đưa các nhà lãnh đạo vào các cuộc trò chuyện quan trọng.\nSCTE đang hình dung về tương lai của kết nối ngay từ hôm nay. Thông qua sự lãnh đạo và đổi mới công nghệ, SCTE đã trở thành đơn vị dẫn đầu về khoa học ứng dụng cho ngành viễn thông cáp trong hơn năm thập kỷ. Là một tổ chức thành viên phi lợi nhuận, SCTE thúc đẩy các công ty thành viên tiến lên thông qua đào tạo liên tục cho lực lượng lao động của tương lai và đưa các nhà lãnh đạo vào các cuộc trò chuyện quan trọng.\nSCTE là một hiệp hội chuyên nghiệp về sự tiến bộ của công nghệ, tiêu chuẩn và giáo dục lực lượng lao động liên quan đến kỹ thuật viễn thông cáp. Được thành lập vào năm 1969 với tên gọi là Hiệp hội Kỹ sư Truyền hình Cáp, SCTE hiện có hơn 19.000 thành viên.\nLợi nhuận thông qua khả năng tương tác. Chương trình Tiêu chuẩn SCTE là nền tảng duy nhất được ANSI công nhận để phát triển các thông số kỹ thuật hỗ trợ viễn thông cáp.\n\nBạn đã là thành viên của Tiêu chuẩn SCTE? Nhấp vào bên dưới để truy cập các tài nguyên tiêu chuẩn.', 'Tiêu chuẩn SCTE bao gồm nhiều nhu cầu của ngành --- từ đầu nối F đến các giao thức truy cập dữ liệu tốc độ cao qua cáp. SCTE được Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) công nhận, được Liên minh Viễn thông Quốc tế (ITU) công nhận và hợp tác với Viện Tiêu chuẩn Viễn thông Châu Âu (ETSI).', NULL, NULL, '29*29.060*31*31.220*33*33.020*33.160*33.170', 'publisher/avatar/6O6827014WFI9Z6KUJZ3.png', 0),
(4446, 'SDI - Steel Door Institute', 'SDI - Steel Door Institute', 'The Steel Door Institute (SDI) was established in 1954 as a voluntary, non-profit business association that develops quality and performance standards for steel doors and frames.\nThe Steel Door Institute produces quality and performance standards for steel doors and frames. And as the door and hardware industry evolves, our standards are updated to reflect current best practices. By specifying steel doors and frames to our standards and from SDI Certified manufacturers, you can be assured to receive high-quality products that fit your specific needs.', 'Viện Cửa thép (SDI) được thành lập vào năm 1954 như một hiệp hội kinh doanh tự nguyện, phi lợi nhuận, phát triển các tiêu chuẩn về chất lượng và hiệu suất cho cửa và khung thép.\nViện Cửa thép đưa ra các tiêu chuẩn về chất lượng và hiệu suất cho cửa và khung thép. Và khi ngành công nghiệp cửa và phần cứng phát triển, các tiêu chuẩn của chúng tôi được cập nhật để phản ánh các thông lệ tốt nhất hiện tại. Bằng cách chỉ định cửa và khung thép theo các tiêu chuẩn của chúng tôi và từ các nhà sản xuất được Chứng nhận SDI, bạn có thể yên tâm nhận được các sản phẩm chất lượng cao phù hợp với nhu cầu cụ thể của mình.', 'Viện Cửa thép (SDI) được thành lập vào năm 1954 như một hiệp hội kinh doanh tự nguyện, phi lợi nhuận, phát triển các tiêu chuẩn về chất lượng và hiệu suất cho cửa và khung thép.', NULL, NULL, NULL, 'publisher/avatar/D7KECK9R5HZJ2WVRCP5S.png', 0),
(4447, 'SES - The Society for Standards Professionals', 'SES - The Society for Standards Professionals', 'SES was founded in 1947 as the Standards Engineering Society, a not-for-profit professional membership society dedicated to furthering the knowledge and use of standards and standardization. SES provides a neutral forum where standards users and developers can come together to address mutual issues, opportunities, and interests in ways that work to the benefit of everyone involved with, or affected by, standards. SES members are primarily involved in the development, application, and use of company, government, national, regional, and international standards.', 'SES được thành lập vào năm 1947 với tên gọi là Standards Engineering Society, một hiệp hội thành viên chuyên nghiệp phi lợi nhuận dành riêng cho việc thúc đẩy kiến ​​thức và sử dụng các tiêu chuẩn và chuẩn hóa. SES cung cấp một diễn đàn trung lập nơi người dùng và nhà phát triển tiêu chuẩn có thể cùng nhau giải quyết các vấn đề, cơ hội và lợi ích chung theo cách có lợi cho tất cả mọi người liên quan đến hoặc bị ảnh hưởng bởi các tiêu chuẩn. Các thành viên của SES chủ yếu tham gia vào việc phát triển, ứng dụng và sử dụng các tiêu chuẩn của công ty, chính phủ, quốc gia, khu vực và quốc tế.', 'SES được thành lập vào năm 1947 với tên gọi là Standards Engineering Society, một hiệp hội thành viên chuyên nghiệp phi lợi nhuận dành riêng cho việc thúc đẩy kiến ​​thức và sử dụng các tiêu chuẩn và chuẩn hóa. SES cung cấp một diễn đàn trung lập nơi người dùng và nhà phát triển tiêu chuẩn có thể cùng nhau giải quyết các vấn đề, cơ hội và lợi ích chung theo cách có lợi cho tất cả mọi người liên quan đến hoặc bị ảnh hưởng bởi các tiêu chuẩn. Các thành viên của SES chủ yếu tham gia vào việc phát triển, ứng dụng và sử dụng các tiêu chuẩn của công ty, chính phủ, quốc gia, khu vực và quốc tế.', NULL, NULL, NULL, 'publisher/avatar/7OCMN54Y78CQ0HROSGAF.jpg', 0),
(4448, 'SIA - Security Industry Association', 'SIA - Security Industry Association', 'The Security Industry Association (SIA) is the leading trade association for global security solution providers, with over 1,400 innovative member companies representing thousands of security leaders and experts who shape the future of the security industry.\nAn ANSI-accredited standards developer, the Security Industry Association (SIA) creates standards that are open, enable easy integration of diverse components, and provide a means to establish predictable levels of performance. Participants shape the future of the industry, acquire industry intelligence, and enable rapid acceptance of products in new markets.', 'Hiệp hội Công nghiệp An ninh (SIA) là hiệp hội thương mại hàng đầu dành cho các nhà cung cấp giải pháp an ninh toàn cầu, với hơn 1.400 công ty thành viên sáng tạo đại diện cho hàng nghìn nhà lãnh đạo và chuyên gia an ninh định hình tương lai của ngành an ninh.\nLà một nhà phát triển tiêu chuẩn được ANSI công nhận, Hiệp hội Công nghiệp An ninh (SIA) tạo ra các tiêu chuẩn mở, cho phép tích hợp dễ dàng các thành phần đa dạng và cung cấp phương tiện để thiết lập các mức hiệu suất có thể dự đoán được. Những người tham gia định hình tương lai của ngành, thu thập thông tin tình báo trong ngành và cho phép chấp nhận nhanh chóng các sản phẩm tại các thị trường mới.', 'Hiệp hội Công nghiệp An ninh (SIA) là hiệp hội thương mại hàng đầu dành cho các nhà cung cấp giải pháp an ninh toàn cầu, với hơn 1.400 công ty thành viên sáng tạo đại diện cho hàng nghìn nhà lãnh đạo và chuyên gia an ninh định hình tương lai của ngành an ninh.', NULL, NULL, NULL, 'publisher/avatar/RL1V028HRF19103YDGUK.png', 0),
(4449, 'SJI - Steel Joist Institute', 'SJI - Steel Joist Institute', 'The Steel Joist Institute, a nonprofit organization of active joist manufacturers and other individuals and entities connected to the industry, was founded in 1928 to address the lack of uniform joist standards within the industry. In addition to setting standards and developing regulations for the steel joist industry, the Institute invests thousands of dollars in ongoing research and offers a complete library of training and research aids. The Institute also holds continuing education seminars, provides technical information and promotes the use of steel joists through a national communications program.', 'Viện Dầm Thép, một tổ chức phi lợi nhuận của các nhà sản xuất dầm thép đang hoạt động và các cá nhân và tổ chức khác có liên quan đến ngành, được thành lập vào năm 1928 để giải quyết tình trạng thiếu các tiêu chuẩn dầm thép thống nhất trong ngành. Ngoài việc thiết lập các tiêu chuẩn và phát triển các quy định cho ngành dầm thép, Viện còn đầu tư hàng nghìn đô la vào nghiên cứu đang diễn ra và cung cấp một thư viện đầy đủ các công cụ đào tạo và nghiên cứu. Viện cũng tổ chức các hội thảo giáo dục liên tục, cung cấp thông tin kỹ thuật và thúc đẩy việc sử dụng dầm thép thông qua một chương trình truyền thông quốc gia.', 'Viện Dầm Thép, một tổ chức phi lợi nhuận của các nhà sản xuất dầm thép đang hoạt động và các cá nhân và tổ chức khác có liên quan đến ngành, được thành lập vào năm 1928 để giải quyết tình trạng thiếu các tiêu chuẩn dầm thép thống nhất trong ngành.', NULL, NULL, NULL, 'publisher/avatar/SLDF32NDH0MRRGM6KNPL.jpg', 0),
(4450, 'SMACNA - Sheet Metal and Air Conditioning Contractors\' National Association', 'SMACNA - Sheet Metal and Air Conditioning Contractors\' National Association', 'SMACNA is the Sheet Metal and Air Conditioning Contractors National Association. As an ANSI-accredited standards developing organization, SMACNA standards and manuals address all facets of the sheet metal industry, from duct construction and installation to air pollution control, energy recovery and roofing. The voluntary technical standards and manuals developed by SMACNA contractors have found worldwide acceptance by the construction community, as well as foreign government agencies.', 'SMACNA là Hiệp hội quốc gia về nhà thầu tấm kim loại và điều hòa không khí. Là một tổ chức phát triển tiêu chuẩn được ANSI công nhận, các tiêu chuẩn và sổ tay hướng dẫn của SMACNA đề cập đến mọi khía cạnh của ngành công nghiệp tấm kim loại, từ xây dựng và lắp đặt ống dẫn đến kiểm soát ô nhiễm không khí, thu hồi năng lượng và lợp mái. Các tiêu chuẩn kỹ thuật tự nguyện và sổ tay hướng dẫn do các nhà thầu SMACNA phát triển đã được cộng đồng xây dựng cũng như các cơ quan chính phủ nước ngoài chấp nhận trên toàn thế giới.', 'SMACNA là Hiệp hội quốc gia về nhà thầu tấm kim loại và điều hòa không khí. Là một tổ chức phát triển tiêu chuẩn được ANSI công nhận, các tiêu chuẩn và sổ tay hướng dẫn của SMACNA đề cập đến mọi khía cạnh của ngành công nghiệp tấm kim loại, từ xây dựng và lắp đặt ống dẫn đến kiểm soát ô nhiễm không khí, thu hồi năng lượng và lợp mái.', NULL, NULL, NULL, 'publisher/avatar/ZCJ3U7DPLEWOSBGBJWH9.png', 0),
(4451, 'SME - Society of Manufacturing Engineers', 'SME - Society of Manufacturing Engineers', 'SME has been supporting the manufacturing industry for the last 85 years. Working closely with manufacturing professionals, companies, educators, schools and communities, we share knowledge and resources that generate solutions to manufacturing industry challenges.\nEstablished in 1932, SME (the Society of Manufacturing Engineers) is a nonprofit organization dedicated to the advancement of manufacturing. SME leads the industrial ecosystem by elevating manufacturers, academia and the communities in which they operate. Together we share one common belief: Manufacturing holds the key to economic growth and prosperity. SME helps unlock the full promise of manufacturing as an engine of commerce, progress and human potential. We believe in technology\'s power and humanity\'s innovation to advance our society and meet many of our biggest challenges. We design new ways to understand and solve problems, and our solutions advance the next wave of inspiration.', 'SME đã hỗ trợ ngành sản xuất trong 85 năm qua. Hợp tác chặt chẽ với các chuyên gia sản xuất, công ty, nhà giáo dục, trường học và cộng đồng, chúng tôi chia sẻ kiến ​​thức và nguồn lực tạo ra các giải pháp cho những thách thức của ngành sản xuất.\nĐược thành lập vào năm 1932, SME (Hiệp hội Kỹ sư Sản xuất) là một tổ chức phi lợi nhuận dành riêng cho sự phát triển của ngành sản xuất. SME dẫn đầu hệ sinh thái công nghiệp bằng cách nâng cao các nhà sản xuất, học viện và cộng đồng nơi họ hoạt động. Chúng tôi cùng nhau chia sẻ một niềm tin chung: Sản xuất nắm giữ chìa khóa cho tăng trưởng kinh tế và thịnh vượng. SME giúp mở khóa toàn bộ lời hứa của ngành sản xuất như một động lực của thương mại, tiến bộ và tiềm năng của con người. Chúng tôi tin vào sức mạnh của công nghệ và sự đổi mới của nhân loại để thúc đẩy xã hội của chúng ta và đáp ứng nhiều thách thức lớn nhất của chúng ta. Chúng tôi thiết kế những cách mới để hiểu và giải quyết vấn đề, và các giải pháp của chúng tôi thúc đẩy làn sóng cảm hứng tiếp theo.', 'SME đã hỗ trợ ngành sản xuất trong 85 năm qua. Hợp tác chặt chẽ với các chuyên gia sản xuất, công ty, nhà giáo dục, trường học và cộng đồng, chúng tôi chia sẻ kiến ​​thức và nguồn lực tạo ra các giải pháp cho những thách thức của ngành sản xuất.', NULL, NULL, NULL, 'publisher/avatar/8LVQQAJETDPBJWJ13ES8.jpg', 0),
(4452, 'SMPTE - Society of Motion Picture and Television Engineers', 'SMPTE - Society of Motion Picture and Television Engineers', 'The Society of Motion Picture and Television Engineers (SMPTE) was founded in 1916 to advance theory and development in the motion imaging field. Today, SMPTE serves its members with the latest technology information and education on a rapidly changing industry. SMPTE also is an accredited and globally-respected industry standards-setting body. As the leading technical society for the motion imaging industry, SMPTE is shaping the future of the constantly evolving content business.', 'Hiệp hội Kỹ sư Điện ảnh và Truyền hình (SMPTE) được thành lập vào năm 1916 để thúc đẩy lý thuyết và phát triển trong lĩnh vực hình ảnh chuyển động. Ngày nay, SMPTE cung cấp cho các thành viên thông tin công nghệ mới nhất và giáo dục về một ngành công nghiệp đang thay đổi nhanh chóng. SMPTE cũng là một tổ chức thiết lập tiêu chuẩn công nghiệp được công nhận và tôn trọng trên toàn cầu. Là hiệp hội kỹ thuật hàng đầu cho ngành công nghiệp hình ảnh chuyển động, SMPTE đang định hình tương lai của ngành kinh doanh nội dung không ngừng phát triển.', 'Hiệp hội Kỹ sư Điện ảnh và Truyền hình (SMPTE) được thành lập vào năm 1916 để thúc đẩy lý thuyết và phát triển trong lĩnh vực hình ảnh chuyển động. Ngày nay, SMPTE cung cấp cho các thành viên thông tin công nghệ mới nhất và giáo dục về một ngành công nghiệp đang thay đổi nhanh chóng.', NULL, NULL, NULL, 'publisher/avatar/G36RML8LW1VP8J0POHON.jpg', 0),
(4453, 'SN - Standards Norway EN', 'SN - Standards Norway EN', 'Standards Norway (SN) is a private member organization with approx. 70 employees. The core activity is to develop standards based on market needs. Standards Norway has the copyright on publishing Norwegian Standards.\n\nThe organization is a non-profit organization, in the sense that all income will be returned to standardization work.\n\nEach year, SN publishes about 1 200 new Norwegian Standards (NS), on the basis of national proposals and European and International Standards. The marketing and sales of Norwegian, international and foreign standards are carried out by a separate company, Standard Online AS, of which SN holds 80 % of the shares.\n\nAs a national member of ISO and the European Committee for Standardization (CEN), SN is responsible for Norwegian participation in European and global standardization work in all areas except telecommunication and the electrotechnical field. In Norway, over 2 000 voluntary experts from the business community, the public authorities, and employee and consumer organizations participate in this international standardization work. The voluntary input of resources is estimated to approximately CHF 27 mill.', 'Standards Norway (SN) là một tổ chức thành viên tư nhân với khoảng 70 nhân viên. Hoạt động cốt lõi là phát triển các tiêu chuẩn dựa trên nhu cầu thị trường. Standards Norway có bản quyền xuất bản các Tiêu chuẩn Na Uy.\n\nTổ chức này là một tổ chức phi lợi nhuận, theo nghĩa là tất cả thu nhập sẽ được trả lại cho công tác chuẩn hóa.\n\nHàng năm, SN xuất bản khoảng 1.200 Tiêu chuẩn Na Uy (NS) mới, dựa trên các đề xuất quốc gia và Tiêu chuẩn Châu Âu và Quốc tế. Hoạt động tiếp thị và bán các tiêu chuẩn Na Uy, quốc tế và nước ngoài được thực hiện bởi một công ty riêng, Standard Online AS, trong đó SN nắm giữ 80% cổ phần.\n\nLà thành viên quốc gia của ISO và Ủy ban Tiêu chuẩn hóa Châu Âu (CEN), SN chịu trách nhiệm cho sự tham gia của Na Uy vào công tác chuẩn hóa Châu Âu và toàn cầu trong mọi lĩnh vực ngoại trừ viễn thông và lĩnh vực kỹ thuật điện. Tại Na Uy, hơn 2.000 chuyên gia tình nguyện từ cộng đồng doanh nghiệp, các cơ quan công quyền và các tổ chức của người lao động và người tiêu dùng tham gia vào công tác chuẩn hóa quốc tế này. Nguồn lực đầu vào tự nguyện ước tính khoảng 27 triệu CHF.', 'Standards Norway (SN) là một tổ chức thành viên tư nhân với khoảng 70 nhân viên. Hoạt động cốt lõi là phát triển các tiêu chuẩn dựa trên nhu cầu thị trường. Standards Norway có bản quyền xuất bản các Tiêu chuẩn Na Uy.', NULL, NULL, NULL, 'publisher/avatar/N2RKANDDVJ43LI63N38V.jpg', 0),
(4454, 'SPC - Standards Press of China', 'SPC - Standards Press of China', 'SPC, the Standards Press of China, is the only publication center in China that publishes National Standards, Sector Standards, standard compilation books, scientific and technical books, and other books concerned with standardization, quality control and quality supervision. Chinese GB, Guojia Biaozhun, standards all have English titles with the text in Chinese (Mandarin).', 'SPC, Nhà xuất bản Tiêu chuẩn Trung Quốc, là trung tâm xuất bản duy nhất tại Trung Quốc xuất bản Tiêu chuẩn quốc gia, Tiêu chuẩn ngành, sách biên soạn tiêu chuẩn, sách khoa học kỹ thuật và các sách khác liên quan đến tiêu chuẩn hóa, kiểm soát chất lượng và giám sát chất lượng. GB, Guojia Biaozhun, tiêu chuẩn Trung Quốc đều có tiêu đề tiếng Anh với văn bản bằng tiếng Trung (Quan Thoại).', 'SPC, Nhà xuất bản Tiêu chuẩn Trung Quốc, là trung tâm xuất bản duy nhất tại Trung Quốc xuất bản Tiêu chuẩn quốc gia, Tiêu chuẩn ngành, sách biên soạn tiêu chuẩn, sách khoa học kỹ thuật và các sách khác liên quan đến tiêu chuẩn hóa, kiểm soát chất lượng và giám sát chất lượng. GB, Guojia Biaozhun, tiêu chuẩn Trung Quốc đều có tiêu đề tiếng Anh với văn bản bằng tiếng Trung (Quan Thoại).', NULL, NULL, NULL, NULL, 0),
(4455, 'SPI - Society of the Plastics Industry', 'SPI - Society of the Plastics Industry', 'Society of the Plastics Industry is a professional society representing individuals in the plastics industry. PLASTICS members represent the entire plastics industry supply chain in the U.S., including processors, machinery and equipment manufacturers, raw materials suppliers, recyclers and brand owners.\nThe Plastics Industry Association (PLASTICS) is a purpose-driven organization that supports the entire plastics supply chain.\n• We work to make our members and the industry more globally competitive.\n• We advance sustainability and strive to keep plastic out of our environment and in the circular economy.\n• We promote plastics manufacturing as a viable career option.\n• We provide education about plastics to both the industry and the public.\n• We support technology-driven innovation to solve problems.\n• We work to change public perceptions about plastics and show how they impact our lives for the better.\n• We understand what’s important to our members’ businesses and advocate on their behalf to enact sustainable policies and create sustainable business growth for the industry.\nOur councils, committees and events such as our signature global tradeshow NPE®, bring the boldest and brightest innovators, influencers and new technologies together to create connections, expand business growth and showcase our industry.  \nFrom the technological advancements we enable to the possibilities we create, we’re dedicated to helping our members shape the future and make a positive impact every day.  \nPLASTICS. WE PROTECT, PROMOTE, AND GROW THE PLASTICS INDUSTRY.', 'Hiệp hội ngành nhựa là một hiệp hội chuyên nghiệp đại diện cho các cá nhân trong ngành nhựa. Các thành viên của PLASTICS đại diện cho toàn bộ chuỗi cung ứng của ngành nhựa tại Hoa Kỳ, bao gồm các nhà chế biến, nhà sản xuất máy móc và thiết bị, nhà cung cấp nguyên liệu thô, đơn vị tái chế và chủ sở hữu thương hiệu.\nHiệp hội ngành nhựa (PLASTICS) là một tổ chức hoạt động có mục đích hỗ trợ toàn bộ chuỗi cung ứng nhựa.\n• Chúng tôi nỗ lực để giúp các thành viên và ngành công nghiệp của mình cạnh tranh hơn trên toàn cầu.\n• Chúng tôi thúc đẩy tính bền vững và nỗ lực để loại bỏ nhựa ra khỏi môi trường của chúng ta và trong nền kinh tế tuần hoàn.\n• Chúng tôi thúc đẩy sản xuất nhựa như một lựa chọn nghề nghiệp khả thi.\n• Chúng tôi cung cấp giáo dục về nhựa cho cả ngành công nghiệp và công chúng.\n• Chúng tôi hỗ trợ đổi mới công nghệ để giải quyết các vấn đề.\n• Chúng tôi nỗ lực để thay đổi nhận thức của công chúng về nhựa và cho thấy cách chúng tác động đến cuộc sống của chúng ta theo hướng tốt đẹp hơn.\n• Chúng tôi hiểu điều gì là quan trọng đối với doanh nghiệp của các thành viên và ủng hộ họ ban hành các chính sách bền vững và tạo ra sự tăng trưởng kinh doanh bền vững cho ngành.\n\nCác hội đồng, ủy ban và sự kiện của chúng tôi như triển lãm thương mại toàn cầu đặc trưng NPE® của chúng tôi, quy tụ những nhà đổi mới, người có sức ảnh hưởng và công nghệ mới táo bạo và sáng giá nhất để tạo ra các kết nối, mở rộng tăng trưởng kinh doanh và giới thiệu ngành của chúng tôi.\nTừ những tiến bộ công nghệ mà chúng tôi cho phép đến các khả năng mà chúng tôi tạo ra, chúng tôi tận tâm giúp các thành viên của mình định hình tương lai và tạo ra tác động tích cực mỗi ngày.\nNHỰA. CHÚNG TÔI BẢO VỆ, THÚC ĐẨY VÀ PHÁT TRIỂN NGÀNH NHỰA.', 'Hiệp hội ngành nhựa là một hiệp hội chuyên nghiệp đại diện cho các cá nhân trong ngành nhựa. Các thành viên của PLASTICS đại diện cho toàn bộ chuỗi cung ứng của ngành nhựa tại Hoa Kỳ, bao gồm các nhà chế biến, nhà sản xuất máy móc và thiết bị, nhà cung cấp nguyên liệu thô, đơn vị tái chế và chủ sở hữu thương hiệu.', NULL, NULL, NULL, 'publisher/avatar/77EPX9H9IEN3QUK83XPJ.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4456, 'SSPC - Society for Protective Coatings', 'SSPC - Society for Protective Coatings', 'The Society for Protective Coatings is the leading source of information on surface preparation, coating selection and application, environmental regulations, and health and safety issues that affect the protective coatings industry.\nSSPC: The Society for Protective Coatings (SSPC) is a professional association for the industrial protective and marine coatings industry. It was founded in 1950 as the Steel Structures Painting Council, a non-profit association concerned with the use of coatings to protect steel structures such as bridges, ships, water tanks, and locks and dams.\nSince the original mission of the organization evolved over the years to include structures built with materials other than steel (concrete, composite materials, etc.), the name was changed in 1997 to SSPC: The Society for Protective Coatings. The organization was originally affiliated with Carnegie Mellon University but is now independent.\nAs of the end of 2019, there are approximately 16,000 members worldwide. There are also approximately 960 corporate members. Industrial painting contractors are a primary beneficiary of SSPC\'s efforts.', 'Hiệp hội sơn phủ bảo vệ là nguồn thông tin hàng đầu về chuẩn bị bề mặt, lựa chọn và ứng dụng sơn phủ, các quy định về môi trường và các vấn đề về sức khỏe và an toàn ảnh hưởng đến ngành sơn phủ bảo vệ.\nSSPC: Hiệp hội sơn phủ bảo vệ (SSPC) là một hiệp hội chuyên nghiệp dành cho ngành sơn phủ bảo vệ công nghiệp và hàng hải. Hiệp hội được thành lập vào năm 1950 với tên gọi là Hội đồng sơn kết cấu thép, một hiệp hội phi lợi nhuận quan tâm đến việc sử dụng sơn phủ để bảo vệ các kết cấu thép như cầu, tàu, bể chứa nước, âu thuyền và đập.\nVì sứ mệnh ban đầu của tổ chức đã phát triển qua nhiều năm để bao gồm các kết cấu được xây dựng bằng vật liệu khác ngoài thép (bê tông, vật liệu composite, v.v.), nên tên đã được đổi thành SSPC: Hiệp hội sơn phủ bảo vệ vào năm 1997. Tổ chức này ban đầu được liên kết với Đại học Carnegie Mellon nhưng hiện đã độc lập.\nTính đến cuối năm 2019, có khoảng 16.000 thành viên trên toàn thế giới. Ngoài ra còn có khoảng 960 thành viên doanh nghiệp. Các nhà thầu sơn công nghiệp là bên hưởng lợi chính từ những nỗ lực của SSPC.', 'Hiệp hội sơn phủ bảo vệ là nguồn thông tin hàng đầu về chuẩn bị bề mặt, lựa chọn và ứng dụng sơn phủ, các quy định về môi trường và các vấn đề về sức khỏe và an toàn ảnh hưởng đến ngành sơn phủ bảo vệ.', NULL, NULL, NULL, 'publisher/avatar/IBJSFS8NTVPJEISG8YUT.jpg', 0),
(4457, 'STI/SPFA - Steel Tank Institute/Steel Plate Fabricators', 'STI/SPFA - Steel Tank Institute/Steel Plate Fabricators', 'AssoAssociationSTI/SPFA provides a wide range of services to industry-leading suppliers and fabricators of steel tanks, pressure vessels, specialty products and piping for the petroleum, chemical, food and water storage industries.\nSTI/SPFA promotes and unites the steel plate fabricated products industry through standards development, education, and communication.\nSTI/SPFA is the leading representative of the steel fabrication industry for tank technologies, storied history, education, advocacy, and industry networking.', 'Hiệp hội STI/SPFA cung cấp nhiều dịch vụ cho các nhà cung cấp và nhà chế tạo hàng đầu trong ngành về bồn thép, bình chịu áp suất, sản phẩm đặc biệt và đường ống cho các ngành công nghiệp dầu khí, hóa chất, thực phẩm và lưu trữ nước.\nSTI/SPFA thúc đẩy và thống nhất ngành sản phẩm chế tạo bằng tấm thép thông qua phát triển tiêu chuẩn, giáo dục và truyền thông.\nSTI/SPFA là đại diện hàng đầu của ngành chế tạo thép về công nghệ bồn, lịch sử lâu đời, giáo dục, vận động và mạng lưới ngành.', 'Hiệp hội STI/SPFA cung cấp nhiều dịch vụ cho các nhà cung cấp và nhà chế tạo hàng đầu trong ngành về bồn thép, bình chịu áp suất, sản phẩm đặc biệt và đường ống cho các ngành công nghiệp dầu khí, hóa chất, thực phẩm và lưu trữ nước.\nSTI/SPFA thúc đẩy và thống nhất ngành sản phẩm chế tạo bằng tấm thép thông qua phát triển tiêu chuẩn, giáo dục và truyền thông.\nSTI/SPFA là đại diện hàng đầu của ngành chế tạo thép về công nghệ bồn, lịch sử lâu đời, giáo dục, vận động và mạng lưới ngành.', NULL, NULL, NULL, 'publisher/avatar/2OK6EP63GVGB9F3B7AZY.jpg', 0),
(4458, 'TAPPI - Technical Association of the Pulp and Paper Industry', 'TAPPI - Technical Association of the Pulp and Paper Industry', 'TAPPI is the leading technical association for the worldwide pulp, paper, packaging, and converting industries. TAPPI Test Methods and Technical Information Papers (TIPs) provide the most comprehensive collection of reliable technical information in the paper processing industry.', 'Hiệp hội Kỹ thuật Ngành Công nghiệp Giấy và Bột giấy Hoa Kỳ (Technical Association of the Pulp and Paper Industry - TAPPI) là một tổ chức chuyên nghiên cứu và phát triển trong lĩnh vực công nghiệp giấy và bột giấy tại Hoa Kỳ. TAPPI được thành lập vào năm 1915 và có trụ sở chính tại Atlanta, Georgia.\n\nTAPPI là một tổ chức không vụ lợi và hội viên của nó bao gồm các công ty, cá nhân và tổ chức liên quan đến ngành công nghiệp giấy và bột giấy. Mục tiêu chính của TAPPI là thúc đẩy sự phát triển công nghiệp, chia sẻ kiến thức và thúc đẩy tiến bộ trong lĩnh vực này.\n\nTAPPI cung cấp một loạt các dịch vụ và hoạt động cho cộng đồng ngành giấy và bột giấy, bao gồm:\n\nHội thảo và hội nghị: TAPPI tổ chức các sự kiện chuyên ngành, hội thảo, hội nghị và triển lãm để giao lưu, chia sẻ thông tin và giới thiệu các công nghệ mới trong ngành.\n\nTạp chí và xuất bản: TAPPI xuất bản các tạp chí và bản tin chuyên ngành như \"TAPPI Journal\" và \"Paper360°\", cung cấp thông tin về nghiên cứu, phát triển và xu hướng trong ngành.\n\nĐào tạo và giáo dục: TAPPI cung cấp các khóa đào tạo, chứng chỉ và chương trình giáo dục để nâng cao kiến thức và kỹ năng của các chuyên gia và nhân viên trong ngành giấy và bột giấy.\n\nĐịnh mức và tiêu chuẩn: TAPPI đóng góp vào việc phát triển các tiêu chuẩn và phương pháp định mức trong ngành công nghiệp giấy và bột giấy.\n\nTAPPI là một tổ chức quan trọng trong ngành công nghiệp giấy và bột giấy tại Hoa Kỳ và có vai trò quan trọng trong việc thúc đẩy sự phát triển và tiến bộ của ngành này.', 'Hiệp hội Kỹ thuật Ngành Công nghiệp Giấy và Bột giấy Hoa Kỳ (Technical Association of the Pulp and Paper Industry - TAPPI) là một tổ chức chuyên nghiên cứu và phát triển trong lĩnh vực công nghiệp giấy và bột giấy tại Hoa Kỳ.', 'TAPPI,JAPANTAPPI,ANSI/TAPPI', 'Hiệp hội Kỹ thuật Ngành Công nghiệp Giấy và Bột giấy Hoa Kỳ, Technical Association of the Pulp and Paper Industry, TAPPI, Tiêu chuẩn giấy, Tiêu chuẩn bột giấy, Tiêu chuẩn hiệp hội, TAPPI standard, Tiêu chuẩn TAPPI', NULL, 'publisher/avatar/QIJ09NEWWKPHA7CJ7JXN.png', 0),
(4459, 'TEMA - Tubular Exchanger Manufacturers Association', 'TEMA - Tubular Exchanger Manufacturers Association', 'The Tubular Exchanger Manufacturers Association, Inc. (TEMA) is trade association of leading manufacturers of shell and tube heat exchangers, who have pioneered the research and development of heat exchangers for over sixty years.\nThe Tubular Exchanger Manufacturers Association (also known as TEMA) is an association of fabricators of shell and tube type heat exchangers. TEMA has established and maintains a set of construction standards for heat exchangers, known as the TEMA Standard. TEMA also produces software for evaluation of flow-induced vibration and of flexible shell elements (expansion joints). TEMA was founded in 1939, and is based in Tarrytown, New York. The association meets regularly to revise and update the standards, respond to inquiries, and discuss topics related to the industry.\nThe current edition of the TEMA Standard is the Tenth Edition, published in 2019. Worldwide, the TEMA Standard is used as the construction standard for most shell and tube heat exchangers. The standard is composed of ten sections: \n1. Nomenclature (see below)\n2. Fabrication Tolerances\n3. General Fabrication and Performance Information\n4. Installation, Operation, and Maintenance\n5. Mechanical Standards\n6. Flow Induced Vibration\n7. Thermal Relations\n8. Physical Properties of Fluids\n9. General Information\n10. Recommended Good Practice', 'Hiệp hội các nhà sản xuất bộ trao đổi nhiệt dạng ống (TEMA) là hiệp hội thương mại của các nhà sản xuất hàng đầu về bộ trao đổi nhiệt dạng vỏ và ống, những người tiên phong trong nghiên cứu và phát triển bộ trao đổi nhiệt trong hơn sáu mươi năm.\nHiệp hội các nhà sản xuất bộ trao đổi nhiệt dạng ống (còn được gọi là TEMA) là hiệp hội của các nhà chế tạo bộ trao đổi nhiệt dạng vỏ và ống. TEMA đã thiết lập và duy trì một bộ tiêu chuẩn xây dựng cho bộ trao đổi nhiệt, được gọi là Tiêu chuẩn TEMA. TEMA cũng sản xuất phần mềm để đánh giá độ rung do dòng chảy và các thành phần vỏ linh hoạt (khớp nối giãn nở). TEMA được thành lập vào năm 1939 và có trụ sở tại Tarrytown, New York. Hiệp hội họp thường xuyên để sửa đổi và cập nhật các tiêu chuẩn, trả lời các câu hỏi và thảo luận các chủ đề liên quan đến ngành.\nPhiên bản hiện tại của Tiêu chuẩn TEMA là Phiên bản thứ mười, được xuất bản vào năm 2019. Trên toàn thế giới, Tiêu chuẩn TEMA được sử dụng làm tiêu chuẩn xây dựng cho hầu hết các bộ trao đổi nhiệt dạng vỏ và ống. Tiêu chuẩn bao gồm mười phần:\n1. Danh pháp (xem bên dưới)\n2. Dung sai chế tạo\n3. Thông tin chung về chế tạo và hiệu suất\n4. Lắp đặt, vận hành và bảo trì\n5. Tiêu chuẩn cơ học\n6. Rung động do dòng chảy\n7. Quan hệ nhiệt\n8. Tính chất vật lý của chất lỏng\n9. Thông tin chung\n10. Thực hành tốt được khuyến nghị', 'Hiệp hội các nhà sản xuất bộ trao đổi nhiệt dạng ống (TEMA) là hiệp hội thương mại của các nhà sản xuất hàng đầu về bộ trao đổi nhiệt dạng vỏ và ống, những người tiên phong trong nghiên cứu và phát triển bộ trao đổi nhiệt trong hơn sáu mươi năm.', NULL, NULL, NULL, 'publisher/avatar/7VPZVN48NWYL35WQMJ7W.png', 0),
(4460, 'TIA - Telecommunications Industry Association', 'TIA - Telecommunications Industry Association', 'The Telecommunications Industry Association (TIA) - the trusted association for the connected world, represents more than 400 organizations that enable high-speed communication networks and accelerate next-generation technology innovation. As a member-driven organization, TIA advocates for our industry in the U.S. and internationally, develops critical standards, manages technology programs, and improves business performance, all to advance trusted global connectivity. TIA is accredited by the American National Standards Institute (ANSI).', 'Hiệp hội Ngành Viễn thông Hoa Kỳ (Telecommunications Industry Association - TIA) là một tổ chức thương mại đại diện cho ngành công nghiệp viễn thông tại Hoa Kỳ. TIA được thành lập vào năm 1988 và có trụ sở tại Arlington, Virginia.\n\nTIA đại diện cho các doanh nghiệp và tổ chức trong lĩnh vực viễn thông, bao gồm các nhà sản xuất, nhà cung cấp dịch vụ, nhà điều hành mạng, nhà phân phối và các tổ chức nghiên cứu. Mục tiêu chính của TIA là thúc đẩy sự phát triển, tiêu chuẩn hóa và tương thích trong ngành công nghiệp viễn thông.\n\nTIA tham gia vào việc đặt ra tiêu chuẩn kỹ thuật, định dạng và giao thức cho các công nghệ viễn thông, bao gồm mạng di động, mạng cáp quang, mạng không dây, mạng lưu trữ và các công nghệ liên quan khác. TIA cũng đóng vai trò quan trọng trong việc đưa ra các quy định và chính sách liên quan đến viễn thông và ảnh hưởng đến ngành công nghiệp.\n\nCác hoạt động của TIA bao gồm:\n\nTiêu chuẩn hóa: TIA đóng vai trò quan trọng trong việc phát triển và duy trì các tiêu chuẩn kỹ thuật cho các công nghệ viễn thông, đảm bảo tính tương thích và sự tương đồng giữa các thiết bị và hệ thống khác nhau.\n\nNghiên cứu và phát triển: TIA thúc đẩy sự nghiên cứu và phát triển công nghệ mới trong ngành viễn thông, đồng thời tạo ra các hướng dẫn và tài liệu về ứng dụng và triển khai.\n\nChính sách và quy định: TIA tham gia vào quá trình đề xuất và đánh giá các chính sách và quy định liên quan đến ngành công nghiệp viễn thông, đại diện cho lợi ích của các thành viên và ngành công nghiệp.\n\nGiáo dục và đào tạo: TIA cung cấp các chương trình giáo dục và đào tạo để nâng cao kiến thức và kỹ năng của các chuyên gia và nhân viên trong ngành viễn thông.\n\nTIA là một tổ chức quan trọng trong ngành công nghiệp viễn thông tại Hoa Kỳ, đóng vai trò quan trọng trong việc thúc đẩy tiến bộ công nghệ và tiêu chuẩn hóa, đồng thời đại diện cho lợi ích của các doanh nghiệp và tổ chức trong ngành.', 'Hiệp hội Ngành Viễn thông Hoa Kỳ (Telecommunications Industry Association - TIA) là một tổ chức thương mại đại diện cho ngành công nghiệp viễn thông tại Hoa Kỳ. TIA được thành lập vào năm 1988 và có trụ sở tại Arlington, Virginia.', 'TIA,ANSI/EIA/TIA,EIA/TIA,TIA/EIA,ANSI/TIA,ANSI/BSR/TIA,ANSI/BSR/TIA/EIA,TIA/EIA/IS', 'Hiệp hội Ngành Viễn thông Hoa Kỳ, Telecommunications Industry Association, TIA, Tiêu chuẩn viễn thông, Viễn thông, Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ, TIA standards', '33.020*33.040*33.100*33.180', 'publisher/avatar/NRGIT25MGS8QV6HAVTKP.png', 0),
(4461, 'TMS - The Masonry Society', 'TMS - The Masonry Society', 'The Masonry Society is an international gathering of people interested in the art and science of masonry. We are a professional, technical, and educational association dedicated to the advancement of knowledge on masonry. TMS members are design engineers, architects, builders, researchers, educators, building officials, material suppliers, manufacturers, and others who want to contribute to and benefit from the global pool of knowledge on masonry.', 'Hiệp hội Masonry là một tập hợp quốc tế của những người quan tâm đến nghệ thuật và khoa học về nghề nề. Chúng tôi là một hiệp hội chuyên nghiệp, kỹ thuật và giáo dục dành riêng cho việc nâng cao kiến ​​thức về nghề nề. Các thành viên của TMS là các kỹ sư thiết kế, kiến ​​trúc sư, thợ xây, nhà nghiên cứu, nhà giáo dục, viên chức xây dựng, nhà cung cấp vật liệu, nhà sản xuất và những người khác muốn đóng góp và hưởng lợi từ nguồn kiến ​​thức toàn cầu về nghề nề.', 'Hiệp hội Masonry là một tập hợp quốc tế của những người quan tâm đến nghệ thuật và khoa học về nghề nề. Chúng tôi là một hiệp hội chuyên nghiệp, kỹ thuật và giáo dục dành riêng cho việc nâng cao kiến ​​thức về nghề nề. Các thành viên của TMS là các kỹ sư thiết kế, kiến ​​trúc sư, thợ xây, nhà nghiên cứu, nhà giáo dục, viên chức xây dựng, nhà cung cấp vật liệu, nhà sản xuất và những người khác muốn đóng góp và hưởng lợi từ nguồn kiến ​​thức toàn cầu về nghề nề.', NULL, NULL, NULL, 'publisher/avatar/B1LIFMILB1I22U1DZO8U.jpg', 0),
(4462, 'UL - Underwriters Laboratories', 'UL - Underwriters Laboratories', 'UL Standards & Engagement translates scientific discoveries into standards and policies that have the power to make a systemic impact on public safety throughout the world. Distinguished by our independent research and informed foresight, we\'ve been driving cutting-edge science into practical standards since 1903. Our extensive library of standards helps to make everyday things safer, more secure, and more sustainable, from life jackets to batteries to autonomous cars. It’s a mission we pursue across the globe. We partner with leading minds and national standards bodies around the world to draw upon an ever-growing body of scientific knowledge from UL Research Institutes and global experts. Together, we\'re creating a dynamic road map to a safer future.', 'Underwriters Laboratories - Hoa Kỳ (UL) là một tổchức chứng nhận antoàn sản phẩm độc lập tiến hành thử nghiệm sản phẩm và xây dựng tiêu chuẩn về an toàn hơn một thế kỷ qua. Hàng năm, UL đánh giá hơn 19.000 loại sản phẩm, phụ kiện, nguyên liệu và hệ thống với 21 tỷ dấu UL xuất hiện trên sản phẩm của 72.000 nhà sản xuất mỗi năm. Mạng lưới các công ty, nhà cung cấp dịch vụ toàn cầu của UL bao gồm 62 phòng thử nghiệm, các cơ sở chứng nhận và thử nghiệm cung cấp dịch vụ cho khách hàng tại 99 quốc gia.\n\nUL là kiến trúc sư của các hệ thống an toàn của Hoa Kỳ và Canada, đã xây dựng hơn 1.200 tiêu chuẩn an toàn và tích cực tham gia vào hoạt động xây dựng tiêu chuẩn quốc gia, quốc tế. UL là tổ chức Chứng nhận Quốc gia (NCB) trong Chương trình tổ chức công nhận (CB scheme) của Hệ thống Uỷ ban kỹ thuật điện quốc tế (IEC) về thử nghiệm phù hợp với các tiêu chuẩn về an toàn thiết bị điện (IECEE). Điều này có ý nghĩa là UL có thể trợ giúp để đạt được chứng nhận quốc gia tại hơn 30 nước trên toàn thế giới. Theo CB scheme của IECEE, UL có thể đánh giá phòng thử nghiệm công nghệ nghệ thông tin và thiết bị kinh doanh theo tiêu chuẩn IEC 950, thiết bị y tế theo tiêu chuẩn IEC 601, thiết bị đo lường và thử nghiệm theo tiêu chuẩn IEC 1010 và cấp Chứng chỉ Thử nghiệm CB và Báo cáo Thử nghiệm CB mà có thể sử dụng để đạt được chứng nhận quốc gia tại các quốc gia tham gia.', 'Underwriters Laboratories - Hoa Kỳ (UL) là một tổchức chứng nhận antoàn sản phẩm độc lập tiến hành thử nghiệm sản phẩm và xây dựng tiêu chuẩn về an toàn hơn một thế kỷ qua. Hàng năm, UL đánh giá hơn 19.000 loại sản phẩm, phụ kiện, nguyên liệu và hệ thống với 21 tỷ dấu UL xuất hiện trên sản phẩm của 72.000 nhà sản xuất mỗi năm', 'UL,ANSI/UL', 'UL, Tổ chức Hợp tác giữa các Phòng thí nghiệm (UL), Underwriters Laboratories (UL), Phòng thí nghiệm, Tiêu chuẩn Hoa Kỳ, Tiêu chuẩn hiệp hội Hoa Kỳ', '13*31*33*35*83*91*91.100', 'publisher/avatar/Y4LBDSH8PIP3BQEMILCL.jpg', 0),
(4463, 'ULC - Underwriters Laboratories of Canada', 'ULC - Underwriters Laboratories of Canada', 'ULC Standards has been publishing standards for Canadians for over 60 years. As one of the Standards Council of Canada (SCC) accredited Standards Development Organizations (SDO), we operate under the consensus-based principles as required by the SCC under the Requirements & Guidance – Accreditation of Standards Development Organizations. ULC Standards is also a signatory to the World Trade Organization (WTO) Technical Barrier to Trade Agreement, which outlines in Annex 3 the Code of Good Practice for the Preparation, Adoption and Application of Standards.', 'ULC Standards đã xuất bản các tiêu chuẩn cho người dân Canada trong hơn 60 năm. Là một trong những Tổ chức Phát triển Tiêu chuẩn (SDO) được Hội đồng Tiêu chuẩn Canada (SCC) công nhận, chúng tôi hoạt động theo các nguyên tắc dựa trên sự đồng thuận theo yêu cầu của SCC theo Yêu cầu & Hướng dẫn – Công nhận các Tổ chức Phát triển Tiêu chuẩn. ULC Standards cũng là bên ký kết Hiệp định Rào cản Kỹ thuật đối với Thương mại của Tổ chức Thương mại Thế giới (WTO), trong đó nêu rõ trong Phụ lục 3 Bộ Quy tắc Thực hành Tốt cho việc Chuẩn bị, Áp dụng và Áp dụng Tiêu chuẩn.', 'ULC Standards đã xuất bản các tiêu chuẩn cho người dân Canada trong hơn 60 năm. Là một trong những Tổ chức Phát triển Tiêu chuẩn (SDO) được Hội đồng Tiêu chuẩn Canada (SCC) công nhận, chúng tôi hoạt động theo các nguyên tắc dựa trên sự đồng thuận theo yêu cầu của SCC theo Yêu cầu & Hướng dẫn – Công nhận các Tổ chức Phát triển Tiêu chuẩn. ULC Standards cũng là bên ký kết Hiệp định Rào cản Kỹ thuật đối với Thương mại của Tổ chức Thương mại Thế giới (WTO), trong đó nêu rõ trong Phụ lục 3 Bộ Quy tắc Thực hành Tốt cho việc Chuẩn bị, Áp dụng và Áp dụng Tiêu chuẩn.', NULL, NULL, '13*31*33*35*83*91*91.100', 'publisher/avatar/ZAHP5I50D2C5JUDX6VZV.jpg', 0),
(4464, 'UOP - UOP LLC', 'UOP - UOP LLC', 'A Honeywell CompanyOver 300 analytical methods and procedures support the installation, implementation, maintenance and safe operation of UOP-licensed processes. These test methods are a valuable resource to help users analyze feedstocks and various process streams. Considered an industry standard in its own right, they supplement ASTM, API, and other important industry standards and publications.', 'Một công ty HoneywellHơn 300 phương pháp và quy trình phân tích hỗ trợ việc lắp đặt, triển khai, bảo trì và vận hành an toàn các quy trình được cấp phép của UOP. Các phương pháp thử nghiệm này là nguồn tài nguyên có giá trị giúp người dùng phân tích nguyên liệu đầu vào và nhiều luồng quy trình khác nhau. Được coi là một tiêu chuẩn công nghiệp theo đúng nghĩa của nó, chúng bổ sung cho ASTM, API và các tiêu chuẩn và ấn phẩm quan trọng khác của ngành.', 'Một công ty HoneywellHơn 300 phương pháp và quy trình phân tích hỗ trợ việc lắp đặt, triển khai, bảo trì và vận hành an toàn các quy trình được cấp phép của UOP. Các phương pháp thử nghiệm này là nguồn tài nguyên có giá trị giúp người dùng phân tích nguyên liệu đầu vào và nhiều luồng quy trình khác nhau. Được coi là một tiêu chuẩn công nghiệp theo đúng nghĩa của nó, chúng bổ sung cho ASTM, API và các tiêu chuẩn và ấn phẩm quan trọng khác của ngành.', NULL, NULL, NULL, 'publisher/avatar/61XUK7AQXOGXMDIOGP6O.png', 0),
(4465, 'WRC - Welding Research Council, Inc.', 'WRC - Welding Research Council, Inc.', 'The Welding Research Council, a 501(c)(3) not-for-profit scientific research corporation, brings to bear in the solution of problems in welding and pressure vessel technology the talents of diverse science and engineering specialists. They exchange knowledge, share perspectives, and develop and guide R & D activities. As needed, the Council organizes and manages cooperative programs to advance codes and standards. Also incorporates the Pressure Vessel Research Council (PVRC) and Materials Properties Council (MPC)', 'Hội đồng nghiên cứu hàn, một tập đoàn nghiên cứu khoa học phi lợi nhuận 501(c)(3), mang đến giải pháp cho các vấn đề trong công nghệ hàn và bình chịu áp lực bằng tài năng của các chuyên gia khoa học và kỹ thuật đa dạng. Họ trao đổi kiến thức, chia sẻ quan điểm, phát triển và hướng dẫn các hoạt động R&D. Khi cần thiết, Hội đồng tổ chức và quản lý các chương trình hợp tác nhằm nâng cao các quy tắc và tiêu chuẩn. Cũng kết hợp với Hội đồng nghiên cứu bình chịu áp lực (PVRC) và Hội đồng tính chất vật liệu (MPC)', 'The Welding Research Council, a 501(c)(3) not-for-profit scientific research corporation, brings to bear in the solution of problems in welding and pressure vessel technology the talents of diverse science and engineering specialists.', 'WRC', 'Ủy ban Nghiên cứu Hàn (WRC), Welding Research Council (WRC), Hàn', NULL, 'publisher/avatar/VF06B8G9F41H3MDSHQCU.jpg', 0),
(4466, 'X9 - Accredited Standards Committee', 'X9 - Accredited Standards Committee', 'X9 IncorporatedIn 1974, the American National Standards Institute (ANSI) approved the scope of activity for the X9 Standards Committee on Banking, as \"Standardization for Facilitating Banking Operations.\" Today, the Accredited Standards Committee X9 (ASC X9, Inc.) operates 5 technical subcommittees and 20-30 technical working groups that develop financial industry standards and guidelines. ASC X9 standards are widely used and cited or required by the Federal government for use in financial procedures and transactions. In addition, X9 standards are the basis for many international standards used in facilitating global commerce.', 'X9 IncorporatedNăm 1974, Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) đã phê duyệt phạm vi hoạt động của Ủy ban Tiêu chuẩn X9 về Ngân hàng, với tên gọi \"Tiêu chuẩn hóa để tạo điều kiện thuận lợi cho Hoạt động Ngân hàng\". Ngày nay, Ủy ban Tiêu chuẩn được công nhận X9 (ASC X9, Inc.) điều hành 5 tiểu ban kỹ thuật và 20-30 nhóm làm việc kỹ thuật phát triển các tiêu chuẩn và hướng dẫn của ngành tài chính. Các tiêu chuẩn ASC X9 được sử dụng rộng rãi và được trích dẫn hoặc yêu cầu bởi Chính phủ Liên bang để sử dụng trong các thủ tục và giao dịch tài chính. Ngoài ra, các tiêu chuẩn X9 là cơ sở cho nhiều tiêu chuẩn quốc tế được sử dụng để tạo điều kiện thuận lợi cho thương mại toàn cầu.', 'X9 IncorporatedNăm 1974, Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) đã phê duyệt phạm vi hoạt động của Ủy ban Tiêu chuẩn X9 về Ngân hàng, với tên gọi \"Tiêu chuẩn hóa để tạo điều kiện thuận lợi cho Hoạt động Ngân hàng\". Ngày nay, Ủy ban Tiêu chuẩn được công nhận X9 (ASC X9, Inc.) điều hành 5 tiểu ban kỹ thuật và 20-30 nhóm làm việc kỹ thuật phát triển các tiêu chuẩn và hướng dẫn của ngành tài chính. Các tiêu chuẩn ASC X9 được sử dụng rộng rãi và được trích dẫn hoặc yêu cầu bởi Chính phủ Liên bang để sử dụng trong các thủ tục và giao dịch tài chính. Ngoài ra, các tiêu chuẩn X9 là cơ sở cho nhiều tiêu chuẩn quốc tế được sử dụng để tạo điều kiện thuận lợi cho thương mại toàn cầu.', NULL, NULL, NULL, 'publisher/avatar/KOMGMXINWWC5A9H0ZGZT.png', 0),
(4467, 'AFNOR', 'AFNOR - French Standards (AFNOR)', 'Established in 1926, AFNOR is an association governed by the law of 1901, consisting of nearly 2500 member companies. Its aim is to lead and coordinate the standards development process and to promote the application of those standards.\n\nRecognized by the public authorities (who entrusted the Ministry in charge of industry with the task of ensuring interministerial coordination and control functions), AFNOR is at the hub of the French standardization system. Bringing together all the major socio-economic players, AFNOR is alert to their needs and cooperates closely with the 25 standards bureaus and the other professional bodies in developing a set of standards that meet their strategic objectives.\n\nAs a service provider, AFNOR has developed a variety of deliverables - for companies in particular - which, ranging from the distribution of standards to certification, including training, helps in a practical way to integrate standards into the company\'s development.\n\nAFNOR has concentrated its commercial and competitive activities within specialised subsidiaries by creating AFNOR Certification and AFNOR Compétences in the training area. The figures herewith refer to the group as a whole, which maintains strong synergy between its different activities.\n\nAFNOR is represented throughout France and abroad.\nIts Web site www.afnor.org provides online access to all information about AFNOR.', 'NF là viết tắt của \"Norme Française\" trong tiếng Pháp, có nghĩa là \"Tiêu chuẩn Pháp\" trong tiếng Anh. NF là hệ thống tiêu chuẩn quốc gia của Pháp, tương đương với các tiêu chuẩn quốc gia được áp dụng trong các quốc gia khác.\n\nTiêu chuẩn NF bao gồm một loạt các tiêu chuẩn kỹ thuật, quy định và hướng dẫn liên quan đến nhiều lĩnh vực khác nhau, bao gồm công nghiệp, xây dựng, kỹ thuật, y tế, môi trường và nhiều lĩnh vực khác. Các tiêu chuẩn này được đưa ra để đảm bảo chất lượng, an toàn và tuân thủ các quy định kỹ thuật trong các hoạt động và sản phẩm tại Pháp.\n\nTiêu chuẩn NF được quản lý và phát triển bởi AFNOR (Association Française de Normalisation), tổ chức tiêu chuẩn quốc gia của Pháp. AFNOR có trách nhiệm xây dựng, duy trì và cải tiến tiêu chuẩn NF, đồng thời cung cấp dịch vụ đánh giá tuân thủ tiêu chuẩn và chứng nhận cho các sản phẩm và hệ thống.\n\nTiêu chuẩn NF thường được sử dụng rộng rãi trong ngành công nghiệp, xây dựng và dịch vụ tại Pháp. Nó đóng vai trò quan trọng trong việc đảm bảo tính đồng nhất, tương thích và an toàn cho', 'Hiệp hội Chuẩn hóa Pháp (AFNOR, en: Hiệp hội Chuẩn hóa Pháp là tổ chức quốc gia của Pháp về chuẩn hóa và là cơ quan thành viên của Tổ chức Chuẩn hóa Quốc tế. Nhóm AFNOR phát triển các hoạt động chuẩn hóa quốc tế, cung cấp thông tin, chứng nhận và đào tạo thông qua mạng lưới các đối tác chính tại Pháp là thành viên của hiệp hội', 'NF', 'French Standards, AFNOR standards, AFNOR', NULL, 'publisher/avatar/AYH1GCUQSUK9W7ZVB3UF.jpg', 0),
(4468, 'CSN', 'CSN - Czech technical standard', 'The work of technical standardization in the country was started by the Czechoslovak Electrotechnical Association, established in 1919, and by the Czechoslovak Association of Standardization, established in 1922. In 1951, the activities of the two organizations were combined, and the Office for Standardization and Measurements was set up. The Federal Office for Standards, Metrology and Testing was established in 1968.\n\nSince January 1993, after the splitting of Czechoslovakia into two independent states, the Czech Office for Standards, Metrology and Testing has undertaken coordination functions in standardization, metrology and testing in the Czech Republic. The Czech Standards Institute was established that same year.\n\nSince 1997, the Czech Standards Institute, on the basis of an authorization from the Ministry of Industry and Trade provided under Act 22/1997 Coll. on technical requirements for products and on amendments of some acts,has become the National Standards Body for all fields of standardization. As of 31 December 2008, the Institute was dissolved by decision of the Ministry.\n\nSince 1 January 2009, the development and publication of standards in the Czech Republic have been ensured by the Czech Office for Standards, Metrology and Testing (UNMZ), on the basis of Act 22/1997 Coll.\n\nNote: Statistical data relate to the Czech Standards Institute that was dissolved as of 2008-12-31. The legal status is relevant to UNMZ.', 'Công tác chuẩn hóa kỹ thuật trong nước được khởi xướng bởi Hiệp hội Kỹ thuật Điện Tiệp Khắc, thành lập năm 1919, và Hiệp hội Chuẩn hóa Tiệp Khắc, thành lập năm 1922. Năm 1951, hoạt động của hai tổ chức này được hợp nhất và Văn phòng Chuẩn hóa và Đo lường được thành lập. Văn phòng Liên bang về Tiêu chuẩn, Đo lường và Kiểm tra được thành lập năm 1968.\n\nKể từ tháng 1 năm 1993, sau khi Tiệp Khắc chia tách thành hai quốc gia độc lập, Văn phòng Tiêu chuẩn, Đo lường và Kiểm tra của Séc đã đảm nhiệm các chức năng điều phối về chuẩn hóa, đo lường và kiểm tra tại Cộng hòa Séc. Viện Tiêu chuẩn Séc được thành lập cùng năm đó.\n\nKể từ năm 1997, Viện Tiêu chuẩn Séc, trên cơ sở ủy quyền của Bộ Công thương theo Đạo luật 22/1997 Coll. về các yêu cầu kỹ thuật đối với sản phẩm và về các sửa đổi của một số đạo luật, đã trở thành Cơ quan Tiêu chuẩn Quốc gia cho tất cả các lĩnh vực chuẩn hóa. Tính đến ngày 31 tháng 12 năm 2008, Viện đã bị giải thể theo quyết định của Bộ.\n\nKể từ ngày 1 tháng 1 năm 2009, việc phát triển và công bố các tiêu chuẩn tại Cộng hòa Séc đã được Văn phòng Tiêu chuẩn, Đo lường và Kiểm tra Séc (UNMZ) đảm bảo, trên cơ sở Đạo luật 22/1997 Coll.\n\nLưu ý: Dữ liệu thống kê liên quan đến Viện Tiêu chuẩn Séc đã bị giải thể tính đến ngày 31 tháng 12 năm 2008. Tình trạng pháp lý có liên quan đến UNMZ.', 'Tiêu chuẩn kỹ thuật Séc (ČSN) cho các tiêu chuẩn kỹ thuật, công nghiệp và thương mại, là một chỉ định được bảo hộ của các tiêu chuẩn kỹ thuật Séc. Việc tạo ra và ban hành ČSN hiện do Cơ quan Tiêu chuẩn hóa Séc cung cấp', 'CSN', 'Czech technical standard, ČSN,  Czech technical standards, Czech Standardization Agency, zechoslovak standards, Czechoslovak technical standards, STN, Slovak Technical Standard', NULL, 'publisher/avatar/FQJ28WYGBY1WHCAYPIU0.jpg', 0),
(4469, 'CODEX STAN', 'CAC - Codex Alimentarius Commission (CAC)', 'C O D E X  A L I M E N T A R I U S  is about safe, good food for everyone - everywhere.\n\nInternational food trade has existed for thousands of years but until not too long ago food was mainly produced, sold and consumed locally. Over the last century the amount of food traded internationally has grown exponentially, and a quantity and variety of food never before possible travels the globe today.\n\nInternational Food Standards\n\nThe C O D E X  A L I M E N T A R I U S international food standards, guidelines and codes of practice contribute to the safety, quality and fairness of this international food trade. Consumers can trust the safety and quality of the food products they buy and importers can trust that the food they ordered will be in accordance with their specifications.\n\nPublic concerns about food safety issues often place Codex at the centre of global debates. Veterinary drugs, pesticides, food additives and contaminants are some of the issues discussed in Codex meetings. Codex standards are based on sound science provided by independent international risk assessment bodies or ad-hoc consultations organized by FAO and WHO. \n\nWhile being recommendations for voluntary application by members, Codex standards serve in many cases as a basis for national legislation.\n\nThe reference made to Codex food safety standards in the World Trade Organization\'s Agreement on Sanitary and Phytosanitary measures (SPS Agreement) means that Codex has far reaching implications for resolving trade disputes. WTO members that wish to apply stricter food safety measures than those set by Codex may be required to justify these measures scientifically.\n\nSince its foundation in 1963, the Codex system has evolved in an open, transparent and inclusive way to meet emerging challenges. International food trade is a 2000 billion dollar a year industry, with billions of tonnes of food produced, marketed and transported.', 'Uỷ ban Tiêu chuẩn thực phẩm CODEX làm một tổ chức liên chính phủ với hơn 170 thành viên, trong khuôn khổ Chương trình Tiêu chuẩn Thực phẩm Phối hợp chung do FAO và WHO thiết lập, với mục đích bảo vệ sức khoẻ người tiêu dùng, đảm bảo hoạt động kinh doanh thực phẩm công bằng. CODEX Alimentarius (tiếng Latin có nghĩa là Bộ quy tắc hoặc Luật về Thực phẩm) là kết quả hoạt động của Uỷ ban: một tập hợp các tiêu chuẩn, hướng dẫn, quy chế thực hành và những khuyến nghị về thực phẩm được quốc tế chấp nhận. Thông qua website của CODEX, người sử dụng có thể tải xuống nhiều tài liệu miễn phí, bao gồm: Các sổ tay quy trình, Chiến lược các giai đoạn, Danh mục các tiêu chuẩn chính thức và phiên bản của các tiêu chuẩn.', 'Uỷ ban Tiêu chuẩn thực phẩm CODEX làm một tổ chức liên chính phủ với hơn 170 thành viên, trong khuôn khổ Chương trình Tiêu chuẩn Thực phẩm Phối hợp chung do FAO và WHO thiết lập, với mục đích bảo vệ sức khoẻ người tiêu dùng, đảm bảo hoạt động kinh doanh thực phẩm công bằng. CODEX Alimentarius (tiếng Latin có nghĩa là Bộ quy tắc hoặc Luật về Thực phẩm) là kết quả hoạt động của Uỷ ban: một tập hợp các tiêu chuẩn, hướng dẫn, quy chế thực hành và những khuyến nghị về thực phẩm được quốc tế chấp nhận. Thông qua website của CODEX, người sử dụng có thể tải xuống nhiều tài liệu miễn phí, bao gồm: Các sổ tay quy trình, Chiến lược các giai đoạn, Danh mục các tiêu chuẩn chính thức và phiên bản của các tiêu chuẩn.', 'CODEX STAN, CAC/GL, CAC/RCP, XOT', 'CODEX STAN, CAC, International standards on Foods (CODEX STAN), Codex Alimentarius Commission (CAC)', '01.040.65*01.040.67,*65*67', 'publisher/avatar/UZTMQKZRLMWLL28NBW4B.jpg', 0),
(4470, 'ITU', 'ITU - International Telecommunication Union (ITU)', 'ITU is the United Nations specialized agency for information and communication technologies (ICTs). The Organization is made up of a membership of 193 Member States and more than 1000 companies, universities and international and regional organizations. Headquartered in Geneva, Switzerland, and with regional offices on every continent, ITU is the oldest agency in the UN family – connecting the world since the dawn of the telegraph in 1865.\nITU facilitate international connectivity in communication networks. ITU allocate global radio spectrum and satellite orbits, develop the technical standards that ensure networks and technologies connect seamlessly, and work to improve access to digital technologies in underserved communities worldwide. ITU works to bring digital connectivity to everyone, providing a trusted, multilateral platform to broker international agreements and standards, share knowledge, build capacity, and work with members and partners to spread access to technology around the world.\nTechnology has become the backbone of modern life. Networks and devices everywhere rely on ITU\'s work. Every time we use a mobile phone, send an e-mail, access the Internet, watch TV or streaming services, take a plane, consult the weather forecast, or use satellite images to navigate or explore, we are relying on ITU\'s work. 2.6 billion people, largely in developing countries, remain unconnected. ITU works to close this digital divide through universal connectivity and sustainable digital transformation.\nThe main products of ITU-T are Recommendations (ITU-T Recs) - standards defining how telecommunication networks operate and interwork. These can be accessed through the links below. ITU-T Recs have non-mandatory status until they are adopted in national laws. The level of compliance is nonetheless high due to international applicability and the high quality guaranteed by ITU-T\'s secretariat, and members from the world\'s foremost information and communication technology (ICT) companies and global administrations.\nThere are over 4000 Recommendations in force on topics from service definition to network architecture and security, from broadband DSL to Gbit/s optical transmission systems, next-generation networks (NGN) and IP-related issues. All of these topics make part of the fundamental components of today\'s ICTs.\nMembership of ITU-T gives exclusive rights to access working documents of standards under development – tomorrow\'s ICTs. The vast majority of all Recommendations are available in electronic (PDF) form, free of charge to all, once the final, edited version is published. Texts that are not free of charge include common ITU-T | ISO / IEC texts for which special arrangements exist. Find out more about membership here.\nITU-T Recommendations are available through the Website in tree views, offering multi-criteria search and cross navigation facilities. Each ITU-T Recommendation is cross-linked to the corresponding work programme item, Alternative and Traditional Approval Processes, formal descriptions (more than 1400 freely available), test signals (more than 15 GB of data freely available), supplements, implementer\'s guides, and IPR statements when applicable.', 'ITU là cơ quan chuyên môn của Liên hợp quốc về công nghệ thông tin và truyền thông (ICT). Tổ chức này bao gồm 193 quốc gia thành viên và hơn 1000 công ty, trường đại học và tổ chức quốc tế và khu vực. Có trụ sở chính tại Geneva, Thụy Sĩ và có các văn phòng khu vực trên mọi châu lục, ITU là cơ quan lâu đời nhất trong gia đình Liên hợp quốc – kết nối thế giới kể từ khi điện báo ra đời vào năm 1865.\nITU tạo điều kiện kết nối quốc tế trong các mạng lưới truyền thông. ITU phân bổ phổ vô tuyến toàn cầu và quỹ đạo vệ tinh, phát triển các tiêu chuẩn kỹ thuật đảm bảo mạng lưới và công nghệ kết nối liền mạch và nỗ lực cải thiện khả năng tiếp cận công nghệ kỹ thuật số trong các cộng đồng chưa được phục vụ trên toàn thế giới. ITU nỗ lực mang kết nối kỹ thuật số đến với mọi người, cung cấp một nền tảng đa phương đáng tin cậy để làm trung gian cho các thỏa thuận và tiêu chuẩn quốc tế, chia sẻ kiến ​​thức, xây dựng năng lực và hợp tác với các thành viên và đối tác để phổ biến khả năng tiếp cận công nghệ trên toàn thế giới.\nCông nghệ đã trở thành xương sống của cuộc sống hiện đại. Mạng lưới và thiết bị ở khắp mọi nơi đều dựa vào công việc của ITU. Mỗi khi chúng ta sử dụng điện thoại di động, gửi email, truy cập Internet, xem TV hoặc các dịch vụ phát trực tuyến, đi máy bay, xem dự báo thời tiết hoặc sử dụng hình ảnh vệ tinh để điều hướng hoặc khám phá, chúng ta đang dựa vào công việc của ITU. 2,6 tỷ người, chủ yếu ở các nước đang phát triển, vẫn chưa được kết nối. ITU nỗ lực thu hẹp khoảng cách số này thông qua kết nối toàn cầu và chuyển đổi số bền vững.\nCác sản phẩm chính của ITU-T là Khuyến nghị (ITU-T Recs) - các tiêu chuẩn xác định cách thức hoạt động và tương tác của các mạng viễn thông. Có thể truy cập các tiêu chuẩn này thông qua các liên kết bên dưới. ITU-T Recs có trạng thái không bắt buộc cho đến khi chúng được thông qua trong luật quốc gia. Tuy nhiên, mức độ tuân thủ vẫn cao do khả năng áp dụng quốc tế và chất lượng cao được đảm bảo bởi ban thư ký của ITU-T và các thành viên từ các công ty công nghệ thông tin và truyền thông (ICT) hàng đầu thế giới và các cơ quan hành chính toàn cầu.\nCó hơn 4000 Khuyến nghị có hiệu lực về các chủ đề từ định nghĩa dịch vụ đến kiến ​​trúc mạng và bảo mật, từ DSL băng thông rộng đến hệ thống truyền dẫn quang Gbit/s, mạng thế hệ tiếp theo (NGN) và các vấn đề liên quan đến IP. Tất cả các chủ đề này đều là một phần của các thành phần cơ bản của CNTT ngày nay.\nTư cách thành viên của ITU-T mang lại quyền độc quyền để truy cập vào các tài liệu làm việc của các tiêu chuẩn đang được phát triển - CNTT của tương lai. Phần lớn tất cả các Khuyến nghị đều có sẵn ở dạng điện tử (PDF), miễn phí cho tất cả mọi người, sau khi phiên bản cuối cùng đã chỉnh sửa được xuất bản. Các văn bản không miễn phí bao gồm các văn bản ITU-T | ISO / IEC phổ biến có các thỏa thuận đặc biệt. Tìm hiểu thêm về tư cách thành viên tại đây.\nCác Khuyến nghị của ITU-T có sẵn thông qua Trang web ở dạng cây, cung cấp các tiện ích tìm kiếm đa tiêu chí và điều hướng chéo. Mỗi Khuyến nghị của ITU-T đều được liên kết chéo với mục chương trình làm việc tương ứng, Quy trình phê duyệt thay thế và truyền thống, mô tả chính thức (hơn 1400 mô tả có sẵn miễn phí), tín hiệu thử nghiệm (hơn 15 GB dữ liệu có sẵn miễn phí), phần bổ sung, hướng dẫn cho người thực hiện và tuyên bố về IPR khi áp dụng.', 'ITU là cơ quan chuyên môn của Liên hợp quốc về công nghệ thông tin và truyền thông (ICT). Tổ chức này bao gồm 193 quốc gia thành viên và hơn 1000 công ty, trường đại học và tổ chức quốc tế và khu vực. Có trụ sở chính tại Geneva, Thụy Sĩ và có các văn phòng khu vực trên mọi châu lục, ITU là cơ quan lâu đời nhất trong gia đình Liên hợp quốc – kết nối thế giới kể từ khi điện báo ra đời vào năm 1865.', 'ITU-R, ITU-T', 'International Telecommunication Union, ITU standards, ITU, Telecommunication, information and communication technologies, ICT', '01.040.33*33', 'publisher/avatar/N1284BEEJNYH1TR96MWR.jpg', 0),
(4471, 'QCVN', 'QCVN - National Technical Regulation (QCVN)', 'QCVN (Quy chuẩn kỹ thuật quốc gia) translates to \"National Technical Regulation\" in English. It refers to a set of legally binding standards established by the Vietnamese government to ensure the quality, safety, and environmental protection of products and services across various industries.\nThe purpose of QCVN (Quy chuẩn kỹ thuật quốc gia) or National Technical Regulation is to:\n1. Ensure Safety and Quality: Establish requirements for the safety, quality, and performance of products and services to protect public health and safety.\n2. Protect Consumers: Provide guidelines that help consumers make informed choices and ensure the goods and services they use meet minimum quality standards.\n3. Promote Fair Trade: Create a level playing field for producers and manufacturers by standardizing product quality, thus facilitating fair competition.\n4. Environmental Protection: Set regulations that address environmental impacts, promoting sustainable practices within industries.\n5. Enhance Product Competitiveness: Support industries in improving their products to meet both domestic and international requirements, thus increasing competitiveness in global markets.\nOverall, QCVN serves as a framework for regulatory compliance across various sectors in Vietnam.', 'QCVN (Quy chuẩn kỹ thuật quốc gia) có nghĩa là \"Quy chuẩn kỹ thuật quốc gia\". Quy chuẩn này đề cập đến một bộ tiêu chuẩn ràng buộc về mặt pháp lý do chính phủ Việt Nam thiết lập để đảm bảo chất lượng, an toàn và bảo vệ môi trường cho các sản phẩm và dịch vụ trong nhiều ngành công nghiệp khác nhau.\nMục đích của QCVN (Quy chuẩn kỹ thuật quốc gia) hoặc Quy chuẩn kỹ thuật quốc gia là:\n1. Đảm bảo an toàn và chất lượng: Thiết lập các yêu cầu về an toàn, chất lượng và hiệu suất của các sản phẩm và dịch vụ để bảo vệ sức khỏe và sự an toàn của cộng đồng.\n2. Bảo vệ người tiêu dùng: Cung cấp các hướng dẫn giúp người tiêu dùng đưa ra lựa chọn sáng suốt và đảm bảo hàng hóa và dịch vụ họ sử dụng đáp ứng các tiêu chuẩn chất lượng tối thiểu.\n3. Thúc đẩy thương mại công bằng: Tạo sân chơi bình đẳng cho các nhà sản xuất và chế tạo bằng cách chuẩn hóa chất lượng sản phẩm, do đó tạo điều kiện cho cạnh tranh công bằng.\n4. Bảo vệ môi trường: Thiết lập các quy định giải quyết các tác động đến môi trường, thúc đẩy các hoạt động bền vững trong các ngành công nghiệp.\n5. Nâng cao năng lực cạnh tranh của sản phẩm: Hỗ trợ các ngành công nghiệp cải tiến sản phẩm của mình để đáp ứng các yêu cầu trong nước và quốc tế, do đó tăng khả năng cạnh tranh trên thị trường toàn cầu.\nNhìn chung, QCVN đóng vai trò là khuôn khổ tuân thủ quy định trong nhiều lĩnh vực khác nhau tại Việt Nam.', 'QCVN (Quy chuẩn kỹ thuật quốc gia) có nghĩa là \"Quy chuẩn kỹ thuật quốc gia\". Quy chuẩn này đề cập đến một bộ tiêu chuẩn ràng buộc về mặt pháp lý do chính phủ Việt Nam thiết lập để đảm bảo chất lượng, an toàn và bảo vệ môi trường cho các sản phẩm và dịch vụ trong nhiều ngành công nghiệp khác nhau.', 'QCVN', 'QCVN, National Technical Regulation', NULL, 'publisher/avatar/1T0D9PDDNRQBHP9P3IM3.jpg', 0);
INSERT INTO `wp_tecbook_publishers` (`id`, `publisherCode`, `englishTitle`, `englishDescription`, `vietnameseDescription`, `abstract`, `reference`, `keyword`, `relatedICSCode`, `avatarPath`, `featured`) VALUES
(4472, 'GB', 'GB - Chinese national standards', 'Standards GB are Chinese national standards, which are issued by China\'s Standardization Administration Office (SAC). \n\nChinese national standards are used all over China commonly labeled as GB standards. They determine the united production requirements regarding product safety and quality .\nGB standards are often modified or created according to the international standards of ISO, IEC or any other international level. Although, they are largely harmonized, GB standards may differ from international standards.\n\nApproximately 15% of all GB standards are obligatory and they can be identified according to the prefix GB, after which the code of the standards follows:\n\nGB – Obligatory national standards\nGB/T – Optional national standards\nGB/Z – National steering technical document \nWith the development through China\'s reforms and opening up, in April of 2001, the State Council of China decided to set up the General Administration of Quality Supervision, Inspection & Quarantine of the People\'s Republic of China (AQSIQ), by merging the former CSBTS and the former State Bureau of Import & Export Inspection and Quarantine (CIQ SA) and, at the same time, to establish the Standardization Administration of the People\'s Republic of China (SAC) and Certification and Accreditation Administration of the People\'s Republic of China (CNCA) under AQSIQ.\n\nThe functions of the SAC authorized by the State Council are to exercise administrative responsibilities by undertaking unified management, supervision and overall coordination of standardization work in China. The SAC represents China within the International Organization for Standardization (ISO), the International Electrotechnical Commission (IEC) and other international and regional standardization organizations; the SAC is responsible for organizing the activities of the Chinese National Committee for ISO and IEC; the SAC approves and organizes the implementation of international cooperation and the exchange of projects on standardization.  \n\nWhat is GB standards (GuoBiao Standards)? \n\nGB standards are the China national standards, also called as Guobiao Standards, China GB standards are classified as two stages, Mandatory or Recommended. Mandatory standards have the force of law as do other technical regulations in China. They are enforced by laws and administrative regulations and concern the protection of human health, personal property and safety. All standards that fall outside of these characteristics are considered Recommended standards.\n\nChina GB standards can be identified as Mandatory or Recommended by their prefix code, Prefix code GB are Mandatory standards, GB/T are Recommended standards (Quasi-Mandatory standards ).\n\nWhy do I need to comply with GB Standards?\n\nIn China, All products or services must be complied with GB standards, no matter domestic or imported products, Any products being sold in China are required to be tested in order to ensure their compliance with GB standards.\n\nIf you want to export products or services to huge Chinese market, need to understand and be aware of the complexities and necessary requirements under the vast range of GB standards, need to ensure they are meet the requirements of GB china national standards.\n\nThe outcome of failing to comply with GB standards can include the rejection of products during importation as well as products being seized from stores, resulting in a significant impact on retailers and manufacturers in terms of reputation and cost.\n\nGB Standards System Main Organizations\n\nThe GB standards system in China is administered at the top by the General Administration of Quality Supervision, Inspection and Quarantine (AQSIQ) and headed primarily by the Standardization Administration of the People’s Republic of China (SAC).\n\nOther governmental and private sector organizations provide a significant amount of additional input and participate in the standards process, Main Organizations include:\n\nGeneral Administration of Quality Supervision, Inspection and Quarantine (AQSIQ)\n\nStandardization Administration of the People’s Republic of China (SAC)\n\nChina Association of Standardization (CAS)\n\nChina National Institute of Standardization (CNIS)\n\nStandards Press of China (SPC)', 'Tiêu chuẩn Trung Quốc GB là tiêu chuẩn quốc gia của Trung Quốc, còn được gọi là Tiêu chuẩn Guobiao, tiêu chuẩn GB của Trung Quốc được phân loại thành hai giai đoạn, Bắt buộc hoặc Khuyến nghị. Các tiêu chuẩn bắt buộc có hiệu lực pháp luật cũng như các quy định kỹ thuật khác ở Trung Quốc. Chúng được thực thi bởi luật pháp và các quy định hành chính và liên quan đến việc bảo vệ sức khỏe con người, tài sản cá nhân và sự an toàn. Tất cả các tiêu chuẩn nằm ngoài các đặc điểm này đều được coi là tiêu chuẩn Khuyến nghị.\nCác tiêu chuẩn GB của Trung Quốc có thể được xác định là Bắt buộc hoặc Được khuyến nghị theo mã tiền tố của chúng, Mã tiền tố GB là các tiêu chuẩn Bắt buộc, GB/T là các tiêu chuẩn được Khuyến nghị (Tiêu chuẩn gần như bắt buộc ).\nTại Trung Quốc, tất cả sản phẩm hoặc dịch vụ phải tuân thủ các tiêu chuẩn GB, bất kể sản phẩm trong nước hay nhập khẩu. Bất kỳ sản phẩm nào được bán ở Trung Quốc đều phải được kiểm tra để đảm bảo tuân thủ các tiêu chuẩn GB;\nNếu bạn muốn xuất khẩu sản phẩm hoặc dịch vụ sang thị trường Trung Quốc rộng lớn, cần hiểu và nhận thức được sự phức tạp cũng như các yêu cầu cần thiết trong vô số tiêu chuẩn GB, cần đảm bảo chúng đáp ứng các yêu cầu của tiêu chuẩn quốc gia GB Trung Quốc;\nHậu quả của việc không tuân thủ các tiêu chuẩn GB có thể bao gồm việc sản phẩm bị từ chối trong quá trình nhập khẩu cũng như sản phẩm bị tịch thu từ các cửa hàng, dẫn đến tác động đáng kể đến các nhà bán lẻ và nhà sản xuất về uy tín và chi phí.\nHệ thống tiêu chuẩn GB ở Trung Quốc được quản lý ở cấp cao nhất bởi Tổng cục Giám sát, Kiểm tra và Kiểm dịch Chất lượng (AQSIQ) và chủ yếu do Cục Tiêu chuẩn hóa Cộng hòa Nhân dân Trung Hoa (SAC) đứng đầu.\nCác tổ chức thuộc khu vực chính phủ và tư nhân khác cung cấp lượng đầu vào bổ sung đáng kể và tham gia vào quy trình tiêu chuẩn, Các tổ chức chính bao gồm:\n• Tổng cục Giám sát, Kiểm định và Kiểm dịch Chất lượng (AQSIQ)\n• Cục Tiêu chuẩn hóa Cộng hòa Nhân dân Trung Hoa (SAC)\n• Hiệp hội Tiêu chuẩn hóa Trung Quốc (CAS)\n• Viện Tiêu chuẩn Quốc gia Trung Quốc (CNIS)\n• Nhà xuất bản tiêu chuẩn Trung Quốc (SPC)\nCó bốn hệ thống tiêu chuẩn của Trung Quốc, đó là\n• Tiêu chuẩn quốc gia Trung Quốc\n• Tiêu chuẩn công nghiệp Trung Quốc\n• Tiêu chuẩn địa phương của Trung Quốc\n• Tiêu chuẩn doanh nghiệp Trung Quốc\nCác Lớp này được phân cấp, Tiêu chuẩn lớp thấp phải tuân thủ các tiêu chuẩn lớp cao hơn, tiêu chuẩn GB là tiêu chuẩn lớp cao nhất, do đó tất cả các tiêu chuẩn lớp khác cần phải tuân theo tiêu chuẩn GB.', 'Tiêu chuẩn Trung Quốc GB là tiêu chuẩn quốc gia của Trung Quốc, còn được gọi là Tiêu chuẩn Guobiao, tiêu chuẩn GB của Trung Quốc được phân loại thành hai giai đoạn, Bắt buộc hoặc Khuyến nghị. Các tiêu chuẩn bắt buộc có hiệu lực pháp luật cũng như các quy định kỹ thuật khác ở Trung Quốc. Chúng được thực thi bởi luật pháp và các quy định hành chính và liên quan đến việc bảo vệ sức khỏe con người, tài sản cá nhân và sự an toàn. Tất cả các tiêu chuẩn nằm ngoài các đặc điểm này đều được coi là tiêu chuẩn Khuyến nghị.', 'GB, GBT, GBZ', 'Chinese national standards, GB, GB/T, GB/Z, GB Standards', NULL, 'publisher/avatar/6P6LA1I586GKIRF9CTRE.png', 0),
(4473, 'OIML', 'OIML - International Organization of Legal Metrology (OIML)', 'The International Organization of Legal Metrology is an intergovernmental treaty organization which\n\ndevelops model regulations, standards and related documents for use by legal metrology authorities and industry,\nprovides mutual recognition systems which reduce trade barriers and costs in a global market,\nrepresents the interests of the legal metrology community within international organizations and forums concerned with metrology, standardization, testing, certification and accreditation,\npromotes and facilitates the exchange of knowledge and competencies within the legal metrology community worldwide,\ncooperates with other metrology bodies to raise awareness of the contribution that a sound legal metrology infrastructure can make to a modern economy.\nThe OIML issues several categories of publications:\n\nInternational Recommendations, which are intended as model regulations for a number of categories of measuring instruments, and which OIML Member States are morally obliged to implement as far as possible;\nInternational Documents, which are informative and are intended for guidance purposes; and\nother publications such as Vocabularies, Guides, Basic Publications and Expert Reports.\nIn addition, the OIML has developed the OIML Certification System (OIML-CS). Under the OIML-CS participants declare that they intend to accept and utilize OIML Certificates and/or OIML type evaluation reports from those participants that are entitled to issue OIML Certificates.\n\nThe OIML is an “international standard-setting body” in the sense of the World Trade Organization\'s Technical Barriers to Trade Agreement. OIML publications should therefore be applied, when appropriate, by all signatories of the TBT Agreement when developing technical regulations, in application of Article 2.4 of that Agreement:\n\n\"Where technical regulations are required and relevant international standards exist or their completion is imminent, Members shall use them, or the relevant parts of them, as a basis for their technical regulations except when such international standards or relevant parts would be an ineffective or inappropriate means for the fulfillment of the legitimate objectives pursued, for instance because of fundamental climatic or geographical factors or fundamental technological problems.\"', 'OIML (International Organization of Legal Metrology) là tổ chức quốc tế chuyên về đo lường pháp quyền. OIML được thành lập vào năm 1955 và có trụ sở tại Paris, Pháp.\n\nOIML có nhiệm vụ phát triển và thúc đẩy tiêu chuẩn và quy định quốc tế về đo lường pháp quyền. Tổ chức này tập trung vào việc đảm bảo tính chính xác, đáng tin cậy và tương đồng của các quy trình đo lường và thiết bị đo lường trên toàn cầu.\n\nCác tiêu chuẩn và quy định của OIML áp dụng cho nhiều lĩnh vực đo lường, bao gồm đo lường khối lượng, đo lường áp suất, đo lường nhiệt độ, đo lường điện, đo lường độ dẻo, và nhiều lĩnh vực khác. OIML cũng đóng vai trò quan trọng trong việc thúc đẩy sự công nhận tương đương giữa các tiêu chuẩn và quy định đo lường của các quốc gia khác nhau.\n\nCác thành viên của OIML bao gồm các quốc gia, tổ chức quốc tế và các cơ quan đo lường pháp quyền. OIML là một diễn đàn quan trọng để các thành viên cùng nhau thảo luận, hợp tác và phát triển các tiêu chuẩn và quy định mới trong lĩnh vực đo lường pháp quyền.\n\nVai trò của OIML đảm bảo rằng đo lường pháp quyền trên toàn cầu được thực hiện một cách đồng nhất và tin cậy, đồng thời tạo điều kiện thuận lợi cho thương mại công bằng và bảo vệ người tiêu dùng.', 'OIML (International Organization of Legal Metrology) là tổ chức quốc tế chuyên về đo lường pháp quyền. OIML được thành lập vào năm 1955 và có trụ sở tại Paris, Pháp.', 'OIML', 'OIML International Organization of Legal Metrology, OIML', '17*75.180.30*01.040.17', 'publisher/avatar/OTEJM9TWTSAKO3KFLAU5.png', 0),
(4474, 'ANSI', 'ANSI - American National Standards Institute', 'The American National Standards Institute (ANSI) is a private, non-profit organization that administers and coordinates the U.S. voluntary standards and conformity assessment system. Founded in 1918, the Institute works in close collaboration with stakeholders from industry and government to identify and develop standards- and conformance-based solutions to national and global priorities.\nTogether, standards and technical regulations impact up to 93% of global trade. Globally relevant standards and the conformance measures that assure their effective use help to increase efficiency, open markets, boost consumer confidence, and reduce costs. And ANSI is the U.S. leader in fostering that potential for the benefit of businesses across every industry and consumers around the world.\nANSI is not itself a standards developing organization. Rather, the Institute provides a framework for fair standards development and quality conformity assessment systems and continually works to safeguard their integrity. And as a neutral venue for coordination of standards-based solutions, the Institute brings together private- and public-sector experts and stakeholders to initiate collaborative standardization activities that respond to national priorities.\nANSI serves as a strong voice on behalf of the U.S. voluntary standards community, protecting and strengthening its impact domestically and internationally. Through its membership, partnerships, and diverse programs and activities, ANSI represents the interests of more than 270,000 companies and organizations and 30 million professionals worldwide.', 'Viện Tiêu chuẩn Quốc gia Hoa Kỳ (ANSI) là một tổ chức tư nhân, phi lợi nhuận quản lý và điều phối hệ thống đánh giá sự phù hợp và tiêu chuẩn tự nguyện của Hoa Kỳ. Được thành lập vào năm 1918, Viện hợp tác chặt chẽ với các bên liên quan từ ngành công nghiệp và chính phủ để xác định và phát triển các giải pháp dựa trên tiêu chuẩn và sự phù hợp cho các ưu tiên quốc gia và toàn cầu.\nCùng nhau, các tiêu chuẩn và quy định kỹ thuật tác động đến 93% thương mại toàn cầu. Các tiêu chuẩn có liên quan trên toàn cầu và các biện pháp phù hợp đảm bảo việc sử dụng hiệu quả của chúng giúp tăng hiệu quả, mở rộng thị trường, thúc đẩy niềm tin của người tiêu dùng và giảm chi phí. Và ANSI là đơn vị dẫn đầu Hoa Kỳ trong việc thúc đẩy tiềm năng đó vì lợi ích của các doanh nghiệp trong mọi ngành công nghiệp và người tiêu dùng trên toàn thế giới.\nBản thân ANSI không phải là một tổ chức phát triển tiêu chuẩn. Thay vào đó, Viện cung cấp một khuôn khổ để phát triển các tiêu chuẩn công bằng và các hệ thống đánh giá sự phù hợp chất lượng và liên tục hoạt động để bảo vệ tính toàn vẹn của chúng. Và với tư cách là một địa điểm trung lập để phối hợp các giải pháp dựa trên tiêu chuẩn, Viện tập hợp các chuyên gia và bên liên quan trong khu vực tư nhân và công cộng để khởi xướng các hoạt động chuẩn hóa hợp tác đáp ứng các ưu tiên quốc gia.\nANSI đóng vai trò là tiếng nói mạnh mẽ thay mặt cho cộng đồng tiêu chuẩn tự nguyện của Hoa Kỳ, bảo vệ và tăng cường tác động của cộng đồng này trong nước và quốc tế. Thông qua tư cách thành viên, quan hệ đối tác và các chương trình và hoạt động đa dạng, ANSI đại diện cho lợi ích của hơn 270.000 công ty và tổ chức và 30 triệu chuyên gia trên toàn thế giới.', 'ANSI supports the development and approval of national voluntary standards, develops accreditation programs, and serves as U.S. representative to the International Standards Organization (ISO). Members include trade associations, labor unions, professional societies, standards developing organizations, private industry, academe, and government.', 'ANSI; ANSI/ANSLG; ANSI/NEMA; ANSI/TCNA; ANSI/UAMA', NULL, NULL, 'publisher/avatar/GHY4LSWF3TYCKCJAZ2OL.jpg', 0);
INSERT INTO `wp_tecbook_standards` (`id`, `idProduct`, `referenceNumber`, `standardTitle`, `status`, `referencedStandards`, `referencingStandards`, `equivalentStandards`, `replace`, `replacedBy`, `standardby`, `languages`, `fullDescription`, `ebookPrice`, `printPrice`, `bothPrice`, `currency`, `historicalEditions`, `documentHistoryProductId`, `icsCode`, `keyword`, `identicalStandards`, `publishedDate`, `pages`, `byTechnology`, `byIndustry`, `previewPath`, `coverPath`, `fullPath`, `deleted`, `newArrival`, `bestSellers`, `isFree`, `specialOffer`, `featured`) VALUES
(182936, '2250713', NULL, 'Machinery for forestry - Portable chain-saw safety requirements and testing - Part 1: Chain-saws for forest service', 'Active', NULL, NULL, NULL, 'ISO 11681-1:1996', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies safety requirements and measures for verification for the design, construction, transporting and commissioning of portable, combustion-engine, hand-held chain-saws. The chain-saws are intended to be used for forest work by only one operator, with the right hand on the rear handle and left hand on the front handle.Dismantling and scrapping of the product is not covered by this document. Methods for the elimination or reduction of hazards arising from the use of these machines and the type of information on safe working practices to be provided by the manufacturer are specified.This document deals with all significant hazards, hazardous situations and hazardous events, with the exception of kickback and balance for machines with an engine displacement of more than 80 cm3, relevant to these machines when they are used as intended and under conditions of misuse which are reasonably foreseeable by the manufacturer (see Annex A).This document is applicable to chain-saws manufactured after its date of publication.', '149', '166.00', '259.00', 'USD', 'ISO 11681-1:2011;ISO 11681-1:2004', '1822332;1153178', '01.040.01* 65.060* 65.060.80', NULL, NULL, '2022', '32', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182937, '2249600', 'ISO 17439', 'Health informatics - Development of terms and definitions for health informatics glossaries', 'Active', NULL, NULL, NULL, 'ISO/TS 17439:2014', NULL, 'ISO - International Organization for Standardization', 'English', 'This document provides details of the metadata and requirements for quality terms and definitions in health informatics for inclusion in health informatics glossaries.\nThis document does not cover specification of terminological content in systems, such as that represented in terminological resources, such as SNOMED CT, or, ICD. It is limited to concepts represented as terms and definitions included in standards.\nThis document is applicable to the following groups:\n&mdash; Health informatics standards developers and standards development organizations.\n&mdash; Developers, implementers, and managers of health information systems, clinical information systems, and clinical decision support systems.\n&mdash; All users of health information systems clinical data, such as health statisticians, researchers, public health agencies, health insurance providers, health risk organizations, data analysts, and data managers.', '73', '81.00', '127.00', 'USD', 'ISO/TS 17439:2014', '1886969', '31* 35.240* 35.240.80', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 0, 0, 1, 1),
(182938, '2250866', 'ISO 638-1', 'Paper, board, pulps and cellulosic nanomaterials - Determination of dry matter content by oven-drying method - Part 1: Materials in solid form', 'Active', NULL, NULL, NULL, 'ISO 638-1:2021', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies an oven-drying method for the determination of the dry matter content in paper, board, pulp and cellulosic nanomaterials in solid form, which all can be produced from virgin and /or recycled materials.It is also applicable to the determination of the dry matter content of paper and board for recycling.The procedure is applicable to paper, board, and pulp and cellulosic nanomaterials which do not contain any appreciable quantities of materials other than water that are volatile at the temperature of 105 &deg;C &plusmn; 2 &deg;C. It is used, for example, in the case of pulp, paper, and board and cellulosic nanomaterial samples taken for chemical and physical tests in the laboratory, when a concurrent determination of dry matter content is required.This method is not applicable to the determination of the dry matter content of slush pulp or to the determination of the saleable mass of pulp lots.NOTE  ISO 638-2[1] specifies an oven-drying method for the determination of the dry matter content of suspensions of cellulosic nanomaterials, ISO 287[2] specifies the determination of the moisture content of a lot of paper and board; ISO 4119[3] specifies the determination of stock concentration of pulps; the ISO 801 series[4] specifies the determination of the saleable mass in lots.NOTE This document determines the total dry matter content of the sample, including any dissolved solids. If only the cellulosic material content free of dissolved solids is desired, dissolved solids are removed prior to measuring the dry matter content, e.g. by washing or dialysis, taking care to retain all cellulosic material; in cases where the sample is filterable without loss of cellulosic solids, ISO 4119[3] can be used to determine the stock consistency (content of cellulosic material in solid form).', '73', '81.00', '127.00', 'USD', 'ISO 638-1:2021', '2222558', '03.100.01* 85.040* 85.060', NULL, NULL, '2022', '18', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182939, '2250784', NULL, 'Plastics - Decorative solid surfacing materials - Part 3: Determination of properties - Solid surface shapes', 'Active', NULL, NULL, NULL, 'ISO 19712-3:2007', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the methods of test for determination of the properties of solid surfacing materials, as defined in Clause 3, in the form of shaped products. These methods are primarily intended for testing the materials specified in ISO 19712-1.\r\nThe tests can be carried out on finished products, but are generally carried out on test panels of a size sufficient to meet the requirements of the test, and of the same material and finish as the finished product.', '200', '223.00', '347.00', 'USD', 'ISO 19712-3:2007', '1529906', '03.080.99* 83.140* 83.140.20', 'Chemical resistance*Damp-heat tests*Decorative*Decorative coatings*Decorative laminates*Definitions*Dry-heat tests*Finishes*Hydrolytic resistance*Impact resistance*Impact strength*Light resisting*Loading tests*Plastics*Polymers*Properties*Shape*Solid (shape)*Specification (approval)*Surfaces*Testing*Testing conditions', NULL, '2022', '48', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182940, '2248277', 'ISO 22769', 'Essential oil of Australian sandalwood [Santalum spicatum (R.Br.) A.DC.]', 'Active', NULL, NULL, NULL, 'ISO 22769:2009', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies certain characteristics of the oil of Australian sandalwood [Santalum spicatum (R.Br.) A.DC.], with a view to facilitating the assessment of its quality.', '73', '81.00', '127.00', 'USD', 'ISO 22769:2009', '1657902', '01.040.19* 71.100* 71.100.60', 'Australia*Chemical properties*Chromatography*Definitions*Essential oils*Materials specification*Materials testing*Properties*Sandalwood*Specification (approval)*Testing', NULL, '2022', '12', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182941, '2249694', 'ISO 638-2', 'Paper, board, pulps and cellulosic nanomaterials - Determination of dry matter content by oven-drying method - Part 2: Suspensions of cellulosic nanomaterials', 'Active', NULL, NULL, NULL, 'ISO 638-2:2021', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies an oven-drying method for the determination of the dry matter content in suspensions of cellulosic nanomaterials. The procedure is applicable to cellulosic nanomaterial suspensions which do not contain any appreciable quantities of materials other than water that are volatile at the temperature of 105 &deg;C 2 &deg;C. It is used, for example, in the case of cellulosic nanomaterial suspensions samples taken for chemical and physical tests in the laboratory, when a concurrent determination of dry matter content is required.\nNOTE  This document determines the total dry matter content of the sample, including any dissolved solids. If only the cellulosic material content free of dissolved solids is desired, dissolved solids are removed prior to measuring the dry matter content, e.g. by washing or dialysis, taking care to retain all cellulosic material.', '73', '81.00', '127.00', 'USD', 'ISO 638-2:2021', '2222559', '03.100.01* 85.040* 85.060', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 1, 0, 0, 0),
(182942, '2249495', 'ISO 10423', 'Petroleum and natural gas industries - Drilling and production equipment - Wellhead and tree equipment', 'Active', NULL, NULL, NULL, 'ISO 10423:2003', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements and gives recommendations for the performance, dimensional and functional interchangeability, design, materials, testing, inspection, welding, marking, handling, storing, shipment, and purchasing of wellhead and tree equipment for use in the petroleum and natural gas industries.\nThis document does not apply to field use or field testing.\nThis document does not apply to repair of wellhead and tree equipment except for weld repair in conjunction with manufacturing.\nThis document does not apply to tools used for installation and service (e.g. running tools, test tools, wash tools, wear bushings, and lubricators).\nThis document supplements API Spec 6A, 21st edition (2018), the requirements of which are applicable with the exceptions specified in this document.', '48', '54.00', '84.00', 'USD', 'ISO 10423:2009;ISO 10423:2003', '1667568;1150408', '03.020* 75.180* 75.180.10', 'Bore holes*Dimensions*Drilling equipment*Hauling plants*Hoisting devices*Inspection*Marking*Materials specification*Natural gas industries*Oil industries*Storage*Technical data sheets*Testing*Valves*Winding gears*Holes*Pumping devices*Bearings', NULL, '2022', '12', NULL, NULL, NULL, NULL, NULL, 0, 1, 0, 0, 0, 1),
(182943, '2249736', 'ISO 8536-15', 'Infusion equipment for medical use - Part 15: Light-protective infusion sets for single use', 'Active', NULL, NULL, NULL, 'ISO 8536-15:2022/Amd1:2023', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the requirements for infusion sets for single use that use light-protective agents in the fluid path materials (henceforth abbreviated as \"light-protective infusion sets\").\nThis document also provides guidelines for performance and quality specifications of materials used in light-protective infusion sets.', '73', '81.00', '127.00', 'USD', NULL, NULL, '11* 11.040* 11.040.20', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 1, 0, 0, 1, 1),
(182944, '2250799', 'ISO 22434', 'Gas cylinders - Inspection and maintenance of valves', 'Active', NULL, NULL, NULL, 'ISO 22434:2006', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements for the inspection and maintenance of valves [including ball valves and valves with integrated pressure regulator (VIPRs)] for:\na) refillable transportable gas cylinders;\nb) cylinder bundles;\nc) pressure drums and tubes;\nwhich convey compressed, liquefied or dissolved gases.\nThis document does not apply to valves for liquefied petroleum gas (LPG).\nNOTE Where there is no risk of ambiguity, gas cylinders, cylinder bundles, pressure drums and tubes are addressed with the collective term \"gas cylinders\" within this document.\nThis document is applicable to valves reused at the time of the periodic inspection of gas cylinders, cylinder bundles, pressure drums and tubes, and can be applied at any other time, e.g. at a change of gas service (see ISO 11621).\nThis document does not apply to the routine inspection of valves, e.g. carried out at the time of a gas cylinder filling.', '73', '81.00', '127.00', 'USD', 'ISO 22434:2006', '1279704', '01* 23.060* 23.060.01* 23.020* 23.020.35', 'Compressed gas equipment*Compressed gases*Connecting threads*Connection valves*Connections*Definitions*Fittings*Gas cylinders*Gas holders*Gas pressure vessels*Gas valves*Gases*Inspection*Maintenance*Marking*Metallic materials*Mobile*Packages*Parallel threads*Screw threads*Screwed connections*Screwed joints*Specification (approval)*Testing*Thread-connections*Threads*Valve for steel cylinders*Valve threads*Valves*Lines', NULL, '2022', '14', NULL, NULL, NULL, NULL, NULL, 0, 1, 0, 0, 0, 0),
(182945, '2249699', 'ISO 6627', 'Internal combustion engines - Piston rings - Expander/rail oil-control rings', 'Active', NULL, NULL, NULL, 'ISO 6627:2000', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the essential dimensional features of expander/rail oil-control rings, without providing a complete product description (because expander rail designs vary from piston-ring manufacturer to piston-ring manufacturer, the interaction between the manufacturer and the client will determine specific design details).\nThis document applies to expander/rail oil-control rings of nominal diameters ranging from 40&deg;mm to 140&deg;mm for reciprocating internal combustion engines for road vehicles and other applications. It also applies to piston rings for compressors working under analogous conditions.', '111', '124.00', '191.00', 'USD', 'ISO 6627:2011;ISO 6627:2000', '1805001;860819', '49* 43.060* 43.060.10', 'Dimensions*Internal combustion engines*Piston rings*Road vehicles*Specification*Specifications*Vehicles', NULL, '2022', '20', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 1, 1),
(182946, '2249693', 'ISO 6183', 'Fire protection equipment - Carbon dioxide extinguishing systems for use on premises - Design and installation', 'Active', NULL, NULL, NULL, 'ISO 6183:1990', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements and gives recommendations for the design, installation, testing, maintenance and safety of fixed carbon dioxide firefighting systems in buildings, plants or other structures. It is not applicable to extinguishing systems on ships, in aircraft, on vehicles or on mobile fire appliances, or to below ground systems in the mining industry; nor does it apply to carbon dioxide pre-inerting systems.\nDesign of systems where unclosable opening(s) exceed a specified area and where the opening(s) can be subject to the effect of wind is not specified, although general guidance on the procedure to be followed in such cases is given (see 7.4.3.2).', '225', '250.00', '391.00', 'USD', 'ISO 6183:2009/Amd1:2017;ISO 6183:2009/Amd2:2019;ISO 6183:2009;ISO 6183:1990', '1992283;2094883;1630247;719147', '13* 13.220* 13.220.10', 'Carbon dioxide*Definitions*Design*Extinguishing equipment*Fire extinguishers*Fire protection*Fire safety*Firefighting equipment*Maintenance*Safety*Specification (approval)*Specifications*Testing*Warning notices*Presentations', NULL, '2022', '76', NULL, NULL, NULL, NULL, NULL, 0, 0, 1, 0, 0, 0),
(182947, '2249573', 'ISO 15179', 'Hot-rolled twin-roll cast steel sheet of structural quality and high strength steel', 'Active', NULL, NULL, NULL, 'ISO 15179:2012', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the requirements for hot-rolled twin-roll cast steel sheet of structural quality and high strength steel.\nThe product is intended for applications where specific mechanical properties are required. It is generally used in the delivered condition and is intended for bolted, riveted or welded structures, and it is produced on a wide strip mill, not a plate mill.\nStructural quality twin-roll cast steel sheet is a carbon steel produced to specified mechanical properties and is available in a number of grades.\nHigh strength hot-rolled twin-roll cast steel sheet, strengthened by microalloys is produced to specified mechanical properties and is available in a number of grades and classes.', '73', '81.00', '127.00', 'USD', 'ISO 15179:2012', '1827451', '03.060* 77.140* 77.140.50', 'Carbon steels*Cast steels*Chemical properties*Definitions*Hot rolled*Inspection*Marking*Mechanical properties*Sheet steels*Specification (approval)*Structural sheets*Testing*Tolerances (measurement)', NULL, '2022', '14', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182948, '2250802', 'ISO 22834', 'Large yachts - Quality assessment of life onboard - Stabilization and sea keeping', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document provides a comparative scale (no judgement) of motion-related comfort onboard yachts to be used for technical and commercial benefit. The scale consists of a maximum number of 5 stars, the higher the amount of stars, the higher the comfort onboard. It allows the selection of the most suitable yacht for a specific purpose, evaluates the impact of stabilization systems, compares designs and identifies the most comfortable position onboard.The methodology, work flow and criteria proposed in this document are subject to possible improvements and do not take into account certain important aspects that influence the comfort onboard.The following aspects are not covered in this document: jerk, the method to derive roll damping, stern quartering seas, risk of parametric roll, the influence of the steering devices, green water and waves impacts, compensation for yacht size, gender and age dependency, habituation.By explicitly listing the aspects that are not covered in this document, the reader becomes aware of them and can improve the assessment with dedicated considerations.', '111', '124.00', '191.00', 'USD', NULL, NULL, '61* 47.040', NULL, NULL, '2022', '24', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182949, '2250853', 'ISO 52032-1', 'Energy performance of buildings - Energy requirements and efficiencies of heating, cooling and domestic hot water (DHW) distribution systems - Part 1: Calculation procedures', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the energy performance calculation of water-based distribution systems for space heating, space cooling and domestic hot water (DHW).This document is applicable to the heat flux from the distributed water to the space and the auxiliary energy of the related pumps.The heat flux and the auxiliary energy for pumps can be calculated for any time interval (hour, month and year). The input and output data are mean values of the time interval.Instead of calculating the energy performance of water-based distribution systems, it is also possible to use measurements as long as they follow the time intervals of the whole performance calculation or can be divided into those time intervals.', '175', '194.00', '302.00', 'USD', NULL, NULL, '03.100.60* 91.120* 91.120.10', NULL, NULL, '2022', '44', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182950, '2248286', 'ISO 23956', 'Traditional Chinese medicine - Determination of benzopyrene in processed natural products', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the method for the determination of benzopyrene content in processed natural products.\nIt is applicable to processed natural products such as processed Rehmannia root, processed Cyperus rhizome, processed ginseng and processed mume fruit. It is not applicable to the analysis of minerals used in traditional Chinese medicine.', '73', '81.00', '127.00', 'USD', NULL, NULL, '11* 11.120* 11.120.10', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 1, 0),
(182951, '2250804', 'ISO 230-10', 'Test code for machine tools - Part 10: Determination of the measuring performance of probing systems of  numerically controlled machine tools', 'Active', NULL, NULL, NULL, 'ISO 230-10:2011', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies test procedures to evaluate the measuring performance of probing systems integrated with a numerically controlled machine tool. Test procedures for touch trigger probing systems and scanning probing systems operating in discrete-point measurement mode are specified in 7.1. Test procedures are specified for scanning probing systems in 7.2, for bore gauge systems in 7.3, for contacting tool measuring systems in 8.1, and for non-contacting tool measuring systems using the laser light barrier principle in 8.2.The evaluation of the performance of the machine tool, used as a coordinate measuring machine (CMM), is outside the scope of this document. Such performance evaluation involves traceability issues, is strongly influenced by machine tool geometric accuracy and can, in addition to the machine tool probing system tests specified in this document, be evaluated according to ISO 10360-2 and ISO 10360-5.Descriptions of test procedures in this document are referred to machining centres. However, tests apply in principle to most NC machine tools.', '225', '250.00', '391.00', 'USD', 'ISO 230-10:2016;ISO 230-10:2011', '1910931;1798017', '07* 25.080* 25.080.01', 'Acceptance*Acceptance inspection*Accessories*Accuracy*CNC machines*Definitions*Geometric*Machine tools*Measurement*Measuring techniques*Numerical control*Precision*Properties*Scanning system*Testing*Tolerances (measurement)', NULL, '2022', '76', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182952, '2249700', 'ISO 6721-12', 'Plastics - Determination of dynamic mechanical properties - Part 12: Compressive vibration - Non-resonance method', 'Active', NULL, NULL, NULL, 'ISO 6721-12:2009', NULL, 'ISO - International Organization for Standardization', 'English', 'This document describes a compressive vibration, non-resonance method for determining the components of the compressive complex modulus E* of polymers at frequencies typically in the range 0,01&deg;Hz to 100&deg;Hz. The method is applicable for measuring dynamic storage moduli of semi-rigid polymers in the range 1 MPa to 1 GPa.\nThis method is particularly suited to the measurements of dynamic moduli and loss factors of semi rigid plastics in the shape of a right-angled prism, cylinder or tube and can be conveniently used to study the variation of dynamic properties with temperature and frequency through most of the glass rubber relaxation region (see&deg;ISO 6721-1).', '77', '81.00', '127.00', 'USD', 'ISO 6721-12:2009', '1660154', '03.080.99* 83.080* 83.080.01', 'Compression testing*Damping*Deformation*Determination*Dynamic*Materials testing*Mathematical calculations*Mechanical properties*Modulus of elasticity*Plastics*Polymers*Pressure*Properties*Rigidity*Test specimens*Testing*Vibration tests*Visco elasticity*Motional', NULL, '2022', '14', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 1, 0),
(182953, '2250777', 'ISO 18283', 'Coal and coke - Manual sampling', 'Active', NULL, NULL, NULL, 'ISO 18283:2006', NULL, 'ISO - International Organization for Standardization', 'English', 'This document provides the basic terms used in manual sampling of coal and coke and describes the general principles of sampling. It provides procedures and requirements for establishing a manual sampling scheme, methods of manual sampling, sampling equipment, handling and storage of samples, sample preparation and a sampling report, and applies to manual sampling during the transfer of coal or coke. Guidelines for manual sampling in stationary situations are given in Annex B, but this method of sampling does not provide a representative test sample and the sampling report shall state this.\nThis document covers sampling of brown coals and lignites, but does not include sampling from coal seams, for which guidance is given in ISO 14180. Mechanical sampling of coal and coke is covered in ISO 13909.', '237', '250.00', '391.00', 'USD', 'ISO 18283/Cor1:2009;ISO 18283:2006', '1622457;1282953', '03.020* 75.160* 75.160.10* 01.040.23* 73.040', 'Bituminous coal*Coal*Coke*Definitions*Fossil fuels*Handling*Hard coal*Individual sample*Lignite*Manual*Moisture contents*Properties*Samples*Sampling methods*Solid fuels*Specimen preparation*Storage*Test equipment*Variance*Bearings*Sample preparation', NULL, '2022', '70', NULL, NULL, NULL, NULL, NULL, 0, 0, 1, 0, 0, 0),
(182954, '2249567', 'ISO 14708-4', 'Implants for surgery - Active implantable medical devices - Part 4: Implantable infusion pump systems', 'Active', NULL, NULL, NULL, 'ISO 14708-4:2008', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies particular requirements for active implantable medical devices intended to deliver a medicinal substance to site-specific locations within the human body, to provide basic assurance of safety for both patients and users. It amends and supplements ISO 14708-1:2014. The requirements of this document take priority over those of ISO 14708-1.\nThis document is applicable to active implantable medical devices intended to deliver medicinal substances to site-specific locations within the human body.\nThis document is also applicable to some non-implantable parts and accessories of the devices defined in Clause 3.\nThe tests that are specified in this document are type tests intended to be carried out on a sample of a device to show compliance and are not intended to be used for the routine testing of manufactured products.\nNOTE  This document is not intended to apply to non-implantable infusion systems.', '225', '250.00', '391.00', 'USD', 'ISO 14708-4:2008', '1588259', '11* 11.040* 11.040.40', 'Accompanying forms*Circulation*Definitions*Electrical engineering*Electrical medical equipment*Electrical safety*Electromagnetic compatibility*Electromedicine*Electronic engineering*Equipment safety*Human medicine*Implants (surgical)*Infusion pumps*Infusions*Inspection*Marking*Medical*Medical equipment*Medical sciences*Medical technology*Packages*Parenteral infusion equipment*Patient protection*Protection against electric shocks*Protective measures*Qualification tests*Safety*Safety requirements*Specification (approval)*Surgical implants*Testing', NULL, '2022', '68', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182955, '2248306', 'ISO 31073', 'Risk management - Vocabulary', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document defines generic terms related to the management of risks faced by organizations.', '48', '54.00', '84.00', 'USD', NULL, NULL, '03* 03.100* 03.100.01* 01* 01.040* 01.040.03', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 1, 0),
(182956, '2250849', 'ISO 4781', 'Building and civil engineering sealants - Determination of application life', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'The document specifies a method for the determination of application life of multi-component sealants.INSERT INTO `wp_tecbook_standards` (`id`, `idProduct`, `referenceNumber`, `standardTitle`, `status`, `referencedStandards`, `referencingStandards`, `equivalentStandards`, `replace`, `replacedBy`, `standardby`, `languages`, `fullDescription`, `ebookPrice`, `printPrice`, `bothPrice`, `currency`, `historicalEditions`, `documentHistoryProductId`, `icsCode`, `keyword`, `identicalStandards`, `publishedDate`, `pages`, `byTechnology`, `byIndustry`, `previewPath`, `coverPath`, `fullPath`, `deleted`, `newArrival`, `bestSellers`, `isFree`, `specialOffer`, `featured`) VALUES
(182975, '2250920', 'ISO 9735-11', 'Electronic data interchange for administration, commerce and transport (EDIFACT) - Application level syntax rules (Syntax version number: 4, Syntax release number: 1) - Part 11: Version 3 compatible profile for Version 4 of ISO 9735', 'Active', NULL, NULL, NULL, 'ISO 9735:1988', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the profiling rules of ISO 9735-1 to ISO&deg;9735-9 that allow users of version 3 (ISO 9735:1988 and ISO ;9735:1988/Amd.1:1992: Syntax version number: 3) to migrate to version 4 (ISO 9735:1998: Syntax version number: 4) with a minimum effort and cost.', '73', '81.00', '127.00', 'USD', 'ISO 9735/Amd1:1992;ISO 9735:1988/Amd1:1992;ISO 9735:1988', '17820;1854209;17813', '31* 35.240* 35.240.63', NULL, NULL, '2022', '18', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182976, '2249659', 'ISO 3030', 'Rolling bearings - Radial needle roller and cage assemblies - Boundary dimensions, geometrical product specifications (GPS) and tolerance values', 'Active', NULL, NULL, NULL, 'ISO 3030:1996', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the boundary dimensions for radial needle roller and cage assemblies.\nIn addition, this document gives the tolerances for the cage width and method of functional gauging of bore diameter of needle roller complement.\nInformative values for the tolerances of shaft raceway, housing raceway and raceway widths are given in Annex A.\nFunctional gauging of radial needle roller and cage assembly is given in Annex B.', '73', '81.00', '127.00', 'USD', 'ISO 3030:2011;ISO 3030:1996', '1817794;43722', '21* 21.100* 21.100.20', 'Bearings*Dimensional tolerances*Dimensions*Needle bearings*Needle roller and cage assembly*Needle rollers*Overall dimensions*Rolling bearings*Stocks', NULL, '2022', '18', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182977, '2249548', 'ISO 13050', 'Synchronous belt drives - Metric pitch, curvilinear profile systems G, H, R and S, belts and pulleys', 'Active', NULL, NULL, NULL, 'ISO 13050:1999', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the principal characteristics of metric pitch curvilinear synchronous endless belts and pulleys in G, H, R, and S profile systems for use in synchronous belt drives (also known in the past as timing belt drives, positive belt drives, gear belt drives) for mechanical power transmission and where positive indexing or synchronization can be required.\nThe principal belt and pulley characteristics include the following:\na) nominal belt tooth dimensions;\nb) belt tooth pitch spacing;\nc) belt length and width dimensions and tolerances;\nd) belt length measurement specifications;\ne) pulley groove dimensions and tolerances;\nf) pulley diameter and width dimensions and tolerances;\ng) pulley quality specification.', '225', '250.00', '391.00', 'USD', 'ISO 13050:2014;ISO 13050:1999', '1887892;715371', '21* 21.220* 21.220.10', 'Belt drives*Belts*Classification systems*Curved*Designations*Diameter*Dimensional measurement*Dimensional tolerances*Dimensions*Flanges*Flexible drives*Formulae (mathematics)*Grooved pulleys*Grooves*Length*Length measurement*Linearity*Mechanical drive*Mechanical transmission systems*Power transmission belts*Power transmission systems*Preferred sizes*Pulleys*Radius*Spaced*Thread pitch*Tooth profiles*Toothed belts*V-belts*Width*Distances', NULL, '2022', '64', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182978, '2250786', 'ISO 20397-1', 'Biotechnology - Massively parallel sequencing - Part 1: Nucleic acid and library preparation', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the general requirements for and gives guidance on quality assessments of nucleic acid samples. It specifies general guidelines for library preparations and library quality assessments prior to sequencing and data generation.', '111', '124.00', '191.00', 'USD', NULL, NULL, '07* 07.080', NULL, NULL, '2022', '22', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182979, '2250680', 'ISO 10545-18', 'Ceramic tiles - Part 18: Determination of light reflectance value (LRV)', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'The objective of this document is to define a test method to determine the light reflectance value (LRV) of ceramic tiles, including mosaic tiles.\nIt is applicable to solid-coloured, multicoloured and non-uniform shade tile surfaces including tile with flame effects, speckled or textured with different types of finishing.', '48', '54.00', '84.00', 'USD', NULL, NULL, '03.100.60* 91.100* 91.100.23', NULL, NULL, '2022', '12', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182980, '2249732', 'ISO 8103-9', 'Escalators and moving walks - Part 9: Measurement of ride quality', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements and methodology for the measurement and reporting of escalator and moving walk ride quality. This document does not specify acceptable or unacceptable ride quality values.', '111', '124.00', '191.00', 'USD', NULL, NULL, '03.100.60* 91.140* 91.140.90', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182981, '2250779', 'ISO 18752', 'Rubber hoses and hose assemblies - Wire- or textile-reinforced single-pressure types for hydraulic applications - Specification', 'Active', NULL, NULL, NULL, 'ISO 18752:2006', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements for ten classes, four grades and seven types of wire- or textile-reinforced hydraulic hoses and hose assemblies of nominal sizes ranging from 5 to 102. Each class has a single maximum working pressure for all sizes.They are suitable for use with:\n&mdash; oil-based hydraulic fluids HH, HL, HM, HR and HV as defined in ISO 6743-4 at temperatures ranging from 40 &deg;C to +100 &deg;C for types AS, AC, BS and BC hoses and from 40 &deg;C to +120 &deg;C for types CS, CC and DC hoses.\n&mdash; water-based fluids HFC, HFAE, HFAS and HFB as defined in ISO 6743 4 at temperatures ranging from 40 &deg;C to +70 &deg;C.\n&mdash; water at temperatures ranging from 0 &deg;C to +70 &deg;C.\nThis document does not include requirements for the connection ends. It is limited to the performance of hoses and hose assemblies. The hose assembly maximum working pressure is governed by the lowest maximum working pressure of the components.NOTE  It is the responsibility of the user, in consultation with the hose manufacturer, to establish the compatibility of the hose with the fluid to be used.', '111', '124.00', '191.00', 'USD', 'ISO 18752:2014;ISO 18752:2012;ISO 18752:2006', '1875676;1845230;1275402', '01* 23.040* 23.040.70', 'Classification*Dimensional tolerances*Dimensions*Fluid engineering*Fluid technology*Hose assemblies*Hoses*Hydraulic fluids*Hydraulic hoses*Marking*Materials*Packages*Physical properties*Plastics hose*Properties*Reinforced hoses*Rubber hoses*Specification*Specification (approval)*Storage*Synthetic rubber*Testing*Vulcanized rubber*Water supply engineering*Wire cores*Wire nettings*Bearings*Flexible pipes', NULL, '2022', '22', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182982, '2249631', 'ISO 22578', 'Graphical symbols - Safety colours and safety signs - Natural disaster safety way guidance system', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the principles governing the design and application of signs and plans used to create a natural disaster safety way guidance system to help people evacuate to safe areas or places of refuge in case of natural disasters (e.g. tsunamis, floods, debris flows, steep slope failures, landslides, tornados, large-scale fires, active volcanoes).\nThis document provides guidance on the selection and use of safety signs conforming to ISO&deg;7010, public information symbols conforming to ISO 7001, and text on evacuation route signs, places of refuge signs and evacuation plan signs for information related to one or more particular natural disasters. Guidance on the design, location, mounting positions and maintenance of the sign components of a natural disaster safety way guidance system is also provided.\nThis document does not apply to the determination of the need for natural disaster safety way guidance. This document assumes that the risk assessment or requirements of an enforcing authority have established the need for such natural disaster safety way guidance systems.\nThis document is not applicable to the particular hazards of high winds, snow avalanches, earthquakes or hurricanes, which cause the natural disasters covered in this document.\nThis document is applicable to safety way guidance from natural disasters from the outside of buildings to safe areas. ISO&deg;16069 is applicable to safety way guidance within a building to the emergency exit(s).', '175', '194.00', '302.00', 'USD', NULL, NULL, '01* 01.080* 01.080.10', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182983, '2248316', 'ISO 3915', 'Plastics - Measurement of resistivity of conductive plastics', 'Active', NULL, NULL, NULL, 'ISO 3915:1981', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the requirements for the laboratory testing of the resistivity of specially prepared specimens of plastics rendered conductive by the inclusion of conductive fillers or suitable modification of the structure. The test is applicable to materials of resistivity less than 106&deg; cm (104&deg; m).\nThe result is not strictly a volume resistivity, because of surface conduction, but the effects of the latter are generally negligible.', '51', '54.00', '84.00', 'USD', 'ISO 3915:1981', '717788', '03.080.99* 83.080* 83.080.01', 'Electrical resistance*Electrical resistivity*Laboratory testing*Laboratory tests*Measurement*Plastics*Resistivity*Test pieces*Test specimens*Testing', NULL, '2022', '14', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182984, '2250788', 'ISO 2078', 'Textile glass - Yarns - Designation', 'Active', NULL, NULL, NULL, 'ISO 2078:1993', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies a system of designating textile glass yarns (including single, multiple-wound, folded (plied), cabled and textured yarns, strands, slivers and rovings) based on their linear density expressed in the tex system.', '48', '54.00', '84.00', 'USD', 'ISO 2078:1993', '716488', '91* 59.100* 59.100.10', 'Aerospace transport*Air transport*Aramide fibres*Carbon fibres*Definitions*Designations*Inspection by attributes*Inspection by variables*Plastics*Reinforcing material*Rovings*Sample tests*Testing*Textile glass*Textile glass fibres*Woven glass fibres*Yarn', NULL, '2022', '12', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182985, '2249559', 'ISO 14229-3', 'Road vehicles - Unified diagnostic services (UDS) - Part 3: Unified diagnostic services on CAN implementation (UDSonCAN)', 'Active', NULL, NULL, NULL, 'ISO 15765-3:2004', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies an application profile for the implementation of unified diagnostic services (UDS) on controller area network (CAN) in road vehicles.\nUDSonCAN references ISO 14229-1 and ISO 14229-2 and specifies implementation requirements of the diagnostic services to be used for diagnostic communication on CAN.\nThis document specifies\n&mdash; additional requirements specific to the implementation of UDS on the CAN network, and;\n&mdash; specific restrictions in the implementation of UDS on the CAN network.', '149', '166.00', '259.00', 'USD', 'ISO 14229-3:2012;ISO 15765-3:2004', '1847193;1187674', '49* 43.180', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182986, '2248308', 'ISO 3518', 'Essential oil of sandalwood (Santalum album L.)', 'Active', NULL, NULL, NULL, 'ISO 3518:2002', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies certain characteristics of the essential oil of sandalwood (Santalum album L.), in order to facilitate assessment of its quality.', '77', '81.00', '127.00', 'USD', 'ISO 3518:2002', '959709', '01.040.19* 71.100* 71.100.60', 'Chemical properties*Essential oils*Materials specification*Properties*Sandalwood*Optical*Physical*Sensory', NULL, '2022', '12', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182987, '2249668', 'ISO 3749', 'Glass syringes - Determination of extractable tungsten', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies an analytical method to quantitatively determine the water-soluble amount of tungsten (W) from the inner surface of glass syringes.\nThe method can be applied to Luer cone, staked needle or Luer lock syringes.', '73', '81.00', '127.00', 'USD', NULL, NULL, '11* 11.040* 11.040.25', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182988, '2249666', 'ISO 37166', 'Smart community infrastructures - Urban data integration framework for smart city planning (SCP)', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document establishes a data framework that involves possible multi-source common data through standardized data integration and sharing mechanisms. It includes recommendations for:\n&mdash; precision, dimensions of the data, data collection, updates and storing mechanisms;\n&mdash; a data model for data integration, data standardization and data fusion approaches for heterogeneous smart city infrastructure data;\n&mdash; a data security level and sharable attributes for all involved data, principles on data sharing or exchange.\nThis document focuses on the integration and application of heterogeneous data from urban infrastructure systems, such as water, transport, energy, drainage and waste, so as to support smart city planning (SCP). It contains case studies, in Annex A, of various smart city projects.', '175', '194.00', '302.00', 'USD', NULL, NULL, '13* 13.020* 13.020.20', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182989, '2248272', 'ISO 22074-8', 'Railway infrastructure - Rail fastening systems - Part 8: Test method for vertical stiffness', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies laboratory test procedures to determine the static and low-frequency dynamic stiffness of rail pads, baseplate pads and complete rail fastening assemblies.', '73', '81.00', '127.00', 'USD', NULL, NULL, '55* 45.080', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182990, '2250809', 'ISO 23537-1', 'Requirements for sleeping bags - Part 1: Thermal, mass and dimensional requirements for sleeping bags designed for limit temperatures of  20°C and higher', 'Active', NULL, NULL, NULL, 'ISO 23537-1:2016', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the requirements, test methods and other provisions for the labelling of adult sized sleeping bags for use in sports and leisure time activities at a limit temperature &ge; 20&deg; C regarding thermal characteristics, dimensions and mass.This document describes a method for the assessment of performance in steady state conditions of a sleeping bag with regard to the protection against cold.NOTE 1  Sleeping bags without homogeneous fillings designed to provide local extra insulation in certain parts pose issues with the calibration and/or test procedure. Ongoing work continues to provide suitable means of establishing temperature ratings.This document does not apply to sleeping bags intended for specific purpose such as military use and extreme climate zone expedition. It does not apply to sleeping bags for children or babies.NOTE 2  No prediction model exists for the determination of the limiting temperatures based on the thermal resistance of the sleeping bag for children and babies. Moreover, such a model for testing cannot be developed because the necessary controlled sleep trials with children or babies in climatic chambers are, out of ethical reasons, not possible.', '149', '166.00', '259.00', 'USD', 'ISO 23537-1:2016/Amd1:2018;ISO 23537-1:2016', '2005576;1929944', '03.120.30* 97.200* 97.200.30', NULL, NULL, '2022', '32', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182991, '2249614', 'ISO 20672', 'Ships and marine technology - Rate of turn indicators', 'Active', NULL, NULL, NULL, 'ISO 20672:2007', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the construction, performance requirements, methods of testing and required test results for the rate of turn indicators required by Clause 2.9.1, Regulation 19, chapter V, SOLAS 1974 (as amended, 2000).\nIt is based upon the requirements of IMO Resolution A.526(13), and is also associated with IMO Resolution A.694 (17) and IEC 60945.\nWhere a requirement in this document is different from that in IEC&deg;60945, the requirement in this document takes precedence.\nNOTE  All requirements that are extracted from the recommendations of IMO Resolution A.526(13) on performance standards for rate of turn indicators are printed in italics and the resolution and paragraph numbers are indicated in brackets.', '48', '54.00', '84.00', 'USD', 'ISO 20672/Cor1:2008;ISO 20672:2007', '1578888;1500909', '61* 47.020* 47.020.70', 'Definitions*Design*Marine safety*Measurement*Navigation*Navigation system*Performance requirements*Ships*Ship\'s equipment*Specification (approval)*Testing*Turn indicators', NULL, '2022', '12', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182993, '2245785', 'ISO 18319-2', 'Fibre reinforced polymer (FRP) reinforcement for concrete structures - Part 2: Specifications of CFRP strips', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements for unidirectional carbon fibre-reinforced polymer (CFRP) strips as external-bonded reinforcements on the concrete substrate. This document is applicable for the CFRP strips that:\n&mdash; consist of carbon fibre and thermoset resin;\n&mdash; are manufactured by pultrusion method;\n&mdash; have a carbon fibre fraction over 60 % by volume; and\n&mdash; have a thickness within 3 mm.\nThis document specifies the methodologies to express the mechanical properties as characteristic values, appearance and dimensions, and sampling test.', '48', '54.00', '84.00', 'USD', NULL, NULL, '03.100.60* 91.080* 91.080.40* 91.100* 91.100.30* 03.080.99* 83.120', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182994, '2245822', 'ISO 24378', 'Feed machinery - Vocabulary', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document defines terms related to feed processing technology, machines and equipment widely used in feed mills.', '48', '54.00', '84.00', 'USD', NULL, NULL, '01.040.01* 65.060* 65.060.01* 01* 01.040* 01.040.65', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182995, '2245788', 'ISO 1888', 'Textile glass - Staple fibres or filaments - Determination of average diameter', 'Active', NULL, NULL, NULL, 'ISO 1888:1996', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies three test methods used for determining the average diameter (i.e. the average value of actual diameters) of staple fibres or filaments in a textile glass product.', '48', '54.00', '84.00', 'USD', 'ISO 1888:2006;ISO 1888:1996', '1275403;716336', '91* 59.100* 59.100.10', 'Cross sections*Diameter*Dimensional measurement*Measurement*Microscopic analysis*Textile fibres*Textile glass*Yarn', NULL, '2022', '12', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182996, '2245820', 'ISO 24169', 'Ships and marine technology - Fireproof watertight hatch covers', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the classification, flagging, requirements, test methods, inspection rules, markings, packaging, transportation and storage of fireproof watertight hatch covers installed on decks (hereafter referred to as “hatch covers”).\nThis document applies to the design, manufacture and acceptance of fireproof watertight hatch covers installed on decks of ships where anticipated water pressure by wave is up to 10 m.', '77', '81.00', '127.00', 'USD', NULL, NULL, '61* 47.020* 47.020.10', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(182997, '2245818', 'ISO 23555-2', 'Gas pressure safety and control devices for use in gas transmission, distribution and installations for inlet pressures up to and including 10 MPa - Part 2: Gas pressure regulator', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies safety, constructional, performance, testing and documentation requirements for gas pressure regulators for use in gas transmission and distribution installations (hereafter referred to as regulators).\nThis document is applicable to regulators with operating pressures greater than 500 kPa and up to and including 10 MPa (100 bar) and nominal diameters up to DN 400 for use with fuel gases as natural gas, manufactured gas, biomethane or liquefied petroleum gas (LPG).\nThis document is applicable to:\n&mdash; test methods which are intended for product type test, routine tests and product surveillance tests;\n&mdash; regulators which use the pipeline gas as a source of control energy unassisted by any external power source;\n&mdash; regulators integrating on the same body a second regulator, used as monitor, complying with the requirements in this document;\n&mdash; regulators integrating a safety shut off device (SSD) according to ISO 23555-3;\n&mdash; regulators incorporating a creep (venting) relief device and/or a vent limiter complying with the requirements in this document.\nThis document does not apply to:\n&mdash; regulators upstream from/on/in domestic gas consuming appliances which are installed downstream of domestic gas meters;\n&mdash; regulators designed to be incorporated into pressure control systems used in service lines (pipework from the main pipework in a gas infrastructure to the point of delivery of the gas) with declared volumetric flow rate  200 m3/h at normal conditions and declared inlet pressure  500 kPa (5 bar);\n&mdash; industrial process control valves, such as IEC 60534 (all parts);\n&mdash; regulators used in aggressive/sour gas environments (gas environments containing water and H2S are considered sour) or severely corrosive conditions;\n&mdash; regulators in service conditions with renewables (e.g. H2NG with hydrogen more than 10 %) and/or waste gases (e.g. biogas etc.), if additional information is not provided (e. g. contaminant, liquid, etc.).', '237', '250.00', '391.00', 'USD', NULL, NULL, '03.100.60* 91.140* 91.140.40* 01* 23.060* 23.060.40', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183005, '2247210', 'ISO 4784', 'Building and civil engineering sealants - Determination of surface cure time', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'The document specifies a method for the determination of the surface cure of one- and multi-component sealants.', '48', '54.00', '84.00', 'USD', NULL, NULL, '03.100.60* 91.100* 91.100.50', NULL, NULL, '2022', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183036, '2247273', 'ISO 9177-3', 'Mechanical pencils for technical drawings - Part 3: Black leads - Bending strengths of HB leads', 'Active', '', '', '', 'ISO 9177-3:1994', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies bending strengths and a test method for black leads of HB hardness degree used for mechanical pencils for technical drawings.', '48.000000', '54.000000', '84.000000', 'USD', 'ISO 9177-3:1994', '228852', '01* 01.100* 01.100.40* 03.120.30* 97.180', 'Bend testing*Bending stiffness*Bending strength*Crayons*Definitions*Degree of hardness*Designations*Determination*Dimensions*Drawing office equipment*Drawing system*Engineering drawings*Graphite*Hardness*HB*Leads (pencils)*Mechanical pencils*Pen refills*Pencils*Products documentation*Propelling pencils*Specifications*Stationery*Strength of materials*Testing*Mines*Flexural strength*Obturating points*Slugs', '', '2024-11-19', '12', '', '', '', '0', '0', 0, 1, 1, 0, 1, 1),
(183037, '2245814', 'ISO 23472-4', 'Foundry machinery - Vocabulary - Part 4: Abrasive blasting machines and other equipment related to cleaning and finishing for casting', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document defines a set of terms and definitions of abrasive blasting machines and other equipment related to cleaning and finishing for casting in foundry machinery.\nIt applies to standard development in the foundry machinery field, technical documentation, related scientific and technical publications, etc.', '48.000000', '54.000000', '84.000000', 'USD', '', '', '01* 01.040* 01.040.77* 01.040.25* 03.060* 77.180', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183038, '2245858', 'ISO 4657', 'Assessment specification of coalbed methane resources', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies the objectives, tasks, work processes, classification, report preparation and acceptance of coalbed methane (CBM) resource evaluation.', '73.000000', '81.000000', '127.000000', 'USD', '', '', '01.040.23* 73.020', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183039, '2245711', 'ISO 11661', 'Mobile cranes - Presentation of rated capacity charts', 'Active', '', '', '', 'ISO 11661:1998', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies a standard presentation or format for mobile crane rated capacities on rated capacity charts.INSERT INTO `wp_tecbook_standards` (`id`, `idProduct`, `referenceNumber`, `standardTitle`, `status`, `referencedStandards`, `referencingStandards`, `equivalentStandards`, `replace`, `replacedBy`, `standardby`, `languages`, `fullDescription`, `ebookPrice`, `printPrice`, `bothPrice`, `currency`, `historicalEditions`, `documentHistoryProductId`, `icsCode`, `keyword`, `identicalStandards`, `publishedDate`, `pages`, `byTechnology`, `byIndustry`, `previewPath`, `coverPath`, `fullPath`, `deleted`, `newArrival`, `bestSellers`, `isFree`, `specialOffer`, `featured`) VALUES
(183055, '2244624', 'ISO 23646', 'Soil quality - Determination of organochlorine pesticides by gas chromatography with mass selective detection (GC-MS) and gas chromatography with electron-capture detection (GC-ECD)', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies a method for quantitative determination of organochlorine pesticides (OCPs) and semi-volatile chlorobenzenes in soil and sediment, using GC-MS and GC-ECD.\nThe limit of detection and the limit of application depends on the determinants, the sample intake, the equipment used, the quality of chemicals used for the extraction of the sample and the clean-up of the extract.\nUnder the conditions specified in this document, lower limits of application from 1 g/kg (expressed as dry matter) for soils to 10  g/kg (expressed as dry matter) for sediments can be achieved. The necessity to achieve these lower limits of application depends on the analyses order and the current limit values.\nSoils and sediments can differ in properties as well as in the expected contamination levels of OCPs and the presence of interfering substances. These differences make it impossible to describe one general procedure. Based on the properties of the samples, this document contains decision tables regarding drying-, extraction- and clean-up procedures. This method is performance based. The method can be modified if all performance criteria given in this method are met.\nThe method can be applied to the analysis of other chlorinated compounds not specified in the scope in cases where suitability has been proven by proper in-house validation experiments.\nNOTE  The validation data are shown in Annex A. This document is validated only for -HCH, -HCH, -HCH, -HCH, o,p -DDE, p,p -DDE, o,p -DDD, p,p -DDD, o,p -DDT and p,p -DDT. For sediments, data are displayed measured using an ECD detection. The comparability of ECD and MS data in terms of the approach of this document was demonstrated on additional matrices.', '175.000000', '194.000000', '302.000000', 'USD', 'ISO 10382:2002', '1039124', '13* 13.080* 13.080.10', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183056, '2244562', 'ISO 14968', 'Paper and board - Cut-size office paper - Measurement of curl in a pack of sheets', 'Active', '', '', '', 'ISO 14968:1999', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies a method for the measurement of curl in cut-size office papers. The test method is typically used in evaluating papers of the type described in ISO 216.\nThis method is limited to papers with a maximum dimension of 300 mm in both directions.\nThe measurement can be made on papers as received, after conditioning, or after processing in a copier or printing device.', '73.000000', '81.000000', '127.000000', 'USD', 'ISO 14968:1999', '32095', '03.100.01* 85.060', 'Board (paper)*Curl*Curling*Definitions*Measuring techniques*Paper*Physical testing*Prominences*Test procedures*Testing', '', '2024-11-19', '18', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183057, '2522034', 'ISO 10303-242', 'Industrial automation systems and integration - Product data representation and exchange - Part 242: Application protocol: Managed model-based 3D engineering', 'Active', '', '', '', 'ISO 10303-242:2014', '', 'ISO - International Organization for Standardization', 'English', 'ISO 10303-242 specifies the application protocol for Managed model based 3d engineering.&nbsp;&nbsp;The following are within the scope of ISO 10303-242:• products of automotive, aerospace and other mechanical manufacturers and of their suppliers, including parts, assemblies of parts, tools, assemblies of tools, and raw materials;• engineering and product data for the purpose of long-term archiving and retrieval; •product data management• breakdown data representing a parent-child structures, such as functional, physical, system or zonal breakdowns. A breakdown is made of breakdown element;• product definition data and configuration control data for managing large numbers of variants of products during the design phase;• data describing the changes that have occurred during the design phase, including tracking of the versions of a product and of the data related to the documentation of the change process;• delta change: data describing the exchange of differences with respect to a set of data previously sent;• identification of standard parts, based on international, national, or industrial standards;• release and approval data for product data;• data that identify the supplier of a product and related contract information;• properties of parts or of tools;• references to product documentation represented in a format other than those specified by ISO 10303;• product manufacturing information, covering the design and manufacturing planning phase;• identification of physically realized parts or of tools, including assembly of physically realized products and recording of test results.• process planning• process plan information describing the relationships between parts and the tools used to manufacture them and to manage the relationships between intermediate stages of part or tool development.• mechanical design• different types of geometry models, including:• 2D- and 3D-wireframe geometry model;• geometrically bounded surface geometry model;• topologically bounded surface geometry model;• faceted-boundary geometry model;• boundary geometry model;• compound shape geometry model;• constructive solid geometry model;• parametric and constrained geometry model;• 2D-sketch model;• 3D tessellated geometry model;• 3D scan data;• curved triangles.• representation of the shape of parts or tools that is a combination of two or more of different types of geometry models;• data that pertains to the presentation of the shape of the product;• representation of portions of the shape of a part or a tool by manufacturing features;• data defining surface conditions;• dimensional and geometrical tolerance data;• quality criteria and inspection results of given three dimensional product shape data;• product documentation as annotated 3D models and as drawings.• message• data that identify a message and an envelope.• interface• data representing the interfaces with version management mechanism and the definition of connection with connectors.• mating• data representing the detailed assembly information on how the involved part occurrences are mated together and which constraints apply.• kinematics• simulation data for the description of kinematic structures and motion.• analysis management• data representing an analysis, managed in versions and the link to the result of the analysis.• composite design• definition of composite structural parts;• the association of the constituents of composite and metallic parts with the constituent shape model;• the depiction of composite laminate tables describing the material, stacking sequence and ply orientation;• constituents of the composite or a portion of the composite with a defined shape;• the identification of material specifications from internal and external sources and their properties for a specific operating environment.• electrical harness assembly design• electrical wire harnesses design;• physical electrical harness model for design and construction;• electrical connectivity information in multilevel assemblies;• wire and cable list data;• definition of wire, cable and connector features.• additive manufacturing part design• build information.• requirements management• verification and validation.', '0.000000', '0.000000', '0.000000', 'USD', 'ISO 10303-242:2020;ISO 10303-242:2014', '2113560;2026296', '07* 25.040* 25.040.40', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183058, '2244549', 'ISO 13472-1', 'Acoustics - Measurement of sound absorption properties of road surfaces in situ - Part 1: Extended surface method', 'Active', NULL, NULL, NULL, 'ISO 13472-1:2002', NULL, 'ISO - International Organization for Standardization', 'English', 'This document describes a test method for measuring in situ the sound absorption coefficient of road surfaces as a function of frequency in the range from 250 Hz to 4 kHz.\nNormal incidence is assumed. However, the test method can be applied at oblique incidence although with some limitations (see Annex F). The test method is intended for the following applications:\n&mdash; determination of the sound absorption properties of road surfaces in actual use;\n&mdash; comparison of sound absorption design specifications of road surfaces with actual performance data of the surface after completion of the construction work.\nThe complex reflection factor can also be determined by this method.', '175', '194.00', '302.00', 'USD', 'ISO 13472-1:2002', '1031040', '03.120* 93.080* 93.080.20* 17* 17.140* 17.140.30', 'Absorption*Acoustic measurement*Acoustic testing*Acoustics*Definitions*Evaluations*Frequencies*In situ*Measurement*Measuring techniques*Pavements (roads)*Properties*Road superstructure*Road surfaces*Sound absorption*Sound absorption coefficient*Surfaces*Testing', NULL, '2022', '36', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183059, '2244600', 'ISO 20766-16', 'Road vehicles - Liquefied petroleum gas (LPG) fuel system components - Part 16: Injectors and gas mixing device/fuel rail', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies general requirements for the injectors and gas mixing device/fuel rail, components of liquefied petroleum gas fuel, intended for use on the types of motor vehicles as defined in ISO 3833. It also provides general design principles and specifies requirements for instructions and marking.\nThis document is applicable to vehicles (mono-fuel, bi-fuel or dual-fuel applications) using gaseous fuels in accordance with ISO 9162. It is not applicable to the following:\na) fuel containers;\nb) stationary gas engines;\nc) container mounting hardware;\nd) electronic fuel management;\ne) refuelling receptacles.\nIt is recognized that miscellaneous components not specifically addressed herein can be examined for compliance with the criteria of any applicable part of the ISO 20766 series, including testing to the appropriate functional tests.\nAll references to pressure in this document are considered gauge pressures unless otherwise specified.\nThis document applies to devices which have a service pressure in the range of 110 kPa (butane rich at 20 &deg;C) and 840 kPa (propane at 20 &deg;C), hereinafter referred to in this document. Other service pressures can be accommodated by adjusting the pressure by the appropriate factor (ratio).', '48.000000', '54.000000', '84.000000', 'USD', '', '', '49* 43.060* 43.060.40', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183060, '2244619', 'ISO 23155', 'Interpreting services - Conference interpreting - Requirements and recommendations', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements and recommendations for the provision of conference interpreting services. It is primarily addressed to conference interpreters and conference interpreting service providers. It also serves as reference for users of conference interpreting services.', '175.000000', '194.000000', '302.000000', 'USD', '', '', '01* 01.020* 03* 03.080* 03.080.99', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183061, '2244598', 'ISO 20766-13', 'Road vehicles - Liquefied petroleum gas (LPG) fuel system components - Part 13: Multivalve', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies general requirements for the multivalve component of liquefied petroleum gas fuel, intended for use on the types of motor vehicles as defined in ISO 3833. It also provides general design principles and specifies requirements for instructions and marking.\nThis document is applicable to vehicles (mono-fuel, bi-fuel or dual-fuel applications) using gaseous fuels in accordance with ISO 9162. It is not applicable to the following:\na) fuel containers;\nb) stationary gas engines;\nc) container mounting hardware;\nd) electronic fuel management;\ne) refuelling receptacles.\nIt is recognized that miscellaneous components not specifically addressed herein can be examined for compliance with the criteria of any applicable part of the ISO 20766 series, including testing to the appropriate functional tests.\nAll references to pressure in this document are considered gauge pressures unless otherwise specified.\nThis document applies to devices which have a service pressure in the range of 110 kPa (butane rich at 20 &deg;C) and 840 kPa (propane at 20 &deg;C), hereinafter referred to in this document. Other service pressures can be accommodated by adjusting the pressure by the appropriate factor (ratio).', '48.000000', '54.000000', '84.000000', 'USD', '', '', '49* 43.060* 43.060.40', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183062, '2244657', 'ISO 4384-2', 'Plain bearings - Hardness testing of bearing metals - Part 2: Solid materials', 'Active', '', '', '', 'ISO 4384-2:1982', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies parameters for the hardness testing of solid materials for plain bearings made from cast and wrought copper and aluminium alloys by machining and forming, of their wrought products and ingots, and of tin-based ingots. This document is a supplement to existing International Standards on hardness testing and, therefore, includes only the extensions and restrictions for observation compared to those publications.\nOwing to the heterogeneous structural composition of the majority of these bearing metals, a Brinell test is used.', '48.000000', '54.000000', '84.000000', 'USD', 'ISO 4384-2:2011;ISO 4384-2:1982', '1798034;718105', '21* 21.100* 21.100.10', 'Alloys*Aluminium*Bearing alloys*Bearing metal*Copper*Hardness*Hardness measurement*Ingots*Lead*Materials*Plain bearings*Strain*Testing*Tin', '', '2024-11-19', '8', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183063, '2244599', 'ISO 20766-14', 'Road vehicles - Liquefied petroleum gas (LPG) fuel system components - Part 14: Vaporizer/pressure regulator', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies general requirements for the vaporizer/pressure regulator, a component of liquefied petroleum gas fuel, intended for use on the types of motor vehicles as defined in ISO 3833. It also provides general design principles and specifies requirements for instructions and marking.\nThis document is applicable to vehicles (mono-fuel, bi-fuel or dual-fuel applications) using gaseous fuels in accordance with ISO 9162. It is not applicable to the following:\na) fuel containers;\nb) stationary gas engines;\nc) container mounting hardware;\nd) electronic fuel management;\ne) refuelling receptacles.\nIt is recognized that miscellaneous components not specifically addressed herein can be examined for compliance with the criteria of any applicable part of the ISO 20766 series, including testing to the appropriate functional tests.\nAll references to pressure in this document are considered gauge pressures unless otherwise specified.\nThis document applies to devices which have a service pressure in the range of 110&deg;kPa (butane rich at 20 &deg;C) and 840 kPa (propane at 20 &deg;C), hereinafter referred to in this document. Other service pressures can be accommodated by adjusting the pressure by the appropriate factor (ratio).', '48.000000', '54.000000', '84.000000', 'USD', '', '', '49* 43.060* 43.060.40', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183064, '2244612', 'ISO 21815-1', 'Earth-moving machinery - Collision warning and avoidance - Part 1: General requirements', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document provides terminology and general guidance on the principles of collision warning and collision avoidance systems for:\n&mdash; earth moving machinery as defined in ISO 6165,\n&mdash; mobile underground mining machinery as defined in ISO 19296, and\n&mdash; road construction machinery as defined in ISO 22242.\nThis document provides general requirements for detection of objects, warnings to the operator, automatic intervention control to avoid collision, and test procedures. It is intended to be used in conjunction with the other parts of the ISO 21815 series, which provide detailed guidance and requirements for collision warning and collision avoidance systems and determining risk areas and risk levels. The specific requirements and definitions for particular types of machines are defined in the use case parts of the ISO 21815 series.\nThis document covers collision avoidance by speed reduction or motion inhibit: it does not cover avoidance by automatic manoeuvring (e.g. steering) away from the intended object.\nThe systems described in this document are only intended to assist the operator of the machine. The responsibility for safe operation of the machine remains with the operator of the machine.\nThis document is not applicable to collision warning and collision avoidance systems installed to the machine before the date of its publication.', '111.000000', '124.000000', '191.000000', 'USD', '', '', '53.100', '', '', '2024-11-19', '26', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183065, '2244621', 'ISO 23296', 'Metallic materials - Fatigue testing - Force controlled thermo-mechanical fatigue testing method', 'Active', '', '', '', '', '', 'ISO - International Organization for Standardization', 'English', 'This document applies to stress and/or force-controlled thermo-mechanical fatigue (TMF) testing. Both forms of control, force or stress, can be applied according to this document. This document describes the equipment, specimen preparation, and presentation of the test results in order to determine TMF properties.', '175.000000', '175.000000', '289.000000', 'USD', '', '', '03.060* 77.040* 77.040.10', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183066, '2242411', 'ISO 3501', 'Plastics piping systems - Mechanical joints between fittings and pressure pipes - Test method for resistance to pull-out under constant longitudinal force', 'Active', '', '', '', 'ISO 3501:1976', '', 'ISO - International Organization for Standardization', 'English', 'This document specifies a method for checking the ability of assembled uniaxial joints between fittings and plastic pressure pipes to withstand longitudinal tensile stresses. The test applies regardless of the design and material of the fitting used for jointing plastics pipe.', '48.000000', '54.000000', '84.000000', 'USD', 'ISO 3501:2015;ISO 3501:1976', '1892954;717477', '01* 23.040* 23.040.60', '', '', '2024-11-19', '0', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(183067, '2243247', 'ISO 21920-2', 'Geometrical product specifications (GPS) - Surface texture: Profile - Part 2: Terms, definitions and surface texture parameters', 'Active', NULL, NULL, NULL, 'ISO 12085:1996', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies terms, definitions and parameters for the determination of surface texture by profile methods.INSERT INTO `wp_tecbook_standards` (`id`, `idProduct`, `referenceNumber`, `standardTitle`, `status`, `referencedStandards`, `referencingStandards`, `equivalentStandards`, `replace`, `replacedBy`, `standardby`, `languages`, `fullDescription`, `ebookPrice`, `printPrice`, `bothPrice`, `currency`, `historicalEditions`, `documentHistoryProductId`, `icsCode`, `keyword`, `identicalStandards`, `publishedDate`, `pages`, `byTechnology`, `byIndustry`, `previewPath`, `coverPath`, `fullPath`, `deleted`, `newArrival`, `bestSellers`, `isFree`, `specialOffer`, `featured`) VALUES
(183298, '2232027', 'ISO 17721-2', 'Quantitative determination of antibacterial activity of ceramic tile surfaces - Test methods - Part 2: Ceramic tile surfaces with incorporated photocatalytic antibacterial agents', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies test methods for evaluating the antibacterial activity of glazed and unglazed ceramic tile surfaces with incorporated photocatalytic antibacterial agents.Secondary effects on ceramic tile surfaces due to photocatalytic antibacterial treatments, such as changes in chemical resistance, stain resistance or small colour differences, are not covered by this document. For chemical resistance refer to ISO 10545-13, for stain resistance refer to ISO 10545-14 and for colour differences refer to ISO 10545-16.Other types of performance of photocatalytic ceramics, i.e. decomposition of water contaminants, self-cleaning, antifogging and air purification, are not covered by this document. It is also not intended to be used to evaluate ceramic surfaces that have been treated with topical disinfectants or agents that can offer residual activity for limited periods.Any results obtained with this document will always refer to this document and the conditions used. Results obtained with this document indicate antibacterial activity under the specified experimental conditions used herein, and do not reflect activity under other circumstances where a variety of factors, such as temperature, humidity, different bacterial species, nutrient conditions, etc., are considered.', '73', '81.00', '127.00', 'USD', NULL, NULL, '03.100.60* 91.100* 91.100.23', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183308, '2232026', 'ISO 17721-1', 'Quantitative determination of antibacterial activity of ceramic tile surfaces - Test methods - Part 1: Ceramic tile surfaces with incorporated antibacterial agents', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies test methods for evaluating the antibacterial activity of glazed and unglazed ceramic tile surfaces with incorporated antibacterial agents.Secondary effects on ceramic tile surfaces due to antibacterial treatments, such as changes in chemical resistance, stain resistance or small colour differences, are not covered by this document. For chemical resistance refer to ISO 10545-13, for stain resistance refer to ISO 10545-14 and for colour differences refer to ISO 10545-16.Any results obtained with this document will always refer to this document and the conditions used. Results obtained with this document indicate antibacterial activity under the specified experimental conditions used herein, and do not reflect activity under other circumstances where a variety of factors, such as temperature, humidity, different bacterial species, nutrient conditions, etc., are considered.', '73', '81.00', '127.00', 'USD', NULL, NULL, '03.100.60* 91.100* 91.100.23', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183325, '2228011', 'ISO 18441', 'Space data and information transfer systems - Space link extension - Application program interface for transfer services - Core specification', 'Active', NULL, NULL, NULL, 'ISO 18441:2013', NULL, 'ISO - International Organization for Standardization', 'English', 'This document defines the Application Program Interface in terms of:the components that provide the services of the API;the functionality provided by each of the components;the interfaces provided by each of the components; andthe externally visible behavior associated with the interfaces exported by the components.It does not specify:individual implementations or products;the internal design of the components; andthe technology used for communications.This document defines those aspects of the Application Program Interface, which are common for all SLE service types or for a subset of the SLE service types, e.g., all return link services or all forward link services.&deg; It also defines a framework for specification of service type-specific elements of the API.&deg; Service-specific aspects of the API are defined by supplemental Recommended Practice documents for SLE return link services (references [10], [11], and [12]) and SLE forward link services (references [13] and [14]).This document for the Application Program Interface responds to the requirements imposed on such an API by the CCSDS SLE transfer service Recommended Standards that were available when this document was released.', '250', '278.00', '434.00', 'USD', 'ISO 18441:2016;ISO 18441:2013', '1935486;1859691', '67* 49.140', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183372, '2228016', 'ISO 19095-6', 'Plastics - Evaluation of the adhesion interface performance in plastic-metal assemblies - Part 6: Accelerated degradation test', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the environmental conditions to evaluate the accelerated degradation for the adhesion interface performance in plastic-metal assemblies.', '73', '81.00', '127.00', 'USD', NULL, NULL, '03.080.99* 83.180', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183386, '2229120', 'ISO 23157', 'Determination of the silanol group content on the surface of fumed silica - Reaction gas chromatographic method', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies a method for the determination of the silanol group content on the surface of fumed silica by reaction gas chromatographic method.', '73', '81.00', '127.00', 'USD', NULL, NULL, '03.100.20* 87.060* 87.060.10', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183387, '2228052', 'ISO 23223', 'Alpine ski boots with improved walking soles - Interface with alpine ski-bindings – Requirements and test methods', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies requirements, test methods and marking for alpine ski-boots with improved walking soles that are used with systems of alpine ski-bindings for improved walking soles with attachment at the boot front and boot rear, the proper release function of which depends on the dimensions and design of the interfaces.Alpine ski boots with improved walking soles are intended to a better walkability without affecting the function of the alpine ski binding designed for improved walking soles.This document is applicable to ski-boots of sizes 15,0 and larger (Types&deg;A (Adults) and C (Children)) in the Mondo point system (see Annex&deg;A).', '200', '223.00', '347.00', 'USD', NULL, NULL, '03.120.30* 97.220* 97.220.20', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183399, '2226422', 'ISO 28199-2', 'Paints and varnishes - Evaluation of properties of coating systems related to the spray application process - Part 2: Colour stability, process hiding power, re-dissolving, overspray absorption, wetting, surface texture and mottling', 'Active', NULL, NULL, NULL, 'ISO 28199-2:2009', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies methods for the determination of colour stability/colour evaluation, process hiding power, re-dissolving, overspray absorption, wetting, surface texture and mottling of coating materials applied to a test panel under defined conditions, using spray application process.', '73', '81.00', '127.00', 'USD', 'ISO 28199-2:2009', '1640628', '03.100.20* 87.040', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183404, '2226381', 'ISO 21919-2', 'Physical device control - Interfaces for automated machine tending - Part 2: Safety and control interface', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document deals with the safety interface and control interface. It allocates signals to a conformance class and/or conformance option. It describes the detailed functions of each signal, describes and displays the timing interactions between signals in flow charts and shows examples for safety matrices and safety-related functional relationships.This document defines three conformance classes and dedicated conformance options. Classes and options consist of a number of signals to:&deg;&deg;&deg;&deg;&deg;&deg; allow a flexible adaptation of the interface(s) to a project-specific scope of functions and simultaneously;&deg;&deg;&deg;&deg;&deg;&deg; tie sets of signals tight enough to avoid unnecessary coordination efforts between suppliers of the machine tending systems and machines.', '200', '223.00', '347.00', 'USD', NULL, NULL, '07* 25.040* 25.040.20', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183405, '2226355', 'ISO 19818-1', 'Eye and face protection - Protection against laser radiation - Part 1: Requirements and test methods', 'Active', NULL, NULL, NULL, 'ISO 6161:1981', NULL, 'ISO - International Organization for Standardization', 'English', 'This document is applicable to protectors intended to provide protection against accidental exposure to laser radiation within the wavelength range 180&deg;nm to 1&deg;mm. It specifies the requirements, test methods and marking. Protectors intended for adjustment work on lasers are included in the scope of this document and are marked in the same way as other protectors, but selection of appropriate eyewear for a specific application is a choice of the user. Laser protective filters used as viewing windows in laser equipment machinery or incorporated into optical instruments such as operating microscopes and loupes that may be used for deliberate viewing of laser radiation as part of their function are outside the scope of this document.Laser radiation in the wavelength range below 180&deg;nm is absorbed in air, therefore eye and face protection should not be required.This document is applicable to devices intended for patient protection during medical laser procedures except for treatment in the periorbital area. Guidance on eye protectors for patients (including those used for periorbital treatment) is given in ISO/TR&deg;22463.', '149', '166.00', '259.00', 'USD', 'ISO 6161:1981', '719134', '13* 13.340* 13.340.20', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183476, '2224079', 'ISO 17215-3', 'Road vehicles - Video communication interface for cameras (VCIC) - Part 3: Camera message dictionary', 'Active', NULL, NULL, NULL, 'ISO 17215-3:2014', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the standardized camera messages and data types used by a VCIC camera (OSI layer 7).Applications hosted on ECUs want to communicate with one or more cameras (e.g. \"Ask camera for parameters.\"). If the applications can use standardized services supported by the cameras (API layer 7), the development of a vision application is independent on the camera used. The services can be implemented by general libraries.The definition of streaming data is not an issue of this API.', '200', '223.00', '347.00', 'USD', 'ISO 17215-3:2014', '1877358', '49* 43.040* 43.040.15', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183479, '2226342', 'ISO 18541-3', 'Road vehicles - Standardized access to automotive repair and maintenance information (RMI) - Part 3: Functional user interface requirements', 'Active', NULL, NULL, NULL, 'ISO 18541-3:2014', NULL, 'ISO - International Organization for Standardization', 'English', 'This document includes functional user interface requirements related to automotive repair and maintenance information (RMI) systems in order to standardize access to RMI for independent operators.This document specifies all functional user interface requirements related to a vehicle manufacturer\'s RMI system. These requirements will reflect the deriving needs from the use cases as specified in ISO&deg;18541&deg;&deg;&deg;1.', '111', '124.00', '191.00', 'USD', 'ISO 18541-3:2014', '1884556', '49* 43.040* 43.040.15* 43.180', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183493, '2226353', 'ISO 19318', 'Surface chemical analysis - X-ray photoelectron spectroscopy - Reporting of methods used for charge control and charge correction', 'Active', NULL, NULL, NULL, 'ISO 19318:2004', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the minimum amount of information spectroscopy to be reported with the analytical results to describe the methods of charge control and charge correction in measurements of core-level binding energies for insulating specimens by X&deg;&deg;ray photoelectron. It also provides methods for charge control and for charge correction in the measurement of binding energies.', '111', '124.00', '191.00', 'USD', 'ISO 19318:2004', '1163365', '01.040.19* 71.040* 71.040.40', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183497, '2226505', 'ISO 7319', 'Aerospace - Fluid systems - Interface of 24° cone metric couplings', 'Active', NULL, NULL, NULL, 'ISO 7319:1992', NULL, 'ISO - International Organization for Standardization', 'English', 'This document defines the geometry of the interface of removable 24&deg; cone couplings for fluid systems in aircraft. The connection with the pipe of each one of the connecting elements can be of different design.This document specifies the dimensions which allow the interchangeability of the male and female elements and of the nut used for the connection.The dimensions define the maximum volume of the male fitting.', '48', '54.00', '84.00', 'USD', 'ISO 7319:1992', '29309', '67* 49.080', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183499, '2223957', 'ISO 23150', 'Road vehicles - Data communication between sensors and data fusion unit for automated driving functions - Logical interface', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document is applicable to road vehicles with automated driving functions. The document specifies the logical interface between in-vehicle environmental perception sensors (for example, radar, lidar, camera, ultrasonic) and the fusion unit which generates a surround model and interprets the scene around the vehicle based on the sensor data. The interface is described in a modular and semantic representation and provides information on object level (for example, potentially moving objects, road objects, static objects) as well as information on feature and detection levels based on sensor technology specific information. Further supportive information is available.This document does not provide electrical and mechanical interface specifications. Raw data interfaces are also excluded.', '250', '263.00', '434.00', 'USD', 'ISO 23150:2023', '2566770', '49* 43.040* 43.040.15', NULL, NULL, '2021', '234', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183537, '2222437', 'ISO 20684-1', 'Intelligent transport systems - Roadside modules SNMP data interface - Part 1: Overview', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'Field devices are a key component in intelligent transport systems (ITS). Field devices include traffic signals, message signs, weather stations, traffic sensors, roadside equipment for connected ITS (C-ITS) environments, etc.The ISO&deg;&deg;20684 series defines data that can be used when field devices need to exchange information with other external entities (called &deg;&deg;&deg;managers&deg;&deg;&deg; in this document, even if they are other field devices). Field devices can be quite complex, necessitating the standardization of many data concepts for exchange. As such, the ISO&deg;&deg;20684 series is divided into several individual parts. This document (Part&deg;&deg;1) introduces the ISO&deg;&deg;20684 series and provides normative content that applies to all subsequent parts.', '149', '166.00', '259.00', 'USD', NULL, NULL, '03* 03.220* 03.220.20* 31* 35.240* 35.240.60', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183545, '2222352', 'ISO 13209-4', 'Road vehicles - Open Test sequence eXchange format (OTX) - Part 4: Expanded extensions interface definition', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document defines the Open Test sequence eXchange (OTX) additional extension requirements and data model specifications.The requirements are derived from the use cases described in ISO&deg;&deg;13209-1. They are listed in Clause&deg;&deg;4.The data model specification aims at an exhaustive definition of all features of the OTX extensions which have been implemented to satisfy the requirements. This document establishes rules for the syntactical entities of each extension. Each of these syntactical entities is accompanied by semantic rules which determine how OTX documents containing extension features are to be interpreted. The syntax rules are provided by UML class diagrams and XML schemas, whereas the semantics are given by UML activity diagrams and prose definitions.', '250', '278.00', '434.00', 'USD', NULL, NULL, '49* 43.040* 43.040.15* 43.180', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183565, '2222438', 'ISO 20730-1', 'Road vehicles - Vehicle interface for electronic Periodic Technical Inspection (ePTI) - Part 1: Application and communication requirements', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document is applicable to road vehicles, where the electronic vehicle interface is used to perform a test method that is part of a periodic technical inspection (ePTI).\nThis document describes use cases and specifies technical requirements in order to support the ePTIrelevant vehicle safety system(s) checks during the periodic technical inspection via the electronic interface. This document references the ISO 14229 series, the unified diagnostic services implemented on diagnostic communication over controller area network (DoCAN) and the Internet protocol (DoIP) along with the required provision of data definitions.\nThe technical requirements of diagnostic services and data definitions of emissions-related systems are specified in other International Standards, for example, ISO 15031 and ISO 27145. Other environmental systems\' ePTI use cases and technical requirements can be considered in the future.', '200', '223.00', '347.00', 'USD', NULL, NULL, '49* 43.180', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183570, '2222416', 'ISO 18114', 'Surface chemical analysis - Secondary-ion mass spectrometry - Determination of relative sensitivity factors from ion-implanted reference materials', 'Active', NULL, NULL, NULL, 'ISO 18114:2003', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies a method of determining relative sensitivity factors (RSFs) for secondary-ion mass spectrometry (SIMS) from ion-implanted reference materials.The method is applicable to specimens in which the matrix is of uniform chemical composition, and in which the peak concentration of the implanted species does not exceed one atomic percent.', '48', '54.00', '84.00', 'USD', 'ISO 18114:2003', '1086834', '01.040.19* 71.040* 71.040.40', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183580, '2217663', 'ISO 20579-3', 'Surface chemical analysis - Sample handling, preparation and mounting - Part 3: Biomaterials', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document gives guidance on methods of handling, mounting and surface treatment for a biomaterial specimen prior to surface chemical analysis. It is intended for the analyst as an aid in understanding the specialized specimen-handling conditions required for analyses by the following techniques:&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg; X-ray photoelectron spectroscopy (XPS or ESCA);&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg; secondary ion mass spectrometry (SIMS);&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg; Auger electron spectroscopy (AES).The protocols presented are also applicable to other analytical techniques that are sensitive to surface composition, such as:&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg; attenuated total reflectance -Fourier transform infrared spectroscopy (ATR-FTIR);&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg; total reflection X-ray fluorescence (TXRF);&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg;&deg; ultraviolet photoelectron spectroscopy (UPS).The influence of vacuum conditions applied and the issue of contamination before and after analysis and implantation, as well as issues related to contamination during analysis, are addressed. Biomaterials covered here are hard and soft specimens such as metals, ceramics, scaffolds and polymers.This document does not cover such viable biological materials as cells, tissues and living organisms. Other related topics not covered in this document include: preparation of specimens for electron or light microscopy.', '73', '81.00', '127.00', 'USD', NULL, NULL, '01.040.19* 71.040* 71.040.40', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183632, '2214710', 'ISO 14907-2', 'Electronic fee collection - Test procedures for user and fixed equipment - Part 2: Conformance test for the on-board unit application interface', 'Active', NULL, NULL, NULL, 'ISO/TS 14907-2:2006', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 14907-2:2021 describes tests which verify on-board unit (OBU) conformance of functions and data structures implementations, as defined in the implementation conformance statement (ICS) based on ISO 14906 for EFC applications.This document defines tests for assessing OBU conformance in terms of :&mdash; basic dedicated short-range communication (DSRC) L7 functionality,&mdash; EFC application functions,&mdash; EFC attributes (i.e. EFC application information),&mdash; the addressing procedures of EFC attributes and (hardware) components,&mdash; the EFC transaction model, which defines the common elements and steps of any EFC transaction, and&mdash; the behaviour of the interface so as to support interoperability on an EFC-DSRC application interface level.After the tests of isolated data items and functions (C.2 to C.4), an example is given for testing a complete EFC transaction (C.3). Although this document defines examples of test cases for DSRC and EFC functionality (see Annex C), it does not intend to specify a complete test suite for a certain implementation. To compose a test suite for a specific EFC implementation, the test cases can be modified and new test cases can be defined and added in order for the conformance test suite to be complete. It can be useful to consider the following when defining a complete test suite:&mdash; small range: &quot;exhaustive testing&quot; of critical interoperability/compatibility features,&mdash; large range: testing of boundaries and random values, and&mdash; composite types: testing of individual items in sequence or parallel.This document does not define tests which assess:&mdash; performance,&mdash; robustness, and&mdash; reliability of an implementation.NOTE 1 ISO 14907-1 defines test procedures that are aimed at assessing performance, robustness and reliability of EFC equipment and systems.NOTE 2 The ISO/IEC 10373 series defines test methods for proximity, vicinity, integrated circuit(s) cards and related devices that can be relevant for OBUs which support such cards.Annex D provides an informative overview of Japanese on-board equipment (OBE) conformance tests which are based on the ISO 14907 series, in order to illustrate how these can be applied in practice.', '225', '250.00', '391.00', 'USD', 'ISO/TS 14907-2:2016;ISO/TS 14907-2:2011;ISO/TS 14907-2:2006', '1921344;1817872;1270855', '49* 43.040* 43.040.15* 31* 35.240* 35.240.60', NULL, NULL, '2021', '84', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183633, '2212013', 'ISO 14707', 'Surface chemical analysis - Glow discharge optical emission spectrometry (GD-OES) - Introduction to use', 'Active', NULL, NULL, NULL, 'ISO 14707:2000', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 14707:2021 provides guidelines that are applicable to bulk and depth profiling GD-OES analyses. The guidelines discussed herein are limited to the analysis of rigid solids, and do not cover the analysis of powders, gases or solutions. Combined with specific standard methods which are available now and, in the future, these guidelines are intended to enable the regulation of instruments and the control of measuring conditions.Although several types of glow discharge optical emission sources have been developed over the years, the Grimm type with a hollow anode accounts for a very large majority of glow discharge optical emission devices currently in use both for dc and rf sources. However, the cathode contact is often located at the back of the sample, in e.g. the Marcus type source, rather than at the front as in the original Grimm design. The guidelines contained herein are equally applicable to both and other source designs and the Grimm type source is used only as an example.', '73', '81.00', '127.00', 'USD', 'ISO 14707:2015;ISO 14707:2000', '1893823;860534', '01.040.19* 71.040* 71.040.40', NULL, NULL, '2021', '20', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183646, '2214790', 'ISO 22581', 'Surface chemical analysis - Near real-time information from the X-ray photoelectron spectroscopy survey scan - Rules for identification of, and correction for, surface contamination by carbon-containing compounds', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'This document is provided to assist in the surface analysis of thin films on materials which are not thought to contain carbon compounds as intended components but for which a C1s peak is observed in the survey spectrum. The films can be those generated on metals and alloys by aerobic or electrochemical oxidation or be those deposited on inert substrates. The procedure described is not suitable for discontinuous deposits of particles on a substrate. With this exception, a simple procedure is provided for identifying the C1s signal from carbon-containing surface contamination. When the C1s peak is identified as arising from an adventitious over-layer the composition derived from the survey spectrum can be corrected for its influence. Recommended procedures are provided in the form of simple Rules structured in the \'If - Then` format with the intention that the information they embody might be utilised by automated procedures in data-systems. The rules provided utilize only information retrieved from the XPS survey scan.', '111', '124.00', '191.00', 'USD', NULL, NULL, '01.040.19* 71.040* 71.040.40', NULL, NULL, '2021', NULL, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183648, '2212066', 'ISO 19734', 'Eye and face protection - Guidance on selection, use and maintenance', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 19734:2021 gives guidance to specifiers and users on the control of eye and face hazards including physical, mechanical, chemical, optical radiation and biological and on the selection, use and maintenance of eye and face protectors.This document applies to&mdash; occupational use,&mdash; tasks that are performed similarly to those in an occupation but not in the workplace, e.g. &quot;do-it-yourself&quot;, and&mdash; schools, educational and research establishments.This document does not apply to eye and face protection for&mdash; ionizing radiation,&mdash; low frequency radio waves,&mdash; microwaves,&mdash; sports or vehicular usage, and&mdash; sunglasses for general (not occupational) use ? see ISO 12312-1.NOTE The ISO 18527 (all parts) sets requirements for eye protectors for some sports.Brief advice on protection when using lasers is included but for detailed advice, see IEC/TR 60825-14.This document is neither a whole nor partial substitute for risk assessment, which is an essential part of any eye and face protection programme.Although this document has been written to help specifiers and users, any recommendations in this document are to be interpreted as guidance only and not intended to replace any national regulatory requirements. Risk assessment is the sole responsibility of the employer and not the PPE manufacturer or its authorised representative.', '200', '223.00', '347.00', 'USD', NULL, NULL, '13* 13.340* 13.340.20', NULL, NULL, '2021', '58', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183652, '2212039', 'ISO 16321-3', 'Eye and face protection for occupational use - Part 3: Additional requirements for mesh protectors', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 16321-3:2021 specifies additional performance and marking requirements for mesh protectors designed to provide protection for the eyes and faces of persons against mechanical hazards such as impacts from flying particles and fragments. The other applicable requirements for mesh protectors and the frames/mountings to which they are intended to be fitted are given in ISO 16321-1.This document also applies to mesh protectors used in educational establishments.This document also applies to those eye and face protectors used for occupational-type tasks that are performed similarly to an occupation, e.g. &quot;do-it-yourself&quot;.This document is not applicable to protectors for use against liquid splash (including molten metal), hot solid risks, infrared and ultraviolet radiation. For protection against these hazards suitable additional or alternative protectors according ISO 16321-1 will be needed.This document does not apply to mesh protectors used in sports such as fencing.', '48', '54.00', '84.00', 'USD', NULL, NULL, '13* 13.340* 13.340.20', NULL, NULL, '2021', '14', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183659, '2212059', 'ISO 18527-1', 'Eye and face protection for sports use - Part 1: Requirements for downhill skiing and snowboarding goggles', 'Active', NULL, NULL, NULL, NULL, NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 18527-1:2021 applies to all goggles with plano lenses, intended for eye protection against hazards including ultraviolet and visible solar radiation, rain, snow and wind, during downhill skiing, snowboarding and other similar activities.This document applies to downhill skiing and snowboarding goggles fitted with an insert to carry prescription lenses.It specifies requirements and testing for materials, performance, marking of goggles and information to be supplied by the manufacturer.Information on the selection and use of downhill skiing and snowboarding goggles is given in Annex A.This document does not apply toa) eye protectors for protection when operating or travelling on a motorized vehicle,b) eye protectors for protection against optical radiation from artificial sources, such as those used in solaria,c) eye protectors for direct observation of the sun, andd) eye protectors intended for sports with unrelated hazards and risks.', '149', '166.00', '259.00', 'USD', NULL, NULL, '13* 13.340* 13.340.20* 03.120.30* 97.220* 97.220.20', NULL, NULL, '2021', '30', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183660, '2212037', 'ISO 16321-1', 'Eye and face protection for occupational use - Part 1: General requirements', 'Active', NULL, NULL, NULL, 'ISO 4852:1978', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 16321-1:2021 specifies general requirements for eye and face protectors. These protectors are intended to provide protection for the eyes and faces of persons against one or more common occupational hazards such as impacts from flying particles and fragments, optical radiation, dusts, splashing liquids, molten metals, heat, flame, hot solids, harmful gases, vapours and aerosols.Additional requirements for eye and face protectors used during welding and related techniques and for mesh protectors are given in ISO 16321-2 and ISO 16321-3, respectively.This document applies to:&mdash; all plano as well as corrective and prescription lensed protectors and components;&mdash; those eye and face protectors used for occupational-type tasks that are performed similarly to an occupation, e.g. &quot;do-it-yourself&quot;;&mdash; those eye and face protectors used in educational establishments.This document does not apply to:&mdash; protectors specifically intended for protection against only solar radiation and used in non- occupational environments for which the ISO 12312 series applies;&mdash; protectors for medically prescribed applications (not occupational), e.g. eye protection for severe dry eye, tints prescribed for medical conditions;&mdash; patient eye protectors during diagnosis or treatment (e.g. ISO/TR 22463);&mdash; protectors for use during medical or e.g. aesthetic applications, e.g. intense light sources (ILS) for which the ISO 12609 series applies;&mdash; protectors specifically intended for sports for which the ISO 18527 series applies;&mdash; laser protectors;&mdash; face protectors intended for live-working to protect against short-circuit electric arcs for which IEC 62819 applies;&mdash; protectors intended to protect against ionizing radiation, e.g. X-rays, for which IEC 61331-3 applies.', '200', '223.00', '368.00', 'USD', 'ISO 4856:1982;ISO 4849:1981;ISO 4851:1979;ISO 4852:1978', '28518;28516;42624;718380', '13* 13.340* 13.340.20', NULL, NULL, '2021', '48', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183676, '2212038', 'ISO 16321-2', 'Eye and face protection for occupational use - Part 2: Additional requirements for protectors used during welding and related techniques', 'Active', NULL, NULL, NULL, 'ISO 4850:1979', NULL, 'ISO - International Organization for Standardization', 'English', 'ISO 16321-2:2021 specifies additional material, design, performance and marking requirements for eye and face protectors designed to provide protection for the eyes and faces of persons against occupational hazards, such as optical radiation, impacts from flying particles and fragments, and hot solids during welding and related techniques. The other applicable requirements for welding protectors are given in ISO 16321-1.This document also applies to welding protectors used in educational establishments.This document also applies to those eye and face protectors used for occupational-type tasks that are performed similarly to an occupation, e.g. &quot;do-it-yourself&quot;.', '111', '124.00', '191.00', 'USD', 'ISO 4850:1979', '28517', '13* 13.340* 13.340.20', NULL, NULL, '2021', '22', NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, 0, 0),
(183791, '2243246', 'ISO 21920-1', 'Geometrical product specifications (GPS) - Surface texture: Profile - Part 1: Indication of surface texture', 'Active', NULL, NULL, NULL, 'ISO 1302:1992', NULL, 'ISO - International Organization for Standardization', 'English', 'This document specifies the rules for indication of surface texture by profile methods in technical product documentation by means of graphical symbols.INSERT INTO `wp_tecbook_standards` (`id`, `idProduct`, `referenceNumber`, `standardTitle`, `status`, `referencedStandards`, `referencingStandards`, `equivalentStandards`, `replace`, `replacedBy`, `standardby`, `languages`, `fullDescription`, `ebookPrice`, `printPrice`, `bothPrice`, `currency`, `historicalEditions`, `documentHistoryProductId`, `icsCode`, `keyword`, `identicalStandards`, `publishedDate`, `pages`, `byTechnology`, `byIndustry`, `previewPath`, `coverPath`, `fullPath`, `deleted`, `newArrival`, `bestSellers`, `isFree`, `specialOffer`, `featured`) VALUES
(419809, '1822928', 'ABMA 19.1:2011 (R2018)', 'Tapered Roller Bearings - Radial - Metric Design', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', 'This standard for inch thrust needle roller and cage assemblies and thrust washers covers:\n\nIdentification Code\nSymbols and Nomenclature\nBoundary Dimensions\nTolerances\nMounting Practice\n\nAll thrust needle roller and cage assemblies and thrust washers listed in this standard are not necessarily\navailable. For availability, consult bearing manufacturers. Other applicable standards should be consulted for\ntolerance definitions, gaging practices and methods of evaluating load ratings.\n\nThis standard only covers external dimensions. Functional interchangeability between different makes of\nstandard thrust needle roller and cage assemblies and thrust washers of the same size may depend on bearing\nfeatures which are not standardized. Hence, the substitution of one make of a standard bearing for another should\nonly be made after careful comparison of their characteristics and consideration of the requirements of the particular\napplication.', '72.000000', '72.000000', '0.000000', 'USD', 'ABMA 19.1:1987 (R2008)', '11860', '', '', '', '2024-11-20', '19', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(419810, '1822927', 'ABMA 20:2011 (R2020)', 'Radial Bearings of Ball, Cylindrical Roller and Spherical Roller Types - Metric Design', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', 'This standard includes:\n\n(a) basic plan for the boundary dimensions of metric radial ball and roller bearings;\n(b) general rules for extension of the basic plans;\n(c) dimensions and tolerances for snap ring groove and locating snap rings;\n(d) dimensions for radial ball bearings with flanged outer ring; and\n(e) tolerances for boundary dimensions, chamfers, various runouts and internal clearance.\n\nThis standard does not contain any direction pertaining to internal bearing design nor any indication as to availability of bearings.\nAirframe bearings, instrument ball bearings, needle roller bearings, tapered roller bearings, thrust bearings and other bearing types and series not conforming to these basic plans for boundary dimensions are covered in other\nANSI/ABMA Standards.', '88.000000', '88.000000', '0.000000', 'USD', 'ABMA 20-1996 (R2008)', '11862', '', '', '', '2024-11-20', '75', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(419811, '665037', 'ABMA 8.2:1999 (S2020)', 'Ball and Roller Bearing Mounting Accessories - Inch Design', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', '', '55.000000', '55.000000', '0.000000', 'USD', 'ABMA 8.2:1991(S2010)', '5108', '', '', '', '1999-11-20', '59', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(419812, '5108', 'ABMA 8.2:1991(S2010)', 'Ball and Roller Bearing Mounting Accessories - Inch Design', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', 'Establishes dimensions and minimum physical properties of these components consistent and compatible with AFBMA and ANSI standards relating to ball and roller bearings.', '0.000000', '0.000000', '0.000000', 'USD', 'ABMA 8.2:1999 (S2020)', '665037', '', '', '', '1999-11-20', '49', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(419813, '11862', 'ABMA 20-1996 (R2008)', 'Radial Bearings of Ball, Cylindrical Roller and Spherical Roller Types - Metric Design', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', 'Includes: basic plan for the boundary dimensions of metric radial ball and roller bearings; general rules for extension of the basic plans; dimensions and tolerances for snap ring groove and locating snap rings, etc.', '0.000000', '0.000000', '0.000000', 'USD', 'ABMA 20:2011 (R2020)', '1822927', '', '', '', '1996-11-20', '72', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(419814, '5106', 'ABMA 7:1995 (S2013)', 'Shaft and Housing Fits for Metric Radial Ball and Roller Bearings (Except Tapered Roller Bearings) Conforming to Basic Boundary Plan', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', 'Covers the general selection of shaft and housing fits for metric radial ball and roller bearings of tolerance classes ABEC 1 - RBEC 1 as influenced by the type and extent of bearing loading and other design requirements.', '55.000000', '55.000000', '0.000000', 'USD', '', '', '', '', '', '1995-11-20', '16', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(419815, '5111', 'ABMA 14:1995 (S2020)', 'Housings for Bearings with Spherical Outside Surfaces', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', 'Specifies boundary dimensions and tolerances for ball bearings with spherical outside surfaces and extended inner ring width. Included are pillow block, flanged and take-up unit housings.', '55.000000', '55.000000', '0.000000', 'USD', '', '', '', '', '', '1995-11-20', '18', '', '', '', '', '', 0, 0, 0, 0, 0, 0),
(419834, '11860', 'ABMA 19.1:1987 (R2008)', 'Tapered Roller Bearings - Radial - Metric Design', 'Active', '', '', '', '', '', 'ABMA - American Bearing Manufacturers Association', 'English', '', '0.000000', '0.000000', '0.000000', 'USD', 'ABMA 19.1:2011 (R2018)', '', '', '', '', '1987-11-20', '55', '', '', '', '', '', 0, 0, 0, 0, 0, 0);
